// Quote console — lazy so its ~345 KB (the @davisdelivery/quote-generator code plus its
// geo/model JSON) loads only when the Quote tab is first opened, instead of riding in the
// cold Map bundle where it's never used. Rendered behind a <Suspense> in QuoteScreen.
const UlineQuoteConsole = React.lazy(() =>
  import('@davisdelivery/quote-generator').then((m) => ({ default: m.UlineQuoteConsole })));

// Vite's tree-shaker considers function-only imports from .ts files to be
// pure; it eliminates them even though they're called from useAutoScanner's
// useEffect (which only fires after notesReady + stops load). Exposing the
// entry points on window keeps the import chain observed so the bundle
// retains the scanner + writer. Doubles as a QA hook —
// window.__DD_SCANNER__.scanStop(...) lets QA test patterns in DevTools.
if (typeof window !== 'undefined') {
  window.__DD_SCANNER__ = { scanStop, scanStopFull, applyScannerResults };
}

// ---------- constants ----------

const APP_VERSION = '0.54.52';

// No auth — see firebase.js. customer_notes writes are stamped with this
// hardcoded identity until we wire up a real per-user signal (out of scope
// for v0.3.0; Glory Bound Dispatch / MarginIQ don't track this either).
const NOTES_UPDATED_BY = 'dispatcher';
// eslint-disable-next-line no-undef
const BUILD_COMMIT = typeof __BUILD_COMMIT__ !== 'undefined' ? __BUILD_COMMIT__ : 'dev';
// eslint-disable-next-line no-undef
const BUILD_TIME = typeof __BUILD_TIME__ !== 'undefined' ? __BUILD_TIME__ : '';
// eslint-disable-next-line no-undef
const BUILD_CONTEXT = typeof __BUILD_CONTEXT__ !== 'undefined' ? __BUILD_CONTEXT__ : 'dev';
// Short commit for the build badge: the real 7-char hash on a Netlify build, or
// 'local' in dev (the vite fallback is 'dev'). Never blank / 'undefined'.
const BUILD_SHORT = BUILD_COMMIT && BUILD_COMMIT !== 'dev' ? BUILD_COMMIT.slice(0, 7) : 'local';

// Mirror of the backend isHashLikeId (nuvizz-list.mts) — keeps a bare NuVizz ObjectId / internal
// load-id from ever rendering as a human load/route NAME. A recurring load's real name is its
// loadNbr ("BEN 2"); loadId is a 24-hex id. Defense-in-depth with the backend guard (#254-style).
function isHashLikeId(v) {
  const s = String(v ?? '').trim();
  if (!s || /\s/.test(s)) return false;            // human names have spaces or are short words
  if (/^[0-9a-f]{24}$/i.test(s)) return true;      // Mongo ObjectId
  if (/^[0-9a-f]{16,}$/i.test(s)) return true;     // long hex token
  return /^[A-Za-z0-9_-]{20,}$/.test(s) && /\d/.test(s); // long id-ish token with a digit
}
// First non-hash human label among the candidates; '' if none — NEVER a raw id. Callers that always
// represent a real load (the Compare card title / send buttons) add their own 'Unnamed load' fallback;
// cell renderers leave it blank when a stop simply has no load.
function loadDisplayName(...vals) {
  for (const v of vals) { const s = String(v ?? '').trim(); if (s && !isHashLikeId(s)) return s; }
  return '';
}
// A NuVizz load NUMBER ("DAVIS000198197") — company code + zero-padded digits, or a long bare
// number. Distinguishes the real number load/info needs from the human route name ("SUW") that
// stops carry in loadNbr. Mirrors looksLikeLoadNbr in netlify/functions/lib/nuvizz-loads.mts.
function looksLikeLoadNbr(v) {
  const s = String(v ?? '').trim();
  return /^[A-Za-z]{2,}\d{5,}$/.test(s) || /^\d{6,}$/.test(s);
}

// Beta version history — shown when the dispatcher taps the build badge, so it's
// easy to keep up with what changed. Newest first; APP_VERSION (top) is highlighted.
// Keep this curated + short (one line each); append a row on each release.
const VERSION_LOG = [
  ['0.54.52', 'THE CS EMAIL NOW FIRES WHEN THE SCAN SEES THE ORDER, NOT WHEN THE BOARD GETS BUILT. Chad: "DSV came in on Friday. The moment the scan picked it up on Friday, it should have sent the email. Why is it sending the email today? It\'s too late." Here is exactly why it was late. The email was riding on the days the scan WRITES — today, plus the next one or two business days, and those future days only get added from 10 AM ET (before 10 the scan builds today only, because looking at a future day costs vendor calls). So the trigger was never "we saw this order"; it was "this order\'s DELIVERY DATE finally came inside the write window." An order for Tuesday sat in every scan from the moment it appeared and was reported by none of them, then went out on Monday\'s first tick after 10 AM. That is the 10:16 email. THE ROWS WERE IN OUR HANDS THE WHOLE TIME. Each scan pulls a SEVEN-DAY-EITHER-SIDE window from NuVizz in one shot and files every day in it — we read two or three of those days and threw the rest away. The fix costs ZERO extra NuVizz calls: the scan now checks the whole pull for flagged customers, every scan, at any hour, and emails the moment one turns up on any day in that window. It runs FIRST, before the address lookups and the board writes, so it does not wait on the slowest part of the scan for something it already knew a minute earlier. SENDING EARLIER MUST NOT MEAN SENDING TWICE. The same order is now seen twice — once as the raw scan row, later with the full address after we pull its detail — and if those two addresses normalize even slightly differently ("Ste 200" appearing, an ATTN line moving) the old per-customer ledger would treat the second sighting as new and send CS a duplicate. The ledger now records the ORDER NUMBERS too — all of them behind that customer, so a customer with two orders that day can\'t sneak a second email out under the drifted key either. Already-delivered and cancelled orders are also filtered out of the sweep: "scheduled for delivery" about something that already delivered is worse than silence. WHAT THIS DOES NOT FIX, PLAINLY: the weekend. Scheduled scans stop Fri 11 PM ET and do not resume until Sun 7 PM. Friday\'s Uline manifest was generated at 11:30 PM — half an hour after the last Friday scan — so if the order reached NuVizz around then, no scan existed to see it until Sunday evening. Nothing about the email logic changes that; it needs a decision from you about running notify-only scans through the weekend (2 vendor calls a fire), which I have NOT done on my own. The 10 AM rule and the two-to-three-day horizon also still govern WRITING and enrichment — untouched, because that is where the vendor cost is. This is email only.'],
  ['0.54.51', 'THE MORE BUTTON EXISTS ON THE PHONE NOW TOO. Chad: "There is no more button on mobile." Correct — v0.54.50 put Manifest check INTO the phone menu but left it as one more line in a flat list, and the container itself was still desktop-only. That misses the point of what he asked for: the More dropdown was never about hiding one tab, it was somewhere for extra screens to live as they get added, and a phone menu that just grows forever is the thing it was meant to prevent. There is now a real More button inside the phone menu, with the overflow tabs grouped under it. IT STARTS OPEN, AND THAT IS DELIBERATE. On desktop More is a closed dropdown because the nav row has no space. On a phone the whole navigation is ALREADY a menu, so nesting a shut dropdown inside it would put a tab two taps deep — the container would have made the app worse to use in order to look tidier. So it opens and closes like a real button, it remembers which way you left it, and it starts open: nothing that works today becomes harder to reach, and the list has a lid for when it grows. AND FOLDING IT AWAY CANNOT HIDE A PROBLEM. When More is collapsed, whatever flag is sitting underneath moves UP onto the More row itself — collapse it with two unaccounted manifest orders and the row reads "More 2". The version chip keeps its red dot regardless, so a problem is still visible before you open anything at all. THE TEST NOW CHECKS THE CONTAINER, not just the tab: that the button is there, that it starts open, that it actually collapses, and that a collapsed More still carries the count. Phone and desktop, with and without something to report. That is the same gap as last time — I verified the tab and not the thing around it — so it is pinned now.'],
  ['0.54.50', 'THE MANIFEST CHECK WAS UNREACHABLE ON YOUR PHONE. Chad sent a screenshot of the menu on his phone asking "did you merge?" — and the answer was yes, he was running the right build, but the tab simply was not there. This one is entirely on me. This app has TWO navigations: a row of tabs on desktop, and on a phone the whole thing collapses to a single chip menu behind the version number. I built the new More dropdown into the desktop row, tested it at desktop size, and never opened the phone menu. So Manifest check shipped visible on a laptop and invisible on a phone — and dispatch runs on a phone. WORSE, IT FAILED SILENTLY. The phone menu maps each entry to a screen and quietly falls back to the MAP for anything it does not recognise, so even if you had found a way to ask for the tab you would have landed on the map with no error, which is the kind of thing you would reasonably read as "the feature never shipped." Manifest check is now in the phone menu, the fallback is written so a screen has to be named on purpose, and a comment there says why. THE FLAG WORKS ON A PHONE TOO, but it had to be a different shape. On desktop the red count sits on the More button. On a phone the entire nav is one chip, so there is nowhere to hang a number where you would see it — the chip now carries a small red DOT when something behind the menu needs you, and the count itself is on the Manifest check row when you open it. Same rule as always: it only counts orders to chase, and it survives a reload. AND THE TEST NOW RUNS AT PHONE SIZE. The browser check I wrote for this tab ran at 1440 pixels wide, which is exactly why it passed while the feature was broken for you. It runs both sizes now — phone and desktop, with and without a problem to report — so a screen that is reachable on a laptop and not on a phone fails the build instead of reaching you. Also confirming what merged: v0.54.48 (the manifest tab, the More menu, the POD photo fix) and v0.54.49 (notes refreshing on every scan) are both in.'],
  ['0.54.49', 'NOTES NOW REFRESH ON EVERY SCAN, AND A CARD YOU OPEN REPAIRS ITS OWN NOTES FOR GOOD. Chad: "Notes should be updated with every scan planned unplanned and completed deliveries." Here is what was actually happening, because it is worse than "a bit behind": an order\'s notes were captured ONCE — the single detail lookup this app does the first time a PRO ever appears on the board — and then never touched again. Not by the next scan, not by any scan. And because that captured record is filed per PRO and reused across days, a repeat customer like ULINE could be showing you notes captured weeks before the instruction you actually needed was written. TWO CHANGES, BOTH FREE. FIRST, the note text now refreshes on every scan. The saved searches you already run — planned, unplanned and completed — have been carrying each order\'s instruction text the whole time, at no extra cost; the app was simply throwing it away, because a field not on the "keep this current" list gets overwritten by the older stored copy on every pass. It is on that list now. Zero extra NuVizz calls, all three searches, every scan. SECOND, opening a stop now FIXES it permanently. Tapping a card, hitting Refresh from NuVizz, or opening the Activity Timeline already pays for a full detail read, and that read comes back with the order\'s current notes — the app was folding them into the card on your screen and then discarding them the moment you closed it. They are now written back, so the next person to open that order sees the good notes without re-fetching anything. Same call, no new cost, and the repair sticks. THE HONEST LIMIT, and it is why there is a new amber banner: what the scans can refresh for free is the note TEXT. The full notes the card renders — with who wrote it, what type it is, and when — exist only in the detail read. So when a scan is carrying instructions the stored notes do not have, the card now says "NuVizz has newer instructions than these" and shows you the new text right there, rather than presenting weeks-old notes as if they were current. Refresh pulls the full version with its author and time. That banner is deliberately hard to trigger: it only fires when the scan has something we do not, never the reverse (the list squashes every comment into one line, so it usually carries LESS — flagging that would mark nearly every stop and you would learn to ignore it within a day), and one stray word is treated as noise rather than a new instruction. IF YOU WANT THE FULL NOTES ON EVERY SCAN TOO, that is one change on your side rather than mine: the saved searches would need the comment author, type and timestamp added as columns. Say the word and I will wire it. 1,334 tests, and the banner was verified rendering in a real browser.'],
  ['0.54.48', 'THE MANIFEST CHECK HAS A SCREEN NOW, AND A FLAG THAT FINDS YOU. Chad: "i want to run the manifest against what is scanned into firestore and want there to be a flag when there is an issue as well as i want to add a more dropdown to start storing things like this tab we are about to build." All three. A MORE MENU ON THE NAV. The tab row was full, and screens like this one are places you visit deliberately rather than live in — so rather than shrink every tab to squeeze them in, there is now a More dropdown at the right of the row and overflow tabs go there. Manifest check is the first one in it; the menu is built to take more. THE TAB. Drop the nightly Uline freight report on it and every order printed on that report is checked against what the scan actually put in Firestore. You get the headline first — either "all 660 manifest orders found in the scan" or the number that are not — then the manifest\'s own totals, then a table of exactly which orders are unaccounted for, with PRO, customer, city, ZIP, weight, skids and loose, so you can go chase them without hunting for the numbers. IT COSTS NOTHING. Not "a little" — nothing. The report is a text-layer PDF so reading it needs no AI pass, and the comparison reads Firestore. The endpoint underneath is capable of going on to ask NuVizz about each unaccounted order, but that is deliberately NOT wired to any button on this screen: nothing you can click here spends a NuVizz call, so it can never surprise you with one. THE FLAG, AND WHY IT SITS ON THE NAV. A problem found on a screen you are not looking at is the same as no problem, so the count of unaccounted orders shows as a red badge on the More menu itself — and it is stored, so it is still there tomorrow morning after a reload. It counts ORDERS TO CHASE, not categories of complaint: three missing orders reads 3, never "3 kinds of thing went wrong." Two things it deliberately does NOT flag: orders in the scan that are not on the manifest (the board carries every shipper, not just Uline — flagging those would bury the one order that matters under hundreds that are fine), and a manifest whose own totals do not reconcile, which warns in amber and marks the freight numbers unconfirmed rather than raising an order alert, because that is a reading problem and not a missing order. HONEST LIMIT, worth saying plainly: this tells you an order is not in the scan for the days it checked. That is not the same as proving NuVizz never got it — the order could be dated to another day. The table says so, and the PRO is right there to search. Verified in a real browser, not just unit tests: the menu opens, dropping a PDF runs the check exactly once, it never once asks for the NuVizz probe, the missing orders render with their customers, the badge appears on the nav without leaving the tab, and it is still there after a reload. Both the found-something and found-nothing paths were run. 1,325 tests.'],
  ['0.54.47', 'AN ORDER ON ULINE\'S NIGHTLY MANIFEST THAT NEVER REACHED NUVIZZ CAN NOW BE FOUND. Chad, with the 8/06 freight report in hand: "an order is on the nightly manifest that is not in nuvizz need to build a way to detect this." WHY NOTHING CAUGHT THIS BEFORE, and it is worth stating plainly: every integrity check this app has starts FROM NuVizz. The scan reads NuVizz. The board reconcile reads NuVizz. The capture seal checks what we captured out of NuVizz. So an order Uline physically handed us that NuVizz never received is invisible to all of them — there is no record to notice the absence of. Uline\'s own manifest is the only independent statement of what we were actually given, which is exactly why it can catch what nothing else can. WHAT WAS BUILT. The nightly PDF is now readable end to end: 660 orders off the 8/06 report, each with its PRO, customer, city, zip, weight, skids and loose pieces. It costs NOTHING to read — this report carries real text, unlike the faxed Estes manifests that need an AI vision pass, so there is no AI call and no NuVizz call in reading it. THE PART THAT TOOK THREE TRIES, because it would have quietly handed you wrong freight counts: the numbers on that report are RIGHT-ALIGNED, so a value\'s position never lines up with its column heading, and an order with no skids simply has no SKID column at all. Reading the numbers in the order they appear — the obvious approach, and my first two attempts — swapped SKIDS and LOOSE on 45 of the 660 orders. The reader now works off real column positions, and then PROVES its reading by reproducing the manifest\'s own FINAL TOTALS line, all four numbers: 660 orders, 359,769 lbs, 1,019 skids, 310 pieces. If a future manifest cannot be reconciled against its own totals it FAILS LOUDLY instead of handing you numbers it could not verify. THE CHECK ITSELF RUNS IN TWO STEPS, and the split is about cost. Step one is FREE: it compares every manifest PRO against the board, zero NuVizz calls, and produces SUSPECTS — orders on the manifest that are not on the board. Step two is the only part that costs anything: one NuVizz call per suspect, capped, and you have to ask for it explicitly. AND THE DISTINCTION THE WHOLE THING RESTS ON: "not on our board" and "not in NuVizz" are different claims. An order can be off the board because it is dated to another day, or cancelled, or on a day we did not scan. Only NuVizz answering "that order does not exist" proves it never arrived. Everything else — scans switched off, auth rejected, throttling, the daily call ceiling tripping — is UNVERIFIED, never absence, because every one of those fails for all 660 orders at once and a lazier design would cheerfully report your entire manifest as missing on a bad night. There is a test that fires all five of those failure modes at 660 orders and demands ZERO false accusations. One more real trap closed: the board stores some orders as 007157687-1 while Uline prints the bare 007157687, so matching had to handle the segment suffix — without that, every one of those orders would have read as missing and the report would have been nothing but false alarms. 26 new tests. NEXT: a drop zone so you can drag the nightly PDF in rather than calling the endpoint, and a nightly run that emails you only when something is actually missing.'],
  ['0.54.46', 'THE DELIVERY-PHOTO BUTTON IS ACTUALLY THERE THIS TIME — I DROVE THE REAL APP IN A BROWSER AND WATCHED IT WORK BEFORE WRITING THIS. Chad: "still no button and this delivery definitely has photos." He was right, and v0.54.45 deserved the complaint: I swapped one bad condition for another. THE FIRST VERSION hid the button unless the order had NO documents at all, so a BOL killed it. THE SECOND VERSION hid it unless the order was DELIVERED — and this order\'s card reads SCHEDULED. It can, and here is why, because it matters beyond this button: the status the card trusts comes from the cheap saved-search scan, and the delivery timestamp is NOT one of the fields that scan keeps current. NuVizz\'s own saved-search index is documented in this app as lagging real status by 30+ minutes and sometimes hours. So an order genuinely delivered can sit on our board marked Scheduled — and my gate made the button disappear at exactly the moment the board was stale, which is precisely when a dispatcher needs to go ask. SO THERE IS NO STATUS GATE ANY MORE. The button asks NuVizz a question. Asking is one call on your tap and is always a reasonable thing to want. The only condition left is the honest one: you don\'t already have photos. Worst case the answer is "no delivery photos on file" — a real answer, and strictly better than hiding the ability to ask. A SECOND BUG FOUND WHILE VERIFYING THIS ONE, and it would have bitten within a day: the card folded a refresh in by simply overwriting every field the pull returned — and a pull that found no documents returns an EMPTY document list. So tapping the button on an order NuVizz has nothing for would have DELETED the BOL you were already looking at. You ask for more and get less. The server has had a guard against exactly this for months (an empty value is never allowed to overwrite a good one); it was never mirrored on the browser side. It is now. WHY YOUR BOL SAYS 6:01 PM AND WHY IT ISN\'T A DELIVERY TIME: NuVizz\'s own guide says a BOL is generated one to three days BEFORE delivery, so that stamp is when the document was made. Printed bare under a heading that says "Proof of delivery", it read as an arrival time. It now says "created 6:01 PM". AND THE LIKELY REASON THE PHOTOS WERE MISSING FROM THE CARD IN THE FIRST PLACE: the cheap scan never carries document data at all. The BOL on your screen came from the single detail lookup this app does when a PRO FIRST APPEARS on the board — days before the driver ever went there — and that snapshot is then carried forward untouched forever. So the card was showing you a document list frozen from before the delivery happened. The button is what unfreezes it. HOW THIS WAS CHECKED, since twice was enough: there is now a script that serves the real built app in a real browser, feeds it this exact order (PRO 007157687-1, route VINCENT, one BOL, status Scheduled), clicks it open and fails unless the button is on screen — then clicks the button and checks both outcomes, photos coming back and nothing coming back. I also deliberately re-broke each fix and confirmed the script caught it, so it is a real test and not a green light that means nothing. 1,286 tests plus that browser check, zero NuVizz calls.'],
  ['0.54.45', 'THE ROUTE NAME STOPPED PRINTING ITSELF TWICE, AND THE DELIVERY PHOTOS ARE REACHABLE AGAIN. Chad, on a delivered VINCENT order: "why is the route name listed twice here get rid of the second one. also where is my view photos of delivery under the pod section." Two separate defects on one card. THE DOUBLE NAME: the Route box prints the route NAME in bold and the load NUMBER in small grey underneath, which is right when they are different things — route "SUW 4" on load "047-54019" tells you two useful facts. But NuVizz frequently names a route after its own load, and on this order both were the word VINCENT, so the card stacked the same word on top of itself and read as a rendering bug. The grey line now appears ONLY when the load number is genuinely something other than the route name, compared ignoring case and spacing. A load number that differs is a real identifier and still shows — this hides a duplicate, it does not throw away information. THE MISSING PHOTOS, which is the worse of the two: the driver\'s capture photos are not included in the cheap scan — NuVizz only hands them over when we re-pull the order — so the card carries a "View delivery photos" button that fetches them on demand. That button was written inside a branch that only ran when the stop had NO documents whatsoever. So the instant an order picked up any document at all — and a delivered order almost always has a signed BOL, a PDF — the button disappeared, and there was no way left to ask for the photos. It failed precisely on the delivered orders most likely to have photos, which is why the section showed a lone BOL line and nothing else. The rule is now about PHOTOS, not documents: if a delivered order has no image on file yet, the button is there, however many PDFs sit above it. The BOL keeps its own line rather than being swallowed by the photo grid, and the card only says "no delivery photos on file" AFTER a pull actually came back empty — before that, silence means nobody has asked yet, which is a different thing and shouldn\'t be reported as an answer. COST: the button is one NuVizz call, on your explicit tap, exactly as before — the same single call the Refresh from NuVizz button makes. Nothing here scans. Eleven new tests pin both rules, including a replay of this screenshot.'],
  ['0.54.44', 'THE PER-DRIVER SKID CAP NOW USES A DRIVER\'S TYPICAL FULL LOAD, NOT THEIR ONE BIGGEST DAY EVER — v0.54.43 WOULD BARELY HAVE MOVED. Correcting my own release from an hour ago, because a review of it found the number I chose was the wrong one and I would rather say so than let it ship quietly doing nothing. v0.54.43 capped each driver at the MOST they had ever carried on a single trip. That sounds right — never split a load someone has proven they can carry — but here is the arithmetic that kills it: a driver has to work 10 observed days before the engine uses their own history at all, which is 12 to 25 trips, and the MAXIMUM of a sample that size is that driver\'s own 95th-to-100th percentile, not their normal. So one 21-skid day in ten weeks would have put a genuine 14-skid driver right back at the class cap of 22 — meaning the release would have changed nothing for exactly the drivers Chad was pointing at. THE BOUND IS NOW THE 85TH PERCENTILE of that driver\'s own per-trip skids — "a full truck for this driver" — which is what "most are 12-15, some take 17-18" actually describes. A driver who normally tops out at 14 gets 14 even if they once squeezed on 21. AND A DIAL IF I HAVE JUDGED IT WRONG: a new Engine setting, skid cap driver headroom, slides the bound from typical (0, the default) to their all-time max (1) with no code change — so if these caps come out too tight against real drivers, that is one number to nudge, not a rebuild. THE HONEST TRADE: a tighter cap means the engine will sometimes split a day dispatch really did run whole, which shows up as more proposed trips and can cost agreement points. I think buildable routes beat a better score against routes drivers can\'t run, but the Skid cap column on the Engine page is there precisely so Chad can check the numbers against what he knows about his own people and tell me if I have it wrong. WORTH KNOWING, and it corroborates Chad: the Build screen\'s truck profiles have capped a box truck at 14 skids this whole time. The live route builder has agreed with him all along; only the shadow engine ever said 22. Also hardened here: the class clamp explicitly reads the driver\'s roster class rather than the class on their learned envelope, because a brand-new driver\'s envelope is a whole-FLEET one with box and tractor days mixed together, and without that clamp a box driver could inherit a tractor\'s numbers. Three new tests, 1,272 total, zero NuVizz calls.'],
  ['0.54.43', 'THE ENGINE STOPPED LOADING EVERY BOX TRUCK LIKE THE STRONGEST ONE. Chad: "Most box truck drivers can\'t put 22 skids on a box truck. You should id the ones who can take 17-18 but most are 12-15." He is right, and the engine\'s own freight study already said so — it measured 912 real dispatch trips and found the MEDIAN box trip is 14 skids. The cap of 22 was the 95th percentile of that same study, meaning the engine was allowed to load EVERY box driver the way the single heaviest box driver loads. That is why routes kept coming back with 20-odd stops on people who have never run them. WHAT CHANGES: each driver is now capped by the most THEY have actually carried on one trip, learned from their own history rather than the fleet\'s. A driver whose real trips top out at 15 gets 15. A driver who has genuinely run 18 gets 18. The data was already being collected per trip — skids and loose pieces per load, every day — it just had never been turned into a per-driver number. THIS IS THE 2.1.1 LESSON APPLIED CORRECTLY, not repeated: that old failure used a PERCENTILE of a driver\'s history, which by definition cuts below their own heaviest real trips and split loads they had already proven would fit. Using their observed MAXIMUM cannot do that — it is the proof itself. AND THE SAFETY RAIL THAT MATTERS: a per-driver cap is clamped at the old class cap, so it is always the same or LOWER than what the flat 22 allowed. This change can only ever split less than before, never more — one bad data point cannot invent a 38-skid box truck. A driver whose observed days were all small is floored at 10 so nobody gets a 4-skid truck, a driver with no skid history yet keeps the class number exactly as today, and setting the floor to 22 in Engine settings turns the whole thing off. YOU CAN NOW SEE WHO IS WHO: the Engine page\'s driver table has a new SKID CAP column, sortable — sort by it and the 17-18 drivers separate from the 12-15 drivers at a glance. A bold number is learned from that driver\'s own trips; a grey one means no skid history yet, so they are still on the class default. Eleven new tests pin all of it, including that an 18-skid bag rides one trip for an 18-skid driver and splits for a 15-skid driver. Zero NuVizz calls. Re-score history to see it applied to past days.'],
  ['0.54.42', 'A BOX TRUCK CAN NO LONGER BE SENT OUT OVER 10,000 POUNDS — AND THE ENGINE CHART THAT "ISN\'T CHANGING" WAS STUCK FOR A REASON I CAN SHOW YOU. Chad, on the engine page: "This isn\'t improving or changing. Also can\'t put more than 10k pounds on a box truck per trip." Two separate things, both real. THE WEIGHT CAP: the planning engine enforced a per-trip SKID cap (box 22, tractor 37) and no weight limit at all, so it was free to propose a box truck loaded to 15,800 lb — which is what Steven Adjetey\'s two proposed trips added up to. It now also enforces a per-trip PAYLOAD cap: 10,000 lb on a box, 44,000 on a tractor. Those are not numbers I picked; they are the SAME ratings this app already enforces on the Build screen\'s truck profiles, so the two halves of the app finally agree on what a truck may legally haul. I WANT TO BE STRAIGHT ABOUT THE HISTORY HERE, because the engine used to have a weight limit and it was deliberately deleted in July for causing "phantom splits." That old limit was a LEARNED number — each driver\'s own 85th-percentile trip weight — and a percentile by definition sits below that driver\'s heaviest real trips, so it kept splitting loads they had already proven would fit. A truck\'s payload rating is not a percentile of anything and cannot chop a tail that way: a trip over 10,000 lb was never legal to build, so splitting it corrects an overload instead of inventing one. WHAT TO EXPECT: mostly quiet. Real freight runs about 300 lb per skid position, so a box packed to its 22-skid cap weighs about 6,600 lb and the skid cap still binds first — this only bites on dense freight, which is exactly when it should. A single order heavier than the whole rating still ships (alone) rather than being stranded, an order NuVizz never gave a weight for is never split on a guess, and either cap can be set to 0 in Engine settings to switch it off if the weight feed ever goes bad. The engine also no longer PENALIZES the reload a payload forces — without that it would have paid to shove a legitimately-loaded driver\'s freight onto a lighter truck to dodge a split it can\'t avoid, which is the precise mistake that cost 3 points of agreement in July. Nine new tests pin all of it. NOW THE CHART. It was not changing because the re-score could never finish: one pass fits about a week of days into its 12-minute budget, notes where it stopped — and then threw that note away, because a background job answers instantly with an empty receipt the browser cannot read. So every tap of "Re-score history" started over at the OLDEST day and re-did the same first week forever; the rest of the summer was never reached, and the trend you were staring at was frozen at whatever engine version happened to be live the night each day was first scored. The stopping point is now SAVED on the server, so each tap genuinely continues where the last left off until the window is done. AND THE CHART COULD NOT HAVE SHOWN PROGRESS EVEN IF IT HAD: it drew a fixed 0-100% scale into 56 pixels, so the whole realistic range (agreement runs 20-30%) lived in the bottom quarter and a genuine 2-point gain moved the line about ONE PIXEL. The scale now fits the data, with zero still at the bottom. One honest caveat: because a re-score OVERWRITES each day in place, even a finished pass leaves every day showing one engine version — the per-version cards below the chart are the real "is it getting better" instrument, and that is a deeper fix than this release. Zero NuVizz calls in any of this.'],
  ['0.54.41', 'THE ESTES TWIN WAS STEALING THE CARD BEFORE THE DATE CHANGE EVEN RAN — THE LAST DOOR IS NOW SHUT. Chad, the morning after v0.54.36: "Changed the date on Estes again and it changed all the addresses so your fix did not work." He was right that it happened and here is the honest accounting of why: the v0.54.36 guards DID hold, but they guarded the date write and its repaint — and the card has three OTHER buttons that pull the order by number and fold the answer straight in: Refresh from NuVizz, opening the Activity timeline, and the delivery-photo check. None of them checked WHICH record NuVizz answered with. So one tap on Refresh (or one timeline open) on an order with a duplicate number quietly replaced the whole card with the twin — every address line at once, which is exactly "it changed all the addresses" — and, worse, the card ADOPTED THE TWIN\'S INTERNAL ID. From that moment the date-change guard was comparing the twin to itself and passing honestly. The theft happened before the write began; the guard never saw it. THE FIX GOES WHERE ALL OF THOSE PATHS MEET: every fold-into-the-card now flows through one checkpoint that compares the incoming record\'s id to the id the card is showing. A mismatch is REFUSED — the card keeps its identity, the red "2 orders share this number" warning lights up, and the Refresh button says plainly that NuVizz answered with the other order instead of pretending nothing happened. The Refresh button, the timeline, the photo check, and both of the already-guarded repaints all pass through it — and so does anything added later, which is the point: v0.54.36 guarded call sites one by one and missed three; this guards the door they all walk through. STILL TRUE AND STILL THE REAL REMEDY: the duplicate Estes entry must be cancelled or renumbered in the NuVizz portal. While it exists, NuVizz\'s own by-number answers keep flipping a coin — this app now refuses to act on the wrong side of that coin anywhere, but only the portal cleanup makes the coin go away. Zero NuVizz calls in this change; six new tests pin the checkpoint and the wiring.'],
  ['0.54.40', 'THE STOP NUMBER SHOWS IN FULL. Chad, on the bottom Stops grid reading "ESTES-2958…" and "ESTES-0158…": "i want the whole number to show." The Stop # column had a fixed 96-pixel ceiling, sized back when a stop number was a bare nine digits like 007157031 — a carrier-prefixed one (ESTES-0828068215) runs half again as long and got cut mid-number. That is worse than it looks: a stop number is an IDENTIFIER, and half of one is not a shorter version of it, it is unusable — you cannot search it, quote it to a carrier, or tell two Estes orders apart by it, which is exactly the kind of confusion that cost us the duplicate-number hunt in v0.54.36. The column now sizes to the longest number actually on screen, in both the Stops and Loads grids, and the grid scrolls sideways as it always has. EVERY OTHER COLUMN IS UNCHANGED and still trims with an ellipsis — a long address should give way rather than shove the whole grid sideways; the exception is deliberately for identifiers. A test pins it, so the clamp cannot quietly come back in a later merge.'],
  ['0.54.39', 'THE ROUTE BOX ON AN ORDER NOW CARRIES THE DRIVER\'S NUMBER, AND THE NUMBER IS THE TEXT BUTTON. Chad, on a stop\'s ROUTE section: "this should have the route name drivers name and their phone number that is a hyperlink that brings up simple text with the pro number and name of customer pre populated." It now reads route name, driver, and the driver\'s mobile — and tapping the number opens the SimpleTexting composer already filled in with "PRO 007157031 — GOOGLE: ", the same reference line every order-text opens with since v0.54.38. So the answer to "who has this order and how do I reach them" is one line and one tap, instead of scrolling for the Text driver button. WHERE THE NUMBER COMES FROM: the MarginIQ employee card, resolved on the server — not matched in the browser. That matters because NuVizz names a driver however the load was keyed and the employee card carries the ALIASES for exactly that ("Mike Frye", "Frye, Michael"), so a browser-side name match would quietly fail for the drivers aliases exist to cover. Each name is looked up once and remembered for the page, misses included, so opening twenty stops on one driver is one lookup. NO NUMBER ON FILE, NO LINE — a driver whose card has no mobile simply shows no phone row rather than a dead link, and that is the honest answer: add the number in MarginIQ and it appears. Sending is unchanged and still resolves the number server-side at send time, so even a stale label can never misdirect a message. Zero NuVizz calls — this reads the employee roster, nothing else.'],
  ['0.54.38', 'TEXTING A CUSTOMER NO LONGER STARTS FROM A BLANK BOX. Chad, looking at the Text window on a GOOGLE stop: "i want it to prepopulate the message with the customer name and their pro number." Done — the Text button on an order now opens on that order\'s reference line, "PRO 007157031 — GOOGLE: ", with the caret sitting after it so you just type what you want to say. That is the same line the "Text driver about this order" button has always opened with, so a message about a delivery now reads the same whether it is going to the driver or to the customer. It is ordinary editable text: trim it, or delete it entirely, and nothing else changes. A missing field never leaves a mess — no PRO on the order gives you "GOOGLE: ", no customer name gives you "PRO 007157031: ", and an order with a stop number but no PRO uses the stop number. Both places the order text lives are wired: the Map stop panel AND the same panel ported into Routing, with a test pinning both so a stale-base merge can\'t quietly blank one of them out (that is exactly how the last-stop ✕ went missing for days in v0.54.19). Bulk "Text selected" is deliberately left blank — those messages go to many different orders at once, so there is no single PRO to seed. AND TO ANSWER THE OTHER HALF OF THE QUESTION — "shouldn\'t this be using simple text": it already is. This window has always sent through SimpleTexting on the Davis number, not through your phone and not through NuVizz, which is why replies come back into the Messages panel. Nothing about that changed here; the only change is what is already typed in the box when it opens.'],
  ['0.54.37', 'THE RESTRICTION ICONS ARE HALF THE SIZE. Chad, pointing at a red no-tractor-trailer truck parked over a stretch of highway: "make this icon half as big." Done — every icon that REPLACES a stop\'s pin when that stop carries restrictions (the red no-T/T truck, the amber Uline straight-truck advisory, liftgate, appointment, the receiving-hours day badges, and the "+N" overflow) now draws at 20×22 instead of 40×44. It had been the biggest thing on the map: taller than a numbered route pin (30) and more than twice an unplanned stop dot (16), which is backwards for a mark whose whole job is to ANNOTATE a stop rather than be one. A stop carrying two or three restrictions shrinks by the same half, so a row of icons stays in proportion with a single one. Nothing else moves: same artwork, same colors, same slash, and the same anchor point — the icon still sits on its exact address, not shifted half a marker off it — and because it is vector art it is drawn smaller, not squashed, so it stays crisp on a phone. The Legend previews shrink to match, on purpose: they render the very same image the map draws, so what you see in the legend is what you will find on the board. Cosmetic only — no data, filtering, scanning, or routing behavior changed.'],
  ['0.54.36', 'THE ESTES ORDER THAT KEPT "REVERTING TO THE DAVIS ENTRY" — TWO NUVIZZ RECORDS SHARE ONE NUMBER, AND EVERY BY-NUMBER LOOKUP WAS FREE TO ANSWER WITH THE WRONG ONE. Jessica, on Estes-0828068215: "I have rekeyed it in dispatch map and as soon as i change the date even in Nuvizz, it automatically reverts to the Davis entry" — and an hour later, "I tried to update this Estes delivery date in nuvizz and it completely changed the address." Neither of those is a haunting; both are one defect. NuVizz can hold TWO order records under ONE stop number — here, the rekeyed order to the real customer sitting next to the older entry consigned to Davis — and everything in this app that looks an order up asks BY NUMBER and trusts whichever single record NuVizz hands back. So the date change read the OTHER record, moved ITS window, and then refreshed the card from the same by-number lookup — which is precisely "it completely changed the address". And on every scan, the board collapsed the two records into one card last-wins, so the finished Davis-side entry kept replacing the live rekeyed order — precisely "it automatically reverts". This app learned this exact lesson for LOADS in v0.54.24 (two loads named STEVEN: identity wins, and a shared name is not allowed to speak for either); this release applies it to ORDERS. FIVE PLACES, ONE RULE — the record\'s internal id, which the board\'s feed already carries for every row, is the identity; the number is just a label. (1) Changing a delivery date now pins the write to the exact record on your screen — if NuVizz answers the read with a different record, the app REFUSES, tells you two orders share the number and which record it was offered, and writes NOTHING (before this it would have happily moved the twin\'s date, or recorded a board-date override read off the twin). (2) Notes to NuVizz get the same pin. (3) After a date change lands, the card only repaints from a lookup that returned the SAME record it verified the write against — never the twin. (4) The scan no longer merges a by-number detail pull over a board row when the ids disagree — that merge is exactly how the corrected address kept getting overwritten with the Davis one — and the same check keeps a twin\'s record from voting a live routed stop off (or onto) a truck in the demotion verify. (5) The board no longer lets a finished twin silently replace live work under the shared number: the LIVE record keeps the card, and the card now carries a red warning — "2 orders share this number" — telling you plainly to cancel or renumber the extra entry in the portal, because while the duplicate exists, portal searches and every by-number path (NuVizz\'s own included) will keep finding the wrong one. THE REAL REMEDY, same as STEVEN: clean up the duplicate in NuVizz and every symptom goes with it — the badge clears itself on the next scan once only one record carries the number.'],
  ['0.54.35', 'YOU CAN GET RID OF A ROUTE COMPLETELY AGAIN — AND NOW IN ONE CLICK. Chad, tonight: "I still have no way to get rid of a route compelely and put all stops back to unplanned." He was right, and here is the uncomfortable reason: the app COULD do this from v0.54.17 (Jul 29, built after this exact complaint the first time) — but v0.54.19, the call-ceiling release the next morning, was cut from an older copy of this screen and its merge quietly put the old code back. The ✕ vanished off the last stop, so a card could be struck down to one order and NO further — while everything behind that button (the route cancel in NuVizz from v0.32.20, the board flip back to Un-Planned from v0.54.18, the red confirm popup, the July 30 refusal/executed-stop hardening) sat fully working and unreachable. THREE THINGS IN THIS RELEASE. (1) THE LAST ✕ IS BACK — amber, labelled for what it really is: removing the last order EMPTIES the load, and an emptied load is a CANCELLED route in NuVizz; that is NuVizz\'s own rule for removing every delivery, not our choice. A test now pins the button itself, so a stale-base merge can never silently take it away again. (2) A CANCEL ROUTE BUTTON on every live Compare card — one click strikes every order off at once instead of eight ✕ clicks. Same staging as the ✕: every struck order is listed with Undo, nothing is sent until Save, and Save still puts the red "This DELETES a route" popup in front of the write. Every guard from the July hardening still stands — a NuVizz refusal fails loudly instead of reading as success, a load with a stop the driver already acted on refuses to empty, and only a positively-confirmed cancel stamps the board. (3) AFTER A CONFIRMED CANCEL THE CARD CLOSES ITSELF — the route no longer exists, and an empty card left open was an invitation to drag stops onto a dead load. The orders land back in Un-Planned on the board immediately, ready for another truck. Not in this release: the ＋ New route card keeps its own rule — it lives only on your screen until Save, so closing the card IS its cancel and it gets no button.'],
  ['0.54.34', 'NEW ROUTE, ROUND TWO — BUILD THE ROUTE FIRST, SEND IT WITH ALL ITS STOPS AT ONCE. Chad tried ＋ New route again after the 400-fix and hit a NEW rejection: reason 903, "Either PlanStop or Stop node should be present". Translation: NuVizz will not create a route with no stops on it, full stop — the "create it empty, drag orders on after" design cannot work, and no retry will change that. THE NEW SHAPE IS CHAD\'S OWN: "when a new route is created on our end then it puts it in the compare panel where we can add stops then we send new route and all stops at same time." Exactly that. ＋ New route now just OPENS A CARD — nothing is sent to NuVizz. The card sits in Compare marked "not sent", you drag orders onto it (and stage a driver if you like) exactly like any other card, and SAVE creates the route in NuVizz with the entire stop list — and the staged driver, and dispatch — riding one create. Close the card before saving and it simply never existed. WHY THIS IS STILL SAFE, because that was the whole point of the original design: each order rides the create as a REFERENCE — its number and its own schedule, echoed straight off NuVizz\'s record — never its address or freight, so the July 2 class of accident (a create overwriting real order data) remains structurally impossible. And every order on the card gets the same respect as any Save: the app reads each one first and REFUSES the whole create if any can\'t be read, is already planned on another route (you\'re told which one), or has already been acted on by a driver. Moving stops OFF a live load onto the new card works in one Save too — the live load\'s save runs first, then the create. Afterwards the app reads the route back and confirms every order actually landed — if NuVizz\'s async worker is slow you\'re told how many attached rather than being left to discover it — and the board is stamped immediately, so the stops flip to planned (and drop their old drivers\' names) without waiting for the next scan.'],
  ['0.54.33', 'THE WEEKEND NO LONGER INVENTS CARRY-OVER ORDERS. Chad, Sunday morning, holding the Uline manifest: "We do not have 127 orders carrying over from last week so scan is not showing closed out orders correctly." He was right about the number and the scan was innocent — I checked his manifest against the board order by order, and the day\'s own freight matched Uline EXACTLY: 545 orders, 848 skids, 117 loose, 260,898 lbs, every PRO present. The phantoms were all in the carry-over fold. WHAT ACTUALLY HAPPENED: every scan writes down which old orders are still genuinely open, and the board uses that list to keep delivered work from re-appearing as carry-over. Friday night\'s 10:31 PM scan wrote that list correctly. But the board only trusted the list while it was under 18 hours old — a rule meant to survive one quiet night, written before scans went dark on weekends. So from Saturday afternoon on, the board threw Friday\'s perfectly good list away and, having nothing to check against, showed EVERY undelivered-looking old order — 127 of them, when the real count was 24. Sunday\'s 1:13 PM scan wrote a new list and the number collapsed on its own, which is exactly the proof of what broke. THE FIX: the list no longer expires by clock. Nothing on the board changes while scans are dark — so a Friday list is still the newest truth on Sunday, and the board now keeps using it straight through a weekend or a breaker pause. It is set aside only for the reasons that are REAL: a scan ran but the list somehow was not rewritten (then it truly is behind), or it is over a week old (past what it can vouch for at all). In both of those cases the board still folds everything rather than hide work — showing too much stays the failure mode, never showing too little. Four tests pin the new rule, including a replay of this weekend.'],
  ['0.54.32', 'THE STOP CARD NOW ANSWERS "WHERE IS THIS ORDER?" AT A GLANCE — AND THE BUTTONS YOU ACTUALLY USE ARE REAL BUTTONS. This is Enhancement 6 from the UI report, built as approved. THREE CHANGES. (1) A STATUS TIMELINE at the top of every stop card: Scheduled → Out for delivery → Delivered, with the current step highlighted and the times the app truly has — arrival and delivery stamps when they exist, and an ETA on the last step ONLY when NuVizz has a real one. A schedule window is never dressed up as an arrival prediction; that is the exact lie v0.54.4 stamped out, and the timeline keeps the rule. An exception shows as a red terminal state instead of being forced into a delivery story, and unplanned or cancelled orders keep the plain status chip they had. (2) THE HEADER CARRIES THE ROUTE — "SUW 4 · stop 6" sits at the top right, so you no longer scroll five sections to learn which truck an order is on. The PRO also has a small copy button: one tap and it is on your clipboard for pasting into NuVizz, Estes, or a text. (3) FOUR THUMB-SIZE BUTTONS — Text, Call, Navigate, Ticket — replace the pile of look-alike text links. Those four are nearly every tap this card ever gets, and on a phone a text link is the hardest thing on the screen to hit. Call only appears when there is a number to call; Navigate opens Google Maps on the corrected pin when you have saved one. Everything else — Street View, Edit address, Correct pin, Text driver, History — is one tap away under "More", and nothing was removed. The big Delivery Ticket button is gone because the Ticket button in the bar IS it, one screen position higher. Both the Map and Routing cards get all of this, desktop and phone, because they have been the same card since v0.45.22. Seven tests pin the timeline\'s honesty rules — including that the out-for-delivery step never invents a time the app does not have.'],
  ['0.54.31', 'THE LIVE TRUCK ICONS ARE SMALLER. Chad: "make the motive truck icons smaller." They were 40 pixels across — the BIGGEST marker on the map, larger than a numbered route pin and more than twice the size of an unplanned stop dot. That was survivable while the driver layer was only ever showing part of the fleet; once v0.54.12 fixed the page-one cutoff and every truck started drawing, twenty-odd 40-pixel trucks blanketed metro Atlanta on a phone and buried the stops underneath them. The truck is now 28 pixels: still an easy tap, still obviously a truck, but it sits BELOW a route pin in size, so your stops read on top of the traffic instead of the other way round. The driver name plate moves with it — its offset is now calculated from the icon size rather than typed in separately, so the label can never end up sitting on top of the truck if the size is ever changed again. Nothing else about the layer changed: same 60-second refresh, same names, same fade after 30 minutes without a ping.'],
  ['0.54.30', 'SCAN NOW NO LONGER DIES ON A BIG MORNING. Chad: "Scan refused (HTTP 504)" on the status card. That 504 was not NuVizz and not the call ceiling — it was our own button. HERE IS THE HISTORY, because this is the second time this button has broken and the two breaks are connected. The scheduled scanner runs as a background job with a 15-minute budget, precisely because a scan takes longer than the ~26 seconds a normal web request is allowed to live — its own code has said so for months. But carrying a cron schedule also makes that function unreachable by a button press (the Jul 29 "why is my scan not available?"). The Jul 29 fix added a fallback that runs the scan INSIDE a normal request — which works on a light board and dies by timeout on a heavy one. Today was a heavy one: 743 stops, 44 carry-overs, 61 NuVizz calls in the 6 AM hour alone. The scan outran its 26 seconds, the gateway killed it, and the button reported "refused" — the worst version of the message, because the scanner had ACCEPTED and was working when it was shot. So the button failed exactly on the mornings a dispatcher most needs a fresh scan. THE FIX IS THE MISSING THIRD PIECE: the same scan behind a background function WITHOUT a schedule. No schedule means a button press reaches it; background means it answers immediately and takes its 15 minutes in peace; the board refreshes itself when the scan lands, exactly as it already did. The two older routes stay as fallbacks. The button also stops lying when a timeout does happen: a 502/504 now reads "Scan timed out — the board is too big for the synchronous scanner", not "refused". AND THE GUARDRAIL THAT MATTERS: the new endpoint structurally CANNOT run the expensive scan — it strips any date parameter before scanning, and a date is what flips the scanner into the ~3,000-call full probe. However this endpoint is called, it is the same cheap ~4-call scan the schedule runs. Three tests pin all of it: no schedule may ever be added to this function, the background suffix must stay, and the date parameter can never ride through.'],
  ['0.54.29', 'THE CUSTOMER\'S PHONE NUMBER IS ON THE STOP CARD NOW. Chad, with NuVizz open beside the app: "why are we not displaying customer phone numbers?" KAI WONG\'s number was sitting in NuVizz\'s Ship-To block and nowhere on our card. WE HAD IT THE WHOLE TIME — that is the annoying part. The scan already pulls the consignee contact off every order, and the Text customer button has always used it; that is exactly how that button knew whether to say "Text customer" or "Text customer (add #)". The number was one click deep inside a compose box and printed nowhere, so the single thing you need in order to CALL a customer was the one thing the card would not tell you. It now shows under the address, with the contact name in front of it when NuVizz has one, and it is a real link — tap it on a phone and it dials. If you have saved your own number for that customer in the notes, yours is shown, exactly the way texting already picks it. Numbers print in the normal (678) 860-8099 shape, EXCEPT when they are not plain US numbers: an extension or an international number is shown exactly as it is stored, because a number reshaped to look American is a number you might dial wrong. Nothing to turn on, no NuVizz calls — this data was already in every stop.'],
  ['0.54.28', 'A SEARCH THAT FINDS NOTHING NOW TELLS YOU WHEN YOUR FILTERS ARE THE REASON. Chad searched PRO 7153822 and got "No stops match" — then: "this is showing nothing however this is planned on a route today, trailer 6." The order was on the board the entire time. Two filters were holding it back: "Has receiving hours" in the left Filters panel and "Hide stem out" on the map. His own conclusion: "all stop filters were the problem." THE SEARCH BOX WAS TELLING HIM SOMETHING FALSE. Search only looks at the stops that survive your filters, so an order a filter has removed can never be found — and the box reported that as "No stops match", which reads as "that order isn\'t on today\'s board." Those are completely different statements, and the wrong one sends you to NuVizz to hunt for an order that was two clicks away. The bottom grid has named its own filters since v0.45.6 and got smarter again in v0.53.11; the search box never learned to do it. Now, when a search comes back empty, the app re-runs the SAME search against the unfiltered board. If the order is there, it says so plainly — "It IS on this board — hidden by your filters" — with a Clear filters button beside it, on both the search box and the map. The button clears BOTH sets, the panel filters and the map toggles, because your board had one of each and clearing either alone would still have hidden it. If the order genuinely is not on the day, the message is unchanged: no stops match, and now you can trust it. Costs nothing when a search finds something, since it only runs on an empty result.'],
  ['0.54.27', 'THE STOP CARD LISTED ITS FREIGHT TWICE. Chad: "why are items listed twice, get rid of the second one and make the one a little bigger." He was looking at ITEMS (8) with "3 pallets · 31 loose · 34 pieces · 862 Lbs" and then, directly underneath, "3 pallets  31 loose pcs  34 total pieces" — the same three numbers again, worded slightly differently, which reads like the two lines might be saying different things when they never were. The second line is gone and the remaining one is bigger and darker. WHICH ONE I KEPT, AND WHY IT IS NOT AS OBVIOUS AS IT LOOKS: the top line is the better of the two — same numbers plus the weight, which the lower one never showed. But it is written once, by the nightly scan, and it is NOT recalculated when an order is later looked up in detail. So there are stops whose pallet and piece counts arrive only from that detailed lookup, and on those the top line can still read "—" while the numbers underneath are real. Simply deleting the lower line would have blanked the freight on exactly those orders. So the lower line became the BACKUP instead: the card shows the scan\'s summary when it has one, and otherwise builds the same sentence from the live numbers. Either way you get one line, and no order loses its freight. Four tests cover it, including the awkward case.'],
  ['0.54.26', 'NEW ROUTE WORKS NOW — NUVIZZ SAYS "400" WHERE WE EXPECTED "NOT FOUND". Chad tried the new ＋ New route button and got: "could not confirm load TRAILER-0731 is free (NuVizz answered 400 to the check) — nothing was created". Nothing was wrong with the route or the name; the app refused ITSELF. HERE IS WHY, and it is the exact thing I told you I could not test without spending calls on your live system. Before creating a route the app asks NuVizz "do you already have this load number?" — because the call that creates a route is the same call that EDITS one, so pointing it at a number already in use would quietly rewrite a real route instead of making a new one. That check has to be certain. I coded it to accept one answer as proof the number was free: a 404, the standard "not found". Your NuVizz answers 400 instead. So every check came back as an answer the app did not recognise, it correctly refused to guess, and no route could ever be created. WORTH KNOWING: the app already asks NuVizz whether an ORDER number exists, and there NuVizz does answer 404. So the two are genuinely inconsistent, and there was no way to know which one applied to loads without asking it for real — which is what your click just did. Both answers mean the same thing and are now both accepted: the lookup came back with no load, so there is nothing at that number to overwrite. WHAT STILL REFUSES, deliberately: a login or permission error, a rate-limit, or a server/network failure. Those are not "the number is free", they are "I could not check" — and creating on one of those risks editing a live route. The rest of the safety is unchanged: the route is still read back after it is created, because NuVizz acknowledges these before the work is actually done, and the name is still verified so you never hunt the board for a route that landed under a different one. And if the number turns out to be malformed rather than merely unknown, the create itself fails loudly and nothing is written.'],
  ['0.54.25', 'BOTH STEVENS NOW EXIST, AND CLICKING THE LIVE ONE PUTS HIS STOPS BACK ON THE MAP. Chad: "shouldn\'t they have different load numbers so for this particular day we should display both — the active and canceled one." Yes, and that is the better answer than the one I shipped an hour earlier. Yesterday\'s fix stopped a cancelled load from stealing the live one\'s status badge, but it did it by REFUSING TO GUESS whenever two loads shared a name — safe, and useless: the app then could not tell which STEVEN a card belonged to, so clicking his route opened nothing and his 16 stops vanished off the map. Correct and unusable is still broken. HERE IS THE RULE THAT FIXES IT PROPERLY. A cancelled load holds no work — NuVizz sends its orders back to Un-Planned when you cancel it. So when two loads share a name and only ONE of them is alive, there is nothing to guess at: the live one owns the name, and any stops on the board under it can only be his. The app now says so. STEVEN\'s card opens again, his stops draw on the map, his status reads Planned, and a Save works — while a real tie (two LIVE loads with the same name) still refuses rather than pick, because that one genuinely cannot be resolved from the board. AND BOTH LOADS ARE NOW LISTED, which is what you actually asked for. The Loads column used to key everything by NAME, so a second load wearing the same name was simply hidden behind the first. NuVizz identifies a load by its NUMBER — a name is just a label, and two loads can wear it at once. So the day\'s load list is now the authority: one row per load, each with its own number, its own status and its own stop count straight from NuVizz. Your two STEVENs show as two rows — one Cancelled with 0 stops, one Dispatched with 16 — and each prints its load number underneath so you can tell them apart and find either in the portal. The one carrying work sorts first. One deliberate limitation, stated plainly: the stop feed we scan carries the route NAME but no load number, so when two loads share a name the board\'s stops cannot always be traced to one of them. When that happens those orders get their own row saying exactly that, rather than being quietly attached to whichever load the app happened to read last — which is the mistake that started all of this.'],
  ['0.54.24', 'STEVEN WAS NEVER CANCELLED — TWO LOADS SHARE THAT NAME AND THE WRONG ONE WAS DOING THE TALKING. Chad, with the portal open beside the app: "why are we showing this load canceled its not canceled in nuvizz." STEVEN had 16 orders, a driver and 52 miles on it in NuVizz, and a red CANCELLED badge on our board. HERE IS THE MECHANIC. A route\'s status does not come from its stops — it comes from the day\'s load list, looked up in a table this app builds. That table was keyed BY NAME, and when two loads on the same day share a name the second one simply overwrites the first. So the day\'s list held two STEVENs — one cancelled, one live — and the cancelled one won the name. Worse, the lookup asked for the name FIRST, before the load\'s own id, EVEN THOUGH we knew this route\'s exact id from its own stops. We had the right answer in hand and asked the wrong question. Identity now wins: a route reads its status from its own load id, and a name shared by two loads is not allowed to speak for either of them — in that case the status is worked out from the route\'s own stops instead, which can never be another load\'s. The code already refused to trust a shared name when assigning a driver or opening a card; the status badge was the one place that never got the same rule. THE SAME DUPLICATE EXPLAINS THE SAVE ERROR you hit right after: "null: commitBoard(rwb): loadNbr or loadId required" while adding orders, with NOR refusing too. When two loads share a name, this app deliberately refuses to guess which one a card belongs to — so the STEVEN card opened carrying NO load number and NO id, and a card like that can never be saved. It let you build the whole thing and told you afterwards. It now refuses AT THE MOMENT YOU OPEN IT and says why: two loads are named STEVEN today, rename one in the portal or cancel the one you are not using. Assigning a driver and dispatching already refused this way; opening a Compare card was the last path that let you do the work first and find out later. NOR\'s message was not a second fault — it is the safety net doing its job: a stop being moved onto a card that failed would have been unplanned by saving NOR, so NOR stopped rather than drop it. And a failed card no longer prints as the word "null" in front of its error. THE REAL REMEDY IS IN NUVIZZ: while two live loads carry one name, this app cannot tell them apart and will keep declining to guess. Rename or clean up the duplicate and both symptoms go with it.'],
  ['0.54.23', 'THE LOADS COLUMN NOW SHOWS YOUR LOADS, AND SELECTED STOPS STAY IN THE ORDER YOU ADD THEM. Chad, looking at the Routing screen with 99 loads listed in the bottom panel and the column beside it reading "No saved loads yet": "can you make loads that are showing up in this bottom panel show up on the right panel, it currently doesn\'t hold or do anything, routes never end up on the column even though it says its what its for." He was right, and it was not a broken feature — it was two different things sharing one word. A LOAD in that column meant a SAVED PLAN: the output of the routing optimiser, the thing the Save load button writes. A load everywhere else in this app means a real route on the day\'s board. So the column was working perfectly and answering a question nobody was asking, while the 99 real loads sat two inches below it. THE COLUMN NOW SHOWS THE DAY\'S ACTUAL LOADS — the same set as the bottom panel: every route built on the board, plus every empty Draft. That second half matters more than it sounds. An empty load has no orders, and everything else in the app finds loads by looking at their orders — so a load with none is invisible to it. They only exist in the day\'s load roster, which is why your 99 loads are nearly all Drafts and why they never showed up in a routes list. Each row shows the driver, stop count, skids and loose, and how much of it is delivered; empty ones are marked "No orders yet". Click any row and it opens in Compare, exactly like clicking it in the bottom panel. There is a search box, and a Built only button that hides the Drafts — on a board like yours that is the difference between scrolling 99 rows and seeing the handful actually carrying freight. If two loads share a name that row says so, because a name is not enough to tell them apart and the app will not guess. YOUR SAVED PLANS ARE NOT GONE: the tab has an On the board / Saved plans switch, and it remembers which one you were using. SECOND FIX, THE STOPS LIST. "when stops are added to this screen i want the default sorted to the order they are added." It was sorting alphabetically by customer, so the stop you just clicked landed somewhere in the middle of the list and you had to hunt for it to confirm it went in. It now stays in the order you added them, which is also the order you were thinking in when you clicked. All the sort buttons still work; there is a new Added chip at the front to get back to add-order after you have sorted by something else. Both the side panel and the floating Selected list behave the same way, so they cannot disagree with each other.'],
  ['0.54.22', 'YOU CAN CREATE A ROUTE FROM THE ROUTING TAB. Chad: "I want to be able to create a route in the routing tab." Until now this app could DESTROY a route but never make one — emptying a load cancels it in NuVizz, and the rebuild had to happen in the portal. That was a one-way door, and it got a lot easier to walk through yesterday when the last order became removable. There is now a green ＋ New route button at the top of the Routes list. Give it a name — TRAILER 6, SUW 2, whatever you would call it on the board — and it creates an empty route on the day the board is showing, then opens it as a Compare card so you can drag orders straight onto it and Save exactly like any other route. WHY IT IS SAFE TO SHIP THIS, given the history: the July 2 incident that wiped freight off 10 live orders came from the load-import path, where sending an order by REFERENCE made NuVizz replace the whole order. That engine is still switched off and this does not use it. Creating a route sends a HEADER ONLY — a name, a day, and the warehouse it leaves from. There is not one order in the message, so there is nothing it could overwrite. The orders get planned onto the route afterwards by the ordinary Save you already use, which refers to orders by id and cannot blank them. THREE THINGS IT CHECKS BEFORE IT WRITES ANYTHING. (1) The load number has to be genuinely free. NuVizz uses one call for "create or update", so aiming it at a number that already exists would quietly EDIT that route instead. It only proceeds when NuVizz confirms the number is unused — and if the check itself fails, it stops rather than guess, because "I could not look" is not "it is free". (2) It reads the route back afterwards. NuVizz answers these calls before the work is actually done, so a success message is not proof; the route has to be readable or you are told it did not land — and told NOT to create it again under the same name, since that is how you end up with two. (3) It checks the NAME that came back. If NuVizz numbers the route itself instead of taking your name, you are told what it is actually called, so you are never hunting the board for a route that is not there under the name you typed. NuVizz caps a route name at 20 characters and needs its own load number, which is built from your name plus the date (TRAILER 6 on the 31st becomes TRAILER6-0731) — so the same route can be created again tomorrow without colliding with today. The form shows you that number before you commit. You need a ship-from address saved in the New Order tab, because NuVizz accepts a route with no origin and then silently creates nothing. Routes are created for the day the board is on — switch the board date first to build tomorrow. And there is a Beta/Live switch on the Routes panel exactly like driver assignment: in Beta it tells you what it would do and sends nothing.'],
  ['0.54.21', 'WHY "SCAN UNAVAILABLE" — AND THE CALL CEILING IS NOW A REAL 2,000. Chad: "Why is my scan not available?" and "set the max calls to 2000 and that needs to be enforced." Both done. THE SCAN BUTTON. That red line means one thing: the Scan now button POSTed to the scanner and the scanner did not accept the request. Your scheduled scans were fine the whole time — the same card said Loads updated 32 min ago. Here is why the button specifically fails: it posts to the BACKGROUND scanner, and that function also carries the every-15-minutes cron schedule. A function with a schedule attached is a scheduled function, and a scheduled function is not reliably reachable over plain HTTP — so the cron fires it happily on its own timer while a manual POST to the same address gets refused. The app already ships a second, plain endpoint that runs the exact same cheap scan, so the button now falls back to it automatically when the first one is refused. Two things worth knowing. FIRST, the fallback is called with NO date attached — deliberately. Handing it a date flips it into the roughly 3,000-call number-probe scan; without one it is the same 4-call list scan the scheduled path runs. SECOND, if it still fails you now get the actual reason and the HTTP code instead of a dead-end "Scan unavailable". And the reason you were reaching for that button matters: a MANUAL scan bypasses the orders-paused-until-10-AM hold and pulls orders for today AND tomorrow, so it is exactly the right tool when you need the board caught up before the pause lifts. THE CEILING, 2,000, ENFORCED. Your card read 133 / 20,000. It now reads out of 2,000, and 2,000 is a genuine hard ceiling: it cannot be raised by the site setting that had it at 20,000, cannot be raised by the Diagnostics editor (which could previously go to 200,000), and cannot be raised by any caller passing its own number. It can only be lowered. Enforcement also no longer depends on a setting being present — the breaker used to default to COUNT-AND-WARN-ONLY if its switch went missing or was mistyped, which is a spend cap that quietly stops being one; blocking is now the default and monitoring is the thing you have to ask for. Sizing: a normal day runs a few hundred calls, so 2,000 is about ten times real usage. Note deliberately: 2,000 sits BELOW the roughly 3,000-call cold full scan, so that scan can no longer complete by accident — it trips the breaker partway. That is the point of the number, not a side effect.'],
  ['0.54.21', 'YOUR 600 PLANNED ORDERS ARE THERE — "UNPLANNED ONLY" WAS ON, AND THE EMPTY GRID BLAMED THE WRONG FILTER. Chad: "says i don\'t have any planned orders today however i have like 600 of them." They are all there. The grid read "None of the 6 stops in this board match — hidden by status (1)", and BOTH numbers in that sentence were wrong. Your board holds 723 stops, not 6. And the thing that removed them was not the status filter — it was Unplanned only, the toggle in the map Filters panel, which was switched on. Here is the mechanism. The map panel filters the stops FIRST, then hands what survives to the bottom grid. With Unplanned only on, 723 stops became the 6 unplanned ones before the grid ever saw them. You then ticked Planned in the grid\'s own Status filter — and of course none of 6 unplanned stops are planned, so you got zero. The grid could only see its own filters, so it reported the 6 as though that were your whole board and named the only culprit it knew about. It now names every filter in the chain and reports the REAL board total: "None of the 723 stops in this board match — hidden by Unplanned only, status (1)." Hide terminal and Hide stem out are named the same way. Clear filters still clears in one click. Nothing about filtering changed — only what the app tells you when the result is empty. This is the same trap as v0.53.11, one layer further up: back then a status filter could blank the board without saying so, and the fix taught the grid to name its own filters. It could not name a filter applied before it, so the next silent blanking came from upstream.'],
  ['0.54.20', 'TWO WAYS A ROUTE CANCEL COULD GO WRONG, CLOSED BEFORE EITHER HAPPENED. A review of this morning\'s cancel work turned up two holes. Neither has been hit in the field, and both got a lot more dangerous the moment the board started trusting a cancel. (1) A REFUSAL FROM NUVIZZ COULD READ AS A SUCCESS. When you empty a load, NuVizz might report the cancellation as an error-shaped message rather than a plain success, so the code accepted any answer containing the word "cancel" as proof the route was cancelled. The problem: a REFUSAL says "cancel" too — "Load cannot be cancelled, already dispatched". That used to be a cosmetic mistake, a wrongly-worded result. Since this morning it would have been much worse: the board would mark all six orders unplanned and defend that for an hour, while NuVizz still had them planned on a route with a driver on it — and orders that look unplanned are orders someone builds onto another truck. The check now has to see an actual cancellation notice, and anything that reads like a refusal fails the Save loudly instead. If we cannot tell, the Save fails — you re-send or check the portal, which costs a minute; the other direction costs a double-planned order. (2) YOU CAN NO LONGER EMPTY A LOAD A DRIVER HAS ALREADY STARTED. NuVizz will not let go of a stop the driver has acted on — arrived, picked up, delivered. It answers SUCCESS and quietly keeps it. The route-building screen has refused those removals up front since the AVRT case back on the 22nd, but emptying a load runs down an older, separate path that never got that check — and until yesterday you could not empty a load at all, so it never came up. Now that you can, it does. Emptying a load with an executed stop is refused before anything is sent, naming the stop and its status, so nothing half-applies and finished work never gets flipped back to unplanned on the board. A stop with no execution status recorded is not treated as executed, so ordinary cancels are untouched. Four tests pin both, including that a real cancellation notice still works exactly as it did.'],
  ['0.54.19', 'CANCELLING A ROUTE NOW ASKS FIRST. Chad: "before you are allowed to cancel the entire route i want a warning to pop up that this will delete a route." Emptying a load is the one edit in the Compare panel that DESTROYS something — NuVizz cancels the route, the load stops existing, and its orders go back to Un-Planned. There is no undo for it in this app. Until now the only notice was the same small toast used for ordinary notes like "2 stops not loaded yet", and it appeared at the exact moment the write was already on its way to NuVizz — a heads-up you could not act on. Save now stops and asks. The box is red, says plainly that this DELETES the route, names it, says how many orders are coming back to Un-Planned, and states that it cannot be undone from here — rebuilding means creating the route again in NuVizz. Two buttons: "Keep the route" and "Cancel the route". Escape and clicking outside both keep the route, because the safe answer should be the easy one, and neither works once the send is actually in flight so a stray tap cannot look like it called off a write NuVizz is already acting on. IF YOUR SAVE ALSO TOUCHES OTHER LOADS, the box says so — only the emptied ones are being deleted and the rest save normally, so agreeing here never means throwing away the rest of your work. AND NOTHING ELSE GAINED A POPUP. This panel deliberately does not confirm ordinary saves, and that is unchanged: reorders, unplanning some of the orders, driver assignments and dispatches all still commit straight through with no interruption. The gate reads the actual Save being sent and only trips on a load explicitly marked as emptied — six tests pin both directions, including that an ordinary reorder can never trip it.'],
  ['0.54.18', 'EMPTYING A LOAD NOW TELLS THE BOARD, NOT JUST NUVIZZ. Chad emptied TRAILER 6 this morning — six orders struck off, Save in LIVE — and NuVizz did exactly the right thing: route cancelled, all six orders back in Un-Planned in the portal. The board never heard about any of it. The orders kept showing planned on a route that no longer existed, and the status card read "0 unplanned in last scan" even after a fresh scan. HERE IS WHY, and it took the v0.54.17 change to expose it: when a Save confirms, the server writes the result straight onto the board so you see it immediately — but that write-through only ever covered saves that leave stops ON the load. An empty-load save leaves zero stops on the load, and it runs down a different path inside the server (emptying is a route CANCEL, which NuVizz handles through an older, simpler sequence of calls) — and that path never had a board write at all. Nobody hit this before because until yesterday the app would not let you remove the last stop from a load; the moment that became possible, the hole behind it was reachable. AND THE SCAN COULD NOT RESCUE YOU, which is the genuinely unfair part: a scan that sees a previously-planned stop go missing deliberately refuses to drop it off its route until NuVizz itself confirms — that is the protection that keeps a lagging feed from tearing stops off live trucks (the Kai Wong fix). With no record that YOU unplanned them, the six orders looked exactly like feed lag, so every scan carefully put them back on the dead route. The protection was doing its job against the wrong target. THE FIX: a confirmed cancel now stamps every order the load actually held as unplanned on the board, the moment the Save comes back — same machinery as a normal save, same 60-minute protection so a lagging NuVizz list cannot flip them back to planned in the meantime. The stamped rows carry no route name, so nothing stays grouped under a route that does not exist. THE SAFETY RAILS, because unplanning by mistake is worse than the bug: the stamp only fires when NuVizz actually confirmed the cancel — a failed cancel stamps nothing; the list of orders comes from the load\'s OWN record as the server read it, never from what was clicked on screen, so a stale card row that the load never really held cannot be flipped; and if the same Save moved an order onto another truck, that order stays planned — only the genuinely freed ones stamp. Six new tests pin all of it, including that a normal save\'s behavior is byte-for-byte unchanged.'],
  ['0.54.17', 'TWO FIXES FROM THIS MORNING. (1) YOU CAN NOW TAKE THE LAST ORDER OFF A LOAD. Chad, five of six orders struck off a TRAILER 6 card: "I have no way of unplanning all stops off this load." The ✕ was hidden on whatever stop was last, from a time when the server genuinely could not empty a load — but that was fixed back in v0.32.20 and the server has handled it ever since, so the button was hiding something the app could already do. The last ✕ is there now, coloured amber and labelled for what it is, because emptying a load CANCELS the route in NuVizz. That is NuVizz\'s own rule for removing every delivery, not a choice of ours — the orders come back to unplanned, the route goes away. (2) A CANCELLED ORDER IS NO LONGER TREATED AS WORK TO PLAN. Those orange dots on the routing map with nothing else around them: exceptions. One of them, MICROSOFT ATL22, was cancelled on the 23rd and never had a route — and because it had no route the app read it as "not planned", which it then treated as "still needs planning". A week-old cancellation was sitting on the map looking like freight, it could be selected and built onto a truck, and anywhere it landed on a day\'s board it counted toward the unplanned total. Cancelled and unable-to-deliver are finished outcomes now, with or without a route: they are neither planned nor unplanned, they stay off the plan-me pile, and they stop inflating the count. Genuinely unplanned orders are untouched — a test pins each status so this cannot drift.'],
  ['0.54.16', 'CI NOW CHECKS THAT THE APP ACTUALLY STARTS. Nothing about the app changed here — this is about last night never happening again. The blank-screen deploy went out with every check green, and it had to: the fault was the kind that only appears when the code RUNS, the build has no reason to complain about it, there was no linter, and not one of the 1,100 tests opens the app. A passing build told you nothing about whether the app would start. Every build now gets served to a real browser at phone size and has to render before it can merge — if the page comes up blank or throws on startup, the merge is blocked instead of you finding out on your phone. It was checked both ways against last night\'s actual broken bundle: it fails on that one, naming the exact culprit, and passes on the fixed one. Costs about a minute per pull request and runs separately, so the fast test gate is unchanged.'],
  ['0.54.15', 'THE UNPLANNED COUNT IS TRUSTWORTHY AGAIN. Chad, holding a 650-order Uline day against a board reading 548 unplanned: "I can\'t drop the carry over setting I need to see what ever is actually unplanned from however many days I have it set for but it\'s showing more than that." He was right, and the freight itself was never the problem — all 650 Uline orders were on the board, 1,035 skids against their 1,031, 204 loose against their 204. The bad number was the carry-over. Carry-over folds still-unplanned orders from previous days onto today. Those older days are frozen the moment they are scanned — we never rewrite them — so an order that was unplanned on the 17th reads unplanned on that day\'s record forever, even after it is delivered. The one thing that could retire it was the live unplanned list, and that list only reaches back about seven days, so it deliberately refuses to judge anything older. Nothing else could either. On the day this was found: 199 orders carried in, 41 genuinely open, 44 correctly held as planned, and 114 from the 16th through the 21st that were finished and had no way out. Worse, that pile can only grow — every order that ages past a week becomes permanent. Now the nightly scan settles them against the delivery history, which unlike the seven-day list never expires: if any day recorded that order delivered, cancelled or failed, it is retired and stops folding, at any age. Reading the board costs one extra lookup for the whole list. The rule is one-directional on purpose — an order is only ever removed on positive proof it finished. No proof, an unreadable record, a scan that runs out of budget: it keeps showing, exactly as it does today. This can under-count nothing; it can only stop counting work that is already done. Your carry-over setting is untouched — set it to whatever number of days you want to see.'],
  ['0.54.14', 'HOTFIX — THE APP WOULD NOT LOAD AT ALL. Chad: "App isn\'t loading on mobile." It was not loading anywhere; a phone was just the first device to fetch the new code, because a desktop tab that has been open a while keeps running the copy it downloaded earlier. Yesterday\'s Dock-scanner-drivers work (v0.54.13) put the panel\'s open/closed switch inside the Routing screen but drew the panel itself from the app\'s outermost frame — two different places in the code, and the outer one has no idea that switch exists. The very first thing the app did on startup was ask for a value that was not there, which stops the page dead before a single pixel is drawn: a white screen, no error, nothing to tap. The panel is now drawn in the same place that owns the switch and the ⚙ menu item that opens it, so the two can never drift apart again. Nothing else changed and no data was affected — the app could not start, so it never read or wrote anything. Worth knowing for next time: a build passing does not catch this. JavaScript only complains about a missing value at the moment it runs, and no test opens the real app, so it went out green. The fix was verified by loading the built app in a real phone-sized browser and confirming it renders — which is now the check to run before anything ships that touches the app frame.'],
  ['0.54.13', 'DOCK SCANNER DRIVER LOGINS ARE NOW MANAGED FROM THIS APP. The driver-facing load scanner needs its own logins, because NuVizz has no per-driver auth at all — it is one service account for the whole company, so a driver cannot sign in \"as themselves\" anywhere in it. That means a separate credential store, and until now the only way to touch it was a second admin URL. Settings menu, Dock scanner drivers: create a driver number, issue a temporary PIN they are forced to change, reset a PIN, clear a lockout after five wrong tries, and deactivate someone the moment they are gone — which takes effect on their very next request, not whenever a laptop is next opened. THE PART THAT MATTERS MOST IS THE ALIAS LIST. The scanner has to know which of today\'s stops belong to the driver holding the phone, and the only driver field on the board is unreliable by construction: it carries a short code like VINCENT on stops that came from a NuVizz scan, but the FULL NAME on stops our own routing engine planned, and it has historically had internal ids leak into it. So matching is not a guess — each driver login holds the full set of spellings they appear under, maintained by hand. Pull the alias report and every NuVizz name on the board for the last 14 or 30 days is listed with how many stops it appeared on and whether it is mapped yet; unmapped ones are highlighted and can be attached to a driver by clicking them instead of typing. If a driver\'s spellings match nothing, or two drivers claim the same one, the scanner refuses to show a load and asks for the load number off the paperwork — it will never put someone on a plausible wrong truck. Those refusals land in a review queue on this panel. NOTHING ABOUT THE CREDENTIAL STORE LIVES IN THIS APP: PIN hashing and every write stay in the scanner, reached server-to-server so no browser ever talks across sites. Zero NuVizz calls anywhere in this feature.'],
  ['0.54.12', 'THE LIVE DRIVER MAP NOW SHOWS THE WHOLE FLEET — IT WAS ONLY EVER SHOWING PAGE ONE OF MOTIVE\'S ANSWER. Chad, holding our map next to Motive\'s Fleet View: "not matching what motive." Verified against the live feed before answering: our layer was serving 22 trucks, every one of them numbered 2195 or below, and the four missing trucks — 2618T Rasko Suljic, 5042 Enock Akyea, 7521 Mone Watkins, 7750 Chris Head — are all numbered above that. That split is not a coincidence. When we ask Motive for vehicle positions, Motive answers in PAGES of about 25 — and our request never asked for page two. Any truck past the first page simply did not exist on our map: no pin, no label, nothing to even hint it was missing. The fleet grew past 25 trucks and the map silently stopped keeping up. THE FIX: the request now walks every page until Motive says the fleet is complete, removes duplicates, and can never loop even if Motive misbehaves — with a safety bound far past any fleet Davis will ever run (1,000 vehicles). ALSO CHECKED WHILE VERIFYING, because your screenshot showed it: truck 0424 read "(no driver) stale" on our map while Motive named Allen Council driving at 36 mph. The live feed NOW carries Allen Council on 0424 with a fresh ping — so that one was a moment-in-time gap (the pairing landed after your screenshot), not a second defect; the honest "(no driver)" label only shows when Motive itself names nobody. And one small landmine defused: Motive sends truck 0186T\'s number with a trailing space, which would silently break any exact match against a clean roster — numbers are now trimmed. Nothing else changed: same 60-second refresh, same labels, same stale fade after 30 minutes.'],
  ['0.54.11', 'RA ORDERS NOW READ AS PICKUPS EVERYWHERE — IMMEDIATELY, NOT EVENTUALLY. Chad: "Ra\'s should be marked as pickups and not deliveries." They were typed as deliveries at the source: the saved-search feed carries no stop-type column, so every row entering the board was stamped Drop-Off, and a pickup only became a pickup when its one-time detailed lookup happened to run and correct it. Until then the stop card said Drop Off, the grid showed it like any delivery, and the map drew it as one. RA-prefixed order numbers ARE pickups — that is Davis\'s own numbering — so the board now types them as pickups the moment the scan sees the number, with the detailed lookup still the final authority if the two ever disagree. WHERE YOU\'LL SEE IT: the bottom grid shows an amber PU chip in front of the customer name; the map pin carries a PU tag in the same slot the AM/PM window uses (a delivery-window tag or a restriction icon still outranks it — a safety mark beats a type mark); route cards keep the amber PU badge from 0.54.10; and the stop card\'s Type row now says Pick Up from the first scan instead of after enrichment. Nothing about counts, statuses, or routing changed — this is the same stop, finally wearing the right label from the start.'],
  ['0.54.10', 'THE TWO "STOP 16"S ON RASHEED ARE PICKUPS WEARING THE TERMINAL\'S NUMBER — NOW LABELLED AS WHAT THEY ARE. Chad: "our system should match NuVizz and we are showing two stop 16\'s in ours." Verified against the stored board before answering: those two rows are the route\'s two PICKUPS (the desk at College Station Rd and the Georgia Univ pickup), and they are real, single stops — not duplicates. Here is the trap. The stop number our feed carries is NuVizz\'s ShipTo Display-Seq, which numbers the DESTINATION side of each order. For a delivery, the destination IS the customer, so the number is the stop\'s true position — that is why every delivery on your panel matched the workbench exactly. For a pickup, the destination is where the freight is GOING: the terminal. Both pickups return to the same terminal, so both inherited the TERMINAL RETURN\'S slot — one shared number, one past the last delivery. 15 when the route had 15 positions, 16 on your screen after a stop was added. The workbench numbers pickups by where the truck actually visits them — 4 and 13 — and the proof is in our own deliveries: their numbers skip exactly 4 and 13. THE HONEST PART: the pickup\'s true run position lives only inside NuVizz\'s route record. It is not in the saved-search feed we scan, at any price, so this app cannot print 4 and 13 without asking NuVizz — and it will not pretend otherwise. WHAT CHANGED: a pickup on a route card now shows an amber PU badge instead of a number (hover it and it says why), and on the framed route map it pins as P instead of a numbered circle. No number ever prints twice, deliveries are untouched, and the pickups sit at the end of the list where the terminal-return slot files them. If the run order of pickups matters for planning a specific route, the workbench remains the authority — one click away.'],
  ['0.54.9', 'CHAD WAS RIGHT ABOUT MARCUS AND LEROY — THE ENGINE PAGE\'S "WHAT DISPATCH RAN" NUMBERS WERE INFLATED, AND HERE IS THE PROOF AND THE FIX. Yesterday this changelog told you 19 and 20 were "what dispatch actually sent them out with." That was wrong. NuVizz\'s own load records for Jul 28: DAWSONVILLE 14 stops, 2,799 lb. CRUMPTON 13 stops, 3,716 lb. Chad: "Marcus and Leroy have never taken 20 stops on one trip ever." Correct — they did not do it on Jul 28 either. WHAT THE VERIFICATION FOUND, reading our own stored day back with zero NuVizz calls: DAWSONVILLE\'s stored 21 rows split into 14 rows DELIVERED on the 28th whose weights sum to 2,799 lb TO THE POUND — exactly NuVizz\'s 14 — plus 7 ESTES orders sitting SCHEDULED with no delivery time at all. CRUMPTON identically: 13 delivered rows summing to exactly 3,716 lb, plus 7 un-delivered ESTES rows. And every one of those 14 extra orders is ON TODAY\'S BOARD RIGHT NOW, on today\'s DAWSONVILLE and CRUMPTON runs — three of them already delivered this morning. THEY ARE TODAY\'S FREIGHT. What happened: when tomorrow\'s routes get built in the evening out of Estes imports, those orders carry no Estimated Arrival, so the board files them on TODAY — that is the same by-design behaviour the date-change feature exists to work around. At the last scan of the 28th they were sitting planned on the 28th\'s board; the nightly history capture sealed the board as-is; and the engine\'s replay then counted tomorrow\'s stops and tomorrow\'s pounds as work Leroy and Marcus did. THE FIX — THE REPLAY NOW DEMANDS EVIDENCE. A stop only counts as "what dispatch ran on day D" if its delivery stamp lands on day D. Planned-but-never-stamped rows are excluded from the actuals, from the engine\'s input pool, from the driver-day profiles the engine learns from, and from the mined route shapes. That one rule also kills the other zombie classes in one move: a stale plan carried forward for days, and a delivered order double-counted on the day it rolled FROM as well as the day it ran. A stop that rolls overnight now counts on the day it was actually driven — once. SAFETY: on a day where most stops carry no delivery stamps at all (old sparse captures), the check switches itself off and that day replays exactly as before, so old history is not erased. ALSO FIXED WHILE IN THERE: the stop count and the pounds on a driver row were computed over two DIFFERENT sets of stops — pounds included rows the stop count skipped — which is why the numbers could not be reconciled against each other. They now describe the same stops. HOW IT ROLLS OUT: this corrects days as the engine re-scores them (tonight\'s run, or Re-score history in the tuning panel — cached data only, zero NuVizz calls). And to be plain about the accounting: with the phantoms removed, the engine\'s Jul 28 answer for Leroy was 12 stops against a real 14 — near agreement — not the halving yesterday\'s explanation described.'],
  ['0.54.8', 'THE ENGINE IS NOT THE ONE PUTTING 20 STOPS ON MARCUS AND LEROY — DISPATCH DID. PLUS A LEGEND FOR THAT WHOLE PAGE, AND AN ANSWER ON THE GREY LINES. Chad: "marcus and leroy have never taken 20 stops on one trip ever so why in the world would it put that many on them? Owusu, that page needs a legend so someone knows how to interpret what they are looking at on the map, and what is all the gray shadow lines?" THREE THINGS, AND THE FIRST ONE IS THE PAGE LYING BY ABBREVIATION. Read the drivers table: Leroy Smith 12/19, Marcus Crumpton 11/20. That column was headed "Stops E/A", and E/A means ENGINE / ACTUAL. So the engine proposed TWELVE stops for Leroy and ELEVEN for Marcus. The 19 and the 20 are what dispatch actually sent them out with on Jul 28. The engine agrees with you — it is cutting those routes roughly in half. The Routes table above says the same thing from the other side: it lists the routes DISPATCH BUILT and scores how the engine would have re-sequenced them, so DAWSONVILLE\'s 21 stops and CRUMPTON\'s 20 are dispatch\'s numbers, not proposals. Two letters were carrying the entire meaning of that page and they were carrying it badly. The columns now read "Stops eng/disp", "Trips eng/disp", "Lbs eng/disp", and the Routes table says "Stops (dispatch)" outright. SECOND, THE LEGEND. There is now a "How to read this page" panel at the top that says in plain words what the page is (it replays a past day and asks what the engine would have done — it never changes a route), that every paired number is engine first and dispatch second, what the Score actually measures, that a negative Travel Δ is the engine SAVING minutes, what Guided versus Unguided means and why they should be read apart, and what every line and colour on the map is. It remembers whether you have it open. THIRD, THE GREY SHADOW LINES — and this one was a real bug that yesterday\'s change exposed rather than caused. Those are the ORIGINAL route, the one dispatch ran. The reason it looked like four or five bands raking across the whole metro is that a driver\'s stops are numbered 1, 2, 3 within EACH TRIP — so Owusu, who ran two trips, had two stop 1s, two stop 2s and so on, and the map was drawing all of them as ONE line sorted by that number. Trip-one stop, trip-two stop, trip-one stop: a line shuttling between Marietta and the warehouse over and over. It has been doing that the whole time; at 2.5 pixels and half-transparent nobody could see it, and making the line thick enough to be useful is what made it obvious. Dispatch now draws ONE LINE PER TRIP, exactly like the engine side always has. A long leg back across town is now the truck genuinely reloading, not a drawing error. That correction lands on days the engine re-runs — older stored days keep the single line until they are re-scored, rather than breaking.'],
  ['0.54.7', 'THE DIFF TAB NOW ACTUALLY SHOWS YOU TWO ROUTES. Chad, on the Diff tab with Aaron Mitchell pulled up: "need an original line and new line." The legend promised a grey line for what dispatch ran and a coloured line for what the engine wants — and there was only ever one line on the map. HERE IS THE THING: BOTH LINES WERE BEING DRAWN. They had been all along. The problem was how. The original was drawn 2.5 pixels wide at half opacity; the engine\'s line was drawn 4 pixels wide, solid, and ON TOP of it. A thinner, fainter line underneath a thicker, solid one is not faint — it is GONE. And two plans for the same driver agree over most of the route, which is exactly where they sit on top of each other, so the original disappeared along nearly its whole length. The bits that did poke out were a 50%-grey line on a Google basemap, which looks precisely like a road. So the one screen whose entire job is comparing two routes was showing you one route and a legend describing a line you could not find. THE FIX IS WIDTH, and it had to be. Colour loses to whatever is painted on top of it. Opacity loses. Width does not: a wider line underneath a narrower one still shows on both sides of it. So the ORIGINAL route is now drawn as a wide grey sleeve UNDER the engine\'s line. Where the two plans agree, you see the new route running inside a grey casing — that IS the "they agree here" signal, and it is visible at every zoom. Where they diverge, the grey peels away and you see two plainly separate lines going two different places. Neither state is ambiguous and neither line can hide the other any more. The legend now says ORIGINAL · what dispatch ran and NEW · engine, and its little colour chips are drawn at the real thicknesses so the legend matches the map. ONE THING DELIBERATELY NOT DONE: the original is not dashed. On this map a dashed line already means "trip 2 or later", and using dashes for the original would have made a driver\'s second trip impossible to tell from the route they actually ran.'],
  ['0.54.6', 'THE DATE CHANGE THAT "DIDN\'T WRITE" — YOU WERE RIGHT, AND HERE IS WHY IT CAME BACK. Chad: "i changed this to 7/30 and it didn\'t write to nuvizz so it showed up in a new scan." Both halves of that sentence are true, and the second one is the actual bug. CHANGING A DATE IS TWO WRITES, NOT ONE. One goes to NuVizz — the order\'s delivery window. The other is ours: a note on our board saying "this order belongs on the 30th," which every later scan has to honor. That second one is not optional and never has been. NuVizz files orders on our board by its "Estimated Arrival" column, and it does NOT recompute that column when the delivery window moves — so without our own note, the very next scan reads the old arrival and puts the order right back on today. NOW THE CASE YOU HIT. An Estes import the customer deferred to the 30th ALREADY CARRIES the 30th as its delivery window — that is exactly the situation this whole feature was built for, back in 0.54.0. So when you set it to the 30th, the app read the order, saw NuVizz already had the 30th, and correctly decided there was nothing to send. Correct — and then it stopped there and skipped the second write as well. Nothing was recorded on our board, so the next scan filed the order onto today all over again. The one case the board note exists for was the one case it never ran in. Setting a date the order already has now still takes it off your board, and says so: "Order 007… already carries 2026-07-30 in NuVizz — nothing sent there. Taken off today\'s board, and scans will keep honoring the day." It costs the same single lookup it always did; the board half is our own storage and hits NuVizz zero times. A SECOND THING, FOUND WHILE FIXING IT: that board note could FAIL — a storage hiccup — and the card would still tell you "off this board until then" in green, then the order would be back ten minutes later with nothing having warned you. If the note doesn\'t land, the message is now amber and tells you plainly that the next scan will pull the order back and to move it again. The NuVizz half succeeding is never allowed to speak for the board half.'],
  ['0.54.5', 'KAI WONG, PART TWO — THIS TIME IT WAS THE BOARD, NOT YOUR BROWSER. Chad: "kai wong issue fix did not work, still showing on route when it\'s actually unplanned in NuVizz." He was right, and the fact that 0.54.3 did NOT fix it is what identified the real cause. That fix was to a note this app keeps in YOUR BROWSER after a Save. This time the wrong answer was coming from the board itself — the shared one, the same for every dispatcher — so nothing in your browser could have been responsible. HERE IS THE HOLE, AND IT IS A BIG ONE. Every scan reads two saved searches: open orders and finished ones. A stop can briefly match neither — in transit, mid-status-flip — so any stop already on the board that the scan does not return is kept exactly as it was. That is deliberate and it is right; without it a truck would lose stops off its route every few minutes. But it was applied to EVERY absent stop, with no exception and no way to question it. Now: when you UNPLAN a stop in NuVizz, it leaves the planned saved search. The scan stops returning it. So it was absent — and absent meant "keep it exactly as it was", which was PLANNED ON SUW 5. Meanwhile the app already HAS a safety net for exactly this: when the list claims a routed stop is no longer planned, we do not believe it — we go and ask NuVizz about that specific stop before dropping it off a route (that is what protects live routes from a lagging saved search). But that net only ever inspected stops the list actually RETURNED. A stop that vanished was never checked by it. So one half of the scan treated absence as proof the plan was still good, and the other half never got to look. There was no scan that could ever have fixed it. Kai Wong would have sat on Trevor\'s SUW 5 until the board rolled over. THE FIX: a PLANNED stop that disappears from a scan is no longer taken at its word — it now goes through that same check. Nothing is dropped just for being absent. We ask NuVizz: does that load still hold this stop? Only NuVizz answering "no" removes it. If the answer does not come back — read failed, or we are at the call budget for that scan — the stop KEEPS its route, exactly as before. A Save you just made still outranks all of it. Deliveries are excluded outright: a delivered stop is meant to drop off its load, and it must never be turned back into an unplanned order. And if a scan comes back thin — half the board missing, which means the scan failed, not that a hundred stops got unplanned — the whole check switches itself off and every plan carries forward untouched. COSTS NOTHING EXTRA: these checks share the call budget the existing route-protection already had (one load lookup covers a whole route), so a scan cannot spend more NuVizz calls than it could yesterday. ONE THING TO KNOW: this corrects itself on the NEXT SCAN, and orders are paused until 10 AM — so Kai Wong will come off SUW 5 when scanning resumes, not the moment you reload.'],
  ['0.54.4', 'THE DATE CHANGE WAS REAL — THE CARD WAS LYING ABOUT IT. PLUS SKIDS, LOOSE AND A REAL ETA ON ROUTE STOP CARDS. Chad: "Don\'t think that this is actually writing to NuVizz when you change the date. Also these stop cards should have skid and loose counts on them, as well as that time should be reflecting what NuVizz is showing as an ETA." THE DATE, FIRST — IT WAS WRITING. Every time. The write moves the order\'s real delivery window, reads the order back out of NuVizz to confirm the day actually landed, and refuses to report success if so much as one other field on that order moved. What it did NOT do was update the copy of the order sitting in our own cache. Moving the date re-filed the order onto the new day and left the order\'s own window pointing at the old one — and that window is the exact field the "Change delivery date (…)" label reads first. It is also a field the scanner never refreshes: it is filled in once, when an order is first looked up in detail, and carried forward untouched from then on. So the label kept showing the old day forever, through every scan, for an order NuVizz had already moved. Close the card, open it again, and it read like nothing had happened. It now moves with the write — same clock, same window length, and an overnight window keeps its span. A SECOND, SEPARATE BUG IN THE SAME BOX, and this one was worse: if you picked a day the order was ALREADY on, the server correctly answered "already dated the 30th, nothing written" — and the card ignored that answer and told you "Moved to the 30th in NuVizz" anyway. It was reading for that answer in the wrong place, so it never once saw it. It reads it properly now, and a real move now names the day it came FROM, straight off the server\'s read-back of the order: "Moved 2026-07-29 → 2026-07-30 in NuVizz." That sentence is evidence, not an echo of what you typed. THE STOP CARDS ON A ROUTE. Two changes. (1) Every stop now shows its skid and loose count under the PRO — the same two numbers as the Compare panel, from the same NuVizz fields. A stop we have no freight numbers for yet shows nothing rather than "0 sk", because an order nobody has looked up in detail is unknown, not empty. (2) THE TIME. Six stops on TRAILER 7 all read 8:00 AM, and no route ever runs like that. That was not an ETA. There are two different things in NuVizz that arrive under one name here: the real per-stop ETA off the route, and the saved search\'s "Estimated Arrival" column — which is a generic window every stop on the load shares. Orders we have looked up in detail carry the real ETA; everything else carries the window, and the card was printing whichever it found first, as a clock, with no way to tell them apart. The card now reads the real ETA only from where the real ETA lives. When NuVizz has one you get "ETA 2:35 PM". When it does not — nothing is dispatched yet, so no ETA exists — you still get the appointment, but labelled "appt 8:00 AM", so a window can never be read as an arrival prediction again. Delivered and arrived stops are unchanged: they show their actual stamped time.'],
  ['0.54.3', 'A PLAN YOU UNDID IN NUVIZZ NO LONGER STICKS TO THE LOAD ON YOUR SCREEN. Chad: "I just did a fresh scan, why is Kai Wong showing up on Trevor\'s load, it is unplanned status in NuVizz." Here is what was happening, and it was only happening on HIS screen. When a Save is confirmed, this app writes that plan down locally — which stop, which load, which driver — and paints it over the board until a scan comes back agreeing with it. That is deliberate and it is a good thing: it is what stops a route you just watched save from looking unbuilt while NuVizz catches up. The flaw was in what counts as "agreeing". A stop recorded as planned onto SUW 5 only agreed with a board row that showed it planned on SUW 5. So when the stop came back UNPLANNED — the honest answer, because it had been unplanned in the portal — the app read that as "the scan is behind" and painted it right back onto SUW 5. That is the one thing the paint exists to do, so it kept doing it, through every fresh scan, for up to twelve hours. And because the note lives only in your browser, no other dispatcher saw the contradiction — and a build run off that board would have planned against a stop the load does not hold. THE FIX: a scan that ran AFTER your save has, by definition, seen the world after your save — so its answer is a verdict, not lag, and it now wins. Scans that merely overlapped your save do not count, since one can finish just after a save while having read NuVizz just before. Nothing was loosened: the server still refuses to un-plan a stop on the saved-search list\'s word alone (it goes and asks NuVizz about that specific stop first), and the overnight case that the twelve hours existed for is untouched — with the scanner paused, no scan ever passes your save, so a confirmed carry-over still holds until morning. Nine tests cover it, Kai Wong\'s case included.'],
  ['0.54.2', 'CLICK A ROUTE LINE ON THE MAP TO PULL UP THE ROUTE. Chad: "I want to be able to click on these route lines and it pull up the route." With Show routes on you get a coloured line per load, and until now they were decoration — the only way to open one was to find it in the Routes list on the right. Click any line now and that route opens: on the Map screen it opens in the route panel and frames it, on Routing it opens as a Compare card. Same gesture on both maps. THE PART THAT MAKES IT USABLE: those lines are drawn 2.5 to 3 pixels wide, and a 3-pixel diagonal is a genuinely bad thing to ask anyone to hit with a mouse — worse for the faded lines, which are drawn at a quarter opacity when another route is already open. So the click target is not the line you see; it is a 16-pixel-wide invisible line running the same path. You aim near the route and it opens. Hovering shows a pointer and thickens the line so you can tell what you are about to open before you commit. Two things deliberately still work exactly as before: clicking a STOP that happens to sit on top of a line opens the stop, not the route (pins always win), and dragging the map across a line still pans instead of opening anything.'],
  ['0.54.1', 'THE STOP COUNT ON THE ROUTING MAP NOW COUNTS THE DOTS YOU CAN SEE. Chad: "why are there more dots on the map than on the bottom panel, they should match." The chip in the corner of the routing map said "833 stops" — and that was the WHOLE day\'s board, counted before anything was hidden. The map underneath it was drawing a filtered subset, because your bottom grid had a status filter on (Un-Planned) and the map follows that filter on purpose. So the number and the pins under it were describing two different things, and neither of them matched the grid. The chip now reads "15 of 833 stops" whenever a grid filter is hiding stops, with the first number in amber, and hovering it explains what is hidden. TWO THINGS THAT ARE WORKING AS INTENDED and are worth knowing, because they are why the counts still will not be identical. FIRST, a route you have pulled up in Compare always draws in full — those nine numbered SUW 4 pins stay on the map no matter what the status filter says, because a route losing members mid-view while you are working it is far worse than an extra pin. Anything you have selected is exempt for the same reason: a hidden stop could otherwise ride into a build unseen. SECOND, the bottom grid and the map are not looking at the same days. The grid was set to "Last 7 days" (4,264 stops); the map shows the one board day you have picked, plus any unplanned orders from the grid\'s window so you can actually select and plan them. Different date ranges, so different counts — by design.'],
  ['0.54.0', 'CHANGE AN ORDER\'S DELIVERY DATE FROM THE STOP CARD. An Estes import the customer didn\'t want until the 30th sat in the 29th board and let itself be planned. WHY, exactly: the board files every order by the "Estimated Arrival" column on the saved search — and NuVizz does not fill that in for an order nobody has routed yet. An order with no arrival is filed on TODAY, by design (it is how re-delivery duplicates with no dates at all stay visible instead of vanishing). The DropOff date the portal shows, the one field that said the 30th, is not in the feed we scan at all, so nothing in the pipeline could have known. The stop card now has "Change delivery date". Pick a day, Send, and three things happen: the order\'s delivery window moves in NuVizz — the real field, the one the portal and the driver read, with the appointment TIME kept exactly as it was — the order leaves today\'s board immediately rather than at the next scan, and the day you chose is remembered so every future scan keeps honoring it. That last part is not optional: NuVizz will go on reporting the old arrival forever, so without it the order would be back on your board ten minutes later and the whole thing would look broken. Safety is the same as the note box, because it is the same machinery: it reads the order, moves only the window, reads it back, and if ANY other field on that order moved — or the freight lines or the BOL went missing — it refuses to call it a success and tells you to check the portal. It will not touch an order the driver is already running, and if the order is already built into a route it says which one before you send, since moving the date leaves it on a truck running a different day. An order already on the day you picked costs one call and writes nothing.'],
  ['0.53.11', 'AN EMPTY BOARD NOW TELLS YOU WHY IT IS EMPTY. Chad sent a grid reading "No stops match." with 64 loads sitting right next to it and asked why his board showed no deliveries. Two separate things were making that message lie. FIRST, IT WAS STILL LOADING. The header said "pulling…" while the table underneath had already announced "No stops match." — the grid stating a conclusion it did not have yet. Pulling a week-long window takes a few seconds, and for those seconds the board looked broken. It now says "Pulling this window…" with a spinner until the answer actually arrives. SECOND, AND THIS IS THE REAL ONE: the Status filter was on (the bar showed "Status (1)"), and for a date window that filter is sent along with the request — the pull itself only asks for that one status. So when the chosen status has nothing in the window, ZERO rows come back, and the grid\'s "N stops exist but a filter is hiding them — [Clear filters]" message could not fire, because from where it was standing no stops existed at all. You got the bare "No stops match." with nothing naming the filter and no button to clear it. That is exactly the silent-blank trap closed back in v0.45.6, quietly reopened through the server side. An empty grid with any filter on now names the filter, explains that a status filter is applied to the pull itself, and gives you the same one-click Clear. No filter can blank your board without saying so.'],
  ['0.53.10', 'THE BOTTOM BAR STOPS HIDING ITS OWN BUTTONS. Chad: "I can\'t see my drivers or stops buttons anymore and they are more important." The window picker read "Last 7 days · board day", and a dropdown is always as wide as its longest line — so that one label was the widest thing on the bar, and everything it pushed past the right edge simply vanished. It now reads "Last 7 days" and "Last 14 days". Nothing about how they work changed: both still count back from the board date you have selected, exactly as before. The deeper fix is that the bar now WRAPS. It has gained a control at a time — the status percentages, Profiles, the no-location chip, the window, the driver filter, the gear — and until now a bar that ran out of room pushed the leftovers off the end, where they were not just invisible but unreachable, with no scroll and no hint they existed. When the room runs out it now takes a second line instead. Stops/Loads and the driver filter additionally hold their width no matter what else is on the bar, because they are the two you reach for most.'],
  ['0.53.9', 'LOOSE COUNT PER STOP + THE REST OF THE MANIFEST STORY. (1) LOOSE ON EVERY STOP. A route card totalled "26 sk · 21 loose" but there was no way to tell WHICH stops carried the loose pieces. Each stop row now reads e.g. "MARIETTA · 2 sk · 3 loose", and expanding a stop shows lb · sk · loose · pcs together — those cross-check each other, since skids plus loose should equal total pieces. Loose only shows on the collapsed row when a stop actually has some, so the rows that do have loose are the ones that stand out. (2) THE OTHER HALF OF YESTERDAY\'S MANIFEST BUG. The inch-mark fix was real, but it was not the whole story. The reader\'s answer has a size limit, and that limit covers its THINKING as well as the orders it writes out. When the reader was upgraded to a newer AI model back in v0.50.77, that model started thinking by default where the previous one had not — quietly drawing from the exact same budget the orders had to fit inside. So a manifest nowhere near the nominal limit could still run out of room and stop mid-order. The budget is now sized to cover thinking AND a manifest several times larger than anything Estes sends (roughly 200 orders), and it is set for the way we make the request rather than pushed as high as it will go. For the record, since it comes up: the reader can take a PDF up to 600 pages and 32 MB — your manifests are 4 to 8 pages and a few hundred KB, so 50 orders in one PDF is not close to any limit that exists.'],
  ['0.53.8', 'BULK ADD — ONE INCH MARK WAS THROWING AWAY A WHOLE MANIFEST. Chad dropped two Estes manifests together and got "The reader returned no usable JSON — try the drop again." Dropping it again did nothing, and it never would have: THE FAILURE IS THE SAME EVERY TIME. Here is what actually happened. Manifest 047-54026\'s very first consignee, DELMAR GARDENS OF GWINNETT, has a description reading TEM130BKWY 20" WIDE ELECTRIC COIL R. That quote mark after the 20 is an inch symbol — and in the data format the reader answers in, a bare quote mark ENDS the text. One character in one description made the entire answer unreadable, so all 24 orders on that manifest were dropped on the floor and you were told to try again. FOUR FIXES, none of them a retry. (1) A stray quote mark inside a description is now repaired automatically and the orders come through — with a warning telling you the file needed fixing, because a repaired read is exactly where a missing order would hide. (2) The reader had a hard ceiling on how much it could write back, and a long manifest could hit it and stop MID-ROW — the same "no usable JSON" for a totally different reason. The ceiling is now five times higher, the reader is asked to write compactly (about half the size), and if it ever does get cut off, the orders that DID arrive are kept instead of the whole file being binned. (3) MISSING ORDERS NOW SHOUT. Every Estes manifest prints its own "Total Pros" count. If we read 31 of 37, that used to be one line in a long amber warning strip. It is now a RED box at the top of the intake: "Orders are missing — do not push until you have checked the paper," naming the file and the exact shortfall. (4) The instructions we send the reader used to illustrate the format with the REAL numbers off an old manifest (047-52228, trailer 521104). A reader that cannot make out a blurry header has an obvious out there: copy the example. Those are now obvious dummy values, and if one is ever echoed back it is thrown away and flagged instead of landing as a real-looking manifest number. Also: when a read does fail, we now keep what the reader actually said so it can be diagnosed, instead of a dead-end "try again". Zero NuVizz calls, as always.'],
  ['0.53.7', 'COMPARE PANEL: LOCKED TO LIVE, LOCKED TO RWB. Chad, on the Compare header: "same here lock it into live and rwb don\'t need the other options classic and import." Both done. (1) LIVE. The ○ Beta / ● LIVE switch reset to Beta on every mount, so a real Save meant flipping it again each session — the same ritual the Routes panel just lost in 0.53.6. It now starts on ● LIVE and remembers what you last set, per device. Say it plainly, because there is no second gate behind it: in Live, pressing Save SENDS to NuVizz, immediately, with no confirm popup (that popup was removed a while back on purpose). The button is still there — click to ○ Beta and a Save just simulates ("nothing sent, N loads simulated"), and that sticks too. (2) RWB ONLY. The engine button no longer cycles ⚙ Classic → ⚡ Import → 🔗 RWB; RWB is simply what a Save runs, and the header now shows 🔗 RWB as a plain badge instead of a picker. RWB is the right one to keep: it is the only engine that references stops BY ID ONLY, so a Save physically cannot blank or clone freight and address data — that is the failure class behind the Jul 2 Import incident — and it commits in 2 synchronous calls per load rather than Import\'s async wait-and-poll or Classic\'s remove-and-reinsert ladder. Nothing about the safety net changed: the SERVER still has the final say, and if the RWB switch is ever turned off there, a Save quietly falls back to the classic path on its own instead of failing. Your old engine choice stored on this device is simply ignored from now on.'],
  ['0.53.6', 'THE ROUTES PANEL STAYS LIVE — NO MORE FLIPPING OFF BETA EVERY TIME. Chad, on the Routes roster: "want to turn the beta off here and it to be live all the time." The ○ Beta / ● LIVE switch beside the route search reset to Beta on EVERY page load, so assigning a driver for real meant flipping it again each session — and a safety switch you always flip is one you stop reading, which is worse than not having it. It now starts on ● LIVE and remembers whatever you last set, per device. That is not a new door opened: this whole row only appears once "Live dispatch (assign driver + dispatch)" is switched on in the ⚙ gear, which is already a deliberate, remembered choice — the panel was just asking you to make the same decision twice. WHAT LIVE MEANS, plainly: picking a driver from a route card\'s dropdown assigns that driver to that load in NuVizz immediately, and the dispatch button dispatches it, both with no second confirm. That was always true in Live mode; it is now the mode you land in. The button is still there and still red when hot — click it to ○ Beta any time and picks go back to preview-only ("would assign X, nothing sent"), and THAT sticks too. Untouched on purpose: the Compare/route-card Save toggle still starts in Beta, because that one fires a batch of route writes at once rather than a single pick — say the word if you want it to match.'],
  ['0.53.5', 'THE STATUS CARD NOW TELLS YOU HOW MANY UNPLANNED STOPS THE LAST SCAN FOUND. Chad: "I want a row that shows how many unplanned deliveries were in the last scan so I know how many stops I should have on the bottom panel." The card showed the total stop count, the pallets, the feed times and the call meter — but nothing you could hold the stops list up against. A new row reads "612 unplanned in last scan". That number is counted over the WHOLE feed the scan produced, carry-over from prior days folded in, before a single map filter or search touches it — so it is the ceiling: the list can show that many or fewer, never more. And when it IS fewer, the row says so rather than leaving you to subtract: "612 unplanned in last scan · 24 hidden by filters" in amber, which is usually Unplanned only, Hide terminal, Hide stem out or a carry-over window doing exactly what you set it to. The count was already being calculated on the server and thrown away by the app, so this costs ZERO extra NuVizz calls and zero extra reads — it rides the board feed you were already getting. It shows on the phone, on desktop, and on the Routing pill (Routing shows the whole board, so it never reports a filter gap). On an older cached feed that doesn\'t carry the number, the row simply doesn\'t appear rather than claiming zero.'],
  ['0.53.4', 'THE LIME "TRACTOR DELIVERED" PAINT CAN NO LONGER FAIL SILENTLY. Chad sent a phone screenshot of a 707-stop board: "my stops aren\'t painted tractor trailer friendly like a lot of them should be — either a render fail or automatic painting fail." Reading the actual pixels settled half of it: every green pin on that board was the DISPATCHER-SET green you paint by hand, and there was not a single pixel of the lime automatic green anywhere on the map. So the lime layer was serving nothing at all. It was NOT a mismatch between the map and the saved locations — the customer notes on those same pins load through the exact same customer key, and the restriction icons and your hand-painted greens all came through fine on that render. Which leaves three things that all look identical on the map (nothing lime) and that the app gave you no way to tell apart: the paint switched OFF on that device, the read of the saved locations failing, or there being no saved locations to read. Three changes. FIRST, the Tractor delivered box in the Legend now says which one it is — "1,284 saved locations loaded", or "0 saved locations — nothing to paint yet", or "couldn\'t load" with a Retry. Loaded a number but no lime on the map is a paint bug; loaded zero is the nightly pass, not the map. SECOND, that box now exists ON THE PHONE, under Filters → Map display. The Legend that holds it has only ever rendered on desktop, so if the switch was off on your phone there was nothing on that screen to show it, let alone turn it back on. THIRD, a failed load now heals itself: it retries twice on its own and offers a Retry button, where before one hiccup as the page opened blanked every lime pin, the stop-panel line, and the green rows for the rest of the session with no way back but a full reload.'],
  ['0.53.3', 'NOTES WORK AGAIN — THE WARNING WAS ABOUT THE ORDER\'S FILES. Two real notes, two orders (007152089 and 007150559), same red message: "the note landed BUT partialUpdate changed 1 other field(s) on the order." Both times the field was the order\'s attached files, and thanks to the 0.52.4 fix printing the values we could finally see WHAT changed: the same BOL, same name, same type, same pdf — carrying a different internal id. Nothing was lost. NuVizz simply hands its own file rows a new id when the order is written. Two changes. FIRST, notes no longer send the file list at all. When we read an order back, NuVizz gives us the file rows as labels with no file in them (the documents themselves live behind a different NuVizz service), so sending them back can only be ignored — or worse, re-create the row from an empty payload. The portal traffic this write was copied from had no attachments on its order, so including them was a guess, and it was the only thing that has ever moved. Freight lines already stayed off the wire for the same reason; the files now join them. SECOND, and this is the part that matters: the safety check no longer just goes quiet about what it stopped sending. It now compares the order BEFORE the note against the order AFTER it, and if a document or a freight line went missing it fails just as loudly as before — naming the document that vanished. A note can still never quietly cost you a BOL. What changed is that an id being reshuffled is no longer reported as though it had. Still 3 NuVizz calls per note, still read-merge-verify, and a clean note now says "Note added in NuVizz." and nothing else.'],
  ['0.53.2', 'THE APP NOW TELLS YOU WHEN IT IS OUT OF DATE. Chad, on a stop card: "No where to put notes on this order on desktop." The note box was there — it shipped four days earlier in v0.52.0, and the live site was serving it correctly. His BROWSER TAB was still running the code it downloaded on July 23. A dispatch console gets left open for days, and a single-page app never re-fetches its own JavaScript, so shipping a fix does not put it on your screen — you have to reload, and nothing ever told you to. Every fix from v0.51 through v0.53.1 was invisible on that tab: writing notes to NuVizz orders, the failure reasons, shared profiles, the planned-stop pins. A blue bar now appears across the top the moment a newer version is deployed — "A newer version of Dispatch Map is available" with a Reload button. It checks when the tab regains focus (the usual case: a deploy landed while you were in NuVizz) and every three minutes otherwise, costing about a kilobyte a check. It will NOT reload on its own — you could be mid-plan with unsaved route cards — and it cannot be dismissed, because a dismissed banner is exactly how a tab ends up four days stale. It can never appear wrongly: it compares the fingerprint of the code the page is running against the fingerprint the site is serving, so it only fires when the code genuinely changed, and stays silent when offline.'],
  ['0.53.1', 'PLANNED STOPS NOW LOOK PLANNED ON THE ROUTING MAP. Chad saved a 13-stop MITCHELL route, closed the card, and every one of those stops went straight back to looking like the unplanned pool around it — impossible to tell what was still to route. The board was right all along (all 13 read planned, on MITCHELL, in sequence); the PIN was the problem. A planned stop had no colour of its own, so it fell through to the truck-eligibility colour, or to the default blue — and when the customer has restriction notes, to a purple a shade off the unplanned purple. At pin size that is the same dot. Planned stops now draw as a quiet hollow slate ring, so what stands out on the map is what still needs a truck. Deliberate exceptions, because these are the ones you need to see: stops already moving keep their live colours (out for delivery, arrived, delivered, exception), and a do-not-send stop, anything you have selected, a search hit, and every stop on an open route card all look exactly as before. Closing a route card is now the moment its stops go from numbered-in-route-colour to quiet slate — never back to looking unrouted.'],
  ['0.53.0', 'SAVED PROFILES NOW FOLLOW YOU TO EVERY DEVICE. Bottom-bar profiles were stored in the browser, so a profile saved on the desktop didn\'t exist on the phone, and the other dispatcher never saw it at all (Chad: "they shouldn\'t be local to the device, should be across all devices"). The list is now shared: save one anywhere and it appears everywhere within a second or two, on every device and for everyone — same for Update and Delete. Two details worth knowing. (1) The profile you have SELECTED stays yours: picking "Tomorrow AM" here doesn\'t yank someone else\'s grid out from under them mid-plan. (2) Deleting a profile now deletes it for everybody, not just on your screen. Profiles you\'d already saved on this device are carried up automatically the first time it connects, so nothing is lost. If the shared store is unreachable the bar keeps working exactly as before, off the copy held on the device, and syncs up when it reconnects.'],
  ['0.52.4', 'NOTE WARNINGS NOW SHOW WHAT ACTUALLY CHANGED. The first real note write (order 007152089) worked — the note landed — but the safety check reported "partialUpdate changed 1 other field(s) on the order (to.documents)" and stopped there. That names the field and nothing else, and "the document list changed" covers both NuVizz harmlessly re-stamping an internal id on the BOL AND the BOL being knocked off the order. Same warning, opposite severity, no way to tell which. The warning now prints the before and after for every field that moved — e.g. to.documents: [{"documentGuid":"abc"…}] → [{"documentGuid":"xyz"…}] — so you can see at a glance whether something real was lost or an id was reshuffled. Values are truncated so the message stays readable, and it shows up to five changed fields before summarising the rest. Nothing about how notes are written changed; this is the warning explaining itself.'],
  ['0.52.3', 'NOTES TO NUVIZZ NOW ACTUALLY SEND. The 0.52.2 fix made the note box report NuVizz\'s real answer, and the answer was: "SOMETHING WENT WRONG!!, PLEASE TRY AGAIN". Cause: NuVizz\'s update endpoint is called "partialUpdate" but it is NOT partial. We were sending the smallest, safest possible payload — the order number and the notes, nothing else — precisely so no other field could be touched. NuVizz rejects that outright. Comparing against the portal\'s own traffic: when you add a note in NuVizz, it sends the ENTIRE order back with the notes swapped in. So we do the same — we read the order, swap in the note list, and send the order back exactly as we read it. Two rules keep that safe: the freight lines are never included (NuVizz maintains those through a separate endpoint, and a note has no business touching them), and no value is ever invented — every field we send is a value we just read off the order. Because a note now rewrites the whole order rather than one field, the safety check after the write was widened to match: instead of spot-checking about 20 important fields, it now compares EVERY field it sent against what came back, and if anything at all moved it tells you loudly and says not to use notes again until it\'s looked at. Same 3 NuVizz calls per note.'],
  ['0.52.2', 'FAILED WRITES NOW TELL YOU WHY. Chad\'s "Add note in NuVizz" on mobile failed with just "Could not add the note." — no reason, nothing to act on. The server had actually built a precise explanation ("could not read the order — nothing was written", "NuVizz rejected the note", "the note landed BUT the update changed 2 other fields — check the order in the portal") and then threw it away at the last step: the response said the write failed without saying why. Every write now carries its reason at the top level, so the note box — and every other Save banner in the app — repeats the server\'s own words instead of a generic message. Multi-load Saves summarise the first few per-load reasons rather than reporting a bare failure. A failure can no longer come back with no explanation at all. Nothing about WHAT gets written changed; this is purely about being told what happened.'],
  ['0.52.1', 'ROUTE WORKBENCH — three defects found in a review of the Compare cards, all fixed. (1) A STOP WITH NO MAP LOCATION COULD LOCK A LOAD OUT OF SAVING. Cards were built from the map\'s pin list, so a stop that hadn\'t geocoded (or never will — a bad address) was simply absent from the card; Save then sent the load one stop short, and the safety guard correctly refused it ("stop(s) the board isn\'t showing … Refresh and retry"). Refreshing could never fix it — a stop with no geocode never joins the pin list — so that load was unsaveable with no way out. Cards are now built from the BOARD, so the stop rides along: shown, counted in the freight totals, printed on the manifest and included in the Save, flagged as "no map location" (it just can\'t be drawn or auto-sequenced until the address is fixed). (2) UNDO NOW PUTS THE STOP BACK WHERE IT WAS. Removing stop #2 of 10 and immediately undoing left it at #10 — so a slip of the mouse silently RESEQUENCED the real load in NuVizz on the next Save. Undo restores the original position, which also means undoing every removal leaves the card genuinely clean instead of holding a phantom reorder. (3) NO MORE SILENT DROPS. If a staged stop left the board (delivered, cancelled, reconsigned elsewhere), the card just stopped showing it while still sending it on Save — the card under-reported its own stop count, freight and manifest. Those now appear as a flagged row ("not on today\'s board — still saved") with an ✕ to drop them deliberately, and printing a manifest that can\'t include one says so out loud.'],
  ['0.52.0', 'WRITE NOTES TO NUVIZZ ORDERS. The stop card now has "Add note in NuVizz" — type an instruction, choose who sees it (Dispatcher, Driver, or both), Send. It lands on the real order in NuVizz, showing up in the portal\'s Dispatcher/Driver Instruction panels and on the driver\'s device, exactly like a note typed in the portal. Until now the app could only READ those instructions. IMPORTANT SAFETY DETAIL: NuVizz replaces an order\'s ENTIRE note list on this API, so a naive write would erase the carrier\'s own instructions ("DO NOT BREAKDOWN SKID", "INSIDE DELIVERY"). Every note is therefore written by reading the order first, adding yours to what\'s already there, and then re-reading to confirm the note landed AND that nothing else on the order changed — if anything else moved, it tells you loudly instead of claiming success. Re-sending the same note is a no-op instead of a duplicate. 3 NuVizz calls per note; nothing fires until you press Send.'],
  ['0.51.1', 'HOTFIX — manifest/paste reads broken by the 0.50.77 model upgrade. The new AI model rejects a legacy request setting (temperature) the reader still sent, so every manifest PDF drop and pasted-rows read failed with "anthropic_400: temperature is deprecated". The setting is removed (harmless on every model, old or new); reads work again immediately after this deploys.'],
  ['0.51.0', 'TWO DISPATCHERS, ONE BOARD + MULTI-PDF DROP. (1) Multi-user presence: with two people in the dispatch map at once you now SEE each other — a chip in the header shows who else is on (click it to set your name), and the stops the other device is STAGING on its Compare cards are claimed live: the selection tools (click, box, lasso, Ninja, Send) skip them with a "being staged by <name> on another device" note, a colliding Save warns before it fires, and a Save on either device silently re-reads the other\'s board within seconds (no more waiting out the 2-minute poll to see each other\'s work — and no more both planning the same order onto two different loads). All Firestore-only, zero NuVizz calls, and totally fail-soft: if presence is unavailable the app behaves exactly as before. (2) Bulk Add: the drop zone now takes SEVERAL files at once — drop 2 (or more) manifest PDFs together and each is read in turn (progress shows "file 1 of 2"), all landing in the same Manifest Intake list deduped as always. The file picker allows multi-select too. One spreadsheet per drop still (the column-mapper is one-at-a-time); extra non-PDFs are skipped with a note.'],
  ['0.50.77', 'MANIFEST READER upgraded to a newer, stronger AI model (Claude Sonnet 5, up from Sonnet 4.6). Fax-quality scans — where a smudged PRO digit or a cramped address line is easy to misread — should come back more accurately. Nothing changes in how you use it: drop the PDF, review the grid, Create. Still zero NuVizz calls; the model is env-configurable so it can be tuned without a code change.'],
  ['0.50.76', 'DAY STATUS BREAKDOWN on the bottom-grid header. The Stops/Loads bar now shows what percentage of the SELECTED DAY\'s board is in each status — e.g. "Planned 62% · Unplanned 28% · Out 4% · Delivered 6%" — right next to the Stops/Loads count (Chad\'s ask: a percentage breakdown of the planned stops for the day). It\'s computed over the WHOLE day, so it stays a steady progress read while you search or filter the list (it doesn\'t follow the filtered rows). Same status buckets as the Status filter, zero-count statuses hidden, and the hover tooltip gives the raw counts. Reflects whichever day/window the bar is set to. Desktop bottom grid on both the Map and Routing screens.'],
  ['0.50.75', 'MANIFEST INTAKE — the consignee column now shows the FULL address. Each order row displays the street line (address + suite) between the consignee name and the city/state/ZIP, in both the intake grid and the Pushed-to-NuVizz log, so you can sanity-check where an order is going without expanding the row. (Expanding ▸ still opens the full editor.)'],
  ['0.50.74', 'MOBILE ROUTING — you can now SEE your selection. Tapping the "N selected" badge (or Setup) on the mobile Build screen opens a "Selected stops (N)" section: the same stacked stop cards the desktop right-rail Stops tab has — customer, city, skids · loose · pcs · weight, restriction icons, remove ✕, sortable by any column, tap a card for its detail. Chad\'s report: 36 stops lassoed and "no way to see the 36 I have selected" — the mobile Setup sheet only showed build controls; the selection list existed on desktop only. The section is collapsible and starts open while composing a selection (collapsed once a build workbench is active, so route cards aren\'t buried). Live counts in the header: Selected stops (36) · 77 sk · 80 pcs.'],
  ['0.50.73', 'STOP HISTORY — "Recent deliveries here" now ALWAYS shows on the stop card, mobile included. The section (past PROs with the driver who ran each and the date) was already shared by desktop and mobile, but it hid itself completely when a customer had no saved history — so on a first-visit customer (Chad\'s MODEL ROUNDUP) the mobile card looked like the feature didn\'t exist. It now says "No prior deliveries recorded — first visit to this customer" instead of vanishing. Lookup is also stronger: it resolves the customer by the stop\'s exact matchKey first (one direct read — immune to business-name variants the name search can miss), with the name search kept as fallback. Firestore-only, zero NuVizz calls, session-cached as before.'],
  ['0.50.72', 'SAVE GUARD — removing an already-executed stop now refuses UP FRONT. The AVRT case (7/22): a stop the driver had already been dispatched on / arrived at survives a Save-removal — NuVizz answers SUCCESS but silently keeps the stop, and the app could only tell you AFTER the save (the "NuVizz KEPT stop" banner) at the cost of a wasted write + repair. The Save now checks each removed stop\'s execution status on the pre-save load read (zero extra NuVizz calls) and refuses immediately with the exact remedy: "stop X is already DISPATCHED — reopen + unplan it in the portal first." Covers explicit removals and the source side of a staged move. Fails open: an unknown status never blocks, and the post-save verify still has the final word.'],
  ['0.50.71', 'ROUTING MAP — the Status filter now filters the MAP, not just the grid. Checking "Planned" (or any status/driver filter in the bottom grid) hides every non-matching pin on the Routing map, so the map and the grid finally show the same stops (Chad: "should only be showing planned"). Safety exemptions: stops you have SELECTED and stops on a shown route stay visible even when filtered out — a selection can never ride invisibly into a build, and a route\'s numbered pins never lose members. Search is unchanged (burnt-orange highlight, never hides). Clearing the filter restores every pin.'],
  ['0.50.70', 'MANIFEST READER — high-resolution scans now work (the real fix). Chad\'s Manifest_04753105 (5 pages, 3.9 MB — a heavy fax scan) still failed: the 0.50.69 page-splitting fix couldn\'t help because at ~1 MB PER PAGE even a single page was over the reader\'s ~256 KB request cap. The PDF now rides AROUND that cap: a big file is uploaded in ~700 KB parts to our own store (with a per-part retry), and the reader reassembles it and reads the WHOLE manifest in one pass — one AI call, no splitting, no quality loss. Handles scans up to ~16 MB; the reader also gets more time (up to 5 min) for heavy scans and the app waits accordingly. Small manifests are unchanged.'],
  ['0.50.69', 'BIG MANIFEST PDFs now read automatically. The manifest reader’s request has a hard ~256 KB size cap (a platform limit on the background job), so a scanned manifest a page or two longer than usual failed with “too large — split it yourself.” It now splits the PDF into page groups that each fit, reads each group, and merges the rows back into one intake — no manual splitting. A truly huge single page still can’t be split and gives a clear message; everything else just works.'],
  ['0.50.66', 'CALL-COUNT FIX — the reconsignment check was quietly leaking /stop/info calls. The address-change detector (added in 0.50.48) compared the cheap saved-search list address against the address stored from a prior /stop/info pull. Those come from two different NuVizz endpoints and can format the same address slightly differently (a leading suite number, a padded ZIP), so for those stops it looked like the address changed on EVERY scan and re-pulled the order each time — never settling. Now it compares the list address to the LAST LIST address we saw for that stop (same source, same format), so it only re-pulls on a REAL reconsignment and then stops. Real address changes are still caught; the per-scan call bleed is gone.'],
  ['0.50.65', 'VIEWING A ROUTE now always shows that driver\'s stops on the map \u2014 even with a board filter on. Before, if you had a filter active (e.g. "unplanned only") and opened a driver\'s load, the map framed an EMPTY area because the route\'s planned stops were being hidden by the filter. Now, whenever a route is open, its stops are always drawn (numbered, full-color) regardless of the active filters, while everything else still dims as usual. Applies to both desktop and mobile.'],
  ['0.50.64', 'MOBILE \u2014 "View on map" from an open route. When you open a route on your phone (Loads \u2192 a route), the stop list is a full-screen sheet that covers the map, so you couldn\'t see the route laid out. There\'s now a blue "View on map" button at the top of that route sheet: tap it and the sheet minimizes to a slim bar at the bottom, revealing the map framed on that route with its stops numbered in delivery order. Tap any pin to open that stop; tap "Stops" on the bar to bring the full list back, or \u2715 to close the route. Desktop is unchanged (the route list already sits beside the map there).'],
  ['0.50.63', 'ENGINE (shadow \u00b7 Assignment) \u2014 the LAST far-corner straggler dies. After v0.50.61 the engine used barely half the far trucks dispatch does (11.6 vs 20.3 a day) \u2014 but one 1-stop truck still tagged along to the NW corner, because the \u201cextra truck in a far area\u201d charge grouped stops by tiny ~5-km cells: a lone stop sat in its own cell, looked \u201cperfectly cohesive\u201d, and its truck was never charged. The charge now works at the AREA level \u2014 the same \u201cDalton\u201d-sized grain the territory-ownership rules use \u2014 so an isolated stop a few miles from the owner\'s loop belongs to that area\'s math and folds onto the owner\'s truck. Engine 2.4.1; full history re-scored.'],
  ['0.50.62', 'ENGINE TAB \u2014 live tuning, no more deploys. New \u2699 Tuning button on the Engine tab opens the engine\'s live settings: the far-route/territory knobs (far threshold, extra-truck-in-a-far-area cost, territory ownership, usual-driver pull out far, ownership floors) each with a plain-English explanation, plus every other engine setting under Advanced. Edits save to the cloud, are clamped to safe ranges (a bad value can\'t stick), show a \u201ccustomized\u201d badge with one-tap reset to default, and take effect on tonight\'s run automatically. A \u201cRe-score history\u201d button re-runs all past days with the current settings in the background (zero NuVizz) so you can see the effect on the charts in minutes instead of waiting for nights to accumulate.'],
  ['0.50.61', 'ENGINE (shadow \u00b7 Assignment) \u2014 Chad\'s rule, encoded: THE ENDS OF THE ROADS GET THE FEWEST TRUCKS POSSIBLE. The last stragglers were single-stop trucks tagging along to the far corners (one extra truck carrying ONE Dalton-area stop that Scott should have taken) \u2014 they survived because the flat penalty for a spare far truck roughly tied with the cost of folding its stop onto the owner. The penalty for an extra truck in a far zone now GROWS with how far out the zone is (a second truck 60 miles out costs more than one 46 miles out, and 90 miles out costs more still), and its base weight doubled \u2014 so the trade always resolves toward fewer trucks at the edge. Verified: the one-stop straggler case now folds onto the zone owner even when it pushes the owner\'s load past their usual single-trip weight. Engine 2.4.0; full history re-scored. Shadow only, zero NuVizz.'],
  ['0.50.60', 'ENGINE (shadow · Assignment) — the territory rules now actually fire. The v0.50.59 re-score came back suspiciously unchanged in the NW corner, and honest digging found why: the engine classified a stop as "far" using NuVizz\'s stopDistance field, which turns out to be the distance from the PREVIOUS stop — a Dalton stop is 3 miles from the previous Dalton stop, not 60 from Buford — so nearly every far stop failed the "is this far?" test and the territory-ownership, far-habit-discount, and zone-cohesion rules silently skipped exactly the stops they were built for. The engine now computes true distance-from-depot itself for every stop (with a test pinning it so this can never quietly regress). Engine 2.3.1; full history re-scored with the Dalton/Chatsworth ownership rules genuinely active for the first time.'],
  ['0.50.59', 'ENGINE (shadow · Assignment) — the engine now KNOWS whose territory Dalton is. v0.50.58 taught it that extra trucks to a far corner are expensive; this release teaches it the thing Chad actually said: "Scott and Victor handle Dalton and Chatsworth almost exclusively — it should never be split 4 ways." Verified in the history first (Scott 54% + Victor 28% + Che 15% = 97% of every NW-corner stop ever), then made it a learned rule: the engine mines each far area\'s OWNERS from route history (any driver carrying ≥10% of that area\'s stops, min 25 observed) and giving one of its stops to anyone else now costs more than any other single pull in the objective. Areas served by everybody (metro Atlanta) never concentrate enough to form an owner set, so they stay flexible — the Dalton-vs-Atlanta distinction is learned from data, not hardcoded. Engine 2.3.0; the whole history was re-scored. Shadow only, zero NuVizz, all thresholds live-tunable.'],
  ['0.50.58', 'ENGINE (shadow · Assignment) — stops sending 3-5 trucks to a far corner one truck should cover. On distant loops (e.g. the NW Dalton/Calhoun run dispatch gives one driver), the engine was scattering the stops across every driver who "usually" delivers to each of those customers — dragging near-Buford trucks 60+ miles out for a stop or two each. The plan solver now has the concept dispatch has in its head: a driver pays a one-time charge for reaching the far corner (so once a truck is out there, more far stops are nearly free, but sending a SECOND truck out is expensive), a distant customer\'s "usual driver" pull is down-weighted where geography should win, and splitting one far zone across multiple drivers is penalized. Net: distant loops coalesce onto one truck like dispatch runs them. This is engine 2.2.0; the whole history was re-scored so the Assignment agreement trend reflects the change. Shadow only — it changes NOTHING about live dispatch, and remains zero NuVizz / zero Google-matrix calls. Every threshold is a live-tunable config knob.'],
  ['0.50.57', 'PUSHED-TO-NUVIZZ LOG — bulletproof against simultaneous pushes. Each pushed order is now stored as its OWN record in the cloud log instead of one shared per-day list, so two pushes landing at the same moment (Bulk Add + Manifest Intake, or two dispatchers) can never overwrite each other\'s history — the last remaining race from the debug sweep. Old history is still readable (the viewer merges the old-format days automatically), the day picker and Pushed tabs look exactly the same, and it remains zero NuVizz calls. Alongside this release the daily call breaker was switched ON in enforce mode with a 5,000-call ceiling: if a runaway anything ever tries to blow past 5,000 NuVizz calls in a day, the scanner now HALTS instead of just logging a warning (the board shows "Daily scan limit reached" and resumes after midnight UTC).'],
  ['0.50.56', 'FULL-APP DEBUG SWEEP — 19 verified fixes from a three-way audit of the client, the server functions, and the board/routing state. The big ones: (1) CS-NOTIFY EMAILS NOW ACTUALLY SEND — the notify hook only existed in the legacy scan engine, which the normal cheap scan never runs, so a notify_cs-flagged customer produced NO email on any production scan; the cheap scan now fires it (deduped, best-effort). (2) COST GUARDS: the ~3,000-call probe scan was reachable through an unauthenticated debug URL (?live=1) and through a mistyped env flag silently flipping scheduled scans onto the expensive engine — the URL now requires an explicit env opt-in and the cheap list scan is the DEFAULT with a loud log if the probe ever runs on a schedule. (3) LOAD MODE: after the Stop#/PRO swap, "Create as NEW load" still gated on Order # while the load is really keyed by PRO — a PRO-less row could silently vanish from the created load; the gate/asterisk now sits on PRO, and load mode also sends the consignee email it used to drop. (4) NO MORE RETRY DUPLICATES: bulk + manifest pushes now reuse a stable per-row idempotency id, so a lost response + a retry can\'t create the same order twice; and the grid freezes structural edits during a push so finishing rows can\'t delete the wrong line. (5) Pushed-to-NuVizz log: concurrent pushes can\'t clobber each other\'s records, ref-less rows aren\'t silently dropped, and switching days fast can\'t show one day\'s orders under another\'s label. Plus: customer-note history no longer stamps tomorrow\'s date after 8pm, Routes cards read the real NuVizz status when joined by load id (and a confirmed Dispatch override now retires properly), "View full route" respects corrected pins instead of framing the old wrong city, searching during a cold load frames results once they land, the carry-over picker can\'t claim more days than the server folds (14), the mobile Loads delivered count matches the board\'s, imports can\'t silently overflow the 300-row grid cap, a remembered column mapping can\'t be recalled one-column-shifted, and long notes with emoji can\'t corrupt the NuVizz write.'],
  ['0.50.55', 'FORMATTING SWEEP — six fixes from a full desktop + iPhone audit. (1) iPHONE: tapping a field no longer ZOOMS THE PAGE IN. Nearly every box in the app used small type, which makes iOS Safari auto-zoom ~33% on focus — on phones, form fields now render at 16px so the lurch-in/pinch-out dance is gone (pinch-zoom still works). (2) BULK ADD GRID: the Consignee column now stays PINNED on the left while you scroll the grid sideways — out at Phone/Notes/Status you can finally tell which order each row is. (3) The Order # and PRO columns are wide enough to show a full SO/SHP number instead of clipping ("SO456…"). (4) BIGGER TAP TARGETS on phone: the menu chip in the top bar (now with a ☰ icon so it reads as the menu), the status-pill scan/collapse buttons, the Filters "Reset", the bottom-grid collapse caret, and all grid checkboxes. (5) Error banners on the Map and Routing screens moved to the BOTTOM of the map area so they can\'t lay over the status pill / selection tally. (6) Cosmetics: "Scan now" no longer wraps to two lines on phone Diagnostics, and the duplicate floating version chip on the phone Map is gone (the top-bar chip stays).'],
  ['0.50.54', 'BULK ADD — the Stop # and Shipment # now land on the RIGHT NuVizz fields. When you imported your NuVizz route export and pushed, orders came out with NuVizz’s Stop Number = the SO series and Shipment Number = the SHP series — backwards from your live board, where the Stop Number IS your PRO (the SHP). The export’s column headers are labeled opposite to how NuVizz actually stores them, and the push trusted the labels. Now a Bulk Add push crosses them correctly: the PRO (SHP) → NuVizz Stop Number, and the Order # (SO) → NuVizz Shipment Number. The grid is unchanged (your PRO still shows in the PRO column); only what gets written to NuVizz changed. Verified against your 720 file: all four orders now write Stop # = SHP, Shipment # = SO. (New Order and scanned-manifest pushes are untouched.)'],
  ['0.50.53', 'BULK ADD — a “Pushed to NuVizz” tab, so a spreadsheet push leaves a receipt. Before, when you imported a spreadsheet and hit Create, the rows just cleared with a green “Created N” banner and there was no list to look back at — the “Pushed to NuVizz” history only existed for scanned-manifest PDFs. Now the spreadsheet Bulk Add screen has two tabs — Orders and Pushed to NuVizz — and every order you push is logged (consignee, Order #, NuVizz #, pallets/loose/weight, price, time). Pick a day to see exactly what went out, from any device; a clean push jumps you straight to the receipt. It reads/writes only our own log — ZERO NuVizz calls — and shares the same history as the manifest flow, so everything pushed that day shows in one place.'],
  ['0.50.52', 'BULK ADD — phone numbers that were already sitting in the grid now format too. v0.50.51 masked phones to xxx-xxx-xxxx as they’re typed or imported, but rows that were already in the grid from before the update (saved on this device) kept showing the raw digit run until you re-imported. Now the grid normalizes those phones the moment it reloads, so every row reads xxx-xxx-xxxx no matter how it got there. (NuVizz still gets the plain digits at push time.)'],
  ['0.50.51', 'BULK ADD — phone numbers import already formatted, wider columns, and the page uses the full width. (1) A phone dropped or pasted in from a spreadsheet now normalizes to xxx-xxx-xxxx the moment it lands in the grid — the same mask you get while typing — instead of arriving as a raw digit run like “4048148100”. (When the order is actually pushed, NuVizz still gets the plain digits.) Extensions (“x45”), “+” international, and unusual longer numbers pass through untouched so nothing gets truncated. (2) The Phone, Email, and Dispatch notes columns are wider now, so you can read the whole value instead of a cut-off “40481481…”. (3) The Bulk Add page is full-width — no more grey margins on the sides — so the table gets all the room.'],
  ['0.50.50', 'BULK ADD is now ONE STEP: drop the file → orders in the grid. When the file’s header reads clean (consignee, address, city, state, ZIP all recognized — like your NuVizz export does), the app imports it immediately: no “Map columns” screen, no Import button, just “Read the columns automatically and imported 4 order(s) — skipped 8 residue row(s)…” with a “Wrong columns? Undo & map manually” link if it ever guesses wrong. The 30-dropdown mapping screen only appears when the app genuinely can’t tell what a column is. And when the mapper DOES open, its button now tells the truth — “Import 4 orders (8 skipped)” instead of “Import 12 rows.” Verified on the real 7/20 file: drop → 4 complete orders, one step.'],
  ['0.50.49', 'BULK ADD — residue rows can’t junk up the import anymore. Your 7/20 spreadsheet had 4 real orders followed by 8 leftover template rows (just “AIR FILTERS · qty 1”, some with a dragged-down “GA” — no consignee, no address, no order #). The importer counted those as orders, so the grid filled with junk rows demanding 5 missing fields each. Now a row with NO identity — no consignee name, no street, no Order #, no PRO — is recognized as template residue and skipped, and the import tells you exactly what it did (“Imported 4 order(s) — skipped 8 residue row(s)…”). Verified against that exact 7/20 file end-to-end: all 4 real orders import complete — consignee, address, pallets, weight, Order # (SO…), PRO (SHP…), phone, and the full dispatch notes.'],
  ['0.50.48', 'RECONSIGNMENTS NOW SHOW UP. When an order was reconsigned in NuVizz (its delivery address changed after it was already on the board), Dispatch Map kept showing the OLD address — and the pin stayed at the old spot — because the address was captured once when the order first appeared and never refreshed. The background scan now watches the (free) saved-search list for a changed delivery address on any order it already has: if the ZIP or the street number changes, it treats it as a reconsignment and re-pulls that one order so the new address, the map pin, and the details all update. Costs at most one lookup for an order that actually moved (never a full scan), and ordinary formatting differences can\'t trigger it.'],
  ['0.50.47', 'BULK ADD reads the NuVizz route export correctly + EMAIL is now a field. (1) Dropping a NuVizz "Ship To/Ship From" route spreadsheet used to grab the wrong columns — it mapped the Buford WAREHOUSE ("Ship From") as the delivery address and the unit label ("Stop Weight Uom" = "pounds") as the weight, so every order would have gone out to the wrong place with no weight. The importer now ignores the pickup/"Ship From" side for delivery fields and never treats a "…Uom" column as a value, and it maps the real Ship To address/city/state/zip, the Stop Weight number, Skids→pallets, Comments→dispatch notes, and the Customer Number (a phone on this export)→phone. Davis convention: the Shipment Number (SO#) is the Order # and the Stop Number (SHP#) is the PRO. (2) EMAIL: added a consignee Email field to the New Order page and the Bulk Add grid; it maps to the NuVizz order contact (to.contact.email) on create, so the customer email rides along with the order.'],
  ['0.50.46', 'ENGINE TAB — the shadow-engine day maps now actually draw. On both the Sequencing and Assignment views the right-hand map could come up solid grey (blank) even with a route/driver picked and the "engine moved" list populated — Google Maps was never told its panel had a real size, so the tiles never painted. The map now redraws and re-fits the moment its panel is sized (and on any resize), so it fills in reliably. Assignment view also got three asks: the daily-agreement trend now shows real DATES on the x-axis (a single-month window used to collapse to one lonely month label); clicking a driver row focuses the map on just that driver — dispatch route vs the engine\'s, fit to their stops, with a Clear button; and the map is bigger (wider + taller) while the chart is shorter, so there\'s far less grey space.'],
  ['0.50.45', 'Three fixes. (1) CORRECT PIN LOCATION no longer closes the order or throws the map across the state. Clicking "Correct pin location" used to close the order card and — because nothing was selected anymore — snap the map back out to the whole board (looked like it jumped "3 cities away"). Now the order stays open and the map holds its place; the draggable blue pin drops right where the stop already is. It only recenters if the pin happens to be off-screen, so you can always grab it. (2) MAP NO LONGER DRIFTS ON ITS OWN. With a search active (e.g. "floor"), every 120-second board refresh was re-framing the map to fit all the far-apart matches — so if you left an order open it slowly zoomed out and lost focus on its own. The map now only re-fits when you actually change the search, not on the background refresh. (3) ROUTING (beta) now opens on the BUILD tab by default instead of Engine (switch to Engine anytime; coming back to Routing lands on Build again).'],
  ['0.50.44', 'MAP — the receiving-hours "clock" pin now pops up a real hover card. Hovering one of these pins on desktop instantly shows a little card with the business name AND its receiving hours (e.g. "ACME WAREHOUSE · Receiving hours: Mon–Fri 8:00a–3:00p · Sat Closed") — no more waiting on the slow grey OS tooltip, and no need to click in. Only the clock pins get the card; plain pins are unchanged. (Replaces the 0.50.43 approach, which relied on the browser\'s built-in tooltip that was easy to miss.)'],
  ['0.50.43', 'MAP — hovering a receiving-hours "clock" pin now shows its hours. On desktop, hovering any map pin has always popped up the platform/business name; now, for the pins that carry a receiving-hours restriction (the clock icon), the hover tooltip also shows the window — e.g. "ACME WAREHOUSE · Receiving hours: Mon–Fri 8:00a–3:00p · Sat Closed" — so when you\'re hunting for a time-restricted stop you can read its hours without clicking in. Only clock pins get the extra line; pins with no hours set are unchanged.'],
  ['0.50.42', 'CS EMAIL ACTUALLY SENDS NOW. The “Email CS when scheduled” toggle was on, the customer matched, the email built — but the scheduled scan had NO recipient wired up (the NOTIFY_CS_TO address was never set on the live site), so it silently sent nothing. Every real send since the feature launched was a no-op; the only one that ever “worked” was a manual test redirected to a personal inbox. Fix: CS emails now default to customerservice@davisdelivery.com (the same inbox the daily Forgotten-Freight log already uses) whenever no address is configured, so a missing setting can’t disable the feature. Also added a per-day status record so this can never be an invisible no-op again — it shows how many customers are opted in, how many matched on the board, and how many emailed. Marked customers will get their email on the next scan.'],
  ['0.50.41', 'HOME-SCREEN ICON now matches the browser tab. Adding Dispatch Map to your iPhone/iPad home screen used to show a plain grey "N" — iOS uses a separate app-icon image (not the tab favicon), and there wasn\'t one. It now uses the same folded-map icon as the browser tab. NOTE: iOS caches the home-screen icon hard — if you already added it and still see the grey "N", REMOVE the app from your home screen and re-add it (Share → Add to Home Screen) to pick up the new icon.'],
  ['0.50.40', 'SINGLE NEW ORDER: typed PROs like “estes-2258732686” no longer blow up the create. NuVizz hard-limits its PRO field to 10 characters, so a carrier-prefixed ref rejected the whole order (“stop.proNumber size must be between 0 and 10, code 1401”). Every create path now applies the same rule the manifest import already used: NuVizz’s PRO field gets just the 10 PRO digits (prefixes, dashes, and a trailing “-1” suffix are handled), while your full typed reference still lands on the stop’s Shipment # and Reference fields — nothing you typed is lost. Same fix everywhere: single New Order, Bulk grid, and manifest intake.'],
  ['0.50.39', 'ENGINE 2.1.1 — STOP MANUFACTURING PHANTOM TRIPS. The assignment engine was proposing ~10-15% more trips per day than dispatch actually ran (81 vs 71 on Jul 14) — a plan the real crew could never cover. Root cause: the per-trip weight ceiling was the 85th-percentile of a driver\'s history × 1.15, which BY DEFINITION chops the heaviest 15% of trips dispatch really runs and splits them in two. Two changes, both learned from our own history rather than hand-tuned: (1) the engine now also remembers the HEAVIEST single trip each driver (or truck class) has ever actually run, and will never force a split below that — if dispatch has proven a weight fits on one truck, the engine may plan it on one truck; (2) the "don\'t over-trip" penalty is now a real vote (8× stronger), pulling each driver\'s trip count toward their true double-trip habit. Shadow-only; replay rescored after deploy.'],
  ['0.50.38', 'MANIFEST INTAKE — stack manifests + a real pushed-to-NuVizz history. (1) Dropping a SECOND (or third) manifest PDF now ADDS its orders to the ones you already have instead of replacing them — held orders are kept, the new ones append below (deduped by order ref so re-dropping the same file won\'t double it), and the header shows "…+ N more · N manifests merged". So you can build up several manifests and push them together. (2) The "Pushed to NuVizz" tab now has a DATE PICKER and a saved history: every push is logged to the cloud (order ref, NuVizz #, consignee, freight, time), so you can pick a day — e.g. yesterday — and see exactly what was pushed, from any device. Today\'s view refreshes the moment a push finishes. Reads/writes only our own log — ZERO NuVizz calls.'],
  ['0.50.37', 'The Routing (beta) screen now opens on the ENGINE tab by default. Every time you go to Routing it lands on Engine instead of Build; switch to Build any time while you\'re there, and it stays on Build until you leave and come back to Routing.'],
  ['0.50.36', 'Three fixes. (1) MOBILE LOADS TAB now has a SEARCH BAR — filter the loads list by route name or driver as you type (with a "showing N of M loads" count), same as the Stops tab. (2) STALE "Scheduled" APPOINTMENT STOPS — an order that sat on an appointment route and then DELIVERED a day or two later kept showing Scheduled on that route forever (e.g. a ULINE APPT stop that delivered early on another driver\'s load). Our board pulls "open work" + "just-completed-today" from NuVizz, so a delivery from 1–2 days ago is in neither pull and the board re-carried the pre-delivery snapshot. Now, before re-carrying a stop that\'s vanished from both pulls, we check our own sealed delivery history and drop it if it was delivered/closed recently — ZERO NuVizz calls, and it can never hide genuinely-open work. (3) MAP "Routes" BUTTON turned blue but sometimes showed nothing on the right (an open order/route was suppressing the roster); opening it now closes whatever detail was open so the roster always appears.'],
  ['0.50.35', 'PICKUP IS PRE-SET TO DAVIS. New Order and Bulk Add now come with “Davis Delivery Service — 943 Gainesville Hwy 200-4000, Buford, GA 30518” built in: the Pickup location dropdown always exists (even on a fresh browser with nothing saved), Davis is auto-selected, and the pickup card starts satisfied — no more typing the terminal address or “Set the pickup + service date first” just to push a manifest. Your own saved pickup locations still appear in the dropdown and win as the default. Picking “＋ New pickup location…” now starts a truly blank form (it used to pre-fill pieces of the default address).'],
  ['0.50.34', 'ITEMS NOW LAND IN NUVIZZ. The item description was being sent as a text reference on the stop, which NuVizz never shows in the Stop Details “Items” table — that’s why it read Items(0) even though the order went through. Every create now ALSO sends the description as a real line item: product = your Items text, ID = the PRO (or order #), quantity = total pieces, weight = the order weight — so it shows up in NuVizz’s Items table like any other shipment line. Applies to all entry paths (manifest intake, Bulk grid, single New Order). Re-pushing an already-pushed order updates it in place and fills in its Items line.'],
  ['0.50.33', 'FIX (the REAL one): manifest pushes that ACTUALLY SUCCEEDED were being reported as failures. NuVizz confirms a stop upsert with the status “STOP UPDATED SUCCESSFULLY” (not the bare word “SUCCESS”), and the app only recognized the exact word “SUCCESS” — so it flagged a successful write as failed and kept the order in the Held queue even though NuVizz already had it. The success check now accepts any “…SUCCESS/SUCCESSFULLY” status (while still failing on PARTIAL / FAIL / REJECT / ERROR), and the same fix is applied to the assign/dispatch path (the async-import path already handled it). Your earlier “failed” pushes DID go through — those orders are in NuVizz; re-pushing just UPDATES the same stop (no duplicates). (The v0.50.32 phone-format change was a red herring but is kept — clean digits are the right thing to send.)'],
  ['0.50.32', 'FIX: pushing a manifest order to NuVizz could fail with an unhelpful “write error.” Two problems, both fixed. (1) When NuVizz rejected a write it returned the reason in a message shape the app wasn’t reading, so you got the generic “write error” instead of WHY — the real reason is now surfaced on the row. (2) The likely cause: the on-screen phone auto-format (xxx-xxx-xxxx) was being sent to NuVizz WITH the dashes, and NuVizz validates that number (it drives the customer text-message) and rejected the punctuation. Phone now goes to NuVizz as clean digits (a leading “+” for international is kept) while still showing formatted on screen. Re-check ● LIVE and retry the push.'],
  ['0.50.31', 'ROUTING + intake fixes. (1) Click a PLANNED stop — on the map OR in the bottom Stops grid — and its route now opens in the Compare panel, just like clicking a load does (it was only toggling the selection before). Pool / unplanned stops still toggle into your selection for route-building. (2) The manifest intake number columns are actually narrow now: Pallets / Loose / Weight / Price were stretching to full width because of a CSS conflict (a w-full override) — they now fit their digits, which gives the Items and Dispatch-notes columns the room. (3) Phone auto-format no longer mangles a number with an extension (“x45”) or an international “+” — those pass through exactly as typed; plain US numbers still snap to xxx-xxx-xxxx.'],
  ['0.50.30', 'MANIFEST INTAKE / order entry — a proper ITEMS column and a cleaner grid. (1) The manifest review table now shows an ITEMS column (what’s actually shipping, read straight off the manifest’s Description) — it was already being read, just never displayed. (2) The number columns are tighter (Pallets / Loose / Weight — “Wt” is now spelled out “Weight”) and Price is slimmer, freeing room so the Dispatch notes and Items columns are now wide enough to actually read. (3) The whole Bulk Add page is wider, reclaiming the gray side margins. (4) PHONE fields on every entry path — single New Order, the Bulk grid, and the manifest intake — now auto-format to xxx-xxx-xxxx as you type. All three paths already share the same column set (Items, Pallets, Loose, Weight, Phone, Dispatch notes, Price).'],
  ['0.50.29', 'FIX: the new full-bleed favicon (v0.50.28) was already live but browsers cache the tab icon so aggressively that even a hard-refresh kept showing the old blue-framed one. The favicon link now carries a version tag (favicon.svg?v=2), which forces every browser to re-fetch it — so the updated map icon actually shows. If a tab STILL shows the old icon, fully close that tab (or the browser) once and reopen; pinned tabs are the stickiest.'],
  ['0.50.28', 'Two small polish items. (1) The browser-tab icon (favicon) is now the map filling the whole tile — the blue frame around it is gone, so the little map reads bigger and clearer in the tab. (2) In "Search past PROs / customer history", when you search by a PRO number the matching chip in that customer\'s list is now highlighted blue, so you can instantly see which of their past deliveries you searched for instead of scanning the row.'],
  ['0.50.27', 'EQUIPMENT ICONS got the cleaner truck. The map markers and sidebar badges for “Tractor trailer friendly” (green ✓), “No tractor trailer” (red 🚫), and “Uline: straight-truck only” (amber) now draw the same crisp semi as the browser-tab favicon — trailer + sloped cab + two wheels — instead of the old blocky three-wheel drawing. Shows up on the Routing map pins, the stop-card equipment chips, and the legend. Cosmetic only — the flags, colors, and meanings are unchanged.'],
  ['0.50.26', 'BROWSER TAB ICON is now a little treasure map — a folded parchment map with a dotted trail leading to a red X, on the brand-blue tile — swapped in for the truck badge. It stays legible even on a pinned tab (icon only). The truck itself isn’t gone: it’s moving into the app’s equipment markers. Cosmetic only.'],
  ['0.50.25', 'ENGINE FIX: "Trips engine / actual" no longer reads N / 0. The Assignment view\'s ACTUAL trip count — how many runs each driver really made — was computed with a one-character type bug (asking a NUMBER for its .length), which silently zeroed the actual side on every scored day: the scoreboard read "71 / 0", every driver row read "1/0", and the travel comparison had nothing real to compare against. Both the day total and the per-driver counts now count trips correctly. Display/metric fix only — the engine\'s plan itself was never affected. (Note: agreement numbers stay cold-start-low until the driver-history backfill runs; that\'s data, not this bug.)'],
  ['0.50.24', 'BROWSER TAB ICON — the Chrome tab now shows a Davis Delivery truck badge (blue tile, white semi) instead of the blank default page icon, so the Dispatch Map tab is easy to pick out in a crowded window. It’s a crisp SVG, so it stays sharp on any screen. Cosmetic only — nothing else changed.'],
  ['0.50.23', 'ENGINE ASSIGNMENT — more room to actually read the routes. The day-plan map now has an ⤢ Expand button that hides the drivers table and blows the map up to full width (⤡ Collapse to bring the table back). The daily-agreement chart is shorter and collapses to a one-line header (▾ hide) so it stops eating the screen. And a new \u201cOnly moved\u201d toggle focuses everything — the drivers table AND the map (routes + pins) — on just the drivers the engine moved a stop to or from, so you can see the disagreements without the rest of the day in the way. Shadow-only view controls; no data or scoring change.'],
  ['0.50.22', 'MANIFEST INTAKE — the review screen you asked for, plus THE SCROLL FIX. (1) Dropping a manifest PDF now opens a dedicated intake panel instead of the generic column-mapper: header with the manifest # / date / trailer, tiles for ORDERS · MNF UNITS · WEIGHT · PICKUP, and two tabs — "Bulk Add — Held" and "Pushed to NuVizz". Every order shows its ESTES- order ref, consignee, and editable Pallets / Loose pcs / Wt / Phone / Dispatch notes / Price boxes; expand a row (▸) to fix its address. Check the rows you want and hit PUSH TO NUVIZZ — the live tally shows exactly what\'s going (count · plt · loose · lb · $). Unchecked orders stay HELD (saved on this device, still there tomorrow); pushed orders move to the Pushed tab with NuVizz\'s number. Same ○ Beta / ● LIVE gate as everything else — Beta shows "PREVIEW MODE — nothing sent". (2) NEW on every create path: PHONE writes to the NuVizz consignee contact (the stop card\'s Contact row / Text customer) and DISPATCH NOTES write as driver instructions (the card\'s notes panel) — on the intake, the Bulk grid, and the single New Order form. (3) FIXED: New Order / Bulk Add wouldn\'t scroll — anything below the first screenful was unreachable (a layout wrapper regression; it looked like the manifest import broke scrolling, but the page could never scroll). One-line fix; both screens scroll properly now.'],
  ['0.50.21', 'BULK ADD: manifest reading FIXED (no more timeout) + pick which rows push now vs queue for later. (1) The manifest reader timed out on your first real drop — reading a multi-page scan takes 20–40s and the server was capped at 26. It now runs in the background with the page checking in every few seconds (spinner shows elapsed time), so even long manifests finish. (2) NEW: every row in the Orders grid has a checkbox — checked rows get pushed to NuVizz on Create; UNCHECKED rows stay QUEUED in the grid (marked "queued", dimmed) and are skipped by every push, including load mode. The grid now SAVES ITSELF on your device, so queued rows are still there tomorrow — or after a reload — for a later push. Check/uncheck-all in the header; the footer counts what pushes vs what queues.'],
  ['0.50.20', 'ENGINE TREND now tracks the REAL learning curve. The Engine → Sequencing "watching the engine learn" chart used to plot the BLENDED daily mean, which rises and falls with how many UNGUIDED routes (no similar past route to learn from) happened to run that day — so a day could look worse just because more untaught routes ran, not because the engine got worse. The bold line is now the GUIDED mean (routes the engine actually had a learned reference for — the real performance signal, and the same number as the "Guided mean" tile), with the blended "all" mean kept as a faint dashed line for context. Days scored before this metric existed simply don\'t draw a guided point. Shadow-only, no data or scoring change.'],
  ['0.50.19', 'FIX: saving your bottom-panel PROFILE was confusing — the blue "Save" button was greyed out unless you typed a NEW name, so when you tweaked your active profile (e.g. set the window to "Last 7 days") and hit Save, nothing happened and there was no way to tell it apart from the smaller "Update … to current" link. Now, when you have a profile active and the name box is empty, that button reads "Update" and overwrites your active profile with the current bar setup in one click; type a name and it reads "Save" and makes a new one. Either way it flashes "✓ Saved" so you know it took. (The separate "Update ‹name› to current" link still works too.)'],
  ['0.50.18', 'BULK ADD reads SCANNED MANIFEST PDFs. Your Estes delivery manifests arrive as fax-style scans — pictures of a table, with no text inside the file at all (that\'s why the drop came in as one garbled column; no spreadsheet parser can ever read them). Now: drop the manifest .pdf on Bulk Add and an AI reader (the same one behind AI search — a few cents per manifest, ZERO NuVizz calls) reads every page and fills the review grid: consignee, address, city/state/ZIP, PRO, units → pallets, weight, description. Order # is prefilled the way your board already names these (ESTES-0288347656 style). Built-in cross-checks: each PRO is read from BOTH the printed number and the barcode digits (a mismatch is flagged, barcode wins), and the row count is checked against the manifest\'s own "Total Pros" header — any discrepancy shows in a banner. NOTHING is created automatically: the rows land in the same editable grid as a spreadsheet, you review against the paper, then hit Create as usual.'],
  ['0.50.17', 'BULK ADD — spreadsheet import + a wider grid. (1) A dropped file that came in as a single "Column 1" (with "no header detected") is fixed: the importer was guessing the wrong column separator on some files — a comma CSV with one stray tab in a cell, or a semicolon/pipe export — and jamming every row into one cell. It now picks whichever separator actually splits your rows into the most columns (tab, comma, semicolon, or pipe), and it sizes the column mapping to your WIDEST row so a short first/title row no longer hides the rest of the columns. (2) The Orders grid now uses the empty gray space on the sides — it was capped narrow, cutting off the right-hand columns; it\'s much wider now so more fields fit without side-scrolling. (If a dropped file STILL shows one column, tell me whether it\'s .xlsx or .csv and paste the first two rows — that pins the exact format.)'],
  ['0.50.16', 'NEW ORDER + BULK ADD now take a PRICE. Davis records a shipment\'s price in NuVizz\'s "Seal #" field, so there\'s a new Price box on the single New Order form ("Price ($ → Seal #)") and a Price column in Bulk Add that auto-maps from a pasted "price / seal / rate / amount / linehaul / revenue…" header. Whatever you enter rides into NuVizz\'s Seal # (sealNbr) on create — capped at 20 characters — across every create path: the single order, the row-by-row bulk Add, AND the "send as ONE import for load" bulk flow.'],
  ['0.50.15', 'FASTER MAP + ROUTING LOAD — for real this time. The board feed was shipping ~6.9 MB every load: 747 stops each carrying the ENTIRE raw NuVizz object (3.8 MB by itself) plus a stack of fields the map never reads — and the page sat blank for 5–6 seconds waiting on it. That, not the app, was the wait (measured it: the fetch was ~5 s of the load). The feed now serves ONLY the ~70 fields the map, grid, stop card, print, texting, and scanner actually use — via a database field-mask, so the dead weight never even leaves storage — cutting the payload ~55% and the server time with it. Nothing you see changes: opening a stop still shows every comment and document. If anything ever looks off, the old full feed is one flip away — add ?full=1 to the URL, or set MAP_FEED_FULL=1 on the site. (This is the real fix behind v0.50.5\'s attempt, which only trimmed the bundle + pin drawing — 3% of the problem.)'],
  ['0.50.14', 'FIX: an OUT-FOR-DELIVERY stop could vanish from the board — searching its PRO returned "no stops match" even though the driver had it. Our board is fed by two NuVizz saved searches: "open work" (Planned + Un-Planned) and "finished" (Delivered + Unable + Cancelled). A stop that is on the truck but not delivered yet — status Out for Delivery or Arrived — is in the middle and matched NEITHER, so it fell off every pull the moment the driver rolled and only stayed on the board if an earlier scan had already caught it (a stop planned + dispatched between scans slipped through). The "open work" pull now also grabs Out-for-Delivery and Arrived stops directly, so an in-flight delivery stays searchable on the board through the whole run. Zero extra NuVizz calls — it\'s the same single pull, just a wider status filter (the same fix that stopped cancelled orders from vanishing). Takes effect on the next scan.'],
  ['0.50.13', 'FIX: the printed Driver Manifest no longer prints a PICKUP location as the route "Origin". On a route with a pickup (e.g. CTL70926 at TSY AMERICA sitting correctly at stop 5), the manifest cover page was reading "Origin: TSY AMERICA" — making it look like the pickup got pushed to the front, even though its own ticket was in the right spot. The header now skips pickup stops when choosing the origin (a pickup\'s from-address IS the pickup location, not the depot the route starts from), so the Origin line shows the real starting point and the pickup only appears at its own stop in the route.'],
  ['0.50.12', 'FIX: you can now UNPLAN a pickup / return / non-delivery stop off a route. Removing a stop like MUGELE (a pickup, not a normal delivery) from a route and saving used to bounce with "load has a non-DO stop in a delivery slot — reorder skipped (verify in portal)", so the stop stayed stuck on the route. The save guard that protects a card from silently resequencing a non-delivery stop it can\'t model now counts the stops you\'re REMOVING as accounted-for — so striking one off and saving goes through and NuVizz unplans it. Planning a card that still leaves an unmodeled non-delivery stop behind is still protected exactly as before.'],
  ['0.50.11', 'HISTORICAL LOOKUP now shows the WHOLE delivery, not an empty shell. "Search past PROs / customer history" → tap a customer used to open a blank card: status Unplanned, ITEMS —, ROUTE "Not yet assigned", PROS (0), and a Delivery Ticket titled "hist:…" with 0 weight/pallets and no line items — because the lookup only ever carried the name + address. Now tapping a customer (or a specific PRO chip — the chips are individually tappable now) pulls that delivery\'s FULL archived record from our own history warehouse: the real route + who delivered it, the PROs, the line items, weight/pallets, and a printable Delivery Ticket. It reads only our saved history — ZERO NuVizz calls — and if a day is too old to be in the warehouse it falls back to the old name+address card so the receiving-hours/notes editor still opens. Tapping the customer name opens the most recent delivery; tap an older PRO chip to open that one.'],
  ['0.50.10', 'ROUTING GRID: search lights up the map + just-planned stops stop lingering. (1) Searching the Routing bottom grid (e.g. "estes") now highlights the matching stops on the Routing map — it only ever did that on the dispatch Map before. The hits render in BURNT ORANGE, a deliberately different color from the amber "selected" highlight, so when both are on the map at once you can tell what you searched for from what you\'ve selected. They ride the top layer (never hidden under another dot) at the same compact size as the Map screen\'s hits, and clearing the search clears the highlight. Debounced so a busy board doesn\'t stutter while you type. (2) FIXED: stops you\'d already planned onto a route (e.g. LVILLE) kept showing as available in the grid\'s date-window view until a scan caught up. The window rows now mirror the live board — which your Save already stamps the moment it verifies — so a just-planned stop flips to its route immediately (and an Un-Planned filter drops it), no scan needed. Zero extra NuVizz calls.'],
  ['0.50.9', 'NIGHTLY WAREHOUSE — the last two path-safety gaps (a 4-agent verification pass found them). (1) One more database key still carried a raw name: the routing engine\'s per-driver day record keyed off the raw driver name, so a co-driver like "COLIN/DJ 1" could throw when that record was written — now path-safe like every other key (this never affected sealing or the tractor paint; it only dropped that one engine record). (2) The ZIP-cleanup shipped in 0.50.8 only landed in the browser copy of the address-key builder; the SERVER copy the nightly capture actually uses still had the old code, so a malformed ZIP could make the app and the server compute different keys for the same customer. Both copies now match exactly. Warehouse-integrity only — zero customer-facing change, zero NuVizz calls.'],
  ['0.50.8', 'NIGHTLY WAREHOUSE: finished sealing the "slash in a name" hole (v0.48.4 fixed it for routes/drivers; this closes it everywhere else) and made the nightly PAINT self-heal. Root cause of a night that captured stops but never sealed — or sealed but never painted the lime "tractor delivered" pins — was a customer/load/stop key containing a character that isn\'t legal in a database path (a co-driver load like "COLIN/DJ 1", or a malformed ZIP with a slash): the write threw and took the rest of the night down with it. Now EVERY key that becomes a database path is made path-safe (stops, the tractor-paint locations, and the per-customer history rollup — routes/drivers were already safe), and the ZIP is cleaned at the source so it can never carry a slash into the key. Two more hardenings: an audit-log hiccup can no longer flip an already-sealed night to "failed" and skip the paint; and the recovery/heal that reseals an orphaned day now RE-PAINTS and re-mines it too (before, healed days got a manifest but their tractor pins and engine data were never written). Warehouse-integrity only — zero customer-facing change, zero NuVizz calls.'],
  ['0.50.7', 'SEARCH HITS: on top + a size smaller. When you search (e.g. "estes-"), the orange matched dots now render ABOVE every other marker, so a hit is never hidden under a nearby unmatched dot — Google used to stack markers by latitude, which could bury a northern hit behind a southern non-match. They\'re also a size smaller now (22px — between the big AM/PM-tagged pin and the small resting dot) so a big result set doesn\'t blanket the map, and the dimmed non-matches sink below the board. No change to the dots\' color or what they mean.'],
  ['0.50.6', '% DELIVERED on the stops count. The "Showing N of M stops" line — on the mobile Stops tab and in the desktop filter panel — now ends with how much of the day is done, e.g. "Showing 849 of 849 stops · 34% delivered". It counts delivered stops against the WHOLE day\'s board, so it\'s a steady progress read: it stays put while you search or filter the list (it always reflects the full day, not just the rows currently shown).'],
  ['0.50.5', 'FASTER MAP LOAD + clustering off by default. (1) Marker clustering is now OFF by default — you told me you\'ve never liked it, so the map shows every pin individually (flip "Show clustered" back on any time in Filters; that sticks). (2) The map used to rebuild every one of your 500–1500 pins about THREE times on each cold load — once when stops arrive, again when customer notes land, again when tractor locations land — regenerating every pin\'s icon from scratch each pass, plus a full rebuild on every 2-minute refresh. Pin icons are now cached and reused, and the map keeps one clusterer instead of building a new one each time, so those repeats are near-free. (3) The Uline quote calculator (~345 KB) no longer loads with the map — it loads the first time you open the Quote tab, trimming the app\'s cold-start download. No change to what any pin looks like, and zero effect on NuVizz calls or scans.'],
  ['0.50.4', 'ROUND DELIVERY PINS + a "Hide map labels" switch. (1) Delivery stops are now CIRCLES, not teardrops — the map, the routing screen, and the Compare/Engine view all render each stop as a round marker centered exactly on the location (a teardrop pointed from above the spot; a circle sits ON it). Everything the old pin carried carries over unchanged: the status color, the route sequence number, the co-located count badge, AM/PM tags, the DNS ✕, hollow "unset" styling, and search-match orange. The only pins that stay teardrops are the draggable "move this stop to the right spot" markers, where the point is the whole point. (2) NEW Map filter "Hide map labels" (Filters panel + the mobile filter drawer) turns off Google\'s own business/place-name labels — the clutter that overlaps your stop pins — the same switch the Routing map has had. It cleans the satellite view; because the map uses a cloud style, the plain roadmap base keeps its labels, so flip on Satellite view to see the labels drop. Also: this deploy points the CS-email recipient at customerservice@davisdelivery.com.'],
  ['0.50.3', 'CS EMAIL IS LIVE. The "Email customer service when scheduled" toggle now actually sends: the Resend email keys are configured on the site, sending as Davis Dispatch from the verified davisdelivery.com domain, to whatever address is set in NOTIFY_CS_TO (start it on yourself, then point it at the CS inbox when ready). Turn the toggle on for a customer and CS gets one email the first time that customer hits a day\'s board. To send a one-off check any time: /.netlify/functions/cs-notify-test?pro=<PRO> (add &dryRun=1 to preview without sending, or &to=you@example.com to redirect). This deploy is also what makes the keys take effect — env changes only reach the functions on a fresh deploy.'],
  ['0.50.2', 'Engine → Sequencing: the Routes table now has a search box. Type any part of a route/load number, a driver name, or a truck class to filter the day\'s scored routes (case-insensitive) — the header shows "N of M" while a filter is active, and sorting still works on the filtered set. Purely a client-side view filter; no data or scoring change.'],
  ['0.50.1', 'Stop-card notes fixes + a way to TEST the CS email. (1) Saving a customer note (e.g. turning on "Email customer service when scheduled") now returns you to the note view instead of staying stuck in edit mode — before, tapping Save left the card looking dirty, so closing it popped a "you have unsaved edits" warning right after you saved, which read as "it won\'t save." (2) The collapsed note now SHOWS "Email CS when scheduled" (and every other set flag) so you can actually see the toggle took. (3) The mobile stop card no longer wastes a big band of white space: the sheet now hugs its content instead of stretching to full-screen when the note is short, and a double-counted safe-area gap under the Save bar is gone. (4) NEW test tool: hit /.netlify/functions/cs-notify-test?pro=<PRO> to send yourself/CS one clearly-marked [TEST] copy of the exact scheduled-customer email — it reports if the email keys (RESEND/NOTIFY_CS_TO) aren\'t configured yet, so you know whether the feature can send at all. Zero vendor calls. NOTE: if a customer\'s toggle still reverts after this, it\'s the customer key drifting when NuVizz returns a slightly different name/address on a later pull — flag it and we\'ll pin the key.'],
  ['0.50.0', 'ROUTING ENGINE 2.1 — audit fixes, the routing calendar, and driver habits. (1) The five-agent audit\'s accepted findings are in: the engine now learns each route\'s zone order from a WEIGHTED CONSENSUS of its top-5 most similar past routes (recency-decayed, a driver\'s own history counted double) instead of a single best neighbor — one weird old route can no longer mislead it, and a lone dissenter gets outvoted; the assignment shadow now uses each driver\'s TYPICAL start time (learned from history) instead of the day\'s actual clock-in, so it only knows what a planner would know; nightly scoring now waits for 14 days of reference history exactly like the replay; and the Engine tab\'s headline numbers are split guided vs unguided (sequencing) and known-driver vs fallback (assignment) so an untaught route never dilutes the real signal. (2) The REAL routing calendar is now config, not lore: dispatch builds overnight 20:00–07:00 ET, Sunday night builds Monday, no weekend boards — the engine idles cleanly on non-board days and holiday tombstones, and future Assist runs inherit the "never read today\'s plan before 07:30 ET" rule. (3) DRIVER HABITS: a new nightly miner tracks which driver usually delivers each customer; the stop panel now shows "Usually delivered by <name> — X of N deliveries" when the pattern is real, and the assignment engine prefers the habitual driver (customer-level signal outranks zone-level). Engine v2.1.0; still 100% shadow.'],
  ['0.49.0', 'ROUTING ENGINE — Phase 2, the ASSIGNMENT layer (still shadow). Phase 1 re-sequenced the loads dispatch built; Phase 2 builds the whole DAY PLAN. Given a board date\'s planned stops and the drivers who actually worked it, the engine assigns every stop to a driver-shift — a chain of 1..N trips through a Buford reload, split far-first (the bigger, farther load first, the close-in load second, the way our double-trippers actually run) — using capacity envelopes and zone affinities it learns per driver from our own history. It scores its plan against what dispatch actually built with the same crew: "stop agreement" (did the engine give the stop to the same driver?) and "co-load agreement" (of the stops dispatch put on one truck, how many did the engine keep together?) — reported separately so a miss is either a load-shape difference or a driver choice. The Engine tab gains a Sequencing | Assignment toggle; Assignment shows the agreement scoreboard, a learning-curve trend, a per-driver table (engine vs actual trips/stops/lbs), and a day map with Dispatch / Engine / Diff (one color per driver, trip 1 solid and later trips dashed, moved stops called out). SHADOW ONLY — it proposes and scores, changes nothing; Assist/Auto stay locked for Phase 3. Zero NuVizz calls, zero route-matrix calls; it reads only our warehouse + roster.'],
  ['0.48.4', 'HISTORY CAPTURE HOLE — ROOT-CAUSED AND SEALED. Six weekdays (Jun 24/25, Jul 1/2/7/10) were missing from the history warehouse — every one a day the co-driver load "COLIN/DJ 1" ran. That slash in the load name made an invalid database path, so the moment the capture tried to write that route it threw — AFTER the day\'s stops were saved but BEFORE the routes, the per-customer history, and the "day complete" seal. Result: the stops were on disk but the day looked empty to every history feature, and a customer\'s delivery on one of those days (e.g. ER SNELL, 7/10) never made it into their history. Fixed: any load/driver name is now made path-safe before it\'s used as a key ("COLIN/DJ 1" → "COLIN_DJ 1"; the real name is still stored on the record), so a slash — or any special character — can never abort a capture again. Also, the manifest-heal recovery no longer fails silently: a heal that hits an error now leaves a loud failure record instead of leaving the day looking merely "missing". The six affected days are being resealed from their stored stops (zero vendor calls) and the affected customers\' histories rebuilt.'],
  ['0.48.3', 'CUSTOMER HISTORY SEARCH now finds names that start with an INITIALISM. Searching "er snell" returned nothing even though E R SNELL CONTRACTOR is in our history (last delivered 6/11 by Steven Adjetey) — the customer\'s "E.R." abbreviation is stored as the single letters "E R", and the name index dropped single letters, so there was no "er" to match. Two-word searches then required BOTH words and quietly filtered the customer out. Now a run of single letters (E R, E.R., A B C…) is indexed as a joined token ("er", "abc"), so "er snell" finds it — and it works on existing history immediately, no rebuild needed. (Searching a single word like "snell", or the PRO number, always worked; this fixes the abbreviation-plus-word case.) Note: a PRO you see on TODAY\'s board isn\'t in history until it\'s actually delivered — history shows the customer\'s PAST completed PROs.'],
  ['0.48.2', 'Build / Engine toggle moved to the top nav row. On the Routing (beta) screen, the Build ⇄ Engine switch now sits at the FAR RIGHT of the same row as the main tabs (Map · Routing · New Order · …) instead of on its own strip below — and it only appears while you\'re actually on the Routing tab, so it never clutters the Map, New Order, Quote, or Diagnostics screens. Same two-tap behavior, one less row of chrome above the workbench. (On phones, where the top bar is a menu button, the toggle stays inside the Routing screen as before.)'],
  ['0.48.1', 'ROUTE FRAMING FIXED — no more deliveries hiding under the bottom grid. Pulling up a route (a load row, the Routes panel, View full route, a saved plan, or a search zoom) fit the stops to the FULL map canvas — but the bottom data grid floats ON TOP of the map, so the canvas keeps going underneath it and the southern end of the frame landed behind the grid (BUFORD: deliveries 4–7 invisible until you panned). Every map fit on BOTH screens (Map + Routing) now pads its bottom edge by the grid\'s actual current height — open, resized, or collapsed — measured at the moment of the fit, so the whole route always lands in the part of the map you can actually see. Recenter and multi-match search zooms get the same treatment.'],
  ['0.48.0', 'WAREHOUSE HOLES — SEALED. The nightly history capture was intermittently writing a full day of stops but never the manifest that marks the day complete, so six fully-captured days (Jun 24, Jun 25, Jul 1, Jul 2, Jul 7, Jul 10) went invisible to everything that lists dates — the reference miner, the replay, the nightly engine all skipped them. Root cause: the capture\'s final "verify-by-readback then seal" step could withhold the manifest silently (a transient under-read of the just-written docs, or a seal write that failed) with no retry and no alarm, so the day sat orphaned forever. Fix: the seal is now RETRIED, and every capture run must end in exactly one of three visible states — a sealed manifest, a tombstone (a day with genuinely no board), or a LOUD failure record — never silence. New Diagnostics "Capture health" strip shows the trailing 21 days at a glance: sealed, healed, tombstoned, did-not-seal (with the reason), or a scheduled weekday that went missing. Recovery tools reseal the orphaned days from their stored stops (nothing fabricated — the same real checks must pass) and re-scan the truly-missing days, tombstoning the ones with no board. No customer-facing behavior change; this is warehouse integrity.'],
  ['0.47.0', 'THE LEARNED ROUTING ENGINE — Phase 1, shadow mode. Routing now has two tabs: Build (the existing beta) and the new ENGINE tab. Every night, the engine takes the routes dispatch actually built, re-sequences each one using constraints learned from our own route history (stops cluster into zones that stay together; the zone ORDER comes from the most similar past route; a penalty search keeps neighborhoods contiguous), and scores its sequence against the dispatcher\'s with the official Amazon/MIT routing-challenge metric — 0 means "routed it exactly like dispatch". The tab shows the scoreboard (routes scored, mean/median similarity, estimated travel delta, unguided count), a daily trend chart to watch it learn, a sortable per-route table, and a Dispatch / Engine / Diff map with a "what the engine moved" list. SHADOW ONLY: it proposes and scores, it changes NOTHING — no NuVizz calls anywhere in the engine (it feeds off the history warehouse), no Google route-matrix calls (distances are estimated), and Assist/Auto stay locked until Phase 2. Kill switch: ROUTING_ENGINE=off.'],
  ['0.46.19', 'PLAN ONTO MY LOADS — the Routing (beta) build now plans straight onto the REAL loads you created in NuVizz. The left panel\'s step 2 is now "Plan onto" with two modes: "My loads" (new, the default) lists the day\'s roster — your ALPHA / ALPHA 2 / ATL / SUW / SUW 2 drafts, empties first with a search box — and you check off the loads to fill; Build then spreads your selected stops across EXACTLY those loads, one route per load, using each load\'s vehicle (a per-load Box/Trailer picker appears when checked; names with "trailer/53" default to the 53′ profile, and the green-only trailer rule still applies). The result shows each route under its LOAD NAME, and one tap — "Stage onto Compare cards" — opens every load\'s card with its planned stops staged (real load number attached, board stops kept, hand-reorders honored). Nothing touches NuVizz until you hit the cards\' normal Save — the same verified, journaled write path as always. The old truck-profile build is one tap away under "Trucks". Also: the Compare workbench now holds up to 6 cards (was 3) so a five-load build stages in one shot; loads with a duplicate name on the roster are shown but not pickable (identity is ambiguous — rename one in the portal), and a load that already holds stops can be picked to ADD to it.'],
  ['0.46.18', 'FIX: setting an AM/PM Delivery window on a customer that ALSO has receiving hours no longer hides the window on the map. The receiving-hours clock icon was taking over the pin and dropping the AM/PM tag entirely, so a "PM" window you set never showed. Now an AM/PM window overrides that clock — the pin shows the AM/PM tag (the window IS the receiving-time statement). Any other restriction icon (liftgate, no-tractor, appointment, closed-day) still shows as before. Applies to both the Map and Routing pins.'],
  ['0.46.17', 'TEST ARMOR (no behavior change). The three heavy test rigs promised in the v0.46.12 audit release are in — 23 new tests, suite now 706. (1) The server-side board write-through now runs END-TO-END in tests against a fake Firestore: pinned forever are the lowercase board tree (the v0.46.10 phantom-tree fix), stamping YOUR board date (v0.46.11), ghost removals never stamping, a batch-planned stop never being stamped unplanned by its own save, the hex-id-never-a-route-name guard, the 62-day carry-over rescue healing old rows in place, boardSync reporting every miss by name, and an unverified save never touching the board. (2) The scan\'s demotion policy (the "list says unplanned but the load still holds it" defense) is extracted into a factory and unit-tested: terminal rows always demote, one memoized load read covers a whole route, ambiguous same-named loads can\'t demote each other\'s stops, a roster failure holds rather than guesses, zero-padding can\'t fake a removal, and over-budget checks hold instead of demoting. (3) The carry-over fold is unit-tested with an injected clock: unplanned orders fold with their home day remembered, delivered/cancelled work never folds, a fresh confirmed Save folds (and replaces a stale-unplanned row in place) while stamps older than 48h age out, the live-set prune only trusts a fresh snapshot, and duplicates dedupe to the nearest day.'],
  ['0.46.16', 'Compare route-card header re-laid-out. The mileage + drive time (e.g. "119.2 mi · 3h59m · DH 45.9 mi") is now the light header line, and the load details drop to their OWN line BELOW it and WRAP instead of getting cut off ("17 sk…"). The freight counts stand out — orders, skids, and loose are now BOLD — and LOOSE is shown too (it was missing before): "ANDERSON FRIMPONG · 13 stops · 14 orders · 17 sk · 3 loose · 17,933 lb · 0%". (If a printed manifest still shows the DAVIS load number instead of the route name, hard-refresh — that fix is already live and your browser is holding an old copy.)'],
  ['0.46.15', 'Bottom-panel PROFILES — save your bar settings and switch between them. Set the grid the way you want (Stops/Loads, Status filter, date window + range, driver, no-location filter, and the sort), then open the new "Profiles" dropdown (top-left of the bar, next to Stops/Loads), type a name, and Save. Pick a saved profile any time to snap the whole bar back to it; "Update" overwrites the active one with the current settings, and the trash icon deletes. Profiles are remembered on your device and work wherever the grid appears (Map + Routing). Your search text is NOT part of a profile (it stays a quick one-off filter).'],
  ['0.46.14', 'Print Manifest polish. (1) The big blue title at the top is now the route NAME (e.g. the driver\'s route), never the raw DAVIS load number — a load opened from the Loads grid used to print "DAVIS000198611" up top; it now prints the load\'s name. (2) On each Delivery Ticket the "Ship To" business name is now bold and a touch larger so the destination stands out at a glance.'],
  ['0.46.13', 'Two Compare/Save tweaks. (1) Save now SENDS TO NUVIZZ DIRECTLY — the "Send to NuVizz / This will fire… / Send" confirmation popup is gone. Click Save and it commits (in ● LIVE against prod); Beta still just simulates. The server still validates every write and a save NuVizz accepts-but-doesn\'t-apply still fails loudly, so nothing is silently lost; a destructive action (emptying a load, which cancels the route) now shows a quick toast instead of a blocking dialog. (2) On the printed Driver Manifest, the Print and ✕ buttons moved to the TOP-RIGHT CORNER OF THE MANIFEST itself (they used to float at the top-right of the whole screen, away from the page).'],
  ['0.46.12', 'FIVE-AGENT AUDIT SWEEP — every fix from yesterday\'s firefight re-audited by five independent agents (cost, tests, board state, client UI, write path), and everything they caught is closed in this one release. SAVE ENGINE: a network hiccup during the post-save verify of ONE load can no longer fail the whole batch (each load verifies in its own guard now — the others keep their green); an assign/dispatch failure after a green save no longer suppresses the board stamp (the plan verified — it stamps); two cards saved together can no longer stamp each other\'s stops unplanned (the removal filter now knows everything the batch planned); a raw hex load id can never become the route name on a board stamp; and save results echo the load you ASKED for so the browser matches them up even when NuVizz renames. BOARD: the scanner\'s full rewrite of a day can no longer clobber a fresh save\'s 60-minute protection stamp mid-scan (the stamp survives the rewrite — this was the last standing way a saved route could revert); demotion double-checks now hit loads in random order so the same few routes can\'t hog the per-scan budget every time; a delivered/cancelled order can\'t carry over onto today; carry-over rows pin to the board day you\'re viewing. SCAN COST: a letters-in-it stop number can no longer rocket the number-probe frontier, and every load read caps at one retry. UI: three caches no longer memorize an error response forever (customer history, driver list, tractor locations — an early blip used to blank those until reload); an explicit box-only mark now beats the lime "tractor delivered" paint; clicking a multi-order location fully selects or fully clears it (mixed state selects the rest first); a staged twin order won\'t re-add itself after you strike it; changing the board date drops stale dispatch overrides; and just-saved stops flip planned on the map immediately in every window mode.'],
  ['0.46.11', 'Server write-through anchors on YOUR board date. Building tomorrow\'s board late at night, the server-side stamp targeted the current calendar day while your rows live on the day you\'re planning — the journal\'s new boardSync field caught it on the first post-fix saves (server patched 1, browser covered the rest). The Save now carries the board date you\'re working on and the server stamps THAT day\'s board; older browsers without the field fall back exactly as before, with their own sync still covering.'],
  ['0.46.10', 'THE AUDIT CAUGHT IT: every board patch since the write-through was BORN has been writing to a phantom copy of the board. Firestore paths are case-sensitive, the scanner files the board under "davis__" but every save-side patch used "DAVIS__" — so write-through stamps, carry-over rescues, and the reconcile all landed in a tree nothing reads. One normalization now converges every caller onto the real board: saves stamp rows that actually exist, the reconcile actually heals, the 60-minute hold actually holds. Also hardened from the same audit: two same-named loads can never demote each other\'s stops (ambiguous names fall back to the stop record, and "not on that load" alone no longer demotes — only the record can); a cancelled/delivered order can\'t be resurrected as live; number padding differences can\'t fake a "not on load"; a stale-unplanned leftover row can\'t hide a confirmed save; and old orders up to 62 days back (the full window range) now rescue onto today\'s board when saved.'],
  ['0.46.9', 'ROOT CAUSE OF EVERY DROP, FOUND AND CLOSED. Forensics on tonight\'s MONE save showed the board write-through NEVER landed — a green 15-stop save left ZERO stamps because the browser\'s sync call was dying silently. The write-through now happens ON THE SERVER, inside the Save itself: the moment a save verifies green against NuVizz, the server stamps our board directly, and the outcome is recorded in the write journal per load — a sync can never fail invisibly again (the browser\'s sync stays as backup). Also: every board-sync call is journaled; the "-1" re-delivery duplicate orders NuVizz creates (007143917-1 style, no dates on them) used to be INVISIBLE on every day\'s board — a dateless open order now files to today; and a window-picked stop that just got saved now flips planned on the map immediately instead of reading stale-unplanned.'],
  ['0.46.8', 'Selected-window green rows now match EVERYTHING the map paints green: the dispatcher-set tractor paint, the "Tractor trailer friendly" badge, AND the lime proven "a tractor has delivered here" locations — not just the manual paint (4 of 6 green-painted stops weren\'t highlighting). An explicit box-only mark still wins: that row never greens.'],
  ['0.46.7', 'Ghost removals can no longer cement a wrong "unplanned" on the board. Removing a stop from a card that the load never actually held (a stale ghost you pulled on, then struck off — the "Removing N orders (Unplanned on Save)" footer) used to stamp that stop CONFIRMED-unplanned on our board after the green save, protected by the post-save hold — so a rescan then DEFENDED the wrong state (why SHP29343 / UNITE MEDICAL kept reading unplanned while TRAILER 1 held them). Now only removals of stops the card started with — stops genuinely on that load — write through as unplanned; ghosts just drop off the card. Run the board reconcile once (v0.46.6) to clear any already-cemented rows.'],
  ['0.46.6', 'BOARD RECONCILE + route names in errors. Tonight\'s pre-fix drops left already-planned stops showing unplanned on our board — so they were grabbable on the map, Saves refused them ("NuVizz holds it on…"), and the holding load\'s card opened empty so the move couldn\'t even be staged. New one-shot repair: the board-reconcile run reads each load on today\'s roster ONCE from NuVizz and rewrites our board to match production truth (same write a green Save does, old-dated orders included). It never runs on its own — you fire it, and the preview shows the exact call cost first (~1 call per route). Also, per Chad: save errors now name loads THE WAY THE CARDS DO — "NuVizz holds it on TRAILER 1 (DAVIS000198690)" instead of a bare number — on both the holding load and your own, and the banner leads with the card\'s route name.'],
  ['0.46.5', 'THE BIG ONE: the board can no longer un-plan a route you saved. NuVizz\'s list feed lagged tonight\'s OWUSU 1 save by 30+ minutes, and once the 20-minute hold expired the scans "corrected" the board back to unplanned — dropping the route on our side while production NuVizz held every stop (NOLAN vanished entirely because its old-day row stopped folding onto today once it read planned). Three-part fix: (1) when the list disagrees with a saved plan, the scan now asks the LOAD itself — one call verifies a whole route — and keeps every stop the load holds, instead of trusting the per-stop record that lags right along with the list; (2) the post-save hold is 60 minutes; (3) an old-dated order a Save routed onto today\'s load keeps showing on today\'s board. Also: markers no longer vanish right after a green save with "Unplanned only" on (the freshly-saved route stayed exempt only under the name it was opened with — now every identity of an open card counts); NEW window presets "Last 7/14 days · board day" that follow the board date; the bottom grid highlights rows of stops in the map selection; and tractor-friendly (green) stops paint green in the Selected window.'],
  ['0.46.4', 'Fixed the FALSE "planned on another load" save failure (OWUSU 1). After a batched add, NuVizz attaches the stops ASYNC — our immediate re-read could catch the load before any arrival showed and then blamed the first stop as "still planned on another load" even though its record read UNPLANNED (as checked in the portal). The verify now gives NuVizz a beat and re-reads before judging; a straggler is re-read BY NUMBER — if NuVizz names a real holding load you get the actionable move error (that check is back even on the new low-call path), if our stored id was stale the save re-adds with the fresh id automatically, and if NuVizz is simply still processing the error now says THAT (wait a few seconds, Save again) instead of inventing a phantom load. Also: with a date window set, the bottom grid\'s status filter now re-applies AFTER the recent-save overlay — a just-planned stop no longer shows under "Un-Planned".'],
  ['0.46.3', 'Four in one. (1) BUILD CALL COST: a 14-stop build was ~24 NuVizz calls because the engine paid one /stop/info per added stop to resolve its internal id. Saves now ride ids the board already has (scan + enrichment) and read only the stops missing one — with ids on hand a build runs at the portal\'s own ~7 calls. To light ids up board-wide, add a "Stop Id" column to the planned/unplanned saved searches in the portal (same as the ShipTo-Display-Seq add) — the scan picks it up automatically, no code change. Every safety stays: the post-save verify still re-reads the load and still names a holding route. (2) MARKERS AFTER PRINT: printing a manifest hid the app for the print engine, which made Google Maps drop the numbered route pins — closing the manifest now rebuilds them exactly as they were. (3) ONE CLICK = THE WHOLE PLACE: clicking a marker that carries a count badge now selects (or clears) ALL of that location\'s orders at once — no more clicking twice for 2, three times for 3. (4) HISTORY ON THE STOP CARD: every stop panel now ends with "Recent deliveries here" — this customer\'s recent PROs with the driver who ran each and the date, straight from our saved history (zero NuVizz calls), no History search needed.'],
  ['0.46.2', 'Fixed OLD ROUTES BLEEDING INTO TODAY\'S COMPARE CARD. With a date range set on the bottom grid, pulling up a route matched every cached day\'s rows that ever carried that route name — last week\'s TAYLOR loads (old driver included) merged into today\'s TAYLOR card as one 26-stop / 951-mi monster, while the Routes rail and Loads grid showed the real 12-order load. Delivered stops leave the scan feeds, so their old-day rows stay frozen as "planned on TAYLOR" forever — the window merge was dragging that history in. Now a Compare card seeds from the SELECTED DAY\'s board only, and the grid\'s other-day rows join the map only while UNPLANNED (the carry-over case the window exists for: grab a missed order and plan it today). Planned rows from other days stay off the map, off cards, and out of Saves. Display-only bug — NuVizz and the board were never touched, and today\'s real loads were always intact.'],
  ['0.46.1', 'Kill switches for the tractor-delivered paint. (1) Legend → "Tractor delivered" now has an On/Off toggle — flipping it off instantly blanks the lime pins AND the stop-panel line on this device (persisted; the data keeps accumulating server-side, so turning it back on loses nothing). (2) Site env var TRACTOR_FLAGS=off stops the nightly server-side flag writes without a code change (existing flags stay). The manual rebuild function ignores the env switch — running it by hand is the intent.'],
  ['0.46.0', 'TRACTOR-DELIVERED LOCATIONS now paint LIME GREEN on the map. Any stop at a location where a tractor driver has EVER completed a delivery gets a lime pin with a white border — a permanent, automatic "a 53′ trailer has physically been here" signal, separate from the dispatcher-set green/red eligibility paint. Who counts as a tractor driver comes straight from the MarginIQ Employees tab (the Tractor tag + the NUVIZZ alias on the card) — tag a driver there and re-run the rebuild, and every location they ever delivered lights up, past included. The stop panel shows "Tractor has delivered here — last <date>", and the Legend explains the lime pin. Data lives in tractor_locations, derived from the saved history warehouse + roster: one Firestore fetch on map load, ZERO NuVizz calls anywhere.'],
  ['0.45.22', 'A stop opened in Routing (beta) now has the SAME full detail panel as the Map — it IS the Map panel now. Clicking a stop in Routing gives you Street View / Google Maps / Find business, Edit address, Correct pin location, Text customer, History, the Delivery Ticket, live notes + Activity Timeline, POD photos, AND the full customer-notes editor: Priority flag, Delivery window, and the Receiving-hours editor with Save. Before, the Routing stop panel showed receiving hours as read-only text and only offered Edit address / Correct pin — no way to set a customer\'s receiving rules or text them without switching to the Map. Opening a route still works the same (the panel\'s "View full route" opens it in Compare), and an appointment-window warning still shows on top. No NuVizz calls — notes save to Firestore, exactly like the Map.'],
  ['0.45.21', 'Looking up a PRO in NuVizz now opens the SAME full stop panel as clicking a stop on the map — so you get the Receiving hours / Priority flag / Delivery window editor plus Edit address, Correct pin location, Text customer and History, and a Save. Before, a PRO you searched for ("Look up PRO in NuVizz") opened a read-only window with none of those route/customer options — you could see the order but not set the customer\'s receiving rules. Now it\'s fully editable, exactly like a stop opened from the board or by customer name. (Note: this only changes how the panel opens — the separate issue of some delivered customers showing few past PROs in the history search is the server history warehouse needing a backfill, tracked separately.)'],
  ['0.45.15', 'Three dispatcher fixes: (1) the map selection tools (click / box / lasso / add-in-view) can NO LONGER grab a stop that\'s already staged on an open Compare card — it tells you which card holds it ("use Ninja to move it"), and area-selects report how many they skipped, so a stop can\'t be double-planned from the selection. (2) Route headers now count PHYSICAL stops — multiple orders to the same address are ONE truck stop (like NuVizz\'s own card): a card reads "7 stops · 9 orders" instead of "9 stops". Applies to the Compare card header and the Routes panel cards. (3) Clicking DISPATCH now flips the route\'s status immediately — it stayed "Draft" until a scan (paused overnight) because the status came from the cached roster; a confirmed dispatch now overrides that until the roster catches up.'],
  ['0.45.14', 'FALSE "SAVED" KILLED: adding a stop that NuVizz already has planned on ANOTHER route (possible when our board shows it stale-unplanned — the WIEDMANN→KOBE accident) used to slip past the save and report success while NuVizz quietly rejected it. Every ADDED stop is now verified against NuVizz itself BEFORE anything writes — if it\'s already planned elsewhere the Save REFUSES up front with "ALREADY PLANNED on load X — open X in Compare to stage the move". Costs one stop-read per newly added stop (a 10-stop build ≈ +10 calls) — the price of never lying about a save.'],
  ['0.45.13', 'FIX: a saved stop could silently DROP OFF a route on our side hours later (WIEDMANN BROS / GEORGE L — NuVizz kept it, our card lost it on re-open). The confirmed-save hold expired after 45 minutes expecting a scan to take over — but overnight the scanner is PAUSED, so a stop the server-side cache patch happened to miss reverted to unplanned with nothing to catch it. The hold now lasts up to 12 hours (it still releases the moment a scan confirms the save — the cap only matters when scans aren\'t running), and the board-sync now reports exactly WHICH stop numbers it couldn\'t patch (console + toast) so a miss is diagnosable instead of silent. Our board also self-corrects at the next scan since NuVizz has the route.'],
  ['0.45.12', 'NEW: Routing map → Filters → "Hide place labels" turns off Google\'s own business/place name labels (the clutter that overlaps your stop pins) on the satellite view. Persisted per device. (It cleans the satellite imagery; the roadmap base keeps its labels.)'],
  ['0.45.11', 'FIX: the bottom grid\'s date-window view now reflects a just-saved build IMMEDIATELY, same as the map — the confirmed-save overlay was painted onto the board/map but the window grid kept its already-fetched rows until a re-pull or scan (Chad: "the map reflects the work I\'ve done, the bottom panel does not"). Every confirmed Save now re-paints the grid in place. FIX: the printed Driver Manifest header now shows the ROUTE NAME (e.g. "TRAILER 3") — a freshly built card\'s stops don\'t carry the route name yet, so it printed a generic "Route".'],
  ['0.45.10', 'The bottom grid\'s ±7-day window now shows a DAY column — the "drift" between the map selection and the grid count was the window quietly mixing three different days\' work in one list: past carry-over (amber ◂), TODAY (blue), and FUTURE-day orders (violet ▸, e.g. tomorrow\'s appointments that are SUPPOSED to be unplanned tonight). The column only appears in a window pull; the normal Board (today) view is unchanged. Sort by it to split today\'s backlog from future work at a glance.'],
  ['0.45.9', 'FIX (route order in production): a PICKUP-type order — a return / RA — placed in the MIDDLE of a route was landing at delivery #1 in NuVizz no matter where you sequenced it. The RWB save loads every stop at the depot up front and delivers the rest in your order; a pickup\'s real customer visit is its "pickup" leg, but that leg was being emitted in the front depot block, so the driver hit it first. Pickups now ride their customer visit at the exact position you put them in, and return to the depot at the end. Pure delivery routes are byte-for-byte unchanged. NOTE: correct a route you already saved with an RA out of place by re-sequencing it once more and Saving (or drag it in the NuVizz portal for tonight).'],
  ['0.45.8', 'Reverted the bottom-grid date-window selector back to its original three choices — Board (today) / NuVizz · Today / NuVizz · ±7 days — on both the Map and Routing screens (per request). The extra ±3/±14/±30 presets and the Custom From/To range are gone; the toolbar reads exactly as before. Under the hood ±7 days still reads our board cache so it can\'t time out, and selecting ±7 days still puts that week\'s orders on the routing map to select/plan — only the picker UI changed back.'],
  ['0.45.7', 'FIX: fixing an address or moving the pin for an order pulled in via a Board date window/range made its pin VANISH until a full map refresh. The map added other-day window orders only if they ALREADY had a location, so a just-corrected order (its new pin lives in customer overrides) wasn\'t in the map\'s set for the override to apply to — it stayed invisible until the next scan re-geocoded it. The map now keeps those orders in its set so a corrected address/pin shows LIVE, the moment you save. FIX: "Debug this view" could fail with a GitHub "bad request" — the issue text was truncated with a plain cut that could split an emoji/special character and leave a broken byte GitHub rejects; truncation is now character-safe, and the error now shows GitHub\'s real reason (and says to rotate the token on a 401).'],
  ['0.45.6', 'FIX: the bottom Stops grid could show "No stops match" even with hundreds of stops in the window — a leftover term in the shared Search box (it\'s used by both Stops and Loads) was filtering everything out, and with the Compare panel open the box shrank to just an icon so you couldn\'t SEE the stray text. The search box now keeps a minimum width and shows a clear-✕ (and highlights) whenever it holds text, and the empty grid now says exactly what\'s hiding the rows ("None of the N stops match — hidden by search “…” / status / driver / no-location") with a one-click Clear filters button. No stray filter can silently blank the grid again.'],
  ['0.45.5', 'FIX: setting a date window/range on the bottom Stops grid was wiping the empty loads out of the Loads view — it dropped from all ~100 of the day\'s loads down to just the built routes. The Loads view is board-day scoped and shouldn\'t be touched by the Stops-view date filter at all, but the day\'s load roster (the empty "No orders yet · Draft" loads) was gated off whenever a window was set. The Loads view now always shows the full board-day roster — every empty load, filled route, and its driver — regardless of what date window the Stops grid is on.'],
  ['0.45.4', 'EVERY ORDER IN THE BOTTOM GRID IS NOW ON THE MAP TO SELECT + PLAN. Before, the routing map only showed the single board day you\'d picked, so when the grid was set to a Board window/range (±7/±14/±30 or a Custom range) the earlier-day unplanned orders it listed had no pin — you couldn\'t box/lasso them onto a load. Now the map ADDS every coord-bearing order from the grid\'s active window (deduped against the day board, which keeps its live status), so select-all on the map matches the grid and you can plan the whole backlog of unplanned orders in one pass. (Orders with no location still can\'t be pinned — the amber "N no location" chip from v0.45.3 flags those to fix first.)'],
  ['0.45.3', 'WHY THE MAP SELECTION AND THE BOTTOM GRID DIDN\'T MATCH — the grid lists every order, but the MAP only shows orders that have a geocoded location, so a stop with a bad/unrecognized address appears in the grid yet has NO pin: it can\'t be box/lasso-selected and, more importantly, can\'t be routed — that\'s how one gets silently missed. The bottom grid now shows an amber "N no location" chip whenever any listed stop has no map pin; click it to isolate exactly those orders and fix each address (Edit address / Correct pin) so they land on the map and become routable. (The other reason the two counts differ: a Board window/range like "±7 days" or a Custom range shows MULTIPLE days, while the map always shows just the one board day you\'ve picked — set the grid to "Board (today)" to mirror the map.)'],
  ['0.45.2', 'SAVED WORK CAN NO LONGER LOOK UNBUILT — a confirmed Save now paints the plan onto the board INSTANTLY on this device (a local overlay held until our scan agrees or 45 min, whichever first), fully independent of the server cache — so "closed the compare panel and it looks like I never planned it" (MONE/Denis) is dead even if every other layer misbehaves. The board write-through itself is also now DECLARATIVE (sends the card\'s full final stop order on every confirmed save, not just the delta) and no longer skippable by a result-to-card join miss; every sync logs its result to the console for forensics. FIX: the ±7-day pull "timed out" — NuVizz\'s own ad-hoc wide query is simply too slow, so wide windows (±7/±14/±30 and Custom range) now read OUR board day-docs instead: instant, includes confirmed saves, ZERO NuVizz calls (the status line says "Board · N stops"); Today and ±3 days stay live from NuVizz. NEW: routing a stop now AUTO-INCLUDES any co-located UNPLANNED order the selection missed (two orders at one address = stacked pins; clicking grabs only the top one — how QAE\'s second order got left behind). It says so in a toast and is removable from the card. NEW: the Routing right panel fully COLLAPSES to a thin strip (chevron in its header; clicking a stop auto-expands it). NEW: the stop panel has a HISTORY button — every past delivery to that location with PRO · date · driver, from saved history only (separate from the per-order Activity timeline; zero NuVizz calls). FIX: Compare-panel header buttons (🔗 engine, ● LIVE, Save, Back to Setup) could silently overflow out of view with a narrow card open — the header now wraps so every button stays visible.'],
  ['0.45.1', 'FIX: a Save of CARRY-OVER orders (yesterday-dated stops routed from today\'s board — the Uline/Denis case) landed in NuVizz but the board still showed the route unbuilt. The write-through only patched the SELECTED day\'s cache doc, and carry-over stops live on their own (prior) day\'s doc — so the patch silently missed every stop and the board kept serving the stale unplanned rows until a scan caught up. The write-through now finds each stop up to 14 days back, patches it in place AND copies the confirmed plan onto today\'s board doc, so the route shows immediately; if any stop still can\'t be patched the Save toast now SAYS so ("board didn\'t update for N stop(s) — NuVizz HAS the save") instead of failing silently. Also hardened the new Custom range from review: pulls are debounced 600ms + aborted when superseded (typing a date can no longer fire a NuVizz call per keystroke), entering Custom no longer auto-pulls, an incomplete/partial covering pull is labeled "≥ N stops (partial — narrow the range)" instead of posing as exact, stale rows can\'t linger under "pick a date range", and an inverted From/To is normalized. Zero new NuVizz calls anywhere (board fix is Firestore-only).'],
  ['0.45.0', 'Bottom grid "pull from NuVizz" — MORE date windows + a settable RANGE, and a fix for the ±7-day error. The window dropdown now offers Today, ±3, ±7, ±14, ±30 days, plus "Custom range…" — pick a From and To calendar date and the grid pulls exactly those delivery days. (NuVizz only understands relative windows, so a custom range pulls the smallest covering window in ONE cheap list call and filters to your exact dates server-side — still ~2 NuVizz calls, never a re-scan.) FIX: selecting ±7 days (or any wide window) could fail with "NuVizz: Unexpected token \'<\'… is not valid JSON" — a large pull was overrunning the function\'s 10s limit and coming back as an HTML error page. The explorer now has 26s of headroom, aborts cleanly at 22s, doesn\'t burn the budget on retries, and turns any non-JSON upstream reply into a plain "window may be too large — try a narrower range" message instead of a raw parse error.'],
  ['0.44.1', '🔗 RWB engine — the portal calls now carry a real browser identity instead of the Node/undici default: User-Agent, Accept, Accept-Language, and the Chrome client hints (sec-ch-ua*, sec-fetch-*), all matched to the dispatcher\'s actual macOS Chrome from a live Route Workbench HAR. (Content-Type stays multipart/form-data — the HAR confirmed the real portal uses that too. X-Requested-With is intentionally NOT sent — the real portal doesn\'t.) Override the UA with NUVIZZ_RWB_USER_AGENT. This closes the header-level fingerprint gap; the request bodies/ids were already HAR-matched.'],
  ['0.44.0', 'Per-action NuVizz call counter on every Compare-panel Save — the success toast now shows how many NuVizz calls that action actually made (e.g. "✓ 1 load saved · 3 NuVizz calls (2 RWB portal)"). "RWB portal" = just the Route-Workbench portal writes (preview / save / validate / add) — the calls that show in the real RWB HAR, so you can reconcile each action against it; the total also counts any cold-start login + safety re-reads. Server-measured as an exact before/after delta on the metered requester, so it\'s the real billed count, not an estimate.'],
  ['0.43.1', 'Customer History (the stop-card button) is now strictly READ-ONLY from our saved Firestore history — it can never make a NuVizz call. The shared history overlay used to offer a one-off "Look up PRO in NuVizz" button when you typed an unknown PRO; that stays on the top "Search past PROs" search box, but the per-customer History view opened from a stop card suppresses it entirely (shows "Shows only our saved delivery history — no NuVizz calls").'],
  ['0.43.0', 'Customer history now shows WHO DELIVERED each PRO. A new "History" button on the stop card opens that customer\'s past PROs seeded by name — each PRO now lists its delivering driver alongside the date. The driver was already captured in the nightly history warehouse; it\'s now carried into the per-customer rollup the lookup reads (no new NuVizz calls — the lookup is still a single Firestore read). New deliveries fill the driver in going forward; existing history fills in after a one-time NuVizz-FREE rebuild of the customer rollup from the warehouse.'],
  ['0.42.0', 'Routing (beta) — clicking a stop now opens its FULL detail in the RIGHT PANEL instead of a center popup, so it sits beside the map/routes. In tractor/box PAINT mode the first click does BOTH: paints the stop (green = 53′ fits, red = box only) AND opens its detail on the right. And that detail now has "Edit address" + "Correct pin location" (drag the pin) right there — the same corrections the Map screen offers, writing the same saved override so the routing pin moves live. No NuVizz calls (Firestore + client geocode only).'],
  ['0.41.0', 'Mobile Map — a persistent search bar at the top (#382: "there should be a search bar here"). Before, search on a phone was only reachable via the Stops drawer; it now sits right on the map, same as desktop (customer / PRO / city / address, with the AI sparkle toggle when available). The other top overlays (date chip, status pill, selection tools, "no stops match", live-drivers note) shifted down to make room — nothing lost, just stacked below the new search row.'],
  ['0.40.1', 'Map board — refinements to the order-left / route-right layout. (1) The search box and "Search past PROs / customer history" button now stay FIXED at the top of the left column, with the open order card sitting BELOW them — before, opening an order replaced the whole rail and hid the search. (2) Pulling up an order now AUTO-OPENS its route in the right panel for context (order ↔ route side by side) — you no longer have to click "View full route" to see it. The map still zooms to the BUILDING for an individual order (#380); the whole route is framed only when you explicitly open it (View full route, a route card, or a load row). Closing the order also closes the route it opened.'],
  ['0.40.0', 'Map board — an open ORDER now sits on the LEFT and its ROUTE on the RIGHT, so you can read a stop and walk its route side by side. Opening a route from an order keeps the order open; clicking a stop inside the route opens that order on the left WITHOUT closing the route (the search / filter / stop-list rail returns when you close the order). Map framing is now context-aware and reliable: selecting an individual stop zooms to the BUILDING, while opening a route frames the WHOLE route — and the route frame now re-fits after the side panels finish resizing, so the far stops of a spread-out load are no longer clipped off-screen behind a panel. (#388, #380)'],
  ['0.39.11', 'Routing (beta) stop popup — the assigned DRIVER now shows right at the top, under the "On load" line, so who a stop is dispatched to is the first thing you see. The duplicate Route/Driver block at the bottom of the card is removed (it just repeated the load + driver). Everything else on the full card is unchanged — Delivery Ticket, full notes, Activity Timeline, POD.'],
  ['0.39.10', '🔗 RWB engine — cross-load moves now match the portal\'s exact call profile (from a live move HAR the dispatcher captured). The portal moves a stop between two open routes with ONE multi-route saveComparedRouteData — the moved stop is simply absent from the source\'s entry and present in the destination\'s; NO validate/add calls at all. The engine now does the same: an arrival held by another load in the same Save classifies as a MOVE (no getStop, no empty-load retarget probe, no add) and ALL touched loads persist in ONE atomic combined save (1 preview per load + 1 save). The 0.39.8 move that cost 10 calls now costs 6 (2 load reads for the guard + 2 previews + 1 save + 1 landed-verify); an A↔B SWAP — previously refused as "circular, save in two steps" — now commits atomically in the same one save. Genuinely-unplanned orders still ride the proven batched validate+add with the post-add verify, and if a portal ever fails to transfer a moved stop inside the save, a one-shot fallback attaches it the proven way and re-sequences — a move can never falsely succeed. Byte-for-byte freight preservation unchanged (stops ride BY ID ONLY).'],
  ['0.39.9', 'Routing (beta) — the stop popup is now a FULL stop card, matching the Map. Alongside the existing summary (PRO / load / appointment window / restrictions / line items) it now shows a printable Delivery Ticket, the on-demand full NuVizz notes + a collapsible Activity Timeline (Planned / Dispatched / Arrival / …), the driver\'s POD photos, and the assigned Route + driver — so you can see a stop\'s activity, print its ticket, and see who it\'s dispatched to without leaving Routing. Opening the card fires NO NuVizz call (the ticket builds from the already-loaded order; the timeline loads only when you expand it; POD and Refresh are opt-in buttons).'],
  ['0.39.8', '🔗 RWB + Compare panel — FIX cross-load moves (both halves of one broken path). (1) SERVER: even with BOTH loads open, moving a stop between routes (drag / → LOAD / move menu) reduces the source load\'s stop list but sends no explicit removeStopNbrs, so the RWB stale-board guard flagged the still-on-source stop as an orphan and REFUSED the source ("has N stop(s) the board isn\'t showing"), cascading a failure to the destination — nothing moved. The guard now treats a stop that ANOTHER load in the same Save is planning as accounted-for (a staged move), while STILL refusing a stop the board truly never knew about. (2) CLIENT: selecting or ninja-clicking a stop that lives on a load NOT open in Compare used to silently do nothing (a faint status line, no staged move, no Save button — the "single route can\'t Save" report). Now the source load AUTO-OPENS into Compare with a prominent banner and the stops stay selected, so a second Send completes the cross-load move; at the 3-card cap the leftover loads are named so you can close one and retry. Cross-load moves under 🔗 RWB / ● LIVE now land.'],
  ['0.39.7', '🔗 RWB engine — FIX: a Save could report success while nothing landed on the load. NuVizz\'s addStopsToRouteAfterValidation silently NO-OPS a stop that is already planned on ANOTHER route (it returns OK but doesn\'t move it), and the 0.39.6 fast path had dropped the check that catches that — so moving a stop that lived on another load looked like it saved but placed nothing. The engine now RE-READS the load after adding and verifies every stop actually landed before it sequences/saves; if a stop couldn\'t be added it FAILS LOUDLY with "stop X is still planned on load Y — open that load in Compare to move it, or unplan it first" instead of a false success. (RWB, like the portal, can only pull a stop off a route that is part of the same Save — so cross-load moves need BOTH loads open.) Costs one extra load read per add.'],
  ['0.39.6', '🔗 RWB engine — matches the portal\'s exact call profile at scale + keeps YOUR order. Two changes: (1) the per-stop getStop that ran the steal-guard on each arrival is gone — the board already knows each stop\'s id, so the engine now uses those ids directly and runs ONE batched validateStopstoPerformAction/{id,id,…}?routeId (the portal\'s own whole-set eligibility check) instead of one getStop per stop; a 22-stop add drops from ~26 calls to ~5, right at the portal\'s number. (getStop is still used only for stops the board didn\'t enrich, and for the retarget probe on an empty load.) (2) The engine now sets the RWB_RTE_EXRTESEC=OFF preference once per session, so NuVizz never re-optimizes a saved route — dispatch-map does the optimization and the saved order is EXACTLY what you sent (seqMode Manual). Byte-for-byte preservation unchanged. If any batched call is rejected it falls back to the proven per-stop path.'],
  ['0.39.5', '🔗 RWB engine — BATCHED stop adds (production scale). Building/adding to a route used to add each order with its own validate+add call pair, so a 6-order build cost ~12 membership calls and a real 15-20 stop route would cost 30-40. Now all new orders are added in ONE addStopsToRouteAfterValidation call (the field is stopIds, plural), with the per-stop validate skipped (the add enforces it server-side). If the portal rejects the batch shape, it FALLS BACK to the proven per-stop path so a save never fails over it. Net: a warm build drops from ~22 calls toward ~6-8, and adding 15-20 stops is a couple of calls instead of dozens. Byte-for-byte preservation and the 2-call reorder are unchanged.'],
  ['0.39.4', '🔗 RWB engine — fixes "write failed" when a recurring load has TWO instances (the exact DARYL case: LOAD…113177 empty + LOAD…112852 holding the 7 stops, both named DARYL). The board groups by name, so it can open the EMPTY twin while showing the stops that actually live on the other instance; the RWB save then refused (steal guard) because the stops were "on a load not part of this Save". Now, when the opened load is empty but its ordered stops sit on ONE other load with the SAME routeName, the save RETARGETS to the instance that holds them (what the board is showing) and reorders there. Costs one extra read, only when the opened load is empty. This is the drift/persistence issue surfacing as a duplicate-instance mismatch — a proper board-vs-NuVizz reconcile (Sync) is the next step.'],
  ['0.39.3', '🔗 RWB engine — safety guard + cleanup from a self-audit. Because the RWB save is DECLARATIVE (it sets the route to EXACTLY the stops you send), a stale board that was missing a stop could have silently unplanned it. The engine now REFUSES a save if the load carries a delivery the board isn\'t showing ("refresh and retry") instead of quietly dropping it. Also removed now-dead code and corrected the Save-preview text to describe the real portal flow (validateStop + addStopsToRoute, then fetchUpdatedJson + declarative save).'],
  ['0.39.2', '🔗 RWB engine now uses the REAL Route Workbench portal flow end-to-end (reverse-engineered from a live portal capture), instead of the earlier shortcut that mixed the v7 API with the RWB save. ADDING an order to a route now goes through the portal\'s own validateStopstoPerformAction + addStopsToRouteAfterValidation (what the RWB UI actually calls), not v7 insertStops. REMOVING an order is done the RWB way — the saveComparedRouteData payload is DECLARATIVE, so a stop omitted from the save is unplanned (no separate v7 removeStops call). A single-stop route is now valid (the portal accepts it; the old "needs 2+ stops" refusal was wrong). Reordering is unchanged (fetchUpdatedJson + saveComparedRouteData). Net: plan / reorder / unplan / cross-load move all run through the same endpoints the portal uses, so behavior matches what you see when you do it by hand in NuVizz.'],
  ['0.39.1', '🔗 RWB engine — correctness fixes from an adversarial pre-prod review (all UAT-only; prod stays gated dark). (1) A load reduced to a SINGLE delivery no longer hard-fails "needs 2+ stops" after its stop was already planned — membership is the whole change, so the sequence step is skipped and the Save succeeds (this also stops a staged driver being stranded and dependent cross-load moves being cascade-blocked). (2) MEMBERSHIP reduction now rides the proven removeStops v7 op: a stop leaving a load (unplan, or the source side of a cross-load move) is explicitly removed rather than trusting RWB to drop an omitted stop — so a moved stop is truly freed before its destination inserts it. (3) saveComparedRouteData success is no longer read from HTTP status alone — a 200 carrying an application error body is now correctly treated as a failure. (4) RWB refuses up-front when its portal creds are unset, before any v7 membership write, so an enabled-but-credentialless deploy can never half-mutate a load. (5) The route window offset is computed DST-correctly from the route timezone instead of a hardcoded EDT literal.'],
  ['0.39.0', '🔗 RWB engine (dark by default) — a THIRD Compare-panel Save engine alongside ⚙ Classic and ⚡ Import. RWB drives NuVizz\'s own Route Workbench portal to set a load\'s stop order in 2 SYNCHRONOUS calls (preview + save) — no async wait, no poll/re-send/reverse-unstick ladder, because the save either lands or errors in-band. Critically, it references stops BY ID ONLY and never re-sends the stop record, so freight/address/item data cannot be blanked or cloned by an incomplete echo (the exact failure class behind the Jul 2 Import incident) — proven byte-for-byte against UAT: before/after stop snapshots differed ONLY in seq/ETA/leg-distance/audit fields. MEMBERSHIP (planning arrivals onto the load) is unchanged — the same insertStops + steal-guard + sources-before-destinations ordering as the Import engine. Server gate NUVIZZ_RWB_ENABLED stays OFF by default; its own login (NUVIZZ_RWB_USER/PASS) defaults to the UAT portal regardless of which NuVizz tenant this deploy\'s v7 API writes to, so enabling it can never reach production without a deliberate separate env change (same bar as Import).'],
  ['0.38.10', 'Routing (beta) — the Routes panel now has a "Dispatch" button on each route card, next to the driver-assign dropdown. It calls the existing dispatchLoad op (NuVizz action DISPATCH) to move an already-assigned load out of Draft/Un-Planned. Same Beta/Live safety as driver-assign: a click only previews in Beta, and fires for real once you flip to ● Live. Disabled until a driver is assigned, and hidden once the route is already In-Transit/Completed/Cancelled.'],
  ['0.38.5', 'Mark vehicle eligibility — one brush now sets BOTH colors. With the Tractor brush armed (⚙ → Mark vehicle eligibility → Tractor OK), clicking a stop marks it green (53′ fits); clicking the SAME stop again marks it red (box truck only); a third click clears it. Before, the second click just cleared the mark and you had to switch the brush to Box to mark red. The Box brush mirrors it (red → green → clear). No need to flip the radio to correct a stop — just click it again.'],
  ['0.38.4', 'The stops status pill is now on Routing (beta) too — the same "N stops / total pallets / Loads+Orders feed freshness / NuVizz calls + by-hour chart" card from the dispatch Map now sits top-right on the routing map (below the ⚙ map filters), so you can see board freshness and the call meter without leaving the routing screen. Same collapse toggle (shared with the Map\'s pill) and the same refresh button firing the cheap ~4-call scan — never the expensive number-probe.'],
  ['0.38.3', 'Print Manifest pagination fix (round 2, from Chad\'s printed page photo): tickets were still mashing together — ticket 2 started on page 1 and only ONE page came out. The 0.36.1 print bridge was correct, but the app shell\'s "lock the app to the viewport" CSS (body position:fixed + overflow:hidden, for iOS scroll containment) still applied DURING printing — and inside a fixed, viewport-clipped body the browser can\'t paginate at all: the one-ticket-per-page breaks are ignored and everything past the first page is clipped. The bridge now lifts that lock for the duration of the print (static body, visible overflow, auto height — print only; the on-screen app is untouched), so page breaks paginate again: page 1 = route summary + ticket 1, then one ticket per page. Verified with a real headless-Chrome print-to-PDF: before the fix 3 tickets → 1 page, after → 3 pages. Applies to the Delivery Ticket and BOL viewers too (same viewer).'],
  ['0.38.2','New "Quote" tab in the top bar (next to New Order) — the shared Uline rate console, the same pricing tool that lives in the quoting app, now embedded right here so you can price a shipment without leaving Dispatch. It reads live from the shared quote source (DavisDelivery/Quotes) at build time, so rate/fuel/zone changes there show up here on the next deploy — no re-copying. Enter a destination ZIP + weight (+ skids/loose) and it prices instantly; nothing here touches NuVizz.'],
  ['0.38.1', 'UAT PROD-MIRROR support: the Firestore DATABASE is now env-selectable (FIRESTORE_DATABASE server-side, VITE_FIRESTORE_DATABASE client-side; unset = the production default, unchanged). Lets the 1:1 UAT mirror of this app (deployed from dispatch-beta2/prod-mirror against uat.nuvizz.com DAVISV5) keep its scans/journals/counters/notes in a fully separate named database in the same Firebase project. SAFETY INVARIANT: a deploy pointed at UAT NuVizz with no named database REFUSES Firestore entirely (loud log) rather than ever mixing UAT rows into the production board data.'],
  ['0.38.0', 'The ⚡ Import engine is REBUILT on the two-lever design and Bulk Add gains "Create as → ⚡ A NEW load". After the Jul 2 incident (import "references" CLONED off-load orders and FULL-REPLACED matched ones — freight wiped), the real NuVizz semantics were pinned on UAT and the engine now makes both failure modes structurally impossible: MEMBERSHIP only ever moves your real orders (insertStops/removeStops by internal id — an off-load order number can never appear in an import), ORDER is one import whose entries are FULL ECHOES of the load\'s own records (freight + references included, so nothing can be blanked), and CREATE (the Bulk Add new-load mode) sends full payloads only after per-number existence checks (a colliding order number is refused, never cloned). Anatomy: plan-10-unplanned ~4-5 calls, inject-middle ~4-5, reorder ~3-4, full re-optimize ~3-4 — every save confirmed by read-back. STILL DARK: the server gate from v0.36.3 stays default-OFF; enabling on prod is an explicit env flip after a prod validation.'],
  ['0.36.3', '⚡ IMPORT ENGINE DISABLED server-side (Jul 2 incident). Production NuVizz treats import "reference" stops as full replaces — a Save through the import engine wiped the freight (skids/loose/weight) off 10 orders and created 10 empty unplanned copies, violating the UAT-verified contract that referenced stops keep their other fields. Until that\'s understood and re-verified, the server refuses ALL import saves regardless of the in-app toggle (Saves with ⚡ selected automatically fall back to the classic engine — nothing dead-ends) and it stays off unless explicitly re-enabled on the server. Also: stop reads now surface freight (skids/loose/weight/pieces) and audit (created-by/when) fields, so originals can be told apart from import-created copies during the repair.'],
  ['0.36.2', 'Board write-through (#361) — planned orders no longer show UNPLANNED after a Save. Before: a confirmed Save changed NuVizz immediately, but the board only learned about it at the next scheduled scan — and NuVizz\'s own list feed can lag an async import by minutes, so even a fresh scan could re-assert the stale "unplanned". Now, the moment a Save is CONFIRMED (the import engine\'s order read-back matches, or a classic save\'s steps all succeed), the app patches the verified plan straight into the board cache (zero NuVizz calls — it\'s state the Save already verified) and re-reads it: the stops flip to planned on the right load, in the confirmed order, immediately. The next scans can\'t revert it either — a confirmed write outranks a lagging list row for 20 minutes, releasing as soon as the list catches up. Works for planning, unplanning (removed orders flip to unplanned), reorders, and cross-load moves.'],
  ['0.36.1', 'Print Manifest pagination FIXED for real — no more one mashed page. The Print button used to open a popup window to print from; when the browser silently blocked that popup, it fell back to printing the on-screen (scaled) preview, which collapses the whole manifest onto a single page — the "everything mashed together, only one page came out" report. Printing now uses a hidden print-only copy of the document rendered straight into the page: nothing to block, no popup, and the per-ticket page breaks paginate natively — page 1 is the route summary + delivery ticket 1, then exactly one ticket per page (verified in a real Chrome print render: 4 tickets → 4 pages). Bonus: pressing Cmd/Ctrl+P with the manifest viewer open now ALSO prints the paginated manifest instead of a screenshot of the app. Applies to the Delivery Ticket and Bill of Lading viewers too (same viewer).'],
  ['0.36.0', 'Save-cost overhaul for the ⚡ Import engine — a reorder Save was burning ~27 NuVizz calls chasing the async worker (measured live: 3 SUW reorganizations = 80 calls, 9 imports + ~64 read-backs) and STILL reporting failure for orders that landed. Three changes from the investigation: (1) VERDICT on the comparator — it was NOT broken (the journal proved the mismatches were real), but it\'s now normalized anyway (zero-padding/case/typing can never read as "not converged") and every poll\'s read-back is journaled. (2) The wait now matches the worker: prod takes ~30-90s to seat an import, so the client polls on a BACKOFF (6/10/15/25/25s — ~5 polls, NO writes) instead of re-Saving every 18/45s; then at most ONE same-order re-send; then at most ONE reverse+forward UNSTICK — the §10.1 cure for the stuck-append state we hit (two moved stops kept landing at the tail across nine same-direction re-sends; same-direction NEVER clears it). (3) Every Save now self-reports its call anatomy (X imports + Y read-backs) in the result, console, and write journal. Typical converging Save: 1 import + 2-4 reads. Worst case (full ladder): ~4 imports + ~12 reads over ~4 minutes — and it says so honestly.'],
  ['0.35.3', 'Bulk Add moved UNDER New Order — it\'s no longer its own top-level tab. Open "New Order" and you\'ll see a "Single order / Bulk add" toggle right at the top; Bulk add is the exact same grid + spreadsheet-import screen as before, just reached from inside New Order instead of a separate tab. The choice is remembered on your device. Nothing about either form changed — same pickup locations, same Beta/Live gating, same per-row Create behavior.'],
  ['0.35.2', 'FIX — the re-sequence dropdown could get STUCK on a strategy you\'d already used. Repro (reported live): apply "Farthest first", then hand-move an order to the middle — some edit paths (moving a stop off a card, ninja-add, "send selection", undo-remove) left the dropdown still claiming "Farthest first", and picking Farthest again did NOTHING (a dropdown fires no event when you pick the value it\'s already showing), so the route couldn\'t be re-optimized or saved. Now EVERY hand-edit flips the card to "Manual order (edited)", which keeps every strategy re-applicable — optimize, tweak by hand, re-optimize, as many times as you like. Bonus fix: re-sequencing a route whose stops haven\'t geocoded yet used to announce "Re-sequenced" while silently doing nothing — it now tells you plainly why it can\'t and to retry in a moment.'],
  ['0.35.1', 'FIX — "re-optimize failed" when NuVizz actually said YES. The live re-sequence Save fired the one-call import and PROD answered "Request for LOAD Async import is SUCCESS. Find more info in AppMessageLog with Id- …" — but prod words the ack differently than UAT (the whole sentence in the status field, and "AppMessageLog WITH Id"), so the stricter 0.33.7 parser read that SUCCESS as a rejection, aborted before the order-verification read-back, and showed a failure banner. The parser now accepts a status containing the standalone word SUCCESS (still rejecting PARTIALSUCCESS/FAILURE/…-with-errors wording) and extracts the AppMessageLog id through prod\'s phrasing. The exact journaled prod ack is a regression test. Re-Save the route — the import is declarative, so re-sending the same order is always safe, and the read-back now confirms it seats.'],
  ['0.35.0', 'Bulk Add — a new tab to create MANY orders at once. Two ways in: (1) fill an editable GRID of rows (Add row / Clear, each row shows ✓ ready or "need N" so you know what\'s missing before you send); (2) IMPORT a spreadsheet — drop a .xlsx or .csv, or paste rows straight from Excel/Google Sheets. The importer auto-detects your header row and maps the columns (consignee, address, city, state, zip, item, order#, PRO, pallets/cartons/weight); you confirm/fix the mapping once and it\'s remembered for that layout next time. Pickup location + service date are set ONCE for the whole batch (same saved-pickup picker as New Order). ○ Beta previews the count; ● LIVE creates them one at a time (each with its own idempotency key, so a mid-batch retry never duplicates). Successful rows drop off; any failures stay in the grid with the reason so you can fix and re-send. New orders land UNPLANNED — plan them onto loads in Routing.'],
  ['0.34.0', 'New Order: item description + multiple pickup locations + the Save-origin fix. (1) New "Item description" field (what\'s being delivered) rides along on the order (stored on NuVizz reference2 — read back on the first live create to confirm it sticks). (2) Pickup (ship-from) is now a SAVED LIST, not a single default: pick a location from the dropdown, or type a new one and "Save pickup location" — for when you\'re picking up from other places. (3) FIX: "Save as default origin" appeared to do nothing — it was silently saving an INCOMPLETE origin with no feedback (the placeholders "Buford"/"30518" look like real values but the fields were empty). The Save button is now disabled until every pickup field is filled, flashes "✓ Saved" when it works, and says "fill all pickup fields to save" when it can\'t. (Bulk multi-row entry + spreadsheet import is coming next.)'],
  ['0.33.10', 'Loads grid — new "Load ID" column, right after "% Done" (dispatch Map + Routing bottom panel, per debug report #352). Shows NuVizz\'s real load number (e.g. DAVIS000198197) — the "Load" column shows the friendly route name, which is all the stops feed carries; this reads the real id from the day\'s loads roster instead, matched by route name. Sortable; "—" when the roster hasn\'t resolved a number for that load yet.'],
  ['0.33.9', 'Tomorrow\'s roster: back to ONCE a day — but the capture only counts when the NUMBERS came through. Chad\'s correction to 0.33.8: tomorrow\'s load set is fixed once it exists, so there\'s nothing to re-pull every 15 minutes — the real Jul 1 failure was that the morning capture ran with the old parser (before the Load-Number column fix in 0.32.25 deployed), wrote every row with NO number, and the "non-empty → done" rule froze that number-less snapshot for the whole day. Now the scan re-tries each cycle ONLY until a roster with real DAVIS000… numbers lands, then stops for the day — steady state one cheap loads-list call per day, self-healing if a capture ever comes back number-less again (bad column/parser/NuVizz hiccup). Manual Refresh stays the on-demand override.'],
  ['0.33.8', 'Plan TOMORROW\'s loads TODAY — the scheduled scan now keeps tomorrow\'s loads roster fresh ALL DAY instead of freezing it at the first morning snapshot. Verified against the live scan (Jul 2): every one of tomorrow\'s loads already carries its real DAVIS000… Load Number the moment it exists — the app just wasn\'t pulling them in until the next morning, which is why loads created during the day reached the evening board number-less. Now a portal-created load (and its number — the key every Save wants) reaches the board within one scan interval (~15 min), so resequencing/unplanning resolves directly; the 0.33.5 seed-then-build remains the fallback for a card that still lacks its number. Cost: one cheap loads-list call per scan cycle — never the number-probe.'],
  ['0.33.7', 'Import engine HARDENING — every confirmed finding from a four-agent adversarial audit of the import path, applied before the next live test. The big ones: (1) the background order-verification\'s automatic re-send now sends ORDER ONLY — it can no longer invisibly assign/dispatch and then have the follow-up Save dispatch the driver a SECOND time; it also reuses the already-resolved load number instead of re-resolving (no chance of a stray re-seed). (2) In a multi-card Save, a load receiving a stop from another card now WAITS until that source card\'s rebuild is confirmed — the untested "steal" can never fire. (3) Assign/dispatch (and other one-shot writes) are never transport-retried, so a flaky network can\'t double-dispatch a driver. (4) Order verification is stricter — a load read back mid-rebuild before NuVizz assigns real stop sequence numbers can\'t be mistaken for "confirmed". (5) Stop references are normalized to the proven shape (GA/USA, clean windows, no unproven fields), the origin street line is cleaned of NuVizz\'s duplicated city/state/zip tail, and real error details are never buried behind a bare "Bad Request". Plus: a newer Save now supersedes an older card\'s background verification; failed Saves report when an order was physically seeded onto a load; and one guaranteed-dead lookup call per Save is skipped.'],
  ['0.33.6', 'FIX (from the write journal — the import finally FIRED and NuVizz told us exactly what it hated): the seed worked and the load number resolved (DAVIS000198073), but NuVizz rejected the import with a 400 JSON parse error. Our tenant\'s load record carries an "origin" field that is an ADDRESS OBJECT (plus long-form "GEORGIA" / "UNITED STATES"), and the header echo sent it where NuVizz expects a plain string code. The header builder now string-coerces every origin field (the object can never be echoed; the code falls back to the proven WHSE), normalizes states to 2-letter and country to USA to match the verified import shape, drops any object that sneaks into an echoed address field, and the payload builder hard-refuses any non-string header value before a single NuVizz call. The exact journaled header that failed is now a regression test.'],
  ['0.33.5', 'FIX (found via the new forensics): building a load from unplanned orders NEVER reached NuVizz — every Save refused with "reorder/unplan needs a load number". Why: an EMPTY Draft load only exists in the app as its internal id — NuVizz\'s loads roster carries no real load number on our tenant, the id→number lookup endpoint is HTTP 501 here, and an empty load has no stops to read the number from. So the server could never key the load and refused before writing anything. Fix: SEED-THEN-BUILD — the Save now plants your FIRST order onto the load via the id-keyed insert (the proven path), reads that order back to learn the load\'s real number, then proceeds normally: ⚡ Import rebuilds the full list in your exact order (the seeded order gets seated too); ⚙ Classic runs its usual anchor plan with the seeded order as the anchor. Works for both engines, costs 3 extra calls, never touches an order that\'s planned on another load, and cancel-intent (emptying a load) never seeds anything.'],
  ['0.33.4', 'Import-engine FORENSICS — the ⚡ Import Save now leaves a complete audit trail so a "sent but nothing landed" is diagnosable instead of a mystery. Every import records exactly what was sent to NuVizz (the load header + the stop order) and exactly what NuVizz answered (the verbatim ack + AppMessageLog id), plus every order read-back — into the save result, the browser console, and the server\'s write journal. New read-only endpoint /.netlify/functions/nuvizz-write-log returns the last few Saves\' full trails straight from our own journal (zero NuVizz calls). If the background verification gives up, the console now logs the whole trail (what we asked for vs every read-back).'],
  ['0.33.3', 'HOTFIX — the first live ⚡ Import Save died silently: nothing landed on the load. Root cause: the write endpoint ran on Netlify\'s DEFAULT 10-second budget, and the import Save (read the load + read each unplanned order + fire the import + verify the order landed) got killed mid-flight. Fixes: (1) the write endpoint now gets the full 26s; (2) the per-order reads run in parallel instead of one-by-one; (3) the order-verification no longer tries to fit inside one server call — the server fires the import, does a quick check, and the APP keeps verifying in the background (cheap load read-backs every ~6s, with an automatic re-send nudge if NuVizz is slow to seat it), toasting "✓ order confirmed" the moment the read-back matches — or telling you plainly if it never does. Driver/dispatch on an import Save now wait until the order is CONFIRMED (Save again after the ✓ to apply them). Also hardened: an empty load\'s import origin now comes from the orders\' own ship-from address in NuVizz (no dependence on the browser\'s saved origin), and a non-date value in the load header can no longer trip NuVizz\'s silent import failure.'],
  ['0.33.2', 'Routing — the LOAD IMPORT engine is now YOUR toggle, not a server switch. The Compare panel header has a new "⚙ Classic / ⚡ Import" button next to ○ Beta / ● LIVE: flip it to ⚡ Import and every Save (preview and LIVE alike) runs each changed load through the new one-call import + order-verification read-back; flip back to ⚙ Classic and the Save is exactly the old engine. The choice is remembered on your device, and the Save-preview names the engine ("IMPORT ENGINE") so you always know what will fire before you Confirm. No Netlify env var to set — the only server flag left is an emergency hard-off brake (and the master write switch, unchanged).'],
  ['0.33.1', 'Routing — your normal Compare-panel Save can now drive the new one-call LOAD IMPORT path (still OFF by default). Nothing changes in how you work: build loads from unplanned orders, stage them in Compare, order the stops, Save through the ○ Beta / ● LIVE toggle exactly as before. When the server\'s NUVIZZ_LOAD_IMPORT switch is ON, that same Save runs each changed load as ONE declarative import (echoing NuVizz\'s own address records — nothing is retyped) plus the convergence read-back, instead of the anchor remove + re-insert engine; the Save-preview tells you which engine will fire ("IMPORT MODE"). Planning unplanned orders, reorders, and cross-load moves (source before destination) all go through the import; emptying a load (cancel), driver-only saves, and anything the import can\'t resolve still use the proven legacy path. Your saved New Order ship-from rides along as the origin for empty loads. Flip the switch off and the Save is byte-identical to before.'],
  ['0.33.0', 'Live dispatch (server, OFF by default) — the new one-call LOAD IMPORT sequencing path. NuVizz\'s async load import (load/update/default) can set a load\'s COMPLETE stop list in exact order in ONE call per load: plan = import the full desired list, unplan = import without those stops, resequence = import the same set permuted — replacing the anchor + remove + one-at-a-time re-insert engine (which stays the active default for now). Because the import is async and can silently not land, every import is driven to CONVERGENCE: the server re-reads the load, compares the real delivery order (to.seq), re-sends if needed, and applies the verified reverse-then-forward unstick — a Save only reports success from the read-back, never from NuVizz\'s "SUCCESS" ack. Double-gated: needs BOTH the existing server write flag AND the new NUVIZZ_LOAD_IMPORT flag, which stays OFF until the verification checklist passes on a throwaway load with sign-off. No UI change yet.'],
  ['0.32.30', 'Bug-hunt wave 2 — eight fixes across live dispatch, the board scan, and New Order. (1) Ninja/selection can no longer pull a stop onto a card when its own load isn\'t open in Compare — that save would have DOUBLE-PLANNED the stop (it was never removed from its real load); the server refuses the same case as a backstop. (2) Changing the board DATE now closes the Compare cards — a surviving card could save today\'s edits onto YESTERDAY\'S load. (3) With "Unplanned only" on, stops staged onto a card no longer vanish from the card/printed manifest while still being saved — what you see is what commits. (4) A rolled-over order delivered today now actually turns delivered on the board (its completion was landing on yesterday\'s never-written board while today\'s kept the stale open copy). (5) CANCELLED orders now reach the board (as exceptions) instead of freezing as live work you could still route. (6) Two same-day loads sharing a name can\'t be opened as one card or cross-wire each other\'s identity on assign/save. (7) New Order: retrying after a network drop can\'t create a DUPLICATE order (same idempotency key until success), and (8) if a typed Order # already existed, it now warns loudly that NuVizz UPDATED that existing order instead of announcing a clean "created."'],
  ['0.32.29', 'HOTFIX (from a full-codebase bug hunt) — two regressions: (1) after a successful ● LIVE Save, the Compare panel crashed internally before showing the "✓ saved" toast (a 0.32.27 cleanup referenced state it couldn\'t reach) — the save itself went through, but you got NO confirmation, no orphaned-stops warning, and staged removals weren\'t cleared. Save feedback is back. (2) Clicking an EMPTY ("No orders yet") load in the Loads grid opened a card that couldn\'t save or assign — since 0.32.25 that row is keyed by the real Load Number, which the load lookup didn\'t recognize. Empty loads open properly again.'],
  ['0.32.28', 'New Order — create a delivery order without leaving Dispatch. A new "New Order" tab at the top opens a form: type the consignee name + address (+ optional order number, PRO, pallets/cartons/weight and service date) and Create. The ship-from origin is set once (saved on your device) and reused. Like the other live actions it has an ○ Beta / ● LIVE switch — in Beta a Create only previews, in ● LIVE it creates the order in NuVizz (also needs the server write flag). A new order lands UNPLANNED — plan it onto a load in Routing.'],
  ['0.32.27', 'Live dispatch (beta) — HARDENING pass (from a full write-path audit), several "reported success but didn\'t persist" and "silently dropped" bugs closed: (1) assigning a driver from the Routes list now resolves the load\'s real internal id first — a Draft load could otherwise get "Success" from NuVizz while nothing was actually assigned (re-confirm any recent Draft assigns in the portal). (2) Emptying/cancelling a load no longer tries to assign/dispatch the now-cancelled route. (3) Dragging a brand-new order to the FRONT of a load now refreshes the load version before removing the rest, so the remove can\'t be rejected and leave the load half-changed, and it won\'t pre-insert a stop still on another load. (4) A partial/failed NuVizz response is no longer read as success. (5) The panel no longer silently discards a staged driver/unplan when some stops aren\'t loaded yet, no longer re-sends an already-unplanned stop on the next Save, and reliably clears a saved load\'s dirty state.'],
  ['0.32.26', 'Live dispatch (beta) — FIX: after unplanning an order off a load, adding that SAME order back and saving did nothing ("Nothing to send"). The order was genuinely off the load and needed to be re-planned, but the server was only matching the desired stops against the load\'s CURRENT stops — so a stop being ADDED back (not currently on the load) was silently dropped instead of inserted. The server now resolves an added stop by its number and plans it back onto the load, so re-adding an order you just removed actually sends it to NuVizz.'],
  ['0.32.25', 'Live dispatch (beta) — the daily Loads scan now captures each load\'s real Load Number (DAVIS0001…) once the "Load Number" column is present in the loads saved search — verified live, all 99 loads now carry their number. That means resequencing, unplanning, and driver-assign on a Draft load resolve the load DIRECTLY from the scan with ZERO extra NuVizz calls (the per-load stop-lookup bridge added in 0.32.24 is now just a fallback). Internal: removed the temporary column-diagnostic endpoint.'],
  ['0.32.24', 'Live dispatch (beta) — FIX (the real one): unplanning/resequencing a Draft load reported success but nothing changed in NuVizz. Root cause found by testing live: the app couldn\'t look up the load\'s real number (DAVIS0001…) for a Draft — the two lookups it tried are both dead on our tenant (the loads scan\'s saved search has no load-number column, and the load/static/info bridge returns "not implemented"). So the remove either errored or never got the number, and the removal never fired. The server now gets the real number the reliable way — by reading a stop that\'s already on the load (its own load membership carries the number) — then runs the remove. Confirmed live: the remove now actually comes off the load. (Once the load-number column is added to the loads saved search in the NuVizz portal, this needs zero extra lookups.)'],
  ['0.32.23', 'Live dispatch (beta) — FIX: assigning a driver to a load from the Routes list failed with "Can\'t assign — its NuVizz load id hasn\'t loaded yet" for a Draft/empty load (one with no orders opened yet). The Routes row only learns a load\'s internal id once its stops are opened, so a Draft had none. It now pulls the load\'s internal id (and real Load Number) from the daily Loads scan — the same source the reorder path uses — so you can assign a driver straight from the Routes list without opening the load first.'],
  ['0.32.22', 'Live dispatch (beta) — FIX: resequencing/unplanning a load and saving in ● LIVE failed with "commitBoard: load not found (loadNbr=…)". The Compare panel was sending the load\'s NAME ("SUW") as its number, but NuVizz\'s load lookup is keyed by the real Load Number ("DAVIS000198197"). That number is right there in the daily Loads scan (the "Load Number" column) — the app was capturing the load NAME and throwing the number away. The scan now grabs the real Load Number for every load and uses it for the lookup, so resequencing and unplanning work with NO extra NuVizz calls (previously it took a bridge call to look the number up from the internal id). If a load\'s number hasn\'t been picked up from the scan yet, that bridge lookup still covers it, and Save gives a clear "needs the load number — refresh and retry" instead of the confusing "load not found."'],
  ['0.32.21', 'Live dispatch (beta) — reorder path: three improvements. (1) Reoptimizing/reordering a load opened from the Loads grid now WORKS — the app looks up the load\'s real number from its internal id (load/static/info) and runs the proper unplan → replan, instead of failing with "Only unplanned stops can be planned" or telling you to open it from the board. (2) Fewer NuVizz calls per reorder — it keeps the part of the order that\'s already correct at the front and only moves the stops that actually changed (appending to an in-order load makes zero removals). (3) A brand-new order that becomes the FIRST delivery is now handled — it\'s put on the load first (so the load always keeps an anchor and never cancels), then the rest are removed and replanned in order.'],
  ['0.32.20', 'Live dispatch (beta) — FIX: unplanning orders from a load and saving in ● LIVE did nothing, and there was no way to take the last (anchor) order off a load. Two wiring bugs: (1) the removes were keyed by internal stop id, but board rows don\'t carry a stop id until you open each stop, so the anchor had none and the whole load got silently dropped from the Save — nothing fired. The panel now sends the always-present stop NUMBERS and the server resolves them to stop ids from the load itself, so unplanning works without opening every stop. (2) Taking the LAST order off a load now EMPTIES and CANCELS the route (the documented "remove all deliveries" flow) instead of silently succeeding with no change. Save now reports honestly — it tells you how many loads actually fired, how many cancelled, and if nothing changed it says so instead of a false "saved."'],
  ['0.32.19', 'Routing (mobile) — FIX: when both the Stops/Loads data grid AND the Setup/Compare sheet were open, the grid grew taller than the shrunken map area and its toolbar (the row with the collapse ⌄, the Stops/Loads tabs, and search) got pushed up behind the "selected/Filters" chips — so you could see the rows but had no way to collapse the grid (#327). The grid is now capped to the visible map height, so its toolbar (and collapse control) always stays put with both drawers open.'],
  ['0.32.18', 'Live dispatch (beta) — FIX: adding orders to a load opened from the Loads grid failed with "commitBoard: load not found." That load is known only by its internal id (hex loadId), which was being sent as the load NUMBER — but NuVizz\'s load lookup is keyed by the human load number (e.g. DAVIS000000123), so it 404\'d. The app no longer sends the hex id as a load number, and the server now plans the orders straight onto the loadId (the documented insert flow) when there\'s no human load number to look up. Add orders in ● LIVE → Save → they plan onto the load.'],
  ['0.32.17', 'Routing (mobile) — FIX: the Lasso selection wouldn\'t apply once you already had a route in the Compare panel. The "Done" button that finishes a lasso lived in the Setup panel\'s Select-stops section, which is replaced by the Compare workbench as soon as a route is built — so you could tap out the polygon but had no way to finish it, and nothing got selected. There\'s now a floating Done / Cancel control right on the map whenever Box or Lasso is armed, so you can close the lasso and select the stops inside it no matter what the bottom panel is showing.'],
  ['0.32.16', 'Routing — tomorrow\'s (next business day\'s) EMPTY loads are now ready first thing in the morning. The next-day load roster (the Draft/empty load shells, before any orders are on them) used to only get cached in the 8pm-midnight scan window — so during the day the Routes/Loads view showed tomorrow\'s stops but none of its empty loads. The roster is the cheap load-list call (not the expensive load-number probe), so it\'s now pulled once each morning, a day into the future, decoupled from that evening load scan — and it keeps trying through the day until tomorrow\'s loads actually show up, then settles. Empty loads for the next business day are ready to plan against in the morning.'],
  ['0.32.15', 'Live dispatch (beta) — driver-assign FIX (corrects 0.32.13). Two wiring problems: (1) the assign action was changed to plain "ASSIGN" in 0.32.13, but the verified NuVizz portal call is "ASSIGN_DISPATCH" — reverted, so the assign matches what actually works. (2) For an empty/Draft load (no orders yet) the app could send the load\'s ROSTER id as the assign target instead of the load\'s internal id; NuVizz answers "Success" but never persists it. The server now resolves the real internal load id (load/info) before assigning whenever the id it was handed isn\'t already the internal one. Note: the board can\'t SHOW a just-assigned driver until the next scheduled scan re-reads NuVizz (the load roster carries no driver field) — confirm an assignment took in the NuVizz portal\'s Loads grid, not by refreshing the map.'],
  ['0.32.14', 'Header — the top "Dispatch" bar is pinned on every screen. The desktop header can no longer be squeezed out by tall content (it never shrinks now), and both the mobile and desktop headers sit above the page content (z-index) so nothing can scroll over or cover them. The bar stays put on Map, Routing, and Diagnostics.'],
  ['0.32.13', 'Live dispatch (beta) — FIX: assigning a driver now actually STICKS. The assign call used NuVizz\'s "ASSIGN_DISPATCH" action, which assigns AND dispatches the route — but you can\'t dispatch an empty/Draft load (nothing to dispatch), so NuVizz accepted the call yet the assignment never persisted (and for any load it was silently dispatching when you only picked a driver). Switched the driver-assign to the plain "ASSIGN" action (assign carrier + driver only); dispatch stays the separate Dispatch checkbox. Pick a driver in ● LIVE → Save → the driver now holds after a refresh.'],
  ['0.32.12', 'Live dispatch (beta) — FIX: assigning a driver to (or dispatching) a Draft/empty load now works. Opening an empty load (no orders yet) gave it no loadId, so Save hit "commitBoard: load not found" — NuVizz needs the load\'s ID to assign anything to it. The Compare panel now resolves the real loadId from the load itself (empty loads are opened BY their loadId) and the day\'s load roster, so Save assigns straight off the loadId with no load/info lookup. The card also shows the load\'s real name (e.g. "NOR") instead of "Unnamed load". Verified across the open → stage → Save → assignDriver path (and against the NuVizz API spec: the assign routeId IS the loadId).'],
  ['0.32.11', 'HOTFIX — the Routing (beta) screen was crashing to a blank page (most visible on mobile, but it hit desktop too). The driver-assign code added in 0.32.5 sat ABOVE the toggles it reads (liveWrite / the on-map toast) in the component, so React threw "Cannot access \'liveWrite\' before initialization" the moment Routing opened. Moved the block below those declarations; Routing loads again. No feature changes.'],
  ['0.32.10', 'Dispatch Map — a "Routes" panel you can turn on. A new "Routes" button in the map\'s top-right toolbar opens a read-only route roster on the right (the same one the Routing screen has): one card per load with route name, driver, status (incl. Draft / Un-Planned from NuVizz\'s real load status), stops · skids · loose · weight, and a delivery-progress bar — plus the Status filter and quick-search. Click a card to frame that route on the map and open its detail. The toggle is remembered (off by default), and the panel pulls NuVizz\'s real load status from the cheap cached roster only while it\'s open.'],
  ['0.32.9', 'Live dispatch (beta) — the "Assign driver…" dropdowns (both the Compare panel and the Routes-panel assign picker) now list drivers in ALPHABETICAL order by name, instead of NuVizz\'s user/list order. Sorted at the roster source so every driver picker is A→Z.'],
  ['0.32.8', 'Live dispatch (beta) — diagnostic for "load not found" on Save. When a Save still can\'t resolve a load, the error now names the EXACT load number it queried and NuVizz\'s response — e.g. "load not found (loadNbr=\\"DAVIS000…\\", load/info HTTP 404)" — and distinguishes a 404 (NuVizz doesn\'t recognize that load number) from a 200 with no loadId (unexpected response). The browser console also logs the full payload sent + per-load result, so the failing load number can be copied back verbatim. Pin-points whether production Saves are sending the wrong load number or hitting a load the write account can\'t see — no behavior change to the commit path.'],
  ['0.32.7', 'Loads grid — new "% Done" column. The bottom Stops/Loads grid (on both the dispatch Map and Routing screens) now shows each load\'s delivery progress as a percent (delivered ÷ stops), green at 100%, right after the Stops count. Sortable like every other column; empty "No orders yet" loads show "—".'],
  ['0.32.6', 'Routing (beta) — remove an order from a route in the Compare panel. Each stop now has an × button; click it and that order is dropped from the load and listed under "Removing N order(s)" with an Undo. Nothing happens until you Save — on Save the removed orders become UNPLANNED in NuVizz (back to the pool), and the Save preview now spells this out ("unplan N order(s)") before you confirm. Staged like every other Compare edit; Undo restores an order before Save.'],
  ['0.32.5', 'Routing (beta) — assign a driver straight from the Routes panel. With Live dispatch on (⚙ → Panels → "Live dispatch"), each route card gets a driver dropdown of your full roster; pick one and it assigns that driver to the load. A Beta/Live toggle sits next to the Status filter — in ○ Beta a pick only previews (nothing sent), in ● LIVE it assigns in NuVizz immediately (assign only — it does NOT dispatch/notify the driver; that\'s still the Compare panel\'s Dispatch step). The card shows the new driver right away. As always a real write also needs the server NUVIZZ_WRITE_ENABLED flag.'],
  ['0.32.4', 'Routing — the Routes-panel Status filter now reflects NuVizz\'s REAL load status, so a "Draft" option appears (plus Un-Planned, In-Transit, Cancelled) to match the NuVizz route grid. Until now the status was derived purely from each route\'s stop execution + driver assignment, so there was no way to see a Draft (or Un-Planned / Cancelled) load. The panel now reads each load\'s actual lifecycle status from the day\'s load roster (the cheap list path, served from the scan cache — no extra number-probe scan) and falls back to the derived status only when a load has no roster status yet. The filter always offers the full NuVizz lifecycle (even at count 0) and never hides a status that\'s actually on the board.'],
  ['0.32.3', 'Live dispatch (beta) — fixes "commitBoard: load not found" when saving a Compare-panel change (re-order, driver assign, or dispatch). The panel was sending the route\'s DISPLAY name (routeName, e.g. "LVILLE") to NuVizz as the load number, but NuVizz\'s load lookup is keyed by the REAL load number (e.g. "DAVIS0000…", from the daily load scan). The Compare panel now captures and sends each route\'s real load number, so Save resolves the live load and commits. The confirm preview still shows the friendly route name.'],
  ['0.32.2', 'Routing (beta) — pulling up a route now always shows it on the map, even with "Unplanned only" on. Opening a route in the Compare panel (from the Routes list, a Loads-grid row, or a stop\'s "Open in Compare") draws that route\'s stops + sequence line in full regardless of the filter — the filter still hides every OTHER planned stop, so the pulled-up route reads clearly against just the unplanned board. Close the route and its planned stops hide again.'],
  ['0.32.1', 'Routing (beta) — the Live-dispatch (driver assign + dispatch) controls now have a gear toggle. Open the ⚙ gear → Panels → "Live dispatch (assign driver + dispatch)" to show/hide the Compare-panel driver picker, Dispatch checkbox, Save, and the Beta/Live toggle — no more ?write=1 URL flag needed (the flag still works and seeds the toggle the first time). The setting is remembered. As before, nothing is sent to NuVizz until you switch a card to Live and Save → Confirm, and a real write also needs the server NUVIZZ_WRITE_ENABLED flag.'],
  ['0.32.0', 'Routing — the right-panel Routes view is upgraded to read like NuVizz. Route cards are now sorted ALPHABETICALLY by route name (was grouped by driver), and there\'s a Status filter (Unassigned / Planned / In Progress / Completed / Exception, multi-select) plus a quick-search box at the top to match the NuVizz route grid. Each card now shows a colored status badge, the driver assignment, and the full freight breakdown — SKIDS (pallets) and LOOSE pieces, not just skids — alongside stops, weight, and delivered count. (The status is derived from each route\'s stop execution + driver assignment; capturing NuVizz\'s exact load-lifecycle code is a follow-up.)'],
  ['0.31.1', 'Mobile Loads tab — the per-load freight line now shows SKIDS and LOOSE pieces instead of one "plt" number. That "plt" count was actually NuVizz\'s total-pieces field (skids + loose) mislabeled as pallets; each load row now reads "X skids · Y loose · Z lb", matching the skids/loose breakdown the Stops list and data grids already use.'],
  ['0.31.0', 'Live dispatch (BETA) — staged Compare-panel Save with real re-ordering. The Compare panel is now a staged working copy: add/remove orders, move stops between routes, re-sequence, pick a driver, flag Dispatch — and NOTHING is sent to NuVizz until you hit the one Save in the Compare header. Save commits every changed load in a single batch (it removes a moved stop from its old load before adding it to the new one, and re-sequences via the verified anchor method — keep the first stop, re-insert the rest one-at-a-time in order). Beta still previews the exact calls; a real write needs Live + the server flag. Closing a load with unsaved changes now prompts you first. A re-order is only saved once every stop on the load has loaded its NuVizz id (you\'ll be warned otherwise).'],
  ['0.30.0', 'Live dispatch (BETA, opt-in) — the Compare panel can now assign a driver and dispatch a load to NuVizz. Each route card gets a driver picker, a Dispatch checkbox, and a Save button; a Beta/Live toggle sits in the Compare header. NOTHING is sent to NuVizz while you build or reorder a load — Save first PREVIEWS the exact NuVizz calls, and a real write only happens on Confirm in Live mode (and only when the server-side write flag is enabled). Hidden by default — turn it on with ?write=1 or the VITE_NUVIZZ_WRITE_BETA env. This is the first feature that writes to NuVizz; everything else stays read-only.'],
  ['0.29.84', 'Routing — the ShipTo - Display Seq delivery order now actually sticks after a re-scan (#292). The fresh order read from the list was being silently overwritten on every scan by the older, carried-forward sequence (the physical route seq that the Display-Seq column was meant to replace), so the route kept re-opening in the old order no matter how many times you refreshed. The list\'s Display-Seq is now authoritative and the carried-forward value can only fill in when the column is genuinely absent. Refresh and re-open the load to see the corrected order.'],
  ['0.29.83', 'Routing — make the ShipTo - Display Seq read robust (#290). The delivery-order column is now matched by its DISPLAY NAME ("ShipTo - Display Seq") as well as the internal key, so the scan can\'t miss it if NuVizz keys the column by an opaque path. (If your refresh did not change the order, it was on v0.29.81 — before the v0.29.82 column read shipped; once this is live, refresh and re-open the load.) When the column genuinely isn\'t present the scan logs it instead of silently falling back to the geographic guess.'],
  ['0.29.82', 'Routing — loads now sequence in the REAL delivery order. The scan now reads the new "ShipTo - Display Seq" column you added to the saved search and uses it as each stop\'s delivery order within its load, so opening a load in Compare (and its map polyline / route list) follows NuVizz\'s actual stop order instead of a geographic guess — no per-stop enrichment needed. Takes effect after the next scheduled scan repopulates the board (like the Estimated-Arrival column add).'],
  ['0.29.81', 'Routing (beta) — fixing a stop\'s address now moves its pin LIVE. After you correct an address, the routing map repositions the stop to the right spot immediately (it applies the same corrected-pin override the dispatch Map uses, and recomputes on the spot) — instead of the stop vanishing until you closed and reopened the map (#287).'],
  ['0.29.80', 'Routing (beta) — load NAMES, not gibberish ids. A Compare card / load / send button / Routes panel / stop detail now ALWAYS shows the recurring-load name (e.g. "BEN 2") and never a raw NuVizz id — a hash-like value is suppressed everywhere (frontend guard) and the load roster now reads the human load number with the same guard the driver field got in #254. Also: the Re-sequence menu now keeps showing the applied logic (e.g. "Shortest distance") until you change it, manually dragging a stop marks the route "Manual order (edited)" so it never auto re-sorts your hand-tweaks, and every Compare card now has a Print-manifest button (#263/#280).'],
  ['0.29.79', 'Routing (beta) — Selected window + stop→load. The Selected window now sizes to its contents (no more empty white space; it grows as you add stops), keeps 420px as the standard width (drag the LEFT edge to resize width), and the Type column moved to the end after Zip (#278). And when you open a stop, the detail now shows which LOAD it\'s on with an "Open in Compare" button that pulls that route up in the Compare panel — so a clicked stop is no longer a mystery (#281).'],
  ['0.29.78', 'Routing (beta) — the map pins now MATCH the dispatch Map again: same rich pins with status colour, priority flag, AM/PM window, restriction icons and DNS (the plain numbered circles from 0.29.73 dropped all that). Selected stops still pop orange and routed stops still show their sequence number in the route colour. Also: the right Stops panel no longer clips — each stop is a stacked card (name + PRO/remove on top, city · skids · loose · pcs · weight on a sub-line) that fits the panel, with sort chips up top. The Compare panel gets an Expand-all / Collapse-all stops button (#275) and drops the redundant per-stop window line (the same 8:00–8:00 on every stop) from the expanded detail (#276). And the Ninja toggle is removed from the Compare header — arm it from the on-map tool (the header button was redundant).'],
  ['0.29.77', 'HOTFIX: routing-map stops are back (#279/#282). The smaller circular pins shipped in 0.29.73 used a vector-marker style that silently failed to paint on the routing map\'s satellite/vector base, so the whole board went blank. The pins are now drawn as small numbered circle images, which render reliably — same look, stops visible again. Also: the bottom Stops/Loads grid now centers in the window when the left Setup panel is closed (instead of hugging the left edge); the Compare "Re-sequence" menu moves "Loop" to the bottom of the list (#280); and the Debug-capture box is focused the moment it opens so you can type right away (#280).'],
  ['0.29.76', 'Routing (beta) — new "Loop" re-sequence that stops the criss-crossing. On a Compare route card, Re-sequence → "Loop — down one side & back" runs the stops out along one side of the corridor and back the other (a U-shaped loop), instead of "Farthest first" zig-zagging across the highway. Under the hood it 2-opts the round trip back to the terminal, which un-crosses the route. Each card now also shows which logic is currently applied ("Sequenced: …").'],
  ['0.29.75', 'Print Manifest / Delivery Ticket viewer — the Print and close (✕) buttons now float at the top-right corner over the document (no more full-width header bar), so they sit right at the top of the manifest and stay reachable while you scroll.'],
  ['0.29.74', 'Print Manifest now paginates correctly — each delivery ticket prints on its own page again, and the whole route prints (not just the first page). The page breaks were always right; the fix is printing from a real window instead of the on-screen iframe, which iOS Safari was collapsing to a single page. Also: the routing bottom-grid Loads "Status" column is spelled out (Planned, Un-Planned, In-Transit, Completed, Cancelled) instead of the terse "Pl / Un / Tr" abbreviations, to read like NuVizz (#266).'],
  ['0.29.73', 'Routing (beta) — smaller map pins (#262). Stops now render as small flat circles instead of the big teardrop pins, so a dense board no longer has markers covering each other. Colour still carries state — route colour when a stop is sequenced (with its stop number in the circle), orange when selected, mint for unplanned and slate for planned otherwise — and selected/hovered stops still pop larger. Click and hover behave exactly as before.'],
  ['0.29.72', 'Routing (beta) — Selected-stops window upgrades. It\'s now drag-to-resize (grab the bottom-left corner; width + height are remembered), has a "Clear all" button in the header to drop the whole selection at once (#261), and shows a Loose-pieces column alongside pallets and weight. The columns are reordered to put Pallets · Loose · Weight right after Location, before City/Zip (#260). And in the Compare panel, the per-stop "→ move to load" dropdown is now hidden on desktop (just drag a stop to another card) — it stays on touch where drag isn\'t available (#267).'],
  ['0.29.71', 'Routing (beta) — map filters, ported from the dispatch Map. A new "Filters" button in the map\'s top-right corner toggles: Unplanned only (hides planned stops so you see just what still needs routing), Satellite view (switch between satellite imagery and the plain roadmap base), and Show routes (overlays each load\'s stops connected in delivery sequence, one colour per load). All persisted. The build-version badge that used to sit in that corner is gone — version history now lives in the gear settings (ⓘ Version history), since the version already shows in the page footer.'],
  ['0.29.70', 'Routing (beta) — the left Setup panel can now be hidden. It\'s still under development, so by default it\'s OFF (the map gets the full width) and you flip it on only while working on it. The on/off toggle (plus the floating-panel, right-panel, and hide-stem settings) now also lives in a gear on the bottom data-grid header, so it stays reachable with the Setup panel hidden — and a compact date picker appears there too so you can still change the board date. Turning the Setup panel off can never hide the bottom grid as well (that would strip every settings gear). Desktop only.'],
  ['0.29.69', 'Routing (beta) + scan accuracy. Compare panel: SELECTED stops can now go straight into an open load — when you have stops selected, the Compare header shows a green "→ Load (N)" button for each open card, so you send the whole selection to either load in one click (#258). Driver names that came through as a hash/id are now shown as "Driver assigned" instead of the gibberish, and the real name shows when NuVizz gives us one (#254). Compare route line can hide the stem-out (depot → first stop) leg via the gear menu (#256). Debug capture sheet auto-closes after it saves (#255); the floating selected-stops panel is now solid white and dropped its redundant Window column (#257). Scan: carry-over no longer folds in stops that were unplanned at the last full scan but have since been delivered/planned — it cross-checks the latest live unplanned set and prunes the stale ones, so the day count stops drifting above what NuVizz shows (#253).'],
  ['0.29.68', 'Routing (beta), Compare panel — more detail, to match NuVizz. Each route card now shows MILEAGE up top: total route miles + drive time + deadhead (depot → first stop), computed depot-anchored in the current order and updating live as you re-sequence/drag. And every stop now has its own expand/collapse chevron — open it to see the full address, delivery window, weight/skids/pieces, and the miles to the next stop (was just name + city before).'],
  ['0.29.67', 'Planning horizon (#251) — the scheduled scan now builds the board for today + the next TWO business days (was today + one). So a Sunday scan already populates Tuesday (Uline ships Sunday for Tuesday delivery) instead of leaving it empty until Monday. The extra day is sliced from the ±7-day saved-search pull the scan already makes — no extra list calls — and its orders are enriched on the lower-volume day (Sunday) rather than piling onto a busy Monday. Tunable via NUVIZZ_LIST_HORIZON_DAYS.'],
  ['0.29.66', 'Refresh button cost fix (#244) — the refresh/Scan-now button beside the stops count now fires ONLY the cheap scheduled-scan path: the saved-search planned/unplanned (77128) + completed (77131) pulls + the load roster, for today and tomorrow (~4 NuVizz calls, plus one per genuinely-new order). It used to pass the viewed date, which flipped the scanner into the full number-probe — a ~3,000-call cold scan. Same button, ~4 calls instead of thousands.'],
  ['0.29.65', 'Carry-over clarity (#245) — the carry-over control now shows the actual window it’s covering, e.g. "since Jun 22 · 7d back", so it’s clear the calendar date and the presets are the SAME setting. Picking "since 6/22" on a 6/29 board IS the 7d preset (7 days back) — it was never overriding your date, just showing the same window two ways.'],
  ['0.29.64', 'Unplanned across multiple days (#239) — the "Carry-over unplanned" filter is now a configurable look-back instead of a fixed on/off. Pick a preset (Off / 3d / 7d / 14d) or a calendar "since" date, and the board folds in every still-unplanned order from that many prior days onto the day you’re viewing (each tagged amber, counted in the "· N c/o" badge). Default is today-only; your old on/off setting migrates to 7 days.'],
  ['0.29.63', 'Routing (beta), Ninja onto a load (#237) — you can now build any load with Ninja, even an empty one. Tap a load in the bottom Loads grid (including the "No orders yet" empties) and it opens in the Compare panel; from there a new "Ninja: add stops" button arms ninja (on mobile it drops the sheet so you can tap stops straight onto the map), and a bright "Ninja on — tap stops → <route>" banner shows it’s live. So: tap an available load → Ninja: add stops → tap stops on the map.'],
  ['0.29.62', 'Empty loads — the next business day’s load roster (including loads created but not yet filled with orders) is now scanned ONCE and cached, so e.g. Monday’s empty loads show up on the Loads view without waiting on a live pull. The Loads view serves the cached roster instantly; a manual "Scan now" on a future date refreshes it. Next-day loads are static, so they’re only pulled once a day (no extra NuVizz traffic).'],
  ['0.29.61', 'Routing (beta), Compare panel — two big ones. (1) Your route optimizations now SHOW ON THE MAP: every route open in the Compare panel is drawn as a colour-coded line with numbered stops (matching a colour dot on each card), and it redraws live as you re-sequence, move, or ninja stops. (2) Drag-and-drop between Compare cards — grab any stop by its handle and drop it to reorder within a route or move it onto another route (a blue line shows where it lands). The old "→" move menu stays for phones.'],
  ['0.29.60', 'Routing (beta), mobile fix (#232) — you can tap stops and use Ninja again. The floating Selected panel used to cover the whole map (and the Box/Lasso/Ninja tool rail) on phones; on mobile the selected list now lives in the Setup sheet instead — tap the "N selected" chip to open it, leaving the map fully tappable. The on-map tool rail sits above everything now, and Ninja is always tappable: if no route is open in the Compare panel yet, it shows a quick hint ("open a route first") instead of looking broken.'],
  ['0.29.59', 'Routing (beta) — Box, Lasso, and Ninja are now small selector buttons that live ON THE MAP (left edge), so they\'re always reachable — including while the Compare panel has replaced the Setup stack. (They moved off the Setup panel / Compare header.) Also: the Compare panel now AUTO-SIZES to the number of open route cards — open a 2nd route and it grows to fit two, close one and it collapses back to one. (The Setup and right panels stay manually resizable.)'],
  ['0.29.58', 'Routing (beta) — configurable, resizable layout (part 6, the finale). The left and right panels are now drag-to-resize, just like the dispatch map (drag the divider, double-click to reset; widths are remembered). The gear settings menu is now the one control center: turn the floating Selected panel and the bottom data grid on/off, switch the right panel between Tabs and Routes/Drivers, and "↺ Reset layout to defaults". Routing-beta only.'],
  ['0.29.57', 'Routing (beta) mobile fix — opening a route now jumps you straight to the Compare panel (the Setup tab), where the 🥷 Ninja toggle lives. Before, tapping a route from the Routes tab quietly opened it on the (hidden) Setup tab, so the Compare panel and Ninja mode never appeared. (To get there on a phone: gear → Right panel: Routes/Drivers → tap a route.)'],
  ['0.29.56', 'Routing (beta) — Ninja mode now uses a little masked-ninja icon (a crisp SVG that looks the same on every device and matches the button color) instead of the emoji, on the toggle, the on-panel hint, and each card\'s target radio.'],
  ['0.29.55', 'Routing (beta) — Ninja mode (part 5). With the Compare panel open, hit "🥷 Ninja" in its header: every stop you then click on the map is appended (in click order) to the target route. The target defaults to the leftmost card; with 2+ routes open, a radio on each card switches which one receives the clicks (the active card is highlighted amber). A stop only ever sits on one card — ninja-clicking it onto a route pulls it off any other open route. Turning ninja off (or closing the panel) returns the map to normal stop-toggling.'],
  ['0.29.54', 'Routing (beta) — route workbench (part 4). Click a route in the right Routes/Drivers panel to open it as a card on the left; open up to 3 side by side (the left panel replaces Setup while routes are open — "Back to Setup" closes them). Each card shows the route\'s stops in order with a re-sequence picker (Shortest distance / Farthest first / Closest first / Reverse), collapse/close, and a per-stop "→" menu to move a stop to another open route. It\'s a planning overlay — reorders and moves stay in the workbench and don\'t change the board. (Next: smooth desktop drag-and-drop between routes.)'],
  ['0.29.53', 'Routing (beta) — new right-panel "Routes / Drivers" view (part 3 of the workbench). From the gear settings you can now switch the right panel between today\'s Stops/Loads/Result tabs and a live Routes/Drivers roster: one summary card per route showing route name, driver, stop count, skids, weight, and a delivery-progress bar (X/Y delivered). Click a card to select that route\'s stops and frame them on the map. Routing-beta only.'],
  ['0.29.52', 'Routing (beta) — the floating "Selected N" panel now has sortable columns (click any header — Stop#, Type, Location, City, Zip, Window, Wt, Plt — to sort asc/desc), and a new panel-settings menu (gear, next to the date picker) where you turn the floating panel on and off. The gear is the start of the configurable panel layout — it will grow to switch the right panel between today\'s Stops/Loads/Result tabs and the new Routes/Drivers view, all Routing-beta only.'],
  ['0.29.51', 'Routing (beta) — new floating "Selected N" panel (part 2 of the routing workbench). A NuVizz-style overlay that floats over the map and lists every selected stop at a glance: Stop# · type (DO/PU) · location · city · zip · requested window · weight · pallets, with a running total and per-row open/remove. Toggle it on/off from the "1 · Select stops" controls (or the × on the panel / the "selected" chip on the map); the preference is remembered.'],
  ['0.29.50', 'Fixed "yesterday\'s stuff on today\'s board" on weekends. The background scanner now anchors each board on the EASTERN calendar day instead of the UTC day — previously the Friday-evening scan (after 8pm ET, when UTC has already rolled to Saturday) wrote Friday\'s live board into SATURDAY\'s board, and with no weekend scan to correct it, Friday\'s completed deliveries sat on Saturday\'s board all weekend. The board view also now strips any stale prior-day delivered/exception stops at load time as a safety net, so a mis-dated bleed is never shown even on a board that can\'t be re-scanned. No effect on normal weekday boards.'],
  ['0.29.49', 'Print Manifest pagination: the first printed page is now the summary plus the first delivery ticket, and every page after that is exactly one delivery ticket (a ticket is never split across two pages). Verified against a real print-to-PDF.'],
  ['0.29.48', 'Each route now has a "Print Manifest" button (in the route detail panel, on both the map and mobile): it prints the whole route as one job — a summary cover page (route name, origin, requested window, stop count, driver, and the freight totals: weight · loose · pallets · total pieces) followed by every stop\'s Delivery Ticket in route-delivery order, one per page. Recreates the NuVizz driver manifest, generated entirely from the order data we already have — no extra NuVizz call.'],
  ['0.29.47', 'Empty loads now show on the Loads tab: a load that\'s been created for the day but has no orders assigned yet (e.g. Monday\'s loads waiting to be filled) appears with a "No orders yet" status badge, pulled from the day\'s load roster. Also: orders pulled on Sunday but requested for Tuesday now correctly board on Tuesday, never Monday; and the weekend scan window is extended (Friday scans run until 11 PM, Sunday scans resume at 7 PM) now that API call volume is low.'],
  ['0.29.46', 'Mobile Stops list rows now show more at a glance: the street address, the driver, skids + loose pieces, and a Scheduled/Delivered (or Arrived/Out-for-delivery/Exception) status badge — on top of the business name, city, and PRO that were already there.'],
  ['0.29.45', 'Delivery Tickets now print in portrait (Letter) instead of landscape.'],
  ['0.29.44', 'Loose pieces (NuVizz "volume") now shows as its own column in the data tables: the bottom Stops/Loads grid and the Routing tab\'s selected-stops tables all get a "Loose" column next to Skids/Pallets, so you can see skids, loose pieces, and total pieces at a glance. (The stop detail card already showed loose under Items.)'],
  ['0.29.43', 'The "Delivery Ticket" button now opens the actual NuVizz Delivery Ticket (the per-stop manifest — sequence + Drop Off/Pick Up, Ship-To, requested window, the weight/loose/pallets/total-pieces summary, the PO line-item table, every special-instruction comment with who/when, signature + driver-comment lines, and the Next-Stop ETA) instead of the Bill of Lading. Generated from the order data we already have — no extra NuVizz call. Plus: the PRO number at the top of the stop card is bigger, and the Items list moved up directly under the address.'],
  ['0.29.42', 'Renamed the "Bill of Lading" button on the stop card to "Delivery Ticket" (the document it opens is unchanged — the same NuVizz-matched printable).'],
  ['0.29.41', 'Three things: (1) Printable Bill of Lading — every order now has a "Bill of Lading" button on its stop card that opens a print-ready BOL that copies NuVizz\'s exactly (Davis logo, header, Ship-To/Buyer, special instructions, line items with class/weight, skid/loose/total-piece totals, signature line). Built from the order data we already have — no extra NuVizz call. (2) Routing screen freight now uses the corrected mapping everywhere — skids, loose pieces, total pieces, and truck-capacity (max skids) math all read the right NuVizz fields, so routes no longer over-fill. (3) The Davis Delivery Service logo now appears throughout the app (top header, version panel, and the BOL).'],
  ['0.29.40', 'Stop card: (1) Freight labels corrected — NuVizz mislabels its fields, so the Items breakdown now reads them as their real meaning: the field NuVizz calls "cartons" is shown as PALLETS, "volume" as LOOSE pieces, and "pallets" as TOTAL pieces (pallets + loose). A stop now reads e.g. "1 pallet · 2 loose pcs · 3 total pieces". (2) Proof-of-delivery photos and documents (BOL) now open in an in-app viewer WITH a Close button — before, tapping one filled the screen with no way back inside the installed app. (3) The "Refresh from NuVizz" button is now a clean full-width button instead of floating to the right.'],
  ['0.29.39', 'Stop card fixes: (1) the status badge now updates when you Refresh or open the timeline — a delivered order the board still shows as "Scheduled" flips to "Delivered" once its real status comes back from NuVizz (the header badge was stuck on the stale board value). (2) Loose pieces: NuVizz\'s "volume" field — how Davis records loose pieces — is now pulled in and shown in the Items section (Skids / cartons / loose pcs). (3) The "View delivery photo" button (added last version) lives in the Proof of delivery section of the stop card.'],
  ['0.29.38', 'Delivery photos: opening a delivered order now shows a "View delivery photo" button under Proof of delivery — it pulls the driver\'s captured photo on demand (the photo from the DOCUMENT CAPTURE timeline events). NuVizz exposes these capture photos in a separate place from the signed POD, which is why the proof-of-delivery section used to come up empty; the card now reads both. Plus: closing a stop from the map (left list or the detail panel) zooms the map back out to where it was before you opened the order.'],
  ['0.29.37', 'Routing (beta) now IS the dispatch Map: the map shows the exact same rich markers — status colors, priority-flag colors, AM/PM tags, "address looks off" flags, equipment / receiving-hours restriction icons, and DNS pins — instead of plain gray dots. Selected stops pop orange and routed stops become numbered route-colored pins. Added the same collapsible Stops/Loads data grid along the bottom; tap a row to frame it and add it to the route, or tap a load to select all of its stops.'],
  ['0.29.36', 'Routing (beta) map now matches the dispatch Map: same satellite imagery + road labels (hybrid) and the same vector map style, instead of the plain green roadmap base.'],
  ['0.29.35', 'Historical PRO lookup: tap the NuVizz result to open a full stop card — a centered window over the map with all of the order\'s detail (address + Street View / Maps / web links, status & activity timeline, line items, delivery photos, route/driver). Uses the data the lookup already pulled, so no extra NuVizz call.'],
  ['0.29.34', 'Fix: make the load-ID anchor actually work. The load-roster request sent the date filter as an object; the NuVizz openapi endpoint requires it as a JSON string and was rejecting the call (HTTP 400) — so the anchor silently did nothing. Verified live: the corrected request returns the day\'s loads with their unique IDs. With NUVIZZ_LOAD_ANCHOR=on, the next scan drops yesterday\'s stops that were being carried onto today.'],
  ['0.29.33', 'Scan: optional load-ID anchor (off by default, NUVIZZ_LOAD_ANCHOR=on). Recurring routes (e.g. "BEN 2") reuse the same NAME daily but each day\'s instance has its own unique load ID; the scan can now pull the day\'s authoritative load roster and drop any board stop whose load ID belongs to a prior day — a second, identity-based guard against yesterday\'s stops bleeding onto today. Best-effort: a load-list hiccup leaves the board untouched.'],
  ['0.29.32', 'Fix: today\'s board no longer doubles with yesterday\'s completed stops. The list-discovery scan was stamping every stop from its multi-day window onto the queried day, so prior-day DELIVERED / unable-to-deliver stops bled onto today (≈700 extra). Those finished stops now stay on their own day; today shows only today\'s work plus genuinely-open carryover.'],
  ['0.29.31', 'Proof-of-delivery photos are now viewable: a delivered order\'s stop card shows a thumbnail gallery of the driver\'s delivery photos (tap to open full size). Pulled securely server-side from NuVizz. The activity timeline also now shows each event\'s GPS location as a tappable map link.'],
  ['0.29.30', 'Stop notes + activity timeline now load ON DEMAND when you open an order (no background backfill) — open a stop, or tap "Refresh from NuVizz", to fill in its full notes and timeline. New orders get their full notes automatically on first sync.'],
  ['0.29.29', 'Stop card upgrade: opening an order now shows its FULL NuVizz notes (every comment — order instructions, pre-visit, billing — with who added it and when), a "Refresh from NuVizz" button that re-pulls the order on demand, and a collapsible Activity Timeline (Stop Planned / Departure / Dispatched / Updated, with the By: and From:). Plus fixes: rolled-over undelivered orders now stay on TODAY\'s route instead of dropping off, and the map route lines no longer crisscross.'],
  ['0.29.28', 'Loads: added a % delivered figure on each load in the Loads list and on the load detail header (green at 100%). The load detail now also shows each stop\'s address under the business name.'],
  ['0.29.27', 'Mobile: swapped the "Drivers" tab for "Loads". The bottom-nav and bottom-sheet tab now lists the day\'s loads (route/load #, driver, delivered-of-total, pallets, weight); tapping a load opens its route detail. Live driver pins on the map are unchanged.'],
  ['0.29.26', 'Messages on mobile: the texting window now sizes to the visible screen, so the keyboard no longer hides the message box and Send button — you can actually type and send a text on a phone. Same fix keeps the conversation above the keyboard in every view.'],
  ['0.29.25', 'Messages, rebuilt (iOS-style). The texting window is now a real messaging app: a searchable conversation list with avatars, names, role tags and unread dots; a "New message" button that opens a CONTACT PICKER split into Drivers / Contractors / Customers / Team (drivers + contractors come from the employee roster via a new /messaging-roster endpoint) plus Recent and "text any typed number"; and a conversation view with iMessage-style bubbles, grouped time stamps, a pill composer, instant (optimistic) send and tap-to-retry on failures. You can now START a text to anyone, not just reply to people who texted first.'],
  ['0.29.24', 'Cleaner buttons: the floating message-bubble icon (desktop + mobile) now opens TEXTING, and the AI assistant moved to a "?" button next to it. On mobile the texting window is full-screen (iOS-style) with notch/home-bar safe spacing; on desktop it stays a side drawer over the map. The message button shows an unread badge.'],
  ['0.29.23', 'Texting — two-way conversations. Messages now opens as a window OVER the map (no more leaving the screen; fixes the blank-screen bug). It shows full back-and-forth threads per customer/driver — your sent texts and their replies together — with an inline reply box. Inbound replies are matched to a customer (from saved contacts) or driver (from MarginIQ) by phone, and driver threads are tagged. New: "Text drivers" from the box/lasso selection texts the drivers of the selected stops at once.'],
  ['0.29.22', 'Fix: a previously-undelivered order rolled back to unplanned and re-added to today\'s load now shows on the driver\'s route. The scan was dropping any load member whose own delivery date wasn\'t today; for a load that started today we now keep all its members (rolled-in older orders included), so a stop like Paulsen Foods on Rasko\'s load appears. No extra NuVizz calls — that stop was already in the load data we fetch. Genuine multi-day carryover loads are unaffected.'],
  ['0.29.21', 'Texting Stage 2 — text drivers. The driver panel now has a "Text driver" button; the driver\'s mobile number is pulled from their MarginIQ employee card (matched by name) on the server, so numbers stay private. Works on desktop + mobile.'],
  ['0.29.20', 'Texting Stage 3 — inbound replies. New "Messages" tab shows customer text replies (newest first, matched to a customer name by phone when known), with a Reply button and an unread badge. Replies arrive via a SimpleTexting webhook into the app.'],
  ['0.29.19', 'Texting fix: the "Text customer" button now always shows in a stop\'s detail (desktop + mobile) even when no phone is on file — you can type/confirm the number right in the compose box. Previously it was hidden whenever a stop had no saved number, so it looked missing on mobile.'],
  ['0.29.18', 'Texting is now active — the SimpleTexting account is connected, so the "Text customer" and "Text selected" buttons send real messages from our number.'],
  ['0.29.17', 'Texting (SMS) via SimpleTexting — Stage 1 (outbound). New "Text customer" button in stop detail and "Text selected" in the box/lasso selection toolbar; both open a compose box and send via our number. Customer number = notes contact, falling back to the NuVizz scan contact. Server send endpoint has a daily send cap. Requires SIMPLETEXTING_API_KEY (and optional SIMPLETEXTING_FROM) env vars. Next stages: text drivers + inbound replies inbox.'],
  ['0.29.16', 'New per-customer "Email customer service when scheduled" toggle in notes. When the scan finds an opted-in customer on a day\'s board, it emails CS once (the first time that customer appears that day, deduped) from our no-reply account via Resend. Requires RESEND_API_KEY + RESEND_FROM + NOTIFY_CS_TO env vars to be set.'],
  ['0.29.15', 'DNS "Drivers not allowed" picker now lists the FULL driver roster from Motive (the fleet app), so you can bar ANY driver — not just ones on today\'s board or currently on the live map. New read-only /motive-drivers endpoint (server-cached ~1h); merged with today\'s board drivers and de-duped.'],
  ['0.29.14', 'DNS "Drivers not allowed" picker now always has drivers to choose from: it lists every driver assigned to the current board\'s loads (from the scan), not just the live Motive feed — which only loaded when "Show drivers (live)" was on for today. Fixed the misleading "Open the Drivers tab" hint too.'],
  ['0.29.13', 'Desktop: the "Search past PROs / customer history" button is now in the left sidebar (under the search box) — previously it existed only on mobile. Opens the same saved-delivery-history lookup as an overlay, prefilled with whatever is already typed in the live search.'],
  ['0.29.12', 'Fix: planned orders no longer show as "Unplanned". NuVizz keeps a stop at status-10 even after it has been put on a load (planned but not yet dispatched); the order/unplanned scan was re-tagging those load-assigned stops as unplanned, overwriting the load scan. The unplanned descent now excludes any stop that already carries a load number, so planned-but-not-started orders stay planned.'],
  ['0.29.11', 'Unplanned stop pins recolored to thistle (light purple) per dispatch request.'],
  ['0.29.10', 'Map pins: planned and unplanned stops now render at the same smaller size (only search-matched / AM-PM-tagged pins are enlarged for emphasis), and unplanned stops are tinted mint instead of blue so they read distinctly on satellite.'],
  ['0.29.9', 'NuVizz scan politeness + learning (addresses their "1000+ calls in a single minute" notice). (1) Probe concurrency is throttled (was firing ~30 load lookups in parallel = a burst) and is now env-tunable, so a scan SPREADS its calls over time instead of hammering NuVizz at once. (2) New scan-discovery monitoring records, every scan, how many loads were found, how many were NEW vs the prior day, and the largest gap between load numbers — surfaced as a learned summary (avg/max new-loads/day, worst gap, recommended look-ahead) so we can safely switch to a no-daily-seed incremental scan next, tuned from real data instead of guesses.'],
  ['0.29.8', 'Weekend call savings + a clearer call counter. (1) The nightly history-warehouse snapshot now skips Saturday & Sunday — it was archiving empty non-working days at full cost (~1,200 NuVizz calls each), which is why calls showed on a weekend even with the live scan off. Friday and Monday are still archived; on-demand backfill is unchanged. (2) The "calls today" counter now follows a normal midnight-to-midnight Eastern day instead of UTC, so after-midnight-UTC jobs (the ~2am ET snapshot) count on the right local day and a truly quiet day reads 0.'],
  ['0.29.7', 'Two additions: (1) Tap a customer in the historical search to open their full detail + notes editor. (2) New "DNS — do not send" control: a red/white DNS badge that shows everywhere the customer appears (map pin = red pin with ✕, stop list, stop detail, and historical search), plus a do-not-send toggle and a multi-select of which drivers are not allowed to that customer (from the app driver list). Saved per customer alongside the other notes.'],
  ['0.29.6', 'Historical customer search now matches a word ANYWHERE in the name, not just the start — searching “locksmith” now finds “SOLID LOCKSMITH” (before, only “solid…” worked). Multi-word searches must match all words. (Built on per-customer name word-tokens; still reads only our saved history, no NuVizz call.)'],
  ['0.29.5', 'Historical customer/PRO search now actually finds everyone. It used to read only a sparse local cache (built just for customers with special receiving rules, off the live board — empty on weekends), so a customer like a locksmith we delivered Friday wouldn’t show up. It now searches our own saved delivery-history warehouse (every delivery, every day → each customer’s last 20 PROs), so business-name and PRO searches find any customer we’ve delivered to — and still WITHOUT calling NuVizz (it reads our own data; only an unknown PRO triggers the explicit one-call lookup).'],
  ['0.29.4', 'Fixes the mobile screen "shifting" — the app sliding partly off the left edge with a white gap on the right (seen when opening the past-PRO search). On iOS, focusing a field can scroll the VISIBLE viewport sideways inside the slightly-wider layout viewport; the app shell stayed anchored to the layout edge and slid off-screen. The shell is now pinned to the visible viewport’s actual position, so it always stays squared to the screen no matter what the keyboard/focus does.'],
  ['0.29.3', 'New "Search past PROs / customer history" button on the mobile Stops tab. Tap it to look up a historical PRO or a customer by business name against the saved 20-stop history we keep per customer — no API calls for that. Searching a business name pulls up that customer’s last 20 PROs (with dates); searching a PRO number finds it across saved history. Business-name searches never call NuVizz. Only when you type a PRO that ISN’T in saved history do you get an explicit "Look up PRO in NuVizz (1 API call)" button — a single, deliberate, on-demand call you choose to make; nothing happens automatically.'],
  ['0.29.2', 'Mobile search no longer auto-calls AI: typing in the search box now just filters the loaded stops locally (live), and AI search is a separate, explicit action (the AI button) — pressing Enter dismisses the keyboard instead of firing AI. Also fixed the version (vX.Y.Z) menu being clipped/hidden behind the header.'],
  ['0.29.1', 'Fixes the right edge of the mobile app getting clipped (the last tab, the AI button, etc. cut off). On iOS the layout viewport can be a few pixels wider than the visible screen, and width:100% resolved to that wider value — pushing right-edge controls off the visible area. The app shell is now pinned to the live visible (visualViewport) width, so every control stays on-screen.'],
  ['0.29.0', 'Mobile is now a real full-screen app with a bottom tab bar (Map · Stops · Filters · Drivers), not a stack of half-height sheets over the map. Every view — the stops list + search, filters, drivers, stop detail + full editor, route detail, driver snapshot — fills the screen under a persistent header, so there’s no wasted empty space, nothing overlaps the map, and nothing hangs off the edge. The search works correctly: it stays at the top with the keyboard up so you can see what you’re typing, with results below; the tab bar stays put. Same features and data as desktop (full parity) — just laid out as a proper mobile app.'],
  ['0.28.3', 'Fixes the blank screen when you tap the search field on mobile. The page body was scrollable (a side effect of the overflow-x guard computing overflow-y to “auto”), so iOS scrolled the whole app up to the focused field, blanking everything above the keyboard. The app shell is now locked to the viewport (no page scroll/bounce); only the inner panels (sheets, lists) scroll. Verified across every mobile screen in Safari’s engine — map, Stops/Filters/Drivers drawers, stop detail + editor, route detail, driver snapshot.'],
  ['0.28.2', 'Mobile bottom sheets now fit their content — no more giant band of empty white space under a sparse stop. The sheet measures its content and sizes to min(content, ~⅔ screen): short stops open compact, while a long one (the full editor) caps at the screen fraction and scrolls with the Save bar pinned. Also hardened the Route row so the “View full route” button wraps instead of clipping. (Verified in Safari’s engine at multiple phone heights — both the content-fit and the cap-and-scroll cases.)'],
  ['0.28.1', 'Fixes the mobile right-edge clipping (status pill, filter rows, day buttons, item quantities, Save button all running off-screen). Root cause: iOS Safari was auto-inflating the small text beyond its set size, widening every row — now pinned with text-size-adjust:100% so the layout renders at the intended size. Also: the items list wraps cleanly (SKU/SEQ stacks under the product, quantity stays put), and focusing a field in the stop sheet now scrolls it into view above the keyboard so you can see what you’re typing. (Verified by rendering the real sheet in Safari’s engine at phone widths.)'],
  ['0.28.0', 'Mobile stop detail rebuilt for full desktop parity. The desktop sidebar and the mobile sheet now render the SAME shared components (one address/window/items/route block + one complete notes editor), so every edit option on desktop is on mobile and the two can never drift again. The mobile stop sheet is now a single scroll with one inline “Edit” that reveals the full editor — priority flag, AM/PM window, per-day receiving hours (with copy-to-weekdays), appointment required + notes, liftgate, equipment restrictions, dock type/notes, and contacts — instead of options split across tabs. Plus a mobile design-system sweep: Filters toggles no longer get pushed off the right edge, the header no longer clips under the notch, the date chip/status pill can’t overlap, long text wraps, modals/chat are keyboard-aware, and the stop sheet opens at a content-appropriate height (less empty space).'],
  ['0.27.37', 'Mobile formatting fixes: (1) the app header no longer tucks under the notch/Dynamic Island — it now grows by the safe-area inset (and viewport-fit=cover is enabled so all safe-area padding actually applies). (2) Focusing the search field no longer clips the bottom sheet under the header — the sheet is now sized to the keyboard-aware visible viewport instead of a fixed vh. (3) The date chip and the status pill now share one row so they can never overlap on a narrow phone. (4) A global guard prevents any stray over-wide element from pushing the FAB / right-aligned PRO badges off the right edge. (5) Long addresses wrap instead of widening the stop drawer.'],
  ['0.27.36', 'Scan-cost: weekend blackout (no scheduled scans Fri 10pm–Sun 8pm ET; manual still works) and a trimmed, env-tunable unplanned high-water buffer (200→150). Backend only — no UI change.'],
  ['0.27.35', 'Route order now matches NuVizz exactly. Routes are sequenced by NuVizz’s own stop-sequence number (the Route Workbench order) instead of a fallback that could scramble stops — most importantly for routes that haven’t started yet (no ETAs computed), which previously fell back to NuVizz’s raw array order and looked random. The numbered map pins AND the route detail list now use that same sequence value, so co-located orders at one stop share its number, exactly like the Workbench.'],
  ['0.27.34', 'Route view now matches NuVizz: opening a route (a) frames/centers the map on that route’s stops (and restores your prior view on close), and (b) numbers the stops on the MAP in delivery sequence (planned-ETA order) — green=delivered / blue=scheduled numbered pins, with the rest of the board dimmed — mirroring NuVizz’s numbered route pins + numbered list.'],
  ['0.27.33', 'Three fixes: (1) deselecting a stop now zooms/pans back out to the board view it had before you clicked in (was staying at building zoom). (2) The Loads table now lists the full board’s loads regardless of stop filters — "Unplanned only" no longer empties it. (3) Lean scan now gap-sweeps the load range DURING THE DAY, so loads you populate by routing mid-morning (route shells that gain stops after the overnight scan) are picked up promptly instead of lingering as stale "unplanned" — fixes routed orders still showing unplanned.'],
  ['0.27.32', 'Filters: new "Potential address issues" checkbox (shows stops the mis-split detector flags) and an "Any equipment restriction" checkbox (complements the specific-restriction dropdown, which it supersedes when on). Address detector broadened: it now flags a stop whose addr1 doesn’t start with a house number while addr2 does — e.g. a dock descriptor "MGE1 NON INVENTORY DOCK DR 178" with the real street "652 BROADWAY AVE" in addr2 (previously missed because addr1 contained digits). Normal addresses (addr1 starting with the house number) are never flagged.'],
  ['0.27.31', 'Auto-flag "CLOSED ON FRIDAYS/MONDAYS" (the Uline instruction format) — the closed-day scanner now also matches the optional "ON" and the plural "S", so e.g. "CLOSED ON FRIDAYS" auto-sets a red Closed-Fri badge on import (all 7 days). Address-fix is also more robust: if the Google Geocoding API is unavailable (REQUEST_DENIED), the corrected addr1/addr2 split is still saved and you can drag the pin via "Correct pin location" instead of losing the fix.'],
  ['0.27.30', 'Mobile status pill is now collapsible (like desktop) — collapses to just the stops count, and the expanded view now also shows the NuVizz call counter (today’s calls / ceiling + mode) alongside total pallets and the load/unplanned feed update times. Shares the collapse state with desktop.'],
  ['0.27.29', 'Address mis-split detection + one-click fix. NuVizz often puts the street in addr2 with a suite/dock/contact in addr1 (e.g. "BLDG 200" / "4310 INDUSTRIAL ACCESS RD"), so the geocoder lands on the wrong spot. Such stops now show an amber "!" pin and a "Address may be mis-split" banner on the stop card with "Fix & move pin" (one-click: swaps the lines, re-geocodes the clean street, saves the corrected address + pin) and "Edit…" (the modal, now with a suite/addr2 field, pre-filled with the suggestion). Detection is conservative and self-clears once corrected. Also adds a new "?" priority flag (indigo pin with a "?") alongside red/yellow/green.'],
  ['0.27.28', 'Bottom table: every column in both the Stops and Loads views is now sortable — click a header to cycle asc → desc (chevron shows the active column). Stops and Loads keep independent sort state. Numeric columns (Stop #, Pallets, Weight, stop count) sort numerically; the Loads Status column sorts by % delivered'],
  ['0.27.27', 'Bottom table: new Stops | Loads tab toggle. The Loads view groups the current board by loadNbr — one row per load with driver, stop count, a per-status breakdown, and pallet/weight totals. Click a load to open its route drawer and frame the map on that load’s stops'],
  ['0.27.26', 'Map fix: clicking a stop pin now recenters and zooms to STOP_ZOOM (18), matching the list/search behavior — the map-marker click handler was setting the selected stop without panning/zooming'],
  ['0.27.25', 'Incremental-scan Phase 6 (default OFF, flag NUVIZZ_TERMINAL_SKIP): terminal-stop skip cache — stops confirmed delivered (status 90/91) are immutable, so their stopNbr→expectedDate is persisted in Firestore (nuvizz_stop_terminal) and the unplanned /stop/info descent synthesizes them from cache instead of re-probing. Heuristics preserved exactly (synthesized probe carries the stored expected date); targets /stop/info, the dominant remaining call source'],
  ['0.27.24', 'Triple-check hardening (audit follow-ups): undelivered report counts code-less deliveries (deliveredDTTM/normalizedStatus) as delivered, and same-day deliveries on the window edge are surfaced as "indeterminate" (+ readErrors) instead of silently assumed on-time; lean history skips a HALTED (ceiling/kill-switch) index and re-scans; regression tests added for the call-counter merge shape and the day-scoped circuit-breaker expiry'],
  ['0.27.23', 'Incremental-scan Phase 5: undelivered / delivered-late / aged-out report + 91(manual)-vs-90(system) completion breakdown, derived from the multi-day history warehouse with zero NuVizz calls (read-only /nuvizz-undelivered-report endpoint)'],
  ['0.27.22', 'Phase 4 fix (audit): lean history path no longer references undefined scan result (would have thrown with the flag on); counts/timestamp derived from the index, and an empty index falls back to a fresh scan'],
  ['0.27.21', 'Incremental-scan Phase 4 (when lean is on): the daily history snapshot is built from the accumulated Firestore stop-index instead of a fresh NuVizz scan (~690 calls → ~0); late deliveries reconciled by the Phase 5 straggler watch'],
  ['0.27.20', 'Incremental-scan Phase 3 hardening (audit): the lean order descent now bounds on an UNPLANNED-only high-water (a high planned stop can no longer ratchet the floor past new orders) + wider safety buffer — closes an order-loss path before enabling'],
  ['0.27.19', 'Incremental-scan Phase 3 (behind NUVIZZ_LEAN_DISCOVERY, default OFF): unplanned/order descent only probes NEW stop numbers above the persisted high-water on warm cycles; writeStops preserves older still-unplanned orders so the lean descent never prunes them'],
  ['0.27.18', 'Incremental-scan Phase 2 hardening (independent audit): lean scans no longer calibrate the fallback window, and cold-start now uses the proven wide-window probe instead of a forward seed that could miss a day with non-contiguous load numbers'],
  ['0.27.17', 'Incremental-scan Phase 2 safety: lean (terminal-skip) load scans now PRESERVE already-delivered stops instead of pruning them (writeStops partialLoads) — closes a data-loss path before lean discovery can be enabled'],
  ['0.27.16', 'Incremental-scan Phase 2 (behind NUVIZZ_LEAN_DISCOVERY=on, default OFF): probe only known-active loads + forward buffer + periodic gap sweep instead of the ±600 window; terminal-skip; wide window stays the cold-start fallback'],
  ['0.27.15', 'Incremental-scan: routing window corrected to OVERNIGHT 20:00–07:00 ET (when routes are built) — shadow buffers tuned (+50 overnight / +10 daytime)'],
  ['0.27.14', 'Incremental-scan Phase 1 (shadow): records a per-day scan_state roster and logs what lean load-discovery WOULD probe vs the current wide window — no scan behavior change yet'],
  ['0.27.13', 'NuVizz call counter now accumulates (was stuck at 1/day) with a per-route breakdown; daily-ceiling breaker is day-scoped + has a monitor/enforce mode (default monitor); today’s call volume shown in the status card'],
  ['0.27.12', 'Priority flag now drives the marker color in ALL cases — a flagged stop shows the flag color even when it renders a receiving-hours/restriction icon (the icon is recolored to the flag hue)'],
  ['0.27.11', 'AM/PM pin takes the priority-flag color when a flag is set (e.g. red flag → red AM pin); pin tag text stays legible on light flags'],
  ['0.27.10', 'Unplanned pins are now bright blue for satellite contrast; customer-notes editor no longer loses in-progress edits when a background note write lands mid-edit'],
  ['0.27.9', 'Unplanned pins are now solid slate (was hollow white — better contrast on satellite) and a touch smaller'],
  ['0.27.8', 'Customer notes: AM/PM "Delivery window" tag — tagged stops show an AM/PM pin on the map'],
  ['0.27.7', 'Order detail: "Find business" now opens a general Google search (name+address); removed the redundant Maps-search button (the "Google Maps" link still opens the map)'],
  ['0.27.6', 'Edit address: correct a mis-entered address — it re-geocodes and moves the pin for that customer (also restores the mobile pin-correct button)'],
  ['0.27.5', 'Order detail: added a "Find business" search link (business name + address)'],
  ['0.27.4', 'Order detail: "Find business" button (Maps search by name+address) + collapsible per-order items list (SKU/qty/weight/oversize)'],
  ['0.27.3', 'Date picker no longer shows the date twice; status card stacks its details and is collapsible to reclaim map space'],
  ['0.27.2', '“Scan now” runs the async scanner + polls (a busy date exceeded the 26s sync cap), so it never times out'],
  ['0.27.1', '“Scan now” refreshes just the viewed date (loads + orders) so it can’t time out'],
  ['0.27.0', 'Scan scheduler: elapsed-time cadence (fires on schedule despite cron jitter) + tomorrow’s orders scanned 10am–midnight + structured [scan] logs + daily-limit banner'],
  ['0.26.0', 'NuVizz scan schedule (ET time-of-day gating ~14k/day) + working manual Scan-now + split load/order timestamps'],
  ['0.25.25', 'Map auto-refreshes from the DB index every 2 min (silent, visible-only) so a long-open tab stays current'],
  ['0.25.24', 'Default delivery pins use a brighter blue (#4285F4) so they read on satellite'],
  ['0.25.23', 'AI results: populate Stops list/table reliably, orange found-pins, cleaner chat formatting'],
  ['0.25.22', 'Clicking a customer zooms to building level (~18) instead of neighborhood level'],
  ['0.25.21', 'Bottom stops table is drag-resizable (grab the top handle); height persists'],
  ['0.25.20', 'Correct a stop’s pin location — drag + save a per-customer override that persists for future loads'],
  ['0.25.19', 'Map controls match the requested set: compass + 2D/3D tilt, zoom, pegman, custom recenter crosshair'],
  ['0.25.18', 'Bottom stops table: search box + status filter (Un-Planned/Planned/In-Transit/Completed/Cancelled)'],
  ['0.25.17', 'HOTFIX: app blank-screen crash — mapFilters referenced before declaration (carry-over fetch TDZ)'],
  ['0.25.16', 'Declutter map controls: drop the on-screen keypad + pegman/scale; keep zoom/rotate(spin)/type/fullscreen + Ctrl-drag 3D'],
  ['0.25.15', 'Compact map controls — icon-only Box/Lasso; Filters collapses to a label-width pill that expands on click'],
  ['0.25.14', 'Collapsible NuVizz-style stops data grid at the bottom of the dispatch map'],
  ['0.25.13', 'Carry-over unplanned (prior-day open orders) toggle + fix box/lasso selection (projection now ready)'],
  ['0.25.12', 'Box + lasso multi-select on the map — highlights and filters the selected stops'],
  ['0.25.11', 'Total pallets count (sum of NuVizz carton field) shown below the stop count'],
  ['0.25.10', 'Distinct route-line colors for every driver (golden-angle hue spread, no more repeats)'],
  ['0.25.9', 'Fix "Unplanned only" (use isPlanned, not driver-assigned) + rename driver toggle to "Show drivers (live)"'],
  ['0.25.8', 'Smaller plain (non-restriction) stop pins to cut map clutter'],
  ['0.25.7', '"Unplanned only" filter — show only unplanned deliveries (off = all); replaces "Show unplanned"'],
  ['0.25.6', 'Full Google Map controls (type/rotate/pegman/fullscreen/zoom) + 3D tilt-rotate via vector Map ID'],
  ['0.25.5', 'Click a stop in the list to center the map on it + Google Maps link alongside Street View on the stop card'],
  ['0.25.4', 'Stop card NuVizz instructions: strip SPL-INSTR-TEXT prefix + hide boilerplate DO NOT BREAKDOWN SKID'],
  ['0.25.3', '"Has receiving hours" filter matches raw NuVizz instructions directly (finds stops the scanner missed)'],
  ['0.25.2', 'Scheduled scan covers today + next business day (was today-only), so tomorrow’s board stays fresh'],
  ['0.25.1', 'Scanner load-number estimate: business-day anchor + self-calibration (fixes the scheduled scan missing a full day of loads)'],
  ['0.25.0', 'Single source of truth (staged): sole NuVizz scanner writes the canonical fleet index + shared daily-ceiling call counter & circuit breaker'],
  ['0.24.9', 'NuVizz call-volume fix: today-only refresh, */15 cron, narrower scan window'],
  ['0.24.8', 'Add NUVIZZ_SCANS_ENABLED kill switch for the scheduled stop-index scan'],
  ['0.24.7', 'Satellite view toggle + Street View link on stop card + raw NuVizz instructions on stop card'],
  ['0.24.6', 'Driver labels: drop misleading "No route assigned" (routes come from NuVizz, not Motive)'],
  ['0.24.5', 'Receiving-hours scan: strip SPL-INSTR-TEXT line prefixes so split RECEIVING HOURS + range parse'],
  ['0.24.4', 'Filter: "Has receiving hours" toggle — show every stop with receiving hours set'],
  ['0.24.3', 'Receiving hours: scan "RH"/"RECEIVING HOURS" Uline formats + chat reads raw order instructions'],
  ['0.24.2', 'AI chat: 12-hour AM/PM times + reads free-text dock/appointment notes for receiving hours'],
  ['0.24.1', 'Tractor Trailer Friendly — green positive equipment kind (manual; suppressed when No T/T set)'],
  ['0.24.0', 'AI Order Search — natural-language search box + chat panel over the loaded board'],
  ['0.23.1', 'Phase 3 growth-guard fix — no phantom spill / no criss-cross on dense builds'],
  ['0.23.0', 'Geographic truck assignment (no two-truck criss-cross) + green stop markers'],
  ['0.22.0', 'Strategy ordering fixed — placeholder windows no longer clobber Min-distance/Closest'],
  ['0.21.0', 'Appointment windows are advisory (flag, don’t spill)'],
  ['0.20.0', 'Build badge on the routing screen'],
  ['0.19.0', 'Drag-lasso, clickable PRO popups, per-load re-sequence, discard plan'],
  ['0.18.0', 'Shared live Loads — save / open / rename / dispatch across devices'],
  ['0.17.1', 'Route by skid count (deck length no longer blocks)'],
  ['0.17.0', 'Manual route reorder — drag + numbered stops, live map sync'],
  ['0.16.1', 'Build reliability — killed the hang, near-instant builds'],
  ['0.16.0', 'Desktop dispatch console (Setup · map · Stops/Loads/Result)'],
  ['0.15.0', 'Touch selection + per-stop intelligence + selected-stops list'],
  ['0.14.0', 'Routing (beta) tab + cheap-by-default engine'],
];

const BUFORD = { lat: 33.9719, lng: -84.0008 };
const BRAND = '#1e5b92';

const FLAG_COLORS = {
  red: '#dc2626',
  yellow: '#eab308',
  green: '#16a34a',
  question: '#6366f1',   // "?" flag — dispatcher-set "uncertain / look into this"
};
// Priority-flag values offered in the pickers (null = none).
const FLAG_OPTIONS = ['red', 'yellow', 'green', 'question'];
const ADDRESS_OFF_TINT = '#d97706';   // amber pin for an auto-detected mis-split address
