// ---------- debug capture ----------
// "Debug this view" bundles what the dispatcher is looking at so a coding agent
// can see the data behind a bad behavior. We ship coordinates + state, not a
// screenshot (the Google map is WebGL and iOS Safari has no getDisplayMedia).
// Customer names/addresses/contacts and the raw NuVizz payload are scrubbed.
function scrubStop(s, seq, note) {
  if (!s) return null;
  return {
    seq: seq == null ? undefined : seq,
    stopNbr: s.stopNbr,
    pro: s.pro,
    loadNbr: s.loadNbr,
    status: s.status,
    normalizedStatus: s.normalizedStatus,
    isPlanned: s.isPlanned,
    isUnplanned: s.isUnplanned,
    isTerminal: s.isTerminal,
    carryover: s.carryover,
    driverName: s.driverName,
    driverUserName: s.driverUserName,
    routeSeq: s.routeSeq,
    loadStopSeq: s.loadStopSeq,
    plannedEtaDTTM: s.plannedEtaDTTM,
    arrivalDTTM: s.arrivalDTTM,
    deliveredDTTM: s.deliveredDTTM,
    cartons: s.cartons,
    pallets: s.pallets,
    volume: s.volume,
    weight: s.weight,
    lat: s.lat,
    lng: s.lng,
    matchKey: s.matchKey,
    hasNote: !!note,
    flag: note?.priority_flag ?? null,
    // dropped (PII / huge): businessName, addr1, addr2, city, state, zip,
    // contact, origin, stopDetails, allComments, raw
  };
}

// Reconstruct a Google Static Maps URL from the live viewport + visible pins, so
// a reviewer can see the same view without WebGL. Uses a __MAPS_KEY__ placeholder
// so no real key lands in the bundle.
function buildStaticMapUrl(center, zoom, stops) {
  if (!center) return null;
  const params = [
    `center=${center.lat},${center.lng}`,
    `zoom=${Math.round(zoom || 11)}`,
    'size=640x640',
    'scale=2',
  ];
  const pins = (stops || [])
    .filter((s) => s.lat != null && s.lng != null)
    .slice(0, 20)
    .map((s) => `${(+s.lat).toFixed(5)},${(+s.lng).toFixed(5)}`);
  if (pins.length) params.push(`markers=size:small%7C${pins.join('%7C')}`);
  params.push('key=__MAPS_KEY__');
  return `https://maps.googleapis.com/maps/api/staticmap?${params.join('&')}`;
}

// POST a capture bundle to the backend, which files it as a GitHub issue.
async function postDebugBundle(bundle) {
  const secret = import.meta.env.VITE_DEBUG_CAPTURE_SECRET;
  const resp = await fetch('/.netlify/functions/debug-capture', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...(secret ? { 'x-debug-secret': secret } : {}) },
    body: JSON.stringify(bundle),
  });
  const data = await resp.json();
  if (!resp.ok || !data.ok) throw new Error(data.error || `HTTP ${resp.status}`);
  return data; // { ok, issueUrl, issueNumber }
}

// The active screen registers its bundle builder into a shared ref so the
// Shell-level "Debug this view" entry (chip menu / desktop nav) can capture
// whatever screen the dispatcher is on. Screens are mounted one at a time, so a
// single ref is unambiguous; the cleanup clears it on tab switch.
function useRegisterDebugCapture(ref, builder) {
  useEffect(() => {
    if (!ref) return undefined;
    ref.current = builder;
    return () => { if (ref.current === builder) ref.current = null; };
  }, [ref, builder]);
}

// Shell-owned capture modal, reachable from any tab. Pulls the active screen's
// bundle from captureRef, posts it, and shows the resulting issue link.
function DebugCaptureSheet({ open, onClose, captureRef }) {
  const [note, setNote] = useState('');
  const [busy, setBusy] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const mountedRef = useRef(true);
  useEffect(() => () => { mountedRef.current = false; }, []);
  // Fresh sheet each time it opens; Escape closes it.
  useEffect(() => { if (open) { setNote(''); setResult(null); setError(null); } }, [open]);
  useEffect(() => {
    if (!open) return undefined;
    const onKey = (e) => { if (e.key === 'Escape') onClose(); };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [open, onClose]);
  // Once the issue is opened, show its number briefly then auto-close (#255) — the dispatcher
  // just needs to see the number, not dismiss the sheet by hand.
  useEffect(() => {
    if (!result) return undefined;
    const t = setTimeout(() => { if (mountedRef.current) onClose(); }, 2800);
    return () => clearTimeout(t);
  }, [result, onClose]);
  if (!open) return null;

  const send = async () => {
    if (busy) return;
    const builder = captureRef && captureRef.current;
    if (typeof builder !== 'function') { setError('Nothing to capture on this screen yet.'); return; }
    setBusy(true); setError(null); setResult(null);
    try {
      const bundle = builder(note.trim());
      const res = await postDebugBundle(bundle);
      if (mountedRef.current) setResult(res);
    } catch (e) {
      if (mountedRef.current) setError(e?.message || 'Could not send the capture. Please try again.');
    } finally {
      if (mountedRef.current) setBusy(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-end sm:items-center sm:justify-center bg-black/30" onClick={onClose}>
      <div
        className="bg-white w-full sm:w-[420px] rounded-t-2xl sm:rounded-2xl shadow-2xl border border-slate-200 max-h-[85dvh] flex flex-col pb-[env(safe-area-inset-bottom)] sm:pb-0"
        onClick={(e) => e.stopPropagation()}
        role="dialog"
        aria-label="Debug this view"
      >
        <div className="flex items-center gap-2 px-4 py-3 border-b" style={{ color: BRAND }}>
          <Bug size={16} />
          <div className="font-semibold text-sm flex-1">Debug this view</div>
          <button onClick={onClose} className="p-2 rounded hover:bg-slate-100 text-slate-500 min-w-[40px] min-h-[40px] flex items-center justify-center" aria-label="Close">
            <X size={18} />
          </button>
        </div>
        <div className="p-4 space-y-3 overflow-y-auto">
          <p className="text-xs text-slate-500">
            Captures what you're looking at right now (data only — no customer names or addresses) and opens a GitHub issue a coding agent can pick up.
          </p>
          <textarea
            value={note}
            onChange={(e) => setNote(e.target.value)}
            placeholder="What looked wrong? (optional)"
            autoFocus
            className="w-full text-sm border border-slate-300 rounded-xl px-3 py-2 h-24 resize-y focus:outline-none focus:ring-2 focus:ring-blue-200 focus:border-blue-400"
          />
          {result && (
            <a href={result.issueUrl} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 text-sm font-medium hover:underline" style={{ color: BRAND }}>
              <ExternalLink size={14} /> Opened issue{result.issueNumber ? ` #${result.issueNumber}` : ''} →
            </a>
          )}
          {result && <div className="text-[11px] text-slate-400">Closing…</div>}
          {error && <div className="text-xs text-red-600 bg-red-50 border border-red-200 rounded px-2 py-1.5">{error}</div>}
        </div>
        <div className="border-t p-3">
          <button
            onClick={send}
            disabled={busy}
            className="w-full text-sm font-semibold py-2.5 rounded-xl text-white disabled:opacity-50 inline-flex items-center justify-center gap-2"
            style={{ background: BRAND }}
          >
            {busy ? <RefreshCw size={15} className="animate-spin" /> : <Send size={15} />}
            {busy ? 'Sending…' : 'Send to coding agent'}
          </button>
        </div>
      </div>
    </div>
  );
}

function MapScreen({ onOpenMessages, smsUnread = 0, debugCaptureRef, presence = null }) {
  // M5 — selectedDate drives every fetch. Defaults to today (ET) and is NOT
  // persisted: every page load resets to today (brief P2.2).
  const [selectedDate, setSelectedDate] = useState(() => todayInET());
  const dateIsToday = isTodayET(selectedDate);

  // Declared before useStops because the carry-over fetch reads mapFilters.carryoverDays
  // (referencing it after the useStops call hit a temporal-dead-zone crash).
  const [mapFilters, setMapFilters] = useState(() => {
    const stored = safeReadJSON(LS_MAP_FILTERS, {}) || {};
    // Migrate the old boolean carry-over toggle → day count (true meant 7 days).
    if (stored.carryoverDays == null && typeof stored.carryover === 'boolean') {
      stored.carryoverDays = stored.carryover ? CARRYOVER_DAYS : 0;
      delete stored.carryover;
    }
    // One-time: clustering now defaults OFF (Chad's preference). Flip any device still
    // carrying the old ON default exactly once, then respect the toggle from then on.
    if (!stored.clusterDefaultOffApplied) {
      stored.showClustered = false;
      stored.clusterDefaultOffApplied = true;
    }
    return { ...DEFAULT_MAP_FILTERS, ...stored };
  });

  const { stops, loading, error, lastRefreshed, lastScannedAt, lastLoadScanAt, lastUnplannedScanAt, scanState, source, ops, scanUnplannedCount, refresh } = useStops(selectedDate, mapFilters.carryoverDays || 0);

  // Manual "Scan now" — the cheap list-discovery scan, shared logic in useManualScan
  // (also used by the Routing tab's status card). See the hook for the cost notes.
  const { scanning, scanCooldown, scanErr, manualScan } = useManualScan(selectedDate, lastScannedAt, refresh);

  // Another dispatcher just SAVED (their presence doc's saveAt moved) → silently
  // re-read the Firestore board now, instead of waiting out the 2-minute poll.
  // Zero NuVizz calls — same cheap cache read the poll does.
  const lastPeerSaveRef = useRef(null);
  useEffect(() => {
    const t = latestPeerSaveAt(presence?.peers);
    if (lastPeerSaveRef.current == null) { lastPeerSaveRef.current = t; return; }
    if (t > lastPeerSaveRef.current) { lastPeerSaveRef.current = t; refresh({ silent: true }); }
  }, [presence?.peers, refresh]);

  const { notes, ready: notesReady } = useCustomerNotes();
  const tractorLocs = useTractorLocations();
  useAutoScanner(stops, notes, notesReady);
  const { google, error: mapsError } = useGoogleMaps();
  const viewportWidth = useViewportWidth();
  const isMobile = viewportWidth < MOBILE_BREAKPOINT;

  const [selectedStop, setSelectedStop] = useState(null);
  const [selectedDriver, setSelectedDriver] = useState(null);
  const [selectedRoute, setSelectedRoute] = useState(null); // M5.2 — loadNbr of opened route, or null
  const [routeMapView, setRouteMapView] = useState(false);  // mobile: route sheet minimized to view the framed route on the map
  // Routes panel (read-only) on the dispatch Map — a togglable right-side route roster mirroring the
  // Routing screen's Routes view. Persisted; off by default. Loads NuVizz's real load status (cheap
  // cached roster) only while the panel is open.
  const [routesPanelOn, setRoutesPanelOn] = useState(() => {
    try { return localStorage.getItem('map.routesPanel') === 'on'; } catch { return false; }
  });
  useEffect(() => { try { localStorage.setItem('map.routesPanel', routesPanelOn ? 'on' : 'off'); } catch { /* ignore */ } }, [routesPanelOn]);
  const [routesLoadStatus, setRoutesLoadStatus] = useState(() => new Map());
  useEffect(() => {
    if (!routesPanelOn || !selectedDate) return;
    let cancelled = false;
    fetch('/.netlify/functions/nuvizz-loads-roster?date=' + encodeURIComponent(selectedDate), { cache: 'no-store' })
      .then((r) => r.json())
      .then((j) => {
        if (cancelled) return;
        const m = new Map();
        if (j && j.ok) for (const l of (j.loads || [])) {
          const nm = String(l.name || '').trim().toLowerCase();
          if (nm) m.set(nm, l.status || '');
          if (l.loadId) m.set('#id:' + String(l.loadId), l.status || '');
        }
        setRoutesLoadStatus(m);
      })
      .catch(() => { if (!cancelled) setRoutesLoadStatus(new Map()); });
    return () => { cancelled = true; };
  }, [routesPanelOn, selectedDate]);
  const routeGroups = useMemo(() => (routesPanelOn ? computeRouteGroups(stops, routesLoadStatus) : []), [routesPanelOn, stops, routesLoadStatus]);
  // M5 — Show Routes toggle (persisted). Polylines render only when ON.
  const [showRoutes, setShowRoutes] = useState(() => safeReadJSON(LS_SHOW_ROUTES, false));
  const [filters, setFilters] = useState({});
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState(null);
  // M4.5 P3.3 — Driver marker labels are hidden by default on mobile to reduce
  // visual clutter; tapping a marker temporarily reveals the label as a side
  // effect of opening the driver-snapshot drawer (the labels stay visible while
  // the toggle is on; defaulting it off keeps the small viewport readable).
  const [showDriverLabels, setShowDriverLabels] = useState(() => {
    const stored = safeReadJSON(LS_DRIVER_LABELS, null);
    if (typeof stored === 'boolean') return stored;
    const w = typeof window === 'undefined' ? 1280 : window.innerWidth;
    return w >= MOBILE_BREAKPOINT;
  });
  const [legendExpanded, setLegendExpanded] = useState(() => safeReadJSON(LS_LEGEND_EXPANDED, false));
  const [routeLegendExpanded, setRouteLegendExpanded] = useState(() => safeReadJSON(LS_ROUTE_LEGEND_EXPANDED, true));
  const [bottomTableOpen, setBottomTableOpen] = useState(() => safeReadJSON(LS_BOTTOM_TABLE_OPEN, false));
  const [tableColumns, setTableColumns] = useState(() => ({
    ...DEFAULT_TABLE_COLUMNS,
    ...safeReadJSON(LS_TABLE_COLUMNS, {}),
  }));
  // M4.4 — Map filter toolbar state. The "Show vehicle location" toggle is the
  // same Motive driver overlay that previously lived in the left panel; the
  // duplicate left-panel toggle is removed.
  const [toolbarCollapsed, setToolbarCollapsed] = useState(() => safeReadJSON(LS_FILTER_TOOLBAR_COLLAPSED, true));
  const [statusCollapsed, setStatusCollapsed] = useState(() => safeReadJSON(LS_STATUS_PILL_COLLAPSED, false));
  // M4.5 — Mobile drawer is closed by default on every load; active tab is
  // restored from localStorage so repeat dispatchers land where they left off.
  const [mobileDrawerOpen, setMobileDrawerOpen] = useState(false);
  const [mobileDrawerTab, setMobileDrawerTab] = useState(() => {
    const t = safeReadJSON(LS_MOBILE_DRAWER_TAB, 'stops');
    return ['stops', 'filters', 'loads'].includes(t) ? t : 'stops';
  });
  // M5 — live drivers (Motive) only meaningful for today. On any other date the
  // overlay is forced off regardless of the toggle's stored value.
  const showDrivers = mapFilters.showVehicleLocation && dateIsToday;
  const [searchInput, setSearchInput] = useState('');
  const debouncedSearch = useDebouncedValue(searchInput, 200);
  const { history, remember } = useSearchHistory();
  // Desktop historical PRO / customer-history lookup (mobile has its own in
  // MobileStopsTab). Rendered as an overlay so the board stays mounted behind it.
  const [histOpen, setHistOpen] = useState(false);
  // What the customer-history overlay opens seeded with. The top "Search past PROs"
  // button seeds it with the live search; a stop card's "History" button seeds it
  // with that customer's name so it opens straight to their past PROs + drivers.
  const [histSeed, setHistSeed] = useState('');
  // The card "History" button opens a Firestore-only view (noApi); the top "Search
  // past PROs" button keeps the deliberate single-PRO NuVizz lookup available.
  const [histNoApi, setHistNoApi] = useState(false);
  const openCustomerHistory = useCallback((s) => { setHistSeed((s?.businessName || '').trim()); setHistNoApi(true); setHistOpen(true); }, []);

  // M6 — AI Order Search state. aiMode flips the search box into NL parse mode;
  // aiResult holds the AI-derived match set (from search OR chat) that overrides
  // the literal keyword filter. aiAvailable gates the affordance on the key being
  // configured server-side (probed once via the function's GET endpoint).
  const [aiMode, setAiMode] = useState(false);
  const [aiResult, setAiResult] = useState(null); // { set:Set<stopNbr>, summary, source }
  const [aiBusy, setAiBusy] = useState(false);
  const [aiError, setAiError] = useState(null);
  const [aiAvailable, setAiAvailable] = useState(true);
  const [chatOpen, setChatOpen] = useState(false);
  useEffect(() => {
    let alive = true;
    fetch('/.netlify/functions/ai-search')
      .then((r) => r.json())
      .then((d) => { if (alive) setAiAvailable(!!d?.available); })
      .catch(() => { /* leave optimistic; POST surfaces ai_key_missing if needed */ });
    return () => { alive = false; };
  }, []);

  // Box / lasso multi-select. selectMode is the armed tool while drawing;
  // selectionSet is the resulting Set<stopNbr> that highlights + filters the
  // board (via effectiveMatchSet, same mechanism as search/AI). The projection
  // ref converts container pixels <-> LatLng for the drawn shape.
  const [selectMode, setSelectMode] = useState(null); // null | 'box' | 'lasso'
  const [selectionSet, setSelectionSet] = useState(null);
  const [selectNote, setSelectNote] = useState(null);
  const selectionOverlayRef = useRef(null); // OverlayView; getProjection() on demand

  // Pin relocation: movingStop is the stop whose pin is being dragged to its real
  // spot; movedTo holds the dragged coords; saved to customer_notes.location_override.
  const [movingStop, setMovingStop] = useState(null);
  const [movedTo, setMovedTo] = useState(null);
  const [savingLoc, setSavingLoc] = useState(false);
  const [editAddrStop, setEditAddrStop] = useState(null);
  const [editAddrSeed, setEditAddrSeed] = useState(null); // suggested split when opened from the fix banner
  // Open the address editor, optionally seeded with a suggested addr1/addr2 split.
  const openAddrEditor = useCallback((stop, seed = null) => { setEditAddrSeed(seed || null); setEditAddrStop(stop); }, []);
  const movingMarkerRef = useRef(null);

  const { drivers, error: driverErr, lastRefreshed: driversAt } = useDriverPositions(showDrivers);
  const { snapshot, loading: snapshotLoading, error: snapshotError } = useDriverSnapshot(selectedDriver);
  const panel = useResizablePanel(viewportWidth);

  // Driver source for the DNS "barred drivers" picker. Three sources, merged &
  // de-duped case-insensitively (board form wins so a driver on today's loads
  // keeps the label used elsewhere):
  //   1. drivers assigned to the current board's loads (from the scan),
  //   2. the FULL Motive roster (fleet app) — so ANY driver can be barred, not
  //      just ones on today's board or currently positioned,
  //   3. live-positioned Motive drivers (when "Show drivers (live)" is on).
  // Synthetic {driverName} objects are fine — the notes editor only reads .driverName.
  const driverRoster = useDriverRoster();
  const notesDrivers = useMemo(() => {
    const seen = new Set();
    const out = [];
    const add = (name) => {
      const nm = (name || '').trim();
      const k = nm.toLowerCase();
      if (!nm || seen.has(k)) return;
      seen.add(k);
      out.push({ driverName: nm });
    };
    (stops || []).forEach((s) => add(s.driverName));
    (driverRoster || []).forEach((d) => add(d?.name));
    (drivers || []).forEach((d) => add(d?.driverName));
    return out.sort((a, b) => a.driverName.localeCompare(b.driverName));
  }, [drivers, stops, driverRoster]);

  const searchInputRef = useRef(null);
  const mapRef = useRef(null);
  const mapDiv = useRef(null);
  const recenterRef = useRef(null); // latest "fit to stops" fn for the custom control
  const clustererRef = useRef(null);
  const markersRef = useRef([]);
  const driverMarkersRef = useRef([]);
  const driverLabelsRef = useRef([]);
  const labelOverlayClassRef = useRef(null);
  const hoverTipRef = useRef(null); // {marker, tip} — the receiving-hours hover tooltip currently shown
  const routePolylinesRef = useRef([]);

  // Persist label-toggle preference whenever it changes.
  useEffect(() => { safeWriteJSON(LS_DRIVER_LABELS, showDriverLabels); }, [showDriverLabels]);
  useEffect(() => { safeWriteJSON(LS_LEGEND_EXPANDED, legendExpanded); }, [legendExpanded]);
  useEffect(() => { safeWriteJSON(LS_TABLE_COLUMNS, tableColumns); }, [tableColumns]);
  useEffect(() => { safeWriteJSON(LS_MAP_FILTERS, mapFilters); }, [mapFilters]);
  useEffect(() => { safeWriteJSON(LS_FILTER_TOOLBAR_COLLAPSED, toolbarCollapsed); }, [toolbarCollapsed]);
  useEffect(() => { safeWriteJSON(LS_STATUS_PILL_COLLAPSED, statusCollapsed); }, [statusCollapsed]);
  useEffect(() => { safeWriteJSON(LS_MOBILE_DRAWER_TAB, mobileDrawerTab); }, [mobileDrawerTab]);
  useEffect(() => { safeWriteJSON(LS_SHOW_ROUTES, showRoutes); }, [showRoutes]);
  useEffect(() => { safeWriteJSON(LS_ROUTE_LEGEND_EXPANDED, routeLegendExpanded); }, [routeLegendExpanded]);
  useEffect(() => { safeWriteJSON(LS_BOTTOM_TABLE_OPEN, bottomTableOpen); }, [bottomTableOpen]);

  // M5 — date change side effects: close any open sidebars (their data was for
  // the previous day) and surface a one-shot note if live drivers were on for a
  // now-non-today date. Stops + routes refetch automatically (date is a dep of
  // useStops + the routes memo). The auto-scanner re-runs when new stops land.
  const [driverGateNote, setDriverGateNote] = useState(false);
  const prevDateRef = useRef(selectedDate);
  useEffect(() => {
    if (prevDateRef.current === selectedDate) return;
    prevDateRef.current = selectedDate;
    setSelectedStop(null);
    setSelectedDriver(null);
    if (!dateIsToday && mapFilters.showVehicleLocation) {
      setDriverGateNote(true);
      setTimeout(() => setDriverGateNote(false), 4000);
    }
  }, [selectedDate, dateIsToday, mapFilters.showVehicleLocation]);

  const goToToday = useCallback(() => setSelectedDate(todayInET()), []);

  // M4.4 — Compute stem-out set client-side. Stem-out = first non-terminal stop
  // in each load (i.e. the outbound leg from terminal to first customer).
  // Stops without a load assignment can't be marked stem-out.
  const stemOutKeys = useMemo(() => {
    const firstSeqByLoad = new Map();
    for (const s of stops) {
      if (!s.loadNbr || s.isTerminal || s.loadStopSeq == null) continue;
      const prev = firstSeqByLoad.get(s.loadNbr);
      if (prev == null || s.loadStopSeq < prev.seq) {
        firstSeqByLoad.set(s.loadNbr, { seq: s.loadStopSeq, key: s.stopNbr });
      }
    }
    const out = new Set();
    for (const v of firstSeqByLoad.values()) if (v.key) out.add(v.key);
    return out;
  }, [stops]);

  // M4.4 — Apply filter toolbar toggles after the existing flag/restriction
  // filter pipeline. Each toggle is a simple inclusion/exclusion test.
  const applyMapFilters = useCallback((rows) => {
    return rows.filter((s) => {
      if (mapFilters.hideTerminal && s.isTerminal) return false;
      if (mapFilters.hideStemOut && stemOutKeys.has(s.stopNbr)) return false;
      // "Unplanned only" ON → hide everything that IS planned (on a load/route);
      // OFF → show all. (isUnplanned means "no driver yet" — wrong signal here;
      // a routed stop with no driver assigned is still planned.)
      if (mapFilters.unplannedOnly && s.isPlanned) return false;
      return true;
    });
  }, [mapFilters.hideTerminal, mapFilters.hideStemOut, mapFilters.unplannedOnly, stemOutKeys]);

  // The same three toggles applyMapFilters tests, in words — so the bottom grid's empty state can
  // NAME what removed the rows instead of blaming only its own status/search bar.
  const mapFilterLabels = useMemo(() => [
    mapFilters.unplannedOnly && 'Unplanned only',
    mapFilters.hideTerminal && 'Hide terminal',
    mapFilters.hideStemOut && 'Hide stem out',
  ].filter(Boolean), [mapFilters.unplannedOnly, mapFilters.hideTerminal, mapFilters.hideStemOut]);

  // Filter pipeline: filters → mapFilters → search. Memoized so we don't recompute on each render.
  // A saved customer_notes.location_override replaces the (often wrong) NuVizz
  // geocode for that customer, so the corrected pin sticks for every future load.
  const filteredStops = useMemo(
    () => applyMapFilters(applyFilters(stops, notes, filters)).map((s) => {
      const ov = notes.get(s.matchKey)?.location_override;
      return (ov && typeof ov.lat === 'number' && typeof ov.lng === 'number') ? { ...s, lat: ov.lat, lng: ov.lng } : s;
    }),
    [stops, notes, filters, applyMapFilters],
  );
  // Total pallet count across the loaded board. NuVizz records the pallet count
  // in its carton field (stop.cartons), so we sum that and label it pallets.
  const totalPalletsCount = useMemo(
    () => stops.reduce((sum, s) => sum + (Number(s.cartons) || 0), 0),
    [stops],
  );
  const carryoverCount = useMemo(() => stops.reduce((n, s) => n + (s.carryover ? 1 : 0), 0), [stops]);
  // Unplanned stops the board is CURRENTLY showing — the map-filtered set, which is what
  // feeds the stops list. Paired with the scan's own tally (scanUnplannedCount) so the
  // status card can name how many the filters are holding back.
  const visibleUnplannedCount = useMemo(
    () => filteredStops.reduce((n, s) => n + (s.isUnplanned ? 1 : 0), 0),
    [filteredStops],
  );

  // ── Box / lasso selection ──────────────────────────────────────────────────
  // The live pixel<->LatLng projection is published by an OverlayView created in
  // the map-init effect (must run after mapRef exists). Converts the drawn
  // shape's container pixels to LatLng for the shared enclosure geometry.
  const pxToLatLng = useCallback((x, y) => {
    const proj = selectionOverlayRef.current?.getProjection();
    if (!proj) return null;
    const ll = proj.fromContainerPixelToLatLng(new google.maps.Point(x, y));
    return ll ? { lat: ll.lat(), lng: ll.lng() } : null;
  }, [google]);

  const commitSelection = useCallback((hits) => {
    if (!hits.length) { setSelectNote('No stops in that area'); setTimeout(() => setSelectNote(null), 2500); return; }
    setSelectionSet(new Set(hits.map((s) => s.stopNbr)));
    setSelectNote(`${hits.length} stop${hits.length === 1 ? '' : 's'} selected`);
  }, []);

  // Box: two opposite container-pixel corners. Lasso: a container-pixel path.
  const selectByBox = useCallback((p1, p2) => {
    const a = pxToLatLng(p1.x, p1.y), b = pxToLatLng(p2.x, p2.y);
    if (!a || !b) return;
    const box = boxFromCorners(a, b);
    commitSelection(filteredStops.filter((s) => s.lat != null && s.lng != null && latLngInBounds(s.lat, s.lng, box)));
  }, [pxToLatLng, filteredStops, commitSelection]);

  const selectByLasso = useCallback((pts) => {
    const poly = pts.map((p) => pxToLatLng(p.x, p.y)).filter(Boolean).map((ll) => [ll.lat, ll.lng]);
    if (poly.length < 3) return;
    commitSelection(filteredStops.filter((s) => s.lat != null && s.lng != null && pointInPolygon(s.lat, s.lng, poly)));
  }, [pxToLatLng, filteredStops, commitSelection]);

  const clearSelection = useCallback(() => { setSelectionSet(null); setSelectNote(null); }, []);

  // SMS compose target ({ title, recipients }) — null = closed. Set by the
  // single-stop "Text" button and the bulk "Text selected" action.
  const [smsTargets, setSmsTargets] = useState(null);
  const textCustomer = useCallback((stop) => {
    if (!stop) return;
    const phone = resolveStopPhone(stop, notes.get(stop.matchKey));
    // Always open the composer; if no number is on file the dispatcher can type
    // one in (the modal validates before allowing send). Opens on the order's
    // reference line (PRO + customer), same as the driver text.
    setSmsTargets({ title: `Text ${stop.businessName || 'customer'}`, recipients: [{ to: phone, label: stop.businessName || stop.stopNbr }], initialText: stopRefPrefill(stop) });
  }, [notes]);
  const textSelected = useCallback(() => {
    if (!selectionSet?.size) return;
    const chosen = stops.filter((s) => selectionSet.has(s.stopNbr));
    const recipients = [];
    let skipped = 0;
    for (const s of chosen) {
      const phone = resolveStopPhone(s, notes.get(s.matchKey));
      if (phone) recipients.push({ to: phone, label: s.businessName || s.stopNbr });
      else skipped++;
    }
    if (!recipients.length) { setSelectNote('No phone numbers in the selected stops'); return; }
    setSmsTargets({ title: `Text ${recipients.length} selected${skipped ? ` (${skipped} have no phone)` : ''}`, recipients });
  }, [selectionSet, stops, notes]);
  // Text a driver by NAME — the phone is resolved server-side from the MarginIQ
  // employee roster (number never reaches the browser).
  const textDriver = useCallback((driverName) => {
    if (!driverName) return;
    setSmsTargets({ title: `Text ${driverName}`, recipients: [{ driverName, label: driverName }] });
  }, []);
  // Text the driver ASSIGNED TO THIS ORDER, prefilled with the order's PRO + customer so the
  // driver knows which delivery it's about. Number resolves server-side from the roster.
  const textDriverForStop = useCallback((stop) => {
    const driverName = stop?.driverName;
    if (!driverName) return;
    setSmsTargets({ title: `Text ${driverName}`, recipients: [{ driverName, label: driverName }], initialText: stopRefPrefill(stop) });
  }, []);
  // Bulk: text the DISTINCT drivers of the selected stops (one text per driver).
  const textSelectedDrivers = useCallback(() => {
    if (!selectionSet?.size) return;
    const names = [...new Set(stops.filter((s) => selectionSet.has(s.stopNbr)).map((s) => s.driverName).filter(Boolean))];
    if (!names.length) { setSelectNote('No drivers assigned to the selected stops'); return; }
    setSmsTargets({ title: `Text ${names.length} driver${names.length === 1 ? '' : 's'}`, recipients: names.map((driverName) => ({ driverName, label: driverName })) });
  }, [selectionSet, stops]);

  // Pin relocation handlers + the draggable marker that the dispatcher drags.
  const startMoveLocation = useCallback((stop) => {
    // Keep the order card OPEN (Chad). Clearing selectedStop here used to close the
    // card and — because it left nothing selected — trip the "everything deselected"
    // board-view restore below, which panned/zoomed the map back out ("3 cities away").
    // Leaving the selection keeps the map framed on the pin where it already is.
    setSelectedDriver(null);
    setMovedTo(null); setMovingStop(stop);
  }, []);
  // One-click address fix: apply the suggested split, re-geocode the clean street
  // (addr2/suite deliberately excluded) and save address_override + the corrected
  // pin. Throws on geocode/save failure so the banner can surface the error.
  const autoFixAddress = useCallback(async (stop, suggestion) => {
    if (!db || !stop || !suggestion) return;
    const fields = {
      addr1: (suggestion.addr1 || '').trim(),
      addr2: (suggestion.addr2 || '').trim(),
      city: stop.city || '', state: stop.state || '', zip: stop.zip || '',
    };
    const q = [fields.addr1, fields.city, fields.state, fields.zip].filter(Boolean).join(', ');
    // Geocode is best-effort: if it fails (e.g. the Geocoding API isn't enabled →
    // REQUEST_DENIED), still SAVE the corrected addr1/addr2 split so the fix isn't
    // lost — just leave the pin where it was. The dispatcher can drag it via
    // "Correct pin location", and a re-fix will move it once geocoding works.
    let geo = null, geoErr = null;
    try { geo = await geocodeAddress(google, q); } catch (e) { geoErr = e; }
    const payload = {
      match_key: stop.matchKey,
      raw_name: stop.businessName || '',
      address_override: fields,
      address_override_at: serverTimestamp(),
      last_updated: serverTimestamp(),
    };
    if (geo) { payload.location_override = { lat: geo.lat, lng: geo.lng }; payload.location_override_at = serverTimestamp(); }
    await setDoc(doc(db, 'customer_notes', stop.matchKey), payload, { merge: true });
    refresh({ silent: true });
    // Saved the address; surface (non-fatally) that the pin couldn't be moved.
    if (geoErr) throw new Error(`Address saved, but the pin couldn’t be moved — ${geoErr.message}. Enable the Geocoding API or use “Correct pin location” to drag it.`);
  }, [google, refresh]);
  const cancelMoveLocation = useCallback(() => { setMovingStop(null); setMovedTo(null); }, []);
  const saveStopLocation = useCallback(async () => {
    if (!db || !movingStop || !movedTo) return;
    setSavingLoc(true);
    try {
      await setDoc(doc(db, 'customer_notes', movingStop.matchKey), {
        match_key: movingStop.matchKey,
        raw_name: movingStop.businessName || '',
        location_override: { lat: movedTo.lat, lng: movedTo.lng },
        location_override_at: serverTimestamp(),
        last_updated: serverTimestamp(),
      }, { merge: true });
      setMovingStop(null); setMovedTo(null);
    } catch (e) { console.error('save location override', e); }
    finally { setSavingLoc(false); }
  }, [movingStop, movedTo]);
  const resetStopLocation = useCallback(async () => {
    if (!db || !movingStop) return;
    setSavingLoc(true);
    try {
      await setDoc(doc(db, 'customer_notes', movingStop.matchKey), {
        match_key: movingStop.matchKey, location_override: null, last_updated: serverTimestamp(),
      }, { merge: true });
      setMovingStop(null); setMovedTo(null);
    } catch (e) { console.error('reset location override', e); }
    finally { setSavingLoc(false); }
  }, [movingStop]);

  useEffect(() => {
    if (movingMarkerRef.current) { movingMarkerRef.current.setMap(null); movingMarkerRef.current = null; }
    if (!google || !mapRef.current || !movingStop) return;
    const ov = notes.get(movingStop.matchKey)?.location_override;
    const start = {
      lat: (ov && typeof ov.lat === 'number') ? ov.lat : movingStop.lat,
      lng: (ov && typeof ov.lng === 'number') ? ov.lng : movingStop.lng,
    };
    if (start.lat == null || start.lng == null) return;
    setMovedTo(start);
    const m = new google.maps.Marker({
      position: start, map: mapRef.current, draggable: true, zIndex: 99999,
      icon: { url: pinSvgStatus('#1e5b92', {}), scaledSize: new google.maps.Size(34, 44), anchor: new google.maps.Point(17, 42) },
      title: 'Drag to the correct location',
      animation: google.maps.Animation.DROP,
    });
    m.addListener('dragend', () => { const p = m.getPosition(); if (p) setMovedTo({ lat: p.lat(), lng: p.lng() }); });
    movingMarkerRef.current = m;
    // Don't move the map if the pin is already on screen (Chad: "the map shouldn't
    // have moved at all"). Only recenter when the stop sits outside the current view,
    // so the draggable pin can never drop off-screen where you can't grab it.
    const b = mapRef.current.getBounds();
    if (!b || !b.contains(new google.maps.LatLng(start.lat, start.lng))) {
      mapRef.current.panTo(start);
      if ((mapRef.current.getZoom() || 0) < 16) mapRef.current.setZoom(18);
    }
    return () => { m.setMap(null); };
  }, [google, movingStop]); // eslint-disable-line react-hooks/exhaustive-deps

  const searchMatchSet = useMemo(() => {
    if (aiMode) return null;                       // AI mode: literal keyword filter suspended
    if (!debouncedSearch.trim()) return null;      // null sentinel = no search active
    const set = new Set();
    for (const s of filteredStops) {
      if (stopMatchesSearch(s, notes.get(s.matchKey), debouncedSearch)) set.add(s.stopNbr);
    }
    return set;
  }, [filteredStops, notes, debouncedSearch, aiMode]);

  // Clear EVERY stop filter — the left Filters panel AND the three map toggles. Chad's board
  // had one of each ("Has receiving hours" + "Hide stem out"), so clearing either alone would
  // still have hidden the stop he was looking for.
  const clearAllStopFilters = useCallback(() => {
    setFilters({});
    setMapFilters((prev) => ({ ...prev, hideTerminal: false, hideStemOut: false, unplannedOnly: false }));
  }, []);

  // A search that finds NOTHING because the FILTERS hid it (Chad, Jul 31: searched PRO
  // 7153822, got 'No stops match "7153822"' — "this is showing nothing however this is planned
  // on a route today trailer 6"; then: "all stop filters were the problem"). The stop was on
  // the board the whole time; "Has receiving hours" and "Hide stem out" were holding it back,
  // and the search box said only that nothing matched.
  //
  // searchMatchSet is built from filteredStops, so a filtered-out stop can never be found and
  // the message can never explain itself. This re-runs the SAME matcher over the unfiltered
  // board purely to answer "would this have matched if nothing were hidden?" — the grid has
  // named its own filters since v0.45.6/v0.53.11; the search box never learned to.
  // Only computed when a search is active and found nothing, so it costs nothing normally.
  const searchHiddenByFilters = useMemo(() => {
    if (aiMode || aiResult || selectionSet) return 0;
    const q = debouncedSearch.trim();
    if (!q || (searchMatchSet && searchMatchSet.size > 0)) return 0;
    let n = 0;
    for (const s of stops) if (stopMatchesSearch(s, notes.get(s.matchKey), q)) n += 1;
    return n;
  }, [stops, notes, debouncedSearch, searchMatchSet, aiMode, aiResult, selectionSet]);

  // M6 — an active AI result (search parse or chat highlight) takes precedence
  // over the literal keyword set. Everything downstream (list + map dim/fit) reads
  // effectiveMatchSet so all surfaces share one filter mechanism. Box/lasso
  // selection takes precedence over search/AI when active.
  const effectiveMatchSet = selectionSet || (aiResult ? aiResult.set : searchMatchSet);

  const visibleStops = useMemo(() => {
    if (!effectiveMatchSet) return filteredStops;
    return filteredStops.filter((s) => effectiveMatchSet.has(s.stopNbr));
  }, [filteredStops, effectiveMatchSet]);

  // Board completion for the stops-count header (Chad: "% completed"). Delivered ÷ the whole
  // day's board — deliberately independent of the search box AND the map filters, so it reads
  // as "how much of today is done" and doesn't jump around while you filter. Null on an empty
  // board (nothing to show a % for).
  const boardCompletion = useMemo(() => {
    const total = stops.length;
    if (!total) return null;
    let delivered = 0;
    for (const s of stops) if (classifyStopStatus(s) === 'DELIVERED') delivered += 1;
    return { delivered, total, pct: Math.round((delivered / total) * 100) };
  }, [stops]);

  // M6 — AI search/chat handlers. runAiSearch parses the NL query and applies the
  // returned spec locally; runChat builds the trimmed context and asks the model.
  const runAiSearch = useCallback(async (q) => {
    const query = (q || '').trim();
    if (!query) return;
    setAiBusy(true); setAiError(null);
    try {
      const { spec } = await aiParse(query);
      const set = applyFilterSpec(filteredStops, notes, spec);
      const empty = !spec || ((spec.predicates || []).length === 0 && !spec.text_match);
      if (empty || set.size === 0) {
        // Nothing parseable / no matches → fall back to literal keyword search.
        setAiResult(null);
        setAiMode(false);
        setSearchInput(query);
        setAiError(empty ? 'Couldn’t turn that into a filter — showing keyword matches.' : 'No stops matched that — showing keyword matches.');
        return;
      }
      setAiResult({ set, summary: summarizeSpec(spec, set.size), source: 'search' });
      remember(query);
    } catch (e) {
      setAiError(e?.code === 'ai_key_missing'
        ? 'AI search isn’t configured yet (missing API key).'
        : 'AI search is unavailable right now.');
    } finally {
      setAiBusy(false);
    }
  }, [filteredStops, notes, remember]);

  const clearAi = useCallback(() => { setAiResult(null); setAiError(null); }, []);

  const handleChatSend = useCallback(async (q) => {
    const { stops: ctx, truncated, sent, total } = buildTrimmedStops(filteredStops, notes, 400);
    const res = await aiChat(q, ctx);
    return { ...res, truncated, sent, total };
  }, [filteredStops, notes]);

  // Highlight the stops a chat answer referenced. Uses the model's MATCHED_PRO_IDS
  // line AND any stop numbers it listed in the prose — the latter covers long
  // answers where the trailing IDs line got cut off by the token cap. Returns the
  // count so the chat bubble can report it. Only sets a highlight when non-empty.
  const handleChatHighlight = useCallback((proIds, answerText) => {
    const wanted = new Set((proIds || []).map((p) => String(p).trim()));
    const text = String(answerText || '');
    const set = new Set();
    for (const s of filteredStops) {
      const id = String(s.stopNbr);
      if (wanted.has(id) || (id && text.includes(id))) set.add(s.stopNbr);
    }
    if (set.size) setAiResult({ set, summary: `${set.size} stop${set.size === 1 ? '' : 's'} from chat`, source: 'chat' });
    return set.size;
  }, [filteredStops]);

  // "Debug this view" — snapshot what the dispatcher is looking at right now and
  // hand it to the coding agent. Reads live map refs + state; scrubs PII; never
  // leaks the Maps key. Returns the backend result ({ issueUrl, issueNumber }).
  const buildDebugBundle = useCallback((note) => {
    const map = mapRef.current;
    let viewport = null;
    if (map && typeof map.getCenter === 'function') {
      const c = map.getCenter?.();
      const b = map.getBounds?.();
      viewport = {
        center: c ? { lat: +c.lat().toFixed(6), lng: +c.lng().toFixed(6) } : null,
        zoom: map.getZoom?.() ?? null,
        bounds: b ? b.toJSON() : null,
      };
    }
    const noteFor = (mk) => notes.get(mk) || null;
    const CAP = 500;

    const bundle = {
      schema: 'dispatch-map.debug-capture/v1',
      captured_at: new Date().toISOString(),
      app: {
        version: APP_VERSION,
        build_commit: BUILD_COMMIT,
        build_time: BUILD_TIME,
        build_context: BUILD_CONTEXT,
        user_agent: typeof navigator !== 'undefined' ? navigator.userAgent : '',
        viewport_width: viewportWidth,
        is_mobile: isMobile,
      },
      scope: {
        date: selectedDate,
        date_is_today: dateIsToday,
        mock_mode: MOCK_MODE,
        maps_loaded: !!google,
      },
      source: {
        stops_source: source,
        loading,
        error: error || null,
        stops_count_total: stops.length,
        stops_count_visible: filteredStops.length,
        last_refreshed: lastRefreshed ? new Date(lastRefreshed).toISOString() : null,
        last_scanned_at: lastScannedAt || null,
        last_load_scan_at: lastLoadScanAt || null,
        last_unplanned_scan_at: lastUnplannedScanAt || null,
        scan_state: scanState ?? null,
        ops: ops ?? null,
      },
      map_filters: mapFilters,
      filters,
      search: { query: debouncedSearch, ai_mode: aiMode },
      ai: aiResult
        ? { active: true, summary: aiResult.summary, source: aiResult.source, match_count: aiResult.set ? aiResult.set.size : null }
        : { active: false },
      selection: {
        kind: selectedDriver ? 'driver' : selectedRoute ? 'route' : selectedStop ? 'stop' : (selectionSet && selectionSet.size ? 'multi' : null),
        stop: selectedStop ? scrubStop(selectedStop, null, noteFor(selectedStop.matchKey)) : null,
        driver: selectedDriver
          ? { driverName: selectedDriver.driverName, driverUserName: selectedDriver.driverUserName, vehicleNumber: selectedDriver.vehicleNumber }
          : null,
        route_load_nbr: selectedRoute || null,
        multi_count: selectionSet ? selectionSet.size : 0,
        select_mode: selectMode,
      },
      map_viewport: viewport,
      static_map_url: viewport ? buildStaticMapUrl(viewport.center, viewport.zoom, filteredStops) : null,
      rendered_stops: filteredStops.slice(0, CAP).map((s, i) => scrubStop(s, i, noteFor(s.matchKey))),
      rendered_stops_truncated: filteredStops.length > CAP,
      rendered_stops_note: 'order = filtered board order, NOT geographic route sequence; routeSeq/loadStopSeq carry NuVizz sequence',
      notes_meta: { loaded_count: notes.size },
      warnings: [
        'static_map_url embeds the Maps key as __MAPS_KEY__ — swap it in locally to view; no real secret is included.',
        'Customer names/addresses/contacts and the raw NuVizz payload are scrubbed from stops; only the join matchKey + coords remain.',
      ],
      user_note: note || '',
    };

    // Safety net: never let the real Maps key escape into the bundle.
    if (MAPS_KEY) {
      const text = JSON.stringify(bundle);
      if (text.includes(MAPS_KEY)) return JSON.parse(text.split(MAPS_KEY).join('__MAPS_KEY__'));
    }
    return bundle;
  }, [
    notes, filteredStops, stops, selectedDate, dateIsToday, google, source, loading, error,
    lastRefreshed, lastScannedAt, lastLoadScanAt, lastUnplannedScanAt, scanState, ops,
    mapFilters, filters, debouncedSearch, aiMode, aiResult, selectedStop, selectedDriver,
    selectedRoute, selectionSet, selectMode, viewportWidth, isMobile,
  ]);

  // Chat fold posts directly; the Shell sheet pulls the bundle via the ref.
  const handleDebugCapture = useCallback((note) => postDebugBundle(buildDebugBundle(note)), [buildDebugBundle]);
  useRegisterDebugCapture(debugCaptureRef, buildDebugBundle);

  // M5 — route grouping (client-side, mirrors parent app src/screens/MapScreen.jsx).
  // Group positioned stops by loadNbr (sequence restarts per load, so one
  // polyline per load keeps order correct). Color by DRIVER so a driver's
  // multiple loads share a color (brief P3.1). Legend aggregates per driver.
  const routeData = useMemo(() => {
    if (!showRoutes) return { byLoad: [], legend: [] };
    const positioned = stops
      .map((s) => { const ov = notes.get(s.matchKey)?.location_override; return (ov && typeof ov.lat === 'number' && typeof ov.lng === 'number') ? { ...s, lat: ov.lat, lng: ov.lng } : s; })
      .filter((s) => s.lat != null && s.lng != null && s.loadNbr && s.driverUserName);
    const loadGroups = new Map();
    for (const s of positioned) {
      if (!loadGroups.has(s.loadNbr)) {
        loadGroups.set(s.loadNbr, {
          loadNbr: s.loadNbr,
          driverUserName: s.driverUserName,
          driverName: s.driverName || s.driverUserName,
          stops: [],
        });
      }
      loadGroups.get(s.loadNbr).stops.push(s);
    }
    const byLoad = [];
    const driverAgg = new Map();
    // Stable, evenly-spread color per driver: sort distinct drivers, assign each
    // a golden-angle hue by index so no two routes share a color (until there are
    // a huge number) and adjacent drivers look clearly different.
    const driverList = [...new Set([...loadGroups.values()].map((g) => g.driverUserName))]
      .sort((a, b) => String(a).localeCompare(String(b)));
    const colorByDriver = new Map(driverList.map((d, i) => [d, routeColorByIndex(i)]));
    for (const g of loadGroups.values()) {
      const ordered = orderRouteStops(g.stops);
      const color = colorByDriver.get(g.driverUserName);
      if (ordered.length >= 2) {
        byLoad.push({ loadNbr: g.loadNbr, driverUserName: g.driverUserName, color, path: ordered });
      }
      const agg = driverAgg.get(g.driverUserName)
        || { driverUserName: g.driverUserName, driverName: g.driverName, color, stopCount: 0 };
      agg.stopCount += g.stops.length;
      driverAgg.set(g.driverUserName, agg);
    }
    const legend = [...driverAgg.values()].sort((a, b) => a.driverUserName.localeCompare(b.driverUserName));
    return { byLoad, legend };
  }, [showRoutes, stops, notes]);

  // M5.2 — the stops on the currently-opened route, kept separate from routeData
  // (which depends on showRoutes). The route detail must render even when the
  // polyline layer is hidden, so derive directly from `stops`.
  const selectedRouteStops = useMemo(() => {
    if (!selectedRoute) return [];
    return stops.filter((s) => s.loadNbr === selectedRoute);
  }, [stops, selectedRoute]);

  // The day's loads, grouped from the board by loadNbr — powers the mobile Loads
  // tab. Delivered count is tolerant of status casing; skids/loose/weight are summed.
  // NuVizz mislabels freight: cartons = real skids, volume = loose pieces,
  // pallets (totalPallets) = total pieces.
  const loads = useMemo(() => {
    const m = new Map();
    for (const s of stops) {
      if (!s.loadNbr) continue;
      let g = m.get(s.loadNbr);
      if (!g) { g = { loadNbr: s.loadNbr, routeName: s.routeName || null, driverName: s.driverName || null, stops: 0, delivered: 0, skids: 0, loose: 0, weight: 0 }; m.set(s.loadNbr, g); }
      g.stops++;
      if (classifyStopStatus(s) === 'DELIVERED') g.delivered++;   // shared classifier — the regex missed code-only '90' rows
      g.skids += Number(s.cartons) || 0;
      g.loose += Number(s.volume) || 0;
      g.weight += Number(s.weight) || 0;
      if (!g.driverName && s.driverName) g.driverName = s.driverName;
      if (!g.routeName && s.routeName) g.routeName = s.routeName;
    }
    return [...m.values()].sort((a, b) => String(a.routeName || a.loadNbr).localeCompare(String(b.routeName || b.loadNbr)));
  }, [stops]);

  // Init map once google + container are ready.
  useEffect(() => {
    if (!google || !mapDiv.current || mapRef.current) return;
    mapRef.current = new google.maps.Map(mapDiv.current, {
      center: BUFORD,
      zoom: 10,
      // Exactly the vector-map control set the dispatcher asked for: the rotate
      // compass + 2D/3D tilt (rotateControl on a vector mapId), zoom, the Street
      // View pegman, and a custom Recenter crosshair (added below). Map-type +
      // fullscreen are dropped (the Filters panel has the Satellite toggle).
      ...(MAP_ID ? { mapId: MAP_ID } : {}),
      mapTypeControl: false,
      streetViewControl: true,
      streetViewControlOptions: { position: google.maps.ControlPosition.RIGHT_BOTTOM },
      fullscreenControl: false,
      zoomControl: true,
      zoomControlOptions: { position: google.maps.ControlPosition.RIGHT_BOTTOM },
      rotateControl: true,
      rotateControlOptions: { position: google.maps.ControlPosition.RIGHT_BOTTOM },
      scaleControl: false,
      keyboardShortcuts: false,
      tiltInteractionEnabled: true,
      headingInteractionEnabled: true,
      gestureHandling: 'greedy',
    });
    labelOverlayClassRef.current = makeDriverLabelOverlayClass(google);
    // Custom "Recenter on stops" control (the crosshair). A ref holds the latest
    // fit function so the once-created button always recenters the current board.
    const recenterBtn = document.createElement('button');
    recenterBtn.type = 'button';
    recenterBtn.title = 'Recenter on stops';
    recenterBtn.setAttribute('aria-label', 'Recenter on stops');
    recenterBtn.style.cssText = 'background:#fff;border:none;border-radius:2px;box-shadow:0 1px 4px rgba(0,0,0,0.3);width:40px;height:40px;margin:0 10px 10px 0;cursor:pointer;display:flex;align-items:center;justify-content:center;';
    recenterBtn.innerHTML = '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#5f6368" stroke-width="2"><circle cx="12" cy="12" r="6"/><line x1="12" y1="1" x2="12" y2="5"/><line x1="12" y1="19" x2="12" y2="23"/><line x1="1" y1="12" x2="5" y2="12"/><line x1="19" y1="12" x2="23" y2="12"/><circle cx="12" cy="12" r="1.5" fill="#5f6368" stroke="none"/></svg>';
    recenterBtn.addEventListener('click', () => recenterRef.current && recenterRef.current());
    mapRef.current.controls[google.maps.ControlPosition.RIGHT_BOTTOM].push(recenterBtn);
    // Box/lasso projection: an invisible OverlayView exposes the live
    // pixel<->LatLng projection. Created HERE (not a separate [google] effect)
    // so it runs AFTER mapRef is set — otherwise it no-ops and selection breaks.
    const projOv = new google.maps.OverlayView();
    projOv.onAdd = projOv.draw = projOv.onRemove = () => {};
    projOv.setMap(mapRef.current);
    selectionOverlayRef.current = projOv;
  }, [google]);

  // The bottom data grid is an ABSOLUTE OVERLAY inside the map container, so Google's canvas
  // extends UNDERNEATH it — a flat 60px fitBounds pad framed a route's southern stops behind
  // the grid (BUFORD Jul 13: deliveries 4–7 hidden; the idle re-fit can't help because the
  // canvas size never changes). Every fit pads the bottom by the grid's LIVE rendered height
  // (open/resized/collapsed alike), measured at call time through a ref on the grid's root.
  const bottomGridRef = useRef(null);
  const fitPad = useCallback(() => ({ top: 60, right: 60, left: 60, bottom: 60 + (bottomGridRef.current?.offsetHeight || 0) }), []);

  // Keep the Recenter button's action pointed at the current board: fit to all
  // currently-shown stops (or fall back to the default center when none).
  useEffect(() => {
    recenterRef.current = () => {
      if (!google || !mapRef.current) return;
      const pts = filteredStops.filter((s) => s.lat != null && s.lng != null);
      if (!pts.length) { mapRef.current.panTo(BUFORD); mapRef.current.setZoom(10); return; }
      const b = new google.maps.LatLngBounds();
      pts.forEach((s) => b.extend({ lat: s.lat, lng: s.lng }));
      mapRef.current.fitBounds(b, fitPad());
    };
  }, [google, filteredStops, fitPad]);

  // M4.4 — satellite/roadmap toggle. 'hybrid' = satellite imagery + road labels,
  // which is most useful for spotting docks/yards while keeping street names.
  // "Hide map labels": on the vector mapId map, JS styles are ignored — so the
  // mapId-safe lever is the TYPE (satellite has no labels, hybrid does). When there's
  // no mapId, also apply a POI/transit label-off style so the roadmap base honors it.
  useEffect(() => {
    if (!google || !mapRef.current) return;
    const type = mapFilters.satellite ? (mapFilters.hideLabels ? 'satellite' : 'hybrid') : 'roadmap';
    try { mapRef.current.setMapTypeId(type); } catch { /* ignore */ }
    if (!MAP_ID) {
      try {
        mapRef.current.setOptions({ styles: mapFilters.hideLabels
          ? [{ featureType: 'poi', elementType: 'labels', stylers: [{ visibility: 'off' }] },
             { featureType: 'transit', elementType: 'labels', stylers: [{ visibility: 'off' }] }]
          : [] });
      } catch { /* ignore */ }
    }
  }, [google, mapFilters.satellite, mapFilters.hideLabels]);

  // Tell Google Maps to redraw as soon as the panel width changes — otherwise
  // the map tiles leave a gap until the next interaction.
  useEffect(() => {
    if (!google || !mapRef.current) return;
    google.maps.event.trigger(mapRef.current, 'resize');
  }, [google, panel.width]);

  // M4.1: render stop markers with full set + search opacity. We render ALL
  // filteredStops as markers but dim non-matches when a search is active so
  // the dispatcher keeps spatial context. Faded pins still cluster — at
  // zoomed-out levels cluster counts include all in view; at zoom-in the
  // 30%-opacity pins are obviously deprioritized.
  useEffect(() => {
    if (!google || !mapRef.current) return;

    if (clustererRef.current) clustererRef.current.clearMarkers();
    markersRef.current.forEach((m) => m.setMap(null));
    markersRef.current = [];
    // Drop any receiving-hours hover tooltip left over from the prior render.
    if (hoverTipRef.current) { hoverTipRef.current.tip.setMap(null); hoverTipRef.current = null; }
    // Reusable overlay class for the desktop hover tooltip (same styling as driver labels).
    const HoverTip = makeDriverLabelOverlayClass(google);

    // Day-aware receiving-hours clock: only light the clock on the weekday the
    // map is showing. A Friday-only customer's clock appears on Fridays only.
    const selectedDayKey = weekdayKeyFromDate(selectedDate);
    let positioned = filteredStops.filter((s) => s.lat != null && s.lng != null);
    // When you're VIEWING A ROUTE, always show that route's stops — even if the current
    // board filters (e.g. "unplanned only") would otherwise hide its planned stops. Add any
    // of the route's stops missing from the filtered set, applying the same location_override
    // filteredStops uses. Without this, opening a driver's load with a filter on framed an
    // empty map (the pins were all filtered out). Fixes desktop + mobile (shared effect).
    if (selectedRoute && selectedRouteStops.length) {
      const have = new Set(positioned.map((s) => s.stopNbr));
      const extra = selectedRouteStops
        .filter((s) => !have.has(s.stopNbr) && s.lat != null && s.lng != null)
        .map((s) => {
          const ov = notes.get(s.matchKey)?.location_override;
          return (ov && typeof ov.lat === 'number' && typeof ov.lng === 'number') ? { ...s, lat: ov.lat, lng: ov.lng } : s;
        });
      if (extra.length) positioned = positioned.concat(extra);
    }
    // When a route is open, number its stops in delivery sequence (planned-ETA
    // order = NuVizz's optimized order) and render numbered pins; dim the rest.
    const routeSeqByStop = new Map();
    if (selectedRoute && selectedRouteStops.length) {
      // Number by NuVizz's own sequence value (routeSeq) so the pins read exactly
      // like the Route Workbench — co-located orders share a number, and the order
      // is correct even before a route starts. Fall back to dense position for any
      // stop missing routeSeq (old cached doc). PICKUPS pin as "P", never a number:
      // their Display-Seq is the terminal return's slot, so two pickups drew two
      // pins wearing the same number (RASHEED's twin 16s).
      orderRouteStops(selectedRouteStops).forEach((s, i) => {
        const { seq: rs, pickup } = routeStopSeq(s);
        routeSeqByStop.set(s.stopNbr, pickup ? 'P' : rs != null ? rs : i + 1);
      });
    }
    const locCounts = buildLocCounts(positioned);   // co-located delivery tally for the badge
    const newMarkers = positioned.map((s) => {
      const note = notes.get(s.matchKey);
      const seq = routeSeqByStop.get(s.stopNbr);
      const inRoute = seq != null;
      const matched = effectiveMatchSet && effectiveMatchSet.has(s.stopNbr);
      const dim = (effectiveMatchSet && !matched) || (!!selectedRoute && !inRoute);
      // The rich per-stop icon (DNS / numbered route / status-flag-window /
      // restriction) is built by the shared stopMarkerIcon helper so the Map and
      // Routing screens stay pixel-identical.
      const icon = stopMarkerIcon(google, s, note, { selectedDayKey, matched, inRoute, seq, sameLocCount: locCounts.get(stopLocKey(s)) || 1, tractorDelivered: tractorLocs.has(s.matchKey) });
      // The native Marker `title` still carries the business name (OS hover fallback).
      const marker = new google.maps.Marker({
        position: { lat: s.lat, lng: s.lng },
        icon,
        title: s.businessName || '',
        opacity: dim ? 0.3 : 1,
        // Search-matched dots ride the TOP layer, above everything (Chad) — above even Google's
        // latitude-based auto stacking (≤ MAX_ZINDEX), so a northern hit never hides beneath a
        // southern non-match. Dimmed non-matches sink below the normal board.
        zIndex: matched ? ((google.maps.Marker?.MAX_ZINDEX ?? 1e6) + 1) : (dim ? 0 : undefined),
      });
      marker.addListener('click', () => {
        setSelectedDriver(null);
        setSelectedStop(s);
        handlePanToStop(s);   // match list/search behavior: recenter + zoom to STOP_ZOOM
      });
      // Desktop hover tooltip for the receiving-hours "clock" pins: pop up the
      // business name + the hours window immediately on hover, so hunting for a
      // time-restricted stop surfaces its window without clicking in. Only clock
      // pins get this — formatReceivingHours returns null when no hours are set,
      // so a plain pin never shows a (false) window. (#receiving-hours-hover)
      const hoursStr = formatReceivingHours(note);
      if (hoursStr) {
        marker.addListener('mouseover', () => {
          if (hoverTipRef.current) hoverTipRef.current.tip.setMap(null);
          const tip = new HoverTip(new google.maps.LatLng(s.lat, s.lng), s.businessName || 'Stop', `Receiving hours: ${hoursStr}`);
          tip.setMap(mapRef.current);
          hoverTipRef.current = { marker, tip };
        });
        marker.addListener('mouseout', () => {
          // Only clear if THIS marker's tip is the one showing (co-located pins can
          // fire mouseover-next before mouseout-prev; don't yank the new tooltip).
          if (hoverTipRef.current && hoverTipRef.current.marker === marker) {
            hoverTipRef.current.tip.setMap(null);
            hoverTipRef.current = null;
          }
        });
      }
      return marker;
    });

    markersRef.current = newMarkers;
    // M4.4 — when clustering is disabled, attach markers directly to the map
    // instead of routing through MarkerClusterer. Skipping clustering on 600+
    // pins is intentionally slow at zoom-out; the toolbar surfaces a warning.
    if (mapFilters.showClustered) {
      // Reuse ONE clusterer across rebuilds (clear at the top of the effect, then re-add)
      // instead of constructing a fresh MarkerClusterer every time stops/notes/tractors/
      // filters change — a new instance re-runs the whole clustering pass and orphans the old.
      if (!clustererRef.current) {
        clustererRef.current = new MarkerClusterer({ map: mapRef.current, markers: newMarkers });
      } else {
        clustererRef.current.addMarkers(newMarkers);
      }
    } else {
      newMarkers.forEach((m) => m.setMap(mapRef.current));
    }
  }, [google, filteredStops, notes, tractorLocs, effectiveMatchSet, mapFilters.showClustered, selectedDate, selectedRoute, selectedRouteStops]);

  // Center/zoom the map to fit a route's stops when it's opened (per dispatcher
  // request — NuVizz frames the route on open). Restores the prior board view on close.
  //
  // Fit SYNCHRONOUSLY. This effect is a passive effect, so it runs after React has
  // committed the DOM (the 380px RouteDetailSidebar is mounted and laid out) and after
  // the browser + Google's ResizeObserver have re-measured the now-narrower map — so a
  // plain fitBounds here frames the true visible area with every stop in view, however
  // far the route spreads. (Do NOT defer this into a requestAnimationFrame: rAF is
  // paused on hidden/background tabs and its cleanup cancels the pending frame every
  // time this effect re-runs on the 120s board refresh, so the deferred fit frequently
  // never applied and the map appeared not to zoom. The recenter and search fits are
  // synchronous for the same reason.)
  // One shared "board view" (center+zoom) saved before the FIRST zoom-in of a
  // selection — a stop building-zoom or a route frame — so clearing the whole
  // selection restores it. saveBoardView no-ops if a view is already banked.
  const boardViewRef = useRef(null);
  const saveBoardView = () => {
    if (boardViewRef.current || !mapRef.current) return;
    const c = mapRef.current.getCenter();
    if (c) boardViewRef.current = { center: c.toJSON(), zoom: mapRef.current.getZoom() || 10 };
  };

  // Imperatively frame a WHOLE route (#380: "opened a route → frame the route").
  // Called ONLY by the explicit "see this route" actions (View full route, the
  // Routes roster, a load row) — never by an order pull-up, which shows the route
  // PANEL for context but keeps the building zoom. Re-fits once after the side
  // panels settle: Google re-measures the canvas asynchronously, so a lone
  // synchronous fit frames against the still-wide map and clips the far stops
  // behind a panel. addListenerOnce → one corrective fit, no loop; not rAF
  // (paused on background tabs).
  const frameRoute = (loadNbr) => {
    if (!google || !mapRef.current || !loadNbr) return;
    const map = mapRef.current;
    // Apply location_override like the markers do — framing on the raw geocode zoomed the
    // map out to span a corrected pin's OLD wrong city (the "thrown across the state" look).
    const pts = stops
      .filter((s) => s.loadNbr === loadNbr)
      .map((s) => { const ov = notes.get(s.matchKey)?.location_override; return (ov && typeof ov.lat === 'number' && typeof ov.lng === 'number') ? { ...s, lat: ov.lat, lng: ov.lng } : s; })
      .filter((s) => s.lat != null && s.lng != null);
    if (!pts.length) return;
    saveBoardView();
    const b = new google.maps.LatLngBounds();
    pts.forEach((s) => b.extend({ lat: s.lat, lng: s.lng }));
    // fitPad() re-measured on each fit: the corrective idle fit sees the grid's settled size.
    const fit = () => map.fitBounds(b, fitPad());
    fit();
    google.maps.event.addListenerOnce(map, 'idle', fit);
  };

  // Open a route as the EXPLICIT focus (roster / load row / the order card's "View
  // full route"): show its panel AND frame it on the map. Clearing routeAutoRef
  // marks it as NOT following an order, so it persists when the order card closes.
  const routeAutoRef = useRef(null);
  const openRouteExplicit = (loadNbr) => {
    routeAutoRef.current = null;
    setSelectedDriver(null);
    setSelectedRoute(loadNbr);
    frameRoute(loadNbr);
  };

  // #388 — pulling up an ORDER auto-opens ITS route in the right panel for context
  // (order ↔ route side by side). Panel only: the map stays at the building zoom
  // from the stop selection (#380). Picking an order on a different load switches
  // the auto route; an EXPLICITLY opened route is left alone. routeAutoRef marks a
  // route that follows the order, so closing the order also closes that route.
  useEffect(() => {
    if (isMobile) return;   // mobile shows one bottom-sheet at a time — no side-by-side
    if (selectedStop) {
      const load = selectedStop.loadNbr && !isHashLikeId(selectedStop.loadNbr) ? selectedStop.loadNbr : null;
      if (!selectedRoute || routeAutoRef.current != null) {
        routeAutoRef.current = load;
        setSelectedRoute(load);
      }
    } else if (routeAutoRef.current != null) {
      routeAutoRef.current = null;   // order closed → close the route it auto-opened
      setSelectedRoute(null);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedStop]);

  // Restore the board view once EVERYTHING is deselected (no order, route, or
  // driver). While any is open the current zoom belongs to that selection.
  useEffect(() => {
    if (selectedStop || selectedRoute || selectedDriver) return;
    const v = boardViewRef.current;
    boardViewRef.current = null;
    if (v && mapRef.current) { mapRef.current.panTo(v.center); mapRef.current.setZoom(v.zoom); }
  }, [selectedStop, selectedRoute, selectedDriver]);

  // M5 — route polylines. One straight-line Polyline per load, ordered by
  // loadStopSeq, colored by driver. zIndex 1 keeps them below markers so pins
  // stay clickable. Google redraws on pan/zoom itself — we only rebuild when
  // routeData changes (toggle, refresh, or selectedDate change all flow through
  // routeData via the stops dependency).
  useEffect(() => {
    if (!google || !mapRef.current) return;
    routePolylinesRef.current.forEach((p) => p.setMap(null));
    routePolylinesRef.current = [];
    if (!showRoutes) return;
    for (const route of routeData.byLoad) {
      const path = route.path
        .filter((s) => s.lat != null && s.lng != null)
        .map((s) => ({ lat: s.lat, lng: s.lng }));
      if (path.length < 2) continue;
      // M5.2 — highlight the open route (thicker, on top, full opacity); when ANY
      // route is open, dim the rest so the dispatcher's eye locks onto the path
      // they're inspecting. No selection → all routes render at normal weight.
      const isSelected = selectedRoute && route.loadNbr === selectedRoute;
      const anySelected = !!selectedRoute;
      const poly = new google.maps.Polyline({
        path,
        strokeColor: route.color,
        strokeOpacity: isSelected ? 1 : (anySelected ? 0.25 : 0.7),
        strokeWeight: isSelected ? 6 : 3,
        geodesic: false,
        zIndex: isSelected ? 3 : 1,
        map: mapRef.current,
        clickable: false,   // the hit line below owns the pointer; see why
      });
      routePolylinesRef.current.push(poly);
      // CLICK THE LINE TO OPEN THE ROUTE (Chad). A 3px stroke is a miserable click target —
      // Google's hit test is the drawn width, so at 3px you are aiming at 3 pixels on a
      // diagonal, and the dimmed 0.25-opacity lines are effectively invisible to aim at.
      // So the pointer lives on a SEPARATE fully transparent 16px line following the same
      // path: easy to hit, draws nothing. The visible line is clickable:false so the two can
      // never both answer a click.
      //
      // It cannot steal clicks from pins: Google renders markers in a higher pane than
      // polylines regardless of zIndex, so a stop under the line still wins the click. Same
      // reason the existing zIndex-1 lines never blocked pins.
      const hit = new google.maps.Polyline({
        path,
        strokeColor: route.color,
        strokeOpacity: 0,
        strokeWeight: 16,
        geodesic: false,
        clickable: true,
        zIndex: isSelected ? 3 : 1,
        map: mapRef.current,
      });
      hit.addListener('click', () => { setSelectedStop(null); openRouteExplicit(route.loadNbr); });
      // Hover feedback so the line reads as clickable — pointer cursor + the visible stroke
      // thickens. Skipped for the already-open route, which is drawn heavy already.
      hit.addListener('mouseover', () => {
        mapRef.current?.setOptions({ draggableCursor: 'pointer' });
        if (!isSelected) poly.setOptions({ strokeWeight: 5, strokeOpacity: anySelected ? 0.6 : 0.95 });
      });
      hit.addListener('mouseout', () => {
        mapRef.current?.setOptions({ draggableCursor: null });
        if (!isSelected) poly.setOptions({ strokeWeight: 3, strokeOpacity: anySelected ? 0.25 : 0.7 });
      });
      routePolylinesRef.current.push(hit);
    }
    // Leave no cursor override behind when the overlay is torn down mid-hover.
    return () => { mapRef.current?.setOptions({ draggableCursor: null }); };
  }, [google, showRoutes, routeData, selectedRoute]);   // eslint-disable-line react-hooks/exhaustive-deps

  // Auto-zoom on search results: 1 match → center + open sidebar, 2-10 → fit bounds.
  const pendingSearchFitRef = useRef(false);   // search settled before the board had rows — fit once when they land
  useEffect(() => {
    if (!google || !mapRef.current) return;
    if (!effectiveMatchSet) return;
    const matched = filteredStops.filter((s) => effectiveMatchSet.has(s.stopNbr) && s.lat != null && s.lng != null);
    pendingSearchFitRef.current = matched.length === 0;
    if (matched.length === 1) {
      const s = matched[0];
      // Don't auto-open if user already navigated away from search results.
      if (!selectedDriver) { setSelectedStop(s); handlePanToStop(s); }   // saves board view → closing zooms back out
      else { mapRef.current.panTo({ lat: s.lat, lng: s.lng }); mapRef.current.setZoom(Math.max(mapRef.current.getZoom() || 10, STOP_ZOOM)); }
    } else if (matched.length >= 2 && matched.length <= 10) {
      const bounds = new google.maps.LatLngBounds();
      matched.forEach((s) => bounds.extend({ lat: s.lat, lng: s.lng }));
      mapRef.current.fitBounds(bounds, fitPad());
    }
    // Re-fit ONLY when the SEARCH ITSELF changes — NOT on every 120s board refresh.
    // effectiveMatchSet is a brand-new Set after each refresh (searchMatchSet re-memoizes
    // on the new stops), so keying the effect on it re-ran this fit every refresh and
    // drifted the map out to frame far-apart matches while the dispatcher sat idle
    // (e.g. "floor" spanning Dalton→Conyers→Marietta). Keying on the stable search
    // inputs fixes that; filteredStops is read live from the closure.
  }, [google, debouncedSearch, aiResult, selectionSet]);  // eslint-disable-line react-hooks/exhaustive-deps
  // One-shot deferred fit: typing during a cold load / date flip used to find zero rows and
  // never re-fit (the effect above deliberately doesn't key on the board). Runs at most once
  // per pending search, then disarms — the 120s-refresh drift fix stays intact.
  useEffect(() => {
    if (!pendingSearchFitRef.current || !google || !mapRef.current || !effectiveMatchSet) return;
    const matched = filteredStops.filter((s) => effectiveMatchSet.has(s.stopNbr) && s.lat != null && s.lng != null);
    if (!matched.length) return;
    pendingSearchFitRef.current = false;
    if (matched.length === 1) {
      const s = matched[0];
      if (!selectedDriver) { setSelectedStop(s); handlePanToStop(s); }
      else { mapRef.current.panTo({ lat: s.lat, lng: s.lng }); mapRef.current.setZoom(Math.max(mapRef.current.getZoom() || 10, STOP_ZOOM)); }
    } else if (matched.length <= 10) {
      const bounds = new google.maps.LatLngBounds();
      matched.forEach((s) => bounds.extend({ lat: s.lat, lng: s.lng }));
      mapRef.current.fitBounds(bounds, fitPad());
    }
  }, [filteredStops]);  // eslint-disable-line react-hooks/exhaustive-deps

  // Build the driver-status line2 text. Route assignment is managed in NuVizz,
  // not Motive, so we do NOT show a "No route assigned" line on the Motive driver
  // tag — only movement status (en route / stopped / stale). If Motive ever does
  // carry route progress we surface it, but its absence is not reported.
  const driverStatusLine = useCallback((d) => {
    let base = '';
    if (d.routeAssigned && d.routeProgress) {
      base = `Stop ${d.routeProgress.completed} of ${d.routeProgress.total}`;
    } else if (d.routeAssigned && d.routeId) {
      base = `Route ${d.routeId} · ${d.routeTotalStops ?? '?'} stops`;
    }
    const suffix = [];
    if (d.speedMph != null && d.speedMph > 5) suffix.push('en route');
    else if (d.speedMph != null && d.speedMph <= 5 && d.stoppedMinutes != null && d.stoppedMinutes > 5) suffix.push('stopped');
    if (d.locatedAt) {
      const ageMin = (Date.now() - new Date(d.locatedAt).getTime()) / 60000;
      if (ageMin > 30) suffix.push('stale');
    }
    return [base, ...suffix].filter(Boolean).join(' · ');
  }, []);

  // M4: driver markers + M4.1 labels — separate layer, larger truck icon.
  useEffect(() => {
    if (!google || !mapRef.current) return;
    driverMarkersRef.current.forEach((m) => m.setMap(null));
    driverMarkersRef.current = [];
    driverLabelsRef.current.forEach((l) => l.setMap(null));
    driverLabelsRef.current = [];
    if (!showDrivers) return;

    const positioned = drivers.filter((d) => d.lat != null && d.lng != null);

    driverMarkersRef.current = positioned.map((d) => {
      const ageMin = d.locatedAt ? (Date.now() - new Date(d.locatedAt).getTime()) / 60000 : 0;
      const stale = ageMin > 30;
      const marker = new google.maps.Marker({
        position: { lat: d.lat, lng: d.lng },
        map: mapRef.current,
        icon: {
          url: truckSvg(DRIVER_TINT),
          scaledSize: new google.maps.Size(DRIVER_MARKER_PX, DRIVER_MARKER_PX),
          anchor: new google.maps.Point(DRIVER_MARKER_PX / 2, DRIVER_MARKER_PX / 2),
        },
        title: `${d.driverName || 'Driver'} · ${d.vehicleNumber || ''}`,
        opacity: stale ? 0.55 : 1,
        zIndex: 1000,
      });
      marker.addListener('click', () => {
        setSelectedStop(null);
        setSelectedDriver(d);
      });
      return marker;
    });

    if (showDriverLabels && labelOverlayClassRef.current) {
      const Klass = labelOverlayClassRef.current;
      driverLabelsRef.current = positioned.map((d) => {
        const ageMin = d.locatedAt ? (Date.now() - new Date(d.locatedAt).getTime()) / 60000 : 0;
        const stale = ageMin > 30;
        const first = d.driverFirstName || (d.driverName ? d.driverName.split(/\s+/)[0] : null);
        const lastInit = d.driverLastInitial || (d.driverName ? (d.driverName.split(/\s+/).slice(-1)[0]?.[0] || '') : '');
        const driverPart = d.driverName ? `${first}${lastInit ? ' ' + lastInit + '.' : ''}` : '(no driver)';
        const line1 = `${d.vehicleNumber || '?'} · ${driverPart}`;
        const line2 = driverStatusLine(d);
        const overlay = new Klass(
          new google.maps.LatLng(d.lat, d.lng),
          line1,
          line2,
          { stale },
        );
        overlay.setMap(mapRef.current);
        return overlay;
      });
    }
  }, [google, drivers, showDrivers, showDriverLabels, driverStatusLine]);

  // Keyboard shortcuts: `/` focuses search; Escape clears + blurs (handled in input).
  useEffect(() => {
    const onKey = (e) => {
      // Don't hijack `/` if user is already typing in any input/textarea.
      if (e.key === '/' && !['INPUT', 'TEXTAREA'].includes(e.target.tagName)) {
        e.preventDefault();
        searchInputRef.current?.focus();
      }
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, []);

  // Trigger map resize once after mount so the initial fit isn't clipped.
  useEffect(() => {
    if (!google || !mapRef.current) return;
    const id = setTimeout(() => google.maps.event.trigger(mapRef.current, 'resize'), 50);
    return () => clearTimeout(id);
  }, [google]);

  const handleSave = async (draft) => {
    if (!db || !selectedStop) return;
    setSaving(true);
    setSaveError(null);
    try {
      const key = selectedStop.matchKey;
      const existing = notes.get(key);
      const pro = selectedStop.pro;
      const proHistory = pro ? bumpProHistory(existing?.pro_history, pro) : (existing?.pro_history || []);
      const payload = {
        ...draft,
        match_key: key,
        raw_name: draft.raw_name || selectedStop.businessName || '',
        raw_address: draft.raw_address || [selectedStop.addr1, selectedStop.city, selectedStop.state, selectedStop.zip].filter(Boolean).join(', '),
        pro_history: proHistory,
        last_updated: serverTimestamp(),
        updated_by: NOTES_UPDATED_BY,
      };
      await setDoc(doc(db, 'customer_notes', key), payload, { merge: true });
    } catch (e) {
      setSaveError(e.message);
    } finally {
      setSaving(false);
    }
  };

  // Pan + building-zoom to a stop (#380: individual stop → building). Banks the
  // board view first so clearing the whole selection zooms back out.
  const handlePanToStop = (stopFromSnapshot) => {
    if (!google || !mapRef.current) return;
    if (stopFromSnapshot.lat == null || stopFromSnapshot.lng == null) return;
    saveBoardView();
    mapRef.current.panTo({ lat: stopFromSnapshot.lat, lng: stopFromSnapshot.lng });
    mapRef.current.setZoom(Math.max(mapRef.current.getZoom() || 10, STOP_ZOOM));
  };

  // On mobile we drop the resize handle and let the panel be a top-edge sheet.
  // Stretch goal per brief — we ship the simple desktop-only resize and
  // collapse the panel by default on mobile; see HANDOFF.md.
  const panelStyle = isMobile
    ? { width: '100%', maxHeight: '40vh' }
    : { width: panel.width, minWidth: PANEL_MIN_WIDTH, maxWidth: panel.maxWidth };

  // Per brief width tiers (still used for the customer-name truncation cutoff):
  //   240-300px: compact (names truncate)
  //   300px+:    extended names
  // Column visibility itself is user-controlled via the Columns gear (persisted
  // to LS_TABLE_COLUMNS).
  const useExtendedNames = !isMobile && panel.width >= 300;

  // Mobile path: map fills the area, FAB + drawer surface the lists/filters,
  // and the existing stop/driver sidebars switch to absolute full-screen
  // overlay mode. PR 2 of M4.5 will swap those overlays for proper drawers.
  if (isMobile) {
    const pickStopFromMobile = (s) => {
      setSelectedDriver(null);
      setSelectedStop(s);
      setMobileDrawerOpen(false);
      handlePanToStop(s);   // saves the board view so closing zooms back out
    };
    const pickDriverFromMobile = (d) => {
      setSelectedStop(null);
      setSelectedDriver(d);
      setMobileDrawerOpen(false);
      if (google && mapRef.current && d.lat != null && d.lng != null) {
        mapRef.current.panTo({ lat: d.lat, lng: d.lng });
        mapRef.current.setZoom(Math.max(mapRef.current.getZoom() || 10, 13));
      }
    };
    // Tap a load → open its route detail (reuses the route drawer) and close the sheet.
    const pickLoadFromMobile = (loadNbr) => {
      setSelectedStop(null);
      setSelectedDriver(null);
      setMobileDrawerOpen(false);
      setRouteMapView(false);   // always open on the stop LIST; "View on map" minimizes it
      setSelectedRoute(loadNbr);
      frameRoute(loadNbr);   // desktop frames via openRouteExplicit; mobile frames here
    };
    return (
      <div className="flex-1 flex flex-col min-h-0">
        {smsTargets && <SmsComposeModal title={smsTargets.title} recipients={smsTargets.recipients} initialText={smsTargets.initialText} onClose={() => setSmsTargets(null)} />}
        <div className="flex-1 relative min-w-0 overflow-hidden">
        <div ref={mapDiv} className="absolute inset-0" />
        {/* Box/lasso multi-select: capture overlay (while a tool is armed) + the
            tool controls (kept above the overlay so you can switch/cancel). */}
        {selectMode && (
          <SelectionOverlay
            mode={selectMode}
            onBox={(a, b) => { selectByBox(a, b); setSelectMode(null); }}
            onLasso={(pts) => { selectByLasso(pts); setSelectMode(null); }}
          />
        )}
        {/* Persistent search bar (#382 — "there should be a search bar here").
            Fixed, single-line height (no "Showing N of M" subtext / AI-summary chip
            like the desktop SearchBar — those grow the box and would collide with
            the date/status row below) so every other top overlay can sit at a FIXED
            offset beneath it without a runtime height measurement. Shares the same
            searchInput/aiMode state as desktop, so results/auto-zoom behave
            identically; "Recent searches" renders as an absolutely-positioned
            dropdown (doesn't push this row's height). */}
        <div className="absolute top-2 left-2 right-2 z-[17]">
          <MobileMapSearchBar
            value={searchInput}
            onChange={setSearchInput}
            onSubmit={(v) => { if (v.trim()) remember(v.trim()); }}
            history={history}
            aiAvailable={aiAvailable}
            aiMode={aiMode}
            setAiMode={(v) => { setAiMode(v); if (!v) clearAi(); }}
            onAskAi={runAiSearch}
            aiBusy={aiBusy}
          />
        </div>
        <div className="absolute top-28 left-2 z-[16] flex flex-col items-start gap-1">
          <SelectionControls mode={selectMode} setMode={setSelectMode} count={selectionSet?.size || 0} onClear={clearSelection} onText={textSelected} onTextDrivers={textSelectedDrivers} />
          {selectNote && <div className="text-[10px] bg-white/95 border border-slate-200 rounded px-1.5 py-0.5 shadow text-slate-700">{selectNote}</div>}
        </div>
        {/* Top overlay row: date chip (left) + status pill (right) share one
            flex row anchored left-2/right-2, so on a narrow phone they lay out
            side-by-side and can NEVER overlap (the old separate top-2 left/right
            absolutes collided in the middle). The wrapper passes map gestures
            through the gap (pointer-events-none) while each control stays tappable. */}
        <div className="absolute top-14 left-2 right-2 z-10 flex items-start justify-between gap-2 pointer-events-none">
          {/* date chip (P2.7): core control, visible without opening the drawer. */}
          <div className="flex items-center gap-1 bg-white/95 backdrop-blur border border-slate-200 rounded-lg shadow px-1.5 py-1 pointer-events-auto flex-shrink-0">
            <input
              type="date"
              value={selectedDate}
              onChange={(e) => { if (e.target.value) setSelectedDate(e.target.value); }}
              className="text-[11px] border-0 p-0 focus:outline-none bg-transparent w-[124px]"
              aria-label="Select delivery date"
            />
            {!dateIsToday && (
              <button
                onClick={goToToday}
                className="text-[10px] font-semibold px-1.5 py-0.5 rounded border border-blue-300 text-blue-700 active:bg-blue-50"
                title="Today"
              >
                Today
              </button>
            )}
          </div>

          {/* Compact status pill — collapsible to just the stops count (shares
              statusCollapsed with desktop). min-w-0 lets it shrink before it can
              ever reach the date chip. */}
          <div className="bg-white/95 backdrop-blur border border-slate-200 rounded-lg shadow px-2.5 py-1.5 text-[11px] pointer-events-auto min-w-0 flex-shrink max-w-[60vw] overflow-hidden">
            {/* Header row — always visible: collapse toggle + stops, scan, filters. */}
            <div className="flex items-center gap-2">
              <button
                onClick={() => setStatusCollapsed((c) => !c)}
                className="flex items-center gap-1 font-semibold min-w-0"
                aria-expanded={!statusCollapsed}
                title={statusCollapsed ? 'Show details' : 'Collapse'}
              >
                {statusCollapsed ? <ChevronDown size={13} className="text-slate-400 flex-shrink-0" /> : <ChevronUp size={13} className="text-slate-400 flex-shrink-0" />}
                <span className="truncate">{stops.length} stops{carryoverCount > 0 ? <span className="text-amber-700 font-normal"> · {carryoverCount} c/o</span> : null}</span>
              </button>
              <button
                onClick={manualScan}
                disabled={scanning || scanCooldown}
                className="ml-auto p-1 rounded hover:bg-slate-100 active:bg-slate-200 disabled:opacity-50 flex-shrink-0 min-w-[34px] min-h-[34px] inline-flex items-center justify-center"
                aria-label="Scan now"
                title={scanCooldown ? 'Just scanned — try again shortly' : 'Refresh from NuVizz — planned/unplanned + completed + loads (~4 calls)'}
              >
                <RefreshCw size={14} className={scanning ? 'animate-spin' : ''} />
              </button>
              <span className="w-px self-stretch bg-slate-200 flex-shrink-0" aria-hidden />
              <button
                onClick={() => { setMobileDrawerTab('filters'); setMobileDrawerOpen(true); }}
                className="flex items-center gap-1 px-1.5 py-1 rounded hover:bg-slate-100 active:bg-slate-200 font-semibold text-slate-700 flex-shrink-0"
                aria-label="Open filters"
              >
                <Filter size={14} /> Filters
              </button>
            </div>
            {/* Stacked details — hidden when collapsed (mirrors desktop). */}
            {!statusCollapsed && (
              <div className="mt-0.5 leading-tight min-w-0 [&>div]:truncate">
                <div className="text-slate-600 text-[10px]">{totalPalletsCount.toLocaleString()} total pallets</div>
                <UnplannedScanCount count={scanUnplannedCount} visible={visibleUnplannedCount} className="text-slate-600 text-[10px]" />
                <FeedTimestamps loadAt={lastLoadScanAt} unplannedAt={lastUnplannedScanAt} isToday={dateIsToday} className="text-slate-500 text-[10px]" stacked />
                {ops && typeof ops.dayCount === 'number' && (
                  <>
                    <div className="text-slate-500 text-[10px]" title={`Today's NuVizz API calls (${ops.mode})${ops.byRoute && Object.keys(ops.byRoute).length ? ' · ' + Object.entries(ops.byRoute).map(([k, v]) => `${k}:${v}`).join(' ') : ''}`}>
                      NuVizz calls: {ops.dayCount.toLocaleString()}{ops.ceiling ? ` / ${ops.ceiling.toLocaleString()}` : ''} <span className="text-slate-400">({ops.mode}{ops.breaker ? ', halted' : ''})</span>
                    </div>
                    <HourlyCalls byHour={ops.byHour} className="text-slate-400 text-[10px] mt-0.5" />
                  </>
                )}
                {scanState?.halted && (
                  <div className="text-[10px] font-semibold text-red-700">
                    {scanState.reason === 'ceiling'
                      ? 'Daily scan limit reached — updates resume after midnight UTC'
                      : 'Scanning paused (kill switch) — board may be stale'}
                  </div>
                )}
                {scanErr && <div className="text-[10px] text-red-600">{scanErr}</div>}
              </div>
            )}
          </div>
        </div>
        {driverGateNote && (
          <div className="absolute top-28 left-1/2 -translate-x-1/2 z-20 bg-amber-50 border border-amber-300 rounded shadow px-2 py-1 text-[10px] text-amber-800">
            Live drivers only available for today.
          </div>
        )}
        {mapsError && (
          // Anchored to the BOTTOM of the map area — the top strip belongs to the date chip +
          // status pill, and a full-width banner up there laid OVER the pill (audit finding).
          // bottom-36 also clears the fetch-error banner that lives at bottom-24.
          <div className="absolute bottom-36 left-2 right-2 bg-red-50 border border-red-200 rounded p-2 text-xs text-red-800 z-10">
            <div className="font-semibold">Google Maps failed to load</div>
            <div className="mt-0.5">{mapsError}</div>
          </div>
        )}
        {!visibleStops.length && !loading && !mapsError && (
          <div className="absolute top-14 left-1/2 -translate-x-1/2 bg-white border border-slate-200 rounded shadow px-3 py-1.5 text-[11px] text-slate-600 z-10 max-w-[92vw] text-center">
            {debouncedSearch ? `No stops match "${debouncedSearch}"` : 'No stops match filters'}
            {searchHiddenByFilters > 0 && (
              <div className="mt-1 text-amber-800">
                {searchHiddenByFilters === 1 ? 'It IS on this board' : `${searchHiddenByFilters} matching stops ARE on this board`} — your filters are hiding {searchHiddenByFilters === 1 ? 'it' : 'them'}.
                <button onClick={clearAllStopFilters} className="ml-1 underline font-semibold hover:text-amber-900">Clear filters</button>
              </div>
            )}
          </div>
        )}

        {error && (
          <div className="absolute bottom-24 left-2 right-2 bg-red-50 border border-red-200 rounded px-2 py-1 text-[11px] text-red-700 z-10">
            ⚠ {error}
          </div>
        )}

        {/* (The floating APP_VERSION chip that sat above the FAB is gone — the app-bar's
            menu chip already shows the version, and two chips on a phone was clutter.) */}

        {/* Navigation is the persistent bottom tab bar (below the map area). */}

        {/* Floating launchers (mobile), bottom-left: texting (message bubble) +
            AI assistant ("?"). Hidden while a panel/overlay is open. */}
        {!chatOpen && !selectedStop && !selectedDriver && !selectedRoute && !mobileDrawerOpen && (
          <div className="absolute left-3 z-[39] flex flex-col gap-2" style={{ bottom: `calc(20px + env(safe-area-inset-bottom))` }}>
            {onOpenMessages && <MessagesLauncher onClick={onOpenMessages} unread={smsUnread} />}
            {aiAvailable && <ChatLauncher onClick={() => setChatOpen(true)} active={aiResult?.source === 'chat'} />}
          </div>
        )}
        <ChatPanel
          open={chatOpen}
          onClose={() => setChatOpen(false)}
          onSend={handleChatSend}
          onHighlight={handleChatHighlight}
          onClear={clearAi}
          highlightActive={aiResult?.source === 'chat'}
          stopCount={filteredStops.length}
          onDebugCapture={handleDebugCapture}
        />
        {movingStop && (
          <MoveLocationBar
            stop={movingStop}
            saving={savingLoc}
            onSave={saveStopLocation}
            onCancel={cancelMoveLocation}
            onReset={resetStopLocation}
          />
        )}
        {editAddrStop && (
          <AddressEditModal
            stop={editAddrStop}
            note={notes.get(editAddrStop.matchKey)}
            google={google}
            seed={editAddrSeed}
            onClose={() => { setEditAddrStop(null); setEditAddrSeed(null); }}
            onSaved={() => refresh({ silent: true })}
          />
        )}

        <MobileDrawer
          open={mobileDrawerOpen}
          onClose={() => setMobileDrawerOpen(false)}
          activeTab={mobileDrawerTab}
          setActiveTab={setMobileDrawerTab}
        >
          {mobileDrawerTab === 'stops' && (
            <MobileStopsTab
              stops={visibleStops}
              notes={notes}
              drivers={drivers}
              searchInput={searchInput}
              setSearchInput={setSearchInput}
              resultCount={visibleStops.length}
              totalCount={filteredStops.length}
              hiddenByFilters={searchHiddenByFilters}
              onClearFilters={clearAllStopFilters}
              completedPct={boardCompletion?.pct ?? null}
              onPickStop={pickStopFromMobile}
              aiAvailable={aiAvailable}
              onAskAi={runAiSearch}
              aiBusy={aiBusy}
              aiSummary={aiResult?.source === 'search' ? aiResult.summary : null}
              aiError={aiError}
              onClearAi={clearAi}
            />
          )}
          {mobileDrawerTab === 'filters' && (
            <MobileFiltersTab
              filters={filters}
              setFilters={setFilters}
              counts={{ visible: visibleStops.length, total: stops.length, pct: boardCompletion?.pct ?? null }}
              mapFilters={mapFilters}
              setMapFilters={setMapFilters}
              showRoutes={showRoutes}
              setShowRoutes={setShowRoutes}
              vehicleDisabled={!dateIsToday}
              boardDate={selectedDate}
            />
          )}
          {mobileDrawerTab === 'loads' && (
            <MobileLoadsTab
              loads={loads}
              onPickLoad={pickLoadFromMobile}
            />
          )}
        </MobileDrawer>

        {/* Customer-history overlay (mobile) — opened by a stop card's "History"
            button, seeded with the customer name so it shows their past PROs +
            who delivered each. Reuses the shared MapScreen histOpen/histSeed. */}
        {histOpen && (
          <div className="fixed inset-0 z-[1100] bg-white flex flex-col" style={{ paddingBottom: 'env(safe-area-inset-bottom)' }}>
            <PastProSearch
              notes={notes}
              initialQuery={histSeed}
              noApi={histNoApi}
              onPickCustomer={(s) => { setHistOpen(false); pickStopFromMobile(s); }}
              onClose={() => setHistOpen(false)}
            />
          </div>
        )}

        {/* Stop detail drawer — slides up over the map. Tabs Info / Notes /
            Hours / PROs. Editing on Notes or Hours pins a sticky Save bar. */}
        {!selectedDriver && selectedStop && (!selectedRoute || routeMapView) && (
          <MobileStopDetailDrawer
            stop={selectedStop}
            note={notes.get(selectedStop.matchKey)}
            drivers={notesDrivers}
            onText={textCustomer}
            onTextDriver={textDriverForStop}
            onOpenHistory={openCustomerHistory}
            onClose={() => setSelectedStop(null)}
            onMoveLocation={startMoveLocation}
            onEditAddress={openAddrEditor}
            onAutoFixAddress={autoFixAddress}
            onOpenRoute={(loadNbr) => { setSelectedStop(null); setRouteMapView(false); setSelectedRoute(loadNbr); frameRoute(loadNbr); }}
            onSave={async (draft) => {
              await handleSave(draft);
              // handleSave clears saveError on success; close the drawer if
              // there was no error this cycle. (saveError is checked on the
              // next render, so we read the post-save state via a setTimeout
              // tick — but simplest: leave the drawer open on save so the
              // user can confirm the green state, and rely on the X to dismiss.)
            }}
            saving={saving}
            saveError={saveError}
          />
        )}

        {/* M5.2 — route detail drawer (mobile). Same bottom-sheet pattern as the
            stop detail; opened from the stop detail's "View full route" button. */}
        {!selectedDriver && selectedRoute && !routeMapView && !selectedStop && (
          <MobileRouteDetailDrawer
            loadNbr={selectedRoute}
            stops={selectedRouteStops}
            onClose={() => { setSelectedRoute(null); setRouteMapView(false); }}
            onViewOnMap={() => { setRouteMapView(true); frameRoute(selectedRoute); }}
            onPickStop={(s) => {
              setSelectedRoute(null);
              setRouteMapView(false);
              setSelectedStop(s);
              handlePanToStop(s);   // saves the board view so closing zooms back out
            }}
          />
        )}
        {/* "View on map" minimizes the route sheet to this slim bar so the framed
            route (numbered pins) is visible; taps on a pin open the stop over it. */}
        {!selectedDriver && selectedRoute && routeMapView && !selectedStop && (
          <RouteMapViewBar
            routeName={selectedRouteStops.find((s) => s.routeName)?.routeName || selectedRoute}
            count={selectedRouteStops.length}
            onShowStops={() => setRouteMapView(false)}
            onClose={() => { setSelectedRoute(null); setRouteMapView(false); }}
          />
        )}

        {/* Driver snapshot drawer — slides up over the map. Tap a stop row in
            the snapshot to dismiss the drawer, pan the map, and open the stop
            detail drawer for that stop. */}
        {selectedDriver && (
          <MobileDriverSnapshotDrawer
            driver={selectedDriver}
            snapshot={snapshot}
            loading={snapshotLoading}
            error={snapshotError}
            onText={textDriver}
            onClose={() => setSelectedDriver(null)}
            onPickStopFromSnapshot={(snapshotStop) => {
              // Try to resolve the snapshot stop (which has its own row shape)
              // back to a live stop from today's map so we can open the full
              // stop detail drawer. Match on the primary PRO; fall back to any
              // PRO in the stop.pros array. If no match, just pan the map.
              const targetPros = new Set();
              if (snapshotStop.primaryPro) targetPros.add(snapshotStop.primaryPro);
              if (snapshotStop.pro) targetPros.add(snapshotStop.pro);
              if (Array.isArray(snapshotStop.pros)) {
                for (const p of snapshotStop.pros) targetPros.add(p);
              }
              const liveMatch = targetPros.size
                ? stops.find((s) => {
                    if (s.pro && targetPros.has(s.pro)) return true;
                    if (Array.isArray(s.pros)) {
                      for (const p of s.pros) if (targetPros.has(p)) return true;
                    }
                    return false;
                  })
                : null;
              setSelectedDriver(null);
              if (liveMatch) {
                setSelectedStop(liveMatch);
                handlePanToStop(liveMatch);   // saves the board view so closing zooms back out
              } else {
                handlePanToStop(snapshotStop);
              }
            }}
          />
        )}
        </div>
        <MobileTabBar
          active={mobileDrawerOpen ? mobileDrawerTab : selectedRoute ? 'loads' : selectedStop ? 'stops' : 'map'}
          onMap={() => { setMobileDrawerOpen(false); setSelectedStop(null); setSelectedRoute(null); setSelectedDriver(null); }}
          onStops={() => { setSelectedStop(null); setSelectedRoute(null); setSelectedDriver(null); setMobileDrawerTab('stops'); setMobileDrawerOpen(true); }}
          onFilters={() => { setSelectedStop(null); setSelectedRoute(null); setSelectedDriver(null); setMobileDrawerTab('filters'); setMobileDrawerOpen(true); }}
          onLoads={() => { setSelectedStop(null); setSelectedRoute(null); setSelectedDriver(null); setMobileDrawerTab('loads'); setMobileDrawerOpen(true); }}
        />
      </div>
    );
  }

  // Desktop / tablet (≥768px): existing layout unchanged.
  return (
    <div className="flex flex-1 overflow-hidden">
      {/* Historical PRO / customer-history lookup — overlay (desktop). Prefilled
          with whatever's typed in the live search so it searches immediately. */}
      {histOpen && (
        <div
          className="fixed inset-0 z-[1100] bg-slate-900/40 flex items-start justify-center p-4 sm:p-8"
          onMouseDown={(e) => { if (e.target === e.currentTarget) setHistOpen(false); }}
        >
          <div className="w-full max-w-lg max-h-[85vh] bg-white rounded-xl shadow-2xl flex flex-col overflow-hidden">
            <PastProSearch
              notes={notes}
              initialQuery={histSeed}
              noApi={histNoApi}
              onPickCustomer={(s) => { setHistOpen(false); setSelectedDriver(null); setSelectedStop(s); }}
              onClose={() => setHistOpen(false)}
            />
          </div>
        </div>
      )}
      {smsTargets && <SmsComposeModal title={smsTargets.title} recipients={smsTargets.recipients} initialText={smsTargets.initialText} onClose={() => setSmsTargets(null)} />}
      {/* LEFT column (#388) — the search box + "Search past PROs" button stay
          FIXED at the top; below them sits either the OPEN ORDER card (read an
          order on the left while its route opens on the right) or, when nothing is
          open, the filters + stop list. Closing the order (X) brings the list
          back; a selected driver keeps the list (its snapshot is on the right). */}
      <div className="flex-shrink-0 bg-white border-r flex flex-col overflow-hidden" style={panelStyle}>
        <div className="shrink-0 border-b border-slate-100">
        <SearchBar
          value={searchInput}
          onChange={setSearchInput}
          onSubmit={(v) => { if (v.trim()) remember(v.trim()); }}
          history={history}
          inputRef={searchInputRef}
          resultCount={visibleStops.length}
          totalCount={filteredStops.length}
          hiddenByFilters={searchHiddenByFilters}
          onClearFilters={clearAllStopFilters}
          aiAvailable={aiAvailable}
          aiMode={aiMode}
          setAiMode={(v) => { setAiMode(v); if (!v) clearAi(); }}
          onAskAi={runAiSearch}
          aiBusy={aiBusy}
          aiSummary={aiResult?.source === 'search' ? aiResult.summary : null}
          aiError={aiError}
          onClearAi={clearAi}
        />
        <div className="px-3 pt-2 pb-2">
          <button
            onClick={() => { setHistSeed(searchInput); setHistNoApi(false); setHistOpen(true); }}
            className="w-full inline-flex items-center justify-center gap-1.5 text-xs font-semibold text-slate-700 border border-slate-300 rounded-lg py-2 hover:bg-slate-50 active:bg-slate-100"
          >
            <Clock size={13} /> Search past PROs / customer history
          </button>
        </div>
        </div>
        {!selectedDriver && selectedStop ? (
          <StopSidebar
            embedded
            stop={selectedStop}
            note={notes.get(selectedStop.matchKey)}
            drivers={notesDrivers}
            onText={textCustomer}
            onTextDriver={textDriverForStop}
            onOpenHistory={openCustomerHistory}
            onClose={() => setSelectedStop(null)}
            onMoveLocation={startMoveLocation}
            onEditAddress={openAddrEditor}
            onAutoFixAddress={autoFixAddress}
            onSave={handleSave}
            saving={saving}
            saveError={saveError}
            onOpenRoute={(loadNbr) => { openRouteExplicit(loadNbr); }}
          />
        ) : (
          <div className="flex-1 min-h-0 overflow-y-auto">
        <FilterPanel
          filters={filters}
          setFilters={setFilters}
          counts={{ visible: visibleStops.length, total: stops.length, pct: boardCompletion?.pct ?? null }}
        />
        <Legend expanded={legendExpanded} setExpanded={setLegendExpanded} />
        {showRoutes && (
          <DriverRouteLegend legend={routeData.legend} expanded={routeLegendExpanded} setExpanded={setRouteLegendExpanded} />
        )}
        {/* M4.4 — Vehicle visibility moved to the map filter toolbar. This
        block keeps only the driver-status text + label-toggle, which are
        secondary to the visibility decision. Hidden entirely when vehicles
        are off. */}
        {showDrivers && (
          <div className="border-t p-3 space-y-2">
            <button
              onClick={() => setShowDriverLabels((v) => !v)}
              className="w-full text-xs py-1 rounded inline-flex items-center justify-center gap-1.5 bg-white border border-slate-300 text-slate-700 hover:bg-slate-50"
              title="Toggle truck/driver labels"
            >
              {showDriverLabels ? <Tags size={12} /> : <Tag size={12} />}
              {showDriverLabels ? 'Hide labels' : 'Show labels'}
            </button>
            <div className="text-[10px] text-slate-500">
              {driverErr ? <span className="text-red-600">⚠ {driverErr}</span> : `${drivers.length} drivers · refresh 60s${driversAt ? ` · ${fmtTimeAgo(driversAt)}` : ''}`}
            </div>
          </div>
        )}

        <StopMiniTable
          stops={visibleStops}
          notes={notes}
          onPick={(s) => { setSelectedDriver(null); setSelectedStop(s); handlePanToStop(s); }}
          columns={tableColumns}
          onColumnsChange={setTableColumns}
          searchQuery={debouncedSearch}
          truncateNames={!useExtendedNames}
        />
          </div>
        )}
      </div>

      {/* Resize handle — desktop only */}
      <ResizeHandle onMouseDown={panel.onMouseDown} onDoubleClick={panel.onDoubleClick} />

      {/* Map */}
      <div className="flex-1 relative min-w-0">
        <div ref={mapDiv} className="absolute inset-0" />
        {/* Box/lasso multi-select: capture overlay + tool controls (above it). */}
        {selectMode && (
          <SelectionOverlay
            mode={selectMode}
            onBox={(a, b) => { selectByBox(a, b); setSelectMode(null); }}
            onLasso={(pts) => { selectByLasso(pts); setSelectMode(null); }}
          />
        )}
        {/* M5 — date picker, top-left of the map canvas. */}
        {!isMobile && (
          <div className="absolute top-3 left-3 z-[16] flex flex-col items-start gap-2">
            <DatePicker selectedDate={selectedDate} onChange={setSelectedDate} onToday={goToToday} />
            <SelectionControls mode={selectMode} setMode={setSelectMode} count={selectionSet?.size || 0} onClear={clearSelection} onText={textSelected} onTextDrivers={textSelectedDrivers} />
            {selectNote && <div className="text-[11px] bg-white/95 border border-slate-200 rounded px-2 py-0.5 shadow text-slate-700">{selectNote}</div>}
          </div>
        )}
        {/* M5.1 — top-right controls live in ONE right-aligned vertical column:
            status pill (row), then the filter toolbar. Stacking them in-flow
            (instead of absolute offsets) means the toolbar can never be buried
            under the pill regardless of the pill's height — the overlap bug
            that hid the toolbar. "Show routes" now lives inside the toolbar. */}
        {!isMobile && (
          <div className="absolute top-3 right-3 z-[6] flex flex-col items-end gap-2">
            <div className="bg-white/95 backdrop-blur border border-slate-200 rounded-lg shadow px-2.5 py-1.5 text-xs">
              {/* Header row: stops count + collapse/refresh — always visible. */}
              <div className="flex items-center gap-2">
                <button
                  onClick={() => setStatusCollapsed((c) => !c)}
                  className="flex items-center gap-1 font-semibold hover:text-slate-600"
                  title={statusCollapsed ? 'Show details' : 'Collapse'}
                  aria-expanded={!statusCollapsed}
                >
                  {statusCollapsed ? <ChevronDown size={13} className="text-slate-400" /> : <ChevronUp size={13} className="text-slate-400" />}
                  <span>{stops.length} stops{carryoverCount > 0 ? <span className="text-amber-700 font-normal"> · {carryoverCount} c/o</span> : null}</span>
                </button>
                <button
                  onClick={manualScan}
                  disabled={scanning || scanCooldown}
                  className="ml-auto p-1 rounded hover:bg-slate-100 disabled:opacity-50 min-w-[30px] min-h-[30px] inline-flex items-center justify-center"
                  title={scanCooldown ? 'Just scanned — try again shortly' : 'Refresh from NuVizz — planned/unplanned + completed + loads (~4 calls)'}
                >
                  <RefreshCw size={13} className={scanning ? 'animate-spin' : ''} />
                </button>
              </div>
              {/* Stacked details — hidden when collapsed. */}
              {!statusCollapsed && (
                <div className="mt-0.5 leading-tight">
                  <div className="text-slate-600">{totalPalletsCount.toLocaleString()} total pallets</div>
                  <UnplannedScanCount count={scanUnplannedCount} visible={visibleUnplannedCount} className="text-slate-600" />
                  <FeedTimestamps loadAt={lastLoadScanAt} unplannedAt={lastUnplannedScanAt} isToday={dateIsToday} className="text-slate-500" stacked />
                  {ops && typeof ops.dayCount === 'number' && (
                    <>
                      <div className="text-slate-500" title={`Today's NuVizz API calls (${ops.mode})${ops.byRoute && Object.keys(ops.byRoute).length ? ' · ' + Object.entries(ops.byRoute).map(([k, v]) => `${k}:${v}`).join(' ') : ''}`}>
                        NuVizz calls: {ops.dayCount.toLocaleString()}{ops.ceiling ? ` / ${ops.ceiling.toLocaleString()}` : ''} <span className="text-slate-400">({ops.mode}{ops.breaker ? ', halted' : ''})</span>
                      </div>
                      <HourlyCalls byHour={ops.byHour} className="text-slate-400 text-[10px] mt-0.5" />
                    </>
                  )}
                  {scanErr && <div className="text-[11px] text-red-600">{scanErr}</div>}
                </div>
              )}
            </div>
            <FilterToolbar
              filters={mapFilters}
              setFilters={setMapFilters}
              collapsed={toolbarCollapsed}
              setCollapsed={setToolbarCollapsed}
              stopCount={filteredStops.length}
              vehicleDisabled={!dateIsToday}
              showRoutes={showRoutes}
              setShowRoutes={setShowRoutes}
              boardDate={selectedDate}
            />
            {/* Routes panel toggle — opens the read-only route roster on the right (route name, driver,
                status incl. Draft, stops/skids/loose/weight, % delivered; click to frame on the map). */}
            <button
              onClick={() => {
                const turningOn = !routesPanelOn;
                setRoutesPanelOn(turningOn);
                // The Routes roster is the DEFAULT right panel and only renders when no stop/route/
                // driver detail is open. Opening it therefore clears any open detail so the roster
                // actually shows — otherwise the button just turned blue with nothing on the right
                // (a lingering open order/route left the panel suppressed).
                if (turningOn) { setSelectedStop(null); setSelectedRoute(null); setSelectedDriver(null); }
              }}
              title={routesPanelOn ? 'Hide the Routes panel' : 'Show the Routes panel (route roster + status)'}
              className={`flex items-center justify-center gap-1 rounded-lg border shadow px-2 py-1.5 text-[11px] font-semibold pointer-events-auto ${routesPanelOn ? 'bg-blue-600 border-blue-600 text-white' : 'bg-white/95 border-slate-200 text-slate-700 hover:bg-slate-50'}`}
            >
              <MapPinned size={13} /> Routes
            </button>
            {/* Launchers at the bottom of the right control column: texting
                (message bubble) + AI assistant ("?"). */}
            {onOpenMessages && <MessagesLauncher onClick={onOpenMessages} unread={smsUnread} />}
            {aiAvailable && !chatOpen && (
              <ChatLauncher onClick={() => setChatOpen(true)} active={aiResult?.source === 'chat'} />
            )}
          </div>
        )}
        {/* M6 — chat panel (fixed; renders as a card on desktop). */}
        <ChatPanel
          open={chatOpen}
          onClose={() => setChatOpen(false)}
          onSend={handleChatSend}
          onHighlight={handleChatHighlight}
          onClear={clearAi}
          highlightActive={aiResult?.source === 'chat'}
          stopCount={filteredStops.length}
          onDebugCapture={handleDebugCapture}
        />
        {movingStop && (
          <MoveLocationBar
            stop={movingStop}
            saving={savingLoc}
            onSave={saveStopLocation}
            onCancel={cancelMoveLocation}
            onReset={resetStopLocation}
          />
        )}
        {editAddrStop && (
          <AddressEditModal
            stop={editAddrStop}
            note={notes.get(editAddrStop.matchKey)}
            google={google}
            seed={editAddrSeed}
            onClose={() => { setEditAddrStop(null); setEditAddrSeed(null); }}
            onSaved={() => refresh({ silent: true })}
          />
        )}
        {/* M5 — one-shot note when live drivers were auto-disabled for a past/future date. */}
        {driverGateNote && (
          <div className="absolute top-16 left-1/2 -translate-x-1/2 z-[7] bg-amber-50 border border-amber-300 rounded shadow px-3 py-1.5 text-xs text-amber-800">
            Live drivers only available for today's date.
          </div>
        )}
        {mapsError && (
          // Bottom of the map area — the top strip holds the selection tally (left) and the
          // Filters button + status pill (right); a full-width banner there overlapped them.
          <div className="absolute bottom-4 left-4 right-4 bg-red-50 border border-red-200 rounded p-3 text-sm text-red-800 z-[8]">
            <div className="font-semibold">Google Maps failed to load</div>
            <div className="text-xs mt-1">{mapsError}</div>
            <div className="text-xs mt-1 text-red-600">Set VITE_GOOGLE_MAPS_API_KEY in your .env / Netlify env.</div>
          </div>
        )}
        {!visibleStops.length && !loading && !mapsError && (
          <div className="absolute top-20 left-1/2 -translate-x-1/2 bg-white border border-slate-200 rounded shadow px-3 py-1.5 text-xs text-slate-600 z-[5] text-center max-w-xs">
            {debouncedSearch
              ? `No stops match "${debouncedSearch}"`
              : dateIsToday
                ? 'No stops match the current filters.'
                : 'No loads are built for this date yet.'}
          </div>
        )}

        {error && (
          <div className="absolute bottom-3 left-1/2 -translate-x-1/2 bg-red-50 border border-red-200 rounded px-3 py-1.5 text-xs text-red-700">
            ⚠ {error}
          </div>
        )}

        {/* NuVizz-style bottom data grid — collapsible spreadsheet of the board. */}
        <BottomStopsTable
          rootRef={bottomGridRef}
          stops={visibleStops}
          boardTotal={stops.length}
          upstreamFilterLabels={mapFilterLabels}
          loadStops={stops}
          boardDate={selectedDate}
          notes={notes}
          totalCount={filteredStops.length}
          open={bottomTableOpen}
          setOpen={setBottomTableOpen}
          onPick={(s) => { setSelectedDriver(null); setSelectedStop(s); handlePanToStop(s); }}
          onPickLoad={(loadNbr) => {
            // Open the load's route as the explicit focus (panel + frame). Clear
            // the stop first so the route — not an order — owns the layout.
            setSelectedStop(null);
            openRouteExplicit(loadNbr);
          }}
        />
      </div>

      {/* Right sidebar — driver snapshot takes priority when a driver is selected. */}
      {selectedDriver && (
        <DriverSnapshotSidebar
          driver={selectedDriver}
          snapshot={snapshot}
          loading={snapshotLoading}
          error={snapshotError}
          onText={textDriver}
          onClose={() => setSelectedDriver(null)}
          onPanToStop={handlePanToStop}
        />
      )}
      {/* RIGHT column — the ROUTE detail (#388). The order sits on the LEFT, so
          opening a route keeps the order open (order ↔ route side by side), and
          picking a stop inside the route opens that order on the left WITHOUT
          closing the route, so you can walk the route stop by stop. */}
      {!selectedDriver && selectedRoute && (
        <RouteDetailSidebar
          loadNbr={selectedRoute}
          stops={selectedRouteStops}
          onClose={() => setSelectedRoute(null)}
          onPickStop={(s) => {
            setSelectedStop(s);
            handlePanToStop(s);   // building zoom; route stays framed/open on the right
          }}
        />
      )}
      {/* Read-only Routes panel — the default right panel when toggled on and nothing else is open.
          Clicking a card frames that route on the map and drills into its RouteDetailSidebar; closing
          it returns here. The roster + Status filter + search mirror the Routing screen's panel. */}
      {routesPanelOn && !selectedDriver && !selectedRoute && !selectedStop && (
        <div className="w-[320px] shrink-0 border-l bg-white flex flex-col min-h-0">
          <div className="flex items-center justify-between px-2 py-1.5 border-b shrink-0">
            <span className="font-semibold text-slate-800 text-[13px]">Routes <span className="text-slate-400 text-[11px]">({routeGroups.length})</span></span>
            <button onClick={() => setRoutesPanelOn(false)} className="text-slate-400 hover:text-slate-700" aria-label="Close routes panel"><X size={16} /></button>
          </div>
          <RoutingRoutesPanel groups={routeGroups} onPick={(key) => { const g = routeGroups.find((x) => x.key === key); setSelectedStop(null); openRouteExplicit(g?.loadNbr || key); }} />
        </div>
      )}
    </div>
  );
}

// Render the PRO cell content per brief: matched PRO first when a search is
// active; "+N" suffix when proCount > 1; em dash when empty. Returns a
// fragment so the parent <td> stays the layout boundary.
function renderProCell(stop, searchQuery) {
  const pros = stop.pros || (stop.pro ? [stop.pro] : []);
  if (pros.length === 0) return <span>—</span>;
  const matched = searchQuery ? matchedPro(stop, searchQuery) : null;
  const head = matched || pros[0];
  const rest = pros.length - 1;
  const tooltip = pros.length > 1 ? pros.join('\n') : undefined;
  return (
    <span title={tooltip} tabIndex={pros.length > 1 ? 0 : -1}>
      {head}{rest > 0 ? <span className="text-slate-400"> +{rest}</span> : null}
    </span>
  );
}

// Columns gear menu — anchored to the top-right of the StopMiniTable header.
// Click toggles a checkbox; localStorage persistence is handled by parent.
function ColumnsMenu({ columns, onChange }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    if (!open) return;
    const onDoc = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener('mousedown', onDoc);
    return () => document.removeEventListener('mousedown', onDoc);
  }, [open]);
  return (
    <div className="relative" ref={ref}>
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="p-1 rounded hover:bg-slate-100 text-slate-500"
        title="Toggle table columns"
        aria-label="Toggle table columns"
      >
        <Settings size={14} />
      </button>
      {open && (
        <div className="absolute right-0 top-full mt-1 z-10 bg-white border border-slate-200 rounded shadow-md py-1 min-w-[140px]">
          {TABLE_COLUMN_DEFS.map(({ key, label }) => (
            <label key={key} className="flex items-center gap-2 px-3 py-1 text-xs hover:bg-slate-50 cursor-pointer">
              <input
                type="checkbox"
                checked={!!columns[key]}
                onChange={(e) => onChange({ ...columns, [key]: e.target.checked })}
              />
              {label}
            </label>
          ))}
        </div>
      )}
    </div>
  );
}

// NuVizz-style bottom data grid. Spans the map width, fully collapsible (the
// header bar stays as the toggle). Rows mirror the loaded board (respects
// filters/search/box-lasso selection via the `stops` it's handed). Click a row
// to open + center that stop. Horizontally scrollable for the wide column set.
// NuVizz status buckets for the bottom-table status filter. Each maps to one or
// more of the app's classifyStopStatus() values.
const TABLE_STATUS_BUCKETS = [
  { k: 'unplanned', label: 'Un-Planned', match: ['UNPLANNED'], codes: ['10'] },
  { k: 'planned', label: 'Planned', match: ['SCHEDULED'], codes: ['20'] },
  { k: 'in_transit', label: 'In-Transit', match: ['OUT_FOR_DEL', 'ARRIVED'], codes: ['40', '50'] },
  { k: 'completed', label: 'Completed', match: ['DELIVERED'], codes: ['90', '91'] },
  { k: 'cancelled', label: 'Cancelled', match: ['EXCEPTION'], codes: ['99'] },
];
function tableStatusBucket(stop) {
  const st = classifyStopStatus(stop);
  const b = TABLE_STATUS_BUCKETS.find((x) => x.match.includes(st));
  return b ? b.k : 'planned';
}
// Header-row day breakdown: the % of the WHOLE day's board in each status (Chad —
// "a percentage breakdown of the planned stops for the day"). Same buckets as the
// Status filter, so the header pill and the filter agree. Rendered in bucket order,
// zero buckets hidden. Percentage over the whole day (not the filtered rows), the
// same steady-denominator philosophy as the "% delivered" count.
const DAY_STATUS_PILLS = [
  { k: 'planned', label: 'Planned', cls: 'text-blue-700' },
  { k: 'unplanned', label: 'Unplanned', cls: 'text-slate-500' },
  { k: 'in_transit', label: 'Out', cls: 'text-amber-600' },
  { k: 'completed', label: 'Delivered', cls: 'text-green-700' },
  { k: 'cancelled', label: 'Cancelled', cls: 'text-red-600' },
];
// Per-status chips for the Loads view status breakdown.
const LOAD_BUCKET_STYLE = {
  unplanned: 'bg-slate-100 text-slate-600',
  planned: 'bg-blue-100 text-blue-700',
  in_transit: 'bg-amber-100 text-amber-700',
  completed: 'bg-green-100 text-green-700',
  cancelled: 'bg-red-100 text-red-700',
};

// `boardTotal` / `upstreamFilterLabels`: the Map screen hands this table an ALREADY
// map-filtered set (visibleStops), so `stops.length` is not the board. Without the real
// total and the names of the filters that did the cutting, the empty state reported the
// filtered count AS the board and blamed only its own bar — "None of the 6 stops in this
// board match — hidden by status (1)" on a 723-stop board with ~600 planned orders, where
// the actual culprit was the map panel's Unplanned only (Chad: "says i don't have any
// planned orders today however i have like 600 of them"). Defaults keep Routing, which
// passes the whole board, behaving exactly as before.
function BottomStopsTable({ stops, loadStops, boardDate, notes, totalCount, open, setOpen, onPick, onPickLoad, headerRight, onWindowRowsChange, onSearchMatchChange = null, onStatusFilterChange = null, planVersion = 0, highlightIds = null, rootRef = null, boardTotal = null, upstreamFilterLabels = [] }) {
  // Loads view groups the FULL board's loads (loadStops) so stop-level filters —
  // notably "Unplanned only" — don't empty it. Falls back to the visible stops.
  const loadSrc = loadStops || stops;
  const [q, setQ] = useState('');
  const [view, setView] = useState('stops'); // 'stops' | 'loads'
  // The day's full load ROSTER (incl. empty loads with no orders yet), pulled on demand
  // when the Loads view is open. Empty loads can't appear from stop-grouping (no stops to
  // group), so we merge these in. Follows the selected board date.
  const [roster, setRoster] = useState([]);
  const [statusSel, setStatusSel] = useState(() => new Set()); // empty = all
  const [statusOpen, setStatusOpen] = useState(false);
  // NuVizz live pull (desktop toolbar): when nvWindow is set, the grid shows stops
  // fetched straight from NuVizz's stop list (any delivery-date window / status)
  // instead of today's board — e.g. "all unplanned ±7 days". Driver is a local
  // refinement applied to whatever rows are shown.
  const [nvWindow, setNvWindow] = useState(''); // '' = board; else '0d' | '+/-7d' | 'custom'
  const [nvFrom, setNvFrom] = useState(''); // 'custom' range endpoints (YYYY-MM-DD)
  const [nvTo, setNvTo] = useState('');
  const [nvRows, setNvRows] = useState([]);
  const [nvTotal, setNvTotal] = useState(0);
  const [nvPartial, setNvPartial] = useState(false); // covering pull was incomplete → count is "≥ N"
  const [nvSource, setNvSource] = useState('live'); // 'live' = straight from NuVizz; 'cache' = our board day-docs (±7d / wide custom ranges)
  const [nvLoading, setNvLoading] = useState(false);
  const [nvErr, setNvErr] = useState(null);
  const [driverSel, setDriverSel] = useState('');
  const [unmappedOnly, setUnmappedOnly] = useState(false); // show only stops with no map location (unroutable until fixed)
  // Drag-resizable height (px), persisted. Drag the top handle up/down.
  const [height, setHeight] = useState(() => {
    const v = safeReadJSON(LS_BOTTOM_TABLE_HEIGHT, 300);
    return typeof v === 'number' && v > 0 ? v : 300;
  });
  useEffect(() => { safeWriteJSON(LS_BOTTOM_TABLE_HEIGHT, height); }, [height]);
  const onResizeDown = (e) => {
    e.preventDefault();
    const move = (ev) => {
      const y = ev.touches ? ev.touches[0].clientY : ev.clientY;
      setHeight(Math.max(120, Math.min(window.innerHeight * 0.85, window.innerHeight - y)));
    };
    const up = () => {
      document.removeEventListener('pointermove', move);
      document.removeEventListener('pointerup', up);
    };
    document.addEventListener('pointermove', move);
    document.addEventListener('pointerup', up);
  };
  // A stop's calendar day for the multi-day window view. Board mode never shows it.
  const rowDayOf = (s) => s.boardDate || s.scheduledDate || s.requestedDate || '';
  const todayET = todayInET();
  const cols = [
    // `fit` (Chad: "i want the whole number to show") — never clip this cell. A stop number is
    // an IDENTIFIER: half of one is not a shorter version of it, it is unusable, and these run
    // from a bare "007157031" to a carrier-prefixed "ESTES-0828068215" that the old 96px clamp
    // cut to "ESTES-2958…". The 150 is only the layout's opening bid; the column takes whatever
    // the longest number on screen needs, and the grid already scrolls sideways.
    { k: 'stop', label: 'Stop #', w: 150, fit: true, get: (s) => <span className="font-mono text-blue-700">{s.stopNbr}</span>, sortVal: (s) => (Number.isFinite(Number(s.stopNbr)) ? Number(s.stopNbr) : s.stopNbr) },
    // DAY — only in a date-window pull. A ±7-day list mixes past carry-over, today, and
    // FUTURE-day orders (tomorrow's appointments legitimately sit unplanned tonight); without
    // this column those read as one big backlog and the counts look "drifted" vs the board.
    ...(nvWindow ? [{
      k: 'day', label: 'Day', w: 92,
      get: (s) => {
        const d = rowDayOf(s);
        if (!d) return <span className="text-slate-400">—</span>;
        const label = d.slice(5).replace('-', '/');
        return d === todayET
          ? <span className="font-semibold text-blue-700">today</span>
          : d < todayET
            ? <span className="text-amber-700" title={`Carry-over from ${d}`}>{label} ◂</span>
            : <span className="text-violet-700" title={`Future delivery day ${d}`}>{label} ▸</span>;
      },
      sortVal: (s) => rowDayOf(s) || '~',
    }] : []),
    // A pickup names itself in the grid (Chad: "Ra's should be marked as pickups and not
    // deliveries") — the chip rides the name cell so no new column is needed and it survives
    // any column re-order the gear menu applies.
    { k: 'name', label: 'Ship To Name', w: 220, get: (s) => (
        String(s.stopType || '').toUpperCase() === 'PU'
          ? <><span className="inline-block text-[9px] font-bold rounded bg-amber-100 text-amber-800 px-1 py-px mr-1.5 align-middle" title="Pickup — freight comes back to the terminal">PU</span>{s.businessName || '—'}</>
          : (s.businessName || '—')
      ), sortVal: (s) => s.businessName },
    { k: 'addr1', label: 'Address 1', w: 200, get: (s) => s.addr1 || '—', sortVal: (s) => s.addr1 },
    { k: 'addr2', label: 'Address 2', w: 150, get: (s) => s.addr2 || '', sortVal: (s) => s.addr2 },
    { k: 'city', label: 'City', w: 120, get: (s) => s.city || '—', sortVal: (s) => s.city },
    { k: 'zip', label: 'Zip', w: 70, get: (s) => s.zip || '', sortVal: (s) => s.zip },
    { k: 'cartons', label: 'Pallets', w: 70, get: (s) => (s.cartons ?? '—'), align: 'right', sortVal: (s) => (typeof s.cartons === 'number' ? s.cartons : null) },
    { k: 'volume', label: 'Loose', w: 64, get: (s) => (s.volume ?? '—'), align: 'right', sortVal: (s) => (typeof s.volume === 'number' ? s.volume : null) },
    { k: 'weight', label: 'Weight', w: 80, get: (s) => (s.weight != null ? Number(s.weight).toLocaleString() : '—'), align: 'right', sortVal: (s) => (s.weight != null ? Number(s.weight) : null) },
    { k: 'restr', label: 'Restrictions', w: 160, get: (s) => {
        const keys = getRestrictionBadgeKeys(notes.get(s.matchKey) || null);
        return keys.length ? keys.map((k) => RESTRICTION_ICONS[k]?.short || k).join(', ') : '';
      }, sortVal: (s) => getRestrictionBadgeKeys(notes.get(s.matchKey) || null).map((k) => RESTRICTION_ICONS[k]?.short || k).join(', ') },
    { k: 'load', label: 'Load', w: 150, get: (s) => loadDisplayName(s.routeName, s.loadNbr), sortVal: (s) => loadDisplayName(s.routeName, s.loadNbr) },
    { k: 'driver', label: 'Driver', w: 150, get: (s) => s.driverName || '', sortVal: (s) => s.driverName },
  ];
  // Board mode shows today's loaded stops; NuVizz mode shows the live-pulled set.
  // WINDOW rows get two layers of plan truth (board-mode `stops` already carry both via
  // useStops + the board itself): (1) the confirmed-save overlay, re-applied on every save
  // (planVersion bump) — covers the seconds between a Save and the board refresh; then
  // (2) reflectBoardPlan mirrors the authoritative BOARD row onto each matching window row.
  // The overlay alone wasn't enough: it's a shared one-shot map that the board consumer
  // self-cleans the moment the patched board agrees — usually before this window repaints —
  // so a just-planned stop reverted to "available" here until a scan (the LVILLE lingering).
  const boardByNbr = useMemo(() => {
    const m = new Map();
    for (const s of stops || []) if (s && s.stopNbr != null) m.set(String(s.stopNbr), s);
    return m;
  }, [stops]);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const baseStops = useMemo(() => (nvWindow ? reflectBoardPlan(applyPlanOverlay(nvRows), boardByNbr) : stops), [nvWindow, nvRows, stops, boardByNbr, planVersion]);
  // Pull from NuVizz whenever a date window is selected (re-pull when the status
  // selection changes so status filters server-side, not just on the loaded page).
  useEffect(() => {
    if (!nvWindow) { setNvErr(null); setNvLoading(false); return; }
    // '-7d' / '-14d' are AUTO ranges: board day back N days, tracking the board-date input —
    // "takes the day the board is set to and goes back". They ride the same fromDate/toDate
    // cache path as a hand-picked custom range (scanned days → cache-served, zero NuVizz).
    const autoBack = nvWindow === '-7d' ? 7 : nvWindow === '-14d' ? 14 : 0;
    const custom = nvWindow === 'custom' || autoBack > 0;
    // Custom range needs BOTH endpoints before it can pull — clear any previous window's rows.
    // An auto range needs a valid board date (always present in practice).
    if ((nvWindow === 'custom' && (!nvFrom || !nvTo)) || (autoBack > 0 && !ymdShift(boardDate, 0))) { setNvErr(null); setNvLoading(false); setNvRows([]); setNvTotal(0); setNvPartial(false); return; }
    let cancelled = false;
    const ctrl = new AbortController();
    const codes = TABLE_STATUS_BUCKETS.filter((b) => statusSel.has(b.k)).flatMap((b) => b.codes);
    const [lo, hi] = nvWindow === 'custom'
      ? (nvFrom <= nvTo ? [nvFrom, nvTo] : [nvTo, nvFrom])
      : autoBack > 0 ? [ymdShift(boardDate, -autoBack), boardDate] : ['', ''];
    const req = custom
      ? { fromDate: lo, toDate: hi, statusCodes: codes, page: 1, pageSize: 1000 }
      : { arrivalPeriod: nvWindow, statusCodes: codes, page: 1, pageSize: 1000 };
    setNvLoading(true); setNvErr(null);
    // DEBOUNCE custom-range pulls: a native date input fires onChange per SEGMENT edit, so a
    // straight fetch would fire a pull on each keystroke. A window preset needs no debounce.
    const timer = setTimeout(() => {
      fetch('/.netlify/functions/nuvizz-stop-explorer', {
        method: 'POST', cache: 'no-store', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(req), signal: ctrl.signal,
      })
        .then((r) => r.json())
        .then((j) => {
          if (cancelled) return;
          if (!j.ok) throw new Error(j.error || 'pull failed');
          // Deploy-skew guard: a server that predates custom ranges ignores fromDate/toDate and
          // would silently return the wrong window — the echoed `range` proves it honored them.
          if (custom && !j.range) throw new Error('server doesn’t support date ranges yet — hard-refresh the app and retry');
          const decorated = (j.rows || []).map((s) => ({
            ...s,
            matchKey: normalizeMatchKey(s.businessName || '', s.addr1 || '', s.city || '', s.zip || ''),
            loadNbr: s.routeName || '',
          }));
          // nvSource is tracked so the routing map knows a cache-backed pull is coord-bearing
          // (±7d / a wide custom range) and can render those orders for selection (v0.45.4).
          setNvRows(decorated); setNvTotal(j.total ?? decorated.length); setNvPartial(!!j.partial); setNvSource(j.source === 'cache' ? 'cache' : 'live');
        })
        .catch((e) => { if (!cancelled) { setNvErr(e.message); setNvRows([]); setNvTotal(0); setNvPartial(false); } })
        .finally(() => { if (!cancelled) setNvLoading(false); });
    }, nvWindow === 'custom' ? 600 : 0);   // only hand-typed dates need the debounce
    return () => { cancelled = true; ctrl.abort(); clearTimeout(timer); };
  }, [nvWindow, nvFrom, nvTo, statusSel, boardDate]);
  // Report the active window's coord-bearing rows UP so the routing map can render them for
  // selection/planning. Only the CACHE path carries coordinates (the live small-window list feed
  // has none); a live window or board mode reports null → the map stays on the single board day.
  // Pass the OVERLAY-APPLIED rows (baseStops), not raw nvRows: a window-picked stop that was
  // just saved onto a route must flip planned on the MAP too — raw rows kept it reading
  // stale-unplanned there (the mapBaseStops comment claimed the overlay applied; it did not),
  // which is how a saved old-dated order looked grabbable/unplanned the moment its card closed.
  // baseStops recomputes on planVersion, so every confirmed save re-pushes fresh rows.
  useEffect(() => {
    if (!onWindowRowsChange) return;
    onWindowRowsChange(nvWindow && nvSource === 'cache' && nvRows.length ? baseStops : null);
  }, [nvWindow, nvSource, nvRows, baseStops, onWindowRowsChange]);
  // On unmount, release the window rows so the map reverts to the day board.
  useEffect(() => () => { if (onWindowRowsChange) onWindowRowsChange(null); }, [onWindowRowsChange]);
  const driverOptions = useMemo(() => {
    const set = new Set();
    for (const s of baseStops) if (s.driverName) set.add(s.driverName);
    return [...set].sort();
  }, [baseStops]);
  const filteredRows = useMemo(() => {
    const needle = q.trim().toLowerCase();
    return baseStops.filter((s) => {
      // Status: client-side in board mode; in a NuVizz window the server pre-filters, but the
      // check re-runs here anyway because the plan OVERLAY runs after that server filter — a
      // cached-unplanned row a recent Save flipped to planned (Load "RASKO") was showing under
      // the Un-Planned filter. Re-checking post-overlay keeps the filter honest either way.
      if (statusSel.size && !statusSel.has(tableStatusBucket(s))) return false;
      if (driverSel && (s.driverName || '') !== driverSel) return false;
      if (needle) {
        const hay = [s.stopNbr, s.businessName, s.addr1, s.addr2, s.city, s.zip, s.routeName, s.loadNbr, s.driverName]
          .filter(Boolean).join(' ').toLowerCase();
        if (!hay.includes(needle)) return false;
      }
      return true;
    });
  }, [baseStops, q, statusSel, driverSel, nvWindow]);
  // Day-level status breakdown over the WHOLE board (baseStops), independent of the
  // active search/status filter — a steady progress read of the selected day, shown
  // as a percentage pill on the header row.
  const dayStatus = useMemo(() => {
    const c = { unplanned: 0, planned: 0, in_transit: 0, completed: 0, cancelled: 0 };
    for (const s of baseStops) { const b = tableStatusBucket(s); c[b] = (c[b] || 0) + 1; }
    const total = baseStops.length;
    const pct = {};
    for (const k of Object.keys(c)) pct[k] = total ? Math.round((c[k] / total) * 100) : 0;
    return { c, pct, total };
  }, [baseStops]);
  // Report the CURRENT SEARCH matches UP (stopNbr set) so the Routing map can highlight them
  // (burnt orange, top layer) — parity with the Map screen's search highlight, which the Routing
  // screen never had. Exactly the rows the grid is showing (WYSIWYG: search + status + driver),
  // but ONLY when a search needle is active (no needle → null → no highlight). Debounced so a
  // per-keystroke rebuild of every map marker doesn't jank. No-op when the parent doesn't pass a
  // handler (the dispatch Map, which has its own search). Keyed String() to match the map's ids.
  const searchActive = q.trim().length > 0;
  const searchMatchIds = useMemo(
    () => (searchActive ? new Set(filteredRows.map((s) => String(s.stopNbr))) : null),
    [searchActive, filteredRows],
  );
  const debouncedMatchIds = useDebouncedValue(searchMatchIds, 180);
  useEffect(() => { onSearchMatchChange?.(debouncedMatchIds); }, [debouncedMatchIds, onSearchMatchChange]);
  useEffect(() => () => onSearchMatchChange?.(null), [onSearchMatchChange]);
  // Status/driver filters reach the MAP too (WYSIWYG — Chad: "Planned checked
  // should only be showing planned"). Reported as the id set of rows PASSING the
  // status+driver filters (search is deliberately NOT folded in: search is a
  // burnt-orange highlight, never a hide). null when no filter is active → the
  // map shows everything, exactly as before.
  const statusFilterIds = useMemo(() => {
    if (!statusSel.size && !driverSel) return null;
    const out = new Set();
    for (const s of baseStops) {
      if (statusSel.size && !statusSel.has(tableStatusBucket(s))) continue;
      if (driverSel && (s.driverName || '') !== driverSel) continue;
      out.add(String(s.stopNbr));
    }
    return out;
  }, [baseStops, statusSel, driverSel]);
  const debouncedStatusIds = useDebouncedValue(statusFilterIds, 180);
  useEffect(() => { onStatusFilterChange?.(debouncedStatusIds); }, [debouncedStatusIds, onStatusFilterChange]);
  useEffect(() => () => onStatusFilterChange?.(null), [onStatusFilterChange]);
  // Stops with NO geocoded location. They list here but have no map marker, so they can't be
  // box/lasso-selected OR routed (the map's stopById is coord-only) — this is how an order gets
  // silently MISSED. Surfaced as a count + one-click filter so they're findable and fixable.
  const unmappedCount = useMemo(() => filteredRows.filter((s) => s.lat == null || s.lng == null).length, [filteredRows]);
  const rows = useMemo(
    () => (unmappedOnly ? filteredRows.filter((s) => s.lat == null || s.lng == null) : filteredRows),
    [filteredRows, unmappedOnly],
  );
  // Never strand the "no location" filter on when there's nothing to show (its chip hides at 0,
  // so the user couldn't turn it back off) — e.g. after switching windows or fixing every address.
  useEffect(() => { if (unmappedOnly && unmappedCount === 0) setUnmappedOnly(false); }, [unmappedOnly, unmappedCount]);
  // Pull the day's full load ROSTER (incl. empty loads) whenever the Loads view is open —
  // empty loads have no stops to group, so this is the only way to see them. The Loads view
  // is ALWAYS board-day-scoped (its grouped loads come from `stops`, the board day), so the
  // Stops-view date window (nvWindow) must NOT gate it — gating it here made every empty
  // draft load vanish from Loads the moment a day range was set on the Stops grid.
  useEffect(() => {
    if (view !== 'loads' || !boardDate) return;
    let cancelled = false;
    fetch('/.netlify/functions/nuvizz-loads-roster?date=' + encodeURIComponent(boardDate), { cache: 'no-store' })
      .then((r) => r.json())
      .then((j) => { if (!cancelled) setRoster(j.ok ? (j.loads || []) : []); })
      .catch(() => { if (!cancelled) setRoster([]); });
    return () => { cancelled = true; };
  }, [view, boardDate]);

  // Loads view — group the same board (the `stops` we're handed) by loadNbr so
  // dispatchers can browse current loads instead of individual stops. Each row
  // aggregates driver, stop count, a per-status breakdown, and pallet/weight
  // totals. Click a row to open that load's route drawer + frame it on the map.
  // Empty loads (no orders assigned yet) are merged in from the roster below.
  // Real NuVizz load NUMBER ("DAVIS000198197") by route name, from the day's roster — the
  // per-stop `loadNbr` field is actually the route NAME (the stops feed has no number column;
  // see nuvizz-write.mts), so this is the ONLY place the grid can source the real id from.
  const rosterByName = useMemo(() => {
    const m = new Map();
    for (const r of roster) { const nm = String(r.name || '').trim().toLowerCase(); if (nm && !m.has(nm)) m.set(nm, r); }
    return m;
  }, [roster]);
  const loadRows = useMemo(() => {
    const m = new Map();
    for (const s of loadSrc) {
      if (!s.loadNbr) continue; // only real (built) loads
      let g = m.get(s.loadNbr);
      if (!g) { g = { loadNbr: s.loadNbr, routeName: s.routeName || '', driverName: s.driverName || '', stops: [] }; m.set(s.loadNbr, g); }
      if (!g.routeName && s.routeName) g.routeName = s.routeName;
      if (!g.driverName && s.driverName) g.driverName = s.driverName;
      g.stops.push(s);
    }
    const needle = q.trim().toLowerCase();
    let arr = [...m.values()].map((g) => {
      const buckets = {};
      let pallets = 0, loose = 0, weight = 0;
      for (const s of g.stops) {
        const bk = tableStatusBucket(s); buckets[bk] = (buckets[bk] || 0) + 1;
        if (typeof s.cartons === 'number') pallets += s.cartons;
        if (typeof s.volume === 'number') loose += s.volume;
        if (s.weight != null) weight += Number(s.weight) || 0;
      }
      const rosterEntry = rosterByName.get(String(g.routeName || '').trim().toLowerCase());
      const realId = rosterEntry?.loadNbr || rosterEntry?.loadId || null;
      return { loadNbr: g.loadNbr, routeName: g.routeName, driverName: g.driverName, count: g.stops.length, buckets, pallets, loose, weight, realId };
    });
    // Merge in EMPTY loads from the day's roster — loads created but with no orders assigned
    // yet have no stops to group, so they never appear from stop-grouping. Match by route
    // name to avoid duplicating loads we already built from stops. NOT gated on nvWindow: the
    // Loads view is board-day-scoped, so the Stops-view date window must never hide the day's
    // empty loads here (that dropped Loads from ~100 down to just the built routes).
    if (roster.length) {
      const haveNames = new Set(arr.map((g) => String(g.routeName || '').trim().toLowerCase()).filter(Boolean));
      for (const r of roster) {
        const nm = String(r.name || '').trim();
        if (!nm || haveNames.has(nm.toLowerCase())) continue;
        arr.push({ loadNbr: r.loadNbr || r.loadId, routeName: nm, driverName: '', count: r.trips || 0, buckets: {}, pallets: 0, loose: 0, weight: 0, empty: true, rosterStatus: r.status, realId: r.loadNbr || r.loadId || null });
      }
    }
    if (needle) arr = arr.filter((g) => [g.loadNbr, g.routeName, g.driverName].filter(Boolean).join(' ').toLowerCase().includes(needle));
    arr.sort((a, b) => String(a.driverName || '~').localeCompare(String(b.driverName || '~')) || String(a.routeName || a.loadNbr).localeCompare(String(b.routeName || b.loadNbr)));
    return arr;
  }, [loadSrc, q, roster, rosterByName]);
  const loadCols = [
    { k: 'load', label: 'Load', w: 150, get: (g) => <span className="font-mono text-blue-700">{loadDisplayName(g.routeName, g.loadNbr) || 'Unnamed load'}</span>, sortVal: (g) => g.routeName || g.loadNbr },
    { k: 'driver', label: 'Driver', w: 180, get: (g) => g.driverName || '—', sortVal: (g) => g.driverName },
    { k: 'count', label: 'Stops', w: 60, align: 'right', get: (g) => g.count, sortVal: (g) => g.count },
    { k: 'pct', label: '% Done', w: 70, align: 'right',
      get: (g) => g.empty ? '—' : (() => { const p = g.count ? Math.round(100 * (g.buckets.completed || 0) / g.count) : 0; return <span className="font-semibold tabular-nums" style={{ color: p === 100 ? '#16a34a' : BRAND }}>{p}%</span>; })(),
      sortVal: (g) => (g.empty ? -1 : (g.count ? (g.buckets.completed || 0) / g.count : 0)) },
    { k: 'loadId', label: 'Load ID', w: 130,
      get: (g) => g.realId ? <span className="font-mono text-[11px] text-slate-500" title={g.realId}>{g.realId}</span> : '—',
      sortVal: (g) => g.realId || '' },
    { k: 'status', label: 'Status', w: 240, get: (g) => (g.empty
        ? <span className="inline-flex items-center gap-1 px-1.5 rounded text-[10px] font-medium bg-amber-50 text-amber-700 border border-amber-200" title={g.rosterStatus ? ('Load status: ' + g.rosterStatus) : 'No orders assigned yet'}>No orders yet{g.rosterStatus ? ' · ' + g.rosterStatus : ''}</span>
        : (
        <span className="inline-flex flex-wrap gap-1">
          {TABLE_STATUS_BUCKETS.map((b) => g.buckets[b.k]
            ? <span key={b.k} className={'px-1.5 rounded text-[10px] font-medium ' + (LOAD_BUCKET_STYLE[b.k] || '')} title={b.label}>{b.label} {g.buckets[b.k]}</span>
            : null)}
        </span>
      )), sortVal: (g) => (g.empty ? -1 : (g.count ? (g.buckets.completed || 0) / g.count : 0)) /* % delivered; empty loads sort first */ },
    { k: 'pallets', label: 'Pallets', w: 70, align: 'right', get: (g) => g.pallets || '—', sortVal: (g) => g.pallets },
    { k: 'loose', label: 'Loose', w: 64, align: 'right', get: (g) => g.loose || '—', sortVal: (g) => g.loose },
    { k: 'weight', label: 'Weight', w: 90, align: 'right', get: (g) => g.weight ? Math.round(g.weight).toLocaleString() : '—', sortVal: (g) => g.weight },
  ];
  // Per-table column sort. null key = original order; click cycles asc → desc.
  // Stops and Loads keep independent sort so switching tabs preserves each.
  const [stopSort, setStopSort] = useState({ key: null, dir: 'asc' });
  const [loadSort, setLoadSort] = useState({ key: null, dir: 'asc' });
  const cycleSort = (setSort) => (k) => setSort((p) => (p.key === k ? { key: k, dir: p.dir === 'asc' ? 'desc' : 'asc' } : { key: k, dir: 'asc' }));
  const toggleStopSort = cycleSort(setStopSort);
  const toggleLoadSort = cycleSort(setLoadSort);
  const sortedRows = useMemo(() => sortRows(rows, cols, stopSort), [rows, stopSort]); // eslint-disable-line react-hooks/exhaustive-deps
  const sortedLoadRows = useMemo(() => sortRows(loadRows, loadCols, loadSort), [loadRows, loadSort]); // eslint-disable-line react-hooks/exhaustive-deps
  const toggleStatus = (k) => setStatusSel((prev) => { const n = new Set(prev); n.has(k) ? n.delete(k) : n.add(k); return n; });
  const anyFilterActive = !!(q.trim() || statusSel.size || driverSel || unmappedOnly);
  const clearAllFilters = () => { setQ(''); setStatusSel(new Set()); setDriverSel(''); setUnmappedOnly(false); };
  // Human list of what's currently hiding rows — powers the "0 shown but N exist" empty state so a
  // stray (and, with the panel narrow, invisible) search term can never silently blank the grid.
  const activeFilterLabels = [
    // Upstream (map-panel) filters FIRST — they cut the set before this table ever saw it,
    // so they are the likeliest answer to "where did my rows go".
    ...(upstreamFilterLabels || []),
    q.trim() && `search “${q.trim()}”`,
    statusSel.size && `status (${statusSel.size})`,
    driverSel && `driver “${driverSel}”`,
    unmappedOnly && 'no-location filter',
  ].filter(Boolean);

  // ── Bottom-panel PROFILES ─────────────────────────────────────────────────
  // Save the current bar settings under a name and switch between saved profiles.
  // A profile snapshots view / status / date-window + range / driver / no-location /
  // sort — everything on the bar EXCEPT the transient search text. The LIST lives in
  // Firestore so it follows you to every device; which one is ACTIVE stays on this
  // device (see useBottomPanelProfiles).
  const { list: profileList, active: activeProfileName, setActive: setActiveProfileName, saveProfile: persistProfile, removeProfile } = useBottomPanelProfiles();
  const [profilesOpen, setProfilesOpen] = useState(false);
  const [newProfileName, setNewProfileName] = useState('');
  const [savedFlash, setSavedFlash] = useState(false); // brief "✓ Saved" confirmation
  const flashSaved = () => { setSavedFlash(true); setTimeout(() => setSavedFlash(false), 1400); };
  const barSnapshot = () => ({ view, status: [...statusSel], nvWindow, nvFrom, nvTo, driverSel, unmappedOnly, stopSort, loadSort });
  const applyBarSettings = (s) => {
    if (!s) return;
    setView(s.view === 'loads' ? 'loads' : 'stops');
    setStatusSel(new Set(Array.isArray(s.status) ? s.status : []));
    setNvWindow(s.nvWindow || '');
    setNvFrom(s.nvFrom || '');
    setNvTo(s.nvTo || '');
    setDriverSel(s.driverSel || '');
    setUnmappedOnly(!!s.unmappedOnly);
    setStopSort(s.stopSort && 'key' in s.stopSort ? s.stopSort : { key: null, dir: 'asc' });
    setLoadSort(s.loadSort && 'key' in s.loadSort ? s.loadSort : { key: null, dir: 'asc' });
    setOpen(true);
  };
  const activeProfile = profileList.find((p) => p.name === activeProfileName) || null;
  const selectProfile = (name) => {
    const p = profileList.find((x) => x.name === name);
    if (!p) return;
    applyBarSettings(p.s);
    setActiveProfileName(name);
    setProfilesOpen(false);
  };
  const saveNewProfile = () => {
    const name = newProfileName.trim();
    if (!name) return;
    persistProfile(name, barSnapshot());     // same name overwrites (no dupes)
    setActiveProfileName(name);
    setNewProfileName('');
    flashSaved();
  };
  const updateActiveProfile = () => {
    if (!activeProfile) return;
    persistProfile(activeProfile.name, barSnapshot());
    flashSaved();
  };
  const deleteProfile = (name) => removeProfile(name);

  return (
    <div ref={rootRef} className="absolute left-0 right-0 bottom-0 z-[12] bg-white border-t border-slate-200 shadow-[0_-2px_10px_rgba(0,0,0,0.10)] flex flex-col" style={{ height: open ? height : undefined, maxHeight: open ? 'calc(100% - 4rem)' : undefined }}>
      {open && (
        <div
          onPointerDown={onResizeDown}
          className="absolute -top-1.5 left-0 right-0 h-3 cursor-row-resize z-10 flex items-center justify-center group"
          title="Drag to resize"
          style={{ touchAction: 'none' }}
        >
          <div className="w-10 h-1 rounded-full bg-slate-300 group-hover:bg-slate-400" />
        </div>
      )}
      {/* flex-wrap: this bar has grown a control at a time (status %, profiles, no-location,
          window, driver, gear) and a non-wrapping row simply pushes the tail off the right
          edge — invisible AND unreachable, which is how the Stops/Loads toggle and the driver
          filter disappeared. Wrapping costs one extra line at narrow widths and can never hide
          a control. */}
      <div className="flex flex-wrap items-center gap-2 px-3 py-1.5 border-b border-slate-100">
        <button onClick={() => setOpen(!open)} className="inline-flex items-center justify-center min-w-[34px] min-h-[34px] rounded text-slate-600 hover:text-slate-900 hover:bg-slate-100" aria-expanded={open} title={open ? 'Collapse' : 'Expand'}>
          {open ? <ChevronDown size={14} /> : <ChevronUp size={14} />}
        </button>
        {/* shrink-0: Stops/Loads is the bar's primary control — it never gives up width. */}
        <div className="inline-flex shrink-0 rounded-md border border-slate-200 overflow-hidden text-xs font-semibold whitespace-nowrap">
          <button
            onClick={() => { setView('stops'); setOpen(true); }}
            className={'inline-flex items-center gap-1.5 px-2.5 py-1 ' + (view === 'stops' ? 'bg-blue-50 text-blue-700' : 'text-slate-600 hover:bg-slate-50')}
          >
            <LayoutList size={13} /> Stops
            <span className="font-normal opacity-60">{rows.length}{nvWindow ? (nvTotal && nvTotal !== rows.length ? `/${nvTotal.toLocaleString()}` : '') : (totalCount != null && totalCount !== rows.length ? `/${totalCount}` : '')}</span>
          </button>
          <button
            onClick={() => { setView('loads'); setOpen(true); }}
            className={'inline-flex items-center gap-1.5 px-2.5 py-1 border-l border-slate-200 ' + (view === 'loads' ? 'bg-blue-50 text-blue-700' : 'text-slate-600 hover:bg-slate-50')}
          >
            <Truck size={13} /> Loads
            <span className="font-normal opacity-60">{loadRows.length}</span>
          </button>
        </div>
        {/* Day status breakdown — % of the selected day's board in each status (Chad:
            "a percentage breakdown of the planned stops for the day"). Whole-day
            denominator, so it's a steady progress read while you search/filter.
            hidden on narrow widths so the packed bar never overflows. */}
        {dayStatus.total > 0 && (
          <div
            className="hidden lg:flex items-center gap-x-2 text-[11px] whitespace-nowrap pl-1"
            title={`${nvWindow ? 'Selected window' : "Today's board"}: ` + DAY_STATUS_PILLS.map((p) => `${p.label} ${dayStatus.c[p.k]}`).join(' · ') + ` · ${dayStatus.total} stop${dayStatus.total === 1 ? '' : 's'} total`}
          >
            {DAY_STATUS_PILLS.filter((p) => dayStatus.c[p.k] > 0).map((p) => (
              <span key={p.k} className={p.cls}>{p.label} <span className="font-semibold">{dayStatus.pct[p.k]}%</span></span>
            ))}
          </div>
        )}
        {/* PROFILES — save/switch the bar settings (view · status · window · driver · sort). */}
        <div className="relative">
          <button
            onClick={() => setProfilesOpen((v) => !v)}
            title="Saved views — save the current bar settings as a profile and switch between them"
            className={'inline-flex items-center gap-1 px-2 py-1 rounded text-xs border whitespace-nowrap ' + (activeProfile ? 'border-blue-400 text-blue-700 bg-blue-50' : 'border-slate-300 text-slate-600 hover:bg-slate-50')}
          >
            <Save size={12} /> <span className="max-w-[110px] truncate">{activeProfile ? activeProfile.name : 'Profiles'}</span>
            <ChevronDown size={11} className="opacity-60" />
          </button>
          {profilesOpen && (
            <>
              <div className="fixed inset-0 z-10" onClick={() => setProfilesOpen(false)} />
              <div className="absolute left-0 bottom-full mb-1 w-64 bg-white border border-slate-200 rounded-lg shadow-lg z-20 p-1 text-xs">
                {profileList.length === 0 && <div className="px-2 py-1.5 text-slate-400 italic">No saved profiles yet — set the bar how you like it, name it below, and Save.</div>}
                {profileList.map((p) => (
                  <div key={p.name} className={'flex items-center gap-1 rounded ' + (p.name === activeProfileName ? 'bg-blue-50' : 'hover:bg-slate-50')}>
                    <button onClick={() => selectProfile(p.name)} className="flex-1 min-w-0 text-left px-2 py-1.5 truncate" title={`Apply “${p.name}”`}>
                      {p.name === activeProfileName ? '● ' : ''}{p.name}
                    </button>
                    <button onClick={() => deleteProfile(p.name)} title={`Delete “${p.name}”`} className="px-1.5 py-1 text-slate-400 hover:text-red-600 shrink-0"><Trash2 size={12} /></button>
                  </div>
                ))}
                {activeProfile && (
                  <button onClick={updateActiveProfile} className="w-full text-left px-2 py-1.5 mt-1 rounded text-slate-600 hover:bg-slate-50 border-t border-slate-100" title="Overwrite this profile with the current bar settings">
                    ⤓ Update “{activeProfile.name}” to current
                  </button>
                )}
                <div className="flex items-center gap-1 mt-1 pt-1 border-t border-slate-100">
                  <input
                    value={newProfileName}
                    onChange={(e) => setNewProfileName(e.target.value)}
                    onKeyDown={(e) => { if (e.key === 'Enter') saveNewProfile(); }}
                    placeholder="Save current as…"
                    className="flex-1 min-w-0 border border-slate-300 rounded px-2 py-1 text-xs focus:outline-none focus:ring-2 focus:ring-blue-200 focus:border-blue-400"
                  />
                  <button
                    onClick={() => { if (newProfileName.trim()) saveNewProfile(); else if (activeProfile) updateActiveProfile(); }}
                    disabled={!newProfileName.trim() && !activeProfile}
                    title={newProfileName.trim() ? 'Save as a new profile' : (activeProfile ? `Overwrite “${activeProfile.name}” with the current bar settings` : 'Type a name to save a profile')}
                    className="px-2 py-1 rounded bg-blue-600 text-white font-semibold disabled:opacity-40 shrink-0 whitespace-nowrap"
                  >
                    {savedFlash ? '✓ Saved' : (newProfileName.trim() || !activeProfile ? 'Save' : 'Update')}
                  </button>
                </div>
                {/* Say it out loud: a saved profile is now everyone's, and deleting one
                    deletes it for everyone. Which profile you're VIEWING stays yours. */}
                <div className="px-2 pt-1 text-[10px] text-slate-400 leading-snug">
                  Shared across all devices. The profile you have selected is just for this device.
                </div>
              </div>
            </>
          )}
        </div>
        {/* No-location chip — these rows have no map pin, so they can't be selected on the map
            or routed until their address is fixed. This reconciles the "grid count > map
            selection" gap AND surfaces silently-unroutable orders. Click to isolate them. */}
        {view === 'stops' && unmappedCount > 0 && (
          <button
            onClick={() => { setUnmappedOnly((v) => !v); setOpen(true); }}
            title="These stops have no map location — they can't be selected on the map or routed until you fix the address (Edit address / Correct pin). Click to show only them."
            className={'inline-flex items-center gap-1 px-2 py-1 rounded text-xs border whitespace-nowrap ' + (unmappedOnly ? 'border-amber-500 bg-amber-500 text-white' : 'border-amber-400 text-amber-700 bg-amber-50 hover:bg-amber-100')}
          >
            <MapPin size={12} /> {unmappedCount} no location{unmappedOnly ? ' · showing' : ''}
          </button>
        )}
        {/* Toolbar controls stay in the bar whether the grid is open OR collapsed (Chad: the
            collapsed bar must be identical). Only the TABLE below hides when collapsed; using any
            control auto-opens the grid so its effect is visible. */}
        {true && (
          <>
            {/* min-w so the box never shrinks to an icon (hiding a stray term that blanks the grid);
                a clear-× so leftover search text is always dismissable and highlighted when present. */}
            <div className="relative flex-1 max-w-xs min-w-[130px]">
              <Search size={13} className="absolute left-2 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
              <input
                value={q}
                onChange={(e) => { setQ(e.target.value); setOpen(true); }}
                onFocus={() => setOpen(true)}
                placeholder={view === 'loads' ? 'Search loads…' : 'Search table…'}
                className={'w-full border rounded pl-7 pr-6 py-1 text-xs focus:outline-none focus:ring-2 focus:ring-blue-200 focus:border-blue-400 ' + (q ? 'border-blue-400 bg-blue-50' : 'border-slate-300')}
              />
              {q && (
                <button onClick={() => setQ('')} title="Clear search" className="absolute right-1.5 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-700">
                  <X size={12} />
                </button>
              )}
            </div>
            {view === 'stops' && (
              <div className="relative">
                <button
                  onClick={() => { setStatusOpen((v) => !v); setOpen(true); }}
                  className={'inline-flex items-center gap-1 px-2 py-1 rounded text-xs border ' + (statusSel.size ? 'border-blue-400 text-blue-700 bg-blue-50' : 'border-slate-300 text-slate-600 hover:bg-slate-50')}
                >
                  <Filter size={12} /> Status{statusSel.size ? ` (${statusSel.size})` : ''}
                </button>
                {statusOpen && (
                  <div className="absolute right-0 bottom-full mb-1 w-40 bg-white border border-slate-200 rounded-lg shadow-lg z-20 p-1">
                    {TABLE_STATUS_BUCKETS.map((b) => (
                      <label key={b.k} className="flex items-center gap-2 px-2 py-1.5 text-xs hover:bg-slate-50 rounded cursor-pointer">
                        <input type="checkbox" checked={statusSel.has(b.k)} onChange={() => toggleStatus(b.k)} className="rounded border-slate-300" />
                        {b.label}
                      </label>
                    ))}
                    {statusSel.size > 0 && (
                      <button onClick={() => setStatusSel(new Set())} className="w-full text-left px-2 py-1.5 text-xs text-slate-500 hover:bg-slate-50 rounded border-t border-slate-100 mt-1">Clear</button>
                    )}
                  </div>
                )}
              </div>
            )}
            {/* NuVizz live pull (desktop): delivery-date window + driver, on the same
                top row as search. Window = Board uses today's loaded data (no calls);
                a NuVizz window pulls the stop list straight from NuVizz. */}
            {view === 'stops' && (
              <>
                <select
                  value={nvWindow}
                  onChange={(e) => { setNvWindow(e.target.value); setOpen(true); }}
                  title="Data source / delivery-date window"
                  className="hidden sm:inline-block border border-slate-300 rounded px-1.5 py-1 text-xs text-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-200 focus:border-blue-400"
                >
                  <option value="">Board (today)</option>
                  <option value="0d">NuVizz · Today</option>
                  <option value="+/-7d">NuVizz · ±7 days</option>
                  {/* Label kept SHORT on purpose: a <select> is as wide as its longest option,
                      and "· board day" was the widest string in this toolbar — it pushed the
                      Stops/Loads toggle and the driver filter off the end of the bar. The
                      behaviour is unchanged (both still track the board date backwards). */}
                  <option value="-7d">Last 7 days</option>
                  <option value="-14d">Last 14 days</option>
                  <option value="custom">Custom range…</option>
                </select>
                {nvWindow === 'custom' && (
                  <span className="hidden sm:inline-flex items-center gap-1">
                    <input
                      type="date" value={nvFrom} max={nvTo || undefined}
                      onChange={(e) => { setNvFrom(e.target.value); setOpen(true); }} title="From delivery date"
                      className="border border-slate-300 rounded px-1.5 py-1 text-xs text-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-200 focus:border-blue-400"
                    />
                    <span className="text-slate-400 text-xs">→</span>
                    <input
                      type="date" value={nvTo} min={nvFrom || undefined}
                      onChange={(e) => { setNvTo(e.target.value); setOpen(true); }} title="To delivery date"
                      className="border border-slate-300 rounded px-1.5 py-1 text-xs text-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-200 focus:border-blue-400"
                    />
                  </span>
                )}
                <select
                  value={driverSel}
                  onChange={(e) => { setDriverSel(e.target.value); setOpen(true); }}
                  title="Filter by driver"
                  className="hidden sm:inline-block shrink-0 border border-slate-300 rounded px-1.5 py-1 text-xs text-slate-700 max-w-[150px] focus:outline-none focus:ring-2 focus:ring-blue-200 focus:border-blue-400"
                >
                  <option value="">All drivers</option>
                  {driverOptions.map((d) => <option key={d} value={d}>{d}</option>)}
                </select>
                {nvWindow && (
                  <span className="hidden sm:inline text-[11px] text-slate-500 whitespace-nowrap">
                    {nvWindow === 'custom' && (!nvFrom || !nvTo)
                      ? <span className="text-slate-400">pick From + To dates</span>
                      : nvLoading
                        ? <span className="inline-flex items-center gap-1"><RefreshCw size={11} className="animate-spin" /> pulling…</span>
                        : nvErr
                          ? <span className="text-red-600">NuVizz: {nvErr}</span>
                          : nvPartial
                            ? <span className="text-amber-600" title="The date window was too large for one pull — some stops in it may be missing. Narrow the range for an exact result.">NuVizz · ≥{nvTotal.toLocaleString()} stops (partial — narrow the range)</span>
                            : nvSource === 'cache'
                              ? <span title="Served from our board cache (every scanned day in the window; confirmed Saves are patched in). Freshness = the last scan — no NuVizz calls.">Board · {nvTotal.toLocaleString()} stops</span>
                              : <>NuVizz · {nvTotal.toLocaleString()} stops</>}
                  </span>
                )}
              </>
            )}
          </>
        )}
        {headerRight && <div className="ml-auto">{headerRight}</div>}
      </div>
      {open && view === 'stops' && (
        <div className="overflow-auto flex-1 min-h-0">
          <table className="text-[11px] border-collapse mx-auto" style={{ minWidth: cols.reduce((a, c) => a + c.w, 0) }}>
            <thead className="sticky top-0 bg-slate-50 z-10">
              <tr>
                {cols.map((c) => (
                  <GridSortTh key={c.k} col={c} sort={stopSort} onToggle={toggleStopSort} />
                ))}
              </tr>
            </thead>
            <tbody>
              {sortedRows.length === 0 && (
                <tr><td colSpan={cols.length} className="px-3 py-5 text-center">
                  {nvLoading ? (
                    // STILL PULLING. The window pull can take seconds, and until it lands nvRows is
                    // empty — which used to render as the flat "No stops match.", i.e. the grid
                    // asserting an answer it did not have yet while the header right above it said
                    // "pulling…". An empty board mid-pull reads as a broken board.
                    <span className="text-slate-400 italic inline-flex items-center gap-1.5">
                      <RefreshCw size={12} className="animate-spin" /> Pulling this window…
                    </span>
                  ) : baseStops.length > 0 && activeFilterLabels.length ? (
                    // There ARE stops in this window/board — a filter is hiding them. Say which, and
                    // give a one-click clear (the invisible-search-term trap that blanked the grid).
                    <div className="text-xs text-slate-500 space-y-2">
                      <div>None of the <span className="font-semibold">{(nvWindow ? baseStops.length : (boardTotal ?? baseStops.length)).toLocaleString()}</span> stops in this {nvWindow ? 'window' : 'board'} match — hidden by {activeFilterLabels.join(', ')}.</div>
                      <button onClick={clearAllFilters} className="inline-flex items-center gap-1 px-2.5 py-1 rounded border border-blue-400 text-blue-700 bg-blue-50 hover:bg-blue-100 text-xs font-semibold">
                        <X size={12} /> Clear filters
                      </button>
                    </div>
                  ) : activeFilterLabels.length ? (
                    // ZERO CAME BACK **AND** A FILTER IS ON. The branch above counts what was
                    // fetched, so it can only fire for client-side filtering — but in window mode
                    // the STATUS filter rides the pull itself (statusCodes on the request), so a
                    // status with nothing in the window returns zero rows, baseStops is 0, and the
                    // count branch is skipped. That dropped the dispatcher onto a bare "No stops
                    // match." with the responsible filter unnamed and no way to clear it from here
                    // — exactly the silent-blank trap v0.45.6 closed, reopened via the server path.
                    <div className="text-xs text-slate-500 space-y-2">
                      <div>
                        Nothing came back for this {nvWindow ? 'window' : 'board'} — filtered by {activeFilterLabels.join(', ')}.
                        {statusSel.size ? <span className="block text-slate-400">The status filter is applied to the pull itself, so a status with no stops here returns an empty grid.</span> : null}
                      </div>
                      <button onClick={clearAllFilters} className="inline-flex items-center gap-1 px-2.5 py-1 rounded border border-blue-400 text-blue-700 bg-blue-50 hover:bg-blue-100 text-xs font-semibold">
                        <X size={12} /> Clear filters
                      </button>
                    </div>
                  ) : (
                    <span className="text-slate-400 italic">No stops match.</span>
                  )}
                </td></tr>
              )}
              {sortedRows.map((s) => (
                <tr
                  key={s.stopNbr}
                  onClick={() => onPick(s)}
                  // Selected-on-the-map rows highlight (Routing passes the live selection) so the
                  // grid and the selection tool read as one; selection tint wins over carry-over.
                  className={'cursor-pointer hover:bg-blue-50 ' + (highlightIds?.has(String(s.stopNbr)) ? 'bg-blue-100 hover:bg-blue-200/70' : s.carryover ? 'bg-amber-50/60' : '')}
                  title={s.carryover ? `Carry-over from ${s.scheduledDate}` : undefined}
                >
                  {cols.map((c) => (
                    // A `fit` column drops the max-width clamp (and with it the ellipsis), so the
                    // cell sizes to its content instead of being cut. Everything else keeps the
                    // clamp — a long address SHOULD ellipsize rather than shove the grid sideways.
                    <td key={c.k} className={'px-2 py-1 border-b border-slate-100 whitespace-nowrap' + (c.fit ? '' : ' overflow-hidden text-ellipsis')} style={{ maxWidth: c.fit ? undefined : c.w, textAlign: c.align || 'left' }}>{c.get(s)}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
      {open && view === 'loads' && (
        <div className="overflow-auto flex-1 min-h-0">
          <table className="text-[11px] border-collapse mx-auto" style={{ minWidth: loadCols.reduce((a, c) => a + c.w, 0) }}>
            <thead className="sticky top-0 bg-slate-50 z-10">
              <tr>
                {loadCols.map((c) => (
                  <GridSortTh key={c.k} col={c} sort={loadSort} onToggle={toggleLoadSort} />
                ))}
              </tr>
            </thead>
            <tbody>
              {sortedLoadRows.length === 0 && (
                <tr><td colSpan={loadCols.length} className="px-3 py-4 text-slate-400 italic text-center">No loads on the current board.</td></tr>
              )}
              {sortedLoadRows.map((g) => (
                <tr
                  key={g.loadNbr}
                  onClick={() => onPickLoad && onPickLoad(g.loadNbr)}
                  className="cursor-pointer hover:bg-blue-50"
                >
                  {loadCols.map((c) => (
                    // Same `fit` rule as the Stops table above, so the two grids can't drift.
                    <td key={c.k} className={'px-2 py-1 border-b border-slate-100 whitespace-nowrap' + (c.fit ? '' : ' overflow-hidden text-ellipsis')} style={{ maxWidth: c.fit ? undefined : c.w, textAlign: c.align || 'left' }}>{c.get(g)}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

function StopMiniTable({ stops, notes, onPick, columns, onColumnsChange, searchQuery = '', truncateNames = true }) {
  const cols = columns || DEFAULT_TABLE_COLUMNS;
  // Decorate rows with flag for sorting. _proSort puts empty PROs last for asc.
  const rows = useMemo(() => stops.map((s) => {
    const n = notes.get(s.matchKey);
    return {
      ...s,
      _flag: n?.priority_flag || 'none',
      _hasNote: !!n,
      _dnsNote: n?.do_not_send ? n : null,
      _priorityRank: n?.priority_flag === 'red' ? 0 : n?.priority_flag === 'yellow' ? 1 : n?.priority_flag === 'green' ? 2 : n?.priority_flag === 'question' ? 3 : 4,
      _proSort: s.primaryPro || s.pro || '￿',
    };
  }), [stops, notes]);
  const { sorted, sortKey, sortDir, toggle } = useSortable(rows, 'businessName', 'asc');
  // Horizontal scroll if columns exceed panel width.
  return (
    <div className="border-t">
      <div className="px-3 py-2 flex items-center justify-between">
        <div className="text-xs font-semibold text-slate-600">Stops ({rows.length})</div>
        {onColumnsChange && <ColumnsMenu columns={cols} onChange={onColumnsChange} />}
      </div>
      <div className="max-h-[40vh] overflow-y-auto overflow-x-auto">
        <table className="w-full text-xs">
          <thead className="bg-slate-50 sticky top-0">
            <tr>
              {cols.flag && <SortableTh label="Flag" k="_flag" sortKey={sortKey} sortDir={sortDir} onToggle={toggle} />}
              {cols.customer && <SortableTh label="Customer" k="businessName" sortKey={sortKey} sortDir={sortDir} onToggle={toggle} />}
              {cols.city && <SortableTh label="City" k="city" sortKey={sortKey} sortDir={sortDir} onToggle={toggle} />}
              {cols.pro && <SortableTh label="PRO" k="_proSort" sortKey={sortKey} sortDir={sortDir} onToggle={toggle} />}
              {cols.priority && <SortableTh label="Pri" k="_priorityRank" sortKey={sortKey} sortDir={sortDir} onToggle={toggle} />}
            </tr>
          </thead>
          <tbody>
            {sorted.map((s) => (
              <tr key={s.stopNbr} onClick={() => onPick(s)} className="cursor-pointer hover:bg-blue-50 border-t">
                {cols.flag && (
                  <td className="px-2 py-1">
                    <span className="inline-block w-2.5 h-2.5 rounded-full" style={{ background: s._flag !== 'none' ? FLAG_COLORS[s._flag] : (s._hasNote ? RESTRICTION_TINT : '#cbd5e1') }} />
                  </td>
                )}
                {cols.customer && (
                  <td
                    className={`px-2 py-1 ${truncateNames ? 'truncate max-w-[160px]' : ''}`}
                    title={s.businessName}
                    style={!truncateNames ? { maxWidth: 320 } : undefined}
                  >
                    <span className="inline-flex items-center gap-1.5">
                      <span className={truncateNames ? 'truncate' : ''}>{s.businessName}</span>
                      <DnsBadge note={s._dnsNote} />
                    </span>
                  </td>
                )}
                {cols.city && <td className="px-2 py-1 text-slate-600 whitespace-nowrap">{s.city}</td>}
                {cols.pro && (
                  <td className="px-2 py-1 font-mono text-[10px] text-slate-500 whitespace-nowrap">
                    {renderProCell(s, searchQuery)}
                  </td>
                )}
                {cols.priority && (
                  <td className="px-2 py-1 text-[10px] uppercase">
                    {s._flag !== 'none' ? (
                      <span style={{ color: FLAG_COLORS[s._flag] }} className="font-semibold">{s._flag.charAt(0)}</span>
                    ) : (s._hasNote ? <span className="text-purple-600 font-semibold">R</span> : <span className="text-slate-300">—</span>)}
                  </td>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

// ---------- M3 stub ----------

function DiagnosticsScreen({ stops, notes, ops, lastLoadScanAt, lastUnplannedScanAt, onRefresh, refreshing }) {
  const [scanning, setScanning] = useState(false);
  const scanNow = useCallback(async () => {
    setScanning(true);
    try {
      const r = await fetch(`${SCAN_NOW_URL}?manual=1`, { method: 'POST' });
      if (!r.ok && r.status !== 202) throw new Error('scan unavailable');
      // Background scan runs async — re-pull stats a couple times as results land.
      setTimeout(() => onRefresh?.(), 6000);
      setTimeout(() => onRefresh?.(), 16000);
    } catch { /* the stats refresh will reflect reality either way */ }
    finally { setTimeout(() => setScanning(false), 16000); }
  }, [onRefresh]);

  return (
    <div className="flex-1 min-h-0 overflow-y-auto p-3 sm:p-6 space-y-4 sm:space-y-6 max-w-4xl mx-auto w-full">
      <div>
        <h2 className="text-xl font-bold text-slate-900">Diagnostics</h2>
        <p className="text-sm text-slate-600 mt-1">NuVizz API usage and the live scan schedule. Schedule edits apply to the running scanner.</p>
      </div>

      <ApiCallsPanel ops={ops} lastLoadScanAt={lastLoadScanAt} lastUnplannedScanAt={lastUnplannedScanAt} onRefresh={onRefresh} refreshing={refreshing} onScanNow={scanNow} scanning={scanning} />
      <CaptureHealthPanel />
      <SchedulePanel onScanNow={scanNow} scanning={scanning} onSaved={onRefresh} />

      <details className="group">
        <summary className="cursor-pointer text-xs font-semibold text-slate-400 hover:text-slate-600 select-none">Data-quality checks (M3, in progress)</summary>
        <div className="space-y-4 sm:space-y-6 mt-3">
      <Panel title="Unmatched Stops Today">
        {/*
          TODO (M3-A):
          Walk through `stops` and surface rows that have NO matching customer_notes doc
          (notes.get(stop.matchKey) is undefined). Render as a sortable table with
          columns: business, address, PRO, count-today. Add a "Create notes" button per
          row that pre-fills the sidebar form (lift selectedStop state up if needed).
          This is the dispatcher's daily "what's new?" view.
        */}
        <Placeholder count={stops.filter((s) => !notes.get(s.matchKey)).length} hint="unmatched today" />
      </Panel>

      <Panel title="Stale Customers (90+ days)">
        {/*
          TODO (M3-B):
          Iterate notes and filter where last_updated (Firestore Timestamp) is older
          than 90 days. Render sortable table: customer, last_updated date, days-since.
          Add a "Review" button that opens the customer in the editor even if they
          don't appear in today's stops. Need to handle the "not on today's map" case —
          maybe a separate compact editor modal that doesn't depend on a selected stop.
        */}
        <Placeholder count={0} hint="stale customers" />
      </Panel>

      <Panel title="Address Line 2 Migration">
        {/*
          TODO (M3-C):
          Group today's stops by addr2 (non-empty), then for each unique addr2 string
          show: text, list of business names that use it, "Promote to Notes" action.
          Promotion = create or update customer_notes for each customer with the
          appropriate field set (e.g. addr2 says "Liftgate" → set liftgate_required=true).
          This is the cleanup pass to drain Chad's addr2 dumping ground into structured fields.
          Heuristic ideas: regex for "liftgate", "appt", "no tractor", "26ft", "ground only".
        */}
        <Placeholder count={stops.filter((s) => (s.addr2 || '').trim()).length} hint="addr2 fields populated today" />
      </Panel>
        </div>
      </details>
    </div>
  );
}

function Panel({ title, action, children }) {
  return (
    <section className="bg-white border border-slate-200 rounded-lg overflow-hidden">
      <div className="px-4 py-3 border-b bg-slate-50 flex items-center justify-between gap-2">
        <h3 className="font-semibold text-slate-900">{title}</h3>
        {action}
      </div>
      <div className="p-4">{children}</div>
    </section>
  );
}

function Placeholder({ count, hint }) {
  return (
    <div className="flex items-center gap-3 text-sm text-slate-500 italic">
      <Activity size={16} />
      <span>{count} {hint} · not implemented (see TODO)</span>
    </div>
  );
}

// Capture health — trailing-21-day view of the nightly history warehouse seal.
// Reads /.netlify/functions/history-capture-health (cheap: manifest list +
// failure list, no stop scans). Surfaces holes the moment they happen: a day
// whose stops captured but never sealed leaves a failure record (red), a
// scheduled weekday with nothing at all reads as missing (amber), weekends Davis
// doesn't run are idle (muted), and recovered days show as healed/tombstone.
const CAPTURE_HEALTH_URL = '/.netlify/functions/history-capture-health';

const CAPTURE_STATE_STYLE = {
  sealed: { tone: 'green', cell: 'bg-emerald-500', label: 'Sealed' },
  healed: { tone: 'green', cell: 'bg-teal-500', label: 'Healed' },
  tombstone: { tone: 'slate', cell: 'bg-slate-400', label: 'Tombstone (no board)' },
  failed: { tone: 'red', cell: 'bg-red-500', label: 'Did not seal' },
  missing: { tone: 'amber', cell: 'bg-amber-400', label: 'Missing (scheduled, absent)' },
  idle_weekend: { tone: 'slate', cell: 'bg-slate-200', label: 'Weekend (idle)' },
};

function CaptureHealthPanel() {
  const [data, setData] = useState(null);
  const [err, setErr] = useState('');
  const [loading, setLoading] = useState(true);

  const load = useCallback(() => {
    setLoading(true); setErr('');
    fetch(CAPTURE_HEALTH_URL, { cache: 'no-store' })
      .then((r) => r.json())
      .then((d) => { if (!d?.ok) throw new Error(d?.error || 'unavailable'); setData(d); })
      .catch((e) => setErr(String(e?.message || e)))
      .finally(() => setLoading(false));
  }, []);
  useEffect(() => { load(); }, [load]);

  const days = data?.days || [];
  const attention = days.filter((d) => d.state === 'failed' || d.state === 'missing');
  const recovered = days.filter((d) => d.state === 'healed' || d.state === 'tombstone');
  const s = data?.summary || {};

  return (
    <Panel
      title="Capture health"
      action={
        <button onClick={load} disabled={loading}
          className="text-[11px] font-semibold px-2 py-1 rounded border border-slate-300 text-slate-600 bg-white hover:bg-slate-50 disabled:opacity-50">
          {loading ? 'Loading…' : 'Refresh'}
        </button>
      }
    >
      {err && <div className="text-xs text-red-600">⚠ {err}</div>}
      {!err && !data && <div className="text-xs text-slate-500">Loading capture health…</div>}
      {data && (
        <div className="space-y-3">
          <div className="text-[11px] text-slate-500">
            Nightly warehouse seal · {data.window?.from ? `${engineDateFmt(data.window.from)} – ${engineDateFmt(data.window.to)}` : `${data.window?.days || 21} days`}
          </div>

          {/* one cell per day — a compact heatmap strip */}
          <div className="flex flex-wrap gap-1" role="img" aria-label="Capture seal state per day">
            {days.map((d) => {
              const st = CAPTURE_STATE_STYLE[d.state] || CAPTURE_STATE_STYLE.idle_weekend;
              const extra = d.detail?.stage ? ` · ${d.detail.stage}` : d.detail?.counts?.stops != null ? ` · ${d.detail.counts.stops} stops` : d.detail?.reason ? ` · ${d.detail.reason}` : '';
              return (
                <div key={d.date} title={`${engineDateFmt(d.date)} — ${st.label}${extra}`}
                  className={`h-5 w-5 rounded-sm ${st.cell}`} />
              );
            })}
          </div>

          {/* summary badges */}
          <div className="flex flex-wrap gap-1.5">
            {s.sealed ? <MiniBadge tone="green">{s.sealed} sealed</MiniBadge> : null}
            {s.healed ? <MiniBadge tone="green">{s.healed} healed</MiniBadge> : null}
            {s.tombstone ? <MiniBadge tone="slate">{s.tombstone} tombstone</MiniBadge> : null}
            {s.failed ? <MiniBadge tone="red">{s.failed} did not seal</MiniBadge> : null}
            {s.missing ? <MiniBadge tone="amber">{s.missing} missing</MiniBadge> : null}
            {s.idle_weekend ? <MiniBadge tone="slate">{s.idle_weekend} weekend</MiniBadge> : null}
          </div>

          {/* the holes that need attention */}
          {attention.length > 0 ? (
            <div className="space-y-1">
              {attention.map((d) => (
                <div key={d.date} className="flex items-start gap-2 text-[12px]">
                  <span className={`mt-1 h-2 w-2 rounded-full shrink-0 ${d.state === 'failed' ? 'bg-red-500' : 'bg-amber-400'}`} />
                  <span className="text-slate-700">
                    <span className="font-semibold">{engineDateFmt(d.date)}</span>
                    {' — '}
                    {d.state === 'failed'
                      ? <>did not seal{d.detail?.stage ? ` at ${d.detail.stage}` : ''}{d.detail?.error ? `: ${d.detail.error}` : ''}</>
                      : <>scheduled weekday with no capture</>}
                  </span>
                </div>
              ))}
            </div>
          ) : (
            <div className="text-[12px] text-emerald-700">No holes — every scheduled day in the window is sealed.</div>
          )}

          {recovered.length > 0 && (
            <div className="text-[11px] text-slate-500">
              Recovered: {recovered.map((d) => `${engineDateFmt(d.date)} (${d.state})`).join(' · ')}
            </div>
          )}
        </div>
      )}
    </Panel>
  );
}

// ============================================================================
// Diagnostics — NuVizz API-call analytics + live-editable scan schedule.
// Reads call volume from the pull endpoint (ops); reads/writes the schedule via
// /.netlify/functions/nuvizz-scan-config (persists to Firestore, scanner obeys it).
// ============================================================================
const SCAN_CONFIG_URL = '/.netlify/functions/nuvizz-scan-config';
const SCAN_NOW_URL = '/.netlify/functions/nuvizz-refresh-stops-background';

// Small pill badge with a few semantic tones.
function MiniBadge({ tone = 'slate', children }) {
  const tones = {
    slate: 'bg-slate-100 text-slate-600',
    green: 'bg-emerald-100 text-emerald-700',
    amber: 'bg-amber-100 text-amber-700',
    red: 'bg-red-100 text-red-700',
    violet: 'bg-violet-100 text-violet-700',
  };
  return <span className={`inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[11px] font-semibold ${tones[tone] || tones.slate}`}>{children}</span>;
}

function Stat({ label, value }) {
  return (
    <div className="rounded-md bg-slate-50 border border-slate-100 px-2.5 py-1.5">
      <div className="text-[10px] uppercase tracking-wide text-slate-400">{label}</div>
      <div className="text-sm font-semibold text-slate-800 tabular-nums">{typeof value === 'number' ? value.toLocaleString() : value}</div>
    </div>
  );
}

// 24-bar hourly call chart with axis ticks, peak marker, and per-bar tooltip.
function HourBarChart({ byHour }) {
  const hours = Array.from({ length: 24 }, (_, h) => String(h).padStart(2, '0'));
  const vals = hours.map((h) => (byHour && byHour[h]) || 0);
  const total = vals.reduce((a, b) => a + b, 0);
  if (!total) return <div className="text-sm text-slate-400 italic">No calls recorded yet today.</div>;
  const max = Math.max(...vals);
  const peak = vals.indexOf(max);
  return (
    <div>
      <div className="flex items-end gap-[3px] h-28" role="img" aria-label="NuVizz API calls per ET hour">
        {vals.map((v, h) => (
          <div key={h} className="flex-1 flex flex-col justify-end items-center group relative">
            <div
              className={`w-full rounded-t transition-colors ${v ? `${h === peak ? 'bg-violet-600' : 'bg-violet-400/70'} group-hover:bg-violet-700` : 'bg-slate-200'}`}
              style={{ height: `${v ? Math.max(3, Math.round((v / max) * 104)) : 2}px` }}
            />
            <div className="pointer-events-none absolute -top-7 hidden group-hover:block whitespace-nowrap rounded bg-slate-900 text-white text-[10px] px-1.5 py-0.5 z-10">
              {hours[h]}:00 · {v.toLocaleString()}
            </div>
          </div>
        ))}
      </div>
      <div className="flex justify-between text-[10px] text-slate-400 mt-1">
        <span>00</span><span>06</span><span>12</span><span>18</span><span>23</span>
      </div>
      <div className="text-[11px] text-slate-500 mt-1">Peak {hours[peak]}:00 ET · {max.toLocaleString()} calls · {total.toLocaleString()} total</div>
    </div>
  );
}

// Per-endpoint breakdown as labeled horizontal bars (sorted desc).
function RouteBars({ byRoute }) {
  const entries = Object.entries(byRoute || {}).sort((a, b) => b[1] - a[1]);
  if (!entries.length) return <div className="text-sm text-slate-400 italic">No per-endpoint data yet.</div>;
  const max = Math.max(...entries.map(([, v]) => v));
  return (
    <div className="space-y-1.5">
      {entries.map(([route, v]) => (
        <div key={route} className="flex items-center gap-2 text-xs">
          <div className="w-28 shrink-0 truncate text-slate-600 font-mono" title={route}>{route}</div>
          <div className="flex-1 bg-slate-100 rounded h-4 overflow-hidden">
            <div className="h-full bg-sky-400/80 rounded" style={{ width: `${Math.max(2, Math.round((v / max) * 100))}%` }} />
          </div>
          <div className="w-16 shrink-0 text-right tabular-nums text-slate-700 font-semibold">{v.toLocaleString()}</div>
        </div>
      ))}
    </div>
  );
}

// Generic labeled horizontal-bar breakdown (by app / by trigger), sorted desc. Same
// shape as RouteBars but with a configurable bar color and a wider label column so
// "scheduled-scan" / "dispatch-map" read cleanly.
function LabelBars({ data, color = 'bg-violet-400/80' }) {
  const entries = Object.entries(data || {}).sort((a, b) => b[1] - a[1]);
  if (!entries.length) return <div className="text-sm text-slate-400 italic">No data yet.</div>;
  const max = Math.max(...entries.map(([, v]) => v));
  return (
    <div className="space-y-1.5">
      {entries.map(([label, v]) => (
        <div key={label} className="flex items-center gap-2 text-xs">
          <div className="w-32 shrink-0 truncate text-slate-600" title={label}>{label}</div>
          <div className="flex-1 bg-slate-100 rounded h-4 overflow-hidden">
            <div className={`h-full ${color} rounded`} style={{ width: `${Math.max(2, Math.round((v / max) * 100))}%` }} />
          </div>
          <div className="w-16 shrink-0 text-right tabular-nums text-slate-700 font-semibold">{v.toLocaleString()}</div>
        </div>
      ))}
    </div>
  );
}

function ApiCallsPanel({ ops, lastLoadScanAt, lastUnplannedScanAt, onRefresh, refreshing, onScanNow, scanning }) {
  const headerBtns = (
    <div className="flex items-center gap-2">
      <button onClick={onScanNow} disabled={scanning}
        className="inline-flex items-center gap-1 rounded-md border border-slate-300 px-2 py-1 text-xs font-medium text-slate-700 hover:bg-slate-50 disabled:opacity-50 whitespace-nowrap">
        <RefreshCw size={12} className={scanning ? 'animate-spin' : ''} /> Scan now
      </button>
      <button onClick={onRefresh} disabled={refreshing} aria-label="Refresh stats"
        className="inline-flex items-center gap-1 rounded-md border border-slate-300 px-2 py-1 text-xs font-medium text-slate-700 hover:bg-slate-50 disabled:opacity-50">
        <RefreshCw size={12} className={refreshing ? 'animate-spin' : ''} /> Refresh
      </button>
    </div>
  );
  if (!ops) {
    return (
      <Panel title="NuVizz API Calls (today)" action={headerBtns}>
        <div className="text-sm text-slate-400 italic">No call data available (Firestore off, or no scans yet today).</div>
      </Panel>
    );
  }
  const used = ops.dayCount || 0;
  const ceiling = ops.ceiling || 0;
  const pct = ceiling ? Math.min(100, Math.round((used / ceiling) * 100)) : 0;
  const tone = pct >= 85 ? 'red' : pct >= 60 ? 'amber' : 'green';
  const barColor = pct >= 85 ? 'bg-red-500' : pct >= 60 ? 'bg-amber-500' : 'bg-emerald-500';
  const learn = ops.scanLearning || {};
  return (
    <Panel title="NuVizz API Calls (today)" action={headerBtns}>
      <div className="space-y-4">
        <div>
          <div className="flex items-end justify-between mb-1 flex-wrap gap-1">
            <div className="flex items-baseline gap-2">
              <span className="text-2xl font-bold text-slate-900 tabular-nums">{used.toLocaleString()}</span>
              <span className="text-sm text-slate-500">/ {ceiling.toLocaleString()} calls</span>
            </div>
            <div className="flex items-center gap-1.5">
              <MiniBadge tone={ops.mode === 'enforce' ? 'violet' : 'slate'}><Gauge size={11} /> {ops.mode}</MiniBadge>
              {ops.breaker
                ? <MiniBadge tone="red"><Ban size={11} /> halted</MiniBadge>
                : <MiniBadge tone={tone}>{pct}% of cap</MiniBadge>}
            </div>
          </div>
          <div className="h-2.5 w-full bg-slate-100 rounded-full overflow-hidden">
            <div className={`h-full ${barColor} rounded-full transition-all`} style={{ width: `${pct}%` }} />
          </div>
        </div>

        <div>
          <div className="text-xs font-semibold text-slate-500 uppercase tracking-wide mb-2 flex items-center gap-1"><Clock size={12} /> Calls by hour (ET)</div>
          <HourBarChart byHour={ops.byHour} />
        </div>

        <div>
          <div className="text-xs font-semibold text-slate-500 uppercase tracking-wide mb-2">By endpoint</div>
          <RouteBars byRoute={ops.byRoute} />
        </div>

        {ops.byTrigger && Object.keys(ops.byTrigger).length > 0 && (
          <div>
            <div className="text-xs font-semibold text-slate-500 uppercase tracking-wide mb-2">By trigger (why)</div>
            <LabelBars data={ops.byTrigger} color="bg-violet-400/80" />
          </div>
        )}

        {ops.byApp && Object.keys(ops.byApp).length > 0 && (
          <div>
            <div className="text-xs font-semibold text-slate-500 uppercase tracking-wide mb-2">By app</div>
            <LabelBars data={ops.byApp} color="bg-emerald-400/80" />
          </div>
        )}

        <div>
          <div className="text-xs font-semibold text-slate-500 uppercase tracking-wide mb-2">Scanner learning</div>
          <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
            <Stat label="Recent scans" value={learn.scans ?? '—'} />
            <Stat label="Loads found / scan" value={learn.lastFoundLoads ?? '—'} />
            <Stat label="Max ID gap" value={learn.maxGap ?? '—'} />
            <Stat label="Rec. empty-stop" value={learn.recommendedEmptyStop ?? '—'} />
            <Stat label="New loads/day (max)" value={learn.maxNewLoads ?? '—'} />
            <Stat label="Missed scans" value={learn.missedScans ?? '—'} />
          </div>
        </div>

        <div className="text-[11px] text-slate-400 flex flex-wrap gap-x-4 gap-y-1 pt-1 border-t">
          <span title={fmtAbsoluteET(lastLoadScanAt)}>Loads scanned {fmtFeedAge(lastLoadScanAt) || '—'}</span>
          <span title={fmtAbsoluteET(lastUnplannedScanAt)}>Orders scanned {fmtFeedAge(lastUnplannedScanAt) || '—'}</span>
        </div>
      </div>
    </Panel>
  );
}

// One numeric field bound to the schedule form, with bounds + default hint and an
// "edited" highlight when the value differs from the site default.
function NumberField({ label, hint, value, def, bound, unit, onChange }) {
  const [lo, hi] = bound || [0, 9999];
  const overridden = def != null && Number(value) !== Number(def);
  return (
    <label className="block">
      <div className="flex items-center justify-between">
        <span className="text-xs font-medium text-slate-700">{label}</span>
        {overridden && <span className="text-[10px] text-violet-600 font-semibold">edited</span>}
      </div>
      <div className="mt-1 flex items-center gap-1.5">
        <input
          type="number" min={lo} max={hi} value={value}
          onChange={(e) => onChange(e.target.value === '' ? '' : Number(e.target.value))}
          className={`w-full rounded-md border px-2 py-1 text-sm tabular-nums focus:outline-none focus:ring-2 focus:ring-sky-300 ${overridden ? 'border-violet-300 bg-violet-50/40' : 'border-slate-300'}`}
        />
        {unit && <span className="text-xs text-slate-400 shrink-0">{unit}</span>}
      </div>
      {hint && <div className="text-[10px] text-slate-400 mt-0.5">{hint}{def != null ? ` · default ${def}` : ''}</div>}
    </label>
  );
}

function SwitchToggle({ checked, onChange, label, hint }) {
  return (
    <div className="flex items-center justify-between gap-3 rounded-md border border-slate-200 px-3 py-2">
      <div>
        <div className="text-sm font-medium text-slate-800">{label}</div>
        {hint && <div className="text-[11px] text-slate-400">{hint}</div>}
      </div>
      <button
        role="switch" aria-checked={checked} aria-label={label}
        onClick={() => onChange(!checked)}
        className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors ${checked ? 'bg-emerald-500' : 'bg-slate-300'}`}
      >
        <span className={`inline-block h-5 w-5 transform rounded-full bg-white shadow transition-transform ${checked ? 'translate-x-5' : 'translate-x-0.5'}`} />
      </button>
    </div>
  );
}

function SchedSection({ icon, title, desc, children }) {
  return (
    <div>
      <div className="text-xs font-semibold text-slate-600 uppercase tracking-wide flex items-center gap-1">{icon} {title}</div>
      {desc && <div className="text-[11px] text-slate-400 mt-0.5 mb-2">{desc}</div>}
      {children}
    </div>
  );
}

// Rough daily-scan-count estimate from the cadence form, so the cost impact of an
// edit is visible before saving.
function EstimateLine({ form }) {
  const dayStart = Number(form.dayBandStartHour), dayEnd = Number(form.dayBandEndHour);
  const dayHours = Math.max(0, dayEnd - dayStart);
  const nightHours = Math.max(0, 24 - dayHours);
  const dayScans = Number(form.intervalDayMin) > 0 ? (dayHours * 60) / Number(form.intervalDayMin) : 0;
  const nightScans = Number(form.intervalNightMin) > 0 ? (nightHours * 60) / Number(form.intervalNightMin) : 0;
  const total = Math.round(dayScans + nightScans);
  if (!Number.isFinite(total) || total <= 0) return null;
  return <div className="text-[11px] text-slate-500 mt-2">≈ <span className="font-semibold">{total}</span> scans/day at this cadence (weekday, outside blackout).</div>;
}

function SchedulePanel({ onScanNow, scanning, onSaved }) {
  const [data, setData] = useState(null);
  const [form, setForm] = useState(null);
  const [status, setStatus] = useState('loading'); // loading|ready|saving|saved|error
  const [err, setErr] = useState(null);

  const load = useCallback(async () => {
    setStatus('loading'); setErr(null);
    try {
      const r = await fetch(SCAN_CONFIG_URL, { cache: 'no-store' });
      const j = await r.json();
      if (!j.ok) throw new Error(j.error || 'load failed');
      setData(j); setForm({ ...j.config }); setStatus('ready');
    } catch (e) { setErr(e.message); setStatus('error'); }
  }, []);
  useEffect(() => { load(); }, [load]);

  if (status === 'loading' || !form) {
    return <Panel title="Scan Schedule"><div className="text-sm text-slate-400 italic flex items-center gap-2"><RefreshCw size={14} className="animate-spin" /> Loading schedule…</div></Panel>;
  }
  if (status === 'error' && !data) {
    return <Panel title="Scan Schedule"><div className="text-sm text-red-600 flex items-center gap-2"><AlertTriangle size={14} /> Couldn't load schedule: {err}</div></Panel>;
  }

  const { defaults, bounds, persistent, stored } = data;
  const set = (k) => (v) => setForm((f) => ({ ...f, [k]: v }));
  const dirty = JSON.stringify(form) !== JSON.stringify(data.config);

  const save = async (override) => {
    setStatus('saving'); setErr(null);
    try {
      const payload = override || form;
      const r = await fetch(SCAN_CONFIG_URL, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
      const j = await r.json();
      if (!j.ok) throw new Error(j.error || 'save failed');
      setData(j); setForm({ ...j.config }); setStatus('saved');
      onSaved?.(); // refetch the top API-calls panel so a changed ceiling shows immediately
      setTimeout(() => setStatus('ready'), 2500);
    } catch (e) { setErr(e.message); setStatus('error'); }
  };
  const resetDefaults = () => { setForm({ ...defaults }); save({ ...defaults }); };

  const action = (
    <div className="flex items-center gap-2">
      {!persistent && <MiniBadge tone="amber"><AlertTriangle size={11} /> read-only</MiniBadge>}
      {status === 'saved' && <MiniBadge tone="green">saved</MiniBadge>}
      <button onClick={onScanNow} disabled={scanning}
        className="inline-flex items-center gap-1 rounded-md border border-slate-300 px-2 py-1 text-xs font-medium text-slate-700 hover:bg-slate-50 disabled:opacity-50 whitespace-nowrap">
        <RefreshCw size={12} className={scanning ? 'animate-spin' : ''} /> Scan now
      </button>
    </div>
  );

  return (
    <Panel title="Scan Schedule" action={action}>
      <div className="space-y-5">
        <SwitchToggle
          label="Scheduled scans enabled"
          hint="Master switch — off pauses automatic scanning (Scan now still works)."
          checked={form.scansEnabled !== false}
          onChange={set('scansEnabled')}
        />

        <SchedSection icon={<Clock size={12} />} title="Cadence" desc="How often the scanner runs, by ET time of day.">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <NumberField label="Day interval" hint="between scans, day band" unit="min" value={form.intervalDayMin} def={defaults.intervalDayMin} bound={bounds.intervalDayMin} onChange={set('intervalDayMin')} />
            <NumberField label="Night interval" hint="between scans, overnight" unit="min" value={form.intervalNightMin} def={defaults.intervalNightMin} bound={bounds.intervalNightMin} onChange={set('intervalNightMin')} />
            <NumberField label="Day band start" hint="ET hour faster cadence begins" unit="h ET" value={form.dayBandStartHour} def={defaults.dayBandStartHour} bound={bounds.dayBandStartHour} onChange={set('dayBandStartHour')} />
            <NumberField label="Day band end" hint="ET hour it ends (exclusive)" unit="h ET" value={form.dayBandEndHour} def={defaults.dayBandEndHour} bound={bounds.dayBandEndHour} onChange={set('dayBandEndHour')} />
          </div>
          <EstimateLine form={form} />
        </SchedSection>

        <SchedSection icon={<Gauge size={12} />} title="Spend cap" desc="Daily NuVizz call ceiling — the breaker threshold and the gauge up top.">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <NumberField label="Daily ceiling" hint="max calls per day" unit="calls" value={form.dailyCeiling} def={defaults.dailyCeiling} bound={bounds.dailyCeiling} onChange={set('dailyCeiling')} />
          </div>
        </SchedSection>

        <SchedSection icon={<Clock size={12} />} title="Deep sweep" desc="The once-a-day full reconciliation, held off the 10am open to avoid a spike.">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <NumberField label="Min hours between" hint="how often a full sweep may run" unit="h" value={form.deepSweepHours} def={defaults.deepSweepHours} bound={bounds.deepSweepHours} onChange={set('deepSweepHours')} />
            <NumberField label="Earliest hour" hint="off-peak ET hour it's allowed" unit="h ET" value={form.deepSweepHour} def={defaults.deepSweepHour} bound={bounds.deepSweepHour} onChange={set('deepSweepHour')} />
          </div>
        </SchedSection>

        <SchedSection icon={<Settings size={12} />} title="Windows" desc="Overnight routing window (thorough vs lean discovery) and the weekend blackout.">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <NumberField label="Routing window start" hint="overnight window opens" unit="h ET" value={form.routingWindowStart} def={defaults.routingWindowStart} bound={bounds.routingWindowStart} onChange={set('routingWindowStart')} />
            <NumberField label="Routing window end" hint="window closes (wraps midnight)" unit="h ET" value={form.routingWindowEnd} def={defaults.routingWindowEnd} bound={bounds.routingWindowEnd} onChange={set('routingWindowEnd')} />
            <NumberField label="Weekend blackout start" hint="Friday scans stop" unit="h ET" value={form.weekendBlackoutStart} def={defaults.weekendBlackoutStart} bound={bounds.weekendBlackoutStart} onChange={set('weekendBlackoutStart')} />
            <NumberField label="Weekend blackout end" hint="Sunday scans resume" unit="h ET" value={form.weekendBlackoutEnd} def={defaults.weekendBlackoutEnd} bound={bounds.weekendBlackoutEnd} onChange={set('weekendBlackoutEnd')} />
          </div>
        </SchedSection>

        {err && <div className="text-sm text-red-600 flex items-center gap-1"><AlertTriangle size={14} /> {err}</div>}

        <div className="flex items-center justify-between gap-2 pt-1 border-t">
          <button onClick={resetDefaults} disabled={!persistent || status === 'saving'}
            className="text-xs text-slate-500 hover:text-slate-700 underline disabled:opacity-50">Reset to defaults</button>
          <div className="flex items-center gap-2">
            {stored?.updatedAt && <span className="text-[10px] text-slate-400">edited {fmtFeedAge(stored.updatedAt) || ''}</span>}
            <button onClick={() => save()} disabled={!persistent || !dirty || status === 'saving'}
              className="inline-flex items-center gap-1.5 rounded-md bg-sky-600 px-3 py-1.5 text-sm font-semibold text-white hover:bg-sky-700 disabled:opacity-40 disabled:cursor-not-allowed">
              <Save size={14} /> {status === 'saving' ? 'Saving…' : 'Save schedule'}
            </button>
          </div>
        </div>
        <p className="text-[11px] text-slate-400">Saved changes take effect on the next scheduled scan (~15 min). Out-of-range values are clamped to safe limits automatically.</p>
      </div>
    </Panel>
  );
}

// ============================================================================
// Phase 2 (PR 2/2) — Routing (beta) tab. Inline per the single-file rule.
// CHEAP BY DEFAULT (Appendix B): builds run free haversine unless the dispatcher
// explicitly opts into Google live drive-times, and the per-build cost is shown.
// Wires to the merged engine via the routing_jobs job-doc lifecycle; renders
// exactly what the engine returns (no client-side feasibility/sequencing).
// ============================================================================

// Feature flag — Chad turned the Routing (beta) tab ON for all dispatchers
// (v0.14.2). It is now VISIBLE BY DEFAULT. A kill switch remains so it can be
// hidden again without a revert: set env VITE_ROUTING_BETA='false', or append
// ?routing=0 to the URL. Cheap-by-default still holds (free estimate unless the
// Google toggle is used), so exposing it carries no automatic cost.
const ROUTING_FLAG = (() => {
  try {
    if (import.meta.env.VITE_ROUTING_BETA === 'false') return false;
    if (typeof window !== 'undefined' && /[?&]routing=0\b/.test(window.location.search)) return false;
  } catch { /* ignore */ }
  return true;
})();

// Live-write (beta) gate — the routes-panel driver-assign + dispatch UI. UNLIKE the
// routing beta this defaults OFF (live writes are opt-in): enable with env
// VITE_NUVIZZ_WRITE_BETA='true', or force per-session with ?write=1 (?write=0 hides it).
// Even when the UI is shown, no real NuVizz write fires unless the dispatcher flips the
// card's Beta→Live toggle AND the server-side NUVIZZ_WRITE_ENABLED flag is set.
const LIVE_WRITE_FLAG = (() => {
  try {
    if (typeof window !== 'undefined' && /[?&]write=1\b/.test(window.location.search)) return true;
    if (typeof window !== 'undefined' && /[?&]write=0\b/.test(window.location.search)) return false;
    if (import.meta.env.VITE_NUVIZZ_WRITE_BETA === 'true') return true;
  } catch { /* ignore */ }
  return false;
})();

const ROUTING_DEPOT = { name: 'Buford Terminal', lat: 34.14838, lng: -83.95948 };
const ROUTING_STRATEGIES = [
  ['MIN_DISTANCE', 'Min distance'],
  ['MIN_TIME', 'Min time'],
  ['CLOSEST_FIRST', 'Closest first'],
  ['FARTHEST_FIRST', 'Farthest first'],
];
const ROUTING_MAX_SELECTION = 150; // matrix cost is quadratic (Appendix B)
const BASIC_RATE_PER_1K_USD = 5.0; // mirror of routing-types BASIC_MATRIX_RATE (display only)

// Client-side mirror of the server seed profiles (truck-profiles.mts). Used only
// to seed the truck_profiles collection on first run; the server remains the
// source of truth for a build (it reads truck_profiles by id).
const CLIENT_DEFAULT_TRUCKS = [
  { id: 'box_26', label: '26ft Box', truckClass: 'BOX_26', maxSkids: 14, maxWeightLbs: 10000, deckLengthIn: 312, deckWidthIn: 96, capabilities: { liftgate: true, tractor: false, lengthClassFt: 26, overheadClearance: true }, active: true },
  { id: 'tractor_53', label: '53ft Trailer', truckClass: 'TRACTOR_53', maxSkids: 28, maxWeightLbs: 44000, deckLengthIn: 636, deckWidthIn: 100, capabilities: { liftgate: false, tractor: true, lengthClassFt: 53, overheadClearance: true }, active: true },
];

// ETAs are epoch-seconds anchored to the planning clock (date + depart in UTC),
// so format in UTC to show the intended wall-clock time (e.g. 8:00 AM depart).
function formatRoutingEta(sec) {
  if (sec == null || !Number.isFinite(sec)) return '—';
  return new Date(sec * 1000).toLocaleTimeString('en-US', { timeZone: 'UTC', hour: 'numeric', minute: '2-digit' });
}

// A selected stop "looks oversize" for the live tally if any line item is NuVizz
// category L. (The authoritative geometry is computed server-side at build time.)
function stopLooksOversize(s) {
  return Array.isArray(s?.stopDetails) && s.stopDetails.some((d) => String(d?.productCategory || '').toUpperCase() === 'L');
}

/**
 * Bottom-panel PROFILES, shared across every device (Chad, 7/27: "they shouldn't be
 * local to the device, should be across all devices").
 *
 * Firestore `bottom_panel_profiles`, one doc per profile keyed by a slug of its name —
 * not one doc holding the whole list, so two dispatchers saving different profiles at
 * the same moment can't clobber each other's write.
 *
 * What syncs and what doesn't: the LIST is shared, the ACTIVE selection is not. Which
 * profile you're currently looking through is your own view of the board — if picking
 * "Tomorrow AM" here yanked the other dispatcher's grid out from under them mid-plan,
 * that's a worse bug than the one being fixed. So `active` stays in localStorage.
 *
 * Fail-soft: with Firestore unavailable (db null, offline, rules) this behaves exactly
 * as the old localStorage version did, and a device that saved while offline migrates
 * its profiles up the next time it connects.
 */
const LS_BOTTOM_PROFILES_ACTIVE = 'dispatchMap.bottomPanelProfiles.active';
const LS_BOTTOM_PROFILES_MIGRATED = 'dispatchMap.bottomPanelProfiles.migrated';
const profileDocId = (name) => String(name).trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 120) || 'profile';

function useBottomPanelProfiles() {
  // Seed from localStorage so the bar renders instantly (and still works with no db).
  const [list, setList] = useState(() => {
    const p = safeReadJSON(LS_BOTTOM_PROFILES, null);
    return (p && Array.isArray(p.list)) ? p.list : [];
  });
  const [active, setActiveState] = useState(() => {
    const a = safeReadJSON(LS_BOTTOM_PROFILES_ACTIVE, null);
    if (typeof a === 'string') return a;
    const legacy = safeReadJSON(LS_BOTTOM_PROFILES, null);   // pre-sync shape carried it inline
    return (legacy && typeof legacy.active === 'string') ? legacy.active : null;
  });
  const setActive = useCallback((name) => {
    setActiveState(name);
    safeWriteJSON(LS_BOTTOM_PROFILES_ACTIVE, name);
  }, []);

  useEffect(() => {
    if (!db) return;
    const unsub = onSnapshot(collection(db, 'bottom_panel_profiles'), async (snap) => {
      const remote = snap.docs
        .map((d) => ({ name: d.data()?.name || d.id, s: d.data()?.s || null }))
        .filter((p) => p.s)
        .sort((a, b) => a.name.localeCompare(b.name));
      // ONE-TIME migration of whatever this device saved before profiles were shared.
      // Guarded by a local flag so a profile someone deletes on another device doesn't
      // get resurrected every time this browser reconnects.
      if (!safeReadJSON(LS_BOTTOM_PROFILES_MIGRATED, false)) {
        const localOnly = (safeReadJSON(LS_BOTTOM_PROFILES, null)?.list || [])
          .filter((p) => p?.name && p?.s && !remote.some((r) => r.name === p.name));
        safeWriteJSON(LS_BOTTOM_PROFILES_MIGRATED, true);
        if (localOnly.length) {
          try {
            await Promise.all(localOnly.map((p) => setDoc(doc(db, 'bottom_panel_profiles', profileDocId(p.name)), { name: p.name, s: p.s, updated_at: serverTimestamp() })));
          } catch { /* the snapshot below still shows what IS shared */ }
          return;   // the write re-fires this listener with the merged set
        }
      }
      setList(remote);
      safeWriteJSON(LS_BOTTOM_PROFILES, { list: remote });   // offline cache for next cold start
    }, () => { /* rules/offline: keep the localStorage list already in state */ });
    return () => unsub();
  }, []);

  const saveProfile = useCallback(async (name, s) => {
    const prof = { name, s };
    setList((v) => [...v.filter((x) => x.name !== name), prof].sort((a, b) => a.name.localeCompare(b.name)));
    if (!db) { safeWriteJSON(LS_BOTTOM_PROFILES, { list: [...(safeReadJSON(LS_BOTTOM_PROFILES, null)?.list || []).filter((x) => x.name !== name), prof] }); return; }
    try { await setDoc(doc(db, 'bottom_panel_profiles', profileDocId(name)), { name, s, updated_at: serverTimestamp() }); } catch { /* optimistic row stands */ }
  }, []);

  const removeProfile = useCallback(async (name) => {
    setList((v) => v.filter((p) => p.name !== name));
    setActiveState((a) => (a === name ? null : a));
    if (!db) { safeWriteJSON(LS_BOTTOM_PROFILES, { list: (safeReadJSON(LS_BOTTOM_PROFILES, null)?.list || []).filter((x) => x.name !== name) }); return; }
    try { await deleteDoc(doc(db, 'bottom_panel_profiles', profileDocId(name))); } catch { /* optimistic removal stands */ }
  }, []);

  return { list, active, setActive, saveProfile, removeProfile, shared: !!db };
}

// Live truck_profiles, seeded on first run. Returns profiles + a persist helper.
function useTruckProfiles() {
  const [profiles, setProfiles] = useState([]);
  const [ready, setReady] = useState(false);
  useEffect(() => {
    if (!db) { setReady(true); return; }
    const unsub = onSnapshot(collection(db, 'truck_profiles'), async (snap) => {
      if (snap.empty) {
        // Seed defaults once; the snapshot will re-fire with them.
        try { await Promise.all(CLIENT_DEFAULT_TRUCKS.map((p) => setDoc(doc(db, 'truck_profiles', p.id), p))); } catch { /* ignore */ }
        return;
      }
      setProfiles(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
      setReady(true);
    }, () => setReady(true));
    return () => unsub();
  }, []);
  const saveProfile = useCallback(async (p) => {
    if (!db) return;
    await setDoc(doc(db, 'truck_profiles', p.id), p, { merge: true });
  }, []);
  return { profiles, ready, saveProfile };
}

// Shared, live-synced saved loads. Subscribes to routing_routes (created_at desc)
// so a save/rename/delete/dispatch on ANY device shows here within seconds, no
// refresh. Clean teardown on unmount. Surfaces loading + error explicitly (never
// a silent catch). Each load carries its own `result` (the saved plan).
function useSavedLoads() {
  const [loads, setLoads] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  useEffect(() => {
    if (!db) { setLoading(false); setError('Firestore not configured'); return; }
    let active = true;
    const q = query(collection(db, 'routing_routes'), orderBy('created_at', 'desc'));
    const unsub = onSnapshot(q, (snap) => {
      if (!active) return;
      setLoads(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
      setLoading(false);
      setError(null);
    }, (err) => {
      if (!active) return;
      console.error('routing_routes snapshot error', err);
      setError(err?.message || 'failed to load saved loads');
      setLoading(false);
    });
    return () => { active = false; unsub(); };
  }, []);
  return { loads, loading, error };
}

// Load-vs-capacity bar (one dimension). Amber ≥90%, red >100% (shouldn't happen).
function CapacityBar({ label, used, cap, unit }) {
  const pct = cap > 0 ? Math.min(100, Math.round((used / cap) * 100)) : 0;
  const over = used > cap;
  const tight = !over && used > cap * 0.9;
  const color = over ? '#dc2626' : tight ? '#f59e0b' : '#16a34a';
  return (
    <div className="text-[11px]">
      <div className="flex justify-between text-slate-600">
        <span>{label}</span>
        <span>{Math.round(used).toLocaleString()} / {Math.round(cap).toLocaleString()} {unit}</span>
      </div>
      <div className="h-1.5 bg-slate-200 rounded overflow-hidden">
        <div style={{ width: `${pct}%`, background: color }} className="h-full" />
      </div>
    </div>
  );
}

// Drill-in detail for one selected stop. Reuses the parent app's customer_notes
// helpers (getRestrictionBadgeKeys / RESTRICTION_ICONS / formatReceivingHours)
// so a routing stop shows the SAME intelligence as the map markers, plus the
// per-line products from stopDetails[]. Degrades cleanly: a stop with no note
// shows no false flags, and an empty stopDetails[] shows "No line items".
// A stop's PRO / order number as a clickable link that opens the detail popup.
// Falls back to plain text when there's no opener (e.g. inside the popup itself)
// or no number. Never a dead link.
function ProLink({ stop, onOpen, className = '' }) {
  const pro = stop?.pro || stop?.stopNbr || stop?.primaryPro || null;
  if (!pro) return null;
  if (!onOpen) return <span className={className}>#{pro}</span>;
  return (
    <button onClick={(e) => { e.stopPropagation(); onOpen(stop); }} className={`text-blue-700 underline hover:text-blue-900 ${className}`} title="Open stop details">#{pro}</button>
  );
}

// Appointment window label from a stop's scheduled times, e.g. "8:00a–8:05a".
function apptWindowLabel(stop) {
  const from = stop?.scheduledFrom, to = stop?.scheduledTo;
  if (!from && !to) return null;
  return `${from ? fmtTime12(from) : '?'}–${to ? fmtTime12(to) : '?'}`;
}

function RoutingStopDetail({ stop, note, onOpen, windowViolated, onMoveLocation, onEditAddress, onAutoFixAddress }) {
  const keys = getRestrictionBadgeKeys(note);
  const oversize = stopLooksOversize(stop);
  const hoursStr = formatReceivingHours(note);
  const lines = Array.isArray(stop.stopDetails) ? stop.stopDetails : [];
  // Prefer a saved address_override (same as the Map card), so a corrected address
  // shows here too — with a "corrected" chip. Falls back to the raw NuVizz address.
  const aAddr1 = note?.address_override?.addr1 || stop.addr1;
  const aCity = note?.address_override?.city ?? stop.city;
  const aState = note?.address_override?.state ?? stop.state;
  const aZip = note?.address_override?.zip ?? stop.zip;
  const addr = [aAddr1, [aCity, aState].filter(Boolean).join(', '), aZip].filter(Boolean).join(' · ');
  const contact = (stop.contact && (stop.contact.name || stop.contact.phone)) ? stop.contact
    : (note?.contacts && note.contacts[0]) || null;
  const Cap = ({ children }) => <div className="text-[9px] uppercase font-semibold text-slate-500 tracking-wide">{children}</div>;
  const pro = stop.pro || stop.stopNbr || stop.primaryPro || null;
  return (
    <div className="rounded bg-slate-50 border border-slate-200 p-2 space-y-1.5 text-[11px]">
      <div className="flex gap-6 flex-wrap">
        <div><Cap>Order / PRO</Cap><div className="text-slate-800"><ProLink stop={stop} onOpen={onOpen} className="font-medium" /> {!pro && '—'}</div></div>
        {stop.loadNbr && <div><Cap>Load</Cap><div className="text-slate-800">{stop.loadNbr}</div></div>}
        {stop.bol && <div><Cap>BOL</Cap><div className="text-slate-800">{stop.bol}</div></div>}
        {stop.customerAccount && <div><Cap>Account</Cap><div className="text-slate-800">{stop.customerAccount}</div></div>}
      </div>
      <div><Cap>Business</Cap><div className="text-slate-800 font-medium">{stop.businessName || '—'}</div></div>
      <div>
        <Cap>Address {note?.address_override && <span className="px-1 rounded bg-blue-100 text-blue-700 text-[8px] font-semibold normal-case align-middle">corrected</span>}</Cap>
        <div className="text-slate-800">{addr || '—'}</div>
        {onAutoFixAddress && onEditAddress && <AddressFixBanner stop={stop} note={note} onAutoFix={onAutoFixAddress} onEdit={onEditAddress} />}
        {(onEditAddress || onMoveLocation) && (
          <div className="flex items-center gap-x-4 gap-y-1 flex-wrap mt-1">
            {onEditAddress && (
              <button onClick={() => onEditAddress(stop)} className="inline-flex items-center gap-1 text-[11px] text-blue-700 hover:underline">
                <MapPin size={12} /> Edit address
              </button>
            )}
            {onMoveLocation && (
              <button onClick={() => onMoveLocation(stop)} className="inline-flex items-center gap-1 text-[11px] text-blue-700 hover:underline">
                <MapPin size={12} /> Correct pin location{note?.location_override ? ' · custom saved' : ''}
              </button>
            )}
          </div>
        )}
      </div>
      {contact && (
        <div><Cap>Contact</Cap><div className="text-slate-800">{[contact.name, contact.phone].filter(Boolean).join(' · ') || '—'}</div></div>
      )}
      <div className="flex gap-6 flex-wrap">
        <div><Cap>Skids</Cap><div className="text-slate-800">{Number(stop.cartons) || 0}</div></div>
        <div><Cap>Loose pcs</Cap><div className="text-slate-800">{Number(stop.volume) || 0}</div></div>
        <div><Cap>Total pcs</Cap><div className="text-slate-800">{Number(stop.pallets) || 0}</div></div>
        <div><Cap>Weight</Cap><div className="text-slate-800">{(Number(stop.weight) || 0).toLocaleString()} lb</div></div>
      </div>
      {(keys.length > 0 || oversize) && (
        <div>
          <Cap>Restrictions</Cap>
          <ul className="mt-0.5">
            {keys.map((k) => (
              <li key={k} className="inline-flex items-center gap-1.5 mr-2 mb-0.5 align-middle">
                <RestrictionIcon kind={k} size={14} /><span>{RESTRICTION_ICONS[k]?.label || k}</span>
              </li>
            ))}
            {oversize && (
              <li className="inline-flex items-center gap-1.5 mr-2 mb-0.5 align-middle">
                <span className="text-[9px] font-bold text-amber-700 border border-amber-400 rounded px-1">OS</span><span>Oversize freight</span>
              </li>
            )}
          </ul>
        </div>
      )}
      {note?.appointment_required && (
        <div><Cap>Appointment</Cap><div className="text-slate-800">Required{note.appointment_notes ? ` — ${note.appointment_notes}` : ''}</div></div>
      )}
      {(apptWindowLabel(stop) || windowViolated) && (
        <div>
          <Cap>Appointment window</Cap>
          <div className="text-slate-800">
            {apptWindowLabel(stop) || '—'}{String(stop.timeConstraint || '').toUpperCase() === 'STRICT' ? ' (strict)' : ''}
            {windowViolated && <span className="ml-1 text-amber-700 font-semibold">⚠ outside appointment window</span>}
          </div>
        </div>
      )}
      {hoursStr && <div><Cap>Receiving hours</Cap><div className="text-slate-800">{hoursStr}</div></div>}
      <div>
        <Cap>Products / line items</Cap>
        {lines.length === 0 ? (
          <div className="text-slate-400 italic">No line items</div>
        ) : (
          <ul className="mt-0.5 space-y-0.5">
            {lines.map((d, i) => {
              const name = d.product || d.sku || 'Item';
              const sku = d.sku && d.product ? ` (${d.sku})` : '';
              const qty = d.quantity != null ? `${d.quantity}${d.quantityUOM ? ` ${d.quantityUOM}` : ''}` : null;
              const wt = d.weight != null ? `${Number(d.weight).toLocaleString()}${d.weightUOM ? ` ${d.weightUOM}` : ''}` : null;
              const dims = lineItemDims(d);
              const meta = [qty, wt, dims].filter(Boolean).join(' · ');
              return (
                <li key={i} className="text-slate-800">
                  {name}{sku}{String(d.productCategory || '').toUpperCase() === 'L' && <span className="ml-1 text-[9px] font-bold text-amber-700">·OS</span>}
                  {meta && <span className="text-slate-500"> — {meta}</span>}
                </li>
              );
            })}
          </ul>
        )}
      </div>
    </div>
  );
}

// The rich "live" extras that turn the Routing stop popup into a FULL stop card (matching the
// Map's): a printable Delivery Ticket, on-demand full NuVizz notes + a collapsible Activity
// Timeline (StopLiveDetail), and the driver's POD photos (the load + assigned driver show at the
// top of the popup, under "On load"). Opening it
// costs NO NuVizz call — the ticket builds from the already-loaded order, the timeline fetches
// only when expanded, and POD/Refresh are opt-in buttons (same lazy behavior as the Map card).
function RoutingStopRichDetail({ stop, onRefreshed }) {
  const [showTicket, setShowTicket] = useState(false);
  const ticketHtml = useMemo(
    () => (showTicket ? buildTicketHtml(stop, (typeof window !== 'undefined' ? window.location.origin : '') + '/davis-logo.jpg') : ''),
    [showTicket, stop],
  );
  return (
    <div className="mt-2 pt-2 border-t space-y-2">
      <button
        onClick={() => setShowTicket(true)}
        className="w-full inline-flex items-center justify-center gap-1.5 text-xs font-semibold text-white rounded-md px-3 py-2"
        style={{ background: BRAND }}
      >
        <FileText size={14} /> Delivery Ticket
      </button>
      {showTicket && (
        <PrintDocModal
          title={`Delivery Ticket · PRO ${stop.pro || stop.stopNbr || ''}`}
          html={ticketHtml}
          pageW={816}
          onClose={() => setShowTicket(false)}
        />
      )}
      <StopLiveDetail stop={stop} onRefreshed={onRefreshed} />
      <PodDocsSection stop={stop} onRefreshed={onRefreshed} />
    </div>
  );
}

// Full-detail card for a stop, shown in the RIGHT PANEL (takeover overlay), opened
// from a map-marker click, a PRO/order-number link, or any panel row. Shows the
// Routing summary (RoutingStopDetail — now with Edit address / Correct pin location)
// PLUS the full live card (Delivery Ticket, notes + Activity Timeline, POD,
// route/driver via RoutingStopRichDetail). Fills the rail column; closes via X or Esc.
// Never renders empty — guards a null stop. (Replaces the old center-popup modal so a
// clicked stop's detail always lives in the right panel — dispatcher request.)
function RoutingStopPanel({ stop, notes, onClose, onOpenLoad, windowViolatedSet, onMoveLocation, onEditAddress, onAutoFixAddress, onOpenHistory, onText, onTextDriver, onSave, saving, saveError, drivers = [] }) {
  useEffect(() => {
    const onKey = (e) => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);
  if (!stop) return null;
  const note = notes?.get?.(stop.matchKey) || null;
  const windowViolated = !!(windowViolatedSet && windowViolatedSet.has(String(stop.stopNbr || stop.pro)));
  // Which load/route is this stop on (#281). loadKey opens it in the Compare panel via the
  // sidebar's "View full route" affordance (onOpenRoute → onOpenLoad).
  const loadKey = loadDisplayName(stop.routeName, stop.loadNbr);
  // Routing now renders the SAME full stop panel as the Map (StopSidebar) — Street View /
  // Google Maps / Find business, Edit address, Correct pin, Text customer, History, AND the
  // customer-notes editor (priority / delivery window / receiving hours + Save). Delivery
  // Ticket, live notes/timeline and POD come along inside StopDataSections. The routing-only
  // extra (an appointment-window warning) sits as a banner on top.
  return (
    <div className="flex-1 min-h-0 flex flex-col bg-white">
      {windowViolated && (
        <div className="shrink-0 px-3 py-1.5 bg-amber-50 border-b border-amber-200 text-[12px] font-semibold text-amber-800">
          ⚠ Outside appointment window
        </div>
      )}
      <StopSidebar
        embedded
        stop={stop}
        note={note}
        onClose={onClose}
        onSave={onSave}
        saving={saving}
        saveError={saveError}
        onMoveLocation={onMoveLocation}
        onEditAddress={onEditAddress}
        onAutoFixAddress={onAutoFixAddress}
        onText={onText}
        onTextDriver={onTextDriver}
        onOpenHistory={onOpenHistory}
        onOpenRoute={loadKey && onOpenLoad ? () => onOpenLoad(loadKey) : undefined}
        drivers={drivers}
      />
    </div>
  );
}

// The selected-stops list — the source of truth for "what is actually selected".
// Mobile: collapsed by default, tap the header to expand. Desktop: persistent
// (parent opens it by default). Each row taps open an inline detail accordion;
// the × removes the stop from the selection (two-way sync via onRemove). Columns
// are sortable via the shared useSortable hook.
function RoutingSelectedList({ selectedStops, notes, onRemove, open, setOpen, onOpenStop }) {
  const [detailId, setDetailId] = useState(null);
  const rows = useMemo(() => selectedStops.map((s) => {
    const note = notes.get(s.matchKey) || null;
    return {
      id: String(s.stopNbr), stop: s, note,
      keys: getRestrictionBadgeKeys(note),
      oversize: stopLooksOversize(s),
      customer: s.businessName || String(s.stopNbr),
      city: s.city || '',
      skids: Number(s.cartons) || 0,         // NuVizz totalCartons = real skids
      loose: Number(s.volume) || 0,          // NuVizz volume = loose pieces
      pieces: Number(s.pallets) || 0,        // NuVizz totalPallets = total pieces
      weight: Number(s.weight) || 0,
    };
  }), [selectedStops, notes]);
  // DEFAULT = the order you added them (Chad, Jul 31: "i want the default sorted to the order
  // they are added"). selectedIds is a Set and a Set keeps insertion order, so selectedStops is
  // ALREADY add-order — the panel was throwing that away with an alphabetical default. A null
  // sort key means "leave the rows alone", so that is the whole fix; the Added chip is how you
  // get back to it once you have sorted by something else.
  const { sorted, sortKey, sortDir, toggle } = useSortable(rows, null, 'asc');
  const SortBtn = ({ label, k }) => (
    <button onClick={() => toggle(k)} className="inline-flex items-center gap-0.5 hover:text-slate-700">
      {label}{sortKey === k && k != null ? (sortDir === 'asc' ? <ChevronUp size={10} /> : <ChevronDown size={10} />) : null}
    </button>
  );
  return (
    <div className="border rounded">
      <button onClick={() => setOpen((o) => !o)} className="w-full flex items-center justify-between px-2 py-1.5 text-[12px] font-semibold text-slate-700">
        <span>Selected stops ({rows.length})</span>
        {open ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
      </button>
      {open && (rows.length === 0 ? (
        <div className="px-2 pb-2 text-[11px] text-slate-400">No stops selected yet. Tap a stop on the map, or use Add in view / Box / Lasso.</div>
      ) : (
        <div className="border-t">
          <div className="flex items-center gap-3 px-2 py-1 text-[10px] uppercase tracking-wide text-slate-500 border-b bg-slate-50">
            <SortBtn label="Added" k={null} /><SortBtn label="Customer" k="customer" /><SortBtn label="City" k="city" /><SortBtn label="Skids" k="skids" /><SortBtn label="Loose" k="loose" /><SortBtn label="Pcs" k="pieces" /><SortBtn label="Wt" k="weight" />
          </div>
          <div className="max-h-[42vh] overflow-y-auto divide-y">
            {sorted.map((r) => (
              <div key={r.id}>
                <div className="flex items-start gap-2 px-2 py-1.5">
                  <button onClick={() => setDetailId((d) => (d === r.id ? null : r.id))} className="flex-1 text-left min-w-0">
                    <div className="flex items-center gap-1.5">
                      <span className="font-medium truncate">{r.customer}</span>
                      {detailId === r.id ? <ChevronUp size={12} /> : <ChevronDown size={12} />}
                    </div>
                    <div className="text-[11px] text-slate-500 truncate">{[r.city, `${r.skids} skid${r.skids === 1 ? '' : 's'}`, `${r.loose} loose`, `${r.pieces} pc${r.pieces === 1 ? '' : 's'}`, `${r.weight.toLocaleString()} lb`].filter(Boolean).join(' · ')}</div>
                    {(r.keys.length > 0 || r.oversize) && (
                      <div className="flex flex-wrap items-center gap-1 mt-0.5">
                        {r.keys.map((k) => <RestrictionIcon key={k} kind={k} size={14} />)}
                        {r.oversize && <span className="text-[9px] font-bold text-amber-700 border border-amber-400 rounded px-1" title="Oversize freight">OS</span>}
                      </div>
                    )}
                  </button>
                  <span className="text-[11px] shrink-0"><ProLink stop={r.stop} onOpen={onOpenStop} /></span>
                  <button onClick={() => onRemove(r.id)} aria-label={`Remove ${r.customer} from selection`} className="text-slate-400 hover:text-red-600 px-1 leading-none text-lg shrink-0">×</button>
                </div>
                {detailId === r.id && <div className="px-2 pb-2"><RoutingStopDetail stop={r.stop} note={r.note} onOpen={onOpenStop} /></div>}
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

// Desktop right-rail variant of the selected-stops list: a full, always-visible
// sortable table with live map<->list hover linkage (hovering a row emphasizes
// its marker and vice-versa via the shared hoverId), a per-row remove, and a
// docked detail panel below the table. Reuses RoutingStopDetail + the same
// customer_notes / stopDetails helpers. The selection is the single source of
// truth (rows derive from selectedStops; remove flows back through onRemove).
// Mobile Setup's selected-stops review — the mobile twin of the desktop rail's
// "Stops" tab (Chad: "I want to see the 36 I have selected and there is no way
// to do that"). Wraps the SAME RoutingStopsPanel in a collapsible section so a
// mid-build workbench isn't buried under 36 cards: open by default while
// composing a selection (no workbench routes yet — the badge-tap flow), starts
// collapsed once a build is underway. Re-mounts on each sheet open, so the
// default re-evaluates then.
function MobileSelectedStops({ count, skids, pieces, defaultOpen, children }) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <div className="rounded border border-slate-200 bg-white overflow-hidden">
      <button
        onClick={() => setOpen((o) => !o)}
        className="w-full flex items-center justify-between px-3 py-2 text-left"
        style={{ minHeight: 44 }}
      >
        <span className="text-xs font-semibold text-slate-700 uppercase tracking-wide">
          Selected stops ({count})<span className="normal-case font-normal text-slate-500"> · {skids} sk · {pieces} pcs</span>
        </span>
        {open ? <ChevronUp size={16} className="text-slate-400" /> : <ChevronDown size={16} className="text-slate-400" />}
      </button>
      {open && <div className="border-t">{children}</div>}
    </div>
  );
}

function RoutingStopsPanel({ selectedStops, notes, onRemove, hoverId, setHoverId, onOpenStop }) {
  const [detailId, setDetailId] = useState(null);
  const rowRefs = useRef(new Map());
  const rows = useMemo(() => selectedStops.map((s) => {
    const note = notes.get(s.matchKey) || null;
    return {
      id: String(s.stopNbr), stop: s, note,
      keys: getRestrictionBadgeKeys(note), oversize: stopLooksOversize(s),
      customer: s.businessName || String(s.stopNbr), city: s.city || '',
      skids: Number(s.cartons) || 0, loose: Number(s.volume) || 0, pieces: Number(s.pallets) || 0, weight: Number(s.weight) || 0,
    };
  }), [selectedStops, notes]);
  // DEFAULT = the order you added them (Chad, Jul 31: "i want the default sorted to the order
  // they are added"). selectedIds is a Set and a Set keeps insertion order, so selectedStops is
  // ALREADY add-order — the panel was throwing that away with an alphabetical default. A null
  // sort key means "leave the rows alone", so that is the whole fix; the Added chip is how you
  // get back to it once you have sorted by something else.
  const { sorted, sortKey, sortDir, toggle } = useSortable(rows, null, 'asc');
  // Keep the hovered row visible. block:'nearest' is a no-op when the row is
  // already on screen (pointer hover), so this only scrolls for map-driven hover.
  useEffect(() => {
    if (hoverId) rowRefs.current.get(hoverId)?.scrollIntoView({ block: 'nearest' });
  }, [hoverId]);
  // The active detail stop may have been removed from the selection.
  const detailRow = rows.find((r) => r.id === detailId) || null;
  // Compact sort chip — the panel is narrow, so instead of a wide multi-column table (which clipped
  // its right columns) each stop is a STACKED card: name + PRO/remove on top, freight on a sub-line.
  // These chips keep the columns sortable without needing the width.
  const SortBtn = ({ label, k }) => (
    <button onClick={() => toggle(k)} className={`inline-flex items-center gap-0.5 hover:text-slate-700 ${sortKey === k ? 'text-slate-700 font-semibold' : ''}`}>
      {label}{sortKey === k && k != null ? (sortDir === 'asc' ? <ChevronUp size={10} /> : <ChevronDown size={10} />) : null}
    </button>
  );

  if (rows.length === 0) {
    return <div className="p-4 text-[12px] text-slate-400">No stops selected yet. Click a stop on the map, drag a box, lasso, or use “Add stops in view”.</div>;
  }
  return (
    <div className="flex-1 min-h-0 flex flex-col">
      <div className="flex items-center flex-wrap gap-x-3 gap-y-0.5 px-2 py-1 text-[10px] uppercase tracking-wide text-slate-500 border-b bg-slate-50 shrink-0">
        <span className="text-slate-400">Sort:</span>
        <SortBtn label="Added" k={null} /><SortBtn label="Customer" k="customer" /><SortBtn label="City" k="city" /><SortBtn label="Skids" k="skids" /><SortBtn label="Loose" k="loose" /><SortBtn label="Pcs" k="pieces" /><SortBtn label="Wt" k="weight" />
      </div>
      <div className="flex-1 min-h-0 overflow-y-auto divide-y">
        {sorted.map((r) => {
          const active = detailId === r.id, hot = hoverId === r.id;
          return (
            <div
              key={r.id}
              ref={(el) => { if (el) rowRefs.current.set(r.id, el); else rowRefs.current.delete(r.id); }}
              onMouseEnter={() => setHoverId(r.id)}
              onMouseLeave={() => setHoverId((h) => (h === r.id ? null : h))}
              onClick={() => setDetailId((d) => (d === r.id ? null : r.id))}
              className={`px-2 py-1.5 cursor-pointer ${active ? 'bg-blue-50 ring-1 ring-inset ring-blue-300' : hot ? 'bg-amber-50' : 'hover:bg-slate-50'}`}
            >
              <div className="flex items-start gap-2">
                <div className="min-w-0 flex-1">
                  <div className="truncate font-medium text-[12px]" title={r.customer}>{r.customer}</div>
                  <div className="text-[11px] text-slate-500 truncate">{[r.city, `${r.skids} sk`, `${r.loose} loose`, `${r.pieces} pcs`, `${r.weight.toLocaleString()} lb`].filter(Boolean).join(' · ')}</div>
                  {(r.keys.length > 0 || r.oversize) && (
                    <div className="flex flex-wrap items-center gap-1 mt-0.5">
                      {r.keys.map((k) => <RestrictionIcon key={k} kind={k} size={13} />)}
                      {r.oversize && <span className="text-[9px] font-bold text-amber-700 border border-amber-400 rounded px-1" title="Oversize freight">OS</span>}
                    </div>
                  )}
                </div>
                <div className="shrink-0 flex items-center gap-1" onClick={(e) => e.stopPropagation()}>
                  <ProLink stop={r.stop} onOpen={onOpenStop} className="text-[11px]" />
                  <button onClick={(e) => { e.stopPropagation(); onRemove(r.id); }} aria-label={`Remove ${r.customer} from selection`} className="text-slate-400 hover:text-red-600 leading-none text-lg">×</button>
                </div>
              </div>
            </div>
          );
        })}
      </div>
      {detailRow && (
        <div className="shrink-0 border-t bg-white max-h-[42%] overflow-y-auto">
          <div className="flex items-center justify-between px-3 py-1.5 border-b bg-slate-50">
            <div className="font-semibold text-[13px] truncate">{detailRow.customer}</div>
            <button onClick={() => setDetailId(null)} className="text-slate-400 hover:text-slate-700 text-lg leading-none" aria-label="Close detail">×</button>
          </div>
          <div className="p-3"><RoutingStopDetail stop={detailRow.stop} note={detailRow.note} onOpen={onOpenStop} /></div>
        </div>
      )}
    </div>
  );
}

// Floating "Selected N" overlay for the Routing map — a NuVizz-style panel that lists EVERY
// selected stop at a glance (Stop# · type · location · city · zip · requested window · weight ·
// pallets), with per-row open/remove. Toggleable on/off (selPanelOpen); floats over the map at
// both widths. The selection is the single source of truth — rows derive from selectedStops and
// remove flows back through onRemove (same contract as RoutingStopsPanel).
// The Routing right-panel "Routes" view (workbench part 3): the day's routes/drivers as summary
// cards — route name, driver, stop count, skids, weight, and delivery progress. Click a card to
// select that route's stops and frame them on the map (reuses pickLoadFromTable via onPick).
// Derived route/load status from the route's stops. NuVizz's exact load-lifecycle code isn't
// captured in the scan yet, so this is computed from each stop's execution status + whether a
// driver is assigned. Buckets the routes into the dispatcher-meaningful states we can filter on.
function deriveRouteStatus(g) {
  if (g.exceptions > 0) return 'Exception';
  if (g.count > 0 && g.delivered === g.count) return 'Completed';
  if (g.inProgress > 0 || g.delivered > 0) return 'In Progress';
  if (g.driver) return 'Planned';        // has a driver, nothing started yet
  return 'Unassigned';                    // no driver assigned
}

// NuVizz's REAL load-lifecycle status, normalized from the load roster's free-text status column.
// We don't control its exact spelling/casing, so match by substring. Returns a clean canonical
// label for the states NuVizz uses; the title-cased raw string for an unrecognized non-empty
// status (so a state we didn't anticipate still shows as its own filter option instead of being
// mis-bucketed); or null when there's no roster status at all (caller falls back to the
// execution-derived status). The un-planned check runs before 'plan' since "unplanned" contains it.
function nuvizzLoadStatus(raw) {
  const s = String(raw || '').trim().toLowerCase();
  if (!s) return null;
  if (s.includes('draft')) return 'Draft';
  if (s.includes('cancel')) return 'Cancelled';
  if (s.includes('complet') || s.includes('deliver')) return 'Completed';
  if (s.includes('transit') || s.includes('out for') || s.includes('en route') || s.includes('enroute')) return 'In-Transit';
  if (s.includes('unplan') || s.includes('un-plan') || s.includes('un plan') || s.includes('not plan')) return 'Un-Planned';
  if (s.includes('plan')) return 'Planned';
  if (s.includes('except')) return 'Exception';
  return String(raw).trim().replace(/\b\w/g, (c) => c.toUpperCase());
}

// Canonical order for the Routes Status filter. The NuVizz lifecycle states (always offered, even
// at count 0, so the filter reads like the NuVizz route grid); the execution-derived fallback
// states (Unassigned / In Progress, used only when a load has no roster status yet) slot in where
// they fit and only show when present.
const ROUTE_STATUS_ORDER = ['Draft', 'Un-Planned', 'Unassigned', 'Planned', 'In Progress', 'In-Transit', 'Completed', 'Cancelled', 'Exception'];
// Always shown in the filter even at count 0 — the NuVizz lifecycle set.
const ROUTE_STATUS_ALWAYS = ['Draft', 'Un-Planned', 'Planned', 'In-Transit', 'Completed', 'Cancelled', 'Exception'];
const ROUTE_STATUS_DEFAULT_META = { color: '#475569', bg: '#f1f5f9' };
const ROUTE_STATUS_META = {
  'Draft':       { color: '#7c3aed', bg: '#f5f3ff' },
  'Un-Planned':  { color: '#475569', bg: '#f1f5f9' },
  'Unassigned':  { color: '#475569', bg: '#f1f5f9' },
  'Planned':     { color: '#1d4ed8', bg: '#eff6ff' },
  'In Progress': { color: '#b45309', bg: '#fffbeb' },
  'In-Transit':  { color: '#b45309', bg: '#fffbeb' },
  'Completed':   { color: '#15803d', bg: '#f0fdf4' },
  'Cancelled':   { color: '#b91c1c', bg: '#fef2f2' },
  'Exception':   { color: '#b91c1c', bg: '#fef2f2' },
};
// The Status-filter option list for the routes on the board: the always-on NuVizz lifecycle states
// plus any other status actually present (a derived fallback, or an unrecognized NuVizz label),
// de-duped, in canonical order with unknowns last. Keeps "Draft" visible even at 0.
function routeStatusOptions(groups) {
  const present = new Set(groups.map((g) => g.status).filter(Boolean));
  const ordered = ROUTE_STATUS_ORDER.filter((s) => ROUTE_STATUS_ALWAYS.includes(s) || present.has(s));
  const extras = [...present].filter((s) => !ROUTE_STATUS_ORDER.includes(s)).sort();
  return [...ordered, ...extras];
}
// Group the day's stops into route/load summary cards for the Routes panel — shared by the Routing
// screen and the dispatch Map. Each group carries driver, loadId/loadNbr, counts, freight totals,
// and a status that prefers NuVizz's REAL load status (from the loads roster, joined by name then
// loadId) and falls back to the execution-derived status. Sorted alphabetically by display name.
function computeRouteGroups(stops, loadStatusByName) {
  const m = new Map();
  for (const s of stops) {
    const key = s.routeName || s.loadNbr;
    if (!key) continue;
    let g = m.get(key);
    if (!g) { g = { key, name: s.routeName || key, loadNbr: s.loadNbr || key, loadId: null, driver: '', driverId: '', count: 0, delivered: 0, inProgress: 0, exceptions: 0, skids: 0, loose: 0, weight: 0, locs: new Set() }; m.set(key, g); }
    if (!g.loadId) g.loadId = s.raw?.load?.loadId ?? s.loadId ?? null;
    if (!g.driver && (s.driverName || s.driverUserName)) g.driver = s.driverName || s.driverUserName;
    if (!g.driverId && s.driverId) g.driverId = s.driverId;
    g.count += 1;
    // PHYSICAL stops: multiple orders to the same customer/address are ONE truck stop —
    // NuVizz's own route card groups them (Total Stops) — so headers count locations.
    g.locs.add(s.matchKey || String(s.stopNbr));
    const kind = classifyStopStatus(s);
    if (kind === 'DELIVERED') g.delivered += 1;
    else if (kind === 'OUT_FOR_DEL' || kind === 'ARRIVED') g.inProgress += 1;
    if (kind === 'EXCEPTION') g.exceptions += 1;
    g.skids += Number(s.cartons) || 0;
    g.loose += Number(s.volume) || 0;
    g.weight += Number(s.weight) || 0;
  }
  const groups = [...m.values()];
  const byName = loadStatusByName || new Map();
  for (const g of groups) {
    // IDENTITY FIRST, and a name shared by two loads may not speak at all (§S). Asking the
    // NAME first is what put a red CANCELLED badge on Chad's live STEVEN: a cancelled load of
    // the same name had last-write-wins on the name key. null here → deriveRouteStatus, which
    // is built from THIS route's own stops and can never be another load's.
    const raw = resolveRosterStatus(g, byName);
    g.rosterStatus = raw || '';
    g.status = nuvizzLoadStatus(raw) || deriveRouteStatus(g);
    g.locCount = g.locs.size; delete g.locs;   // physical stops (orders sharing an address = one stop)
  }
  return groups.sort((a, b) =>
    String(loadDisplayName(a.name, a.loadNbr) || a.name).localeCompare(
      String(loadDisplayName(b.name, b.loadNbr) || b.name), undefined, { sensitivity: 'base' }));
}
function RouteStatusBadge({ status }) {
  const m = ROUTE_STATUS_META[status] || ROUTE_STATUS_DEFAULT_META;
  return (
    <span className="text-[9px] font-bold uppercase tracking-wide px-1.5 py-0.5 rounded-full shrink-0"
      style={{ color: m.color, background: m.bg }}>{status}</span>
  );
}

// onNewRoute is OPTIONAL on purpose: this panel is also rendered by the dispatch Map screen
// (which passes only groups/onPick), and a create button has no business there.
function RoutingRoutesPanel({ groups, onPick, liveWrite = false, roster = [], rosterError = null, assignLive = false, setAssignLive, onAssignDriver, assignedOverride = {}, assigningKey = null, onDispatchLoad, dispatchingKey = null, onNewRoute = null }) {
  const [selected, setSelected] = useState(() => new Set());   // empty = All
  const [menuOpen, setMenuOpen] = useState(false);
  const [q, setQ] = useState('');

  const counts = useMemo(() => {
    const c = {};
    for (const g of groups) c[g.status] = (c[g.status] || 0) + 1;
    return c;
  }, [groups]);
  // Status options reflect NuVizz's real load lifecycle (Draft / Un-Planned / … from the load
  // roster), always offering the lifecycle set plus any other status present on the board.
  const statusOptions = useMemo(() => routeStatusOptions(groups), [groups]);

  const filtered = useMemo(() => {
    const query = q.trim().toLowerCase();
    return groups.filter((g) => {
      if (selected.size && !selected.has(g.status)) return false;
      if (query) {
        const name = String(loadDisplayName(g.name, g.loadNbr) || g.name).toLowerCase();
        if (!name.includes(query) && !String(g.driver || '').toLowerCase().includes(query)) return false;
      }
      return true;
    });
  }, [groups, selected, q]);

  const toggle = (st) => setSelected((prev) => { const n = new Set(prev); n.has(st) ? n.delete(st) : n.add(st); return n; });
  const tot = filtered.reduce((a, g) => ({ stops: a.stops + g.count, skids: a.skids + g.skids, loose: a.loose + g.loose, weight: a.weight + g.weight }), { stops: 0, skids: 0, loose: 0, weight: 0 });

  return (
    <div className="flex-1 min-h-0 overflow-y-auto">
      {/* Filter bar — Status (multi-select) + quick search, mirroring the NuVizz route view. */}
      <div className="sticky top-0 z-20 bg-white border-b px-2 py-1.5 flex items-center gap-1.5">
        <div className="relative shrink-0">
          <button onClick={() => setMenuOpen((o) => !o)}
            className="inline-flex items-center gap-1 text-[11px] font-semibold border border-slate-300 rounded px-2 py-1 hover:bg-slate-50">
            <Filter size={12} /> Status{selected.size ? ` (${selected.size})` : ''} <span className="text-slate-400">▾</span>
          </button>
          {menuOpen && (
            <>
              <div className="fixed inset-0 z-30" onClick={() => setMenuOpen(false)} />
              <div className="absolute left-0 mt-1 z-40 w-48 bg-white border rounded-lg shadow-lg py-1 text-[12px]">
                <button onClick={() => setSelected(new Set())}
                  className={`w-full flex items-center justify-between px-2.5 py-1.5 hover:bg-slate-50 ${selected.size === 0 ? 'font-semibold' : ''}`}>
                  <span>All</span><span className="text-slate-400">{groups.length}</span>
                </button>
                <div className="border-t my-1" />
                {statusOptions.map((st) => (
                  <button key={st} onClick={() => toggle(st)}
                    className="w-full flex items-center justify-between px-2.5 py-1.5 hover:bg-slate-50">
                    <span className="flex items-center gap-1.5">
                      <input type="checkbox" readOnly checked={selected.has(st)} className="pointer-events-none" />
                      <RouteStatusBadge status={st} />
                    </span>
                    <span className="text-slate-400">{counts[st] || 0}</span>
                  </button>
                ))}
              </div>
            </>
          )}
        </div>
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Quick search route / driver"
          className="flex-1 min-w-0 text-[12px] border border-slate-300 rounded px-2 py-1" />
        {(q || selected.size > 0) && (
          <button onClick={() => { setQ(''); setSelected(new Set()); }} className="text-[11px] text-slate-500 hover:text-slate-800 shrink-0">Clear</button>
        )}
        {/* Driver-assign mode (only when Live dispatch is enabled). Beta = a pick previews; Live =
            a pick assigns the driver in NuVizz immediately. Defaults to LIVE and the choice is
            remembered on this device — see the assignLive state in RoutingScreen. */}
        {liveWrite && setAssignLive && (
          <button onClick={() => setAssignLive((v) => !v)}
            title={assignLive ? 'LIVE — picking a driver assigns it in NuVizz immediately. Click for Beta (preview only); the mode is remembered on this device.' : 'BETA — picking a driver only previews, nothing is sent. Click to go Live and assign for real; the mode is remembered on this device.'}
            className={`inline-flex items-center gap-1 text-[11px] font-bold px-2 py-1 rounded border shrink-0 ${assignLive ? 'border-red-600 bg-red-600 text-white' : 'border-slate-300 bg-white text-slate-600 hover:bg-slate-50'}`}>
            {assignLive ? '● LIVE' : '○ Beta'}
          </button>
        )}
        {/* Make a route (§R). Until v0.54.21 the app could CANCEL a route but never create one,
            so emptying a load was one-way — the rebuild had to happen in the portal. */}
        {onNewRoute && (
          <button onClick={onNewRoute} title="Create a new, empty route on this day's board, then drag orders onto it"
            className="inline-flex items-center gap-1 text-[11px] font-semibold px-2 py-1 rounded border border-emerald-600 bg-emerald-600 text-white hover:bg-emerald-700 shrink-0">
            <Plus size={12} /> New route
          </button>
        )}
      </div>

      <div className="px-3 py-1.5 text-[11px] text-slate-500 border-b bg-slate-50">
        {filtered.length === groups.length ? `${groups.length} route${groups.length === 1 ? '' : 's'}` : `${filtered.length} of ${groups.length} routes`} · {tot.stops} stops · {tot.skids} skids · {tot.loose} loose · {Math.round(tot.weight).toLocaleString()} lb
      </div>

      {filtered.length === 0 ? (
        <div className="p-4 text-[12px] text-slate-400">{groups.length === 0 ? "No routes on this day's board yet. Routes appear here once orders are assigned to a load." : 'No routes match the filter.'}</div>
      ) : (
        <div className="p-2 space-y-2">
          {filtered.map((g) => {
            const pct = g.count ? Math.round((100 * g.delivered) / g.count) : 0;
            const done = pct === 100;
            // Optimistic: show a just-assigned driver right away (the board's own driverName lags
            // until the next scan). Preselect the dropdown to the current driver when it matches the roster.
            const shownDriver = assignedOverride[g.key] || g.driver;
            const curDriverId = roster.find((d) => String(d.name || '').trim().toLowerCase() === String(shownDriver || '').trim().toLowerCase())?.driverId;
            const busy = assigningKey === g.key;
            const dispatching = dispatchingKey === g.key;
            // Dispatch only makes sense before the load is already underway — hide it once NuVizz
            // has moved the route past the pre-dispatch lifecycle states.
            const canDispatch = onDispatchLoad && ['Draft', 'Un-Planned', 'Unassigned', 'Planned'].includes(g.status);
            return (
              <div key={g.key} className="w-full border rounded-lg p-2 hover:bg-slate-50">
                <button onClick={() => onPick(g.key)} className="w-full text-left active:bg-slate-100 focus:outline-none focus:ring-2 focus:ring-blue-300 rounded">
                  <div className="flex items-center justify-between gap-2">
                    <div className="font-semibold text-slate-800 truncate">{loadDisplayName(g.name, g.loadNbr) || 'Unnamed load'}</div>
                    <div className="text-[12px] font-bold shrink-0" style={{ color: done ? '#16a34a' : BRAND }}>{pct}%</div>
                  </div>
                  <div className="flex items-center gap-1.5 mt-0.5 min-w-0">
                    <RouteStatusBadge status={g.status} />
                    <span className={`text-[11px] truncate ${shownDriver ? 'text-slate-600' : 'text-slate-400 italic'}`}>{shownDriver || 'No driver assigned'}</span>
                  </div>
                  <div className="flex flex-wrap items-center gap-x-3 gap-y-0.5 mt-1 text-[11px] text-slate-600">
                    <span title={g.locCount != null && g.locCount !== g.count ? `${g.count} orders across ${g.locCount} physical stops (same-address orders ride together)` : undefined}>
                      {(g.locCount ?? g.count)} stop{(g.locCount ?? g.count) === 1 ? '' : 's'}{g.locCount != null && g.locCount !== g.count ? ` · ${g.count} orders` : ''}
                    </span>
                    <span>{g.skids} skids</span>
                    <span>{g.loose} loose</span>
                    <span>{Math.round(g.weight).toLocaleString()} lb</span>
                    <span className="text-slate-400">{g.delivered}/{g.count} delivered</span>
                  </div>
                  <div className="mt-1.5 h-1 rounded bg-slate-100 overflow-hidden"><div className="h-full rounded" style={{ width: `${pct}%`, background: done ? '#16a34a' : BRAND }} /></div>
                </button>
                {/* Driver assign dropdown + Dispatch button — only when Live dispatch is on. Picks/clicks
                    act immediately in Live mode (preview-only in Beta). stopPropagation so this row
                    doesn't open the route. */}
                {liveWrite && (onAssignDriver || canDispatch) && (
                  <div className="mt-1.5 flex items-center gap-1.5" onClick={(e) => e.stopPropagation()}>
                    <Truck size={12} className="text-slate-400 shrink-0" />
                    {onAssignDriver && (
                      <select
                        value={curDriverId != null ? String(curDriverId) : ''}
                        disabled={!!rosterError || busy}
                        onChange={(e) => { const d = roster.find((x) => String(x.driverId) === e.target.value); if (d) onAssignDriver(g, d.driverId, d.name); }}
                        className="flex-1 min-w-0 border rounded px-1 py-1 text-[11px] bg-white"
                        aria-label={`Assign driver to ${loadDisplayName(g.name, g.loadNbr) || g.loadNbr}`}
                      >
                        <option value="">{rosterError ? 'Driver roster unavailable' : (roster.length ? (assignLive ? 'Assign driver…' : 'Assign driver… (Beta)') : 'Loading drivers…')}</option>
                        {roster.map((d) => <option key={String(d.driverId)} value={String(d.driverId)}>{d.name}{d.userName ? ` (${d.userName})` : ''}</option>)}
                      </select>
                    )}
                    {busy && <span className="text-[10px] text-slate-400 shrink-0">…</span>}
                    {canDispatch && (
                      <button
                        onClick={() => onDispatchLoad(g)}
                        disabled={!shownDriver || dispatching || busy}
                        title={!shownDriver ? 'Assign a driver before dispatching' : (assignLive ? `Dispatch ${loadDisplayName(g.name, g.loadNbr) || g.loadNbr} in NuVizz now` : 'Beta — preview only, flip to ● Live to dispatch for real')}
                        className="shrink-0 text-[11px] font-semibold px-2 py-1 rounded border border-slate-300 bg-white text-slate-700 hover:bg-slate-50 disabled:opacity-40 disabled:cursor-not-allowed"
                      >
                        {dispatching ? '…' : 'Dispatch'}
                      </button>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

// Segmented Routes | Drivers toggle for the right panel (and the mobile sheet). The right
// panel's "Routes / Drivers" mode used to show only routes; this splits it so you can flip
// between today's route cards and the full driver roster.
function RoutesDriversToggle({ subTab, setSubTab, routesCount, className = '' }) {
  const btn = (key, label) =>
    <button
      onClick={() => setSubTab(key)}
      className={`px-2.5 py-1 ${key !== 'routes' ? 'border-l border-slate-300' : ''} ${subTab === key ? 'text-white' : 'text-slate-600 hover:bg-slate-50'}`}
      style={subTab === key ? { background: BRAND } : {}}
      aria-pressed={subTab === key}
    >{label}</button>;
  return (
    <div className={`flex rounded-md border border-slate-300 overflow-hidden text-[12px] font-semibold shrink-0 ${className}`}>
      {btn('routes', `Routes${routesCount ? ` (${routesCount})` : ''}`)}
      {btn('drivers', 'Drivers')}
    </div>
  );
}

// "updated 3h ago" / "updated Jun 12" stamp for the roster freshness line.
function fmtRosterAge(iso) {
  if (!iso) return null;
  const then = new Date(iso).getTime();
  if (Number.isNaN(then)) return null;
  const mins = Math.round((Date.now() - then) / 60000);
  if (mins < 1) return 'just now';
  if (mins < 60) return `${mins}m ago`;
  const hrs = Math.round(mins / 60);
  if (hrs < 24) return `${hrs}h ago`;
  const days = Math.round(hrs / 24);
  if (days < 30) return `${days}d ago`;
  return new Date(iso).toLocaleDateString([], { month: 'short', day: 'numeric' });
}

// Right-panel Drivers view: the on-demand roster (from /.netlify/functions/nuvizz-driver-roster)
// cross-referenced against today's routeGroups so each enabled driver shows active/idle with
// today's stops + % delivered. "Update list" pulls a fresh roster (~1 NuVizz call). Clicking an
// active driver frames all their stops on the map.
function RoutingDriversPanel({ roster, routeGroups, onRefresh, onPickDriver }) {
  const drivers = roster.drivers || [];
  const enabled = useMemo(() => drivers.filter((d) => d.status === 'ENABLED'), [drivers]);

  // Group today's routes by driver (name or userName, upper-cased) → route keys + tallies.
  const byDriver = useMemo(() => {
    const m = new Map();
    for (const g of routeGroups) {
      const k = String(g.driver || '').trim().toUpperCase();
      if (!k) continue;
      let e = m.get(k);
      if (!e) { e = { routeKeys: [], routeNames: [], stops: 0, delivered: 0 }; m.set(k, e); }
      e.routeKeys.push(g.key); e.routeNames.push(g.name); e.stops += g.count; e.delivered += g.delivered;
    }
    return m;
  }, [routeGroups]);

  const rows = useMemo(() => {
    const matchToday = (d) =>
      byDriver.get(String(d.name || '').trim().toUpperCase()) ||
      byDriver.get(String(d.userName || '').trim().toUpperCase()) || null;
    const list = enabled.map((d) => { const today = matchToday(d); return { ...d, today, active: !!today }; });
    // Surface anyone dispatched today who isn't in the roster, so nobody active is hidden.
    const matched = new Set();
    for (const d of enabled) { matched.add(String(d.name || '').trim().toUpperCase()); matched.add(String(d.userName || '').trim().toUpperCase()); }
    for (const [k, info] of byDriver.entries()) {
      if (!matched.has(k)) list.push({ userName: k, name: k, status: 'ENABLED', today: info, active: true, _unlisted: true });
    }
    return list.sort((a, b) => (a.active !== b.active ? (a.active ? -1 : 1) : String(a.name || '').localeCompare(String(b.name || ''))));
  }, [enabled, byDriver]);

  const activeCount = rows.filter((r) => r.active).length;
  const age = fmtRosterAge(roster.updatedAt);

  return (
    <div className="flex-1 min-h-0 overflow-y-auto">
      <div className="px-3 py-1.5 border-b bg-slate-50 sticky top-0 z-10 flex items-center justify-between gap-2">
        <span className="text-[11px] text-slate-500 truncate">
          {enabled.length} enabled · {activeCount} active{age ? ` · updated ${age}` : ''}
        </span>
        <button
          onClick={onRefresh}
          disabled={roster.refreshing}
          className="inline-flex items-center gap-1 text-[11px] font-semibold px-2 py-1 rounded border border-slate-300 text-slate-700 hover:bg-white disabled:opacity-50 shrink-0"
          title="Pull the latest driver list from NuVizz (~1 call). Only needed when drivers are added or removed."
        >
          <RefreshCw size={12} className={roster.refreshing ? 'animate-spin' : ''} />
          {roster.refreshing ? 'Updating…' : 'Update list'}
        </button>
      </div>

      {roster.error && <div className="px-3 py-1.5 text-[11px] text-red-600 break-words">{roster.error}</div>}

      {roster.loading && !drivers.length ? (
        <div className="p-4 text-[12px] text-slate-400 inline-flex items-center gap-1.5"><RefreshCw size={13} className="animate-spin" /> Loading drivers…</div>
      ) : rows.length === 0 ? (
        <div className="p-4 text-[12px] text-slate-400">
          {roster.neverScanned ? 'No driver list yet — tap “Update list” to pull the roster from NuVizz (~1 call).' : 'No drivers to show.'}
        </div>
      ) : (
        <div className="p-2 space-y-2">
          {rows.map((d) => <RoutingDriverCard key={d.userName || d.name} d={d} onPick={onPickDriver} />)}
        </div>
      )}
    </div>
  );
}

function RoutingDriverCard({ d, onPick }) {
  const t = d.today;
  const pct = t && t.stops ? Math.round((100 * t.delivered) / t.stops) : 0;
  const done = pct === 100;
  const clickable = !!(t && t.routeKeys && t.routeKeys.length);
  return (
    <button
      onClick={() => clickable && onPick(t.routeKeys)}
      disabled={!clickable}
      className={`w-full text-left border rounded-lg p-2 focus:outline-none ${clickable ? 'hover:bg-slate-50 active:bg-slate-100 focus:ring-2 focus:ring-blue-300' : 'opacity-70 cursor-default'}`}
    >
      <div className="flex items-center justify-between gap-2">
        <div className="font-semibold text-slate-800 truncate">{d.name || d.userName}{d._unlisted ? ' *' : ''}</div>
        {d.active
          ? <span className="text-[10px] font-semibold text-emerald-700 bg-emerald-50 px-1.5 py-0.5 rounded-full shrink-0">Active</span>
          : <span className="text-[10px] text-slate-400 shrink-0">Idle</span>}
      </div>
      <div className="text-[11px] text-slate-500 truncate">{d.userName}{d.mobileNumber ? ` · ${d.mobileNumber}` : ''}</div>
      {d.active && t ? (
        <>
          <div className="flex flex-wrap items-center gap-x-3 gap-y-0.5 mt-1 text-[11px] text-slate-600">
            {t.routeNames.filter(Boolean).length > 0 && <span className="truncate">{t.routeNames.filter(Boolean).slice(0, 3).join(', ')}</span>}
            <span>{t.stops} stop{t.stops === 1 ? '' : 's'}</span>
            <span className="text-slate-400">{t.delivered}/{t.stops} delivered</span>
          </div>
          <div className="mt-1.5 h-1 rounded bg-slate-100 overflow-hidden"><div className="h-full rounded" style={{ width: `${pct}%`, background: done ? '#16a34a' : BRAND }} /></div>
        </>
      ) : (
        <div className="text-[11px] text-slate-400 mt-0.5">No route today</div>
      )}
    </button>
  );
}

// A little masked-ninja icon for Ninja mode — hooded head with side headband tails and a
// white eye-slit. Uses currentColor so it inherits the button's text color.
function NinjaIcon({ size = 14, className = '' }) {
  return (
    <svg viewBox="0 0 24 24" width={size} height={size} className={className} aria-hidden="true" fill="none">
      <path d="M3.5 12C3.5 7 7.4 4 12 4s8.5 3 8.5 8c0 .9-.2 1.7-.6 2.4H4.1c-.4-.7-.6-1.5-.6-2.4Z" fill="currentColor" />
      <path d="M19.4 9.4l3.1 1.3-3.1 1.3M4.6 9.4 1.5 10.7l3.1 1.3" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round" />
      <rect x="5.5" y="10" width="13" height="3" rx="1.5" fill="#fff" />
      <circle cx="9.5" cy="11.5" r="1.1" fill="currentColor" />
      <circle cx="14.6" cy="11.5" r="1.1" fill="currentColor" />
    </svg>
  );
}

// Floating on-map selection toolbar: Box · Lasso · Ninja, as small selectors that live on the
// map (so they're reachable even when the Compare panel replaces the Setup stack). Box/Lasso
// toggle their select mode; Ninja toggles ninja mode (disabled until a route is open in Compare).
function RoutingMapTools({ selectMode, onBox, onLasso, ninjaMode, onToggleNinja, ninjaAvailable }) {
  const Btn = ({ active, onClick, disabled, title, children }) => (
    <button
      onClick={onClick} disabled={disabled} title={title} aria-pressed={!!active}
      className={`w-9 h-9 flex items-center justify-center rounded-lg border shadow-sm ${active ? 'bg-blue-600 border-blue-700 text-white' : 'bg-white/95 border-slate-300 text-slate-700 hover:bg-white'} disabled:opacity-40 disabled:cursor-not-allowed`}
    >{children}</button>
  );
  // z-30 keeps the tools above the Selected panel and chips so they're always tappable (issue #232).
  // Ninja is never disabled — when no Compare route is open, tapping it surfaces a hint (handled by
  // onToggleNinja) instead of presenting a dead button the dispatcher can't tell apart from a bug.
  return (
    <div className="absolute left-2 top-1/2 -translate-y-1/2 z-30 flex flex-col gap-1.5">
      <Btn active={selectMode === 'box'} onClick={onBox} title="Box select — tap two corners (or drag) to grab a group"><Square size={16} /></Btn>
      <Btn active={selectMode === 'lasso'} onClick={onLasso} title="Lasso select — tap points (or hold & draw) around stops"><Lasso size={16} /></Btn>
      <Btn active={ninjaMode} onClick={onToggleNinja} title={ninjaAvailable ? 'Ninja — click stops onto the active Compare route' : 'Ninja — open a route in the Compare panel first'}><NinjaIcon size={16} /></Btn>
    </div>
  );
}

// One route card in the workbench (part 4): a route opened from the right Routes panel. Shows
// the route's stops in working order with a re-sequence strategy picker (Shortest / Farthest /
// Closest / Reverse), collapse/close, per-stop open, and — when other routes are open — a
// "move to route" picker that reassigns a stop to another open card. The order lives in wbRoutes
// state; this is a planning overlay (it does not mutate the board).
// Human labels for the re-sequence strategies (shared by the card's applied-strategy line and the
// "Re-sequenced …" toast).
const RESEQ_LABELS = { loop: 'Loop — down one side & back', min: 'Shortest distance', closest: 'Closest first', farthest: 'Farthest first', reverse: 'Reverse', manual: 'Manual order' };

// ── Live dispatch (beta) ─────────────────────────────────────────────────────
// The routes-panel write surface: assign a driver to a load + dispatch it to NuVizz.
// NOTHING fires while you build/reorder a load — this bar only STAGES a driver choice +
// dispatch intent, and a write happens only on Save → Confirm. In Beta mode Save just
// previews the exact NuVizz calls (server dry-run, zero calls); in Live mode Confirm
// commits them. Hidden entirely unless LIVE_WRITE_FLAG is opted-in. route.key is the
// load number (loadNbr); the server resolves it to the internal loadId.
// Per-card staging row (beta): pick a driver + flag dispatch for THIS load. PURE STAGING —
// it only updates the panel's staged state; nothing is sent until the panel-level "Save".
// The load's membership + order are staged in the card's stop list itself (drag / move /
// re-sequence), so this row covers just driver + dispatch. `dirty` shows an edited marker.
function LiveDispatchBar({ route, staged, onStage, roster, rosterError, dirty }) {
  const loadNbr = route.key;
  const driverId = staged?.driverId != null && staged?.driverId !== '' ? String(staged.driverId) : '';
  const dispatch = !!staged?.dispatch;
  const onDriver = (e) => {
    const d = roster.find((x) => String(x.driverId) === String(e.target.value)) || null;
    onStage({ driverId: d ? d.driverId : '', driverName: d ? d.name : '' });
  };
  return (
    <div className="px-2 py-1.5 border-t bg-slate-50/70 shrink-0 space-y-1">
      <div className="flex items-center gap-1.5">
        <Truck size={12} className="text-slate-400 shrink-0" />
        <select
          value={driverId}
          onChange={onDriver}
          disabled={!!rosterError}
          className="flex-1 min-w-0 border rounded px-1 py-1 text-[11px] bg-white"
          aria-label={`Assign driver to ${loadNbr}`}
        >
          <option value="">{rosterError ? 'Driver roster unavailable' : (roster.length ? 'Assign driver…' : 'Loading drivers…')}</option>
          {roster.map((d) => <option key={String(d.driverId)} value={String(d.driverId)}>{d.name}{d.userName ? ` (${d.userName})` : ''}</option>)}
        </select>
      </div>
      <div className="flex items-center justify-between gap-2">
        <label className="flex items-center gap-1 text-[11px] text-slate-600 cursor-pointer" title="Also release the load to the assigned driver when you Save">
          <input type="checkbox" checked={dispatch} onChange={(e) => onStage({ dispatch: e.target.checked })} /> <Send size={11} /> Dispatch
        </label>
        {dirty && <span className="text-[10px] font-semibold text-amber-600" title="Unsaved staged changes — use Save in the Compare header">● edited</span>}
      </div>
    </div>
  );
}

// Confirmation modal shown before any live commit — lists the EXACT NuVizz calls the
// Save will fire (from the server dry-run plan) and, in Live mode against the prod
// tenant, a hard production warning. This is the last gate before a real write.
function LiveCommitConfirm({ confirm, liveMode, busy, title, onCancel, onConfirm }) {
  const isProd = confirm.tenant === 'DAVIS';
  return (
    <div className="fixed inset-0 z-[60] bg-black/40 flex items-center justify-center p-4" onMouseDown={(e) => { if (e.target === e.currentTarget) onCancel(); }}>
      <div className="bg-white rounded-lg shadow-xl w-full max-w-md max-h-[80vh] flex flex-col">
        <div className="px-4 py-3 border-b flex items-center justify-between">
          <div className="font-semibold text-slate-800 flex items-center gap-2"><Send size={16} /> {liveMode ? 'Send to NuVizz' : 'Preview (Beta)'}</div>
          <button onClick={onCancel} className="text-slate-400 hover:text-slate-700" aria-label="Cancel"><X size={18} /></button>
        </div>
        <div className="px-4 py-3 overflow-y-auto text-sm">
          <div className="text-slate-600 mb-2">{title} · tenant <b className={isProd ? 'text-red-600' : 'text-slate-700'}>{confirm.tenant}{isProd ? ' (PROD)' : ''}</b></div>
          {confirm.warnings?.length > 0 && (
            <div className="mb-2 text-[12px] text-amber-700 bg-amber-50 border border-amber-200 rounded p-2 space-y-0.5">
              {confirm.warnings.map((w, i) => <div key={i}>⚠ {w}</div>)}
            </div>
          )}
          <div className="text-slate-500 mb-1">{liveMode ? 'This will fire:' : 'In Live mode this would fire:'}</div>
          <ul className="list-disc pl-5 space-y-0.5 text-slate-700">
            {(confirm.plan.length ? confirm.plan : ['(no changes)']).map((p, i) => <li key={i}>{p}</li>)}
          </ul>
          {liveMode && isProd && (
            <div className="mt-3 flex items-start gap-1.5 text-[12px] text-red-700 bg-red-50 border border-red-200 rounded p-2">
              <AlertTriangle size={14} className="shrink-0 mt-0.5" /> This writes to PRODUCTION dispatch — the driver will be assigned/notified in NuVizz.
            </div>
          )}
        </div>
        <div className="px-4 py-3 border-t flex items-center justify-end gap-2">
          <button onClick={onCancel} className="px-3 py-1.5 text-sm rounded border border-slate-300 text-slate-600 hover:bg-slate-50">Cancel</button>
          <button onClick={onConfirm} disabled={busy} className={`px-3 py-1.5 text-sm rounded font-semibold text-white disabled:opacity-60 ${liveMode ? 'bg-red-600 hover:bg-red-700' : 'bg-blue-600 hover:bg-blue-700'}`}>
            {busy ? 'Sending…' : (liveMode ? 'Send' : 'OK (simulated)')}
          </button>
        </div>
      </div>
    </div>
  );
}

function RoutingWorkbenchCard({ route, stopById, otherKeys, ninjaMode, isActive, onSetActive, onResequence, onCollapse, onClose, onMoveStop, onDropStop, onRemoveStop, onRemoveAllStops, onUndoRemove, onOpenStop, onPrintManifest, roster, rosterError, staged, onStage, dirty, isMobile, liveWrite }) {
  // The live-dispatch UI gate is now the gear toggle (prop) rather than the module-level
  // ?write=1/env const. Aliased to the original name so the gate sites below are unchanged.
  const LIVE_WRITE_FLAG = liveWrite;
  // NEVER silently drop an id the lookup can't resolve. `rows` used to be
  // `.map(get).filter(Boolean)`, so a staged stop that left the board (delivered,
  // cancelled, reconsigned) vanished from the card, from the freight totals and from
  // the PRINTED MANIFEST — while still riding in route.order and in the Save. The card
  // must show exactly what Save will send, so an unresolved id renders as a stub row.
  const rows = route.order.map((id) => stopById.get(String(id)) || { stopNbr: String(id), __unresolved: true });
  const unresolvedCount = rows.filter((s) => s.__unresolved).length;
  const unmappedCount = rows.filter((s) => !s.__unresolved && (s.lat == null || s.lng == null)).length;
  // Orders staged for removal (in `removed` but no longer in the live order) — shown in the footer.
  const removedRows = (route.removed || [])
    .filter((id) => !route.order.includes(String(id)))
    .map((id) => stopById.get(String(id)) || { stopNbr: id, businessName: String(id) });
  // Drag-and-drop (desktop): track which row we're hovering so we can show a drop line, and read
  // the dragged stop out of dataTransfer on drop. beforeId=null means "append to the end".
  const [dragOverId, setDragOverId] = useState(null);
  const [expanded, setExpanded] = useState(() => new Set());   // per-stop detail expand (NuVizz-style)
  const toggleExpand = (id) => setExpanded((prev) => { const n = new Set(prev); n.has(id) ? n.delete(id) : n.add(id); return n; });
  // Expand-all / collapse-all the per-stop detail in one click (#275).
  const allExpanded = route.order.length > 0 && route.order.every((id) => expanded.has(String(id)));
  const toggleAll = () => setExpanded(allExpanded ? new Set() : new Set(route.order.map(String)));
  const onRowDragStart = (e, id) => { try { e.dataTransfer.setData('text/plain', JSON.stringify({ fromKey: route.key, id: String(id) })); e.dataTransfer.effectAllowed = 'move'; } catch { /* ignore */ } };
  const readDrag = (e) => { try { return JSON.parse(e.dataTransfer.getData('text/plain')); } catch { return null; } };
  const onDrop = (e, beforeId) => {
    e.preventDefault(); e.stopPropagation(); setDragOverId(null);
    const d = readDrag(e);
    if (d && d.id) onDropStop(d.fromKey, d.id, route.key, beforeId);
  };
  const color = route.color || '#64748b';
  let skids = 0, loose = 0, weight = 0, delivered = 0;
  let driverName = '', driverId = '';
  for (const s of rows) {
    if (s.__unresolved) continue;   // a stub row carries no freight/status to total
    skids += Number(s.cartons) || 0; loose += Number(s.volume) || 0; weight += Number(s.weight) || 0;
    if (classifyStopStatus(s) === 'DELIVERED') delivered += 1;
    if (!driverName && (s.driverName || s.driverUserName)) driverName = s.driverName || s.driverUserName;
    if (!driverId && s.driverId) driverId = s.driverId;
  }
  const driverLabel = driverName || (driverId ? 'Driver assigned' : 'No driver');
  // Route distance + drive time (depot-anchored, in the CURRENT order) via the same haversine
  // recompute the map polyline uses — matches the NuVizz route card's mileage and updates live on
  // re-sequence / drag. Per-stop "next leg" miles feed the expanded detail. All local, no API.
  const pts = [];
  for (const s of rows) if (s.lat != null && s.lng != null) pts.push({ id: String(s.stopNbr), lat: s.lat, lng: s.lng });
  const rc = pts.length ? recomputeRoute(pts, ROUTING_DEPOT) : null;
  const miles = rc ? rc.totalDistanceMeters / 1609.344 : 0;
  const driveMin = rc ? Math.round(rc.totalDurationSec / 60) : 0;
  const dhMi = rc && rc.legs[0] ? rc.legs[0].distanceMeters / 1609.344 : 0;   // deadhead: depot → first stop
  const nextMiById = new Map();
  if (rc) for (let k = 0; k < pts.length; k++) { const nl = rc.legs[k + 1]; if (nl) nextMiById.set(pts[k].id, nl.distanceMeters / 1609.344); }
  const fmtDur = (m) => (m >= 60 ? `${Math.floor(m / 60)}h${String(m % 60).padStart(2, '0')}m` : `${m}m`);
  const fmtWin = (iso) => { const m = String(iso || '').match(/[T ](\d{2}):(\d{2})/); if (!m) return ''; let h = +m[1]; const ap = h >= 12 ? 'p' : 'a'; h = h % 12 || 12; return `${h}:${m[2]}${ap}`; };
  return (
    <div className={`${isMobile ? 'w-full' : 'w-[300px]'} shrink-0 border rounded-lg bg-white flex flex-col min-h-0 ${isMobile ? '' : 'max-h-full'} ${ninjaMode && isActive ? 'ring-2 ring-amber-400 border-amber-300' : ''}`}>
      <div className={`px-2 py-1.5 border-b rounded-t-lg shrink-0 ${ninjaMode && isActive ? 'bg-amber-50' : 'bg-slate-50'}`}>
        <div className="flex items-center justify-between gap-1">
          <button onClick={onCollapse} className="flex items-center gap-1 min-w-0" aria-expanded={!route.collapsed}>
            {route.collapsed ? <ChevronRight size={14} /> : <ChevronDown size={14} />}
            <span className="w-2.5 h-2.5 rounded-full shrink-0" style={{ background: color }} title="Route colour on the map" />
            <span className="font-semibold text-slate-800 truncate" title={route.name || loadDisplayName(route.key) || 'Unnamed load'}>{route.name || loadDisplayName(route.key) || 'Unnamed load'}</span>
            {route.pendingCreate && (
              <span className="text-[9px] font-bold uppercase text-amber-800 bg-amber-100 border border-amber-300 rounded px-1 shrink-0"
                title="This route exists only on this screen so far — Save creates it in NuVizz with all its stops (NuVizz refuses an empty route)">
                not sent
              </span>
            )}
          </button>
          <div className="flex items-center gap-1.5 shrink-0">
            {ninjaMode && (
              <label className={`flex items-center gap-1 text-[10px] font-semibold cursor-pointer ${isActive ? 'text-amber-700' : 'text-slate-400'}`} title="Ninja clicks add to this route">
                <input type="radio" name="wb-active-route" checked={isActive} onChange={onSetActive} />
                <NinjaIcon size={13} /> {isActive ? 'target' : 'set'}
              </label>
            )}
            <button onClick={onClose} className="text-slate-400 hover:text-red-600 leading-none text-lg" aria-label={`Close route ${route.name || loadDisplayName(route.key) || ''}`}>×</button>
          </div>
        </div>
        {/* Mileage + drive time is the light header line; the load details drop BELOW it and wrap
            (no truncation — nothing gets cut off), with the freight counts (orders · skids · loose)
            bolded so they stand out. Physical stops = one truck stop per address (like NuVizz's
            card); orders shown alongside when it differs so nothing is hidden. */}
        {rc && <div className="text-[11px] text-slate-500">{miles.toFixed(1)} mi · {fmtDur(driveMin)} · DH {dhMi.toFixed(1)} mi</div>}
        {(() => { const locs = new Set(rows.map((s) => s.matchKey || String(s.stopNbr))).size; return (
        <div className="text-[11px] text-slate-500 leading-tight">
          {driverLabel} · {locs} stop{locs === 1 ? '' : 's'}
          {locs !== rows.length ? <> · <span className="font-bold text-slate-700">{rows.length} orders</span></> : null}
          {' · '}<span className="font-bold text-slate-700">{skids} sk</span>
          {' · '}<span className="font-bold text-slate-700">{loose} loose</span>
          {' · '}{Math.round(weight).toLocaleString()} lb · {rows.length ? Math.round((100 * delivered) / rows.length) : 0}%
        </div>
        ); })()}
        {/* Stops that can't be drawn or auto-sequenced, called out so the card explains itself
            rather than looking like it lost them. Both still ride in the Save. */}
        {(unmappedCount > 0 || unresolvedCount > 0) && (
          <div className="text-[10px] text-amber-700 leading-tight mt-0.5">
            {unmappedCount > 0 && <>⚠ {unmappedCount} stop{unmappedCount === 1 ? '' : 's'} with no map location — fix the address to sequence {unmappedCount === 1 ? 'it' : 'them'}. </>}
            {unresolvedCount > 0 && <>⚠ {unresolvedCount} stop{unresolvedCount === 1 ? '' : 's'} no longer on today’s board.</>}
          </div>
        )}
        {!route.collapsed && (
          // The dropdown shows the APPLIED strategy and keeps showing it until you change it (#280/
          // #263). EVERY hand-edit (drag, move in/out, ninja, send-selection, remove, undo) flips the
          // route to "Manual order (edited)" — that's what keeps a strategy re-APPLICABLE: a native
          // select fires no change event when you pick its already-selected value, so if a stale
          // "Farthest first" stayed shown after an edit, picking Farthest again did nothing (the
          // reported bug). No same-value guard here either — any strategy pick re-applies.
          <select onChange={(e) => { if (e.target.value && e.target.value !== 'manual') onResequence(e.target.value); }} value={route.strategy || ''} className="mt-1 w-full border rounded px-1 py-1 text-[11px] bg-white">
            <option value="" disabled>Re-sequence…</option>
            {route.strategy === 'manual' && <option value="manual" disabled>Manual order (edited)</option>}
            <option value="min">Shortest distance</option>
            <option value="farthest">Farthest first</option>
            <option value="closest">Closest first</option>
            <option value="reverse">Reverse</option>
            <option value="loop">Loop — down one side &amp; back (no crossings)</option>
          </select>
        )}
        {!route.collapsed && (
          <div className="mt-1 flex items-center justify-between gap-2">
            {rows.length > 0 ? (
              <button onClick={toggleAll} className="text-[10px] text-slate-500 hover:text-slate-700 underline">
                {allExpanded ? 'Collapse all stops' : 'Expand all stops'}
              </button>
            ) : <span />}
            <div className="flex items-center gap-1.5 shrink-0">
              {/* Cancel route — strike EVERY order off in one click ("I still have no way to get
                  rid of a route completely and put all stops back to unplanned", Aug 3). Staged
                  like eight individual ✕ clicks: the footer lists every order with Undo, nothing
                  is sent until Save, and Save gates the cancel behind the red confirm popup.
                  Hidden on a pending (＋ New route) card — that route doesn't exist in NuVizz
                  yet, so closing the card IS its cancel. */}
              {rows.length > 0 && !route.pendingCreate && onRemoveAllStops && (
                <button onClick={() => onRemoveAllStops(route.key)} className="inline-flex items-center gap-1 text-[10px] font-semibold px-1.5 py-0.5 rounded border border-red-200 text-red-700 hover:bg-red-50" title="Strike every order off this route — on Save this EMPTIES the load, which CANCELS the route in NuVizz and returns all its orders to Un-Planned (you confirm before anything is sent)">
                  <X size={12} /> Cancel route
                </button>
              )}
              {rows.length > 0 && onPrintManifest && (
                <button onClick={() => onPrintManifest(route.key)} className="inline-flex items-center gap-1 text-[10px] font-semibold px-1.5 py-0.5 rounded border border-slate-300 text-slate-600 hover:bg-slate-50" title="Print this load's driver manifest">
                  <Printer size={12} /> Print manifest
                </button>
              )}
            </div>
          </div>
        )}
      </div>
      {!route.collapsed && (
        <ol
          className={`${isMobile ? 'max-h-[40vh]' : 'flex-1'} min-h-0 overflow-y-auto divide-y`}
          onDragOver={isMobile ? undefined : (e) => { e.preventDefault(); e.dataTransfer.dropEffect = 'move'; }}
          onDrop={isMobile ? undefined : (e) => onDrop(e, null)}
        >
          {rows.length === 0 && <li className="px-2 py-2 text-[11px] text-slate-400">{isMobile ? 'No stops on this route.' : 'No stops — drag one here.'}</li>}
          {rows.map((s, i) => {
            const id = String(s.stopNbr);
            const isExp = expanded.has(id);
            const nextMi = nextMiById.get(id);
            // STUB ROW — the id is in this card's order (so Save WILL send it) but the board
            // no longer carries the stop. Shown rather than hidden so the card can't
            // under-report what it's about to save; not draggable/expandable (there's no
            // record behind it), but removable so the dispatcher can drop it deliberately.
            if (s.__unresolved) {
              return (
                <li key={id} className="text-[11px] bg-amber-50/60">
                  <div className="px-2 py-1 flex items-center gap-1.5">
                    <span className="w-4 text-right text-slate-400 font-mono shrink-0">{i + 1}</span>
                    <AlertTriangle size={11} className="text-amber-600 shrink-0" />
                    <span className="font-mono text-slate-700">{id}</span>
                    <span className="text-[10px] text-amber-700 truncate">not on today’s board — still saved</span>
                    <button onClick={(e) => { e.stopPropagation(); onRemoveStop(route.key, s.stopNbr); }} className="ml-auto text-slate-400 hover:text-red-600 shrink-0" title="Remove from this route">✕</button>
                  </div>
                </li>
              );
            }
            return (
            <li
              key={id}
              draggable={!isMobile}
              onDragStart={isMobile ? undefined : (e) => onRowDragStart(e, s.stopNbr)}
              onDragOver={isMobile ? undefined : (e) => { e.preventDefault(); e.dataTransfer.dropEffect = 'move'; setDragOverId(id); }}
              onDragLeave={isMobile ? undefined : () => setDragOverId((d) => (d === id ? null : d))}
              onDrop={isMobile ? undefined : (e) => onDrop(e, s.stopNbr)}
              className={`text-[11px] ${isMobile ? '' : 'cursor-grab active:cursor-grabbing'} ${dragOverId === id ? 'border-t-2 border-t-blue-500 bg-blue-50/60' : ''}`}
            >
              <div className="px-2 py-1 flex items-center gap-1.5">
                {!isMobile && <GripVertical size={11} className="text-slate-300 shrink-0" />}
                <span className="w-4 text-right text-slate-400 font-mono shrink-0">{i + 1}</span>
                <button onClick={(e) => { e.stopPropagation(); toggleExpand(id); }} className="text-slate-400 hover:text-slate-700 shrink-0" aria-label={isExp ? 'Collapse stop detail' : 'Expand stop detail'} aria-expanded={isExp}>
                  {isExp ? <ChevronDown size={13} /> : <ChevronRight size={13} />}
                </button>
                <div className="min-w-0 flex-1">
                  <div className="truncate font-medium text-slate-800">{s.businessName || id}</div>
                  {/* City · skids · loose. The card header totals loose for the whole route, so a
                      per-stop breakdown was the missing half — you could see 21 loose on BRIAN with
                      no way to tell WHICH stops carried it. Shown only when the stop actually has
                      loose pieces: a "0 loose" on every row is noise, and the ones that have it are
                      exactly the ones worth spotting. */}
                  {!isExp && <div className="truncate text-slate-500">{[s.city, `${Number(s.cartons) || 0} sk`, (Number(s.volume) || 0) ? `${Number(s.volume)} loose` : null].filter(Boolean).join(' · ')}</div>}
                </div>
                <button onClick={() => onOpenStop && onOpenStop(s)} className="font-mono text-blue-700 text-[10px] shrink-0" title="Open stop">{s.primaryPro || s.pro || s.stopNbr}</button>
                {/* Move-to-other-load picker — desktop drags between cards, so it's only needed on
                    touch where drag isn't available (#267). */}
                {isMobile && otherKeys.length > 0 && (
                  <select onChange={(e) => { if (e.target.value) onMoveStop(id, e.target.value); e.target.value = ''; }} defaultValue="" className="border rounded text-[10px] px-0.5 py-0.5 bg-white shrink-0" title="Move to another route" aria-label={`Move ${s.businessName || id} to another route`}>
                    <option value="">→</option>
                    {otherKeys.map((k) => <option key={k} value={k}>{k}</option>)}
                  </select>
                )}
                {/* Remove from route — drops the order off this load; it becomes Unplanned on Save.
                    The LAST stop is removable too (v0.54.17 — Chad: "I have no way of unplanning all
                    stops off this load"): emptying a load CANCELS the route in NuVizz — that is
                    NuVizz's own behaviour on removing every delivery, not our choice — so the last ✕
                    says so plainly and colours amber to mark it as the different action it is. Save
                    then gates the cancel behind the red confirm popup (cancel-guard). NOTE: v0.54.19
                    reverted this to hidden-on-last-stop by accident (a stale-base merge restored the
                    pre-0.54.17 code); test/last-stop-removable.test.mjs now pins it. */}
                {onRemoveStop && (
                  <button onClick={(e) => { e.stopPropagation(); onRemoveStop(s.stopNbr); }} className={'shrink-0 hover:text-red-600 ' + (rows.length === 1 ? 'text-amber-500' : 'text-slate-300')} title={rows.length === 1 ? 'Remove the LAST order — this EMPTIES the load, which CANCELS the route in NuVizz on Save' : 'Remove from route (unplans on Save)'} aria-label={`Remove ${s.businessName || id} from route`}>
                    <X size={13} />
                  </button>
                )}
              </div>
              {isExp && (
                <div className="px-2 pb-1.5 pl-[34px] text-[10px] text-slate-500 space-y-0.5">
                  <div className="text-slate-600">{[s.addr1, s.city, s.zip].filter(Boolean).join(', ') || '—'}</div>
                  {/* Window line dropped (#276) — it's the same default (e.g. 8:00–8:00) on every stop, so it just adds noise. */}
                  {/* Expanded shows loose UNCONDITIONALLY (unlike the collapsed line) — this is the
                      detail view, and the three numbers cross-check each other: NuVizz's `pallets`
                      is TOTAL pieces, so sk + loose should equal pcs. A row where they don't is a
                      freight count worth a second look. */}
                  <div>{Math.round(Number(s.weight) || 0).toLocaleString()} lb · {Number(s.cartons) || 0} sk · {Number(s.volume) || 0} loose · {Number(s.pallets) || 0} pcs</div>
                  {nextMi != null && <div className="text-slate-400">Next stop: {nextMi.toFixed(1)} mi</div>}
                </div>
              )}
            </li>
          ); })}
        </ol>
      )}
      {/* Removed orders — staged to become Unplanned on Save, with Undo to put them back. */}
      {!route.collapsed && removedRows.length > 0 && (
        <div className="px-2 py-1.5 border-t bg-red-50/60 shrink-0 space-y-1">
          <div className="text-[10px] font-semibold text-red-700">Removing {removedRows.length} order{removedRows.length === 1 ? '' : 's'} (Unplanned on Save):</div>
          {removedRows.map((s) => (
            <div key={String(s.stopNbr)} className="flex items-center gap-1.5 text-[11px] text-slate-600">
              <span className="min-w-0 flex-1 truncate line-through">{s.businessName || s.stopNbr}</span>
              {onUndoRemove && <button onClick={() => onUndoRemove(s.stopNbr)} className="text-blue-700 hover:underline shrink-0">Undo</button>}
            </div>
          ))}
        </div>
      )}
      {LIVE_WRITE_FLAG && !route.collapsed && (
        <LiveDispatchBar route={route} staged={staged} onStage={onStage} roster={roster || []} rosterError={rosterError} dirty={dirty} />
      )}
    </div>
  );
}

// The route workbench (part 4): the 1–3 route cards opened from the right Routes panel, laid out
// side by side (desktop) or stacked (mobile). Replaces the Setup stack on the left while routes
// are open; "Back to Setup" closes them all.
// `stopById` is the MAP's coord-only index; `boardStopById` is every board row including
// ungeocoded ones. Card membership, display, freight totals and the Save payload all use
// boardStopById so what the card shows == what Save sends (a coord-less stop is still on
// the load). Anything that needs geometry keeps using stopById.
function RoutingWorkbench({ wbRoutes, stopById, boardStopById, ninjaMode, onToggleNinja, onArmNinja, activeKey, onSetActive, onResequence, onCollapse, onClose, onCloseAll, onMoveStop, onDropStop, onRemoveStop, onRemoveAllStops, onUndoRemove, onClearRemoved, onOpenStop, onPrintManifest, selectedCount = 0, onSendSelection, isMobile, liveWrite, onBoardSync, boardDate, peerClaimFor = null, onRouteCreated = null }) {
  const lookup = boardStopById || stopById;
  // Live-dispatch gate comes from the gear toggle (prop), aliased to the original name so the
  // many gate sites in this component (Save, Beta/Live toggle, dirty guards, confirm) are unchanged.
  const LIVE_WRITE_FLAG = liveWrite;
  // Live dispatch — Beta vs Live applies to EVERY card here. DEFAULTS LIVE and the choice
  // STICKS per device (Chad: "same here lock it into live"), matching the Routes panel's
  // assign toggle. It used to reset to Beta on every mount, so a real Save meant flipping the
  // switch again each session — a safety you always flip is one you stop reading. The panel
  // only renders at all when the Live-dispatch gear is on, which is itself a persisted, explicit
  // opt-in. Note there is no confirm step behind this (see onPanelSave): in Live, Save sends.
  // Flip to ○ Beta any time for a simulated Save, and that sticks too.
  // The driver roster is pulled once (one cheap user/list read) so each card's picker is
  // populated; a failure degrades to a disabled picker, never a crash. All hooks run
  // unconditionally (the LIVE_WRITE_FLAG gate is inside the effect + the render), so hook order
  // is stable when the flag is off.
  const [liveMode, setLiveMode] = useState(() => {
    try { if (localStorage.getItem('routing.compareLive') === 'off') return false; } catch { /* private mode */ }
    return true;
  });
  useEffect(() => { try { localStorage.setItem('routing.compareLive', liveMode ? 'on' : 'off'); } catch { /* private mode */ } }, [liveMode]);
  // Save ENGINE — PINNED TO RWB. The ⚙ Classic / ⚡ Import picker is retired (Chad: "rwb don't
  // need the other options classic and import"). RWB is the only path that references stops BY
  // ID ONLY, so a Save cannot blank or clone freight/address data — the exact failure class
  // behind the Jul 2 Import incident — and it commits in 2 synchronous calls per load instead of
  // Import's async convergence poll or Classic's remove-and-reinsert ladder.
  // The SERVER brake is untouched and still has the last word: with NUVIZZ_RWB_ENABLED unset,
  // commitBoard falls through to the classic path on its own (nuvizz-write.mts —
  // `useRwb === true && !rwbEngineBlocked()`), so pinning the client here can never strand a
  // Save. The header keeps a static 🔗 RWB badge so the engine in use is still visible.
  // The old dd_write_engine / dd_import_engine localStorage keys are simply no longer read.
  // Per-card verification generation: each Save bumps its cards' generation so any OLDER
  // background verification loop for those cards exits instead of re-imposing a stale order.
  const verifyGenRef = useRef(new Map());
  const [roster, setRoster] = useState([]);
  const [rosterError, setRosterError] = useState(null);
  const [toast, setToast] = useState(null);
  const toastTimer = useRef(null);
  const showToast = useCallback((msg) => {
    setToast(msg);
    if (toastTimer.current) clearTimeout(toastTimer.current);
    // A FAILURE message stays until dismissed — the BEN 2 refusal ("stop 007144371 couldn't be
    // added — NuVizz still holds it on …") auto-vanished in 6s and truncated to "stop 0071…",
    // leaving nothing to act on. Success/info toasts keep the quick auto-dismiss.
    if (String(msg).trimStart().startsWith('✗')) return;
    toastTimer.current = setTimeout(() => setToast(null), 6000);
  }, []);
  useEffect(() => () => { if (toastTimer.current) clearTimeout(toastTimer.current); }, []);
  const rosterLoaded = useRef(false);
  useEffect(() => {
    if (!LIVE_WRITE_FLAG || rosterLoaded.current) return;
    rosterLoaded.current = true;
    let alive = true;
    callWrite('roster', {}).then((res) => {
      if (!alive) return;
      if (res.ok && Array.isArray(res.result?.drivers)) setRoster(res.result.drivers);
      else setRosterError(res.error || 'roster unavailable');
    }).catch((e) => { if (alive) setRosterError(e?.message || 'roster error'); });
    return () => { alive = false; };
  }, [LIVE_WRITE_FLAG]);

  // ── Staged commit (beta) — panel-level "Save" of the whole Compare board (§10) ──
  // Nothing is sent while you build / reorder / move stops or pick drivers; Save commits
  // every CHANGED load in one batch (commitBoard: removes-before-inserts across loads), after
  // a dry-run preview + Confirm. Beta = preview only. baselines snapshots each load's NuVizz
  // order at open, so "dirty" = the staged order/membership differs, or a driver/dispatch is set.
  const [staged, setStaged] = useState({});        // key → { driverId, driverName, dispatch }
  const [baselines, setBaselines] = useState({});  // key → stopNbr[] (order at open / last save)
  const [confirm, setConfirm] = useState(null);
  const [busy, setBusy] = useState(false);
  const [closeGuard, setCloseGuard] = useState(null);
  // Pending destructive Save held for confirmation: { loads, warnings, cancels }. Only ever set
  // for a LIVE save that would cancel one or more routes (see onPanelSave).
  const [cancelGuard, setCancelGuard] = useState(null);
  // Escape dismisses the cancel gate — but never mid-send: once the write is in flight, dropping
  // the dialog would imply it was called off when NuVizz is already acting on it.
  useEffect(() => {
    if (!cancelGuard) return undefined;
    const onKey = (e) => { if (e.key === 'Escape' && !busy) setCancelGuard(null); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [cancelGuard, busy]);
  const setStageFor = useCallback((key, patch) => setStaged((p) => ({ ...p, [key]: { ...(p[key] || {}), ...patch } })), []);
  useEffect(() => {
    const liveKeys = new Set(wbRoutes.map((r) => r.key));
    // Prune closed routes (so a reopen re-seeds against the FRESH order, not a stale baseline),
    // then seed any newly-opened route's baseline = its order at open.
    setBaselines((prev) => {
      let next = prev, changed = false;
      for (const k of Object.keys(prev)) if (!liveKeys.has(k)) { if (!changed) { next = { ...prev }; changed = true; } delete next[k]; }
      // Baseline = what NuVizz actually holds. A card opened from the board seeds from its
      // order-at-open as always; a card STAGED from a built plan carries an explicit `baseline`
      // (the load's board stops only) so the plan's added stops read as dirty and Save sends them.
      for (const r of wbRoutes) if (!(r.key in next)) { if (!changed) { next = { ...next }; changed = true; } next[r.key] = (r.baseline || r.order).slice(); }
      return changed ? next : prev;
    });
    setStaged((prev) => {
      let next = prev, changed = false;
      for (const k of Object.keys(prev)) if (!liveKeys.has(k)) { if (!changed) { next = { ...prev }; changed = true; } delete next[k]; }
      return changed ? next : prev;
    });
  }, [wbRoutes]);
  const orderChanged = useCallback((r) => {
    const b = baselines[r.key];
    return b ? (b.length !== r.order.length || b.some((id, i) => String(id) !== String(r.order[i]))) : false;
  }, [baselines]);
  const isDirty = useCallback((r) => {
    const s = staged[r.key];
    return orderChanged(r) || (!!s && ((s.driverId != null && s.driverId !== '') || s.dispatch));
  }, [orderChanged, staged]);
  const dirtyRoutes = wbRoutes.filter(isDirty);

  const buildBoardPayload = () => {
    const loads = [], warnings = [];
    for (const r of dirtyRoutes) {
      // A PENDING card's route does not exist in NuVizz yet — it goes through the newRoute
      // create in onPanelSave (header + all stops in one call), never through commitBoard
      // (which would 404 "load not found" on the derived number).
      if (r.pendingCreate) continue;
      const s = staged[r.key] || {};
      // loadNbr = the REAL NuVizz number (load/info is keyed by it) — NEVER the r.key, which for a
      // load opened from the Loads grid is the hex loadId; sending that as loadNbr made load/info 404
      // ("commitBoard: load not found"). When there's no real loadNbr we send only the loadId, and the
      // server adds stops straight off it. routeName = the friendly display name for the plan label.
      // __key carries the Compare-card key so the result can be reconciled back to THIS card even when
      // the server echoes a loadNbr/loadId that differs from what we sent (server ignores the field).
      const load = { __key: r.key, loadNbr: r.loadNbr || undefined, routeName: r.name || r.key, loadId: r.loadId || undefined };
      if (orderChanged(r)) {
        // Send the desired order as stop NUMBERS (always present on a board stop). For a load with a
        // real loadNbr the server resolves them to stopIds against the load itself, so an unplan/reorder
        // no longer silently drops a load whose stops were never opened/enriched.
        load.orderedStopNbrs = r.order.map(String);
        // Enriched stopIds when we have them — REQUIRED for the loadId-only insert path (#328), where
        // there's no loadNbr to resolve stopNbrs against.
        const ids = r.order.map((nbr) => lookup.get(String(nbr))?.stopId).filter(Boolean);
        if (ids.length) load.orderedStopIds = ids;
        // Same ids as an EXPLICIT nbr→id map (orderedStopIds is positional and only safe when
        // complete). The RWB engine uses these to skip its one-getStop-per-added-stop id lookup —
        // a 14-stop build drops from ~24 NuVizz calls to the portal's own ~7. Board rows carry
        // stopId from the scan's Stop-Id column and from enrichment; rows without one simply
        // aren't in the map and the server reads those the old way.
        const idByNbr = {};
        for (const nbr of r.order) { const sid = lookup.get(String(nbr))?.stopId; if (sid) idByNbr[String(nbr)] = String(sid); }
        if (Object.keys(idByNbr).length) load.stopIdsByNbr = idByNbr;
        if (!r.loadNbr && ids.length !== r.order.length) {
          // Numberless load + unenriched stops → can't safely resolve the reorder. Drop the ORDER
          // fields but DON'T drop the load: a staged driver/dispatch/unplan below must still be sent
          // (never silently discard an assignment).
          warnings.push(`${loadDisplayName(r.name || r.key) || r.key}: ${r.order.length - ids.length} stop(s) not loaded yet — the reorder was NOT sent (open them, then Save); any driver/unplan still applied.`);
          delete load.orderedStopNbrs; delete load.orderedStopIds;
        } else if (r.order.length === 0) {
          // Every order removed → empty the load. Removing all deliveries CANCELS the route (§10).
          load.emptyLoad = true;
          warnings.push(`${loadDisplayName(r.name || r.key) || r.key}: removing the LAST order EMPTIES the load and CANCELS the route in NuVizz.`);
        }
      }
      // stopNbrs of removed orders — drives the "unplan N order(s)" Save-preview label.
      const removedNbrs = (r.removed || []).map(String).filter((nbr) => !r.order.includes(nbr));
      if (removedNbrs.length) load.removeStopNbrs = removedNbrs;
      if (s.driverId != null && s.driverId !== '') { load.driverId = s.driverId; load.driverName = s.driverName; }
      if (s.dispatch) load.dispatch = true;
      if (load.orderedStopNbrs || load.orderedStopIds || load.emptyLoad || load.removeStopNbrs || load.driverId || load.dispatch) loads.push(load);
    }
    return { loads, warnings };
  };

  // The saved New Order ship-from (dd_neworder_origin) rides along on every board Save as the
  // LAST-RESORT origin block for the server's import mode (NUVIZZ_LOAD_IMPORT): an async load
  // import must carry a full origin or NuVizz "succeeds" and creates nothing. The server prefers
  // the load's own origin (header, then its stops' from-address); this only covers an EMPTY load
  // that exposes neither. Ignored entirely by the legacy engine.
  const savedShipFrom = () => {
    try {
      const s = JSON.parse(localStorage.getItem(NEWORDER_ORIGIN_KEY) || 'null');
      return s && String(s.addr1 || '').trim() ? s : undefined;
    } catch { return undefined; }
  };

  // Save sends to NuVizz DIRECTLY — no confirmation popup (dispatcher's call). The per-load
  // dry-run preview + the LiveCommitConfirm "Send to NuVizz" gate were removed. The server
  // still validates every write and a save NuVizz accepts-but-doesn't-apply still fails
  // loudly, so nothing is silently lost. Beta mode still simulates.
  //
  // ONE EXCEPTION, and it is deliberately narrow (Chad, Jul 30): emptying a load CANCELS the
  // route in NuVizz — the load stops existing and its orders return to Un-Planned, with no
  // undo in this app. That was announced by the same non-blocking toast used for "N stops not
  // loaded yet", fired at the instant the write left. A destructive, unrecoverable action gets
  // a real gate: `cancelsIn` reads the BUILT payload and qualifies a load only on the explicit
  // emptyLoad flag, so an ordinary reorder/unplan/driver Save can never trip it and still
  // commits with no popup at all.
  const sendBoardSave = async (loads, warnings = []) => {
    if (warnings.length) showToast(`⚠ ${warnings[0]}`);
    // Cross-device collision heads-up (presence layer): the OTHER dispatcher's
    // Compare cards are staging stop(s) this Save also plans. Warn — don't block:
    // a stale card on an idle device must never be able to freeze a real Save.
    if (peerClaimFor) {
      const claimed = [];
      for (const L of loads) for (const nbr of (L.orderedStopNbrs || [])) { const who = peerClaimFor(nbr); if (who) claimed.push({ nbr, who }); }
      if (claimed.length) showToast(`⚠ ${claimed.length} stop(s) in this Save (${claimed.slice(0, 3).map((c) => c.nbr).join(', ')}${claimed.length > 3 ? '…' : ''}) are ALSO being staged by ${claimed[0].who} on another device — the later Save wins. Coordinate before sending twice.`);
    }
    await onPanelConfirm({ loads, clientOpId: newClientOpId() });
  };
  // A PENDING card (＋ New route) is created here — the route header + its WHOLE stop list in
  // one routePlan/update (NuVizz refuses an empty route, reason 903), with any staged
  // driver/dispatch riding the same Save (Chad's design, Aug 3: "we send new route and all
  // stops at same time"). Separate from commitBoard on purpose: the load doesn't exist yet,
  // so every piece of the existing-load machinery (load/info resolve, RWB adds, retarget)
  // would just 404 on the derived number.
  const sendPendingCreates = async (pending) => {
    for (const r of pending) {
      const name = r.name || r.key;
      if (!r.order.length) { showToast(`⚠ ${name}: drag at least one order onto the card first — NuVizz won't create an empty route.`); continue; }
      const origin = readShipFromOrigin();
      if (!origin) { showToast(`⚠ ${name}: set a ship-from address in the New Order tab first — NuVizz will not create a route without one.`); continue; }
      const s = staged[r.key] || {};
      setBusy(true);
      let res;
      try {
        res = await callWrite('newRoute', {
          routeName: name, loadNbr: r.loadNbr, date: boardDate || undefined, origin,
          orderedStopNbrs: r.order.map(String),
          ...(s.driverId != null && s.driverId !== '' ? { driverId: s.driverId, driverName: s.driverName } : {}),
          ...(s.dispatch ? { dispatch: true } : {}),
        }, { dryRun: false, clientOpId: newClientOpId(), createdBy: 'dispatcher' });
      } catch (e) { res = { ok: false, error: e?.message || 'network error' }; }
      setBusy(false);
      const rr = res?.result || {};
      if (!(res?.ok && rr.ok)) {
        // `pending:true` on the result = NuVizz took the create and it may still land — its own
        // message says not to re-create; surface the server's text verbatim, never a generic ✗.
        showToast(`✗ ${name}: ${res?.error || rr.error || 'create failed'}`);
        continue;
      }
      // Flip the card to its verified identity (same key), clean its dirty state, and belt-sync
      // the board (the server already write-through-stamped the verified plan — this is the
      // same belt the commit path keeps).
      if (onRouteCreated) onRouteCreated(r.key, { loadId: rr.loadId, loadNbr: rr.loadNbr, name: rr.routeName || name });
      markSaved([r.key]);
      setStaged((p) => { const n = { ...p }; delete n[r.key]; return n; });
      if (onClearRemoved) onClearRemoved([r.key]);
      if (onBoardSync && rr.stopsAttached) {
        const nameForBoard = rr.routeName || name;
        if (nameForBoard && !isHashLikeId(nameForBoard)) {
          try { await onBoardSync({ routeName: nameForBoard, orderedStopNbrs: r.order.map(String), unplannedStopNbrs: [], driverName: rr.driverApplied ? (s.driverName || null) : null }); } catch { /* the server's own stamp is the primary */ }
        }
      }
      showToast(rr.warning
        ? `⚠ ${rr.warning}`
        : `✓ Route ${rr.routeName || name} created in NuVizz with ${rr.stopsAttached ?? r.order.length} stop(s)${rr.driverApplied ? ` · ${s.driverName || 'driver'} assigned` : ''}${rr.dispatched ? ' · dispatched' : ''}.`);
    }
  };
  const onPanelSave = async () => {
    const pending = dirtyRoutes.filter((r) => r.pendingCreate);
    const { loads, warnings } = buildBoardPayload();
    if (!pending.length && !loads.length) { showToast(warnings[0] || 'No changes to save.'); return; }
    if (!liveMode) { showToast(`Beta — nothing sent (${pending.length + loads.length} load(s) simulated).`); return; }
    // Beta returns above, so everything below is a REAL write.
    //
    // ORDER MATTERS: the EXISTING-load saves run FIRST, then the pending creates. A stop
    // dragged off a live load onto a new-route card is still planned on the source until that
    // load's save unplans it — created first, the new route's already-planned guard would
    // refuse the whole create. Saved first, the stop is unplanned by the time the create's
    // guard reads it, so the one Save click covers the whole move.
    if (loads.length) {
      const cancels = cancelsIn(loads);
      if (cancels.length) {
        setCancelGuard({ loads, warnings, cancels });
        if (pending.length) showToast('⚠ New-route card(s) not sent yet — decide the route cancellation above first, then Save again.');
        return;
      }
      await sendBoardSave(loads, warnings);
    }
    if (pending.length) await sendPendingCreates(pending);
  };

  const markSaved = (keys) => setBaselines((prev) => {
    const n = { ...prev };
    for (const k of keys) { const r = wbRoutes.find((x) => x.key === k); if (r) n[k] = r.order.slice(); }
    return n;
  });

  // Runs the real write. Called directly by onPanelSave with { loads, clientOpId } now that
  // the confirm popup is gone (falls back to the `confirm` state if ever called without args).
  const onPanelConfirm = async (commitArg) => {
    const { loads, clientOpId } = commitArg || confirm || {};
    if (!loads) return;
    if (!liveMode) { setConfirm(null); showToast(`Beta — nothing sent (${loads.length} load(s) simulated).`); return; }
    // This Save supersedes any in-flight verification loop for the same cards (see verifyGenRef).
    for (const L of loads) { const k = L.__key ?? L.routeName ?? L.loadNbr ?? L.loadId; if (k) verifyGenRef.current.set(k, (verifyGenRef.current.get(k) || 0) + 1); }
    setBusy(true);
    const res = await callWrite('commitBoard', { loads, date: boardDate || undefined, origin: savedShipFrom(), useRwb: true }, { dryRun: false, clientOpId, createdBy: 'dispatcher' });
    setBusy(false); setConfirm(null);
    const resLoads = res.result?.loads || [];
    const orphaned = res.result?.orphaned || [];
    // Map each result back to its Compare-card key (the routeName) so markSaved / staged-clear and
    // the toast use the friendly name, not "DAVIS…". Join by loadNbr OR loadId: the server may echo
    // a loadNbr it resolved from the loadId (load/static/info) that differs from what we sent (or we
    // sent none), so loadId is the stable join on that fallback path.
    const toKey = new Map();
    for (const l of loads) {
      const k = l.__key ?? l.routeName ?? l.loadNbr ?? l.loadId;   // the actual Compare-card key
      if (l.loadNbr != null) toKey.set('nbr:' + String(l.loadNbr), k);
      if (l.loadId != null) toKey.set('id:' + String(l.loadId), k);
    }
    // Resolve a result back to its card key by loadNbr OR loadId. If neither maps (server echoed an
    // id we never sent), return null and DROP it — never markSaved a bare loadNbr that isn't a card
    // key (that silently no-ops markSaved and leaves the card dirty forever / mislabels the toast).
    const keyOf = (l) => toKey.get('nbr:' + String(l.loadNbr)) ?? toKey.get('id:' + String(l.loadId))
      // Retarget-proof join (audit C8): after a recurring-instance retarget the result carries
      // the TWIN's identity — the server now echoes what we SENT, which always joins.
      ?? toKey.get('nbr:' + String(l.requestedLoadNbr)) ?? toKey.get('id:' + String(l.requestedLoadId)) ?? null;
    const okKeys = resLoads.filter((l) => l.ok).map(keyOf).filter(Boolean);
    let boardSyncMissing = 0; // stops the board write-through couldn't find on ANY recent day's cache
    if (okKeys.length) {
      markSaved(okKeys);
      setStaged((p) => { const n = { ...p }; for (const k of okKeys) delete n[k]; return n; });
      // Clear each saved route's `removed` list — otherwise a later edit re-sends the already-unplanned
      // stops (a stale removeStopNbrs) on the next Save. Via a prop: wbRoutes' setter lives in
      // RoutingScreen, NOT here — referencing it directly threw a ReferenceError that killed the
      // rest of this handler (no toast/orphan warning) on every successful LIVE save.
      if (onClearRemoved) onClearRemoved(okKeys);
    }
    // Board write-through (#361): each load CONFIRMED in-band gets its verified plan patched
    // straight into the board cache (Firestore-only, zero NuVizz calls) + the local overlay —
    // the board flips to planned immediately instead of waiting out the next scan.
    // DELIBERATELY OUTSIDE the okKeys gate and DECLARATIVE over the card's full current order:
    // the old delta-only version silently skipped a save whenever the result couldn't be joined
    // back to a card key or the payload carried no order change (driver-only re-save) — and a
    // skipped sync is exactly how a saved route kept LOOKING unbuilt (Denis/MONE). The RWB save
    // is declarative over the card's order, so on a confirmed save card.order IS the truth.
    if (onBoardSync) {
      const syncPromises = [];
      for (const l of resLoads) {
        // A FAILED verify that still confirmed MEMBERSHIP carries NuVizz's observedOrder — write
        // the board through with that TRUTH so the board can't keep showing a landed stop as
        // unplanned once the card closes (SCOTT/SHP29379: the false ✗ skipped the sync entirely
        // and the stop read unplanned-but-actually-planned until the next healthy scan).
        if (!l.ok && !l.pending && Array.isArray(l.observedOrder) && l.observedOrder.length) {
          const kf = keyOf(l);
          const Lf = loads.find((x) => (x.__key ?? x.routeName ?? x.loadNbr ?? x.loadId) === kf)
            ?? (loads.length === 1 ? loads[0] : null);
          const nameF = Lf?.routeName || loadDisplayName(kf) || String(kf || l.loadNbr || '');
          // Only a HUMAN route name may stamp the board — a hex key / load number as routeName
          // grouped rows under an identity nothing else matches (audit C5-class).
          if (nameF && !isHashLikeId(nameF)) syncPromises.push(onBoardSync({ routeName: nameF, orderedStopNbrs: l.observedOrder.map(String), unplannedStopNbrs: [], driverName: null }));
          continue;
        }
        if (!l.ok || l.pending) continue; // pending imports sync on their verified read-back below
        const k = keyOf(l);
        const L = loads.find((x) => (x.__key ?? x.routeName ?? x.loadNbr ?? x.loadId) === k)
          ?? (loads.length === 1 ? loads[0] : null); // single-load save: echo mismatch can't mislead
        const cardKey = k ?? L?.__key ?? null;
        const card = cardKey != null ? wbRoutes.find((x) => x.key === cardKey) : null;
        const ordered = ((L?.orderedStopNbrs?.length ? L.orderedStopNbrs : null) ?? card?.order ?? []).map(String);
        // Sync-unplan ONLY removals of stops this card STARTED with (the baseline = what the
        // load actually held at open). A GHOST — a stale-unplanned stop the dispatcher pulled
        // onto the card and then removed — was never on this load, so the save never unplanned
        // it in NuVizz; stamping it board-unplanned here wrote a write-grace-protected WRONG
        // state that a rescan then defended (SHP29343/UNITE MEDICAL: planned on TRAILER 1 all
        // along, but staged-removed from a FRYE card → cemented unplanned on our board).
        const base = new Set((baselines[cardKey] || []).map(String));
        // Cross-card move race (audit C4): the per-load syncs fire concurrently, so a stop
        // removed from card A and planned onto card B in the SAME Save could land in either
        // order. Planned wins — exclude anything any green load in this batch planned.
        const batchPlanned = new Set(resLoads.filter((x) => x.ok).flatMap((x) => {
          const kx = keyOf(x);
          const Lx = loads.find((y) => (y.__key ?? y.routeName ?? y.loadNbr ?? y.loadId) === kx);
          return (Lx?.orderedStopNbrs || []).map(String);
        }));
        const removed = (L?.removeStopNbrs || []).map(String).filter((nbr) => base.has(nbr) && !batchPlanned.has(nbr));
        if (!ordered.length && !removed.length) {
          // eslint-disable-next-line no-console
          console.warn('[board-sync] skipped — could not resolve any stops for a confirmed load', { loadNbr: l?.loadNbr ?? null, loadId: l?.loadId ?? null, cardKey });
          continue;
        }
        const driverApplied = (l.steps || []).some((s) => s.op === 'assignDriver' && s.ok);
        syncPromises.push(onBoardSync({
          routeName: L?.routeName || card?.name || loadDisplayName(cardKey) || String(cardKey || ''),
          orderedStopNbrs: ordered,
          unplannedStopNbrs: removed,
          driverName: driverApplied ? (L?.driverName || null) : null,
        }));
      }
      // Surface a write-through miss instead of discarding the result — a silent
      // {patched:0, missing:N} is how a saved route could LOOK unbuilt on the board
      // even though NuVizz took it (the "built Denis's route, closed it, gone" case).
      const syncs = (await Promise.all(syncPromises)).filter(Boolean);
      boardSyncMissing = syncs.reduce((n, r) => n + (Number(r?.missing) || 0), 0);
    }
    // Honest reporting: a load only "saved" if its result has a SUCCESSFUL step (an actual NuVizz
    // call). A load that returns ok:true with no steps was a no-op — never report it as saved.
    const fired = resLoads.filter((l) => l.ok && (l.steps || []).some((s) => s.ok)).length;
    const noop = resLoads.filter((l) => l.ok && !(l.steps || []).some((s) => s.ok)).length;
    const cancelled = resLoads.filter((l) => (l.steps || []).some((s) => s.cancelledRoute)).length;
    // A confirmed cancel leaves the card pointing at a route that no longer exists in NuVizz —
    // close it, so an empty shell can't sit in Compare inviting stops to be dragged onto a dead
    // load (a Save against it would resolve the cancelled instance, or worse, a same-named twin).
    // Only on the POSITIVE confirmation (steps[].cancelledRoute — set server-side when
    // cancelResponseConfirms accepted NuVizz's own cancellation notice AND the remove succeeded);
    // a failed or refused cancel keeps its card open with the removals still staged for Undo.
    if (onClose) {
      for (const l of resLoads) {
        if (l.ok && (l.steps || []).some((s) => s.cancelledRoute)) { const k = keyOf(l); if (k) onClose(k); }
      }
    }
    // IMPORT-engine loads the server fired but couldn't CONFIRM inside its window come back
    // `pending` — not failures. We verify them below (getLoad read-backs + a re-Save nudge).
    const pendings = resLoads.filter((l) => l.pending && l.loadNbr && Array.isArray(l.requestedOrder));
    const failed = resLoads.filter((l) => !l.ok && !l.pending);
    const orphanMsg = orphaned.length ? ` ⚠ ${orphaned.length} stop(s) now UNPLANNED — re-Save to reroute.` : '';
    const syncMsg = boardSyncMissing ? ` ⚠ board didn't update for ${boardSyncMissing} stop(s) (NuVizz HAS the save) — it catches up on the next scan.` : '';
    const cancelMsg = cancelled ? ` · ${cancelled} route(s) emptied/cancelled` : '';
    const noopMsg = noop ? ` · ${noop} no change` : '';
    // Per-action NuVizz call count, so you can reconcile each action against the real
    // Route Workbench HAR. totalCalls (res.callsUsed) = EXACT calls this save made
    // (incl. any cold-instance login + safety re-reads); portalCalls = just the RWB
    // portal writes (preview/save/validate/add) — the ones that show in the RWB HAR.
    const portalCalls = resLoads.reduce((n, l) => n + ((l.calls?.rwb || 0) + (l.calls?.rwbAdd || 0)), 0);
    const totalCalls = typeof res.callsUsed === 'number' ? res.callsUsed : null;
    const callsMsg = totalCalls != null
      ? ` · ${totalCalls} NuVizz call${totalCalls === 1 ? '' : 's'}${portalCalls ? ` (${portalCalls} RWB portal)` : ''}`
      : (portalCalls ? ` · ${portalCalls} RWB-portal call${portalCalls === 1 ? '' : 's'}` : '');
    if (failed.length) {
      // Full diagnostic to the console: the EXACT payload we sent (incl. each load's loadNbr) plus
      // NuVizz's per-load result — so a "load not found" can be read/copied back verbatim.
      // eslint-disable-next-line no-console
      console.error('[commitBoard] save failed', { sent: loads, result: res.result, error: res.error });
      // Lead with the CARD's route name (the way the dispatcher knows the load), keeping the
      // number for the portal. Server-side messages name holder loads the same way.
      const cardName = (l) => {
        const k = keyOf(l);
        const r = wbRoutes.find((x) => x.key === k);
        const nm = r?.name || loadDisplayName(k);
        // A card the server couldn't identify echoes nothing to join on, and this printed the
        // literal "null:" in front of its error. Name the condition instead.
        if (k == null || String(k).trim() === '' || String(k) === 'null') return nm ? String(nm) : 'a card with no load number';
        return nm && nm !== String(k) ? `${nm} (${k})` : String(k);
      };
      showToast(`✗ ${failed.map((l) => `${cardName(l)}: ${l.error || (l.steps || []).filter((s) => !s.ok).map((s) => s.error).join('; ')}`).join(' | ') || res.error || 'write failed'}${orphanMsg}`);
    } else if (!pendings.length) {
      if (res.ok) showToast(fired || cancelled ? `✓ ${fired} load(s) saved to NuVizz${cancelMsg}${noopMsg}${callsMsg}.${orphanMsg}${syncMsg}` : `Nothing to send — no changes actually fired.${orphanMsg}`);
      else showToast(`✗ ${res.error || 'write failed'}${orphanMsg}`);
    }
    if (pendings.length) verifyPendingImports(pendings, loads, keyOf);
  };

  // ── IMPORT-engine convergence, client-side ────────────────────────────────────
  // The import is ASYNC in NuVizz and prod's worker takes ~30-90s to seat an order (measured
  // live Jul 2 2026), so the CLIENT owns the wait: poll getLoad on a BACKOFF (6/10/15/25/25s —
  // ~5 polls before any write) comparing the REAL delivery order (to.seq) to what we sent,
  // NORMALIZED (trim/case/zero-padding) on both sides. Escalation only after the polls:
  //   1. ONE same-order re-send (a lost import is rare but possible).
  //   2. ONE reverse+forward UNSTICK (the §10.1 cure for the worker's stuck-append state —
  //      the Jul 2 session proved same-direction re-sends do NOT clear it: 9 imports, the two
  //      membership-changed stops appended to the tail every time).
  // Every poll's read-back is console-logged; the old cadence (poll every 6s + re-Save at 18s
  // and 45s) burned ~27 calls per Save chasing the worker's lag — this ladder is ~4-8 typical.
  const IMPORT_POLL_SCHEDULE_MS = [6000, 10000, 15000, 25000, 25000];   // before the re-send
  const IMPORT_POST_SEND_POLLS_MS = [10000, 20000, 30000];              // after re-send / unstick
  const normNbr = (v) => { const s = String(v ?? '').trim().toUpperCase(); const t = s.replace(/^0+(?=.)/, ''); return t || s; };
  const verifyPendingImports = async (pendings, sentLoads, keyOf) => {
    const names = pendings.map((l) => loadDisplayName(keyOf(l)) || keyOf(l) || l.loadNbr).join(', ');
    showToast(`⏳ Import sent for ${names} — verifying the stop order in NuVizz…`);
    const remaining = new Map(pendings.map((l) => [String(l.loadNbr), l]));
    // Generation guard: a NEW Save for one of these cards supersedes this loop — a stale loop's
    // re-send would otherwise re-impose the OLD order over the dispatcher's newer edit.
    const myGen = new Map();
    for (const l of pendings) { const k = keyOf(l); if (k) myGen.set(k, verifyGenRef.current.get(k)); }
    const superseded = (l) => { const k = keyOf(l); return k && verifyGenRef.current.get(k) !== myGen.get(k); };
    const seenLog = new Map();   // loadNbr → every read-back order (forensics, directive #1)
    let infoReads = 0;           // per-save anatomy (directive #4): client-side load/info count

    const pollOnce = async (label) => {
      for (const [nbr, l] of [...remaining]) {
        if (superseded(l)) { remaining.delete(nbr); continue; }   // a newer Save owns this card now
        try {
          const res = await callWrite('getLoad', { loadNbr: nbr }, { dryRun: false });
          infoReads++;
          const stops = (res.result?.load?.stops || []).filter((s) => String(s.stopType || 'DO').toUpperCase() !== 'PU');
          // STRICT: a mid-rebuild read can list the stops before their to.seq is assigned —
          // never trust a comparison where any delivery lacks a real numeric seq.
          const seqsOk = stops.every((s) => s.stopSeq != null && Number.isFinite(Number(s.stopSeq)));
          const seen = stops.slice()
            .sort((a, b) => (Number(a.stopSeq ?? 1e9)) - (Number(b.stopSeq ?? 1e9)))
            .map((s) => String(s.stopNbr));
          if (!seenLog.has(nbr)) seenLog.set(nbr, []);
          seenLog.get(nbr).push(seen);
          const want = l.requestedOrder.map(String);
          // eslint-disable-next-line no-console
          console.log(`[import-verify] ${label} ${nbr}`, { requested: want, readBack: seen, seqsOk });
          const match = seqsOk && seen.length === want.length && seen.every((n, i) => normNbr(n) === normNbr(want[i]));
          if (match) {
            remaining.delete(nbr);
            const k = keyOf(l);
            if (k) {
              markSaved([k]);
              if (onClearRemoved) onClearRemoved([k]);
              // Board write-through (#361): the read-back that just CONFIRMED this order is the
              // truth — patch it into the board cache now (Firestore-only). Driver stays null:
              // assignment is deferred on the pending path until the follow-up Save.
              if (onBoardSync) {
                const L = sentLoads.find((x) => (x.__key ?? x.routeName ?? x.loadNbr ?? x.loadId) === k);
                // Ghost guard (same rule as the main sync): only removals of stops the card
                // STARTED with may stamp board-unplanned — see the baseline filter above.
                const base2 = new Set((baselines[k] || []).map(String));
                onBoardSync({
                  routeName: L?.routeName || loadDisplayName(k) || String(k),
                  orderedStopNbrs: l.requestedOrder.map(String),
                  unplannedStopNbrs: (L?.removeStopNbrs || []).map(String).filter((nbr) => base2.has(nbr)),
                  driverName: null,
                });
              }
              const hasStaged = !!(staged[k] && ((staged[k].driverId != null && staged[k].driverId !== '') || staged[k].dispatch));
              showToast(`✓ ${loadDisplayName(k) || k}: stop order confirmed in NuVizz.${hasStaged ? ' Save again to apply the driver/dispatch.' : ''}`);
            }
          }
        } catch { /* transient read failure — keep polling */ }
      }
    };
    // ORDER-ONLY escalation Save: driver/dispatch STRIPPED (they'd fire server-side on a
    // converged re-send, then the "Save again" follow-up would DOUBLE-dispatch) and the
    // server-resolved loadNbr injected so it can't wander back into the resolution ladder.
    const escalate = async (label, unstick) => {
      const again = sentLoads
        .filter((L) => [...remaining.values()].some((l) => !superseded(l) && keyOf(l) === (L.__key ?? L.routeName ?? L.loadNbr ?? L.loadId)))
        .map((L) => {
          const { driverId, driverName, dispatch, ...orderOnly } = L;
          const match = [...remaining.values()].find((l) => keyOf(l) === (L.__key ?? L.routeName ?? L.loadNbr ?? L.loadId));
          return { ...orderOnly, date: boardDate || undefined, loadNbr: match?.loadNbr || L.loadNbr };
        });
      if (!again.length) return;
      // eslint-disable-next-line no-console
      console.log(`[import-verify] escalate: ${label}`, again.map((L) => L.loadNbr));
      try { await callWrite('commitBoard', { loads: again, origin: savedShipFrom(), useImport: true, convergence: unstick ? { unstick: true } : undefined }, { dryRun: false, clientOpId: newClientOpId(), createdBy: 'dispatcher' }); } catch { /* next poll decides */ }
    };

    // Phase A — patient backoff polls (no writes).
    for (const [i, ms] of IMPORT_POLL_SCHEDULE_MS.entries()) {
      if (!remaining.size) break;
      await new Promise((r) => setTimeout(r, ms));
      await pollOnce(`poll ${i + 1}/${IMPORT_POLL_SCHEDULE_MS.length}`);
    }
    // Phase B — ONE same-order re-send, then more patient polls.
    if (remaining.size) {
      await escalate('re-send same order', false);
      for (const [i, ms] of IMPORT_POST_SEND_POLLS_MS.entries()) {
        if (!remaining.size) break;
        await new Promise((r) => setTimeout(r, ms));
        await pollOnce(`post-resend poll ${i + 1}/${IMPORT_POST_SEND_POLLS_MS.length}`);
      }
    }
    // Phase C — ONE reverse+forward unstick (server does both imports in one invocation).
    if (remaining.size) {
      await escalate('reverse+forward unstick', true);
      for (const [i, ms] of IMPORT_POST_SEND_POLLS_MS.entries()) {
        if (!remaining.size) break;
        await new Promise((r) => setTimeout(r, ms));
        await pollOnce(`post-unstick poll ${i + 1}/${IMPORT_POST_SEND_POLLS_MS.length}`);
      }
    }
    // eslint-disable-next-line no-console
    console.log('[import-verify] anatomy: client load/info reads this save =', infoReads);
    if (remaining.size) {
      const stuck = [...remaining.values()].map((l) => loadDisplayName(keyOf(l)) || keyOf(l) || l.loadNbr).join(', ');
      // Forensic trail to the console: what we asked for, what the server's import steps said
      // (incl. the exact sent header + NuVizz's verbatim ack), and EVERY read-back we saw.
      // eslint-disable-next-line no-console
      console.error('[import-verify] never converged', {
        pending: [...remaining.values()].map((l) => ({ loadNbr: l.loadNbr, requestedOrder: l.requestedOrder, serverSteps: l.steps, readBacks: seenLog.get(String(l.loadNbr)) ?? [] })),
      });
      showToast(`✗ ${stuck}: NuVizz still isn't showing the sent order after ~4 minutes (incl. one re-send + one reverse-unstick) — check the load in the portal, then Save again (safe to repeat).`);
    }
  };

  // Gate on LIVE_WRITE_FLAG: with the feature off, a dirty card must close normally (the guard
  // modal is flag-gated, so without this an order-edited card would set unrenderable state = stuck).
  const guardedClose = (key) => { const r = wbRoutes.find((x) => x.key === key); if (LIVE_WRITE_FLAG && r && isDirty(r)) setCloseGuard({ kind: 'one', key }); else onClose(key); };
  const guardedCloseAll = () => { if (LIVE_WRITE_FLAG && dirtyRoutes.length) setCloseGuard({ kind: 'all' }); else onCloseAll(); };
  const doClose = () => { if (closeGuard?.kind === 'all') onCloseAll(); else if (closeGuard?.key) onClose(closeGuard.key); setCloseGuard(null); };

  return (
    <div className="flex flex-col h-full min-h-0">
      {/* Header WRAPS instead of clipping: the button group used to be shrink-0, so flex
          never squeezed it, flex-wrap never triggered, and with one narrow card open the
          engine/LIVE/Save/Back buttons silently overflowed past the panel edge — they
          looked MISSING. min-w-0 + wrap keeps every control visible at any panel width. */}
      <div className="flex items-center justify-between gap-2 px-2 py-1.5 border-b shrink-0 bg-white flex-wrap">
        <span className="font-semibold text-slate-800 text-[13px] shrink-0">Compare <span className="text-slate-400 text-[11px]">({wbRoutes.length}/3)</span></span>
        <div className="flex items-center gap-1.5 min-w-0 flex-wrap justify-end">
          {/* One-click "send the current map selection into this load" per open route (#258).
              Only shown when something is selected — otherwise the buttons would be dead. With two
              loads open you get two buttons, so you can route the selection to either in one click. */}
          {selectedCount > 0 && onSendSelection && wbRoutes.map((r) => (
            <button
              key={r.key}
              onClick={() => onSendSelection(r.key)}
              title={`Add the ${selectedCount} selected stop${selectedCount === 1 ? '' : 's'} to ${loadDisplayName(r.key) || 'this load'}`}
              className="flex items-center gap-1 text-[11px] font-semibold px-2 py-1 rounded border border-emerald-600 bg-emerald-600 text-white hover:bg-emerald-700 min-w-0"
            >
              <ArrowRight size={13} className="shrink-0" /> <span className="truncate max-w-[130px]">{loadDisplayName(r.key) || 'Load'}</span> ({selectedCount})
            </button>
          ))}
          {/* Ninja is armed from the on-map tool (left edge), not here — the dispatcher asked to drop
              the redundant header button. The active-state banner below still shows when it's on. */}
          {LIVE_WRITE_FLAG && dirtyRoutes.length > 0 && (
            <button
              onClick={onPanelSave}
              disabled={busy}
              title={liveMode ? 'Save all staged changes to NuVizz' : 'Save (Beta — preview only, nothing sent)'}
              className={`inline-flex items-center gap-1 text-[11px] font-semibold px-2 py-1 rounded disabled:opacity-60 ${liveMode ? 'bg-red-600 text-white hover:bg-red-700' : 'bg-blue-600 text-white hover:bg-blue-700'}`}
            >
              <Save size={12} /> {busy ? '…' : `Save (${dirtyRoutes.length})`}
            </button>
          )}
          {/* Engine indicator, not a picker — RWB is the only Save engine now (see the pin above). */}
          {LIVE_WRITE_FLAG && (
            <span
              title="RWB engine — Save sets each load's stop order via the NuVizz Route Workbench portal: 2 SYNCHRONOUS calls per load (preview + save), no async wait, and it references stops BY ID ONLY so freight/address data can't be blanked or cloned. This is the only Save engine; Classic and Import were retired."
              className="inline-flex items-center gap-1 text-[11px] font-bold px-2 py-1 rounded border border-teal-600 bg-teal-600 text-white"
            >
              🔗 RWB
            </span>
          )}
          {LIVE_WRITE_FLAG && (
            <button
              onClick={() => setLiveMode((v) => !v)}
              title={liveMode ? 'LIVE — Save sends writes to NuVizz. Click for Beta (preview only).' : 'BETA — Save only previews (nothing sent). Click to go Live.'}
              className={`inline-flex items-center gap-1 text-[11px] font-bold px-2 py-1 rounded border ${liveMode ? 'border-red-600 bg-red-600 text-white' : 'border-slate-300 bg-white text-slate-600 hover:bg-slate-50'}`}
            >
              {liveMode ? '● LIVE' : '○ Beta'}
            </button>
          )}
          <button onClick={guardedCloseAll} className="text-[11px] text-slate-500 hover:text-slate-800 underline">Back to Setup</button>
        </div>
      </div>
      {LIVE_WRITE_FLAG && toast && (
        <div className="px-2 py-1 text-[11px] bg-slate-800 text-white shrink-0 flex items-start justify-between gap-2">
          {/* Wrap, never truncate: a Save refusal must be readable in full (which stop, which load holds it, what to do). */}
          <span className="whitespace-pre-wrap break-words min-w-0">{toast}</span>
          <button onClick={() => setToast(null)} className="text-slate-300 hover:text-white shrink-0" aria-label="Dismiss"><X size={12} /></button>
        </div>
      )}
      {ninjaMode && (
        <div className="px-2 py-1 text-[11px] bg-amber-50 border-b border-amber-200 text-amber-800 shrink-0 flex items-center gap-1"><NinjaIcon size={13} /><span>Ninja on — clicking a stop adds it to <b>{activeKey || '—'}</b>{wbRoutes.length > 1 ? ' (use the radio on a card to switch target)' : ''}.</span></div>
      )}
      <div className={`flex-1 min-h-0 gap-2 p-2 ${isMobile ? 'flex flex-col overflow-y-auto' : 'flex overflow-x-auto'}`}>
        {wbRoutes.map((r) => (
          <RoutingWorkbenchCard
            key={r.key}
            route={r}
            stopById={lookup}
            otherKeys={wbRoutes.map((x) => x.key).filter((k) => k !== r.key)}
            ninjaMode={ninjaMode}
            isActive={activeKey === r.key}
            onSetActive={() => onSetActive(r.key)}
            onResequence={(strat) => onResequence(r.key, strat)}
            onCollapse={() => onCollapse(r.key)}
            onClose={() => guardedClose(r.key)}
            onMoveStop={(stopNbr, toKey) => onMoveStop(r.key, stopNbr, toKey)}
            onDropStop={onDropStop}
            onRemoveStop={(stopNbr) => onRemoveStop(r.key, stopNbr)}
            onRemoveAllStops={onRemoveAllStops}
            onUndoRemove={(stopNbr) => onUndoRemove(r.key, stopNbr)}
            onOpenStop={onOpenStop}
            onPrintManifest={onPrintManifest}
            roster={roster}
            rosterError={rosterError}
            staged={staged[r.key]}
            onStage={(patch) => setStageFor(r.key, patch)}
            dirty={isDirty(r)}
            isMobile={isMobile}
            liveWrite={liveWrite}
          />
        ))}
      </div>
      {/* The "Send to NuVizz" confirmation popup was removed — Save commits directly (onPanelSave).
          The ONE popup left is this: a Save that would CANCEL a route (delete it in NuVizz) is
          unrecoverable from this app, so it asks first. Red, names every route and the order count,
          and defaults to the safe side — backdrop click, Escape and "Keep the route" all cancel;
          only the explicit button sends. Busy-disabled so a double-tap can't double-fire the write. */}
      {cancelGuard && (
        <div
          className="fixed inset-0 z-[70] bg-black/50 flex items-center justify-center p-4"
          role="dialog" aria-modal="true" aria-label="Confirm route cancellation"
          onMouseDown={(e) => { if (e.target === e.currentTarget && !busy) setCancelGuard(null); }}
        >
          <div className="bg-white rounded-lg shadow-xl w-full max-w-md max-h-[85dvh] flex flex-col">
            <div className="px-4 py-3 border-b font-semibold text-red-700 flex items-center gap-2">
              <AlertTriangle size={16} className="text-red-600" />
              {cancelGuard.cancels.length === 1 ? 'This DELETES a route' : `This DELETES ${cancelGuard.cancels.length} routes`}
            </div>
            <div className="px-4 py-3 overflow-y-auto text-sm text-slate-700 space-y-2">
              <div className="text-[13px] text-red-800 bg-red-50 border border-red-200 rounded p-2">
                {cancelSummary(cancelGuard.cancels, (c) => loadDisplayName(c.routeName, c.loadNbr) || 'this load')}
              </div>
              <ul className="list-disc pl-5 space-y-0.5">
                {cancelGuard.cancels.map((c, i) => (
                  <li key={i}>
                    <b>{loadDisplayName(c.routeName, c.loadNbr) || 'Unnamed load'}</b> — every order removed
                    {c.orderCount ? ` (${c.orderCount} order${c.orderCount === 1 ? '' : 's'} back to Un-Planned)` : ''}
                  </li>
                ))}
              </ul>
              {/* Other loads in the same Save are NOT cancelled — say so, so "Cancel the route(s)"
                  never reads as "throw away everything I staged". */}
              {cancelGuard.loads.length > cancelGuard.cancels.length && (
                <div className="text-[12px] text-slate-500">
                  The other {cancelGuard.loads.length - cancelGuard.cancels.length} load(s) in this Save are unaffected and will be saved normally.
                </div>
              )}
            </div>
            <div className="px-4 py-3 border-t flex items-center justify-end gap-2">
              <button
                onClick={() => setCancelGuard(null)}
                disabled={busy}
                className="px-3 py-1.5 text-sm rounded border border-slate-300 text-slate-600 hover:bg-slate-50 disabled:opacity-60"
              >
                Keep the {cancelGuard.cancels.length === 1 ? 'route' : 'routes'}
              </button>
              <button
                onClick={async () => { const g = cancelGuard; setCancelGuard(null); await sendBoardSave(g.loads, g.warnings); }}
                disabled={busy}
                className="px-3 py-1.5 text-sm rounded font-semibold text-white bg-red-600 hover:bg-red-700 disabled:opacity-60"
              >
                {busy ? 'Sending…' : `Cancel the ${cancelGuard.cancels.length === 1 ? 'route' : 'routes'}`}
              </button>
            </div>
          </div>
        </div>
      )}
      {LIVE_WRITE_FLAG && closeGuard && (
        <div className="fixed inset-0 z-[60] bg-black/40 flex items-center justify-center p-4" onMouseDown={(e) => { if (e.target === e.currentTarget) setCloseGuard(null); }}>
          <div className="bg-white rounded-lg shadow-xl w-full max-w-sm">
            <div className="px-4 py-3 border-b font-semibold text-slate-800 flex items-center gap-2"><AlertTriangle size={16} className="text-amber-500" /> Unsaved changes</div>
            <div className="px-4 py-3 text-sm text-slate-600">{closeGuard.kind === 'all' ? `${dirtyRoutes.length} load(s) have` : 'This load has'} staged changes not yet saved to NuVizz. Close without saving?</div>
            <div className="px-4 py-3 border-t flex items-center justify-end gap-2">
              <button onClick={() => setCloseGuard(null)} className="px-3 py-1.5 text-sm rounded border border-slate-300 text-slate-600 hover:bg-slate-50">Keep editing</button>
              <button onClick={doClose} className="px-3 py-1.5 text-sm rounded font-semibold text-white bg-slate-700 hover:bg-slate-800">Discard &amp; close</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// Routing panel-settings menu — a gear button opening a small popover of panel on/off toggles
// (`panels`: { key, label, on, setOn }) plus optional single-choice view switchers
// (`views`: { key, label, value, setValue, options: [{ value, label }] }).
function RoutingSettingsMenu({ panels = [], views = [], actions = [], dropUp = false }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    if (!open) return;
    const onDoc = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    const onKey = (e) => { if (e.key === 'Escape') setOpen(false); };
    document.addEventListener('mousedown', onDoc);
    window.addEventListener('keydown', onKey);
    return () => { document.removeEventListener('mousedown', onDoc); window.removeEventListener('keydown', onKey); };
  }, [open]);
  return (
    <div className="relative shrink-0" ref={ref}>
      <button onClick={() => setOpen((o) => !o)} className={`p-1.5 rounded border ${open ? 'border-slate-400 bg-slate-100' : 'border-slate-300 hover:bg-slate-50'} text-slate-600`} title="Panel settings" aria-label="Panel settings" aria-expanded={open}>
        <Settings size={16} />
      </button>
      {open && (
        <div className={`absolute right-0 z-30 w-60 bg-white border border-slate-300 rounded-lg shadow-xl p-2 text-[12px] ${dropUp ? 'bottom-full mb-1' : 'mt-1'}`}>
          {views.map((v) => (
            <div key={v.key} className="mb-1.5">
              <div className="font-semibold text-slate-700 px-1 pb-1 mb-1 border-b">{v.label}</div>
              {v.options.map((o) => (
                <label key={o.value} className="flex items-center gap-2 px-1 py-1.5 rounded hover:bg-slate-50 cursor-pointer">
                  <input type="radio" name={`rt-view-${v.key}`} checked={v.value === o.value} onChange={() => v.setValue(o.value)} />
                  <span className="text-slate-700">{o.label}</span>
                </label>
              ))}
            </div>
          ))}
          {panels.length > 0 && (
            <>
              <div className="font-semibold text-slate-700 px-1 pb-1 mb-1 border-b">Panels</div>
              {panels.map((p) => (
                <label key={p.key} className="flex items-center justify-between gap-2 px-1 py-1.5 rounded hover:bg-slate-50 cursor-pointer">
                  <span className="text-slate-700">{p.label}</span>
                  <input type="checkbox" checked={p.on} onChange={(e) => p.setOn(e.target.checked)} />
                </label>
              ))}
            </>
          )}
          {actions.length > 0 && (
            <div className="mt-1 pt-1 border-t flex flex-col gap-1">
              {actions.map((a) => (
                <button key={a.key} onClick={() => { a.onClick(); setOpen(false); }} className="text-left px-1 py-1.5 rounded text-slate-600 hover:bg-slate-50">{a.label}</button>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function RoutingSelectionFloatPanel({ selectedStops, notes, tractorLocs, onRemove, onClearAll, onOpenStop, onClose, isMobile }) {
  // Compact window from the naive (zoneless) schedule ISO — parse the clock straight off the
  // string so there's no local-timezone drift. "8:00a", "8:00a–8:00p".
  const fmtWin = (iso) => {
    const m = String(iso || '').match(/[T ](\d{2}):(\d{2})/);
    if (!m) return '';
    let h = +m[1]; const ap = h >= 12 ? 'p' : 'a'; h = h % 12 || 12;
    return `${h}:${m[2]}${ap}`;
  };
  const rows = useMemo(() => selectedStops.map((s) => {
    const f = fmtWin(s.scheduledFrom), t = fmtWin(s.scheduledTo);
    return {
      id: String(s.stopNbr), stop: s,
      pro: s.primaryPro || s.pro || s.stopNbr || '',
      type: ((s.stopType || '') === 'PU') ? 'PU' : 'DO',
      location: s.businessName || s.addr1 || String(s.stopNbr),
      city: s.city || '', zip: s.zip || '',
      win: f && t ? `${f}–${t}` : (f || t || ''),
      winSort: s.scheduledFrom || '',    // sort the window by the real (zoneless) start time
      weight: Number(s.weight) || 0,
      pallets: Number(s.cartons) || 0,   // NuVizz totalCartons = real skids/pallets
      loose: Number(s.volume) || 0,      // NuVizz volume = loose-piece count
      // Green = EVERY signal the map paints green for, not just the dispatcher-set
      // eligibility: the manual green paint, the "Tractor trailer friendly" badge, and the
      // proven lime "a tractor has delivered here" (tractor_locations). Only checking the
      // manual paint left badge/proven-green stops un-highlighted (Chad: "4 of these are
      // painted... rows are not highlighted"). An explicit box-only mark still wins as red
      // — never green a stop the dispatcher marked off-limits.
      tractorOk: (() => {
        const note = notes?.get?.(s.matchKey) || null;
        if (note?.vehicle_eligibility === 'box_only') return false;
        return note?.vehicle_eligibility === 'tractor'
          || getRestrictionBadgeKeys(note).includes('tractor_trailer_friendly')
          || !!(tractorLocs && tractorLocs.has(s.matchKey));
      })(),
    };
  }), [selectedStops, notes, tractorLocs]);
  const tot = rows.reduce((a, r) => ({ wt: a.wt + r.weight, plt: a.plt + r.pallets, ls: a.ls + r.loose }), { wt: 0, plt: 0, ls: 0 });
  const { sorted, sortKey, sortDir, toggle } = useSortable(rows, null, 'asc');
  // WIDTH-resizable window (drag the left edge); width persisted; desktop only. Height is always
  // content-driven (capped at 60vh) so the window grows as stops are added and never shows empty
  // white space (#278). 420px is the standard default width.
  const [panelW, setPanelW] = useState(() => { const v = Number(localStorage.getItem('routing.selPanelW')); return v >= 300 ? v : 420; });
  useEffect(() => { try { localStorage.setItem('routing.selPanelW', String(panelW)); } catch { /* ignore */ } }, [panelW]);
  const onResizeDown = (e) => {
    e.preventDefault(); e.stopPropagation();
    const startX = e.clientX, w0 = panelW;
    const move = (ev) => setPanelW(Math.max(300, Math.min(window.innerWidth - 24, w0 + (startX - ev.clientX))));
    const up = () => { document.removeEventListener('pointermove', move); document.removeEventListener('pointerup', up); };
    document.addEventListener('pointermove', move); document.addEventListener('pointerup', up);
  };
  // Compact, click-to-sort header cell (the shared SortableTh is sized for the wider docked tables).
  const Th = ({ label, k, align }) => (
    <th onClick={() => toggle(k)} className={`px-1.5 py-1 cursor-pointer select-none hover:bg-slate-100 ${align === 'right' ? 'text-right' : 'text-left'}`}>
      <span className={`inline-flex items-center gap-0.5 ${align === 'right' ? 'justify-end' : ''}`}>{label}{sortKey === k ? (sortDir === 'asc' ? <ChevronUp size={9} /> : <ChevronDown size={9} />) : null}</span>
    </th>
  );
  return (
    <div
      className={`absolute z-20 bg-white border border-slate-300 rounded-lg shadow-xl flex flex-col ${isMobile ? 'left-2 right-2 top-12 max-h-[45vh]' : 'right-2 top-12 max-w-[calc(100%-1rem)] max-h-[60vh]'}`}
      style={isMobile ? undefined : { width: panelW }}
    >
      <div className="flex items-center justify-between gap-2 px-3 py-1.5 border-b bg-slate-50 rounded-t-lg shrink-0">
        <div className="font-semibold text-[13px] text-slate-800 min-w-0 truncate">
          Selected {rows.length}
          {rows.length > 0 && <span className="text-slate-500 font-normal"> · {tot.plt} plt · {tot.ls} loose · {tot.wt.toLocaleString()} lb</span>}
        </div>
        <div className="flex items-center gap-1 shrink-0">
          {rows.length > 0 && onClearAll && (
            <button onClick={onClearAll} className="text-[11px] font-medium text-slate-500 hover:text-red-600 px-1.5 py-0.5 rounded hover:bg-red-50" title="Clear all selected stops">Clear all</button>
          )}
          <button onClick={onClose} className="text-slate-400 hover:text-slate-700 leading-none p-1" aria-label="Hide selected panel"><X size={16} /></button>
        </div>
      </div>
      {rows.length === 0 ? (
        <div className="px-3 py-3 text-[11px] text-slate-400">No stops selected yet. Tap a stop on the map, or use Add in view / Box / Lasso.</div>
      ) : (
        <div className="overflow-auto flex-1 min-h-0">
          <table className="w-full text-[11px]">
            <thead className="bg-slate-50 sticky top-0 z-10">
              <tr className="text-[9px] uppercase tracking-wide text-slate-500">
                <Th label="Stop#" k="pro" />
                <Th label="Location" k="location" />
                <Th label="Plt" k="pallets" align="right" />
                <Th label="Loose" k="loose" align="right" />
                <Th label="Wt" k="weight" align="right" />
                <Th label="City" k="city" />
                <Th label="Zip" k="zip" />
                <Th label="Type" k="type" />
                <th className="px-1 py-1" />
              </tr>
            </thead>
            <tbody>
              {sorted.map((r) => (
                <tr key={r.id} className={`border-t ${r.tractorOk ? 'bg-green-100 hover:bg-green-200/70' : 'hover:bg-slate-50'}`}>
                  <td className="px-1.5 py-1 whitespace-nowrap"><button onClick={() => onOpenStop && onOpenStop(r.stop)} className="font-mono text-blue-700 hover:underline">{r.pro}</button></td>
                  <td className="px-1.5 py-1 max-w-[150px] truncate" title={r.location}>{r.location}</td>
                  <td className="px-1 py-1 text-right tabular-nums">{r.pallets}</td>
                  <td className="px-1 py-1 text-right tabular-nums">{r.loose}</td>
                  <td className="px-1 py-1 text-right tabular-nums">{r.weight.toLocaleString()}</td>
                  <td className="px-1.5 py-1 max-w-[90px] truncate" title={r.city}>{r.city}</td>
                  <td className="px-1 py-1 whitespace-nowrap text-slate-600">{r.zip}</td>
                  <td className="px-1 py-1"><span className={`text-[9px] font-bold px-1 rounded ${r.type === 'PU' ? 'bg-violet-100 text-violet-700' : 'bg-slate-100 text-slate-600'}`}>{r.type}</span></td>
                  <td className="px-1 py-1"><button onClick={() => onRemove(r.id)} aria-label={`Remove ${r.location} from selection`} className="text-slate-400 hover:text-red-600 leading-none text-base">×</button></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
      {/* Width-resize handle (desktop) — drag the LEFT edge; height stays content-driven (#278). */}
      {!isMobile && (
        <div
          onPointerDown={onResizeDown}
          className="absolute top-0 bottom-0 left-0 w-1.5 cursor-ew-resize hover:bg-slate-200/70 rounded-l-lg"
          title="Drag to resize width"
          style={{ touchAction: 'none' }}
        />
      )}
    </div>
  );
}

// Routing-map view filters — a compact popover in the map's top-right corner that ports the
// dispatch Map's controls to the routing beta: Unplanned-only (hides planned stops), Satellite
// view (hybrid imagery vs the plain roadmap base), and Show routes (draws each load's stops
// connected in delivery sequence). (The old build-version badge lived here; version history now
// lives in the gear settings, since the dispatcher reads the version from the page footer.)
function RoutingMapFilters({ unplannedOnly, setUnplannedOnly, satellite, setSatellite, showRoutes, setShowRoutes, hideLabels, setHideLabels }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    if (!open) return;
    const onDoc = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    const onKey = (e) => { if (e.key === 'Escape') setOpen(false); };
    document.addEventListener('mousedown', onDoc);
    window.addEventListener('keydown', onKey);
    return () => { document.removeEventListener('mousedown', onDoc); window.removeEventListener('keydown', onKey); };
  }, [open]);
  const anyOn = unplannedOnly || showRoutes || !satellite || hideLabels;
  return (
    <div className="absolute top-2 right-2 z-20" ref={ref}>
      <button
        onClick={() => setOpen((o) => !o)}
        className={`flex items-center gap-1 px-2 py-1 rounded border text-[11px] font-semibold shadow-sm ${open || anyOn ? 'border-slate-400 bg-white text-slate-800' : 'border-slate-200 bg-white/90 hover:bg-white text-slate-600'}`}
        aria-expanded={open}
        title="Map filters"
      >
        <Filter size={13} /> Filters
      </button>
      {open && (
        <div className="absolute right-0 mt-1 w-52 bg-white border border-slate-300 rounded-lg shadow-xl px-3 py-1.5 text-[12px]">
          <MapFilterToggle label="Unplanned only" checked={unplannedOnly} onChange={setUnplannedOnly} />
          <MapFilterToggle label="Satellite view" checked={satellite} onChange={setSatellite} />
          <MapFilterToggle label="Hide place labels" checked={hideLabels} onChange={setHideLabels} />
          <MapFilterToggle label="Show routes" checked={showRoutes} onChange={setShowRoutes} />
        </div>
      )}
    </div>
  );
}

// The saved ship-from (New Order tab). NuVizz will not create a route without a full origin —
// it accepts the call and creates nothing — so the create refuses unless name/addr1/city/zip are
// all present, which is stricter than the addr1-only check the board Save uses for its fallback.
function readShipFromOrigin() {
  try {
    const o = JSON.parse(localStorage.getItem(NEWORDER_ORIGIN_KEY) || 'null');
    const ok = o && ['name', 'addr1', 'city', 'zip'].every((k) => String(o[k] ?? '').trim());
    return ok ? o : null;
  } catch { return null; }
}

/**
 * NewRouteModal (§R) — open a LOCAL route card the dispatcher builds onto, sent on Save.
 *
 * MODULE SCOPE, not nested in RoutingScreen: a component re-created on every parent render
 * remounts its inputs, and the text field would lose focus on every keystroke (the same
 * reason OrderField lives at module scope).
 *
 * NOTHING IS SENT FROM THIS FORM (Aug 3). NuVizz refuses a route with no stop node (reason
 * 903), so the old create-empty-then-drag design cannot work. Chad's design instead: the
 * form opens a pending Compare card (local only), orders are dragged on as usual, and SAVE
 * creates the route in NuVizz with the whole stop list riding the one create call. Closing
 * the card before saving simply discards it — nothing ever existed in NuVizz.
 *
 * The card is made for the day the board is ALREADY showing. That is not a shortcut —
 * changing the board date closes every Compare card, so letting this form pick a different
 * day would make a card the date change immediately destroys. To build tomorrow's route,
 * move the board to tomorrow first.
 *
 * No driver field: the pending card carries the ordinary driver dropdown, and the staged
 * assignment rides the same Save that creates the route.
 */
function NewRouteModal({ date, existingNames, origin, busy, error, onCancel, onCreate }) {
  const [routeName, setRouteName] = useState('');
  const check = validateNewRoute({ routeName, date, existingNames, hasOrigin: !!origin });
  const showCheck = routeName.trim().length > 0;
  useEffect(() => {
    const onKey = (e) => { if (e.key === 'Escape' && !busy) onCancel(); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onCancel, busy]);
  return (
    <div className="fixed inset-0 z-[70] bg-black/50 flex items-center justify-center p-4"
      role="dialog" aria-modal="true" aria-label="New route"
      onMouseDown={(e) => { if (e.target === e.currentTarget && !busy) onCancel(); }}>
      <div className="bg-white rounded-lg shadow-xl w-full max-w-md max-h-[85dvh] flex flex-col">
        <div className="px-4 py-3 border-b font-semibold text-slate-800 flex items-center gap-2">
          <Plus size={16} className="text-emerald-600" /> New route for {formatDateLong(date)}
        </div>
        <form
          className="px-4 py-3 overflow-y-auto text-sm space-y-3"
          onSubmit={(e) => { e.preventDefault(); if (check.ok && !busy) onCreate(routeName.trim(), check.loadNbr); }}
        >
          <OrderField label="Route name" req value={routeName} onChange={(e) => setRouteName(e.target.value)}
            placeholder="e.g. TRAILER 6" disabled={busy} />
          <div className="text-[11px] text-slate-500">
            This is the name the board groups by. NuVizz also needs its own load number, which is made from the
            name and the day{check.loadNbr ? <> — this one would be <b className="font-mono">{check.loadNbr}</b>.</> : '.'}
          </div>
          {showCheck && !check.ok && (
            <div className="text-[12px] text-amber-800 bg-amber-50 border border-amber-200 rounded p-2">{check.error}</div>
          )}
          {error && <div className="text-[12px] text-red-800 bg-red-50 border border-red-200 rounded p-2">{error}</div>}
          <div className="text-[11px] text-slate-500">
            The route opens as a Compare card for {formatDateLong(date)} — <b>nothing is sent to NuVizz yet</b>.
            Drag orders onto it, then Save: the route and all its stops are created together (NuVizz won&apos;t
            accept an empty route). Closing the card before saving discards it. To build another day&apos;s route,
            change the board date first.
          </div>
          <button type="submit" className="hidden" aria-hidden="true" tabIndex={-1} />
        </form>
        <div className="px-4 py-3 border-t flex items-center justify-end gap-2">
          <button onClick={onCancel} disabled={busy}
            className="px-3 py-1.5 text-sm rounded border border-slate-300 text-slate-600 hover:bg-slate-50 disabled:opacity-60">Cancel</button>
          <button onClick={() => onCreate(routeName.trim(), check.loadNbr)} disabled={!check.ok || busy}
            className="px-3 py-1.5 text-sm rounded font-semibold text-white bg-emerald-600 hover:bg-emerald-700 disabled:opacity-60">
            Open route card
          </button>
        </div>
      </div>
    </div>
  );
}

// Beta version history popup (opened from the build badge).
function VersionLogModal({ onClose }) {
  useEffect(() => {
    const onKey = (e) => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);
  return (
    <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4" role="dialog" aria-modal="true">
      <div className="absolute inset-0 bg-black/40" onClick={onClose} />
      <div className="relative bg-white rounded-lg shadow-xl w-full max-w-sm max-h-[85dvh] flex flex-col" style={{ paddingBottom: 'env(safe-area-inset-bottom)' }}>
        <div className="flex items-center justify-between px-3 py-2 border-b shrink-0">
          <div className="flex items-center gap-2 min-w-0">
            <img src="/davis-logo.jpg" alt="Davis Delivery Service" className="h-7 w-auto" />
            <div className="font-bold text-slate-800 border-l border-slate-200 pl-2">Version history</div>
          </div>
          <button onClick={onClose} aria-label="Close" className="text-slate-400 hover:text-slate-700 text-2xl leading-none px-1">×</button>
        </div>
        <div className="flex-1 min-h-0 overflow-y-auto p-2">
          <div className="px-1 pb-2 text-[10px] text-slate-400">Build {BUILD_SHORT} · {BUILD_CONTEXT}</div>
          <ul className="divide-y">
            {VERSION_LOG.map(([v, note]) => {
              const current = v === APP_VERSION;
              return (
                <li key={v} className={`flex gap-2 px-1 py-1.5 text-[12px] ${current ? 'bg-emerald-50 rounded' : ''}`}>
                  <span className="font-bold tabular-nums shrink-0" style={{ color: current ? '#16a34a' : '#334155' }}>v{v}</span>
                  <span className="text-slate-600">{note}{current ? ' — current' : ''}</span>
                </li>
              );
            })}
          </ul>
        </div>
      </div>
    </div>
  );
}

function RoutingScreen({ debugCaptureRef, presence = null }) {
  const [selectedDate, setSelectedDate] = useState(() => todayInET());
  const { stops, loading, error: stopsError, refresh: refreshStops, lastScannedAt, lastLoadScanAt, lastUnplannedScanAt, ops, scanUnplannedCount } = useStops(selectedDate);
  // Stops status card (same pill as the dispatch Map, top-right of the routing map):
  // stops count + total pallets + feed freshness + NuVizz call meter. Shares the Map's
  // collapse preference and the cheap manual-scan path (~4 calls, never the number-probe).
  const { scanning, scanCooldown, scanErr, manualScan } = useManualScan(selectedDate, lastScannedAt, refreshStops);
  const [statusCollapsed, setStatusCollapsed] = useState(() => safeReadJSON(LS_STATUS_PILL_COLLAPSED, false));
  useEffect(() => { safeWriteJSON(LS_STATUS_PILL_COLLAPSED, statusCollapsed); }, [statusCollapsed]);
  // NuVizz records the pallet count in its carton field (stop.cartons) — same sum/label as the Map.
  const boardTotalPallets = useMemo(() => stops.reduce((sum, s) => sum + (Number(s.cartons) || 0), 0), [stops]);
  // A FUNCTION, not a pre-built element: it reads `drawnStops`, which is declared far below
  // (it needs vPositioned / effectiveRouteInfo). Building the element here would evaluate that
  // reference during this line and throw "Cannot access 'drawnStops' before initialization" —
  // the same temporal-dead-zone crash that blanked Routing in v0.32.11. A function body is not
  // evaluated until it's called, and both call sites are below the declaration.
  const statusCard = () => (
    <StopsStatusCard
      stopCount={stops.length}
      // What the map is ACTUALLY drawing, so the chip can't disagree with the pins under it.
      drawnCount={drawnStops.length}
      totalPallets={boardTotalPallets}
      loadAt={lastLoadScanAt}
      unplannedAt={lastUnplannedScanAt}
      isToday={isTodayET(selectedDate)}
      scanUnplannedCount={scanUnplannedCount}
      // Routing renders the whole board (its own grid/status filters live below the map),
      // so the pool here IS the scan's unplanned set — no filter gap to report.
      visibleUnplannedCount={undefined}
      ops={ops}
      scanErr={scanErr}
      scanning={scanning}
      scanCooldown={scanCooldown}
      onRefresh={manualScan}
      collapsed={statusCollapsed}
      onToggleCollapsed={() => setStatusCollapsed((c) => !c)}
    />
  );
  // Board write-through (#361): a CONFIRMED Save patches the day's board cache (Firestore-only
  // endpoint — zero NuVizz calls) with the verified plan, then re-reads the cache — so planned
  // orders flip to planned on the board immediately instead of waiting out the next scan (and
  // NuVizz's own list feed, which can lag an async import by minutes).
  const syncBoardAfterSave = useCallback(async (patch) => {
    // 1) LOCAL overlay first — the confirmed plan paints over every board read on THIS
    //    device immediately (and across reloads) until a scan agrees or it expires. It
    //    doesn't depend on the server at all, so no cache keying or sync failure can
    //    make a confirmed save look unbuilt here again.
    recordPlanOverlay(patch);
    setPlanVersion((v) => v + 1); // re-paint consumers that hold already-fetched rows (bottom grid window mode)
    // Tell the OTHER dispatcher's device a save landed — its presence watcher
    // silently re-reads the board within seconds (vs the 2-minute poll).
    presence?.bumpSave();
    // 2) Server write-through (+ carry-over rescue) so other devices/tabs agree too.
    //    Returns {patched, missing, rescued} so the Save toast can surface a miss.
    let out = null;
    try {
      const r = await fetch('/.netlify/functions/nuvizz-board-sync', {
        method: 'POST', cache: 'no-store', headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ date: selectedDate, ...patch }),
      });
      out = await r.json().catch(() => null);
    } catch { /* best-effort — the overlay + next scan cover it */ }
    // Always visible in the console for forensics — which stops were synced, what the
    // server found (patched/rescued/missing), or that the endpoint call itself failed.
    // eslint-disable-next-line no-console
    console.log('[board-sync]', { date: selectedDate, sent: patch, result: out });
    try { refreshStops(); } catch { /* ignore */ }
    return out;
  }, [selectedDate, refreshStops, presence?.bumpSave]);
  const { notes } = useCustomerNotes();
  const tractorLocs = useTractorLocations();
  const { profiles, saveProfile } = useTruckProfiles();
  const { google, error: mapsError } = useGoogleMaps();
  const viewportWidth = useViewportWidth();
  const isMobile = viewportWidth < MOBILE_BREAKPOINT;

  const mapDiv = useRef(null);
  const mapRef = useRef(null);
  const markersRef = useRef([]);
  const polylinesRef = useRef([]);
  const dayRoutePolylinesRef = useRef([]);   // "Show routes" overlay — one polyline per load
  const [mapReady, setMapReady] = useState(0);
  // Coord-bearing orders from the bottom grid's active Board window/range (cache-backed).
  // When set, the map ADDS the other-day orders in it so every order the grid lists can be
  // selected + planned (dispatcher: "all these unplanned orders should be on the map"). null
  // = grid is on the single board day (or a live window with no coords) → map is day-only.
  const [gridWindowStops, setGridWindowStops] = useState(null);
  // Bottom-grid SEARCH matches (stopNbr Set, or null) reported up by BottomStopsTable, so the
  // Routing map can highlight them in burnt orange on the top layer — parity with the Map screen.
  const [searchMatchIds, setSearchMatchIds] = useState(null);
  const [statusFilterIds, setStatusFilterIds] = useState(null); // grid status/driver filter → map visibility (null = no filter)

  // Touch-native selection. No DrawingManager (its drag-to-draw never worked on
  // a phone and its async load could silently no-op): Box = tap two corners,
  // Lasso = tap vertices then Done — both driven by plain map click listeners,
  // so every tool works identically on touch and mouse. Refs hold the in-flight
  // geometry + preview overlays; state drives the prompts.
  const [selectMode, setSelectMode] = useState(null);   // null | 'box' | 'lasso'
  const [boxStep, setBoxStep] = useState(0);             // corners placed so far
  const [lassoCount, setLassoCount] = useState(0);       // vertices placed so far
  const [lastAction, setLastAction] = useState(null);    // visible "N added" feedback
  const selectModeRef = useRef(null);
  const boxCornersRef = useRef([]);
  const lassoVtxRef = useRef([]);
  const tempMarkersRef = useRef([]);   // corner/vertex dots
  const tempShapeRef = useRef(null);   // lasso preview polyline
  const handleSelectPointRef = useRef(() => {});
  useEffect(() => { selectModeRef.current = selectMode; }, [selectMode]);

  // Live map<->list linkage: the hovered stop id is shared between the markers
  // and the desktop stop table, so emphasis is two-directional.
  const [hoverId, setHoverId] = useState(null);
  const hoverIdRef = useRef(null);
  useEffect(() => { hoverIdRef.current = hoverId; }, [hoverId]);
  const markerByIdRef = useRef(new Map());  // stopId -> { marker, sel, routed }
  const lastEmphRef = useRef(null);

  // Desktop click-drag rubber-band box. The overlay (rendered over the map only
  // while Box mode is armed on desktop) captures the drag so it doesn't pan the
  // map; mouseup converts the two pixel corners to LatLng via the map projection
  // and reuses the proven boxFromCorners + latLngInBounds geometry.
  const overlayRef = useRef(null);         // google.maps.OverlayView for px->latlng
  const dragStartRef = useRef(null);
  const [dragRect, setDragRect] = useState(null);

  // Desktop freehand drag-lasso: a pointer-captured SVG path (NOT DrawingManager).
  // While lasso mode is armed the overlay intercepts pointer events so the map
  // can't pan; pointer-up converts the pixel path to LatLng and selects via
  // pointInPolygon. (Touch keeps the tap-vertices lasso — no overlay on mobile.)
  const lassoDrawingRef = useRef(false);
  const lassoPxRef = useRef([]);
  const [lassoPath, setLassoPath] = useState([]);

  // Stop detail — shown in the RIGHT PANEL (takeover overlay), not a center popup.
  // A map-marker click, a ProLink #pro, or any panel row's onOpenStop sets this;
  // the right rail then renders RoutingStopPanel over whatever tab/mode is active.
  const [panelStop, setPanelStop] = useState(null);
  // Bumped on every confirmed Save so components holding already-fetched rows (the bottom
  // grid's window mode) re-apply the plan overlay immediately instead of waiting for a scan.
  const [planVersion, setPlanVersion] = useState(0);
  // Customer-history overlay (the stop panel's "History" button) — the same Firestore-only
  // lookup as the Map screen: this location's past PROs + date + who delivered each.
  // Distinct from the per-order Activity timeline; never makes a NuVizz call.
  const [histOpen, setHistOpen] = useState(false);
  const [histSeed, setHistSeed] = useState('');
  const openCustomerHistory = useCallback((s) => { setHistSeed((s?.businessName || '').trim()); setHistOpen(true); }, []);
  const [versionLogOpen, setVersionLogOpen] = useState(false);
  const openStop = useCallback((s) => setPanelStop(s || null), []);

  // ── Edit-address + Correct-pin-location (ported from MapScreen) ──────────────
  // Both write customer_notes overrides (address_override / location_override);
  // RoutingScreen's positionedAll already applies location_override live (via the
  // notes onSnapshot), so a corrected pin relocates the routing marker with no
  // extra plumbing. No NuVizz calls — Firestore + client-side geocode only.
  const [movingStop, setMovingStop] = useState(null);
  const [movedTo, setMovedTo] = useState(null);
  const [savingLoc, setSavingLoc] = useState(false);
  const [editAddrStop, setEditAddrStop] = useState(null);
  const [editAddrSeed, setEditAddrSeed] = useState(null);
  const openAddrEditor = useCallback((stop, seed = null) => { setEditAddrSeed(seed || null); setEditAddrStop(stop); }, []);
  const movingMarkerRef = useRef(null);

  // The NuVizz-style bottom data grid (same spreadsheet as the dispatch Map) —
  // collapsed by default so it doesn't cover the map until opened.
  const [bottomTableOpen, setBottomTableOpen] = useState(false);

  // Which list the rail's Loads tab shows: 'board' = the day's NuVizz loads (what a dispatcher
  // means by a load), 'saved' = saved optimizer plans. Defaults to the board — the tab pointing
  // only at saved plans is what made it look dead (§L). Remembered per device.
  const [loadsRailView, setLoadsRailView] = useState(() => {
    try { return localStorage.getItem('routing.loadsRail') === 'saved' ? 'saved' : 'board'; } catch { return 'board'; }
  });
  useEffect(() => { try { localStorage.setItem('routing.loadsRail', loadsRailView); } catch { /* ignore */ } }, [loadsRailView]);

  // Desktop right rail: Stops | Result. Persisted as a view pref (localStorage ok).
  const [desktopRail, setDesktopRail] = useState(() => {
    try { return localStorage.getItem('routing.rail') === 'result' ? 'result' : 'stops'; } catch { return 'stops'; }
  });
  useEffect(() => { try { localStorage.setItem('routing.rail', desktopRail); } catch { /* ignore */ } }, [desktopRail]);

  // Floating "Selected N" panel (NuVizz-style overlay listing every selected stop). A view
  // pref the dispatcher can turn on/off; default ON. Persisted in localStorage.
  const [selPanelOpen, setSelPanelOpen] = useState(() => {
    try { return localStorage.getItem('routing.selPanel') !== 'off'; } catch { return true; }
  });
  useEffect(() => { try { localStorage.setItem('routing.selPanel', selPanelOpen ? 'on' : 'off'); } catch { /* ignore */ } }, [selPanelOpen]);

  // Right-panel layout version (Routing-beta only): 'tabs' = today's Stops/Loads/Result rail,
  // 'routes' = the new live Routes/Drivers roster. Chosen from the gear settings; persisted.
  const [rightPanelMode, setRightPanelMode] = useState(() => {
    try { return localStorage.getItem('routing.rightPanel') === 'routes' ? 'routes' : 'tabs'; } catch { return 'tabs'; }
  });
  useEffect(() => { try { localStorage.setItem('routing.rightPanel', rightPanelMode); } catch { /* ignore */ } }, [rightPanelMode]);

  // Routes-mode sub-tab: today's route cards vs the driver roster. Driver roster is the
  // on-demand list (shared with the mobile app); fetched lazily the first time Drivers opens.
  const [routesSubTab, setRoutesSubTab] = useState('routes');
  const [driverRoster, setDriverRoster] = useState({ drivers: null, updatedAt: null, neverScanned: false, loading: false, refreshing: false, error: null });

  const loadDriverRoster = useCallback(async () => {
    setDriverRoster((s) => ({ ...s, loading: true, error: null }));
    try {
      const r = await fetch('/.netlify/functions/nuvizz-driver-roster?tenant=davis', { cache: 'no-store' });
      const d = await r.json();
      setDriverRoster({
        drivers: Array.isArray(d.drivers) ? d.drivers : [],
        updatedAt: d.updatedAt || null,
        neverScanned: !!d.neverScanned,
        loading: false, refreshing: false,
        error: (d && d.ok === false) ? (d.error || 'Failed to load roster') : null,
      });
    } catch (e) {
      setDriverRoster((s) => ({ ...s, loading: false, error: e.message }));
    }
  }, []);

  // Manual rebuild — the only path that hits NuVizz's /user/list (~1 call). Writes the shared roster.
  const refreshDriverRoster = useCallback(async () => {
    setDriverRoster((s) => ({ ...s, refreshing: true, error: null }));
    try {
      const r = await fetch('/.netlify/functions/nuvizz-driver-roster?tenant=davis&refresh=1', { method: 'POST', cache: 'no-store' });
      const d = await r.json();
      if (d && d.ok === false) { setDriverRoster((s) => ({ ...s, refreshing: false, error: d.error || 'Refresh failed — list left unchanged' })); return; }
      setDriverRoster({
        drivers: Array.isArray(d.drivers) ? d.drivers : [],
        updatedAt: d.refreshedAt || null,
        neverScanned: false,
        loading: false, refreshing: false, error: null,
      });
    } catch (e) {
      setDriverRoster((s) => ({ ...s, refreshing: false, error: e.message }));
    }
  }, []);

  // Lazy-load the roster the first time the Drivers sub-view is opened.
  useEffect(() => {
    if (rightPanelMode === 'routes' && routesSubTab === 'drivers' && driverRoster.drivers === null && !driverRoster.loading) {
      loadDriverRoster();
    }
  }, [rightPanelMode, routesSubTab, driverRoster.drivers, driverRoster.loading, loadDriverRoster]);

  // The day's load roster (the cheap list-discovery path, served from the scan cache — no number-probe
  // scan) carries each load's lifecycle status (Draft / Un-Planned / … for the Routes filter) AND its
  // loadId. Pulled whenever the routing screen has a board date — not just when the Routes panel is
  // open — because opening ANY load in Compare needs its loadId to assign/dispatch, and Draft/empty
  // loads have no stops to get it from. Failure just leaves the derived status + stop-only loadId.
  const [loadStatusByName, setLoadStatusByName] = useState(() => new Map());
  // The day's FULL load roster (every load created for the date, empty Drafts included) — the
  // pick list for "Plan onto my loads" in the left panel. Same fetch as the identity index
  // below; kept as plain rows {name, loadNbr, loadId, status, trips}.
  const [loadRosterList, setLoadRosterList] = useState([]);
  // Load-resolution index from the same roster: route name (lc) and loadId → { loadId, name }. This is
  // how a load that has NO stops on the board (a Draft/empty load) gets its real loadId — there are no
  // stops to derive it from, and assignDriver needs the loadId. Kept in a ref so openRouteInWorkbench
  // (deps []) always reads the latest without re-binding.
  const loadRosterRef = useRef(new Map());
  // Confirmed-dispatch status overrides (load name lc / '#id:loadNbr' → 'Dispatched'). The roster
  // is a cached snapshot that only refreshes with scans — paused overnight — so a successful
  // production dispatch kept reading Draft here. An override wins over the stale roster and is
  // DROPPED the moment the roster itself reports a non-Draft status (agreement — scans caught up).
  const dispatchOverrideRef = useRef(new Map());
  useEffect(() => {
    if (!selectedDate) return;
    let cancelled = false;
    fetch('/.netlify/functions/nuvizz-loads-roster?date=' + encodeURIComponent(selectedDate), { cache: 'no-store' })
      .then((r) => r.json())
      .then((j) => {
        if (cancelled) return;
        // Status map via the shared builder: it writes the by-id keys AND the '#amb:' markers
        // that stop a name shared by two loads from deciding either one's status (§S).
        const rosterLoads = (j && j.ok) ? (j.loads || []) : [];
        const status = buildRosterStatusMap(rosterLoads);
        const index = new Map();
        const owners = new Map();   // name lc → { load, ambiguous }
        const asEntry = (l) => ({ loadId: l?.loadId ? String(l.loadId) : null, name: l?.name || '', loadNbr: l?.loadNbr ? String(l.loadNbr) : null });
        if (j && j.ok) for (const l of rosterLoads) {
          const nm = String(l.name || '').trim().toLowerCase();
          const entry = asEntry(l);
          if (nm) {
            // Two roster loads sharing a NAME → last-write-wins here could hand one load's
            // number/id to the other's card. But a CANCELLED load holds no planned work, so
            // "the active and canceled one" (Chad's two STEVENs) is not a real contest — the
            // LIVE load owns the name. Only two LIVE loads are ambiguous, and identity
            // consumers (openRouteInWorkbench / onAssignDriver) still refuse those.
            if (!owners.has(nm)) owners.set(nm, resolveNameOwner(nm, rosterLoads));
            const own = owners.get(nm);
            if (own.ambiguous) index.set(nm, { ...entry, ambiguous: true });
            else index.set(nm, asEntry(own.load || l));
          }
          if (l.loadId) { index.set(String(l.loadId), entry); }
          // Also key by the REAL load number: an empty load's Loads-grid row is keyed by it since
          // 0.32.25 (loadNbr || loadId), so opening one must resolve back to the entry — without
          // this the card had no loadId/loadNbr and assign/save failed on every empty load.
          if (l.loadNbr) index.set(String(l.loadNbr), entry);
        }
        // Confirmed-dispatch overrides beat the stale snapshot; agreement retires them.
        for (const [k, v] of dispatchOverrideRef.current) {
          const raw = String(status.get(k) || '').toLowerCase();
          if (raw && !raw.includes('draft')) dispatchOverrideRef.current.delete(k); // roster caught up
          else status.set(k, v);
        }
        loadRosterRef.current = index;
        setLoadStatusByName(status);
        setLoadRosterList(j && j.ok ? (j.loads || []) : []);
      })
      .catch(() => { if (!cancelled) { loadRosterRef.current = new Map(); setLoadStatusByName(new Map()); setLoadRosterList([]); } });
    return () => { cancelled = true; };
  }, [rightPanelMode, selectedDate]);


  // Part 6 — resizable left & right panels (the bottom grid already resizes via BottomStopsTable),
  // and a bottom-grid on/off toggle. All persisted; Routing-beta only.
  const leftPanel = useSidePanelWidth('left', 'routing.leftW', 340, 240, viewportWidth);
  const rightPanel = useSidePanelWidth('right', 'routing.rightW', 380, 280, viewportWidth);
  // Full right-rail collapse (dispatcher request): hide the rail entirely; a thin strip
  // stays as the re-open affordance. Opening a stop auto-expands so a clicked stop's
  // detail can never land in a hidden panel. Persisted per device.
  const [rightCollapsed, setRightCollapsed] = useState(() => safeReadJSON('routing.rightCollapsed', false) === true);
  useEffect(() => { safeWriteJSON('routing.rightCollapsed', rightCollapsed); }, [rightCollapsed]);
  useEffect(() => { if (panelStop) setRightCollapsed(false); }, [panelStop]);
  const [bottomGridOn, setBottomGridOn] = useState(() => { try { return localStorage.getItem('routing.bottomGrid') !== 'off'; } catch { return true; } });
  useEffect(() => { try { localStorage.setItem('routing.bottomGrid', bottomGridOn ? 'on' : 'off'); } catch { /* ignore */ } }, [bottomGridOn]);
  // Setup panel (the left controls column) on/off. The dispatcher asked to keep it hidden while the
  // routing beta's left-side controls are still under development, and flip it on only while working
  // on them — so the toggle lives in the gear on the bottom data-grid header (reachable even when
  // this panel is hidden). Default OFF (hidden); persisted. Invariant: never hide the Setup panel
  // while the bottom grid is also off — that would strip away every settings gear — so turning it
  // off force-shows the bottom grid, keeping the gear (and date picker) reachable.
  const [leftPanelOn, setLeftPanelOn] = useState(() => { try { return localStorage.getItem('routing.leftPanel') === 'on'; } catch { return false; } });
  useEffect(() => { try { localStorage.setItem('routing.leftPanel', leftPanelOn ? 'on' : 'off'); } catch { /* ignore */ } }, [leftPanelOn]);
  const setLeftPanelVisible = useCallback((on) => { setLeftPanelOn(on); if (!on) setBottomGridOn(true); }, []);
  // Routing-map view filters (port of the dispatch Map's). Persisted; defaults keep the current look
  // (satellite base on, nothing hidden). unplannedOnly filters the rendered stops; satellite swaps
  // the map base; showRoutes overlays each load's delivery-sequence polyline.
  const [routeUnplannedOnly, setRouteUnplannedOnly] = useState(() => { try { return localStorage.getItem('routing.mapUnplannedOnly') === 'on'; } catch { return false; } });
  const [routeSatellite, setRouteSatellite] = useState(() => { try { return localStorage.getItem('routing.mapSatellite') !== 'off'; } catch { return true; } });
  const [routeShowRoutes, setRouteShowRoutes] = useState(() => { try { return localStorage.getItem('routing.mapShowRoutes') === 'on'; } catch { return false; } });
  useEffect(() => { try { localStorage.setItem('routing.mapUnplannedOnly', routeUnplannedOnly ? 'on' : 'off'); } catch { /* ignore */ } }, [routeUnplannedOnly]);
  useEffect(() => { try { localStorage.setItem('routing.mapSatellite', routeSatellite ? 'on' : 'off'); } catch { /* ignore */ } }, [routeSatellite]);
  useEffect(() => { try { localStorage.setItem('routing.mapShowRoutes', routeShowRoutes ? 'on' : 'off'); } catch { /* ignore */ } }, [routeShowRoutes]);
  // Hide the "stem-out" leg — the line drawn from the terminal/depot to the first stop of each
  // route (NuVizz's "hide stem out", #256). On = the polyline connects only the stops, no depot
  // anchor line. Persisted; default OFF (show), matching NuVizz's default.
  const [routeHideStem, setRouteHideStem] = useState(() => { try { return localStorage.getItem('routing.hideStem') === 'on'; } catch { return false; } });
  useEffect(() => { try { localStorage.setItem('routing.hideStem', routeHideStem ? 'on' : 'off'); } catch { /* ignore */ } }, [routeHideStem]);
  // Hide Google's own place/business labels (the POI clutter that overlaps stop pins). On the
  // vector mapId map JS styles are ignored, so the mapId-safe lever is the TYPE: satellite has
  // no labels, hybrid does. Persisted.
  const [routeHideLabels, setRouteHideLabels] = useState(() => { try { return localStorage.getItem('routing.hideLabels') === 'on'; } catch { return false; } });
  useEffect(() => { try { localStorage.setItem('routing.hideLabels', routeHideLabels ? 'on' : 'off'); } catch { /* ignore */ } }, [routeHideLabels]);
  const resetRoutingLayout = useCallback(() => {
    leftPanel.onDoubleClick(); rightPanel.onDoubleClick();
    setSelPanelOpen(true); setRightPanelMode('tabs'); setBottomGridOn(true); setRouteHideStem(false); setLeftPanelOn(false); setRightCollapsed(false);
  }, [leftPanel, rightPanel]);
  // Nudge Google Maps to re-render when a side panel resizes (the canvas changed width).
  useEffect(() => {
    if (google && mapRef.current) { try { google.maps.event.trigger(mapRef.current, 'resize'); } catch { /* ignore */ } }
  }, [leftPanel.width, rightPanel.width, rightCollapsed, google]);

  // Route workbench (part 4): routes opened from the right Routes panel become side-by-side
  // cards you tune. Each entry { key, order:[stopNbr...], collapsed, baseline? }; capped at 6
  // (raised from 3 for "plan onto my loads" — staging a 5-load build needs 5 cards; the card
  // row scrolls horizontally). Planning overlay only — reorders/moves live here, they don't
  // mutate the board.
  const WB_MAX = 6;
  const [wbRoutes, setWbRoutes] = useState([]);
  // Every stop id currently STAGED on an open Compare card, mapped to its card key. The map
  // selection tools must not grab these — selecting a staged stop and sending it to another
  // load double-plans it (the save-level guard now refuses, but the selection shouldn't
  // invite the mistake at all). A ref so guards in stable callbacks read the latest.
  const wbStagedRef = useRef(new Map());
  useEffect(() => {
    const m = new Map();
    for (const r of wbRoutes) for (const id of r.order) m.set(String(id), r.key);
    wbStagedRef.current = m;
    // Publish what THIS device is staging so the other dispatcher's selection
    // tools stay off these stops (presence layer; best-effort, Firestore-only).
    presence?.publishStaged([...m.keys()], selectedDate);
  }, [wbRoutes, selectedDate, presence?.publishStaged]);
  // Every stop the OTHER dispatcher's device is staging (same board date), mapped
  // to their name. A ref — the selection guards live in stable callbacks, exactly
  // like wbStagedRef above.
  const peerClaimsRef = useRef(new Map());
  useEffect(() => {
    peerClaimsRef.current = presence ? buildPeerClaims(presence.peers, selectedDate) : new Map();
  }, [presence?.peers, selectedDate]);
  const peerClaimFor = useCallback((nbr) => peerClaimsRef.current.get(String(nbr)) || null, []);
  // Another device's confirmed Save → silently re-read the board now (zero NuVizz
  // calls — the same cheap Firestore read the 2-minute poll does).
  const lastPeerSaveRef = useRef(null);
  useEffect(() => {
    const t = latestPeerSaveAt(presence?.peers);
    if (lastPeerSaveRef.current == null) { lastPeerSaveRef.current = t; return; }
    if (t > lastPeerSaveRef.current) { lastPeerSaveRef.current = t; refreshStops({ silent: true }); }
  }, [presence?.peers, refreshStops]);
  // Ninja mode (part 5): while on, each stop clicked on the map is appended (in click order) to
  // the ACTIVE compare-panel route. activeRouteKey picks the target; defaults to the leftmost card.
  const [ninjaMode, setNinjaMode] = useState(false);
  const [activeRouteKey, setActiveRouteKey] = useState(null);
  const effectiveActiveKey = (activeRouteKey && wbRoutes.some((r) => r.key === activeRouteKey)) ? activeRouteKey : (wbRoutes[0]?.key || null);
  const ninjaActionRef = useRef(null);
  const openRouteRef = useRef(null);   // planned-stop click → open its route in Compare (kept current below)
  // Vehicle-eligibility paint mode: null | 'tractor' | 'box'. Refs let the
  // bound-once marker click listener read the live brush + handler.
  const [eligPaint, setEligPaint] = useState(null);
  const eligPaintRef = useRef(null);
  const eligActionRef = useRef(null);

  const [selectedIds, setSelectedIds] = useState(() => new Set());
  const [selectedTruckIds, setSelectedTruckIds] = useState(() => new Set());
  // "Plan onto": 'loads' spreads the selection across REAL NuVizz loads picked from the day's
  // roster (one built route per picked load, staged onto Compare cards → the normal Save);
  // 'trucks' is the original abstract truck-profile build. Persisted; loads-first is the
  // dispatcher flow ("select alpha, alpha 2, atl, suw, suw 2 then plan my selection onto them").
  const [planMode, setPlanMode] = useState(() => { try { return localStorage.getItem('routing.planMode') === 'trucks' ? 'trucks' : 'loads'; } catch { return 'loads'; } });
  useEffect(() => { try { localStorage.setItem('routing.planMode', planMode); } catch { /* ignore */ } }, [planMode]);
  // Picked roster loads (row keys) + a per-load truck-profile override for capacity/eligibility.
  const [planTargetKeys, setPlanTargetKeys] = useState(() => new Set());
  const [planTargetProfileById, setPlanTargetProfileById] = useState(() => new Map());
  const [planLoadFilter, setPlanLoadFilter] = useState('');
  // A different day = a different roster — stale picks must never carry across dates.
  useEffect(() => { setPlanTargetKeys(new Set()); setPlanTargetProfileById(new Map()); setPlanLoadFilter(''); }, [selectedDate]);
  const [intent, setIntent] = useState('');
  const [strategy, setStrategy] = useState('MIN_DISTANCE');
  const [useGoogle, setUseGoogle] = useState(false);
  // When on, the auto-router puts ONLY green (tractor-friendly) stops on a 53'
  // trailer; every other stop is held to a box truck. Per-build (not persisted).
  const [trailerGreenOnly, setTrailerGreenOnly] = useState(false);
  const [job, setJob] = useState(null);     // { status, result, error }
  const [building, setBuilding] = useState(false);
  const [saveState, setSaveState] = useState(null); // null | 'saving' | 'saved' | error string
  const [lastRequest, setLastRequest] = useState(null);

  // Every coord-bearing stop with any address fix applied — the UNFILTERED base. The "Unplanned only"
  // view below filters this down; the workbench opens routes off this base so a planned route can
  // still be pulled up (and captured in full) while the filter is on.
  // The map's base set: the board day's stops, PLUS any other-day orders the bottom grid's
  // window/range surfaced (deduped by stopNbr — the day board's copy wins so its live status /
  // plan-overlay is kept). The extra orders get the same plan-overlay pass so a just-saved one
  // flips planned on the map too. This is what makes "every order the grid lists is on the map
  // to select and plan" true even across days.
  const mapBaseStops = useMemo(() => {
    if (!gridWindowStops || !gridWindowStops.length) return stops;
    const seen = new Set(stops.map((s) => String(s.stopNbr)));
    // Other-day orders the day board doesn't already carry. Do NOT pre-filter to coord-bearing
    // here — a stop that has no NuVizz location but was just given one via "Edit address" /
    // "Correct pin" (a location_override in notes) must stay in the base set so positionedAll
    // below can apply that override and pin it LIVE. Dropping coordless extras here meant a
    // freshly-fixed order stayed invisible until the next scan re-geocoded it (#pin-live). The
    // coord filter still runs in positionedAll, AFTER overrides — so genuinely locationless
    // extras are excluded there, exactly as before.
    // ONLY UNPLANNED extras join. An other-day row that's planned on a load is a FROZEN
    // SNAPSHOT of that day's board (delivered stops leave the scan feeds, so their rows keep
    // "planned on TAYLOR" + the old driver forever) — merging those painted ghost pins and,
    // worse, name-merged last week's loads into today's same-named Compare card (26-stop /
    // 951-mi TAYLOR). The carry-over case the window merge exists for — grab an old MISSED
    // order and plan it today — is exactly the unplanned rows, which still flow through.
    // Tagged windowExtra so route-card seeding below can refuse them outright.
    const extra = gridWindowStops
      .filter((s) => s && s.stopNbr && !seen.has(String(s.stopNbr))
        // Frozen-history planned rows stay OFF (the TAYLOR bleed rule) — but a row OUR OWN
        // confirmed save just planned (planOverlay stamp) stays ON: excluding it made a
        // just-saved window stop vanish from map + open card until the rescue's board-day
        // copy landed (a blink when healthy, hours if the sync missed).
        && (s.planOverlay === true || !(s.isPlanned === true || s.routeName || s.loadNbr)))
      .map((s) => ({ ...s, windowExtra: true }));
    return extra.length ? [...stops, ...extra] : stops;
  }, [stops, gridWindowStops]);
  // EVERY board row for the day, with any corrected pin applied (location_override from the
  // "Edit address" fix) — INCLUDING stops that have no coordinates yet. Recomputed on `notes`
  // so a pin fix lands LIVE, not only after closing/reopening the map (#287).
  const boardStopsAll = useMemo(() => mapBaseStops
    .map((s) => { const ov = notes.get(s.matchKey)?.location_override; return (ov && typeof ov.lat === 'number' && typeof ov.lng === 'number') ? { ...s, lat: ov.lat, lng: ov.lng } : s; }),
  [mapBaseStops, notes]);
  // positionedAll = the MAP's contract: markers, polylines and re-sequencing all need real
  // lat/lng, so coord-less rows are excluded here and everywhere downstream (stopById).
  // Compare-card MEMBERSHIP deliberately does NOT use this list — see boardStopById.
  const positionedAll = useMemo(() => boardStopsAll.filter((s) => s.lat != null && s.lng != null), [boardStopsAll]);
  // EVERY identity of each open Compare card — key AND display name AND load number. A card
  // opened from an empty Draft load is keyed by its load NUMBER (DAVIS000198668), but the
  // save's board write-through stamps rows with the route NAME (OWUSU 1): matching on the key
  // alone hid the whole freshly-saved route the moment the success toast fired ("dropped my
  // markers") while "Unplanned only" was on. Any identity match keeps the route on the map.
  const openRouteKeys = useMemo(() => {
    const set = new Set();
    for (const r of wbRoutes) for (const v of [r.key, r.name, r.loadNbr]) if (v) set.add(String(v));
    return set;
  }, [wbRoutes]);
  // "Unplanned only" hides planned stops — but NEVER the stops of a route the dispatcher has pulled
  // up (open in Compare). A pulled-up route always renders in full on the map regardless of the
  // filter, so its planned stops + polyline stay visible while everything else stays hidden.
  const positioned = useMemo(() => {
    if (!routeUnplannedOnly) return positionedAll;
    return positionedAll.filter((s) => s.isUnplanned
      || (s.routeName != null && openRouteKeys.has(String(s.routeName)))
      || (s.loadNbr != null && openRouteKeys.has(String(s.loadNbr))));
  }, [positionedAll, routeUnplannedOnly, openRouteKeys]);
  // Lookup map for cards / manifest / the Save payload — built from the UNFILTERED set, so a
  // stop staged onto an open card never vanishes from the card rows, printed manifest, or
  // re-sequencing while "Unplanned only" hides it on the MAP (markers use `positioned` below).
  // With the filtered map, what you saw ≠ what Save sent (hidden stops were still committed,
  // and a re-sequence shoved them to the end of the real order).
  const stopById = useMemo(() => new Map(positionedAll.map((s) => [String(s.stopNbr), s])), [positionedAll]);
  // MEMBERSHIP lookup for Compare cards — every board row, coord-less ones included. A stop
  // with no geocode is still ON its load, so a card must carry it: omitting it made Save send
  // an orderedStopNbrs list short one stop, which the server's stale-board guard rightly
  // refused ("…stop(s) the board isn't showing … Refresh and retry") — an unfixable loop,
  // since a stop with no geocode never joins positionedAll however often you refresh. The map
  // keeps using the coord-only stopById; only card membership/display/payload use this.
  const boardStopById = useMemo(() => new Map(boardStopsAll.map((s) => [String(s.stopNbr), s])), [boardStopsAll]);
  const positionedRef = useRef(positioned);
  useEffect(() => { positionedRef.current = positioned; }, [positioned]);
  // Unfiltered ref so opening a route captures ALL its stops even while "Unplanned only" is on.
  const positionedAllRef = useRef(positionedAll);
  useEffect(() => { positionedAllRef.current = positionedAll; }, [positionedAll]);
  // …and the coord-inclusive twin, which is what seeds a Compare card (see boardStopById).
  const boardStopsAllRef = useRef(boardStopsAll);
  useEffect(() => { boardStopsAllRef.current = boardStopsAll; }, [boardStopsAll]);

  // The day's routes/drivers roster — group the board by load (route name) for the right-panel
  // "Routes" view: stop count, driver, skids (cartons), weight, and delivery progress per route.
  const routeGroups = useMemo(() => computeRouteGroups(stops, loadStatusByName), [stops, loadStatusByName]);
  // The day's NuVizz LOADS for the right rail — routes built on the board PLUS the roster's
  // empty Drafts, which have no stops to group and so exist nowhere else (§L). This is the
  // same set the bottom grid's Loads view shows; the rail used to show saved optimizer plans
  // instead, which is why real routes never appeared in a column labelled Loads.
  const dayLoads = useMemo(() => mergeDayLoads(routeGroups, loadRosterList), [routeGroups, loadRosterList]);
  const dayLoadsTally = useMemo(() => dayLoadTally(dayLoads), [dayLoads]);

  // Workbench handlers — open a route into the side-by-side cards, tune it, close it.
  const openRouteInWorkbench = useCallback((key) => {
    if (!key) return;
    setWbRoutes((prev) => {
      if (prev.some((r) => r.key === key)) return prev;                 // already open
      if (prev.length >= WB_MAX) { setLastAction(`Workbench is full (${WB_MAX} routes) — close one first.`); return prev; }
      // BOARD-DAY ROWS ONLY. windowExtra rows come from OTHER days' cached boards (the bottom
      // grid's date range) — seeding by bare name match across them merged every historical
      // load that ever used this route name into one card. A card is always the selected
      // day's load instance; other-day orders reach a card only by explicit staging.
      // COORD-INCLUSIVE on purpose (boardStopsAllRef, not positionedAllRef): a load's
      // ungeocoded stop is still on the load, and seeding without it produced a card whose
      // Save was one stop short — refused by the server's stale-board guard with advice
      // ("Refresh and retry") that could never work. It rides in the card as a "no map
      // location" row instead: visible, counted, saved, just not drawn or auto-sequenced.
      const routeStops = boardStopsAllRef.current.filter((s) => !s.windowExtra && (s.routeName || s.loadNbr) === key);
      // TWO same-day loads sharing this NAME would merge onto one card and a Save would reorder
      // across loads (and could pair one load's id with the other's number). Refuse to open.
      const distinctLoadIds = new Set(routeStops.map((s) => s.raw?.load?.loadId ?? s.loadId).filter(Boolean).map(String));
      if (distinctLoadIds.size > 1) {
        setLastAction(`Two loads share the name "${loadDisplayName(key) || key}" today — their stops can't be edited as one card. Rename one in the portal, or work stop-by-stop.`);
        return prev;
      }
      // Resolve the load's real loadId + name from the day's roster (the daily load scan, by name or
      // loadId). REQUIRED for Draft/empty loads: they have no stops to derive a loadId from, and
      // assignDriver/commitBoard need the loadId (without it the Save falls through to a load/info
      // lookup with a bad key → "commitBoard: load not found"). For loads WITH stops, the stop-derived
      // loadId still wins (it's the verified same-day instance); the roster only fills the gap.
      // An AMBIGUOUS roster entry (two roster loads share the name) is never trusted for identity.
      const rosterEntry0 = loadRosterRef.current.get(String(key)) || loadRosterRef.current.get(String(key).toLowerCase()) || null;
      const rosterEntry = rosterEntry0 && !rosterEntry0.ambiguous ? rosterEntry0 : null;
      const stopLoadIdV = routeStops.map((s) => s.raw?.load?.loadId ?? s.loadId).find(Boolean) || null;
      // Only take the roster's loadNbr/loadId when it agrees with the stop-derived identity — a
      // roster row for a DIFFERENT same-named load must not attach its number to this card.
      const rosterMatches = !stopLoadIdV || !rosterEntry?.loadId || String(rosterEntry.loadId) === String(stopLoadIdV);
      // loadId: verified stop-derived id first; then the roster; then the key ITSELF when it's a load
      // id hash — an empty load is opened from the Loads grid BY its loadId, so this resolves it even
      // if the roster hasn't loaded yet (no race) and the roster only enriches the display name.
      const loadId = stopLoadIdV
        || (rosterMatches ? rosterEntry?.loadId : null)
        || (isHashLikeId(String(key)) ? String(key) : null);
      // The REAL NuVizz load NUMBER (e.g. "DAVIS000198197") — load/info is keyed by it, NOT the human
      // route name. The stop rows carry only the route NAME in loadNbr (the stops grid has no number
      // column), so it 404s load/info; prefer the loads-roster's numeric number, and fall back to a
      // stop value ONLY if it actually looks like a load number — never the bare route name. (When
      // neither is available the server bridges loadId→loadNbr via getStop/static-info.)
      const loadNbr = (rosterMatches ? rosterEntry?.loadNbr : null)
        || routeStops.map((s) => s.loadNbr).find((v) => looksLikeLoadNbr(v))
        || null;
      // Display name — the human route/load name; from stops, else the roster (so an empty load shows
      // "NOR" instead of "Unnamed load").
      const name = routeStops.map((s) => s.routeName).find(Boolean) || rosterEntry?.name || null;
      // NO IDENTITY AT ALL → refuse to open (§S). A card with neither a load number nor a load id
      // cannot be saved: BOTH engines reject it up front ("commitBoard(rwb): loadNbr or loadId
      // required"), and worse, its failure strands every stop being moved ONTO it — Chad built
      // STEVEN and NOR, and NOR refused too rather than unplan a stop bound for the dead card.
      // Assign and Dispatch already refuse this exact state with a message; opening a Compare
      // card was the one path that let you do the work first and find out afterwards.
      if (!loadId && !loadNbr) {
        const shown = loadDisplayName(name, key) || String(key);
        setLastAction(rosterEntry0?.ambiguous
          ? `Two loads are named "${shown}" today, so a card can't tell which one it would save to. Rename one in the portal (or cancel the one you're not using), then refresh.`
          : `"${shown}" has no NuVizz load number or id yet, so a Save would be refused. Open it from the Loads grid, or refresh once the day's loads have loaded.`);
        return prev;
      }
      // Ids already staged onto ANOTHER open card stay there (the staged move wins) — otherwise a
      // freshly-opened card re-seeds them from the board and the stop sits in BOTH cards' orders.
      const stagedElsewhere = new Set(prev.flatMap((r) => r.order));
      const order = orderRouteStops(routeStops).map((s) => String(s.stopNbr)).filter((id) => !stagedElsewhere.has(id));
      return [...prev, { key, name, loadNbr, loadId, order, collapsed: false }];
    });
  }, []);
  const closeWbRoute = useCallback((key) => setWbRoutes((prev) => prev.filter((r) => r.key !== key)), []);
  const closeAllWb = useCallback(() => setWbRoutes([]), []);
  const toggleWbCollapse = useCallback((key) => setWbRoutes((prev) => prev.map((r) => (r.key === key ? { ...r, collapsed: !r.collapsed } : r))), []);
  // After a successful LIVE save, clear the saved cards' staged-removal lists (the workbench calls
  // this via prop — it has no access to setWbRoutes) so a later Save can't re-send stale removes.
  const clearWbRemoved = useCallback((keys) => {
    const okSet = new Set(keys);
    setWbRoutes((prev) => prev.map((r) => (okSet.has(r.key) && (r.removed || []).length) ? { ...r, removed: [] } : r));
  }, []);
  // Changing the board DATE closes all Compare cards. A card freezes its loadId/loadNbr at open;
  // recurring loads share NAMES across days, so a card surviving a date flip looks like today's
  // load but would Save edits onto YESTERDAY'S instance. (Mirrors the assignedOverride reset.)
  useEffect(() => { setWbRoutes([]); }, [selectedDate]);
  // The optimistic Dispatch checkmark is keyed by route NAME — recurring names mean tomorrow's
  // Draft load would inherit today's "Dispatched" once the date flips (audit). Clear on flip,
  // like assignedOverride and the cards themselves.
  useEffect(() => { dispatchOverrideRef.current.clear(); }, [selectedDate]);
  const wbResequence = useCallback((key, strategy) => {
    if (!strategy || strategy === 'manual') return;
    // Computed OUTSIDE the state updater so the feedback line can tell the truth: the old shape
    // announced "Re-sequenced …" even when the updater silently bailed (stops not geocoded yet),
    // which read as "it worked" while the order (and the shown strategy) never changed.
    const r = wbRoutes.find((x) => x.key === key);
    if (!r) return;
    const pts = r.order.map((id) => { const s = stopById.get(String(id)); return s ? { id: String(id), lat: s.lat, lng: s.lng } : null; }).filter(Boolean);
    if (pts.length < 2) {
      const missing = r.order.length - pts.length;
      // Cards now legitimately carry stops that will NEVER geocode (bad address), so "try
      // again in a moment" alone would be a lie — point at the actual fix too.
      setLastAction(`Can't re-sequence ${loadDisplayName(key) || 'load'} — ${missing > 0 ? `${missing} stop(s) have no map location (still geocoding, or the address needs fixing — see the card)` : 'it needs at least 2 stops'}.`);
      return;
    }
    const newOrder = resequence(pts, ROUTING_DEPOT, strategy).map((s) => s.id);
    const resolved = new Set(newOrder);
    setWbRoutes((prev) => prev.map((x) => {
      if (x.key !== key) return x;
      const tail = x.order.map(String).filter((id) => !resolved.has(id));   // never drop unresolvable ids
      return { ...x, order: [...newOrder, ...tail], strategy };   // remember + show the applied logic
    }));
    setLastAction(`Re-sequenced ${loadDisplayName(key) || 'load'} · ${RESEQ_LABELS[strategy] || strategy}`);
  }, [wbRoutes, stopById]);
  const wbMoveStop = useCallback((fromKey, stopNbr, toKey) => {
    if (!toKey || fromKey === toKey) return;
    const id = String(stopNbr);
    setWbRoutes((prev) => prev.map((r) => {
      // BOTH cards are hand-edited now — the source too. Leaving the source's applied strategy
      // (e.g. "Farthest first") standing made the dropdown refuse to re-apply that same strategy
      // later (same value ⇒ no change event), the reported "can't set it back to Farthest" bug.
      if (r.key === fromKey) return { ...r, order: r.order.filter((x) => x !== id), strategy: 'manual' };
      if (r.key === toKey) return r.order.includes(id) ? r : { ...r, order: [...r.order, id], strategy: 'manual' };
      return r;
    }));
    setLastAction(`Moved ${stopNbr} → ${loadDisplayName(toKey)}`);
  }, []);
  // Drag-and-drop between/within Compare cards (desktop). Drops a stop into `toKey` at the slot
  // before `beforeId` (or the end when null), and strips it from every other card so a stop only
  // ever sits on one route. Same-card drops reorder; cross-card drops move. Map polyline + numbers
  // redraw live off wbRoutes. (The `→` move menu stays for touch / a11y.)
  const wbDropStop = useCallback((fromKey, stopNbr, toKey, beforeId) => {
    if (!toKey) return;
    const id = String(stopNbr);
    const before = beforeId == null ? null : String(beforeId);
    if (id === before) return;                                  // dropped onto itself — no-op
    setWbRoutes((prev) => prev.map((r) => {
      if (r.key === toKey) {
        const order = r.order.filter((x) => x !== id);
        let idx = before == null ? order.length : order.indexOf(before);
        if (idx < 0) idx = order.length;
        order.splice(idx, 0, id);
        return { ...r, order, strategy: 'manual' };   // hand-ordered now — never auto re-sort (#280)
      }
      return r.order.includes(id) ? { ...r, order: r.order.filter((x) => x !== id), strategy: 'manual' } : r;
    }));
    setLastAction(fromKey === toKey ? `Reordered ${stopNbr} in ${loadDisplayName(toKey)}` : `Moved ${stopNbr} → ${loadDisplayName(toKey)}`);
  }, []);
  // Remove an order FROM a route (it becomes Unplanned on Save). Staged like every other edit:
  // dropped from the card's order and tracked in `removed` so the card + Save preview can show it,
  // and Undo can restore it. The actual unplan happens server-side on Save (planSequence removes a
  // stop that's no longer in the desired order); nothing is sent until Save → Confirm.
  const wbRemoveStop = useCallback((key, stopNbr) => {
    const id = String(stopNbr);
    setWbRoutes((prev) => prev.map((r) => {
      if (r.key !== key || !r.order.includes(id)) return r;
      const removed = (r.removed || []).includes(id) ? r.removed : [...(r.removed || []), id];
      // Remember WHERE it sat so Undo is a true undo. Without this the restore appended to the
      // end, so "remove #2 of 10 → oops → Undo" left the stop at #10: the card stayed dirty and
      // any later Save silently REORDERED the real load in NuVizz. Parallel map (not a reshaped
      // `removed`) so every existing consumer of the id list keeps working unchanged.
      const removedIdx = { ...(r.removedIdx || {}), [id]: r.order.indexOf(id) };
      return { ...r, order: r.order.filter((x) => x !== id), removed, removedIdx, strategy: 'manual' };
    }));
    setLastAction(`Removed ${stopNbr} from ${loadDisplayName(key) || 'load'} — unplans on Save`);
  }, []);
  // Strike EVERY order off a card in one click (the card's "Cancel route" button). Identical
  // staging to clicking each stop's ✕ in turn: all ids move to `removed` with their positions
  // recorded (so per-stop Undo restores in place), the order empties, and NOTHING is sent until
  // Save — which then flags emptyLoad and runs the red cancel-confirm popup before the write.
  const wbRemoveAllStops = useCallback((key) => {
    let n = 0;
    setWbRoutes((prev) => prev.map((r) => {
      if (r.key !== key || !r.order.length) return r;
      n = r.order.length;
      const removed = [...(r.removed || [])];
      const removedIdx = { ...(r.removedIdx || {}) };
      r.order.forEach((id0, i) => {
        const id = String(id0);
        if (!removed.includes(id)) removed.push(id);
        removedIdx[id] = i;
      });
      return { ...r, order: [], removed, removedIdx, strategy: 'manual' };
    }));
    setLastAction(`Struck every order off ${loadDisplayName(key) || 'load'} — Save CANCELS the route`);
    return n;
  }, []);
  const wbUndoRemove = useCallback((key, stopNbr) => {
    const id = String(stopNbr);
    setWbRoutes((prev) => prev.map((r) => {
      if (r.key !== key) return r;
      const removed = (r.removed || []).filter((x) => x !== id);
      const { [id]: idx, ...restIdx } = (r.removedIdx || {});
      if (r.order.includes(id)) return { ...r, removed, removedIdx: restIdx };
      // Splice back where it was. Clamped, because other edits may have shortened the order
      // since. Landing in its original slot means undoing every removal returns the card to
      // its baseline order — i.e. genuinely CLEAN, so Save stops offering a phantom reorder.
      const order = r.order.slice();
      const at = Number.isInteger(idx) && idx >= 0 ? Math.min(idx, order.length) : order.length;
      order.splice(at, 0, id);
      // Restored in place = back to baseline, so DON'T force 'manual' (that would keep the
      // re-sequence dropdown stuck on "Manual order (edited)" after a no-op remove+undo).
      // A restore anywhere else IS a hand-edit and still clears the strategy.
      const inPlace = Number.isInteger(idx) && at === idx;
      return { ...r, order, removed, removedIdx: restIdx, strategy: inPlace ? r.strategy : 'manual' };
    }));
  }, []);
  // Print the driver manifest for a Compare card's stops, in the card's CURRENT order (#263). Opens
  // the shared PrintDocModal. No API — built from the stops we already hold.
  const [wbManifest, setWbManifest] = useState(null);   // { title, html } | null
  const printWbManifest = useCallback((key) => {
    const route = wbRoutes.find((r) => r.key === key);
    if (!route) return;
    // boardStopById, not stopById: a stop with no geocode is still a stop the driver has to
    // make, and printing from the coord-only index silently dropped it off the manifest.
    const stops = route.order.map((id) => boardStopById.get(String(id))).filter(Boolean);
    if (!stops.length) { setLastAction(`${loadDisplayName(key)} has no stops to print`); return; }
    // Any id the board can't resolve at all can't be printed (no address to put on paper) —
    // say so out loud rather than handing over a manifest that's quietly one stop short.
    const missing = route.order.length - stops.length;
    if (missing > 0) setLastAction(`${loadDisplayName(key)}: ${missing} stop(s) aren’t on today’s board and are NOT on this manifest — check the card.`);
    const logo = (typeof window !== 'undefined' ? window.location.origin : '') + '/davis-logo.jpg';
    // Pass the card's human route NAME (not the DAVIS load number a Loads-grid-opened card is
    // keyed by) as the manifest header name.
    const displayName = route.name || loadDisplayName(key) || String(key);
    setWbManifest({ title: `Driver Manifest · ${displayName}`, html: buildManifestHtml(stops, logo, displayName) });
  }, [wbRoutes, boardStopById]);
  // Ninja-add: append a clicked stop to the active route (in click order), removing it from any
  // OTHER open route so a stop only ever sits on one compare-panel card. No-op if it's already there.
  const ninjaAddStop = useCallback((stopNbr) => {
    const id = String(stopNbr);
    // The OTHER dispatcher's device is staging this stop — don't grab it out from
    // under them (both Saves would fight over it; the later one silently wins).
    const claimedBy = peerClaimsRef.current.get(id);
    if (claimedBy) { showMapToast(`${stopNbr} is being staged by ${claimedBy} on another device — coordinate before planning it.`); return; }
    // A stop still PLANNED on a load that is NOT open in Compare must not be ninja'd onto a card:
    // nothing would stage its removal from the holder load, so Save would double-plan it (the
    // server can only see loads that are in the payload). Open the holder first = staged move.
    const s = stopById.get(id);
    const holder = s ? String(s.routeName || s.loadNbr || '') : '';
    if (s && !s.isUnplanned && holder && !openRouteKeys.has(holder)) {
      // Bring the SOURCE load into Compare so the move stages on both loads (a declarative Save can
      // only pull a stop off a route that is part of the Save). Then click the stop again to move it.
      // Card COUNT comes from wbRoutes — openRouteKeys is an identity set (key+name+loadNbr per card).
      if (wbRoutes.length >= WB_MAX) {
        showMapToast(`${stopNbr} is on ${loadDisplayName(holder) || holder} — Compare is full (${WB_MAX}/${WB_MAX}). Close a card, then click it again to move it.`);
      } else {
        openRouteInWorkbench(holder);
        showMapToast(`Opened ${loadDisplayName(holder) || holder} in Compare — click ${stopNbr} again to move it.`);
      }
      return;
    }
    setWbRoutes((prev) => {
      if (!prev.length) return prev;
      const target = (activeRouteKey && prev.some((r) => r.key === activeRouteKey)) ? activeRouteKey : prev[0].key;
      const already = prev.find((r) => r.key === target)?.order.includes(id);
      setLastAction(already ? `${stopNbr} already on ${target}` : `Ninja → ${stopNbr} onto ${target}`);
      if (already) return prev;
      return prev.map((r) => {
        // Any card whose order changes is hand-edited — clear its applied strategy so the
        // re-sequence dropdown stays re-applicable (see wbMoveStop note).
        if (r.key === target) return { ...r, order: [...r.order, id], strategy: 'manual' };
        return r.order.includes(id) ? { ...r, order: r.order.filter((x) => x !== id), strategy: 'manual' } : r;
      });
    });
  }, [activeRouteKey, stopById, openRouteKeys, wbRoutes.length]);
  // Bulk "send the current selection onto an open Compare load" (#258) — one click moves every
  // selected stop onto that route (deduped, and stripped from any other card so a stop sits on one
  // route), then clears the selection. Header shows one button per open route.
  const sendSelectionToRoute = useCallback((key) => {
    let ids = [...selectedIds].map(String);
    if (!key || !ids.length) return;
    // Strip stops the OTHER dispatcher's device started staging AFTER they were
    // selected here (the selection tools already refuse to add claimed stops).
    const claimedSel = ids.filter((id) => peerClaimsRef.current.get(id));
    if (claimedSel.length) {
      ids = ids.filter((id) => !peerClaimsRef.current.get(id));
      showMapToast(`Skipped ${claimedSel.length} stop(s) being staged by ${peerClaimsRef.current.get(claimedSel[0])} on another device.`);
      if (!ids.length) return;
    }
    // A stop planned on a load NOT open in Compare can't just be added to the target: the Save is
    // DECLARATIVE over the loads in the payload, so without the SOURCE load in the Save the stop would
    // double-plan. Instead of silently skipping it, AUTO-OPEN each such source load into Compare
    // (respecting the 3-card cap) and keep the stops selected — once the source is open a second Send
    // stages the real cross-load move (source releases the stop, target gains it, both loads Saved).
    const holderOf = (id) => { const s = stopById.get(id); return s && !s.isUnplanned ? String(s.routeName || s.loadNbr || '') : ''; };
    const blocked = ids.filter((id) => { const h = holderOf(id); return h && !openRouteKeys.has(h); });
    let keepSelected = [];
    if (blocked.length) {
      const blockedHolders = [...new Set(blocked.map(holderOf).filter(Boolean))];
      const slots = Math.max(0, WB_MAX - wbRoutes.length);   // cards, not identity-set entries
      const toOpen = new Set(blockedHolders.slice(0, slots));
      toOpen.forEach((h) => openRouteInWorkbench(h));   // opens the source card(s) so the move can stage
      keepSelected = blocked;                            // keep every blocked stop selected for the next Send
      ids = ids.filter((id) => !blocked.includes(id));   // this pass only stages the already-stageable stops
      const openedNames = [...toOpen].map((h) => loadDisplayName(h) || h);
      const heldNames = blockedHolders.filter((h) => !toOpen.has(h)).map((h) => loadDisplayName(h) || h);
      const parts = [];
      if (openedNames.length) parts.push(`Opened ${openedNames.join(', ')} in Compare — Send again to move ${blocked.filter((id) => toOpen.has(holderOf(id))).length} stop(s).`);
      if (heldNames.length) parts.push(`${heldNames.join(', ')} need a free card (Compare full ${WB_MAX}/${WB_MAX}) — close one, then Send.`);
      showMapToast(parts.join(' '));
      if (!ids.length) { setSelectedIds(new Set(keepSelected)); return; }
    }
    // Same-address twin guard: two ORDERS at one location render as pins stacked exactly on
    // top of each other, so a click-selection grabs only the top one and the second order
    // silently stays behind (the "missed one of these orders" case — 007144652 routed,
    // co-located 007144651 left unplanned). Same-address freight rides together, so every
    // UNPLANNED order sharing a selected stop's location is auto-included — loudly, and
    // removable from the card if the split was intentional.
    const twinNames = [];
    {
      const inIds = new Set(ids);
      const byMatchKey = new Map();
      for (const t of stops) {
        if (!t?.matchKey || !t.isUnplanned) continue;
        if (!byMatchKey.has(t.matchKey)) byMatchKey.set(t.matchKey, []);
        byMatchKey.get(t.matchKey).push(t);
      }
      for (const id of [...inIds]) {
        const s = stopById.get(id);
        for (const t of (s?.matchKey ? byMatchKey.get(s.matchKey) : null) || []) {
          const tn = String(t.stopNbr);
          if (wbStagedRef.current.get(tn) || peerClaimsRef.current.get(tn)) continue;   // staged on another card / another device — same guard as click/box select
          if (!inIds.has(tn)) { inIds.add(tn); twinNames.push(`${t.stopNbr} (${t.businessName || 'same address'})`); }
        }
      }
      if (twinNames.length) ids = [...inIds];
    }
    const idSet = new Set(ids);
    setWbRoutes((prev) => {
      if (!prev.some((r) => r.key === key)) return prev;
      return prev.map((r) => {
        // Hand-edit ⇒ clear the applied strategy on every touched card (see wbMoveStop note).
        if (r.key === key) {
          const have = new Set(r.order);
          const add = ids.filter((id) => !have.has(id));
          return add.length ? { ...r, order: [...r.order, ...add], strategy: 'manual' } : r;
        }
        return r.order.some((id) => idSet.has(id)) ? { ...r, order: r.order.filter((id) => !idSet.has(id)), strategy: 'manual' } : r;
      });
    });
    if (twinNames.length) {
      showMapToast(`⚠ Also added ${twinNames.length} co-located order${twinNames.length === 1 ? '' : 's'} the selection missed: ${twinNames.slice(0, 3).join(', ')}${twinNames.length > 3 ? '…' : ''} — remove from the card if you meant to split.`);
    }
    setLastAction(`Sent ${ids.length} selected stop${ids.length === 1 ? '' : 's'} → ${loadDisplayName(key) || 'load'}`);
    setSelectedIds(new Set(keepSelected));   // cleared when nothing was blocked; keeps cap/holder-pending stops for the next Send
  }, [selectedIds, stopById, openRouteKeys, stops, wbRoutes.length]); // showMapToast is stable and declared later — including it in deps would TDZ at render
  // The marker click listener is bound once; route ninja clicks through a ref so toggling ninja
  // (or closing the panel) never re-creates the markers. Null = ninja off / nothing to add to.
  useEffect(() => { ninjaActionRef.current = (ninjaMode && wbRoutes.length > 0) ? ninjaAddStop : null; }, [ninjaMode, wbRoutes.length, ninjaAddStop]);
  useEffect(() => { openRouteRef.current = openRouteInWorkbench; }, [openRouteInWorkbench]);
  // Ninja needs an open route; drop it when the panel empties so the map returns to normal toggling.
  useEffect(() => { if (!wbRoutes.length && ninjaMode) setNinjaMode(false); }, [wbRoutes.length, ninjaMode]);

  // Transient on-map hint (issue #232) — a small banner that auto-dismisses. Used to explain why
  // Ninja can't arm yet (no Compare route open) instead of leaving a silently-dead button.
  const [mapToast, setMapToast] = useState('');
  const mapToastTimer = useRef(null);
  const showMapToast = useCallback((msg) => {
    setMapToast(msg);
    if (mapToastTimer.current) clearTimeout(mapToastTimer.current);
    mapToastTimer.current = setTimeout(() => setMapToast(''), 4000);
  }, []);
  useEffect(() => () => { if (mapToastTimer.current) clearTimeout(mapToastTimer.current); }, []);

  // Live-dispatch (write) UI visibility — a persisted gear toggle so the dispatcher reveals the
  // driver-assign + dispatch controls without the ?write=1 URL flag. Seeds from that flag/env the
  // first time, then the toggle is the source of truth. A real write still needs the card's Live mode
  // AND the server NUVIZZ_WRITE_ENABLED flag — this only shows/hides the UI.
  const [liveWrite, setLiveWrite] = useState(() => {
    try { const v = localStorage.getItem('routing.liveWrite'); if (v === 'on') return true; if (v === 'off') return false; } catch { /* ignore */ }
    return LIVE_WRITE_FLAG;
  });
  useEffect(() => { try { localStorage.setItem('routing.liveWrite', liveWrite ? 'on' : 'off'); } catch { /* ignore */ } }, [liveWrite]);

  // ── Routes-panel driver assignment (live) ─────────────────────────────────────
  // A driver dropdown on each Routes card assigns a driver to that load on pick. Gated behind the
  // Live-dispatch gear toggle (liveWrite); the Beta/Live mode is the second gate — in Beta a pick
  // only previews, in Live it writes immediately via the assignDriver op (ASSIGN_DISPATCH with
  // assignDtls only = assign, not release). Declared here, AFTER liveWrite + showMapToast, which it
  // reads in its dependency arrays during render (TDZ guard).
  //
  // DEFAULTS LIVE, and the choice STICKS (Chad: "turn the beta off here and it to be live all the
  // time"). It used to reset to Beta on every page load, so a real assignment meant flipping the
  // switch again every single time — and a safety you always flip is one you stop reading. The
  // panel this lives in only appears when the Live-dispatch gear is already on, which is itself a
  // persisted, explicit opt-in, so this honors that choice instead of re-asking for it. The button
  // stays put: flip to ○ Beta any time for a dry run, and that sticks too.
  const [assignRoster, setAssignRoster] = useState([]);
  const [assignRosterError, setAssignRosterError] = useState(null);
  const assignRosterLoaded = useRef(false);
  const [assignLive, setAssignLive] = useState(() => {
    try { if (localStorage.getItem('routing.assignLive') === 'off') return false; } catch { /* private mode */ }
    return true;
  });
  useEffect(() => { try { localStorage.setItem('routing.assignLive', assignLive ? 'on' : 'off'); } catch { /* private mode */ } }, [assignLive]);
  const [assignedOverride, setAssignedOverride] = useState({});   // route key → driver name
  const [assigningKey, setAssigningKey] = useState(null);
  useEffect(() => { setAssignedOverride({}); }, [selectedDate]);   // don't carry a day's assignments onto another board
  useEffect(() => {
    if (!liveWrite || rightPanelMode !== 'routes' || assignRosterLoaded.current) return;
    assignRosterLoaded.current = true;
    let alive = true;
    callWrite('roster', {}).then((res) => {
      if (!alive) return;
      if (res.ok && Array.isArray(res.result?.drivers)) setAssignRoster(res.result.drivers);
      else setAssignRosterError(res.error || 'roster unavailable');
    }).catch((e) => { if (alive) setAssignRosterError(e?.message || 'roster error'); });
    return () => { alive = false; };
  }, [liveWrite, rightPanelMode]);
  const onAssignDriver = useCallback(async (g, driverId, driverName) => {
    if (!driverId) return;
    const label = loadDisplayName(g.name, g.loadNbr) || g.loadNbr;
    if (!assignLive) { showMapToast(`Beta — would assign ${driverName} to ${label} (nothing sent). Flip to ● Live to assign.`); return; }
    // The route group carries loadId only once its stops are enriched; a DRAFT/empty load has none.
    // Resolve the internal loadId (and the REAL load number) from the loads-roster scan, keyed by
    // route name or by the loadId itself — the same source the Compare panel already uses.
    const rosterEntry0 = loadRosterRef.current.get(String(g.name || '').trim().toLowerCase())
      || loadRosterRef.current.get(String(g.key || '').trim().toLowerCase())
      || (g.loadId ? loadRosterRef.current.get(String(g.loadId)) : null)
      || null;
    // Never take identity from an AMBIGUOUS name entry (two same-day loads share the name) —
    // assigning against the wrong instance persists silently in NuVizz.
    const rosterEntry = rosterEntry0 && !rosterEntry0.ambiguous ? rosterEntry0 : null;
    const loadId = g.loadId || rosterEntry?.loadId || null;
    const loadNbr = (g.loadNbr && looksLikeLoadNbr(g.loadNbr)) ? g.loadNbr : (rosterEntry?.loadNbr || null);
    if (!loadId) { showMapToast(`Can't assign ${label} — its NuVizz load id hasn't loaded yet.`); return; }
    setAssigningKey(g.key);
    let res;
    try {
      res = await callWrite('assignDriver', { routeId: loadId, loadId, loadNbr, driverId, driverName, date: selectedDate },
        { dryRun: false, clientOpId: newClientOpId(), createdBy: 'dispatcher' });
    } catch (e) { res = { ok: false, error: e?.message || 'network error' }; }
    setAssigningKey(null);
    if (res.ok && res.result?.ok !== false) {
      setAssignedOverride((p) => ({ ...p, [g.key]: driverName }));
      showMapToast(`✓ ${driverName} assigned to ${label}.`);
    } else {
      showMapToast(`✗ Assign failed for ${label}: ${res.error || res.result?.error || 'write error'}`);
    }
  }, [assignLive, showMapToast, selectedDate]);
  // Routes-panel "Dispatch" button — releases an already-assigned load in NuVizz (action DISPATCH,
  // the dispatchLoad op). Same Beta/Live safety + loadId resolution as onAssignDriver above; a
  // dispatched load's status won't flip in the board until the next scheduled scan, so this only
  // toasts success/failure rather than optimistically rewriting g.status.
  const [dispatchingKey, setDispatchingKey] = useState(null);
  const onDispatchLoad = useCallback(async (g) => {
    const label = loadDisplayName(g.name, g.loadNbr) || g.loadNbr;
    if (!assignLive) { showMapToast(`Beta — would dispatch ${label} (nothing sent). Flip to ● Live to dispatch.`); return; }
    const rosterEntry0 = loadRosterRef.current.get(String(g.name || '').trim().toLowerCase())
      || loadRosterRef.current.get(String(g.key || '').trim().toLowerCase())
      || (g.loadId ? loadRosterRef.current.get(String(g.loadId)) : null)
      || null;
    const rosterEntry = rosterEntry0 && !rosterEntry0.ambiguous ? rosterEntry0 : null;
    const loadId = g.loadId || rosterEntry?.loadId || null;
    const loadNbr = (g.loadNbr && looksLikeLoadNbr(g.loadNbr)) ? g.loadNbr : (rosterEntry?.loadNbr || null);
    if (!loadId) { showMapToast(`Can't dispatch ${label} — its NuVizz load id hasn't loaded yet.`); return; }
    setDispatchingKey(g.key);
    let res;
    try {
      res = await callWrite('dispatchLoad', { routeId: loadId, loadId, loadNbr, date: selectedDate },
        { dryRun: false, clientOpId: newClientOpId(), createdBy: 'dispatcher' });
    } catch (e) { res = { ok: false, error: e?.message || 'network error' }; }
    setDispatchingKey(null);
    if (res.ok && res.result?.ok !== false) {
      showMapToast(`✓ ${label} dispatched.`);
      // Reflect the confirmed dispatch IMMEDIATELY: the Routes card status comes from the
      // cached roster, which only refreshes with scans (paused overnight) — without this the
      // card kept reading Draft after a successful production dispatch. The override also
      // survives a stale roster refetch (see the roster effect's merge).
      const nm = String(g.name || '').trim().toLowerCase();
      // Key the '#id:' twin by loadId — the roster map's actual key — so the retire loop can
      // see agreement and drop it (a loadNbr-keyed twin never matched and re-applied forever).
      const idKey = g.loadId ?? g.loadNbr;
      dispatchOverrideRef.current.set(nm, 'Dispatched');
      if (idKey) dispatchOverrideRef.current.set('#id:' + String(idKey), 'Dispatched');
      setLoadStatusByName((prev) => {
        const n = new Map(prev);
        n.set(nm, 'Dispatched');
        if (idKey) n.set('#id:' + String(idKey), 'Dispatched');
        return n;
      });
    } else {
      showMapToast(`✗ Dispatch failed for ${label}: ${res.error || res.result?.error || 'write error'}`);
    }
  }, [assignLive, showMapToast, selectedDate]);
  // Ninja toolbar tap: arm/disarm when a Compare route is open; otherwise coach the dispatcher to
  // open one first (the button stays tappable so the hint is reachable on mobile too).
  const onNinjaTool = useCallback(() => {
    if (wbRoutes.length === 0) {
      showMapToast('Ninja needs a route — open one in the Routes list, then tap Ninja to drop stops onto it.');
      return;
    }
    setEligPaint(null);   // arming Ninja cancels an eligibility brush (one gesture at a time)
    setNinjaMode((v) => !v);
  }, [wbRoutes.length, showMapToast]);

  // ── Vehicle-eligibility marking (tractor-friendly green / box-truck-only red) ──
  // A lightweight "paint" mode: arm a brush, then click stops to set whether a 53'
  // tractor-trailer fits. The flag is a property of the LOCATION
  // (customer_notes.vehicle_eligibility, keyed by matchKey) so it sticks for every
  // future stop there. Repeated clicks on the SAME stop cycle through all three states
  // without touching the ⚙ brush: with the Tractor brush armed a stop goes
  // none → tractor (green) → box only (red) → cleared; the Box brush mirrors it
  // (none → box only → tractor → cleared). So a single brush can set either color and
  // still clear. Mutually exclusive with Box/Lasso/Ninja so a click only ever does one thing.
  const markEligibility = useCallback(async (s) => {
    if (!db || !s) return;
    const brush = eligPaintRef.current;            // 'tractor' | 'box' | null
    if (!brush) return;
    const mk = s.matchKey;
    if (!mk) { setLastAction(`${s.stopNbr}: no location key to mark`); return; }
    // The armed brush's own color is the FIRST state; a second click on the same stop
    // advances to the other color; a third clears — one brush, all three states.
    const primary = brush === 'box' ? 'box_only' : 'tractor';
    const secondary = brush === 'box' ? 'tractor' : 'box_only';
    const current = notes.get(mk)?.vehicle_eligibility || null;
    const next = current === primary ? secondary : current === secondary ? null : primary;
    const who = s.businessName || s.stopNbr;
    try {
      await setDoc(doc(db, 'customer_notes', mk), {
        match_key: mk,
        raw_name: s.businessName || '',
        vehicle_eligibility: next,
        vehicle_eligibility_at: serverTimestamp(),
        vehicle_eligibility_by: 'dispatcher',
        last_updated: serverTimestamp(),
      }, { merge: true });
      setLastAction(
        next === 'tractor' ? `${who} → tractor-trailer OK (green)`
        : next === 'box_only' ? `${who} → box truck only (red)`
        : `${who} → eligibility cleared`,
      );
    } catch (e) {
      setLastAction(`Couldn't mark ${s.stopNbr}: ${e.message}`);
    }
  }, [notes]);
  // Arm/disarm a brush (null = off). Arming one cancels Box/Lasso/Ninja (one gesture at
  // a time) and flashes an on-map reminder, since the control now lives in the ⚙ gear.
  const setEligBrush = useCallback((brush) => {
    setEligPaint(brush);
    if (brush) {
      setNinjaMode(false); setSelectMode(null); selectModeRef.current = null;
      showMapToast(brush === 'tractor'
        ? 'Tractor brush on — click a stop for green (53′ fits); click it again for red (box only), again to clear. Off in ⚙ to stop.'
        : 'Box brush on — click a stop for red (box only); click it again for green (53′ fits), again to clear. Off in ⚙ to stop.');
    }
  }, [showMapToast]);
  useEffect(() => { eligPaintRef.current = eligPaint; }, [eligPaint]);
  useEffect(() => { eligActionRef.current = eligPaint ? markEligibility : null; }, [eligPaint, markEligibility]);
  // Disarm the brush when the day changes so a hidden, still-armed brush can't silently
  // mark the new day's stops.
  useEffect(() => { setEligPaint(null); }, [selectedDate]);

  // Default trucks selected once profiles load.
  useEffect(() => {
    if (profiles.length && selectedTruckIds.size === 0) setSelectedTruckIds(new Set(profiles.map((p) => p.id)));
  }, [profiles]); // eslint-disable-line

  const result = job?.status === 'done' ? job.result : null;

  // "Debug this view" bundle for the routing screen — captures the solver state
  // (job/result routes, selection, strategy) so a coding agent can see the data
  // behind a bad route. Same scrub + Maps-key guard as the map bundle.
  const buildRoutingBundle = useCallback((note) => {
    const map = mapRef.current;
    let viewport = null;
    if (map && typeof map.getCenter === 'function') {
      const c = map.getCenter?.();
      const b = map.getBounds?.();
      viewport = {
        center: c ? { lat: +c.lat().toFixed(6), lng: +c.lng().toFixed(6) } : null,
        zoom: map.getZoom?.() ?? null,
        bounds: b ? b.toJSON() : null,
      };
    }
    const noteFor = (mk) => notes.get(mk) || null;
    const selStops = [...selectedIds].map((id) => stopById.get(String(id))).filter(Boolean);
    const res = job?.status === 'done' ? job.result : null;
    const bundle = {
      schema: 'dispatch-map.debug-capture/v1',
      captured_at: new Date().toISOString(),
      screen: 'routing',
      app: {
        version: APP_VERSION, build_commit: BUILD_COMMIT, build_time: BUILD_TIME, build_context: BUILD_CONTEXT,
        user_agent: typeof navigator !== 'undefined' ? navigator.userAgent : '',
        viewport_width: viewportWidth, is_mobile: isMobile,
      },
      scope: { date: selectedDate, mock_mode: MOCK_MODE, maps_loaded: !!google },
      source: { stops_count_total: stops.length, stops_positioned: positioned.length, loading, error: stopsError || null },
      routing: {
        job_status: job?.status ?? null,
        job_error: job?.error ?? null,
        strategy,
        intent,
        use_google: useGoogle,
        select_mode: selectMode,
        selected_stop_count: selectedIds.size,
        selected_truck_count: selectedTruckIds.size,
        truck_ids: [...selectedTruckIds],
        last_request: lastRequest || null,
        routes: res?.routes
          ? res.routes.map((r) => ({
              truckId: r.truckId,
              stop_count: Array.isArray(r.orderedStopIds) ? r.orderedStopIds.length : null,
              orderedStopIds: r.orderedStopIds,
              totalDistanceMeters: r.totalDistanceMeters,
              totalDurationSec: r.totalDurationSec,
              eta_count: Array.isArray(r.etas) ? r.etas.length : null,
              leg_count: Array.isArray(r.legs) ? r.legs.length : null,
            }))
          : null,
        meta: res?.meta || null,
      },
      selected_stops: selStops.slice(0, 500).map((s, i) => scrubStop(s, i, noteFor(s.matchKey))),
      selected_stops_truncated: selStops.length > 500,
      map_viewport: viewport,
      static_map_url: viewport ? buildStaticMapUrl(viewport.center, viewport.zoom, selStops) : null,
      notes_meta: { loaded_count: notes.size },
      warnings: [
        'static_map_url embeds the Maps key as __MAPS_KEY__ — swap it in locally to view; no real secret is included.',
        'Customer names/addresses/contacts and the raw NuVizz payload are scrubbed from stops.',
      ],
      user_note: note || '',
    };
    if (MAPS_KEY) {
      const text = JSON.stringify(bundle);
      if (text.includes(MAPS_KEY)) return JSON.parse(text.split(MAPS_KEY).join('__MAPS_KEY__'));
    }
    return bundle;
  }, [
    mapRef, notes, selectedIds, stopById, job, strategy, intent, useGoogle, selectMode,
    selectedTruckIds, lastRequest, stops, positioned, loading, stopsError, selectedDate,
    google, viewportWidth, isMobile,
  ]);
  useRegisterDebugCapture(debugCaptureRef, buildRoutingBundle);

  // ── Shared loads (live) + "view a saved load" mode ──
  // Viewing a saved load NEVER touches the live build state (selectedIds /
  // routeState / job / selectedDate). It only swaps what's RENDERED: baseResult +
  // the effective stop map. "Back to build" clears it and the in-progress build is
  // exactly as it was.
  const { loads, loading: loadsLoading, error: loadsError } = useSavedLoads();
  const [viewedLoad, setViewedLoad] = useState(null);
  const [manageError, setManageError] = useState(null);
  const viewing = !!viewedLoad;
  const baseResult = viewedLoad ? viewedLoad.result : result;

  // A saved load carries its own stop snapshot so it renders on the map on any day
  // (names + coords), independent of today's live cache. Old saves without it fall
  // back to the live stopById (same-day loads still work).
  const snapStopById = useMemo(() => {
    const snap = viewedLoad?.stops_snapshot;
    if (!snap) return null;
    const m = new Map();
    for (const [id, v] of Object.entries(snap)) {
      m.set(String(id), { stopNbr: String(id), businessName: v.name ?? id, lat: v.lat, lng: v.lng, pallets: v.pallets ?? null, cartons: v.cartons ?? null, weight: v.weight ?? null });
    }
    return m;
  }, [viewedLoad]);

  // ── Manual route reorder (client-side override of the engine's order) ──
  // routeState holds the CURRENT order per truck (the panel is the source of
  // truth) plus a `reordered` flag. It seeds from the engine result and the
  // dispatcher drags / moves stops to mutate it; the map + panel + recompute all
  // read from here. The engine is never called to reorder.
  const [routeState, setRouteState] = useState(null);
  useEffect(() => {
    if (result && Array.isArray(result.routes)) {
      const init = {};
      for (const r of result.routes) init[r.truckId] = { order: [...r.orderedStopIds], reordered: false };
      setRouteState(init);
    } else {
      setRouteState(null);
    }
  }, [result]);

  const reorderStop = useCallback((truckId, from, to) => {
    setRouteState((prev) => {
      if (!prev || !prev[truckId]) return prev;
      const order = moveItem(prev[truckId].order, from, to);
      if (order === prev[truckId].order || order.length !== prev[truckId].order.length) return prev;
      // moveItem returns a new array even on no-op; detect a real change:
      const changed = order.some((id, i) => id !== prev[truckId].order[i]);
      if (!changed) return prev;
      return { ...prev, [truckId]: { order, reordered: true } };
    });
  }, []);
  const moveStop = useCallback((truckId, index, dir) => reorderStop(truckId, index, index + dir), [reorderStop]);

  // Effective stop map / list — the saved load's snapshot when viewing one
  // (renders any day), else today's live stops. Selection/build always use the
  // live stopById; only the RESULT rendering switches.
  const vStopById = (viewing && snapStopById && snapStopById.size) ? snapStopById : stopById;
  const vPositioned = useMemo(
    () => (viewing ? [...vStopById.values()].filter((s) => s.lat != null && s.lng != null) : positioned),
    [viewing, vStopById, positioned],
  );

  // Per-route display: the CURRENT order, plus legs/ETAs/totals. Live build = the
  // engine's order or a haversine recompute after a manual reorder (read/write).
  // Viewing a saved load = render exactly as saved (read-only); its honesty flags
  // (manualReorder / matrixSource) carry through from the doc.
  const routesView = useMemo(() => {
    const res = baseResult;
    if (!res || !Array.isArray(res.routes)) return [];
    if (!viewing && !routeState) return [];
    const depot = res.meta?.depot || ROUTING_DEPOT;
    const departSec = Number(res.meta?.departEpochSec) || 0;
    const serviceSec = Number(res.meta?.serviceMin) > 0 ? Number(res.meta.serviceMin) * 60 : DEFAULT_SERVICE_SEC;
    const sum = (legs, k) => (Array.isArray(legs) ? legs.reduce((a, l) => a + (Number(l?.[k]) || 0), 0) : null);
    return res.routes.map((r, i) => {
      const color = ROUTE_PALETTE[i % ROUTE_PALETTE.length];
      if (viewing) {
        const reordered = !!(r.manualReorder || res.manualReorder);
        return { truckId: r.truckId, color, order: r.orderedStopIds || [], reordered, etas: r.etas, legs: r.legs,
          totalDistanceMeters: sum(r.legs, 'distanceMeters'), totalDurationSec: sum(r.legs, 'durationSec'), route: r };
      }
      const st = routeState[r.truckId] || { order: r.orderedStopIds, reordered: false };
      if (!st.reordered) {
        return { truckId: r.truckId, color, order: st.order, reordered: false, etas: r.etas, legs: r.legs,
          totalDistanceMeters: sum(r.legs, 'distanceMeters'), totalDurationSec: sum(r.legs, 'durationSec'), route: r };
      }
      const orderedStops = st.order.map((id) => { const s = stopById.get(String(id)); return s ? { id: String(id), lat: s.lat, lng: s.lng } : null; }).filter(Boolean);
      const rc = recomputeRoute(orderedStops, depot, departSec, serviceSec);
      return { truckId: r.truckId, color, order: st.order, reordered: true, etas: rc.etas, legs: rc.legs,
        totalDistanceMeters: rc.totalDistanceMeters, totalDurationSec: rc.totalDurationSec, route: r };
    });
  }, [baseResult, viewing, routeState, stopById]);

  // stopId -> { color, seq } for the numbered route markers (panel & map match).
  const routeInfo = useMemo(() => {
    const m = new Map();
    routesView.forEach((rv) => rv.order.forEach((id, idx) => m.set(String(id), { color: rv.color, seq: idx + 1 })));
    return m;
  }, [routesView]);

  // Compare-panel routes on the map ("not seeing my route optimizations in the compare panel").
  // Each open card gets a stable palette color; its stops are numbered + linked by a depot-anchored
  // polyline that redraws live on re-sequence / move / drag / ninja-add. While the Compare panel
  // has routes open it is the working set, so the map tracks THESE instead of the engine result.
  const wbRoutesColored = useMemo(
    () => wbRoutes.map((r, i) => ({ ...r, color: ROUTE_PALETTE[i % ROUTE_PALETTE.length] })),
    [wbRoutes],
  );
  const wbRouteInfo = useMemo(() => {
    const m = new Map();
    wbRoutesColored.forEach((rv) => rv.order.forEach((id, idx) => m.set(String(id), { color: rv.color, seq: idx + 1 })));
    return m;
  }, [wbRoutesColored]);
  const effectiveRouteInfo = wbRoutesColored.length ? wbRouteInfo : routeInfo;

  // The plan to persist on Save — engine result with any manual order applied.
  const editedResultForSave = useMemo(() => {
    if (!result) return null;
    const anyReordered = routeState && Object.values(routeState).some((s) => s.reordered);
    if (!anyReordered) return result;
    const byTruck = new Map(routesView.map((rv) => [rv.truckId, rv]));
    return {
      ...result,
      manualReorder: true,
      routes: result.routes.map((r) => {
        const rv = byTruck.get(r.truckId);
        if (!rv || !rv.reordered) return r;
        return { ...r, orderedStopIds: rv.order, etas: rv.etas, legs: rv.legs, manualReorder: true, drivenEstimate: 'haversine' };
      }),
    };
  }, [result, routeState, routesView]);

  // Selection tally + a SPECIFIC per-restriction summary (replaces the old vague
  // "equipment restriction in selection" line). Counts each restriction key and
  // oversize across the selected stops, resolved through the same helpers the
  // map markers use.
  const tally = useMemo(() => {
    let skids = 0, pieces = 0, weight = 0;
    const counts = {};
    let oversize = 0;
    for (const id of selectedIds) {
      const s = stopById.get(String(id));
      if (!s) continue;
      skids += Number(s.cartons) || 0;       // NuVizz totalCartons = real skids
      pieces += Number(s.pallets) || 0;      // NuVizz totalPallets = total pieces
      weight += Number(s.weight) || 0;
      if (stopLooksOversize(s)) oversize += 1;
      const note = notes.get(s.matchKey);
      for (const k of getRestrictionBadgeKeys(note || null)) counts[k] = (counts[k] || 0) + 1;
    }
    const summary = Object.entries(counts).map(([k, n]) => `${n} ${RESTRICTION_ICONS[k]?.short || k}`);
    if (oversize) summary.push(`${oversize} oversize`);
    return { count: selectedIds.size, skids, pieces, weight, summary };
  }, [selectedIds, stopById, notes]);

  const selectedStops = useMemo(
    () => [...selectedIds].map((id) => stopById.get(String(id))).filter(Boolean),
    [selectedIds, stopById],
  );

  const toggleStop = useCallback((id) => {
    const k = String(id);
    // Already staged on an open Compare card → don't let the selection grab it (Ninja is the
    // move tool). setLastAction is used (not a toast dep) so this callback stays stable and
    // the marker layer doesn't rebuild on every staging edit.
    const holder = wbStagedRef.current.get(k);
    // De-selecting is always allowed (a stop can be selected AND staged via the keep-selected
    // Send flow — the guard used to lock it in the selection forever); only ADDING a staged
    // stop to the selection is blocked.
    if (holder) {
      let removed = false;
      setSelectedIds((prev) => { if (!prev.has(k)) return prev; removed = true; const n = new Set(prev); n.delete(k); return n; });
      if (!removed) setLastAction(`${k} is already on ${loadDisplayName(holder) || holder} — remove it there or use Ninja to move it`);
      return;
    }
    // Claimed by the OTHER dispatcher's Compare cards (presence layer) — same rule
    // as a local card: de-select is allowed, adding it to the selection is not.
    const peer = peerClaimsRef.current.get(k);
    if (peer) {
      let removed = false;
      setSelectedIds((prev) => { if (!prev.has(k)) return prev; removed = true; const n = new Set(prev); n.delete(k); return n; });
      if (!removed) setLastAction(`${k} is being staged by ${peer} on another device — coordinate before planning it`);
      return;
    }
    setSelectedIds((prev) => { const n = new Set(prev); n.has(k) ? n.delete(k) : n.add(k); return n; });
  }, []);
  const removeStop = useCallback((id) => {
    setSelectedIds((prev) => { const n = new Set(prev); n.delete(String(id)); return n; });
  }, []);
  // One click takes the WHOLE place: a marker with N co-located orders (the count badge)
  // toggles ALL of them in/out of the selection together — two orders at one stop used to
  // take two clicks, three took three. Direction follows the clicked stop (unselected →
  // select all; selected → clear all). mateIds come from the marker build (the same set the
  // badge counts), and ids staged on a Compare card stay put — same rule as toggleStop.
  const toggleStopGroup = useCallback((id, mateIds) => {
    const k = String(id);
    const ids = (Array.isArray(mateIds) && mateIds.length ? mateIds : [k]).map(String);
    const held = ids.filter((x) => wbStagedRef.current.get(x));
    const free = ids.filter((x) => !wbStagedRef.current.get(x) && !peerClaimsRef.current.get(x));
    if (!free.length) {
      const h = wbStagedRef.current.get(k) || wbStagedRef.current.get(held[0]);
      if (h) {
        setLastAction(`${held.length > 1 ? `These ${held.length} orders are` : `${k} is`} already on ${loadDisplayName(h) || h} — remove there or use Ninja to move`);
      } else {
        // Whole group claimed by the other dispatcher's device (presence layer).
        const claimed = ids.filter((x) => peerClaimsRef.current.get(x));
        const who = peerClaimsRef.current.get(k) || peerClaimsRef.current.get(claimed[0]);
        setLastAction(`${claimed.length > 1 ? `These ${claimed.length} orders are` : `${k} is`} being staged by ${who} on another device — coordinate before planning`);
      }
      return;
    }
    setSelectedIds((prev) => {
      const n = new Set(prev);
      // Direction from the GROUP, not the clicked stop: at a stacked location the click often
      // lands on a staged/numbered pin that can never be in the selection, which froze `on`
      // at true and made map de-selection impossible. Any free mate unselected → select all;
      // all free mates selected → clear all.
      const on = free.some((x) => !n.has(x));
      for (const x of free) { if (on) n.add(x); else n.delete(x); }
      return n;
    });
  }, []);
  const clearSelection = useCallback(() => { setSelectedIds(new Set()); setLastAction('Cleared selection'); }, []);

  // ── Bottom-table pick handlers (the dispatch-Map grid, made route-able) ──
  // Pan/zoom the map to a stop.
  const panToStop = useCallback((s) => {
    if (!s || s.lat == null || s.lng == null || !mapRef.current) return;
    mapRef.current.panTo({ lat: s.lat, lng: s.lng });
    if ((mapRef.current.getZoom() || 0) < 12) mapRef.current.setZoom(13);
  }, []);
  // Tap a table row → frame it on the map AND toggle it into the route selection,
  // so the dispatcher can build a route straight from the spreadsheet.
  const pickStopFromTable = useCallback((s) => {
    if (!s) return;
    panToStop(s);
    if (viewing) return;                       // saved-load view is read-only
    // A PLANNED stop → pull its route up in the Compare panel ("click a stop, see its route").
    // Unplanned/pool stops keep the selection toggle so route-building from the pool is unaffected.
    const routeKey = !s.isUnplanned ? (s.routeName || s.loadNbr) : null;
    if (routeKey) { openRouteInWorkbench(routeKey); return; }
    toggleStop(s.stopNbr);
  }, [panToStop, viewing, toggleStop, openRouteInWorkbench]);
  // Same overlay-aware fit as the dispatch Map: the bottom data grid floats INSIDE the map
  // container, so Google's canvas runs underneath it and a flat 60px pad frames a route's
  // southern stops behind the grid. Pad the bottom by the grid's live height at call time.
  const bottomGridRef = useRef(null);
  const fitPad = useCallback(() => ({ top: 60, right: 60, left: 60, bottom: 60 + (bottomGridRef.current?.offsetHeight || 0) }), []);

  // Right Routes-panel click → open that route into the workbench (cards) and frame it on the
  // map. Unlike pickLoadFromTable it does NOT add the stops to the selection set.
  const onPickRoute = useCallback((key) => {
    openRouteInWorkbench(key);
    if (!google || !mapRef.current) return;
    const pts = positionedAll.filter((s) => (s.routeName || s.loadNbr) === key && s.lat != null && s.lng != null);
    if (!pts.length) return;
    const b = new google.maps.LatLngBounds();
    pts.forEach((s) => b.extend({ lat: s.lat, lng: s.lng }));
    mapRef.current.fitBounds(b, fitPad());
  }, [openRouteInWorkbench, google, positionedAll, fitPad]);

  // ── NEW ROUTE (§R) ──────────────────────────────────────────────────────────
  // Chad, Jul 30: "I want to be able to create a route in the routing tab." Cancelling a
  // route was one-way until now — the app could destroy one but the rebuild had to happen in
  // the portal.
  const [newRouteOpen, setNewRouteOpen] = useState(false);
  const [newRouteBusy, setNewRouteBusy] = useState(false);
  const [newRouteError, setNewRouteError] = useState(null);
  const openNewRoute = useCallback(() => { setNewRouteError(null); setNewRouteOpen(true); }, []);
  // Opening a new route is now LOCAL ONLY (Aug 3): NuVizz refuses an empty route (903), so
  // nothing can be sent until the card has orders. The modal makes a PENDING card
  // (pendingCreate: true, no loadId); the workbench Save creates the route in NuVizz with the
  // card's whole stop list riding the one create call. Closing the card discards it —
  // nothing ever existed in NuVizz.
  const createNewRoute = useCallback((routeName, loadNbr) => {
    setNewRouteError(null);
    if (wbRoutes.length >= WB_MAX) { setNewRouteError(`Compare is full (${WB_MAX} routes) — close one first, then create.`); return; }
    setNewRouteOpen(false);
    const key = routeName;
    setWbRoutes((prev) => (prev.some((x) => x.key === key) ? prev : [...prev,
      { key, name: routeName, loadNbr, loadId: null, pendingCreate: true, order: [], baseline: [], collapsed: false }]));
    showMapToast(`Route card ${routeName} opened — drag orders onto it, then Save to create it in NuVizz with all its stops.`);
  }, [showMapToast, wbRoutes.length]);
  // A pending card's create CONFIRMED by the server: flip it to a real card in place (same
  // key) and index its verified identity so assign-driver / later re-opens resolve it before
  // the next roster fetch.
  const onRouteCreated = useCallback((key, made) => {
    const entry = { loadId: made.loadId ? String(made.loadId) : null, name: made.name || key, loadNbr: made.loadNbr ? String(made.loadNbr) : null };
    try {
      const idx = loadRosterRef.current;
      if (entry.name) idx.set(String(entry.name).trim().toLowerCase(), entry);
      if (entry.loadId) idx.set(String(entry.loadId), entry);
      if (entry.loadNbr) idx.set(String(entry.loadNbr), entry);
    } catch { /* a stale index never blocks the card update below */ }
    setWbRoutes((prev) => prev.map((r) => (r.key === key
      ? { ...r, pendingCreate: false, name: entry.name, loadNbr: entry.loadNbr ?? r.loadNbr, loadId: entry.loadId ?? r.loadId }
      : r)));
  }, []);

  // Frame ALL of a driver's stops (they may run multiple routes). Lighter than onPickRoute —
  // it only fits the map bounds, it doesn't open every route in the workbench.
  const onPickDriver = useCallback((routeKeys) => {
    const keys = new Set((routeKeys || []).map(String));
    if (!keys.size || !google || !mapRef.current) return;
    const pts = positionedAll.filter((s) => keys.has(String(s.routeName || s.loadNbr)) && s.lat != null && s.lng != null);
    if (!pts.length) return;
    const b = new google.maps.LatLngBounds();
    pts.forEach((s) => b.extend({ lat: s.lat, lng: s.lng }));
    mapRef.current.fitBounds(b, fitPad());
  }, [google, positionedAll, fitPad]);

  // The selected-stops list: persistent on desktop, collapsed by default on mobile.
  const [listOpen, setListOpen] = useState(!isMobile);
  useEffect(() => { setListOpen(!isMobile); }, [isMobile]);

  // ── Touch-native selection primitives ──
  const clearTemp = useCallback(() => {
    tempMarkersRef.current.forEach((m) => m.setMap(null));
    tempMarkersRef.current = [];
    if (tempShapeRef.current) { tempShapeRef.current.setMap(null); tempShapeRef.current = null; }
  }, []);
  const addTempMarker = useCallback((latLng) => {
    if (!google || !mapRef.current) return;
    const m = new google.maps.Marker({
      position: latLng, map: mapRef.current, clickable: false, zIndex: 60,
      icon: { path: google.maps.SymbolPath.CIRCLE, scale: 5, fillColor: '#f59e0b', fillOpacity: 1, strokeColor: '#fff', strokeWeight: 1.5 },
    });
    tempMarkersRef.current.push(m);
  }, [google]);
  const redrawLasso = useCallback(() => {
    if (!google || !mapRef.current) return;
    if (tempShapeRef.current) tempShapeRef.current.setMap(null);
    tempShapeRef.current = new google.maps.Polyline({
      path: lassoVtxRef.current.map((v) => ({ lat: v.lat, lng: v.lng })),
      strokeColor: BRAND, strokeWeight: 2, strokeOpacity: 0.9, map: mapRef.current, zIndex: 55,
    });
  }, [google]);
  const cancelMode = useCallback(() => {
    clearTemp();
    boxCornersRef.current = []; lassoVtxRef.current = [];
    lassoDrawingRef.current = false; lassoPxRef.current = []; setLassoPath([]);
    selectModeRef.current = null;
    setSelectMode(null); setBoxStep(0); setLassoCount(0);
  }, [clearTemp]);
  const beginMode = useCallback((mode) => {
    clearTemp();
    boxCornersRef.current = []; lassoVtxRef.current = [];
    selectModeRef.current = mode;
    setEligPaint(null);   // arming Box/Lasso cancels an eligibility brush
    setSelectMode(mode); setBoxStep(0); setLassoCount(0); setLastAction(null);
  }, [clearTemp]);
  const addEnclosed = useCallback((arr) => {
    if (!arr.length) { setLastAction('No stops in that area'); return; }
    // Skip stops already staged on an open Compare card (see wbStagedRef) — a box/lasso over
    // an area with an open route must not re-grab its stops onto the selection. Same for
    // stops the OTHER dispatcher's device is staging (peerClaimsRef, presence layer).
    const staged = wbStagedRef.current;
    const claims = peerClaimsRef.current;
    const take = arr.filter((s) => !staged.has(String(s.stopNbr)) && !claims.has(String(s.stopNbr)));
    const skippedLocal = arr.filter((s) => staged.has(String(s.stopNbr))).length;
    const skippedPeer = arr.length - take.length - skippedLocal;
    if (!take.length) {
      setLastAction(skippedPeer && !skippedLocal
        ? `All ${arr.length} stop${arr.length === 1 ? ' is' : 's are'} being staged on another device`
        : `All ${arr.length} stop${arr.length === 1 ? ' is' : 's are'} already on open Compare cards${skippedPeer ? ' or staged on another device' : ''}`);
      return;
    }
    setSelectedIds((prev) => { const n = new Set(prev); for (const s of take) n.add(String(s.stopNbr)); return n; });
    setLastAction(`Added ${take.length} stop${take.length === 1 ? '' : 's'}${skippedLocal ? ` · skipped ${skippedLocal} already on open cards` : ''}${skippedPeer ? ` · skipped ${skippedPeer} staged on another device` : ''}`);
  }, []);

  // ── Pin relocation + address edit handlers (ported from MapScreen 6826-6909) ──
  // startMoveLocation disarms Routing's own map tools (Box/Lasso + eligibility
  // brush) so a click during the drag can't fight it. The rest are verbatim except
  // refresh→refreshStops (the cheap Firestore board re-read — NOT a NuVizz scan).
  const startMoveLocation = useCallback((stop) => {
    cancelMode();
    setEligPaint(null);
    setMovedTo(null);
    setMovingStop(stop);
  }, [cancelMode]);
  const autoFixAddress = useCallback(async (stop, suggestion) => {
    if (!db || !stop || !suggestion) return;
    const fields = {
      addr1: (suggestion.addr1 || '').trim(),
      addr2: (suggestion.addr2 || '').trim(),
      city: stop.city || '', state: stop.state || '', zip: stop.zip || '',
    };
    const q = [fields.addr1, fields.city, fields.state, fields.zip].filter(Boolean).join(', ');
    let geo = null, geoErr = null;
    try { geo = await geocodeAddress(google, q); } catch (e) { geoErr = e; }
    const payload = {
      match_key: stop.matchKey,
      raw_name: stop.businessName || '',
      address_override: fields,
      address_override_at: serverTimestamp(),
      last_updated: serverTimestamp(),
    };
    if (geo) { payload.location_override = { lat: geo.lat, lng: geo.lng }; payload.location_override_at = serverTimestamp(); }
    await setDoc(doc(db, 'customer_notes', stop.matchKey), payload, { merge: true });
    refreshStops({ silent: true });
    if (geoErr) throw new Error(`Address saved, but the pin couldn’t be moved — ${geoErr.message}. Enable the Geocoding API or use “Correct pin location” to drag it.`);
  }, [google, refreshStops]);
  // Text customer + save customer note — parity with the Map stop panel (ported), so a
  // Routing stop's detail has the SAME editor/actions. resolveStopPhone / SmsComposeModal /
  // bumpProHistory are the shared helpers the Map path uses; saves write customer_notes by
  // matchKey (zero NuVizz calls) then re-read the board.
  const [routingSmsTargets, setRoutingSmsTargets] = useState(null);
  const textCustomer = useCallback((stop) => {
    if (!stop) return;
    const phone = resolveStopPhone(stop, notes.get(stop.matchKey));
    setRoutingSmsTargets({ title: `Text ${stop.businessName || 'customer'}`, recipients: [{ to: phone, label: stop.businessName || stop.stopNbr }], initialText: stopRefPrefill(stop) });
  }, [notes]);
  // Text the driver assigned to THIS order, prefilled with PRO + customer (parity with the Map
  // stop panel). Number resolves server-side from the roster; zero NuVizz calls.
  const textDriverForStop = useCallback((stop) => {
    const driverName = stop?.driverName;
    if (!driverName) return;
    setRoutingSmsTargets({ title: `Text ${driverName}`, recipients: [{ driverName, label: driverName }], initialText: stopRefPrefill(stop) });
  }, []);
  const notesDrivers = useMemo(() => {
    const seen = new Set(); const out = [];
    const add = (name) => { const nm = (name || '').trim(); const k = nm.toLowerCase(); if (!nm || seen.has(k)) return; seen.add(k); out.push({ driverName: nm }); };
    (stops || []).forEach((s) => add(s.driverName));
    (driverRoster?.drivers || []).forEach((d) => add(d?.name));
    return out.sort((a, b) => a.driverName.localeCompare(b.driverName));
  }, [stops, driverRoster]);
  const [savingNote, setSavingNote] = useState(false);
  const [saveNoteError, setSaveNoteError] = useState(null);
  const saveStopNote = useCallback(async (draft) => {
    if (!db || !panelStop) return;
    setSavingNote(true); setSaveNoteError(null);
    try {
      const key = panelStop.matchKey;
      const existing = notes.get(key);
      const pro = panelStop.pro;
      const proHistory = pro ? bumpProHistory(existing?.pro_history, pro) : (existing?.pro_history || []);
      await setDoc(doc(db, 'customer_notes', key), {
        ...draft,
        match_key: key,
        raw_name: draft.raw_name || panelStop.businessName || '',
        raw_address: draft.raw_address || [panelStop.addr1, panelStop.city, panelStop.state, panelStop.zip].filter(Boolean).join(', '),
        pro_history: proHistory,
        last_updated: serverTimestamp(),
        updated_by: NOTES_UPDATED_BY,
      }, { merge: true });
      refreshStops({ silent: true });
    } catch (e) { setSaveNoteError(e.message); } finally { setSavingNote(false); }
  }, [notes, panelStop, refreshStops]);
  const cancelMoveLocation = useCallback(() => { setMovingStop(null); setMovedTo(null); }, []);
  const saveStopLocation = useCallback(async () => {
    if (!db || !movingStop || !movedTo) return;
    setSavingLoc(true);
    try {
      await setDoc(doc(db, 'customer_notes', movingStop.matchKey), {
        match_key: movingStop.matchKey,
        raw_name: movingStop.businessName || '',
        location_override: { lat: movedTo.lat, lng: movedTo.lng },
        location_override_at: serverTimestamp(),
        last_updated: serverTimestamp(),
      }, { merge: true });
      setMovingStop(null); setMovedTo(null);
    } catch (e) { console.error('save location override', e); }
    finally { setSavingLoc(false); }
  }, [movingStop, movedTo]);
  const resetStopLocation = useCallback(async () => {
    if (!db || !movingStop) return;
    setSavingLoc(true);
    try {
      await setDoc(doc(db, 'customer_notes', movingStop.matchKey), {
        match_key: movingStop.matchKey, location_override: null, last_updated: serverTimestamp(),
      }, { merge: true });
      setMovingStop(null); setMovedTo(null);
    } catch (e) { console.error('reset location override', e); }
    finally { setSavingLoc(false); }
  }, [movingStop]);
  useEffect(() => {
    if (movingMarkerRef.current) { movingMarkerRef.current.setMap(null); movingMarkerRef.current = null; }
    if (!google || !mapRef.current || !movingStop) return;
    const ov = notes.get(movingStop.matchKey)?.location_override;
    const start = {
      lat: (ov && typeof ov.lat === 'number') ? ov.lat : movingStop.lat,
      lng: (ov && typeof ov.lng === 'number') ? ov.lng : movingStop.lng,
    };
    if (start.lat == null || start.lng == null) return;
    setMovedTo(start);
    const m = new google.maps.Marker({
      position: start, map: mapRef.current, draggable: true, zIndex: 99999,
      icon: { url: pinSvgStatus('#1e5b92', {}), scaledSize: new google.maps.Size(34, 44), anchor: new google.maps.Point(17, 42) },
      title: 'Drag to the correct location',
      animation: google.maps.Animation.DROP,
    });
    m.addListener('dragend', () => { const p = m.getPosition(); if (p) setMovedTo({ lat: p.lat(), lng: p.lng() }); });
    movingMarkerRef.current = m;
    // Don't move the map if the pin is already on screen (Chad: "the map shouldn't
    // have moved at all"). Only recenter when the stop sits outside the current view,
    // so the draggable pin can never drop off-screen where you can't grab it.
    const b = mapRef.current.getBounds();
    if (!b || !b.contains(new google.maps.LatLng(start.lat, start.lng))) {
      mapRef.current.panTo(start);
      if ((mapRef.current.getZoom() || 0) < 16) mapRef.current.setZoom(18);
    }
    return () => { m.setMap(null); };
  }, [google, movingStop]); // eslint-disable-line react-hooks/exhaustive-deps
  const addInView = useCallback(() => {
    if (!google || !mapRef.current) { setLastAction('Map not ready'); return; }
    const b = mapRef.current.getBounds();
    if (!b) { setLastAction('Map not ready'); return; }
    const ne = b.getNorthEast(), sw = b.getSouthWest();
    const box = { north: ne.lat(), south: sw.lat(), east: ne.lng(), west: sw.lng() };
    addEnclosed(positionedRef.current.filter((s) => latLngInBounds(s.lat, s.lng, box)));
  }, [google, addEnclosed]);
  const finishLasso = useCallback(() => {
    const verts = lassoVtxRef.current;
    if (verts.length < 3) { setLastAction('Tap at least 3 points first'); return; }
    const poly = verts.map((v) => [v.lat, v.lng]);
    const enclosed = positionedRef.current.filter((s) => pointInPolygon(s.lat, s.lng, poly));
    addEnclosed(enclosed);
    cancelMode();
  }, [addEnclosed, cancelMode]);
  // A tap on the map (or a marker) while a draw mode is active places a corner /
  // vertex. The once-bound map listener calls the latest version via a ref.
  const handleSelectPoint = useCallback((latLng) => {
    const mode = selectModeRef.current;
    if (!mode || !google || !mapRef.current || !latLng) return;
    if (mode === 'box') {
      boxCornersRef.current.push({ lat: latLng.lat(), lng: latLng.lng() });
      addTempMarker(latLng);
      if (boxCornersRef.current.length >= 2) {
        const box = boxFromCorners(boxCornersRef.current[0], boxCornersRef.current[1]);
        addEnclosed(positionedRef.current.filter((s) => latLngInBounds(s.lat, s.lng, box)));
        cancelMode();
      } else {
        setBoxStep(1);
      }
    } else if (mode === 'lasso') {
      lassoVtxRef.current.push({ lat: latLng.lat(), lng: latLng.lng() });
      addTempMarker(latLng);
      redrawLasso();
      setLassoCount(lassoVtxRef.current.length);
    }
  }, [google, addTempMarker, addEnclosed, redrawLasso, cancelMode]);
  useEffect(() => { handleSelectPointRef.current = handleSelectPoint; }, [handleSelectPoint]);

  // The weekday key drives the receiving-hours restriction badges (same as the Map).
  const selectedDayKey = useMemo(() => weekdayKeyFromDate(selectedDate), [selectedDate]);

  // Hover emphasis for the rich image-pin markers — scale the rendered SVG up ~30%
  // and shift the anchor to match (image icons have no Symbol `scale`). Falls back
  // to the Symbol-path bump for any non-image icon (e.g. temp selection dots).
  const emphIcon = useCallback((base) => {
    if (base && base.url && base.scaledSize) {
      const f = 1.3;
      const w = Math.round(base.scaledSize.width * f), h = Math.round(base.scaledSize.height * f);
      return { ...base, scaledSize: new google.maps.Size(w, h), anchor: new google.maps.Point(base.anchor.x * f, base.anchor.y * f) };
    }
    return { ...base, scale: (base.scale || 6) + 2.5, strokeColor: '#0f172a', strokeWeight: 2 };
  }, [google]);

  // Desktop drag-box: convert a container-pixel point to LatLng via the overlay
  // projection (exact, unlike interpolating viewport bounds).
  const pxToLatLng = useCallback((px, py) => {
    const proj = overlayRef.current?.getProjection();
    if (!proj || !google) return null;
    return proj.fromContainerPixelToLatLng(new google.maps.Point(px, py));
  }, [google]);
  const relPoint = (e) => { const r = e.currentTarget.getBoundingClientRect(); return { x: e.clientX - r.left, y: e.clientY - r.top }; };
  const onBoxDown = useCallback((e) => { const p = relPoint(e); dragStartRef.current = p; setDragRect({ x0: p.x, y0: p.y, x1: p.x, y1: p.y }); }, []);
  const onBoxMove = useCallback((e) => { if (!dragStartRef.current) return; const p = relPoint(e); setDragRect({ x0: dragStartRef.current.x, y0: dragStartRef.current.y, x1: p.x, y1: p.y }); }, []);
  const onBoxUp = useCallback((e) => {
    const start = dragStartRef.current;
    dragStartRef.current = null; setDragRect(null);
    if (!start) return;
    const p = relPoint(e);
    if (Math.abs(p.x - start.x) < 4 && Math.abs(p.y - start.y) < 4) { cancelMode(); return; } // a click, not a drag
    const a = pxToLatLng(start.x, start.y), b = pxToLatLng(p.x, p.y);
    if (a && b) {
      const box = boxFromCorners({ lat: a.lat(), lng: a.lng() }, { lat: b.lat(), lng: b.lng() });
      addEnclosed(positionedRef.current.filter((s) => latLngInBounds(s.lat, s.lng, box)));
    }
    cancelMode();
  }, [pxToLatLng, addEnclosed, cancelMode]);

  // Desktop freehand drag-lasso (pointer-captured; stays armed for repeat draws —
  // the Cancel button / Esc exits). pointInPolygon over the drawn pixel path
  // mapped to LatLng, reusing the proven selection geometry.
  const onLassoDown = useCallback((e) => { const p = relPoint(e); lassoDrawingRef.current = true; lassoPxRef.current = [p]; setLassoPath([p]); }, []);
  const onLassoMove = useCallback((e) => {
    if (!lassoDrawingRef.current) return;
    const p = relPoint(e);
    const arr = lassoPxRef.current;
    const last = arr[arr.length - 1];
    if (last && Math.hypot(p.x - last.x, p.y - last.y) < 3) return; // throttle by distance
    arr.push(p); setLassoPath([...arr]);
  }, []);
  const onLassoUp = useCallback(() => {
    if (!lassoDrawingRef.current) return;
    lassoDrawingRef.current = false;
    const pts = lassoPxRef.current;
    lassoPxRef.current = []; setLassoPath([]);
    if (pts.length < 3) { setLastAction('Draw a longer shape around the stops'); return; }
    const poly = pts.map((p) => { const ll = pxToLatLng(p.x, p.y); return ll ? [ll.lat(), ll.lng()] : null; }).filter(Boolean);
    if (poly.length >= 3) addEnclosed(positionedRef.current.filter((s) => pointInPolygon(s.lat, s.lng, poly)));
    // stay in lasso mode so the dispatcher can draw more; Cancel/Esc exits.
  }, [pxToLatLng, addEnclosed]);

  // Re-sequence ONE route client-side (Min distance / Closest / Farthest / Reverse),
  // writing into routeState exactly like a manual drag so the map + ETAs update live
  // and it carries the "Manual order / straight-line estimate" treatment.
  const onResequence = useCallback((truckId, strategy) => {
    if (!strategy) return;
    const depot = result?.meta?.depot || ROUTING_DEPOT;
    const engineRoute = (result?.routes || []).find((r) => r.truckId === truckId);
    setRouteState((prev) => {
      // Seed from routeState if present, else from the freshly-built engine route —
      // so the dropdown reorders a route even before any manual edit (don't no-op).
      const curOrder = (prev && prev[truckId]) ? prev[truckId].order
        : (engineRoute ? engineRoute.orderedStopIds.map(String) : null);
      if (!curOrder) return prev;
      const stops = curOrder.map((id) => { const s = stopById.get(String(id)); return s ? { id: String(id), lat: s.lat, lng: s.lng } : null; }).filter(Boolean);
      if (stops.length < 2) return prev;
      const newOrder = resequence(stops, depot, strategy).map((s) => s.id);
      const resolved = new Set(newOrder);
      const tail = curOrder.map(String).filter((id) => !resolved.has(id)); // keep any unresolvable ids (no silent drops)
      return { ...(prev || {}), [truckId]: { order: [...newOrder, ...tail], reordered: true } };
    });
    setLastAction(`Re-sequenced ${truckId} · ${({ min: 'Min distance', closest: 'Closest first', farthest: 'Farthest first', reverse: 'Reverse' })[strategy] || strategy}`);
  }, [stopById, result]);

  // Esc cancels any armed selection mode.
  useEffect(() => {
    if (!selectMode) return;
    const onKey = (e) => { if (e.key === 'Escape') cancelMode(); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [selectMode, cancelMode]);

  // Auto-surface the Result in the desktop right rail when a build completes
  // (Stops stays one click away).
  useEffect(() => { if (job?.status === 'done') setDesktopRail('result'); }, [job?.status]);

  // (Re)init the map into the CURRENT container. Re-runs when the viewport crosses
  // the mobile/desktop breakpoint (the map div is then a different DOM node), so
  // the markers + click listener rebind to the live map via the mapReady signal.
  useEffect(() => {
    if (!google || !mapDiv.current) return;
    // Any in-flight draw belongs to the old map node; reset it on re-init.
    clearTemp();
    boxCornersRef.current = []; lassoVtxRef.current = [];
    selectModeRef.current = null; setSelectMode(null); setBoxStep(0); setLassoCount(0);
    mapRef.current = new google.maps.Map(mapDiv.current, {
      center: ROUTING_DEPOT, zoom: 9, mapTypeControl: false, streetViewControl: false, fullscreenControl: false,
      gestureHandling: 'greedy', // one-finger pan/zoom on touch (no two-finger requirement)
      // Match the dispatch Map's look: the same vector map style (mapId) + satellite
      // imagery with road labels (hybrid), instead of the plain roadmap base.
      ...(MAP_ID ? { mapId: MAP_ID } : {}),
      mapTypeId: routeSatellite ? 'hybrid' : 'roadmap',
    });
    // Single click listener drives Box/Lasso. Empty-map taps place points; the
    // latest handler is read via a ref so the listener is bound only once per map.
    mapRef.current.addListener('click', (e) => { if (e.latLng) handleSelectPointRef.current(e.latLng); });
    // Invisible overlay → exact container-pixel ↔ LatLng projection for drag-box.
    const ov = new google.maps.OverlayView();
    ov.onAdd = ov.draw = ov.onRemove = () => {};
    ov.setMap(mapRef.current);
    overlayRef.current = ov;
    setMapReady((n) => n + 1);
  }, [google, isMobile]); // eslint-disable-line

  // Render stop markers — the SAME rich dispatch-map pins (status / priority flag /
  // AM-PM window / restriction icons / DNS) via the shared stopMarkerIcon helper, so
  // Routing reads exactly like the Map. Layered with routing semantics: a SELECTED
  // (not-yet-routed) stop pops ORANGE (matched), and a ROUTED stop becomes a numbered
  // pin in its truck's route color (sequence 1..N matching the panel). Click toggles
  // selection; hover drives the map<->list linkage. Numbers/colors track routeInfo so
  // a manual reorder updates the labels live.
  //
  // Grid status/driver filter → the map hides non-matching stops (WYSIWYG with the bottom
  // grid). Exemptions: a SELECTED stop and any stop on a shown route stay visible — hiding a
  // selection would let invisible stops ride into a build, and a route's numbered pins must
  // never lose members mid-view.
  //
  // HOISTED out of the marker effect so the status card can report what is actually DRAWN.
  // It used to publish `stops.length` — the whole unfiltered day board — while the map drew a
  // filtered subset, so the chip and the pins under it disagreed, and neither matched the
  // bottom grid. A count nobody can reconcile is worse than no count.
  const drawnStops = useMemo(() => (statusFilterIds
    ? vPositioned.filter((s) => { const id = String(s.stopNbr); return statusFilterIds.has(id) || selectedIds.has(id) || effectiveRouteInfo.has(id); })
    : vPositioned), [statusFilterIds, vPositioned, selectedIds, effectiveRouteInfo]);
  useEffect(() => {
    if (!google || !mapRef.current) return;
    markersRef.current.forEach((m) => m.setMap(null));
    const byId = new Map();
    // Location → its member stopNbrs. Length feeds the count badge; the member list feeds the
    // one-click group select (clicking a multi-order marker toggles every order at the place).
    const locMates = new Map();
    for (const s of drawnStops) { const k = stopLocKey(s); const a = locMates.get(k); a ? a.push(String(s.stopNbr)) : locMates.set(k, [String(s.stopNbr)]); }
    markersRef.current = drawnStops.map((s) => {
      const id = String(s.stopNbr);
      const sel = !viewing && selectedIds.has(id);
      // A bottom-grid SEARCH hit — highlighted BURNT ORANGE (distinct from the amber selection
      // color, since both can be on the map at once) and pushed to the very top layer. Selection
      // still wins the color if a stop is both (stopMarkerIcon precedence).
      const searchMatched = !!searchMatchIds && searchMatchIds.has(id);
      const ri = effectiveRouteInfo.get(id);     // { color, seq } when on a route (Compare cards win)
      const numbered = !!ri;
      const note = notes.get(s.matchKey) || null;
      const hovered = hoverIdRef.current === id;
      // Use the SAME rich pin as the dispatch Map (status colour, priority flag, AM/PM, restriction
      // icons, DNS) so the two surfaces match. Image-URL icons render reliably on the vector map.
      // Routing semantics layer on top: selected (not-yet-routed) → orange, routed → numbered pin in
      // the route colour.
      const baseIcon = stopMarkerIcon(google, s, note, {
        selectedDayKey,
        matched: sel,
        searchMatched,
        inRoute: numbered,
        seq: ri?.seq,
        routeColor: ri?.color,
        sameLocCount: (locMates.get(stopLocKey(s)) || []).length || 1,
        tractorDelivered: tractorLocs.has(s.matchKey),
        // Planned onto a load and no card open for it → mute. `numbered` covers the
        // open-card case, so closing a card is exactly the moment a route's stops go
        // from numbered-in-route-colour to quiet slate — never back to pool-coloured.
        plannedMuted: !numbered && isPlannedStop(s),
      });
      // Search hits ride the TOP layer above everything (Chad), even above numbered route pins,
      // so a hit is never hidden; otherwise numbered > selected > resting.
      const baseZ = searchMatched ? ((google.maps.Marker?.MAX_ZINDEX ?? 1e6) + 1) : (numbered ? 30 : (sel ? 25 : 10));
      const marker = new google.maps.Marker({
        position: { lat: s.lat, lng: s.lng },
        title: s.businessName || s.stopNbr,
        icon: hovered ? emphIcon(baseIcon) : baseIcon,
        zIndex: hovered ? 50 : baseZ,
      });
      marker.addListener('click', () => {
        if (viewing) return;                     // saved load is read-only
        // Paint mode: mark the stop (green/red) AND open its full detail in the right
        // panel — dispatcher request, "first click does both". setPanelStop is a stable
        // useState setter so the marker-build effect's deps (12476) don't change.
        if (eligActionRef.current) { eligActionRef.current(s); setPanelStop(s); }
        else if (selectModeRef.current) handleSelectPointRef.current(marker.getPosition());
        else if (ninjaActionRef.current) ninjaActionRef.current(s.stopNbr);   // ninja → add to active route
        else {
          // A PLANNED stop → open its route in the Compare panel (via ref so this effect's deps
          // below don't change and rebuild every marker). Pool/unplanned stops keep the select-the-place toggle.
          const routeKey = !s.isUnplanned ? (s.routeName || s.loadNbr) : null;
          if (routeKey && openRouteRef.current) openRouteRef.current(routeKey);
          else toggleStopGroup(s.stopNbr, locMates.get(stopLocKey(s)));         // whole place in one click
        }
      });
      marker.addListener('mouseover', () => setHoverId(id));
      marker.addListener('mouseout', () => setHoverId((h) => (h === id ? null : h)));
      marker.setMap(mapRef.current);
      byId.set(id, { marker, baseIcon, baseZ });
      return marker;
    });
    markerByIdRef.current = byId;
    lastEmphRef.current = hoverIdRef.current; // markers were built already-emphasized
  }, [google, drawnStops, vPositioned, viewing, selectedIds, searchMatchIds, statusFilterIds, effectiveRouteInfo, notes, tractorLocs, toggleStopGroup, mapReady, selectedDayKey, emphIcon]);

  // Hover emphasis — touch only the two affected markers, not all of them. Keeps
  // the sequence label intact (only the icon scale/ring change).
  useEffect(() => {
    const byId = markerByIdRef.current;
    const setEmph = (id, on) => {
      const e = byId.get(id); if (!e) return;
      e.marker.setIcon(on ? emphIcon(e.baseIcon) : e.baseIcon);
      e.marker.setZIndex(on ? 50 : e.baseZ);
    };
    if (lastEmphRef.current && lastEmphRef.current !== hoverId) setEmph(lastEmphRef.current, false);
    if (hoverId) setEmph(hoverId, true);
    lastEmphRef.current = hoverId;
  }, [hoverId, emphIcon]);

  // Route polylines (one per route, depot-anchored), drawn in the CURRENT order so any reorder
  // redraws the path live. While the Compare panel has routes open it draws THOSE (the working set
  // the dispatcher is tuning); otherwise it draws the engine Build result (routesView).
  useEffect(() => {
    if (!google || !mapRef.current) return;
    polylinesRef.current.forEach((p) => p.setMap(null));
    polylinesRef.current = [];
    const toDraw = wbRoutesColored.length ? wbRoutesColored : routesView;
    if (!toDraw.length) return;
    toDraw.forEach((rv) => {
      // The leading depot point is the "stem-out" leg (terminal → first stop); omit it when the
      // dispatcher has hidden the stem (#256) so the line connects only the stops.
      const path = routeHideStem ? [] : [{ lat: ROUTING_DEPOT.lat, lng: ROUTING_DEPOT.lng }];
      for (const id of rv.order) { const s = vStopById.get(String(id)); if (s && s.lat != null && s.lng != null) path.push({ lat: s.lat, lng: s.lng }); }
      if (path.length < 2) return;
      const pl = new google.maps.Polyline({ path, strokeColor: rv.color, strokeWeight: 3, strokeOpacity: 0.85, zIndex: 5 });
      pl.setMap(mapRef.current);
      polylinesRef.current.push(pl);
    });
  }, [google, routesView, wbRoutesColored, vStopById, mapReady, routeHideStem]);

  // Satellite-view toggle — swap the map base between hybrid imagery and the plain roadmap without
  // re-initialising the map (which would drop markers/listeners). mapReady re-applies it after a
  // mobile/desktop re-init.
  useEffect(() => {
    if (!google || !mapRef.current) return;
    // Satellite: 'satellite' drops ALL of Google's labels; 'hybrid' keeps them. Roadmap always
    // carries labels — with a cloud mapId JS styles can't strip them, so "Hide place labels"
    // primarily cleans the satellite view (where the POI clutter overlaps the pins). When there's
    // NO mapId, also apply a POI/transit-off style so roadmap honors it too.
    const type = routeSatellite ? (routeHideLabels ? 'satellite' : 'hybrid') : 'roadmap';
    try { mapRef.current.setMapTypeId(type); } catch { /* ignore */ }
    if (!MAP_ID) {
      try {
        mapRef.current.setOptions({ styles: routeHideLabels
          ? [{ featureType: 'poi', elementType: 'labels', stylers: [{ visibility: 'off' }] },
             { featureType: 'transit', elementType: 'labels', stylers: [{ visibility: 'off' }] }]
          : [] });
      } catch { /* ignore */ }
    }
  }, [google, routeSatellite, routeHideLabels, mapReady]);

  // "Show routes" overlay — group the day's positioned stops by load, order each by the same
  // sequencing the panel uses, and draw a colored polyline per load (independent of the Compare /
  // build polylines above). Mirrors the dispatch Map's Show-routes toggle.
  const dayRoutes = useMemo(() => {
    if (!routeShowRoutes) return [];
    const groups = new Map();
    for (const s of positioned) {
      const key = s.routeName || s.loadNbr;
      if (!key) continue;
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(s);
    }
    const out = [];
    let i = 0;
    for (const [key, gs] of groups) {
      const path = orderRouteStops(gs).filter((s) => s.lat != null && s.lng != null).map((s) => ({ lat: s.lat, lng: s.lng }));
      if (path.length >= 2) out.push({ key, color: ROUTE_PALETTE[i % ROUTE_PALETTE.length], path });
      i++;
    }
    return out;
  }, [routeShowRoutes, positioned]);
  useEffect(() => {
    if (!google || !mapRef.current) return;
    dayRoutePolylinesRef.current.forEach((p) => p.setMap(null));
    dayRoutePolylinesRef.current = [];
    dayRoutes.forEach((r) => {
      const pl = new google.maps.Polyline({ path: r.path, strokeColor: r.color, strokeWeight: 2.5, strokeOpacity: 0.6, zIndex: 4, clickable: false });
      pl.setMap(mapRef.current);
      dayRoutePolylinesRef.current.push(pl);
      // Clicking a day-route line opens that route in Compare — same gesture as the Map
      // screen's route lines, so the two maps behave alike. Transparent 16px hit line for
      // the same reason: 2.5px is not a click target. Markers still win the click (higher
      // pane), so a stop sitting on the line opens the stop, not the route.
      const hit = new google.maps.Polyline({ path: r.path, strokeColor: r.color, strokeOpacity: 0, strokeWeight: 16, zIndex: 4, clickable: true });
      hit.setMap(mapRef.current);
      hit.addListener('click', () => openRouteRef.current?.(r.key));
      hit.addListener('mouseover', () => {
        mapRef.current?.setOptions({ draggableCursor: 'pointer' });
        pl.setOptions({ strokeWeight: 4.5, strokeOpacity: 0.9 });
      });
      hit.addListener('mouseout', () => {
        mapRef.current?.setOptions({ draggableCursor: null });
        pl.setOptions({ strokeWeight: 2.5, strokeOpacity: 0.6 });
      });
      dayRoutePolylinesRef.current.push(hit);
    });
    return () => { mapRef.current?.setOptions({ draggableCursor: null }); };
  }, [google, dayRoutes, mapReady]);

  const selectedTrucks = useMemo(() => profiles.filter((p) => selectedTruckIds.has(p.id)), [profiles, selectedTruckIds]);

  // ── "Plan onto my loads" pick list ────────────────────────────────────────
  // The day's roster as pickable build targets. Empty loads (nothing on the board yet — the
  // ones you create in NuVizz to fill) sort first; loads that already hold stops are still
  // pickable (the build ADDS to them via the card merge). Loads whose NAME is duplicated on
  // the roster are shown but not pickable — identity is ambiguous, the same rule the Compare
  // card open enforces — and the solver needs unique route keys anyway.
  const boardCountByName = useMemo(() => {
    const m = new Map();
    for (const g of routeGroups) { const nm = String(g.name || g.key || '').trim().toLowerCase(); if (nm) m.set(nm, g.count); }
    return m;
  }, [routeGroups]);
  const planPickRows = useMemo(() => {
    const nameCounts = new Map();
    for (const l of loadRosterList) { const nm = String(l.name || '').trim().toLowerCase(); if (nm) nameCounts.set(nm, (nameCounts.get(nm) || 0) + 1); }
    const rows = loadRosterList.map((l) => {
      const name = String(l.name || '').trim();
      const rowKey = String(l.loadId || l.loadNbr || name);
      const boardCount = boardCountByName.get(name.toLowerCase()) || 0;
      return {
        rowKey, name, loadNbr: l.loadNbr ? String(l.loadNbr) : null, loadId: l.loadId ? String(l.loadId) : null,
        status: l.status || '', boardCount,
        ambiguous: name ? (nameCounts.get(name.toLowerCase()) || 0) > 1 : false,
        display: name || (l.loadNbr ? String(l.loadNbr) : String(l.loadId || 'Unnamed load')),
      };
    });
    rows.sort((a, b) => (Number(a.boardCount > 0) - Number(b.boardCount > 0)) || a.display.localeCompare(b.display));
    return rows;
  }, [loadRosterList, boardCountByName]);
  // Default vehicle per load: the name says trailer → the tractor profile, else the box
  // profile. The per-load chip in the panel overrides it.
  const guessProfileFor = useCallback((name) => {
    const tractor = profiles.find((p) => p.capabilities?.tractor) || profiles.find((p) => /53|trailer|tractor/i.test(p.label || p.id));
    const box = profiles.find((p) => !p.capabilities?.tractor) || profiles[0];
    return (/(^|\W)(trailer|trl|53)(\W|$)/i.test(String(name || '')) && tractor) ? tractor : (box || tractor || profiles[0]);
  }, [profiles]);
  const planTargets = useMemo(() => {
    const out = [];
    for (const r of planPickRows) {
      if (!planTargetKeys.has(r.rowKey) || r.ambiguous) continue;
      const p = profiles.find((x) => x.id === planTargetProfileById.get(r.rowKey)) || guessProfileFor(r.display);
      if (p) out.push({ ...r, profile: p });
    }
    return out;
  }, [planPickRows, planTargetKeys, planTargetProfileById, profiles, guessProfileFor]);

  const canBuild = selectedIds.size >= 1
    && (planMode === 'loads' ? planTargets.length >= 1 : selectedTrucks.length >= 1)
    && selectedIds.size <= ROUTING_MAX_SELECTION && !building;
  const wouldBeElements = (selectedIds.size + 1) ** 2;
  const wouldBeCost = Math.round((wouldBeElements / 1000) * BASIC_RATE_PER_1K_USD * 100) / 100;

  const runBuild = useCallback(async () => {
    if (!db) { setJob({ status: 'error', error: 'Firestore not configured' }); return; }
    setBuilding(true); setJob({ status: 'queued' }); setSaveState(null);
    const jobId = `job_${(crypto.randomUUID ? crypto.randomUUID() : String(Date.now()))}`;
    // "Plan onto my loads": ONE solver truck per picked roster load, keyed by the load's
    // display name — the solver builds exactly one route per key, so route cards, reorder
    // state, and the map all speak the load's name ("SUW 2"), and the result routes bind
    // back to real loadNbr/loadId for staging. Capacity/eligibility come from the load's
    // chosen truck profile. The server honors request.trucks as-is (routing-build's
    // pre-resolved-trucks path) — zero server changes, zero NuVizz calls.
    const loadsBound = planMode === 'loads';
    const plannedLoads = loadsBound
      ? planTargets.map((t) => ({ key: t.display, name: t.name || null, loadNbr: t.loadNbr, loadId: t.loadId, profileId: t.profile.id }))
      : null;
    const solverTrucks = loadsBound
      ? planTargets.map((t) => ({ id: t.display, label: t.display, maxSkids: t.profile.maxSkids, maxWeightLbs: t.profile.maxWeightLbs, deckLengthIn: t.profile.deckLengthIn, capabilities: { ...t.profile.capabilities } }))
      : null;
    const request = {
      tenant: 'davis', date: selectedDate,
      selectedStopIds: [...selectedIds],
      truckProfileIds: loadsBound ? [] : selectedTrucks.map((t) => t.id),
      truckSnapshots: loadsBound ? solverTrucks : selectedTrucks,
      ...(loadsBound ? { trucks: solverTrucks, plannedLoads } : {}),
      intent: intent.trim(), strategy,
      matrixMode: useGoogle ? 'google' : 'haversine',
      tractorOnlyGreen: trailerGreenOnly,
    };
    setLastRequest(request);
    try {
      await setDoc(doc(db, 'routing_jobs', jobId), { id: jobId, status: 'queued', created_at: serverTimestamp(), created_by: 'dispatcher', app_version: APP_VERSION, request });
      // Fire the background build; it returns 202 and we watch the doc.
      fetch('/.netlify/functions/routing-build-background', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ jobId }) }).catch(() => {});
      const unsub = onSnapshot(doc(db, 'routing_jobs', jobId), (snap) => {
        const d = snap.data();
        if (!d) return;
        setJob(d);
        if (d.status === 'done' || d.status === 'error') { setBuilding(false); unsub(); }
      }, (e) => { setJob({ status: 'error', error: e.message }); setBuilding(false); });
    } catch (e) {
      setJob({ status: 'error', error: e.message }); setBuilding(false);
    }
  }, [selectedDate, selectedIds, selectedTrucks, intent, strategy, useGoogle, trailerGreenOnly, planMode, planTargets]);

  // Save panel — a name (prefilled with a sensible auto-name per build) + optional
  // free-text initials. No native prompt(); no auth.
  const [saveName, setSaveName] = useState('');
  const [savedBy, setSavedBy] = useState('');
  useEffect(() => { if (result) setSaveName(buildLoadAutoName(editedResultForSave || result, Date.now())); }, [result]); // eslint-disable-line

  const savePlan = useCallback(async () => {
    if (!db || !result) return;
    setSaveState('saving');
    const id = `routeset_${(crypto.randomUUID ? crypto.randomUUID() : String(Date.now()))}`;
    const plan = editedResultForSave || result;
    const name = (saveName && saveName.trim()) || buildLoadAutoName(plan, Date.now());
    // Self-contained stop snapshot (name + coords + counts) so the load renders on
    // the map on any day, independent of today's live cache.
    const stops_snapshot = {};
    const ids = new Set();
    for (const r of plan.routes || []) for (const sid of r.orderedStopIds || []) ids.add(String(sid));
    for (const u of plan.unassigned || []) ids.add(String(u.stopId));
    for (const sid of ids) {
      const s = stopById.get(sid);
      if (s) stops_snapshot[sid] = { name: s.businessName || sid, lat: s.lat ?? null, lng: s.lng ?? null, pallets: Number(s.pallets) || 0, cartons: Number(s.cartons) || 0, weight: Number(s.weight) || 0 };
    }
    try {
      await setDoc(doc(db, 'routing_routes', id), {
        id, name, status: 'saved', dispatched: false,
        created_at: serverTimestamp(), updated_at: serverTimestamp(),
        created_by: 'dispatcher', saved_by: (savedBy && savedBy.trim()) || null,
        app_version: APP_VERSION, request: lastRequest, result: plan,
        manual_reorder: !!(editedResultForSave && editedResultForSave.manualReorder),
        stops_snapshot,
      });
      // Verify by readback (convention: never trust the write alone).
      const back = await getDoc(doc(db, 'routing_routes', id));
      if (!back.exists() || back.data().name !== name) throw new Error('save not confirmed by readback');
      setSaveState('saved');
    } catch (e) { setSaveState(e.message || 'save failed'); }
  }, [result, lastRequest, editedResultForSave, saveName, savedBy, stopById]);

  // Manage a saved load (rename / dispatched / delete) — every write verified by
  // readback; the live onSnapshot reflects the change everywhere.
  const renameLoad = useCallback(async (id, name) => {
    setManageError(null);
    if (!db || !name || !name.trim()) return;
    try {
      await updateDoc(doc(db, 'routing_routes', id), { name: name.trim(), updated_at: serverTimestamp() });
      const back = await getDoc(doc(db, 'routing_routes', id));
      if (!back.exists() || back.data().name !== name.trim()) throw new Error('rename not confirmed');
    } catch (e) { setManageError(e.message || 'rename failed'); }
  }, []);
  const toggleDispatched = useCallback(async (id, next) => {
    setManageError(null);
    if (!db) return;
    try {
      await updateDoc(doc(db, 'routing_routes', id), { dispatched: !!next, status: next ? 'dispatched' : 'saved', updated_at: serverTimestamp() });
      const back = await getDoc(doc(db, 'routing_routes', id));
      if (!back.exists() || back.data().dispatched !== !!next) throw new Error('dispatch toggle not confirmed');
    } catch (e) { setManageError(e.message || 'update failed'); }
  }, []);
  const deleteLoad = useCallback(async (id) => {
    setManageError(null);
    if (!db) return;
    try {
      await deleteDoc(doc(db, 'routing_routes', id));
      const back = await getDoc(doc(db, 'routing_routes', id));
      if (back.exists()) throw new Error('delete not confirmed');
      setViewedLoad((v) => (v && v.id === id ? null : v));
    } catch (e) { setManageError(e.message || 'delete failed'); }
  }, []);

  // Keep the viewed load live: track edits from any device, close if deleted.
  // Only swap when the doc actually changed (updated_at) so unrelated snapshot
  // churn doesn't re-render the whole view.
  useEffect(() => {
    if (!viewedLoad) return;
    const fresh = loads.find((l) => l.id === viewedLoad.id);
    if (!fresh) { setViewedLoad(null); return; }
    if (tsToMillis(fresh.updated_at) !== tsToMillis(viewedLoad.updated_at)) setViewedLoad(fresh);
  }, [loads]); // eslint-disable-line

  // Frame the map to a saved load's stops when it's opened (not on every refresh).
  useEffect(() => {
    if (!google || !mapRef.current || !viewing) return;
    const pts = vPositioned.filter((s) => s.lat != null && s.lng != null);
    if (!pts.length) return;
    const b = new google.maps.LatLngBounds();
    pts.forEach((s) => b.extend({ lat: s.lat, lng: s.lng }));
    b.extend(ROUTING_DEPOT);
    mapRef.current.fitBounds(b, fitPad());
  }, [viewing, viewedLoad?.id, mapReady, google]); // eslint-disable-line

  // Stops kept on a route but outside their appointment window (advisory flag from
  // the engine result). Used to flag rows + the detail popup.
  const windowViolatedSet = useMemo(() => {
    const s = new Set();
    for (const r of (baseResult?.routes || [])) for (const id of (r.windowViolatedIds || [])) s.add(String(id));
    return s;
  }, [baseResult]);

  const meta = baseResult?.meta || {};
  const usedGoogle = meta.matrixSource === 'google';

  // Responsive: desktop = three side rails; mobile = full map + a collapsible
  // bottom sheet that toggles between the Setup controls and the Result.
  const [mobilePanel, setMobilePanel] = useState('setup');
  const [sheetOpen, setSheetOpen] = useState(true);
  useEffect(() => { if (job?.status === 'done') { setMobilePanel('result'); setSheetOpen(true); } }, [job?.status]);
  // Opening a stop's detail (map click, incl. paint mode) reveals the bottom sheet if collapsed.
  useEffect(() => { if (panelStop) setSheetOpen(true); }, [panelStop]);
  // Tap a load in the bottom Loads grid → OPEN IT IN COMPARE (so you can ninja stops onto it),
  // including EMPTY loads with no orders yet (issue #237 — "add stops to one of the available
  // loads... can't figure out how"). The grid clicks with the raw loadNbr; resolve it to the
  // canonical workbench key (routeName||loadNbr) off a matching stop so a route WITH stops opens
  // populated, while an empty load (no match) opens as a blank card ready to fill.
  const pickLoadToCompare = useCallback((loadNbr) => {
    if (viewing || !loadNbr) return;
    const s = positionedAll.find((p) => p.loadNbr === loadNbr || (p.routeName || p.loadNbr) === loadNbr);
    const key = s ? (s.routeName || s.loadNbr) : loadNbr;
    openRouteInWorkbench(key);
    if (isMobile) { setMobilePanel('setup'); setSheetOpen(true); }
    const pts = positionedAll.filter((p) => (p.routeName || p.loadNbr) === key && p.lat != null && p.lng != null);
    if (google && mapRef.current && pts.length) {
      const b = new google.maps.LatLngBounds();
      pts.forEach((p) => b.extend({ lat: p.lat, lng: p.lng }));
      mapRef.current.fitBounds(b, fitPad());
    }
  }, [viewing, positionedAll, openRouteInWorkbench, google, isMobile, fitPad]);
  // Arm/disarm Ninja from the Compare panel button (the on-map tool is easy to miss). When arming
  // on mobile, drop the bottom sheet so the map — and the stops you're about to tap — are visible.
  const armNinjaFromPanel = useCallback(() => {
    if (wbRoutes.length === 0) return;
    setNinjaMode((v) => {
      const next = !v;
      if (next && isMobile) setSheetOpen(false);
      return next;
    });
  }, [wbRoutes.length, isMobile]);
  // Mobile: when the FIRST route is opened into the Compare panel, jump to the Setup tab (which
  // hosts the Compare workbench + the Ninja toggle) and open the sheet — otherwise opening a route
  // from the Routes tab looks like nothing happened and Ninja mode is never seen.
  const prevWbLenRef = useRef(0);
  useEffect(() => {
    if (isMobile && wbRoutes.length > 0 && prevWbLenRef.current === 0) { setMobilePanel('setup'); setSheetOpen(true); }
    prevWbLenRef.current = wbRoutes.length;
  }, [wbRoutes.length, isMobile]);

  // Discard the BUILT plan (output), keeping the selection + trucks (inputs) so the
  // dispatcher can adjust and rebuild without re-selecting. Purely local — no
  // Firestore write, saved Loads untouched. `planEdited` (a manual reorder or P3
  // re-sequence) gates a one-tap confirm so hand-tuning isn't lost by accident.
  const planEdited = !!(routeState && Object.values(routeState).some((s) => s.reordered));
  const discardPlan = useCallback(() => {
    setJob(null); setRouteState(null); setSaveState(null); setBuilding(false); setLastRequest(null);
    setLastAction('Discarded plan — selection kept');
    setMobilePanel('setup');
  }, []);

  // ── Stage a loads-bound build onto Compare cards ───────────────────────────
  // Each built route (keyed by the picked load's name) becomes/merges into a Compare card
  // carrying the load's REAL identity (loadNbr/loadId from the roster) with the built stop
  // order staged — in the CURRENT panel order, so a hand-reorder before staging is honored.
  // The card's `baseline` stays the load's board stops only, so every added stop reads dirty
  // and the normal Save (the verified multi-route commitBoard) writes it to NuVizz. Nothing
  // is sent here — staging is local; Save remains the single write path.
  const plannedLoadsBound = (!viewing && job?.status === 'done' && Array.isArray(lastRequest?.plannedLoads) && lastRequest.plannedLoads.length) ? lastRequest.plannedLoads : null;
  const stagePlanOntoLoads = useCallback(() => {
    const bound = lastRequest?.plannedLoads || [];
    if (!bound.length || !routesView.length) return;
    const byKey = new Map(bound.map((b) => [String(b.key), b]));
    let added = 0, skippedHeld = 0, fullSkipped = [];
    let next = [...wbRoutes];
    const heldBy = () => { const m = new Map(); for (const r of next) for (const id of r.order) m.set(String(id), r.key); return m; };
    for (const rv of routesView) {
      const b = byKey.get(String(rv.truckId));
      if (!b) continue;
      const ids = rv.order.map(String).filter((id) => stopById.has(id));
      if (!ids.length) continue;
      const held = heldBy();
      const idx = next.findIndex((r) => r.key === b.key || (b.loadId && String(r.loadId || '') === String(b.loadId)));
      if (idx >= 0) {
        const cur = next[idx];
        const have = new Set(cur.order.map(String));
        const add = ids.filter((id) => !have.has(id) && (!held.has(id) || held.get(id) === cur.key));
        skippedHeld += ids.filter((id) => !have.has(id) && held.has(id) && held.get(id) !== cur.key).length;
        if (add.length) { next[idx] = { ...cur, order: [...cur.order, ...add] }; added += add.length; }
      } else {
        if (next.length >= WB_MAX) { fullSkipped.push(b.key); continue; }
        // Seed with the load's existing same-day board stops (identical rule to opening the
        // card), then append the built stops; anything staged on another open card stays there.
        const boardStops = positionedAllRef.current.filter((s) => !s.windowExtra && (s.routeName || s.loadNbr) === b.key);
        const baseline = orderRouteStops(boardStops).map((s) => String(s.stopNbr)).filter((id) => !held.has(id));
        const seen = new Set(baseline);
        const adds = [];
        for (const id of ids) {
          if (seen.has(id)) continue;
          if (held.has(id)) { skippedHeld++; continue; }
          seen.add(id); adds.push(id);
        }
        next.push({ key: b.key, name: b.name || b.key, loadNbr: b.loadNbr || null, loadId: b.loadId || null, order: [...baseline, ...adds], baseline, collapsed: false });
        added += adds.length;
      }
    }
    setWbRoutes(next);
    const bits = [`Staged ${added} stop${added === 1 ? '' : 's'} onto ${Math.min(bound.length, next.length)} card${bound.length === 1 ? '' : 's'} — review, then Save to send to NuVizz`];
    if (skippedHeld) bits.push(`${skippedHeld} already staged on another open card (left there)`);
    if (fullSkipped.length) bits.push(`workbench full — couldn't open: ${fullSkipped.join(', ')}`);
    setLastAction(bits.join(' · '));
    if (isMobile) { setMobilePanel('setup'); setSheetOpen(true); }
  }, [lastRequest, routesView, wbRoutes, stopById, isMobile]);

  // Shared gear-settings config — rendered in two places: the left Setup-panel header and the
  // bottom data-grid header. The bottom gear is what stays reachable when the Setup panel is hidden,
  // so it carries every toggle EXCEPT "Bottom data grid" (turning that off from the bottom gear would
  // close the very header the gear lives in, leaving no way back).
  // Vehicle-eligibility brush lives in the gear: Off / Tractor OK (green) / Box only (red).
  // Picking a brush arms the paint mode; click stops on the map to mark them.
  const eligView = {
    key: 'elig',
    label: 'Mark vehicle eligibility',
    value: eligPaint || 'off',
    setValue: (v) => setEligBrush(v === 'off' ? null : v),
    options: [
      { value: 'off', label: 'Off' },
      { value: 'tractor', label: <span className="font-semibold" style={{ color: ELIG_TRACTOR_COLOR }}>● Tractor OK (53′ fits)</span> },
      { value: 'box', label: <span className="font-semibold" style={{ color: ELIG_BOX_COLOR }}>● Box truck only</span> },
    ],
  };
  const routingSettingsViews = [
    { key: 'rightPanel', label: 'Right panel', value: rightPanelMode, setValue: setRightPanelMode, options: [{ value: 'tabs', label: 'Tabs (Stops / Loads / Result)' }, { value: 'routes', label: 'Routes / Drivers' }] },
    eligView,
  ];
  const routingSettingsActions = [
    { key: 'versionLog', label: `ⓘ Version history (v${APP_VERSION})`, onClick: () => setVersionLogOpen(true) },
    { key: 'reset', label: '↺ Reset layout to defaults', onClick: resetRoutingLayout },
  ];
  const leftPanelToggle = { key: 'leftPanel', label: 'Setup panel (left controls)', on: leftPanelOn, setOn: setLeftPanelVisible };
  const selPanelToggle = { key: 'selPanel', label: 'Floating selected-stops panel', on: selPanelOpen, setOn: setSelPanelOpen };
  const bottomGridToggle = { key: 'bottomGrid', label: 'Bottom data grid', on: bottomGridOn, setOn: setBottomGridOn };
  const hideStemToggle = { key: 'hideStem', label: 'Hide stem-out line (depot → first stop)', on: routeHideStem, setOn: setRouteHideStem };
  const liveWriteToggle = { key: 'liveWrite', label: 'Live dispatch (assign driver + dispatch)', on: liveWrite, setOn: setLiveWrite };
  const leftGearPanels = [leftPanelToggle, selPanelToggle, bottomGridToggle, hideStemToggle, liveWriteToggle];
  const bottomGearPanels = [leftPanelToggle, selPanelToggle, hideStemToggle, liveWriteToggle];
  // The settings gear (+ a compact date picker when the Setup panel is hidden) for the bottom
  // data-grid header — keeps date selection and every panel toggle reachable with the left panel off.
  const bottomGridHeaderRight = (
    <div className="flex items-center gap-1.5 shrink-0">
      {!leftPanelOn && <DatePicker selectedDate={selectedDate} onChange={setSelectedDate} onToday={() => setSelectedDate(todayInET())} compact />}
      <RoutingSettingsMenu views={routingSettingsViews} panels={bottomGearPanels} actions={routingSettingsActions} dropUp />
    </div>
  );

  const controlsContent = (
    <>
      <div className="flex items-center justify-between gap-2">
        <div className="font-bold text-slate-800">Routing <span className="text-[10px] uppercase tracking-wide bg-amber-100 text-amber-700 px-1.5 py-0.5 rounded">beta</span></div>
        <div className="flex items-center gap-1.5">
          <DatePicker selectedDate={selectedDate} onChange={setSelectedDate} onToday={() => setSelectedDate(todayInET())} compact />
          <RoutingSettingsMenu
            views={routingSettingsViews}
            panels={leftGearPanels}
            actions={routingSettingsActions}
          />
        </div>
      </div>
      <div className="text-[11px] text-slate-500">{loading ? 'Loading stops…' : `${positioned.length} stops on ${formatDateLong(selectedDate)}`}{stopsError ? ` · ${stopsError}` : ''}</div>

      {/* Selection tools — all touch-native (no drag-to-draw). */}
      <div className="border rounded p-2 space-y-2">
        <div className="font-semibold text-slate-700">1 · Select stops</div>
        {selectMode ? (
          <div className="rounded border border-amber-300 bg-amber-50 p-2 text-[12px] space-y-2">
            {selectMode === 'box' ? (
              isMobile
                ? <div>📦 <b>Tap two corners</b> on the map to box a group ({boxStep === 0 ? '1 of 2' : '2 of 2'}).</div>
                : <div>📦 <b>Drag a box</b> around the stops on the map. Esc or Cancel to stop.</div>
            ) : (
              isMobile
                ? <div>⬠ <b>Tap points</b> around the stops, then <b>Done</b> ({lassoCount} {lassoCount === 1 ? 'point' : 'points'}; need ≥3).</div>
                : <div>⬠ <b>Hold and draw</b> a shape around the stops (release to select). Esc or Cancel to stop.</div>
            )}
            <div className="flex gap-1">
              {selectMode === 'lasso' && isMobile && (
                <button onClick={finishLasso} disabled={lassoCount < 3} className="flex-1 px-2 py-2 text-xs rounded text-white font-semibold disabled:opacity-40" style={{ background: BRAND }}>Done</button>
              )}
              <button onClick={cancelMode} className="flex-1 px-2 py-2 text-xs rounded border border-slate-300 bg-white hover:bg-slate-50 active:bg-slate-100">Cancel</button>
            </div>
          </div>
        ) : (
          <>
            <div className="flex gap-1">
              <button onClick={addInView} className="flex-1 px-2 py-2 text-xs rounded border-2 font-semibold hover:bg-blue-50 active:bg-blue-100" style={{ borderColor: BRAND, color: BRAND }}>＋ Add stops in view</button>
              <button onClick={clearSelection} className="px-3 py-2 text-xs rounded border border-slate-300 hover:bg-slate-50 active:bg-slate-100">Clear</button>
            </div>
            <div className="text-[11px] text-slate-600">{isMobile ? 'Tap' : 'Click'} a stop to toggle it. Use the <b>Box</b> / <b>Lasso</b> / <b>Ninja</b> tools on the map (left edge), or pan/zoom then <b>Add stops in view</b>.</div>
          </>
        )}
        {lastAction && <div className="text-[11px] text-slate-500">{lastAction}</div>}
        <div className="bg-slate-50 rounded p-2 text-[12px] space-y-0.5">
          <div className="flex justify-between"><span>Selected</span><b>{tally.count}</b></div>
          <div className="flex justify-between"><span>Skids</span><b>{tally.skids}</b></div>
          <div className="flex justify-between"><span>Loose pieces</span><b>{tally.pieces}</b></div>
          <div className="flex justify-between"><span>Weight</span><b>{tally.weight.toLocaleString()} lb</b></div>
          {tally.summary.length > 0 && (
            <div className="text-[11px] text-amber-700 pt-1">⚠ {tally.summary.join(' · ')}</div>
          )}
          {tally.count > ROUTING_MAX_SELECTION && <div className="text-[11px] text-red-600 pt-1">Over {ROUTING_MAX_SELECTION}-stop limit — narrow the selection (matrix cost is quadratic).</div>}
        </div>

        {/* On mobile the selected-stops list lives here in the Setup sheet (the #41
            pattern). On desktop it is the right rail's Stops tab instead. */}
        {isMobile && <RoutingSelectedList selectedStops={selectedStops} notes={notes} onRemove={removeStop} open={listOpen} setOpen={setListOpen} onOpenStop={openStop} />}
      </div>

      {/* Vehicle-eligibility marking lives in the ⚙ gear (Mark vehicle eligibility). When a
          brush is armed, show a slim reminder + quick Stop so the mode is never silently on. */}
      {eligPaint && (
        <div
          className="rounded border p-2 text-[12px] flex items-center justify-between gap-2"
          style={{
            borderColor: eligPaint === 'tractor' ? ELIG_TRACTOR_COLOR : ELIG_BOX_COLOR,
            background: (eligPaint === 'tractor' ? ELIG_TRACTOR_COLOR : ELIG_BOX_COLOR) + '14',
          }}
        >
          <span className="font-semibold" style={{ color: eligPaint === 'tractor' ? ELIG_TRACTOR_COLOR : ELIG_BOX_COLOR }}>
            ● {eligPaint === 'tractor' ? 'Tractor' : 'Box'} brush on — {isMobile ? 'tap' : 'click'} stops to mark; again to clear.
          </span>
          <button onClick={() => setEligBrush(null)} className="px-2 py-1 text-[11px] rounded border bg-white hover:bg-slate-50 shrink-0">Stop</button>
        </div>
      )}

      {/* Plan targets — REAL NuVizz loads from the day's roster (default), or the abstract
          truck profiles (the original build). Loads mode: one built route per picked load,
          staged onto Compare cards → the normal verified Save writes NuVizz. */}
      <div className="border rounded p-2 space-y-2">
        <div className="flex items-center justify-between gap-2">
          <div className="font-semibold text-slate-700">2 · Plan onto</div>
          <div className="flex rounded border border-slate-300 overflow-hidden text-[11px] shrink-0">
            <button onClick={() => setPlanMode('loads')} className={`px-2 py-1 font-semibold ${planMode === 'loads' ? 'text-white' : 'bg-white text-slate-600 hover:bg-slate-50'}`} style={planMode === 'loads' ? { background: BRAND } : undefined}>My loads</button>
            <button onClick={() => setPlanMode('trucks')} className={`px-2 py-1 font-semibold border-l border-slate-300 ${planMode === 'trucks' ? 'text-white' : 'bg-white text-slate-600 hover:bg-slate-50'}`} style={planMode === 'trucks' ? { background: BRAND } : undefined}>Trucks</button>
          </div>
        </div>
        {planMode === 'loads' ? (
          <>
            <div className="text-[11px] text-slate-600">Pick the loads to fill (e.g. ALPHA, ALPHA 2, ATL, SUW, SUW 2). Build spreads the selected stops across them — <b>one route per load</b> — then stage the plan onto Compare cards and Save.</div>
            {planPickRows.length === 0 ? (
              <div className="text-[11px] text-amber-700 bg-amber-50 border border-amber-200 rounded p-1.5">No loads on this day's roster yet — create them in NuVizz first, or switch to <b>Trucks</b>.</div>
            ) : (
              <>
                {planPickRows.length > 6 && (
                  <input value={planLoadFilter} onChange={(e) => setPlanLoadFilter(e.target.value)} placeholder="Filter loads…" className="w-full border rounded px-2 py-1 text-[12px]" />
                )}
                <div className="max-h-56 overflow-y-auto border rounded divide-y divide-slate-100">
                  {planPickRows
                    .filter((r) => { const n = planLoadFilter.trim().toLowerCase(); return !n || r.display.toLowerCase().includes(n); })
                    .map((r) => {
                      const on = planTargetKeys.has(r.rowKey) && !r.ambiguous;
                      const prof = profiles.find((x) => x.id === planTargetProfileById.get(r.rowKey)) || guessProfileFor(r.display);
                      return (
                        <div key={r.rowKey} className={`px-1.5 py-1 text-[12px] flex items-center gap-1.5 ${r.ambiguous ? 'opacity-50' : ''}`}>
                          <label className={`flex items-center gap-1.5 flex-1 min-w-0 ${r.ambiguous ? '' : 'cursor-pointer'}`} title={r.ambiguous ? 'Two loads share this name today — rename one in the portal to plan onto it.' : undefined}>
                            <input type="checkbox" disabled={r.ambiguous} checked={on}
                              onChange={() => setPlanTargetKeys((prev) => { const n = new Set(prev); n.has(r.rowKey) ? n.delete(r.rowKey) : n.add(r.rowKey); return n; })} />
                            <span className="font-medium truncate">{r.display}</span>
                            {r.ambiguous
                              ? <span className="px-1 rounded text-[10px] bg-red-50 text-red-600 border border-red-200 shrink-0">duplicate name</span>
                              : r.boardCount > 0
                                ? <span className="px-1 rounded text-[10px] bg-slate-100 text-slate-600 border border-slate-200 shrink-0" title="This load already holds stops — the build ADDS to it.">{r.boardCount} on board</span>
                                : <span className="px-1 rounded text-[10px] bg-amber-50 text-amber-700 border border-amber-200 shrink-0">empty</span>}
                          </label>
                          {on && (
                            <select value={prof?.id || ''} title="Vehicle for this load — sets its capacity + what's allowed on it"
                              onChange={(e) => setPlanTargetProfileById((prev) => { const m = new Map(prev); m.set(r.rowKey, e.target.value); return m; })}
                              className="border rounded px-1 py-0.5 text-[10px] text-slate-700 shrink-0">
                              {profiles.map((p) => <option key={p.id} value={p.id}>{p.label}</option>)}
                            </select>
                          )}
                        </div>
                      );
                    })}
                </div>
                {planTargets.length > 0 && (
                  <div className="text-[11px] text-slate-600 bg-slate-50 rounded p-1.5"><b>{planTargets.length}</b> route{planTargets.length === 1 ? '' : 's'} to build: {planTargets.map((t) => t.display).join(', ')}</div>
                )}
              </>
            )}
          </>
        ) : (
          <>
            <div className="text-[11px] text-slate-400">({selectedTrucks.length} in play)</div>
            {profiles.map((p) => (
              <div key={p.id} className="border rounded p-1.5">
                <label className="flex items-center gap-2">
                  <input type="checkbox" checked={selectedTruckIds.has(p.id)} onChange={() => setSelectedTruckIds((prev) => { const n = new Set(prev); n.has(p.id) ? n.delete(p.id) : n.add(p.id); return n; })} />
                  <span className="font-medium">{p.label}</span>
                </label>
                <div className="grid grid-cols-3 gap-1 mt-1 text-[10px] text-slate-500">
                  <label className="flex flex-col">Skids
                    <input type="number" defaultValue={p.maxSkids} onBlur={(e) => saveProfile({ ...p, maxSkids: Number(e.target.value) })} className="border rounded px-1 py-0.5 text-slate-800" />
                  </label>
                  <label className="flex flex-col">Weight
                    <input type="number" defaultValue={p.maxWeightLbs} onBlur={(e) => saveProfile({ ...p, maxWeightLbs: Number(e.target.value) })} className="border rounded px-1 py-0.5 text-slate-800" />
                  </label>
                  <label className="flex flex-col">Deck in
                    <input type="number" defaultValue={p.deckLengthIn} onBlur={(e) => saveProfile({ ...p, deckLengthIn: Number(e.target.value) })} className="border rounded px-1 py-0.5 text-slate-800" />
                  </label>
                </div>
                <label className="flex items-center gap-1 text-[11px] mt-1">
                  <input type="checkbox" defaultChecked={!!p.capabilities?.liftgate} onChange={(e) => saveProfile({ ...p, capabilities: { ...p.capabilities, liftgate: e.target.checked } })} /> liftgate
                </label>
              </div>
            ))}
          </>
        )}
      </div>

      {/* Controls */}
      <div className="border rounded p-2 space-y-2">
        <div className="font-semibold text-slate-700">3 · Plan</div>
        <textarea value={intent} onChange={(e) => setIntent(e.target.value)} placeholder="Optional: tell the engine what you want (e.g. 'tight appointments first, keep the trailer off downtown')" rows={2} className="w-full border rounded p-1.5 text-[12px]" />
        <label className="flex items-center justify-between text-[12px]">Strategy
          <select value={strategy} onChange={(e) => setStrategy(e.target.value)} className="border rounded px-1 py-1">
            {ROUTING_STRATEGIES.map(([v, l]) => <option key={v} value={v}>{l}</option>)}
          </select>
        </label>
        <label className={`flex items-start gap-2 text-[12px] rounded p-1.5 ${useGoogle ? 'bg-amber-50 border border-amber-300' : 'bg-slate-50'}`}>
          <input type="checkbox" checked={useGoogle} onChange={(e) => setUseGoogle(e.target.checked)} className="mt-0.5" />
          <span>Use live Google drive-times <b>(costs money)</b><br /><span className="text-[11px] text-slate-500">Default is a free straight-line estimate. {selectedIds.size > 0 && <>This build ≈ {wouldBeElements} elements ≈ <b>${wouldBeCost.toFixed(2)}</b>.</>}</span></span>
        </label>
        <label className="flex items-start gap-2 text-[12px] rounded p-1.5 bg-slate-50">
          <input type="checkbox" checked={trailerGreenOnly} onChange={(e) => setTrailerGreenOnly(e.target.checked)} className="mt-0.5" />
          <span>Only put <b style={{ color: ELIG_TRACTOR_COLOR }}>green</b> (tractor-OK) stops on a 53′ trailer<br /><span className="text-[11px] text-slate-500">Any stop not marked tractor-friendly is kept on a box truck. Red (box-only) stops are always kept off trailers.</span></span>
        </label>
        <button onClick={runBuild} disabled={!canBuild} className="w-full py-2 rounded text-white font-semibold disabled:opacity-40" style={{ background: BRAND }}>
          {building ? 'Building…'
            : planMode === 'loads' && planTargets.length > 0 ? `Build onto ${planTargets.length} load${planTargets.length === 1 ? '' : 's'}${useGoogle ? ' · Google drive-times' : ''}`
            : useGoogle ? 'Build with Google drive-times' : 'Build (free estimate)'}
        </button>
        {!canBuild && !building && <div className="text-[11px] text-slate-400">{planMode === 'loads' ? 'Select ≥1 stop and pick ≥1 load to build.' : 'Select ≥1 stop and ≥1 truck to build.'}</div>}
      </div>
    </>
  );

  const resultContent = (
    <RoutingResultPanel job={job} result={baseResult} meta={meta} usedGoogle={usedGoogle} stopById={vStopById}
      plannedLoads={plannedLoadsBound} onStagePlan={stagePlanOntoLoads}
      onSave={savePlan} saveState={saveState} saveName={saveName} setSaveName={setSaveName} savedBy={savedBy} setSavedBy={setSavedBy}
      onDiscard={discardPlan} planEdited={planEdited}
      routesView={routesView} onReorder={reorderStop} onMove={moveStop} onResequence={onResequence} readOnly={viewing}
      hoverId={hoverId} setHoverId={setHoverId} onOpenStop={openStop}
      savedLoad={viewedLoad} onCloseLoad={() => setViewedLoad(null)}
      onRename={renameLoad} onToggleDispatch={toggleDispatched} onDelete={deleteLoad} manageError={manageError} />
  );

  const loadsContent = (
    <RoutingLoadsPanel loads={loads} loading={loadsLoading} error={loadsError}
      viewedId={viewedLoad?.id || null}
      onOpen={(l) => { setViewedLoad(l); setMobilePanel('result'); setSheetOpen(true); }}
      onRename={renameLoad} onToggleDispatch={toggleDispatched} onDelete={deleteLoad} manageError={manageError} />
  );

  // ── Mobile: map + collapsible bottom sheet (Setup / Result) ──
  // Rendered in BOTH layout branches below — RoutingScreen returns separately for mobile and
  // desktop, and a modal defined in only one is invisible on the other.
  const newRouteModal = newRouteOpen ? (
    <NewRouteModal
      date={selectedDate}
      existingNames={routeGroups.map((g) => g.name || g.key)}
      origin={readShipFromOrigin()}
      busy={newRouteBusy}
      error={newRouteError}
      onCancel={() => { if (!newRouteBusy) { setNewRouteOpen(false); setNewRouteError(null); } }}
      onCreate={createNewRoute}
    />
  ) : null;

  if (isMobile) {
    const tabCls = (on) => `flex-1 py-1.5 text-xs font-semibold rounded ${on ? 'text-white' : 'text-slate-600 bg-slate-100'}`;
    return (
      <div className="flex-1 flex flex-col min-h-0">
        <div className="flex-1 relative min-w-0">
          <div ref={mapDiv} className="absolute inset-0" />
          <RoutingMapFilters unplannedOnly={routeUnplannedOnly} setUnplannedOnly={setRouteUnplannedOnly} satellite={routeSatellite} setSatellite={setRouteSatellite} showRoutes={routeShowRoutes} setShowRoutes={setRouteShowRoutes} hideLabels={routeHideLabels} setHideLabels={setRouteHideLabels} />
          {/* Stops status card — same pill as the dispatch Map (below the ⚙ filters button). */}
          <div className="absolute top-12 right-2 z-[15] max-w-[230px]">{statusCard()}</div>
          {!viewing && <RoutingMapTools selectMode={selectMode} onBox={() => (selectMode === 'box' ? cancelMode() : beginMode('box'))} onLasso={() => (selectMode === 'lasso' ? cancelMode() : beginMode('lasso'))} ninjaMode={ninjaMode} onToggleNinja={onNinjaTool} ninjaAvailable={wbRoutes.length > 0} />}
          {mapsError && <div className="absolute top-2 left-1/2 -translate-x-1/2 bg-red-50 border border-red-300 text-red-700 text-[11px] rounded px-2 py-1">{mapsError}</div>}
          {mapToast && <div className="absolute bottom-3 left-1/2 -translate-x-1/2 z-30 max-w-[92%] bg-slate-900/90 text-white text-[11px] rounded-lg shadow-lg px-3 py-1.5 text-center"><NinjaIcon size={12} className="inline -mt-0.5 mr-1" />{mapToast}</div>}
          {/* Ninja status — while armed, tapping a stop on the map adds it to the active route. Shown
              here so it's clear even with the bottom sheet collapsed (the sheet drops on arm). */}
          {!viewing && ninjaMode && wbRoutes.length > 0 && (
            <div className="absolute top-12 left-1/2 -translate-x-1/2 z-30 max-w-[92%] bg-amber-500 text-white text-[11px] font-semibold rounded-full shadow-lg px-3 py-1 flex items-center gap-1.5">
              <NinjaIcon size={13} /><span>Ninja on — tap stops → <b>{effectiveActiveKey || '—'}</b></span>
              <button onClick={() => setNinjaMode(false)} className="ml-1 underline font-normal">done</button>
            </div>
          )}
          {/* Floating Box/Lasso control — the Setup panel's Done button is hidden behind the
              Compare workbench once a route is built, so finishing the lasso must not depend on
              the bottom sheet. Shown on the map whenever a select tool is armed (mobile). */}
          {!viewing && selectMode && isMobile && (
            <div className="absolute top-12 left-1/2 -translate-x-1/2 z-30 max-w-[94%] bg-amber-500 text-white text-[11px] font-semibold rounded-full shadow-lg pl-3 pr-1.5 py-1 flex items-center gap-2">
              {selectMode === 'lasso'
                ? <span>⬠ Tap points · {lassoCount} placed{lassoCount < 3 ? ' (need ≥3)' : ''}</span>
                : <span>📦 Tap two corners · {boxStep === 0 ? '1 of 2' : '2 of 2'}</span>}
              {selectMode === 'lasso' && (
                <button onClick={finishLasso} disabled={lassoCount < 3} className="rounded-full bg-white text-amber-700 px-2.5 py-0.5 font-bold disabled:opacity-50">Done</button>
              )}
              <button onClick={cancelMode} className="rounded-full bg-white/25 px-2 py-0.5 font-normal">Cancel</button>
            </div>
          )}
          {viewing
            ? <div className="absolute top-2 left-1/2 -translate-x-1/2 z-20 bg-indigo-600 text-white text-[11px] rounded shadow px-3 py-1.5 flex items-center gap-2 max-w-[92%]"><span className="truncate">👁 {viewedLoad?.name || viewedLoad?.id}</span><button onClick={() => setViewedLoad(null)} className="underline shrink-0">Back</button></div>
            : <button onClick={() => { setMobilePanel('setup'); setSheetOpen(true); }} className="absolute top-2 left-2 z-20 bg-white/95 border border-slate-200 rounded shadow px-2 py-1 text-[11px]" title="Review selected stops in the Setup panel">{tally.count} selected · {tally.skids} skids · {tally.pieces} pcs</button>}
          {/* On mobile the selected list lives in the Setup sheet (tap the chip) — a full-width map
              overlay here covered the stops and tool rail (issue #232), so it's desktop-only now. */}
          {/* The dispatch-Map data grid — Stops/Loads spreadsheet, route-able. Toggleable (gear). */}
          {bottomGridOn && <BottomStopsTable
            rootRef={bottomGridRef}
            stops={stops}
            loadStops={stops}
            boardDate={selectedDate}
            notes={notes}
            totalCount={stops.length}
            open={bottomTableOpen}
            setOpen={setBottomTableOpen}
            onPick={pickStopFromTable}
            onPickLoad={pickLoadToCompare}
            onWindowRowsChange={setGridWindowStops}
            onSearchMatchChange={setSearchMatchIds}
            onStatusFilterChange={setStatusFilterIds}
            highlightIds={selectedIds}
            planVersion={planVersion}
          />}
        </div>
        <div className="border-t bg-white flex flex-col shrink-0" style={{ height: sheetOpen ? '50%' : 'auto' }}>
          <div className="flex items-center gap-2 px-2 py-1.5 border-b">
            <button onClick={() => setSheetOpen((o) => !o)} className="text-xs px-2 py-1 rounded border border-slate-300" aria-label={sheetOpen ? 'Collapse' : 'Expand'}>{sheetOpen ? '▾' : '▴'}</button>
            <div className="flex-1 flex gap-1">
              <button onClick={() => { setPanelStop(null); setMobilePanel('setup'); setSheetOpen(true); }} className={tabCls(mobilePanel === 'setup')} style={mobilePanel === 'setup' ? { background: BRAND } : {}}>Setup{tally.count ? ` (${tally.count})` : ''}</button>
              <button onClick={() => { setPanelStop(null); setMobilePanel('loads'); setSheetOpen(true); }} className={tabCls(mobilePanel === 'loads')} style={mobilePanel === 'loads' ? { background: BRAND } : {}}>{rightPanelMode === 'routes' ? `Routes${routeGroups.length ? ` (${routeGroups.length})` : ''}` : `Loads${loads.length ? ` (${loads.length})` : ''}`}</button>
              <button onClick={() => { setPanelStop(null); setMobilePanel('result'); setSheetOpen(true); }} className={tabCls(mobilePanel === 'result')} style={mobilePanel === 'result' ? { background: BRAND } : {}}>Result{baseResult ? ` (${baseResult.routes.length})` : job?.status === 'running' || job?.status === 'queued' ? ' …' : ''}</button>
            </div>
          </div>
          {sheetOpen && (
            panelStop ? (
              <RoutingStopPanel
                stop={panelStop}
                notes={notes}
                windowViolatedSet={windowViolatedSet}
                onClose={() => setPanelStop(null)}
                onOpenLoad={(key) => { openRouteInWorkbench(key); setPanelStop(null); }}
                onMoveLocation={startMoveLocation}
                onEditAddress={openAddrEditor}
                onAutoFixAddress={autoFixAddress}
                onOpenHistory={openCustomerHistory}
                onText={textCustomer}
                onTextDriver={textDriverForStop}
                onSave={saveStopNote}
                saving={savingNote}
                saveError={saveNoteError}
                drivers={notesDrivers}
              />
            ) : (
            <div className="flex-1 min-h-0 overflow-y-auto p-3 space-y-3 text-sm" style={{ paddingBottom: 'calc(12px + env(safe-area-inset-bottom))' }}>
              {mobilePanel === 'setup'
                ? <>
                    {selectedStops.length > 0 && (
                      <MobileSelectedStops count={tally.count} skids={tally.skids} pieces={tally.pieces} defaultOpen={wbRoutes.length === 0}>
                        <RoutingStopsPanel selectedStops={selectedStops} notes={notes} onRemove={removeStop} hoverId={hoverId} setHoverId={setHoverId} onOpenStop={openStop} />
                      </MobileSelectedStops>
                    )}
                    {wbRoutes.length > 0
                      ? <RoutingWorkbench wbRoutes={wbRoutesColored} stopById={stopById} boardStopById={boardStopById} ninjaMode={ninjaMode} onToggleNinja={setNinjaMode} onArmNinja={armNinjaFromPanel} activeKey={effectiveActiveKey} onSetActive={setActiveRouteKey} onResequence={wbResequence} onCollapse={toggleWbCollapse} onClose={closeWbRoute} onCloseAll={closeAllWb} onMoveStop={wbMoveStop} onDropStop={wbDropStop} onRemoveStop={wbRemoveStop} onRemoveAllStops={wbRemoveAllStops} onUndoRemove={wbUndoRemove} onClearRemoved={clearWbRemoved} onOpenStop={openStop} onPrintManifest={printWbManifest} selectedCount={selectedStops.length} onSendSelection={sendSelectionToRoute} isMobile liveWrite={liveWrite} onBoardSync={syncBoardAfterSave} boardDate={selectedDate} peerClaimFor={peerClaimFor} onRouteCreated={onRouteCreated} />
                      : controlsContent}
                  </>
                : mobilePanel === 'loads'
                  ? (rightPanelMode === 'routes'
                      ? (
                        <>
                          <RoutesDriversToggle subTab={routesSubTab} setSubTab={setRoutesSubTab} routesCount={routeGroups.length} className="mb-2" />
                          {routesSubTab === 'drivers'
                            ? <RoutingDriversPanel roster={driverRoster} routeGroups={routeGroups} onRefresh={refreshDriverRoster} onPickDriver={onPickDriver} />
                            : <RoutingRoutesPanel groups={routeGroups} onPick={onPickRoute} liveWrite={liveWrite} roster={assignRoster} rosterError={assignRosterError} assignLive={assignLive} setAssignLive={setAssignLive} onAssignDriver={onAssignDriver} assignedOverride={assignedOverride} assigningKey={assigningKey} onDispatchLoad={onDispatchLoad} dispatchingKey={dispatchingKey} onNewRoute={liveWrite ? openNewRoute : null} />}
                        </>
                      )
                      : loadsContent)
                  : resultContent}
            </div>
            )
          )}
        </div>
        {newRouteModal}
        {movingStop && <MoveLocationBar stop={movingStop} saving={savingLoc} onSave={saveStopLocation} onCancel={cancelMoveLocation} onReset={resetStopLocation} />}
        {editAddrStop && <AddressEditModal stop={editAddrStop} note={notes.get(editAddrStop.matchKey)} google={google} seed={editAddrSeed} onClose={() => { setEditAddrStop(null); setEditAddrSeed(null); }} onSaved={() => refreshStops({ silent: true })} />}
        {routingSmsTargets && <SmsComposeModal title={routingSmsTargets.title} recipients={routingSmsTargets.recipients} initialText={routingSmsTargets.initialText} onClose={() => setRoutingSmsTargets(null)} />}
        {/* Closing the manifest bumps mapReady: the print bridge display:none's the whole app during
            window.print(), which makes Google Maps drop its rendered markers — the numbered route
            pins were GONE after printing until something else rebuilt them. The bump re-runs the
            marker/polyline effects so the map comes back exactly as it was. */}
        {wbManifest && <PrintDocModal title={wbManifest.title} html={wbManifest.html} onClose={() => { setWbManifest(null); setMapReady((n) => n + 1); }} />}
        {versionLogOpen && <VersionLogModal onClose={() => setVersionLogOpen(false)} />}
        {/* Customer-history overlay (History button on the stop panel) — Firestore-only. */}
        {histOpen && (
          <div className="fixed inset-0 z-[1100] bg-white flex flex-col" style={{ paddingBottom: 'env(safe-area-inset-bottom)' }}>
            <PastProSearch notes={notes} initialQuery={histSeed} noApi onPickCustomer={(s) => { setHistOpen(false); setPanelStop(s); setSheetOpen(true); }} onClose={() => setHistOpen(false)} />
          </div>
        )}
      </div>
    );
  }

  // ── Desktop: the dispatch console — Setup (left) · large map (center) ·
  //    Stops/Result (right). ──
  const railTab = (id, label) => (
    <button
      onClick={() => setDesktopRail(id)}
      className={`flex-1 py-2 text-[13px] font-semibold border-b-2 ${desktopRail === id ? 'text-slate-900' : 'text-slate-500 border-transparent hover:text-slate-700'}`}
      style={desktopRail === id ? { borderColor: BRAND, color: BRAND } : {}}
    >{label}</button>
  );
  // The Compare panel AUTO-SIZES to the number of open route cards (1→3): each card is 300px wide
  // plus the 8px gaps and 16px padding, clamped to 72% of the viewport. So opening a 2nd route
  // grows it to two, closing one collapses it back to one. (The Setup left panel stays resizable.)
  const wbCols = Math.min(WB_MAX, wbRoutes.length);
  const wbWidth = Math.min(wbCols * 300 + Math.max(0, wbCols - 1) * 8 + 16, Math.round(viewportWidth * 0.72));
  return (
    <div className="flex-1 flex min-h-0">
      {/* Left: Setup stack (resizable) — OR the route workbench, which auto-sizes to its open cards.
          The Setup stack is hideable (gear → "Setup panel"); the Compare workbench always shows when
          routes are open. With the Setup panel off and no routes open, the map gets the full width. */}
      {wbRoutes.length > 0 ? (
        <div className="shrink-0 border-r bg-white min-h-0 overflow-x-auto" style={{ width: wbWidth }}>
          <RoutingWorkbench wbRoutes={wbRoutesColored} stopById={stopById} boardStopById={boardStopById} ninjaMode={ninjaMode} onToggleNinja={setNinjaMode} onArmNinja={armNinjaFromPanel} activeKey={effectiveActiveKey} onSetActive={setActiveRouteKey} onResequence={wbResequence} onCollapse={toggleWbCollapse} onClose={closeWbRoute} onCloseAll={closeAllWb} onMoveStop={wbMoveStop} onDropStop={wbDropStop} onRemoveStop={wbRemoveStop} onRemoveAllStops={wbRemoveAllStops} onUndoRemove={wbUndoRemove} onClearRemoved={clearWbRemoved} onOpenStop={openStop} onPrintManifest={printWbManifest} selectedCount={selectedStops.length} onSendSelection={sendSelectionToRoute} isMobile={false} liveWrite={liveWrite} onBoardSync={syncBoardAfterSave} boardDate={selectedDate} peerClaimFor={peerClaimFor} onRouteCreated={onRouteCreated} />
        </div>
      ) : leftPanelOn ? (
        <div className="shrink-0 border-r bg-white overflow-y-auto p-3 space-y-3 text-sm" style={{ width: leftPanel.width }}>
          {controlsContent}
        </div>
      ) : null}
      {/* Resize the Setup panel; the Compare panel auto-sizes to its cards, so no handle there. */}
      {wbRoutes.length === 0 && leftPanelOn && <ResizeHandle onMouseDown={leftPanel.onMouseDown} onDoubleClick={leftPanel.onDoubleClick} />}

      {/* Center: the map canvas */}
      <div className="flex-1 relative min-w-0">
        <div ref={mapDiv} className="absolute inset-0" />
        <RoutingMapFilters unplannedOnly={routeUnplannedOnly} setUnplannedOnly={setRouteUnplannedOnly} satellite={routeSatellite} setSatellite={setRouteSatellite} showRoutes={routeShowRoutes} setShowRoutes={setRouteShowRoutes} hideLabels={routeHideLabels} setHideLabels={setRouteHideLabels} />
        {/* Stops status card — same pill as the dispatch Map (below the ⚙ filters button). */}
        <div className="absolute top-12 right-2 z-[15] max-w-[240px]">{statusCard()}</div>
        {!viewing && <RoutingMapTools selectMode={selectMode} onBox={() => (selectMode === 'box' ? cancelMode() : beginMode('box'))} onLasso={() => (selectMode === 'lasso' ? cancelMode() : beginMode('lasso'))} ninjaMode={ninjaMode} onToggleNinja={onNinjaTool} ninjaAvailable={wbRoutes.length > 0} />}
        {mapsError && <div className="absolute top-2 left-1/2 -translate-x-1/2 bg-red-50 border border-red-300 text-red-700 text-[11px] rounded px-2 py-1">{mapsError}</div>}
        {mapToast && <div className="absolute bottom-3 left-1/2 -translate-x-1/2 z-30 max-w-[80%] bg-slate-900/90 text-white text-[12px] rounded-lg shadow-lg px-3 py-1.5 text-center"><NinjaIcon size={13} className="inline -mt-0.5 mr-1" />{mapToast}</div>}
        {viewing && (
          <div className="absolute top-2 left-1/2 -translate-x-1/2 z-20 bg-indigo-600 text-white text-[12px] rounded shadow px-3 py-1.5 flex items-center gap-3 max-w-[80%]">
            <span className="truncate">👁 Viewing saved load: <b>{viewedLoad?.name || viewedLoad?.id}</b></span>
            <button onClick={() => setViewedLoad(null)} className="underline shrink-0 font-semibold">Back to build</button>
          </div>
        )}
        {/* Floating "Selected N" panel (toggleable) — lists every selected stop over the map. */}
        {!viewing && selPanelOpen && selectedStops.length > 0 && (
          <RoutingSelectionFloatPanel selectedStops={selectedStops} notes={notes} tractorLocs={tractorLocs} onRemove={removeStop} onClearAll={clearSelection} onOpenStop={openStop} onClose={() => setSelPanelOpen(false)} isMobile={false} />
        )}
        {/* Reopen chip when the panel is toggled off but stops are selected. */}
        {!viewing && !selPanelOpen && selectedStops.length > 0 && (
          <button onClick={() => setSelPanelOpen(true)} className="absolute top-2 left-2 z-20 bg-white/95 border border-slate-300 rounded shadow px-2 py-1 text-[12px] font-medium text-slate-700 hover:bg-white" title="Show selected panel">▦ Selected ({selectedStops.length})</button>
        )}
        {/* Drag-box capture overlay — active only while Box mode is armed on desktop. */}
        {selectMode === 'box' && (
          <div
            className="absolute inset-0 z-10 cursor-crosshair"
            onMouseDown={onBoxDown} onMouseMove={onBoxMove} onMouseUp={onBoxUp} onMouseLeave={onBoxUp}
          >
            <div className="absolute top-2 left-1/2 -translate-x-1/2 bg-slate-900/85 text-white text-[11px] rounded px-2 py-1 pointer-events-none">Drag a box around the stops · Esc to cancel</div>
            {dragRect && (
              <div className="absolute border-2 bg-blue-400/10 pointer-events-none" style={{
                borderColor: BRAND,
                left: Math.min(dragRect.x0, dragRect.x1), top: Math.min(dragRect.y0, dragRect.y1),
                width: Math.abs(dragRect.x1 - dragRect.x0), height: Math.abs(dragRect.y1 - dragRect.y0),
              }} />
            )}
          </div>
        )}
        {/* Freehand drag-lasso capture overlay — desktop, while Lasso mode is armed.
            Pointer-captured so the map can't pan; an SVG path previews the shape. */}
        {selectMode === 'lasso' && (
          <div
            className="absolute inset-0 z-10 cursor-crosshair"
            onMouseDown={onLassoDown} onMouseMove={onLassoMove} onMouseUp={onLassoUp} onMouseLeave={onLassoUp}
          >
            <div className="absolute top-2 left-1/2 -translate-x-1/2 bg-slate-900/85 text-white text-[11px] rounded px-2 py-1 pointer-events-none">Hold and draw a shape around the stops · Esc to cancel</div>
            {lassoPath.length > 1 && (
              <svg className="absolute inset-0 w-full h-full pointer-events-none">
                <polyline points={lassoPath.map((p) => `${p.x},${p.y}`).join(' ')} fill="rgba(30,91,146,0.10)" stroke={BRAND} strokeWidth="2" strokeLinejoin="round" />
              </svg>
            )}
          </div>
        )}
        {/* The dispatch-Map data grid — Stops/Loads spreadsheet, route-able. Toggleable (gear). */}
        {bottomGridOn && <BottomStopsTable
          rootRef={bottomGridRef}
          stops={stops}
          loadStops={stops}
          boardDate={selectedDate}
          notes={notes}
          totalCount={stops.length}
          open={bottomTableOpen}
          setOpen={setBottomTableOpen}
          onPick={pickStopFromTable}
          onPickLoad={pickLoadToCompare}
          headerRight={bottomGridHeaderRight}
          onWindowRowsChange={setGridWindowStops}
          onSearchMatchChange={setSearchMatchIds}
          highlightIds={selectedIds}
          planVersion={planVersion}
        />}
      </div>

      {/* Right: Stops | Result (or the Routes/Drivers view) — resizable, like the left,
          and fully collapsible to a thin re-open strip (dispatcher request). */}
      {rightCollapsed ? (
        <button
          onClick={() => setRightCollapsed(false)}
          className="shrink-0 border-l bg-white w-7 min-h-0 flex flex-col items-center gap-1.5 pt-2 text-slate-500 hover:bg-slate-50 hover:text-slate-700"
          title="Expand right panel"
        >
          <ChevronRight size={15} className="rotate-180" />
          <span className="text-[10px] font-semibold uppercase tracking-wide" style={{ writingMode: 'vertical-rl' }}>
            {rightPanelMode === 'routes' ? `Routes (${routeGroups.length})` : 'Panel'}
          </span>
        </button>
      ) : (
      <>
      <ResizeHandle onMouseDown={rightPanel.onMouseDown} onDoubleClick={rightPanel.onDoubleClick} />
      <div className="shrink-0 border-l bg-white flex flex-col min-h-0" style={{ width: rightPanel.width }}>
        {panelStop ? (
          <RoutingStopPanel
            stop={panelStop}
            notes={notes}
            windowViolatedSet={windowViolatedSet}
            onClose={() => setPanelStop(null)}
            onOpenLoad={(key) => { openRouteInWorkbench(key); setPanelStop(null); }}
            onMoveLocation={startMoveLocation}
            onEditAddress={openAddrEditor}
            onAutoFixAddress={autoFixAddress}
            onOpenHistory={openCustomerHistory}
            onText={textCustomer}
            onTextDriver={textDriverForStop}
            onSave={saveStopNote}
            saving={savingNote}
            saveError={saveNoteError}
            drivers={notesDrivers}
          />
        ) : rightPanelMode === 'routes' ? (
          <>
            <div className="flex items-center justify-between px-3 py-2 border-b shrink-0 gap-2">
              <RoutesDriversToggle subTab={routesSubTab} setSubTab={setRoutesSubTab} routesCount={routeGroups.length} />
              <span className="text-[10px] uppercase tracking-wide text-slate-400 truncate">{formatDateLong(selectedDate)}</span>
              <button onClick={() => setRightCollapsed(true)} className="shrink-0 text-slate-400 hover:text-slate-700" title="Collapse panel"><ChevronRight size={15} /></button>
            </div>
            {routesSubTab === 'drivers'
              ? <RoutingDriversPanel roster={driverRoster} routeGroups={routeGroups} onRefresh={refreshDriverRoster} onPickDriver={onPickDriver} />
              : <RoutingRoutesPanel groups={routeGroups} onPick={onPickRoute} liveWrite={liveWrite} roster={assignRoster} rosterError={assignRosterError} assignLive={assignLive} setAssignLive={setAssignLive} onAssignDriver={onAssignDriver} assignedOverride={assignedOverride} assigningKey={assigningKey} onDispatchLoad={onDispatchLoad} dispatchingKey={dispatchingKey} onNewRoute={liveWrite ? openNewRoute : null} />}
          </>
        ) : (
        <>
        <div className="flex border-b shrink-0">
          {railTab('stops', `Stops${tally.count ? ` (${tally.count})` : ''}`)}
          {railTab('loads', `Loads${dayLoads.length ? ` (${dayLoads.length})` : ''}`)}
          {railTab('result', `Result${baseResult ? ` (${baseResult.routes.length})` : (job?.status === 'running' || job?.status === 'queued') ? ' …' : ''}`)}
          <button onClick={() => setRightCollapsed(true)} className="shrink-0 px-1.5 text-slate-400 hover:text-slate-700 border-l" title="Collapse panel"><ChevronRight size={15} /></button>
        </div>
        {desktopRail === 'stops' ? (
          <RoutingStopsPanel selectedStops={selectedStops} notes={notes} onRemove={removeStop} hoverId={hoverId} setHoverId={setHoverId} onOpenStop={openStop} />
        ) : desktopRail === 'loads' ? (
          <div className="flex-1 min-h-0 flex flex-col">
            {/* Two different things are called a load. The board's routes are what a dispatcher
                wants here; saved optimizer plans stay one click away rather than being cut. */}
            <div className="flex gap-1 px-2 py-1.5 border-b shrink-0">
              {[['board', `On the board${dayLoads.length ? ` (${dayLoads.length})` : ''}`], ['saved', `Saved plans${loads.length ? ` (${loads.length})` : ''}`]].map(([id, label]) => (
                <button key={id} onClick={() => setLoadsRailView(id)}
                  className={`flex-1 text-[11px] font-semibold px-2 py-1 rounded border ${loadsRailView === id ? 'border-blue-600 bg-blue-600 text-white' : 'border-slate-300 bg-white text-slate-600 hover:bg-slate-50'}`}>
                  {label}
                </button>
              ))}
            </div>
            {loadsRailView === 'saved' ? (
              <RoutingLoadsPanel loads={loads} loading={loadsLoading} error={loadsError}
                viewedId={viewedLoad?.id || null}
                onOpen={(l) => { setViewedLoad(l); setDesktopRail('result'); }}
                onRename={renameLoad} onToggleDispatch={toggleDispatched} onDelete={deleteLoad} manageError={manageError} />
            ) : (
              <RoutingDayLoadsPanel rows={dayLoads} tally={dayLoadsTally}
                onPickLoad={(r) => pickLoadToCompare(r.loadNbr || r.loadId || r.key)}
                isOpen={(r) => wbRoutes.some((w) => w.key === r.key || (r.name && w.key === r.name) || (r.loadNbr && (w.key === r.loadNbr || w.loadNbr === r.loadNbr)))} />
            )}
          </div>
        ) : (
          <div className="flex-1 min-h-0 overflow-y-auto p-3 space-y-3 text-sm">{resultContent}</div>
        )}
        </>
        )}
      </div>
      </>
      )}
      {newRouteModal}
      {movingStop && <MoveLocationBar stop={movingStop} saving={savingLoc} onSave={saveStopLocation} onCancel={cancelMoveLocation} onReset={resetStopLocation} />}
      {editAddrStop && <AddressEditModal stop={editAddrStop} note={notes.get(editAddrStop.matchKey)} google={google} seed={editAddrSeed} onClose={() => { setEditAddrStop(null); setEditAddrSeed(null); }} onSaved={() => refreshStops({ silent: true })} />}
      {routingSmsTargets && <SmsComposeModal title={routingSmsTargets.title} recipients={routingSmsTargets.recipients} initialText={routingSmsTargets.initialText} onClose={() => setRoutingSmsTargets(null)} />}
        {/* Closing the manifest bumps mapReady: the print bridge display:none's the whole app during
            window.print(), which makes Google Maps drop its rendered markers — the numbered route
            pins were GONE after printing until something else rebuilt them. The bump re-runs the
            marker/polyline effects so the map comes back exactly as it was. */}
        {wbManifest && <PrintDocModal title={wbManifest.title} html={wbManifest.html} onClose={() => { setWbManifest(null); setMapReady((n) => n + 1); }} />}
        {versionLogOpen && <VersionLogModal onClose={() => setVersionLogOpen(false)} />}
        {/* Customer-history overlay (History button on the stop panel) — this location's past
            PROs + date + delivering driver, from saved Firestore history only (no NuVizz). */}
        {histOpen && (
          <div
            className="fixed inset-0 z-[1100] bg-slate-900/40 flex items-start justify-center p-4 sm:p-8"
            onMouseDown={(e) => { if (e.target === e.currentTarget) setHistOpen(false); }}
          >
            <div className="w-full max-w-lg max-h-[85vh] bg-white rounded-xl shadow-2xl flex flex-col overflow-hidden">
              <PastProSearch notes={notes} initialQuery={histSeed} noApi onPickCustomer={(s) => { setHistOpen(false); setPanelStop(s); }} onClose={() => setHistOpen(false)} />
            </div>
          </div>
        )}
    </div>
  );
}

function RoutingResultPanel({ job, result, meta, usedGoogle, stopById, plannedLoads, onStagePlan, onSave, saveState, saveName, setSaveName, savedBy, setSavedBy, onDiscard, planEdited, routesView, onReorder, onMove, onResequence, readOnly, hoverId, setHoverId, onOpenStop, savedLoad, onCloseLoad, onRename, onToggleDispatch, onDelete, manageError }) {
  const [confirmDiscard, setConfirmDiscard] = useState(false);
  const [riskOpen, setRiskOpen] = useState(false); // risk flags are a collapsed disclosure; never auto-expand
  useEffect(() => { setConfirmDiscard(false); setRiskOpen(false); }, [job, savedLoad]);
  // Live-build status gates only apply when NOT viewing a saved load.
  if (!savedLoad) {
    if (!job) return <div className="text-[12px] text-slate-400">Build a plan to see routes, ETAs, load, spill, and cost here.</div>;
    if (job.status === 'queued' || job.status === 'running') return <div className="text-[12px] text-slate-600">⏳ Building plan… ({job.stage || job.status})</div>;
    if (job.status === 'error') return <div className="text-[12px] text-red-600">Build failed: {job.error || 'unknown error'}</div>;
    if (!result) return <div className="text-[12px] text-slate-400">No result.</div>;
  }
  if (!result || !Array.isArray(result.routes)) {
    return (
      <div className="space-y-3">
        {savedLoad && <SavedLoadManageBar load={savedLoad} onClose={onCloseLoad} onRename={onRename} onToggleDispatch={onToggleDispatch} onDelete={onDelete} manageError={manageError} />}
        <div className="text-[12px] text-slate-400">This load has no routes to show.</div>
      </div>
    );
  }

  const cost = meta.estimatedCostUsd || 0;
  const ai = result.aiAssist || {};
  return (
    <div className="space-y-3">
      {savedLoad ? (
        <SavedLoadManageBar load={savedLoad} onClose={onCloseLoad} onRename={onRename} onToggleDispatch={onToggleDispatch} onDelete={onDelete} manageError={manageError} />
      ) : (
        <div className="rounded border border-slate-300 bg-slate-50 p-2 text-[11px] text-slate-600">
          This is a <b>plan saved in our system only</b>. It has <b>NOT</b> been sent to NuVizz or dispatched to any driver.
        </div>
      )}

      {/* Loads-bound build: the primary next step. Staging is LOCAL — each built route lands on
          its load's Compare card (real loadNbr/loadId); the card Save is the one write path. */}
      {!savedLoad && plannedLoads && plannedLoads.length > 0 && onStagePlan && (
        <div className="rounded border-2 p-2 text-[12px] space-y-1.5" style={{ borderColor: BRAND }}>
          <div className="font-semibold text-slate-800">Bound to your NuVizz loads</div>
          <div className="text-[11px] text-slate-600">One route per picked load: <b>{plannedLoads.map((b) => b.key).join(', ')}</b>. Stage them onto Compare cards, tweak anything (drag / ninja / driver), then hit <b>Save</b> on the cards — that's what writes NuVizz, with the full post-save verify.</div>
          <button onClick={onStagePlan} className="w-full py-2 rounded text-white font-semibold" style={{ background: BRAND }}>Stage onto Compare cards →</button>
        </div>
      )}

      {/* Cost / quality readout */}
      <div className={`rounded border p-2 text-[12px] ${usedGoogle ? 'border-amber-300 bg-amber-50' : 'border-green-300 bg-green-50'}`}>
        <div className="font-semibold">{usedGoogle ? 'Google live drive-times' : 'Free estimate (straight-line)'}</div>
        <div className="flex justify-between"><span>Matrix elements</span><b>{meta.googleElementCount ?? '—'}</b></div>
        <div className="flex justify-between"><span>Estimated cost</span><b>${Number(cost).toFixed(2)}</b></div>
        <div className="flex justify-between"><span>AI assist</span><b>{result.aiConfigured ? `${[ai.intent && 'intent', ai.explain && 'rationale', ai.geometry && 'geometry'].filter(Boolean).join(', ') || 'available, not needed'}` : 'off'}</b></div>
      </div>

      {!readOnly && <div className="text-[11px] text-slate-500">Drag a stop (or use ▲▼) to reorder a route. The map and ETAs update live.</div>}

      {/* Rationale + risk */}
      {result.rationale && <div className="text-[12px] text-slate-700"><b>Rationale.</b> {result.rationale}</div>}
      {Array.isArray(result.riskFlags) && result.riskFlags.length > 0 && (
        <div className="text-[11px] text-amber-800 bg-amber-50 border border-amber-200 rounded">
          <button onClick={() => setRiskOpen((o) => !o)} className="w-full flex items-center justify-between gap-2 px-2 py-1.5 font-semibold text-left" aria-expanded={riskOpen}>
            <span>⚠ {result.riskFlags.length} risk flag{result.riskFlags.length === 1 ? '' : 's'}</span>
            {riskOpen ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
          </button>
          {riskOpen && <ul className="list-disc ml-5 pr-2 pb-2 space-y-0.5">{result.riskFlags.map((f, i) => <li key={i}>{f}</li>)}</ul>}
        </div>
      )}

      {/* Routes (numbered; reorderable unless viewing a saved load) */}
      {(routesView || []).map((rv) => (
        <RoutingRouteCard key={rv.truckId} rv={rv} stopById={stopById} usedGoogle={usedGoogle} readOnly={readOnly}
          onReorder={onReorder} onMove={onMove} onResequence={onResequence} hoverId={hoverId} setHoverId={setHoverId} onOpenStop={onOpenStop} />
      ))}

      {/* Spill */}
      {result.unassigned && result.unassigned.length > 0 && (
        <div className="rounded border border-red-200 bg-red-50 p-2 text-[12px]">
          <div className="font-semibold text-red-700 mb-1">Could not place ({result.unassigned.length})</div>
          {result.unassigned.map((u) => {
            const s = stopById.get(String(u.stopId));
            return (
              <div key={u.stopId} className="mb-1">
                <div className="flex items-center gap-1.5"><b>{s?.businessName || u.stopId}</b>{s && <ProLink stop={s} onOpen={onOpenStop} className="text-[11px]" />}</div>
                <div className="text-[11px] text-red-600">{u.reasons.join('; ')}</div>
              </div>
            );
          })}
        </div>
      )}

      {/* Save panel (live build only) */}
      {!savedLoad && (
        <div className="border-t pt-2 space-y-1.5">
          <label className="block text-[11px] font-semibold text-slate-600">Save as
            <input value={saveName} onChange={(e) => setSaveName(e.target.value)} placeholder="Load name" className="mt-0.5 w-full border rounded px-2 py-1 text-[12px] font-normal text-slate-800" />
          </label>
          <input value={savedBy} onChange={(e) => setSavedBy(e.target.value)} placeholder="Saved by (initials, optional)" className="w-full border rounded px-2 py-1 text-[12px] text-slate-800" />
          <div className="flex gap-2">
            <button onClick={onSave} disabled={saveState === 'saving'} className="flex-1 py-2 rounded text-white font-semibold disabled:opacity-40" style={{ background: BRAND }}>
              {saveState === 'saving' ? 'Saving…' : saveState === 'saved' ? '✓ Saved — shared' : 'Save load'}
            </button>
            {onDiscard && (
              confirmDiscard ? (
                <button onClick={() => { setConfirmDiscard(false); onDiscard(); }} className="shrink-0 px-3 py-2 rounded bg-red-600 text-white text-[12px] font-semibold">Discard hand-tuned plan?</button>
              ) : (
                <button
                  onClick={() => (planEdited ? setConfirmDiscard(true) : onDiscard())}
                  title="Throw away this built plan and start over (keeps your stop + truck selection)"
                  className="shrink-0 px-3 py-2 rounded border border-red-300 text-red-700 text-[12px] font-semibold hover:bg-red-50"
                >Discard plan</button>
              )
            )}
          </div>
          {saveState && saveState !== 'saving' && saveState !== 'saved' && <div className="text-[11px] text-red-600">{saveState}</div>}
          <div className="text-[10px] text-slate-400">Discard clears the routes (keeps your selection); it doesn’t touch any saved load.</div>
        </div>
      )}
    </div>
  );
}

// Saved-load header + manage row: rename (inline, no native prompt), toggle
// Dispatched, Delete (explicit confirm), and "Back to build".
function SavedLoadManageBar({ load, onClose, onRename, onToggleDispatch, onDelete, manageError }) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(load?.name || '');
  const [confirmDel, setConfirmDel] = useState(false);
  useEffect(() => { setDraft(load?.name || ''); setEditing(false); setConfirmDel(false); }, [load?.id]);
  const dispatched = !!load?.dispatched;
  const created = formatDateTime(tsToMillis(load?.created_at));
  return (
    <div className="rounded border border-indigo-300 bg-indigo-50 p-2 text-[12px] space-y-1.5">
      <div className="flex items-center justify-between gap-2">
        <span className="text-[10px] uppercase font-bold tracking-wide text-indigo-700">Viewing saved load</span>
        <button onClick={onClose} className="text-[11px] underline text-indigo-700 font-semibold shrink-0">← Back to build</button>
      </div>
      {editing ? (
        <div className="flex items-center gap-1">
          <input value={draft} onChange={(e) => setDraft(e.target.value)} className="flex-1 border rounded px-2 py-1 text-[12px]" />
          <button onClick={() => { onRename(load.id, draft); setEditing(false); }} className="px-2 py-1 text-[11px] rounded text-white font-semibold" style={{ background: BRAND }}>Save</button>
          <button onClick={() => { setDraft(load.name || ''); setEditing(false); }} className="px-2 py-1 text-[11px] rounded border border-slate-300">Cancel</button>
        </div>
      ) : (
        <div className="flex items-center gap-2">
          <span className="font-semibold text-slate-800 truncate flex-1" title={load?.name}>{load?.name || load?.id}</span>
          <button onClick={() => setEditing(true)} className="text-[11px] underline text-slate-600 shrink-0">Rename</button>
        </div>
      )}
      <div className="flex items-center gap-2 flex-wrap text-[10px] text-slate-500">
        <span className={`px-1.5 py-0.5 rounded font-bold uppercase ${dispatched ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-200 text-slate-600'}`}>{dispatched ? 'Dispatched' : 'Saved'}</span>
        {load?.manual_reorder && <span className="px-1.5 py-0.5 rounded font-bold uppercase bg-amber-100 text-amber-700">Manual order</span>}
        {created && <span>{created}</span>}
        {load?.saved_by && <span>· by {load.saved_by}</span>}
        {load?.app_version && <span>· v{load.app_version}</span>}
      </div>
      <div className="flex items-center gap-1 pt-0.5">
        <button onClick={() => onToggleDispatch(load.id, !dispatched)} className="flex-1 px-2 py-1 text-[11px] rounded border border-slate-300 bg-white hover:bg-slate-50">
          {dispatched ? 'Mark not dispatched' : 'Mark dispatched'}
        </button>
        {confirmDel ? (
          <>
            <button onClick={() => onDelete(load.id)} className="px-2 py-1 text-[11px] rounded bg-red-600 text-white font-semibold">Confirm delete</button>
            <button onClick={() => setConfirmDel(false)} className="px-2 py-1 text-[11px] rounded border border-slate-300">Cancel</button>
          </>
        ) : (
          <button onClick={() => setConfirmDel(true)} className="px-2 py-1 text-[11px] rounded border border-red-300 text-red-700 hover:bg-red-50">Delete</button>
        )}
      </div>
      {manageError && <div className="text-[11px] text-red-600">{manageError}</div>}
    </div>
  );
}

// The live, shared Loads list — fed by useSavedLoads (onSnapshot). Sortable;
// explicit loading / empty / error. Each row opens the load on the map.
/**
 * RoutingDayLoadsPanel (§L) — the day's NuVizz LOADS in the right rail.
 *
 * Chad, Jul 31: "eroutes never end up on the column even though it says its what its for."
 * The rail's Loads tab listed SAVED PLANS (optimizer output, Firestore) while the bottom grid
 * beside it listed 99 real loads — two different things wearing the same word. This panel is
 * the same set the bottom grid shows: routes built on the board, plus the day's empty Drafts,
 * which exist only in the roster because they have no stops to group.
 *
 * Clicking a row opens it in Compare, exactly like the bottom grid's Loads row.
 */
function RoutingDayLoadsPanel({ rows, tally, onPickLoad, isOpen }) {
  const [q, setQ] = useState('');
  const [hideEmpty, setHideEmpty] = useState(false);
  const shown = useMemo(() => {
    const needle = q.trim().toLowerCase();
    return rows.filter((r) => {
      if (hideEmpty && (r.empty || r.count === 0)) return false;
      if (!needle) return true;
      return [r.display, r.name, r.loadNbr, r.driver].filter(Boolean).join(' ').toLowerCase().includes(needle);
    });
  }, [rows, q, hideEmpty, ]);
  return (
    <div className="flex-1 min-h-0 flex flex-col">
      <div className="sticky top-0 z-20 bg-white border-b px-2 py-1.5 flex items-center gap-1.5 shrink-0">
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search loads / driver"
          className="flex-1 min-w-0 text-[12px] border border-slate-300 rounded px-2 py-1" />
        {/* On a board that is mostly Drafts, this is the difference between browsing 99 rows
            and browsing the handful that actually carry freight. */}
        <button onClick={() => setHideEmpty((v) => !v)}
          title={hideEmpty ? 'Showing only loads that carry orders — click to show empty Drafts too' : 'Showing every load on the day — click to hide the empty Drafts'}
          className={`text-[11px] font-semibold px-2 py-1 rounded border shrink-0 ${hideEmpty ? 'border-blue-600 bg-blue-600 text-white' : 'border-slate-300 bg-white text-slate-600 hover:bg-slate-50'}`}>
          Built only
        </button>
      </div>
      <div className="px-3 py-1.5 text-[11px] text-slate-500 border-b bg-slate-50 shrink-0">
        {tally.withOrders} built · {tally.empty} empty · {tally.stops} stops
        {shown.length !== rows.length ? ` · showing ${shown.length}` : ''}
      </div>
      {rows.length === 0 ? (
        <div className="p-4 text-[12px] text-slate-400">No loads on this day&apos;s board yet. Use <b>＋ New route</b> in the Routes panel to make one.</div>
      ) : shown.length === 0 ? (
        <div className="p-4 text-[12px] text-slate-400">No loads match.</div>
      ) : (
        <div className="flex-1 min-h-0 overflow-y-auto divide-y">
          {shown.map((r) => {
            const pct = r.count ? Math.round((100 * r.delivered) / r.count) : 0;
            const open = isOpen ? isOpen(r) : false;
            return (
              <button key={r.key} onClick={() => onPickLoad(r)}
                className={`w-full text-left px-3 py-2 hover:bg-slate-50 ${open ? 'bg-blue-50' : ''}`}>
                <div className="flex items-center gap-2">
                  <span className="font-semibold text-[12px] text-blue-700 truncate flex-1 min-w-0">{loadDisplayName(r.name, r.loadNbr) || r.display}</span>
                  {r.empty
                    ? <span className="shrink-0 px-1.5 rounded text-[10px] font-medium bg-amber-50 text-amber-700 border border-amber-200" title={r.status ? `Load status: ${r.status}` : 'No orders assigned yet'}>No orders yet</span>
                    : <span className="shrink-0 text-[11px] font-semibold tabular-nums" style={{ color: pct === 100 ? '#16a34a' : BRAND }}>{pct}%</span>}
                </div>
                <div className="mt-0.5 flex items-center gap-2 text-[11px] text-slate-500">
                  <span className="truncate flex-1 min-w-0">{r.driver || (r.empty ? (r.status || 'Draft') : 'No driver')}</span>
                  {!r.empty && <span className="shrink-0 tabular-nums">{r.count} stop{r.count === 1 ? '' : 's'}{r.onBoard ? ` · ${r.skids} sk · ${r.loose} loose` : ''}</span>}
                </div>
                {/* Two loads CAN share a name — a route cancelled and rebuilt leaves both on the
                    day. They always have different NUMBERS, so show the number: it is the only
                    thing that tells them apart, and the dispatcher needs it for the portal. */}
                {r.ambiguous && r.loadNbr && (
                  <div className="mt-0.5 text-[10px] text-amber-700 font-mono">
                    {r.status || 'load'} · {r.loadNbr}
                  </div>
                )}
                {r.unattributed && (
                  <div className="mt-0.5 text-[10px] text-amber-700">⚠ {r.count} order(s) on the board under this name — two loads share it, so which one holds them can&apos;t be told from the board.</div>
                )}
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

function RoutingLoadsPanel({ loads, loading, error, viewedId, onOpen, onRename, onToggleDispatch, onDelete, manageError }) {
  const rows = useMemo(() => (loads || []).map((l) => ({
    id: l.id, doc: l,
    name: l.name || l.id,
    trucks: Array.isArray(l.result?.routes) ? l.result.routes.length : 0,
    stops: Array.isArray(l.result?.routes) ? l.result.routes.reduce((a, r) => a + (r.orderedStopIds?.length || 0), 0) : 0,
    status: l.dispatched ? 'Dispatched' : 'Saved',
    created: tsToMillis(l.created_at) || 0,
  })), [loads]);
  const { sorted, sortKey, sortDir, toggle } = useSortable(rows, 'created', 'desc');

  return (
    <div className="flex-1 min-h-0 flex flex-col">
      <div className="px-3 py-2 text-[11px] text-slate-500 border-b shrink-0">Saved loads are <b>shared live</b> — a save on any device shows here within seconds.{manageError && <span className="text-red-600"> · {manageError}</span>}</div>
      {error ? (
        <div className="p-4 text-[12px] text-red-600">Couldn’t load saved loads: {error}</div>
      ) : loading ? (
        <div className="p-4 text-[12px] text-slate-500">Loading saved loads…</div>
      ) : rows.length === 0 ? (
        <div className="p-4 text-[12px] text-slate-400">No saved loads yet. Build a plan and use <b>Save load</b>.</div>
      ) : (
        <div className="flex-1 min-h-0 overflow-auto">
          <div className="flex items-center gap-3 px-3 py-1 text-[10px] uppercase tracking-wide text-slate-500 border-b bg-slate-50 sticky top-0">
            <button onClick={() => toggle('name')} className="flex-1 text-left inline-flex items-center gap-0.5">Name{sortKey === 'name' ? (sortDir === 'asc' ? <ChevronUp size={10} /> : <ChevronDown size={10} />) : null}</button>
            <button onClick={() => toggle('status')} className="inline-flex items-center gap-0.5">Status{sortKey === 'status' ? (sortDir === 'asc' ? <ChevronUp size={10} /> : <ChevronDown size={10} />) : null}</button>
            <button onClick={() => toggle('stops')} className="inline-flex items-center gap-0.5">Stops{sortKey === 'stops' ? (sortDir === 'asc' ? <ChevronUp size={10} /> : <ChevronDown size={10} />) : null}</button>
            <button onClick={() => toggle('created')} className="inline-flex items-center gap-0.5">Created{sortKey === 'created' ? (sortDir === 'asc' ? <ChevronUp size={10} /> : <ChevronDown size={10} />) : null}</button>
          </div>
          <div className="divide-y">
            {sorted.map((r) => (
              <LoadRow key={r.id} row={r} active={viewedId === r.id} onOpen={onOpen} onRename={onRename} onToggleDispatch={onToggleDispatch} onDelete={onDelete} />
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

function LoadRow({ row, active, onOpen, onRename, onToggleDispatch, onDelete }) {
  const l = row.doc;
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(l.name || '');
  const [confirmDel, setConfirmDel] = useState(false);
  const created = formatDateTime(row.created);
  return (
    <div className={`px-3 py-2 ${active ? 'bg-indigo-50' : 'hover:bg-slate-50'}`}>
      {editing ? (
        <div className="flex items-center gap-1 mb-1">
          <input value={draft} onChange={(e) => setDraft(e.target.value)} className="flex-1 border rounded px-2 py-1 text-[12px]" />
          <button onClick={() => { onRename(l.id, draft); setEditing(false); }} className="px-2 py-1 text-[11px] rounded text-white font-semibold" style={{ background: BRAND }}>Save</button>
          <button onClick={() => { setDraft(l.name || ''); setEditing(false); }} className="px-2 py-1 text-[11px] rounded border border-slate-300">Cancel</button>
        </div>
      ) : (
        <button onClick={() => onOpen(l)} className="w-full text-left">
          <div className="flex items-center gap-1.5">
            <span className="font-medium text-[12px] truncate flex-1" title={row.name}>{row.name}</span>
            {active && <span className="text-[9px] font-bold text-indigo-700">VIEWING</span>}
          </div>
          <div className="text-[11px] text-slate-500 flex items-center gap-1.5 flex-wrap mt-0.5">
            <span className={`px-1.5 py-0.5 rounded text-[9px] font-bold uppercase ${l.dispatched ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-200 text-slate-600'}`}>{row.status}</span>
            {l.manual_reorder && <span className="px-1.5 py-0.5 rounded text-[9px] font-bold uppercase bg-amber-100 text-amber-700">Manual order</span>}
            <span>{row.trucks} truck{row.trucks === 1 ? '' : 's'} · {row.stops} stop{row.stops === 1 ? '' : 's'}</span>
            {created && <span>· {created}</span>}
            {l.saved_by && <span>· {l.saved_by}</span>}
            {l.app_version && <span>· v{l.app_version}</span>}
          </div>
        </button>
      )}
      <div className="flex items-center gap-2 mt-1 text-[11px]">
        <button onClick={() => onOpen(l)} className="underline text-blue-700">Open</button>
        <button onClick={() => setEditing((e) => !e)} className="underline text-slate-600">Rename</button>
        <button onClick={() => onToggleDispatch(l.id, !l.dispatched)} className="underline text-slate-600">{l.dispatched ? 'Un-dispatch' : 'Dispatch'}</button>
        {confirmDel ? (
          <span className="inline-flex items-center gap-1">
            <button onClick={() => onDelete(l.id)} className="underline text-red-700 font-semibold">Confirm</button>
            <button onClick={() => setConfirmDel(false)} className="underline text-slate-500">Cancel</button>
          </span>
        ) : (
          <button onClick={() => setConfirmDel(true)} className="underline text-red-600 ml-auto">Delete</button>
        )}
      </div>
    </div>
  );
}

function fmtRouteDur(sec) {
  if (sec == null || !Number.isFinite(sec)) return '—';
  const h = Math.floor(sec / 3600), m = Math.round((sec % 3600) / 60);
  return h ? `${h}h ${m}m` : `${m}m`;
}

// One truck's route — NUMBERED stops in the CURRENT sequence (matching the map
// markers). On a live build: drag-and-drop or ▲▼ to reorder. When viewing a
// saved load (readOnly), the reorder affordances are hidden (view-only this PR).
function RoutingRouteCard({ rv, stopById, usedGoogle, readOnly, onReorder, onMove, onResequence, hoverId, setHoverId, onOpenStop }) {
  const route = rv.route;
  const rows = rv.order.map((id, idx) => {
    const s = stopById.get(String(id));
    return { seq: idx + 1, stopId: String(id), stop: s, customer: s?.businessName || id, eta: rv.etas?.[idx] ?? null,
      skids: Number(s?.cartons) || 0, pieces: Number(s?.pallets) || 0, weight: Number(s?.weight) || 0 };
  });
  const piecesTotal = rows.reduce((a, r) => a + r.pieces, 0);
  const skidsTotal = rows.reduce((a, r) => a + r.skids, 0);
  const miles = rv.totalDistanceMeters != null ? rv.totalDistanceMeters / 1609.34 : null;
  const lastIdx = rows.length - 1;
  const winViolated = new Set((route?.windowViolatedIds || []).map(String)); // advisory window flags

  const dragFrom = useRef(null);
  const [overIdx, setOverIdx] = useState(null);
  const onDragStart = (i) => (e) => { dragFrom.current = i; e.dataTransfer.effectAllowed = 'move'; try { e.dataTransfer.setData('text/plain', String(i)); } catch { /* some browsers */ } };
  const onDragOver = (i) => (e) => { e.preventDefault(); e.dataTransfer.dropEffect = 'move'; if (overIdx !== i) setOverIdx(i); };
  const onDrop = (i) => (e) => { e.preventDefault(); const from = dragFrom.current; dragFrom.current = null; setOverIdx(null); if (from != null && from !== i) onReorder(rv.truckId, from, i); };
  const onDragEnd = () => { dragFrom.current = null; setOverIdx(null); };

  return (
    <div className="rounded border border-slate-200">
      <div className="px-2 py-1.5 flex items-center gap-2 border-b flex-wrap" style={{ borderLeft: `4px solid ${rv.color}` }}>
        <span className="font-semibold">{route.truckId}</span>
        <span className="text-[11px] text-slate-500">{rows.length} stops · {skidsTotal} skid{skidsTotal === 1 ? '' : 's'} · {piecesTotal} pc{piecesTotal === 1 ? '' : 's'}{miles != null ? ` · ~${miles.toFixed(1)} mi · ~${fmtRouteDur(rv.totalDurationSec)}` : ''}</span>
        {rv.reordered && <span className="text-[9px] font-bold uppercase tracking-wide bg-amber-100 text-amber-700 px-1.5 py-0.5 rounded">Manual order</span>}
        {!readOnly && onResequence && rows.length > 1 && (
          <select
            value=""
            onChange={(e) => { const v = e.target.value; e.target.value = ''; if (v) onResequence(rv.truckId, v); }}
            title="Re-sequence this route"
            className="ml-auto text-[11px] border border-slate-300 rounded px-1 py-0.5 bg-white"
          >
            <option value="">Re-sequence…</option>
            <option value="min">Min distance</option>
            <option value="closest">Closest first</option>
            <option value="farthest">Farthest first</option>
            <option value="reverse">Reverse</option>
          </select>
        )}
      </div>
      <div className="p-2 space-y-1.5">
        <CapacityBar label="Skids" used={route.load.skids} cap={route.capacity.skids} unit="" />
        <CapacityBar label="Weight" used={route.load.weightLbs} cap={route.capacity.weightLbs} unit="lb" />
        <CapacityBar label="Deck" used={route.load.linearFeetIn} cap={route.capacity.linearFeetIn} unit="in" />
      </div>
      {rv.reordered && (
        <div className="px-2 pb-1 text-[10px] text-amber-700">
          Sequence edited — drive times are straight-line estimates{usedGoogle ? ' (original Google road times no longer apply to this order)' : ''}.
        </div>
      )}
      <ul className="divide-y">
        {rows.map((row, i) => {
          const hot = hoverId === row.stopId;
          return (
            <li
              key={row.stopId}
              draggable={!readOnly}
              onDragStart={readOnly ? undefined : onDragStart(i)} onDragOver={readOnly ? undefined : onDragOver(i)} onDrop={readOnly ? undefined : onDrop(i)} onDragEnd={readOnly ? undefined : onDragEnd}
              onMouseEnter={() => setHoverId && setHoverId(row.stopId)}
              onMouseLeave={() => setHoverId && setHoverId((h) => (h === row.stopId ? null : h))}
              className={`flex items-center gap-2 px-2 py-1.5 ${overIdx === i ? 'border-t-2 border-t-blue-500' : ''} ${hot ? 'bg-amber-50' : 'hover:bg-slate-50'}`}
            >
              {!readOnly && <span className="cursor-grab text-slate-400 select-none text-sm leading-none" title="Drag to reorder" aria-hidden>⋮⋮</span>}
              <span className="w-5 h-5 shrink-0 rounded-full text-white text-[10px] font-bold flex items-center justify-center" style={{ background: rv.color }}>{row.seq}</span>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-1.5 min-w-0">
                  <span className="truncate font-medium text-[12px]" title={row.customer}>{row.customer}</span>
                  {row.stop && <span className="shrink-0 text-[10px]"><ProLink stop={row.stop} onOpen={onOpenStop} /></span>}
                </div>
                <div className="text-[10px] text-slate-500">{formatRoutingEta(row.eta)} · {row.skids} sk · {row.pieces} pc · {row.weight.toLocaleString()} lb</div>
                {winViolated.has(row.stopId) && <div className="text-[10px] text-amber-700 font-semibold">⚠ outside appointment window{apptWindowLabel(row.stop) ? ` (${apptWindowLabel(row.stop)})` : ''}</div>}
              </div>
              {!readOnly && (
                <div className="flex flex-col shrink-0">
                  <button onClick={() => onMove(rv.truckId, i, -1)} disabled={i === 0} aria-label={`Move ${row.customer} up`} className="text-slate-500 hover:text-slate-900 disabled:opacity-25 leading-none text-[11px]">▲</button>
                  <button onClick={() => onMove(rv.truckId, i, +1)} disabled={i === lastIdx} aria-label={`Move ${row.customer} down`} className="text-slate-500 hover:text-slate-900 disabled:opacity-25 leading-none text-[11px]">▼</button>
                </div>
              )}
            </li>
          );
        })}
      </ul>
    </div>
  );
}

// ── Quote — embeds the shared Uline rate console as a tab. The console is the single
// source of truth (the @davisdelivery/quote-generator package, cloned from
// DavisDelivery/Quotes at build time); this app just renders it. Its own model/fuel/zone
// data ships inside the package, so no NuVizz calls and no props are required.
function QuoteScreen() {
  return (
    <div className="flex-1 min-h-0 overflow-auto bg-slate-50">
      <React.Suspense fallback={<div className="p-6 text-sm text-slate-500">Loading quote console…</div>}>
        <UlineQuoteConsole embedded />
      </React.Suspense>
    </div>
  );
}

// ---------- Routing → Engine tab (learned routing engine, Phase 1 shadow) ----------
//
// SHADOW ONLY. Every night the engine re-sequences the routes dispatch
// actually built (constraints learned from our own route history), scores its
// sequence against the dispatcher's with the official Amazon/MIT challenge
// metric (0 = routed it exactly like dispatch), and this tab shows the
// results: scoreboard, learning-curve trend, per-route table, and a
// Dispatch / Engine / Diff map. It reads route_proposals +
// route_proposals_daily through one read-only endpoint — no NuVizz calls, no
// polling, and it changes NOTHING about live plan data (write-back is
// Phase 2+, which is why Assist and Auto are visible but locked).

const ENGINE_VERSION_FALLBACK = '2.1.0'; // display fallback until data loads (server stamps the real one)

const ENGINE_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
function engineMonthLabel(date) {
  // 'YYYY-MM-DD' → "Jul '26" — pure string math, no Date parsing (no TZ shift).
  return `${ENGINE_MONTHS[Number(date.slice(5, 7)) - 1]} '${date.slice(2, 4)}`;
}
function engineScoreFmt(v) {
  return v == null || Number.isNaN(Number(v)) ? '—' : Number(v).toFixed(3);
}
function engineDeltaFmt(v) {
  if (v == null || Number.isNaN(Number(v))) return '—';
  const n = Number(v);
  return `${n > 0 ? '+' : ''}${n.toFixed(1)}m`;
}
function engineDateFmt(date) {
  // 'YYYY-MM-DD' → "Jul 10, 2026" (house rule: month-name dates, no TZ parsing)
  if (!date || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return date || '—';
  return `${ENGINE_MONTHS[Number(date.slice(5, 7)) - 1]} ${Number(date.slice(8, 10))}, ${date.slice(0, 4)}`;
}
function engineDayShort(date) {
  // 'YYYY-MM-DD' → "Jul 3" (no Date parse, no TZ shift)
  if (!date || date.length < 10) return date || '';
  return `${ENGINE_MONTHS[Number(date.slice(5, 7)) - 1]} ${Number(date.slice(8, 10))}`;
}
// Readable x-axis for the daily trend charts. A month-boundary axis (one tick
// per month) is only legible once the data spans several months; early on every
// scored day lands in ONE month, so that logic collapses to a single lonely
// label — which reads as "no dates on the axis". This falls back to evenly
// spaced "Mon D" day labels (≤6, so they never collide) whenever the window is
// one or two months, and only switches to month labels for longer spans.
function engineAxisTicks(pts) {
  if (!pts.length) return [];
  const months = new Set(pts.map((d) => d.date.slice(0, 7)));
  if (months.size >= 3) {
    const ticks = []; let last = '';
    pts.forEach((d, i) => { const m = d.date.slice(0, 7); if (m !== last) { ticks.push({ i, label: engineMonthLabel(d.date) }); last = m; } });
    return ticks;
  }
  const n = pts.length;
  const count = Math.min(6, n);
  const ticks = []; const seen = new Set();
  for (let k = 0; k < count; k += 1) {
    const i = count <= 1 ? 0 : Math.round((k * (n - 1)) / (count - 1));
    if (seen.has(i)) continue;
    seen.add(i);
    ticks.push({ i, label: engineDayShort(pts[i].date) });
  }
  return ticks;
}

// Daily mean + median trend — the watch-it-learn instrument. Hand-rolled SVG
// (house style: no chart lib), evenly spaced by scored day, month labels on
// the axis, dots carry the exact values as tooltips.
function EngineTrendChart({ days }) {
  const W = 640, H = 170, PAD_L = 34, PAD_R = 8, PAD_T = 10, PAD_B = 22;
  const pts = (days || []).filter((d) => d.mean_score != null);
  if (pts.length < 2) {
    return <div className="h-[120px] flex items-center justify-center text-xs text-slate-400">Not enough scored days yet — the trend appears after the historical replay runs.</div>;
  }
  // The GUIDED mean is the real learning curve (routes the engine had a learned
  // reference for); the blended "all" mean rides up and down with how many
  // UNGUIDED routes ran that day, so it isn't a clean performance read. Plot
  // guided as the headline line and keep "all" as faint context.
  const maxY = Math.max(0.05, ...pts.map((d) => Math.max(d.mean_score ?? 0, d.mean_score_guided ?? 0))) * 1.1;
  const x = (i) => PAD_L + (i * (W - PAD_L - PAD_R)) / (pts.length - 1);
  const y = (v) => PAD_T + (H - PAD_T - PAD_B) * (1 - v / maxY);
  const line = (key) => pts.map((d, i) => `${x(i).toFixed(1)},${y(d[key] ?? 0).toFixed(1)}`).join(' ');
  // guided line: only the days that actually carry a guided mean, so pre-2.1
  // scored days (no guided field) don't drop the line to zero.
  const guidedPts = pts.map((d, i) => ({ i, d, v: d.mean_score_guided })).filter((p) => p.v != null);
  const guidedLine = guidedPts.map((p) => `${x(p.i).toFixed(1)},${y(p.v).toFixed(1)}`).join(' ');
  // month labels for a multi-month span, else evenly spaced day labels so a
  // single-month window still shows real dates on the axis.
  const monthTicks = engineAxisTicks(pts);
  const gridVals = [0, maxY / 2, maxY];
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="w-full h-auto" role="img" aria-label="Daily engine guided-score trend">
      {gridVals.map((v, k) => (
        <g key={k}>
          <line x1={PAD_L} y1={y(v)} x2={W - PAD_R} y2={y(v)} stroke="#e2e8f0" strokeWidth="1" />
          <text x={PAD_L - 4} y={y(v) + 3} fontSize="9" fill="#94a3b8" textAnchor="end">{v.toFixed(2)}</text>
        </g>
      ))}
      {monthTicks.map((t) => (
        <text key={t.i} x={x(t.i)} y={H - 6} fontSize="9" fill="#64748b" textAnchor={t.i === 0 ? 'start' : x(t.i) > W - 30 ? 'end' : 'middle'}>{t.label}</text>
      ))}
      {/* blended "all" mean — faint context (dilutes with unguided mix) */}
      <polyline points={line('mean_score')} fill="none" stroke="#94a3b8" strokeWidth="1.5" strokeDasharray="4 3" />
      {/* guided mean — the headline learning curve */}
      {guidedPts.length >= 2 && <polyline points={guidedLine} fill="none" stroke={BRAND} strokeWidth="2.25" />}
      {guidedPts.map((p) => (
        <circle key={p.d.date} cx={x(p.i)} cy={y(p.v)} r="2.4" fill={BRAND}>
          <title>{`${p.d.date} — guided ${engineScoreFmt(p.d.mean_score_guided)} · all ${engineScoreFmt(p.d.mean_score)} · median ${engineScoreFmt(p.d.median_score)} · ${p.d.routes_scored} routes${p.d.unguided_count ? ` (${p.d.unguided_count} unguided)` : ''}`}</title>
        </circle>
      ))}
      <g fontSize="9">
        <line x1={W - 150} y1={12} x2={W - 132} y2={12} stroke={BRAND} strokeWidth="2.25" />
        <text x={W - 128} y={15} fill="#475569">guided</text>
        <line x1={W - 84} y1={12} x2={W - 66} y2={12} stroke="#94a3b8" strokeWidth="1.5" strokeDasharray="4 3" />
        <text x={W - 62} y={15} fill="#475569">all</text>
      </g>
    </svg>
  );
}

// The three-way mode switch. Shadow is live; Assist and Auto ship with
// Phase 2 (assignment layer + write-back) and are rendered but locked.
function EngineModeSwitch() {
  const modes = [
    { id: 'shadow', label: 'Shadow', enabled: true },
    { id: 'assist', label: 'Assist', enabled: false },
    { id: 'auto', label: 'Auto', enabled: false },
  ];
  return (
    <div className="flex items-center rounded-lg border border-slate-200 overflow-hidden text-[11px] font-semibold">
      {modes.map((m) => m.enabled ? (
        <button key={m.id} className="px-2.5 py-1 text-white" style={{ background: BRAND }} title="Shadow mode — the engine proposes and scores; it changes nothing.">
          {m.label}
        </button>
      ) : (
        <button key={m.id} disabled className="px-2.5 py-1 text-slate-400 bg-slate-50 cursor-not-allowed inline-flex items-center gap-1" title={`${m.label} arrives with Phase 2 (write-back). Shadow only for now.`}>
          {m.label}
          <span className="text-[8px] uppercase tracking-wide bg-slate-200 text-slate-500 px-1 rounded">P2</span>
        </button>
      ))}
    </div>
  );
}

function EngineStatTile({ label, value, hint }) {
  return (
    <div className="border rounded-lg bg-white px-3 py-2 min-w-[108px]" title={hint || ''}>
      <div className="text-[10px] uppercase tracking-wide text-slate-500">{label}</div>
      <div className="text-lg font-bold text-slate-800 tabular-nums">{value}</div>
    </div>
  );
}

// "How to read this" — the page's own legend. Chad, on the plan-vs-engine screen: "that page
// needs a legend so someone knows how to interpret what they are looking at on the map."
//
// It is not a nicety. Every number here is a COMPARISON between two things — what the engine
// proposes and what dispatch actually ran — and the screen was labelling those "E/A". Reading
// a driver's "11/20" as the engine loading someone with 20 stops, when 20 is what dispatch ran
// and 11 is the engine's answer, inverts the meaning of the whole page. Collapsed by default so
// it costs nothing once you know it; the state sticks per device.
function EngineHowToRead() {
  const [open, setOpen] = useState(() => {
    try { return localStorage.getItem('engine.howto') !== 'closed'; } catch { return true; }
  });
  useEffect(() => {
    try { localStorage.setItem('engine.howto', open ? 'open' : 'closed'); } catch { /* private mode */ }
  }, [open]);
  const Row = ({ term, children }) => (
    <div className="flex gap-2 py-0.5">
      <div className="w-[124px] shrink-0 font-semibold text-slate-600">{term}</div>
      <div className="min-w-0 text-slate-600">{children}</div>
    </div>
  );
  return (
    <div className="border rounded-lg bg-white p-2">
      <button onClick={() => setOpen((v) => !v)}
        className="w-full flex items-center justify-between text-[11px] font-semibold text-slate-600 px-1 pb-1">
        <span>How to read this page</span>
        <span className="text-slate-400 ml-2 shrink-0">{open ? '▾ hide' : '▸ show'}</span>
      </button>
      {open && (
        <div className="px-1 pb-1 text-[11px] leading-snug">
          <div className="text-slate-700 font-semibold pb-1">
            Nothing on this page changes a route. It replays a past day and asks what the engine
            would have done instead.
          </div>
          <Row term="eng / disp">
            Every paired number is <b>engine first, dispatch second</b>. “11/20” is the engine
            proposing 11 stops for a driver who actually ran 20 — never the other way round.
          </Row>
          <Row term="Routes table">
            One row per route <b>dispatch actually built</b>. Its Stops and Zones are theirs; the
            engine only re-sequenced them.
          </Row>
          <Row term="Score">
            0–1, how closely the engine’s ORDER for that same route matches the order dispatch
            drove. 1.0 is identical. A low score is a disagreement, not an error.
          </Row>
          <Row term="Travel Δ">
            Estimated driving minutes, engine minus dispatch, same distance model both sides.
            <b> Negative is the engine saving time.</b>
          </Row>
          <Row term="Guided">
            The engine found a similar route in history to learn the shape from.
            <b> Unguided</b> means it had no example and worked from clustering alone — read
            those separately, they are a harder problem.
          </Row>
          <Row term="Agree %">
            Share of that driver’s stops the engine put on the same driver as dispatch.
          </Row>
          <Row term="Map · Dispatch">One colour per driver, drawn in true delivery order.</Row>
          <Row term="Map · Engine">The proposal. Solid = trip 1, dotted = trip 2 or later.</Row>
          <Row term="Map · Diff">
            Both at once. The wide grey sleeve is <b>ORIGINAL — what dispatch ran</b>; the narrow
            coloured line inside it is <b>NEW — the engine</b>. Where they run together the plans
            agree; where the grey peels away they don’t. One line per trip on each side, each
            starting from the warehouse — a driver with two trips has two lines, so a long leg
            back across town is the truck reloading, not a mistake.
          </Row>
          <Row term="Amber pins">
            Stops the engine would give to a <b>different driver</b>. Listed under the map.
          </Row>
        </div>
      )}
    </div>
  );
}

// Live engine tuning — reads/writes routing_engine_config through the
// routing-engine-tuning function (clamped server-side by the same pure helpers
// the solver uses, so a bad value can never persist). Edits take effect on the
// NEXT nightly run automatically; "Re-score history" force-replays the scored
// days with the current settings (Firestore-only, zero NuVizz).
const ENGINE_TUNING_FIELDS = [
  ['far_deadhead_mi', 'Far threshold (miles from Buford)', 'Stops beyond this distance count as "far" — every rule below applies only out there.'],
  ['w_zone_cohesion', 'Extra truck in a far area', 'Charged per ADDITIONAL truck serving one far area, and it grows with distance — the ends of the roads get the fewest trucks possible. Raise to consolidate harder.'],
  ['w_zone_owner', 'Territory ownership', 'Cost of giving a far stop to a driver who does not own that area (owners are learned from route history — e.g. Dalton = Scott + Victor).'],
  ['w_far_deadhead', 'Reaching-out penalty', 'One-time charge for a truck reaching past the far threshold, growing with depth — makes a second truck out far expensive while more stops on the first are ~free.'],
  ['habit_far_discount', 'Usual-driver pull on far stops (0–1)', 'How much a customer’s usual driver counts OUT FAR. 1 = full pull (scatters far loops), lower lets geography win. Near-Buford stops always keep the full pull.'],
  ['zone_owner_min_share', 'Ownership share floor (0–1)', 'A driver owns an area once they carry at least this share of its historical stops.'],
  ['zone_owner_min_obs', 'Ownership history minimum', 'An area needs this many observed stops before ownership locks in — keeps thin data from claiming territory.'],
];
function EngineTuningPanel({ onClose }) {
  const [data, setData] = useState(null);
  const [err, setErr] = useState('');
  const [edits, setEdits] = useState({});     // key → string (input value)
  const [resets, setResets] = useState([]);   // keys being reset to default
  const [saving, setSaving] = useState(false);
  const [note, setNote] = useState('');

  const load = () => fetchJsonWithRetry('/.netlify/functions/routing-engine-tuning')
    .then((d) => { if (!d?.ok) throw new Error(d?.error || 'tuning load failed'); setData(d); setEdits({}); setResets([]); })
    .catch((e) => setErr(String(e?.message || e)));
  useEffect(() => { load(); }, []);

  const numericKeys = data ? Object.keys(data.bounds || {}) : [];
  const advancedKeys = numericKeys.filter((k) => !ENGINE_TUNING_FIELDS.some(([key]) => key === k)).sort();
  const effVal = (k) => (resets.includes(k) ? data.defaults[k] : (edits[k] !== undefined ? edits[k] : data.config[k]));
  const isOverridden = (k) => data.stored && data.stored[k] !== undefined && !resets.includes(k);
  const dirty = Object.keys(edits).length > 0 || resets.length > 0;

  const save = async () => {
    setSaving(true); setErr(''); setNote('');
    try {
      const body = { updatedBy: 'engine-tab', reset: resets };
      for (const [k, v] of Object.entries(edits)) { const n = Number(v); if (Number.isFinite(n)) body[k] = n; }
      const resp = await fetch('/.netlify/functions/routing-engine-tuning', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
      });
      const d = await resp.json();
      if (!d?.ok) throw new Error(d?.error || 'save failed');
      setData(d); setEdits({}); setResets([]);
      setNote('Saved. Tonight’s run uses these automatically — tap “Re-score history” to re-run the past days with them now.');
    } catch (e) { setErr(String(e?.message || e)); }
    setSaving(false);
  };

  const rescore = async () => {
    if (!window.confirm('Re-score history with the CURRENT settings? Runs in the background (~12 min per pass, zero NuVizz). One pass covers about a week of days and then saves its place — tap again to continue from there until the whole window is done.')) return;
    setNote('');
    try {
      await fetch('/.netlify/functions/routing-engine-plan-replay-background?force=1', { method: 'POST' });
      setNote('Re-score started. Give it ~12 minutes, then refresh the Assignment view — each pass picks up where the last one stopped, so keep tapping until the oldest days stop changing.');
    } catch (e) { setErr(String(e?.message || e)); }
  };

  const row = (k, label, hint) => {
    const [lo, hi] = data.bounds[k] || [null, null];
    return (
      <div key={k} className="py-1.5 border-b border-slate-100 last:border-b-0">
        <div className="flex items-center justify-between gap-2">
          <div className="min-w-0">
            <span className="text-[12px] font-semibold text-slate-700">{label || k}</span>
            {isOverridden(k) && <span className="ml-1.5 text-[9px] font-semibold uppercase tracking-wide bg-amber-100 text-amber-700 px-1 py-0.5 rounded align-middle">customized</span>}
          </div>
          <div className="flex items-center gap-1 shrink-0">
            <input
              type="number" step="any" min={lo ?? undefined} max={hi ?? undefined}
              value={effVal(k)}
              onChange={(e) => { setResets((r) => r.filter((x) => x !== k)); setEdits((m) => ({ ...m, [k]: e.target.value })); }}
              className="w-24 text-right text-[12px] border border-slate-300 rounded px-1.5 py-0.5 tabular-nums focus:outline-none focus:ring-2 focus:ring-blue-200"
              aria-label={label || k}
            />
            {(isOverridden(k) || edits[k] !== undefined) && (
              <button onClick={() => { setEdits((m) => { const n = { ...m }; delete n[k]; return n; }); if (data.stored[k] !== undefined) setResets((r) => (r.includes(k) ? r : [...r, k])); }}
                className="text-[10px] text-slate-400 hover:text-slate-600" title={`Back to the default (${data.defaults[k]})`}>↺</button>
            )}
          </div>
        </div>
        {hint && <div className="text-[10px] text-slate-500 pr-8">{hint} <span className="text-slate-400">default {data.defaults[k]}{lo != null ? ` · range ${lo}–${hi}` : ''}</span></div>}
      </div>
    );
  };

  return (
    <div className="fixed inset-0 z-[70] bg-black/40 flex items-start justify-center p-3 overflow-y-auto" onClick={onClose}>
      <div className="bg-white rounded-xl shadow-xl w-full max-w-xl mt-6 mb-10" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between px-4 pt-3 pb-2 border-b">
          <div>
            <div className="font-bold text-slate-800 text-sm">Engine tuning <span className="text-[10px] uppercase tracking-wide bg-amber-100 text-amber-700 px-1.5 py-0.5 rounded ml-1">live</span></div>
            <div className="text-[10px] text-slate-500">Saved values apply from tonight’s run — no deploy. Everything is clamped to a safe range; “customized” marks values changed from the default.</div>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 text-lg leading-none px-1" aria-label="Close">×</button>
        </div>
        <div className="px-4 py-2 max-h-[60vh] overflow-y-auto">
          {err && <div className="text-xs text-red-600 border border-red-200 bg-red-50 rounded p-2 mb-2">⚠ {err}</div>}
          {!data && !err && <div className="text-xs text-slate-500 py-4">Loading current settings…</div>}
          {data && (
            <>
              {!data.persistent && <div className="text-[11px] text-amber-700 bg-amber-50 border border-amber-200 rounded p-2 mb-2">Preview environment — edits here won’t persist.</div>}
              <div className="text-[10px] uppercase tracking-wide text-slate-500 pt-1">Far routes &amp; territory</div>
              {ENGINE_TUNING_FIELDS.map(([k, label, hint]) => row(k, label, hint))}
              <details className="mt-2">
                <summary className="text-[11px] font-semibold text-slate-500 cursor-pointer select-none">Advanced ({advancedKeys.length} more settings)</summary>
                {advancedKeys.map((k) => row(k, k, null))}
              </details>
              {data.stored?.updated_at && (
                <div className="text-[10px] text-slate-400 pt-2">Last saved {data.stored.updated_at.slice(0, 16).replace('T', ' ')} by {data.stored.updated_by || '—'}</div>
              )}
            </>
          )}
        </div>
        <div className="flex items-center justify-between gap-2 px-4 py-3 border-t flex-wrap">
          <button onClick={rescore} disabled={!data}
            className="text-[11px] font-semibold py-1.5 px-2.5 rounded border border-slate-300 text-slate-600 bg-white hover:bg-slate-50"
            title="Force-replay all scored days with the current settings (background, zero NuVizz)">↻ Re-score history</button>
          <div className="flex items-center gap-2">
            {note && <span className="text-[10px] text-emerald-700 max-w-[220px]">{note}</span>}
            <button onClick={save} disabled={!dirty || saving}
              className={`text-[11px] font-semibold py-1.5 px-3 rounded text-white ${dirty && !saving ? '' : 'opacity-40'}`}
              style={{ background: BRAND }}>{saving ? 'Saving…' : 'Save'}</button>
          </div>
        </div>
      </div>
    </div>
  );
}

function EngineScreen() {
  const { google, error: mapsError } = useGoogleMaps();
  const [daily, setDaily] = useState(null);
  const [dailyErr, setDailyErr] = useState('');
  const [date, setDate] = useState('');
  const [day, setDay] = useState(null);
  const [dayLoading, setDayLoading] = useState(false);
  const [dayErr, setDayErr] = useState('');
  const [selectedKey, setSelectedKey] = useState(null);
  const [mapMode, setMapMode] = useState('diff'); // 'dispatch' | 'engine' | 'diff'
  const [engineView, setEngineView] = useState('sequencing'); // 'sequencing' | 'assignment'
  const [tuningOpen, setTuningOpen] = useState(false);

  const days = daily?.days || [];
  const latestDate = days.length ? days[days.length - 1].date : '';
  const engineVersion = daily?.engine_version || ENGINE_VERSION_FALLBACK;

  useEffect(() => {
    fetchJsonWithRetry('/.netlify/functions/routing-engine-data?view=daily')
      .then((d) => {
        if (!d?.ok) throw new Error(d?.error || 'engine data unavailable');
        setDaily(d);
        const ds = d.days || [];
        if (ds.length) setDate(ds[ds.length - 1].date);
      })
      .catch((e) => setDailyErr(String(e?.message || e)));
  }, []);

  useEffect(() => {
    if (!date) return;
    let alive = true;
    setDayLoading(true); setDayErr(''); setDay(null); setSelectedKey(null);
    fetchJsonWithRetry(`/.netlify/functions/routing-engine-data?view=day&date=${date}`)
      .then((d) => {
        if (!alive) return;
        if (!d?.ok) throw new Error(d?.error || 'day load failed');
        setDay(d);
        if (d.routes?.length) setSelectedKey(d.routes[0].load_key);
      })
      .catch((e) => { if (alive) setDayErr(String(e?.message || e)); })
      .finally(() => { if (alive) setDayLoading(false); });
    return () => { alive = false; };
  }, [date]);

  const rollup = day?.rollup || null;
  const routes = day?.routes || [];
  const selected = routes.find((r) => r.load_key === selectedKey) || null;

  // sortable routes table
  const [routeQuery, setRouteQuery] = useState('');
  const tableRows = useMemo(() => routes.map((r) => ({
    load_key: r.load_key,
    driver: r.driver_name || r.driver_user_name || '—',
    truck_class: r.truck_class || '—',
    stops: r.stop_count,
    zones: r.zones_count,
    score: r.score,
    delta: Math.round(((r.travel_min_proposed_est ?? 0) - (r.travel_min_actual_est ?? 0)) * 10) / 10,
    guided: r.unguided ? 'Unguided' : 'Guided',
    reference_date: r.reference_date || '—',
  })), [routes]);
  // free-text filter over route/load id, driver, and truck class (case-insensitive)
  const filteredRows = useMemo(() => {
    const q = routeQuery.trim().toLowerCase();
    if (!q) return tableRows;
    return tableRows.filter((r) =>
      String(r.load_key).toLowerCase().includes(q) ||
      String(r.driver).toLowerCase().includes(q) ||
      String(r.truck_class).toLowerCase().includes(q)
    );
  }, [tableRows, routeQuery]);
  const { sorted: sortedRows, sortKey, sortDir, toggle } = useSortable(filteredRows, 'score', 'desc');

  // moved stops for the Diff side list (position shifted by more than 2)
  const movedStops = useMemo(() => {
    if (!selected) return [];
    return (selected.stops || [])
      .filter((s) => s.proposed_pos != null && Math.abs(s.actual_pos - s.proposed_pos) > 2)
      .sort((a, b) => Math.abs(b.actual_pos - b.proposed_pos) - Math.abs(a.actual_pos - a.proposed_pos));
  }, [selected]);
  const movedSet = useMemo(() => new Set(movedStops.map((s) => s.pro)), [movedStops]);

  // ── map ──
  const mapDiv = useRef(null);
  const mapRef = useRef(null);
  const [mapReady, setMapReady] = useState(0);
  const markersRef = useRef([]);
  const linesRef = useRef([]);
  const lastBoundsRef = useRef(null); // last fitted bounds, so a resize can refit

  useEffect(() => {
    if (!google || !mapDiv.current || mapRef.current) return;
    mapRef.current = new google.maps.Map(mapDiv.current, {
      center: ROUTING_DEPOT, zoom: 9, mapTypeControl: false, streetViewControl: false, fullscreenControl: false,
      gestureHandling: 'greedy',
      ...(MAP_ID ? { mapId: MAP_ID } : {}),
    });
    setMapReady((n) => n + 1);
  }, [google]);

  useEffect(() => {
    if (!google || !mapRef.current) return;
    markersRef.current.forEach((m) => m.setMap(null));
    linesRef.current.forEach((l) => l.setMap(null));
    markersRef.current = []; linesRef.current = [];
    if (!selected) return;

    const stops = (selected.stops || []).filter((s) => s.lat != null && s.lng != null);
    if (!stops.length) return;
    const byActual = [...stops].sort((a, b) => a.actual_pos - b.actual_pos);
    const byProposed = [...stops].filter((s) => s.proposed_pos != null).sort((a, b) => a.proposed_pos - b.proposed_pos);
    const depotPt = { lat: ROUTING_DEPOT.lat, lng: ROUTING_DEPOT.lng };
    const path = (ordered) => [depotPt, ...ordered.map((s) => ({ lat: s.lat, lng: s.lng }))];

    const DISPATCH_COLOR = '#64748b';
    const ENGINE_COLOR = BRAND;
    const MOVED_COLOR = '#d97706';

    const addLine = (ordered, color, weight, opacity, z) => {
      const pl = new google.maps.Polyline({ path: path(ordered), strokeColor: color, strokeWeight: weight, strokeOpacity: opacity, zIndex: z });
      pl.setMap(mapRef.current);
      linesRef.current.push(pl);
    };
    const addPins = (ordered, posOf, colorOf) => {
      for (const s of ordered) {
        const mk = new google.maps.Marker({
          position: { lat: s.lat, lng: s.lng },
          map: mapRef.current,
          icon: {
            url: circleMarkerSvg(colorOf(s), { label: String(posOf(s)) }),
            scaledSize: new google.maps.Size(30, 30),
            anchor: new google.maps.Point(15, 15),
          },
          title: `${s.businessName || s.pro} — dispatch #${s.actual_pos}${s.proposed_pos != null ? `, engine #${s.proposed_pos}` : ''}`,
          zIndex: 20,
        });
        markersRef.current.push(mk);
      }
    };

    if (mapMode === 'dispatch') {
      addLine(byActual, DISPATCH_COLOR, 3, 0.9, 5);
      addPins(byActual, (s) => s.actual_pos, () => DISPATCH_COLOR);
    } else if (mapMode === 'engine') {
      addLine(byProposed, ENGINE_COLOR, 3, 0.9, 5);
      addPins(byProposed, (s) => s.proposed_pos, () => ENGINE_COLOR);
    } else {
      // Diff: dispatch muted underneath, engine bold on top; pins numbered by the
      // ENGINE order, stops the engine moved by >2 positions in amber.
      addLine(byActual, DISPATCH_COLOR, 2.5, 0.45, 4);
      addLine(byProposed, ENGINE_COLOR, 4, 0.9, 6);
      addPins(byProposed, (s) => s.proposed_pos, (s) => (movedSet.has(s.pro) ? MOVED_COLOR : ENGINE_COLOR));
    }

    const bounds = new google.maps.LatLngBounds();
    bounds.extend(depotPt);
    for (const s of stops) bounds.extend({ lat: s.lat, lng: s.lng });
    lastBoundsRef.current = bounds;
    mapRef.current.fitBounds(bounds, 40);
  }, [google, mapReady, selected, mapMode, movedSet]);

  // Google Maps paints solid gray until it's told its container has a real size.
  // This map is created inside a tab/flex layout whose final size can settle a
  // frame AFTER the map exists, and it has no other resize trigger — so a
  // ResizeObserver refires a resize + refit the moment the container gets a
  // non-zero size (and on every later resize), which is what stops the tiles
  // from staying blank.
  useEffect(() => {
    if (!google || !mapDiv.current) return undefined;
    const el = mapDiv.current;
    const kick = () => {
      if (!mapRef.current || !el.offsetWidth || !el.offsetHeight) return;
      google.maps.event.trigger(mapRef.current, 'resize');
      const b = lastBoundsRef.current;
      if (b && !b.isEmpty()) mapRef.current.fitBounds(b, 40);
    };
    const ro = new ResizeObserver(kick);
    ro.observe(el);
    return () => ro.disconnect();
  }, [google, mapReady]);

  const mapModeBtn = (id, label) => (
    <button
      key={id}
      onClick={() => setMapMode(id)}
      className={`px-2 py-1 text-[11px] font-semibold rounded ${mapMode === id ? 'text-white' : 'text-slate-600 bg-white border border-slate-200 hover:bg-slate-50'}`}
      style={mapMode === id ? { background: BRAND } : {}}
    >{label}</button>
  );

  return (
    <div className="flex-1 min-h-0 overflow-y-auto bg-slate-50">
      <div className="max-w-[1900px] mx-auto p-3 space-y-3 text-sm">
        {/* header */}
        <div className="flex items-center justify-between gap-2 flex-wrap">
          <div className="flex items-center gap-2 flex-wrap">
            <div className="font-bold text-slate-800">Engine <span className="text-[10px] uppercase tracking-wide bg-amber-100 text-amber-700 px-1.5 py-0.5 rounded">shadow</span></div>
            {/* Sequencing (Phase 1) | Assignment (Phase 2) */}
            <div className="flex items-center rounded-lg border border-slate-200 overflow-hidden text-[11px] font-semibold">
              {[['sequencing', 'Sequencing'], ['assignment', 'Assignment']].map(([id, label]) => (
                <button key={id} onClick={() => setEngineView(id)}
                  className={`px-2.5 py-1 ${engineView === id ? 'text-white' : 'text-slate-600 bg-white hover:bg-slate-50'}`}
                  style={engineView === id ? { background: BRAND } : {}}>{label}</button>
              ))}
            </div>
            <EngineModeSwitch />
          </div>
          <div className="flex items-center gap-2 flex-wrap">
            {engineView === 'sequencing' && (
              <>
                <input
                  type="date"
                  value={date}
                  onChange={(e) => { if (e.target.value) setDate(e.target.value); }}
                  className="text-xs border border-slate-300 rounded px-1.5 py-1 focus:outline-none focus:ring-2 focus:ring-blue-200 focus:border-blue-400"
                  aria-label="Select scored date"
                />
                {date !== latestDate && latestDate && (
                  <button
                    onClick={() => setDate(latestDate)}
                    className="text-[10px] font-semibold py-1 px-2 rounded border border-blue-300 text-blue-700 bg-white hover:bg-blue-50 whitespace-nowrap"
                    title="Jump to the most recent scored date"
                  >Latest</button>
                )}
              </>
            )}
            <button
              onClick={() => setTuningOpen(true)}
              className="text-[10px] font-semibold py-1 px-2 rounded border border-slate-300 text-slate-600 bg-white hover:bg-slate-50 whitespace-nowrap"
              title="Tune the engine's live settings — takes effect on the next nightly run, no deploy"
            >⚙ Tuning</button>
            <span className="text-[10px] text-slate-500 whitespace-nowrap">Engine v{engineVersion} · App v{APP_VERSION}</span>
          </div>
        </div>

        {tuningOpen && <EngineTuningPanel onClose={() => setTuningOpen(false)} />}

        {engineView === 'assignment' && <EngineAssignmentView google={google} mapsError={mapsError} />}
        {engineView === 'sequencing' && (<div className="space-y-3">

        {dailyErr && <div className="text-xs text-red-600 border border-red-200 bg-red-50 rounded p-2">⚠ {dailyErr}</div>}
        {!daily && !dailyErr && <div className="text-xs text-slate-500">Loading engine history…</div>}
        {daily && !days.length && (
          <div className="text-xs text-slate-600 border rounded bg-white p-3">
            No scored dates yet. Run the reference backfill, then the historical replay (routing-engine-replay-background) — the trend fills in from there and the nightly shadow keeps it current.
          </div>
        )}

        {/* scoreboard for the selected date */}
        {rollup && (
          <div className="flex gap-2 flex-wrap">
            <EngineStatTile label="Routes scored" value={rollup.routes_scored ?? '—'} hint={`${rollup.routes_skipped ?? 0} skipped by the miner rules`} />
            <EngineStatTile label="Guided mean" value={engineScoreFmt(rollup.mean_score_guided ?? null)} hint="Routes with a learned reference — the headline: 0 means the engine routed it exactly like dispatch" />
            <EngineStatTile label="Unguided mean" value={engineScoreFmt(rollup.mean_score_unguided ?? null)} hint="Routes with NO similar historical reference (clustering + hierarchy only) — the engine had no teacher; read separately, never blended" />
            <EngineStatTile label="Mean (all)" value={engineScoreFmt(rollup.mean_score)} hint="Blended mean across guided + unguided — kept for continuity with older scored days" />
            <EngineStatTile label="Median (all)" value={engineScoreFmt(rollup.median_score)} />
            <EngineStatTile label="Travel Δ (engine − dispatch)" value={engineDeltaFmt(rollup.mean_travel_delta_min)} hint="Estimated minutes, same haversine model for both sequences — negative means the engine's order is shorter" />
            <EngineStatTile label="Unguided" value={rollup.unguided_count ?? 0} hint="Count of routes with no similar historical reference" />
          </div>
        )}

        {/* trend */}
        <div className="border rounded-lg bg-white p-2">
          <div className="text-[11px] font-semibold text-slate-600 px-1 pb-1">Daily similarity — watching the engine learn · <span style={{ color: BRAND }}>guided</span> = routes with a learned reference (the real learning curve); lower is closer to dispatch</div>
          <EngineTrendChart days={days} />
        </div>

        {/* routes table + map */}
        <div className="flex flex-col xl:flex-row gap-3 items-stretch">
          <div className="xl:w-[54%] border rounded-lg bg-white overflow-hidden flex flex-col">
            <div className="flex items-center justify-between gap-2 px-3 pt-2 pb-1">
              <div className="text-[11px] font-semibold text-slate-600 min-w-0 truncate">
                Routes {date ? `— ${formatDateLong(date)}` : ''}{dayLoading ? ' · loading…' : ''}{dayErr ? ` · ⚠ ${dayErr}` : ''}{routeQuery.trim() ? ` · ${filteredRows.length} of ${tableRows.length}` : ''}
              </div>
              <input
                type="search"
                value={routeQuery}
                onChange={(e) => setRouteQuery(e.target.value)}
                placeholder="Filter route / driver…"
                aria-label="Filter routes by route, load, or driver"
                className="shrink-0 w-40 text-[11px] border border-slate-300 rounded px-2 py-1 focus:outline-none focus:ring-2 focus:ring-blue-200 focus:border-blue-400"
              />
            </div>
            <div className="overflow-x-auto overflow-y-auto max-h-[420px]">
              <table className="w-full text-xs">
                <thead className="bg-slate-50 sticky top-0">
                  <tr>
                    <SortableTh label="Route / load" k="load_key" sortKey={sortKey} sortDir={sortDir} onToggle={toggle} />
                    <SortableTh label="Driver" k="driver" sortKey={sortKey} sortDir={sortDir} onToggle={toggle} />
                    <SortableTh label="Class" k="truck_class" sortKey={sortKey} sortDir={sortDir} onToggle={toggle} />
                    {/* This table scores the routes DISPATCH BUILT — the stop count is theirs,
                        not a proposal. Named so, because a bare "Stops" next to a score reads
                        like the engine is the one handing out 21-stop routes. */}
                    <SortableTh label="Stops (dispatch)" k="stops" sortKey={sortKey} sortDir={sortDir} onToggle={toggle} />
                    <SortableTh label="Zones" k="zones" sortKey={sortKey} sortDir={sortDir} onToggle={toggle} />
                    <SortableTh label="Score" k="score" sortKey={sortKey} sortDir={sortDir} onToggle={toggle} />
                    <SortableTh label="Travel Δ" k="delta" sortKey={sortKey} sortDir={sortDir} onToggle={toggle} />
                    <SortableTh label="Guided" k="guided" sortKey={sortKey} sortDir={sortDir} onToggle={toggle} />
                    <SortableTh label="Ref date" k="reference_date" sortKey={sortKey} sortDir={sortDir} onToggle={toggle} />
                  </tr>
                </thead>
                <tbody>
                  {sortedRows.map((r) => (
                    <tr
                      key={r.load_key}
                      onClick={() => setSelectedKey(r.load_key)}
                      className={`cursor-pointer border-t ${selectedKey === r.load_key ? 'bg-blue-50' : 'hover:bg-slate-50'}`}
                    >
                      <td className="px-2 py-1 font-semibold text-slate-800">{r.load_key}</td>
                      <td className="px-2 py-1">{r.driver}</td>
                      <td className="px-2 py-1">{r.truck_class}</td>
                      <td className="px-2 py-1 tabular-nums">{r.stops}</td>
                      <td className="px-2 py-1 tabular-nums">{r.zones}</td>
                      <td className="px-2 py-1 tabular-nums font-semibold">{engineScoreFmt(r.score)}</td>
                      <td className={`px-2 py-1 tabular-nums ${r.delta < 0 ? 'text-emerald-700' : r.delta > 0 ? 'text-amber-700' : ''}`}>{engineDeltaFmt(r.delta)}</td>
                      <td className="px-2 py-1">
                        <span className={`text-[10px] font-semibold px-1.5 py-0.5 rounded ${r.guided === 'Guided' ? 'bg-emerald-50 text-emerald-700' : 'bg-slate-100 text-slate-500'}`}>{r.guided}</span>
                      </td>
                      <td className="px-2 py-1 text-slate-500">{r.reference_date === '—' ? '—' : engineDateFmt(r.reference_date)}</td>
                    </tr>
                  ))}
                  {!sortedRows.length && !dayLoading && (
                    <tr><td colSpan="9" className="px-3 py-4 text-center text-slate-400">{routeQuery.trim() ? `No routes match “${routeQuery.trim()}”.` : 'No scored routes for this date.'}</td></tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>

          <div className="xl:w-[46%] border rounded-lg bg-white overflow-hidden flex flex-col">
            <div className="flex items-center justify-between gap-2 px-3 pt-2 pb-1">
              <div className="text-[11px] font-semibold text-slate-600 truncate">
                {selected ? `${selected.load_key} — ${selected.driver_name || selected.driver_user_name || ''}` : 'Pick a route'}
              </div>
              <div className="flex gap-1">{mapModeBtn('dispatch', 'Dispatch')}{mapModeBtn('engine', 'Engine')}{mapModeBtn('diff', 'Diff')}</div>
            </div>
            <div ref={mapDiv} className="w-full h-[320px] bg-slate-100" />
            {mapsError && <div className="text-[11px] text-red-600 px-3 py-1">⚠ map failed to load: {String(mapsError)}</div>}
            {mapMode === 'diff' && selected && (
              <div className="px-3 py-2 border-t max-h-[130px] overflow-y-auto">
                <div className="text-[10px] uppercase tracking-wide text-slate-500 pb-1">Engine moved (by more than 2 positions)</div>
                {movedStops.length ? movedStops.map((s) => (
                  <div key={s.pro} className="text-[11px] text-slate-700 py-0.5">
                    <span className="inline-block w-2 h-2 rounded-full mr-1.5 align-middle" style={{ background: '#d97706' }} />
                    engine moved <span className="font-semibold">{s.businessName || s.pro}</span> from #{s.actual_pos} to #{s.proposed_pos}
                  </div>
                )) : <div className="text-[11px] text-slate-400">No stop moved more than 2 positions — the engine broadly agrees with dispatch here.</div>}
              </div>
            )}
          </div>
        </div>
        </div>)}
      </div>
    </div>
  );
}

// ── Engine tab · Assignment view (Phase 2) ───────────────────────────────────
// The day PLAN: how the engine would have loaded the same crew, scored against
// what dispatch actually did. stop_agreement = driver-choice; co-load agreement
// = load-shape (label-symmetric). Reads plan_proposals / plan_proposals_daily.
function EngineAssignmentView({ google, mapsError }) {
  const [daily, setDaily] = useState(null);
  const [dailyErr, setDailyErr] = useState('');
  const [date, setDate] = useState('');
  const [day, setDay] = useState(null);
  const [dayLoading, setDayLoading] = useState(false);
  const [dayErr, setDayErr] = useState('');
  const [mapMode, setMapMode] = useState('diff'); // dispatch | engine | diff
  const [versions, setVersions] = useState(null); // cross-version progress rollups

  const days = daily?.days || [];
  const latestDate = days.length ? days[days.length - 1].date : '';

  useEffect(() => {
    fetchJsonWithRetry('/.netlify/functions/routing-engine-data?view=plan-daily')
      .then((d) => { if (!d?.ok) throw new Error(d?.error || 'plan data unavailable'); setDaily(d); const ds = d.days || []; if (ds.length) setDate(ds[ds.length - 1].date); })
      .catch((e) => setDailyErr(String(e?.message || e)));
    // Cross-version progress (separate, non-blocking — its own collection).
    fetchJsonWithRetry('/.netlify/functions/routing-engine-data?view=version-rollups')
      .then((d) => { if (d?.ok) setVersions(d.versions || []); })
      .catch(() => {});
  }, []);
  useEffect(() => {
    if (!date) return;
    let alive = true;
    setDayLoading(true); setDayErr(''); setDay(null); setSelectedDriver(null);
    fetchJsonWithRetry(`/.netlify/functions/routing-engine-data?view=plan-day&date=${date}`)
      .then((d) => { if (!alive) return; if (!d?.ok) throw new Error(d?.error || 'day load failed'); setDay(d); })
      .catch((e) => { if (alive) setDayErr(String(e?.message || e)); })
      .finally(() => { if (alive) setDayLoading(false); });
    return () => { alive = false; };
  }, [date]);

  const rollup = day?.rollup || null;
  const plan = day?.plan || null;

  const rows = useMemo(() => (plan?.per_driver || []).map((d) => ({
    driver: d.driver, driver_key: d.driver_key, class: d.class || '—',
    trips_engine: d.trips_engine, trips_actual: d.trips_actual,
    stops_engine: d.stops_engine, stops_actual: d.stops_actual,
    lbs_engine: d.lbs_engine, lbs_actual: d.lbs_actual,
    skid_cap: d.skid_cap == null ? -1 : d.skid_cap, skid_cap_learned: !!d.skid_cap_learned,
    agreement_pct: d.agreement_pct == null ? -1 : d.agreement_pct,
  })), [plan]);
  const { sorted, sortKey, sortDir, toggle } = useSortable(rows, 'stops_actual', 'desc');

  // moved stops: engine driver differs from dispatch
  const moved = useMemo(() => (plan?.stops || []).filter((s) => s.engine_driver && s.actual_driver && s.engine_driver !== s.actual_driver), [plan]);
  // the drivers involved in a move (gained OR lost a stop) — powers the "Only moved" filter
  const movedDrivers = useMemo(() => {
    const set = new Set();
    moved.forEach((m) => { if (m.actual_driver) set.add(m.actual_driver); if (m.engine_driver) set.add(m.engine_driver); });
    return set;
  }, [moved]);
  // view controls: collapse the trend chart, expand the map, focus only on moved routes
  const [chartOpen, setChartOpen] = useState(true);
  const [mapExpanded, setMapExpanded] = useState(false);
  const [movedOnly, setMovedOnly] = useState(false);
  // click a driver row → isolate that driver's dispatch vs engine on the map
  const [selectedDriver, setSelectedDriver] = useState(null); // { key, name } | null
  const shownRows = movedOnly ? sorted.filter((r) => movedDrivers.has(r.driver_key) || movedDrivers.has(r.driver)) : sorted;
  // moves involving the focused driver (for the Diff side list when one is picked)
  const focusMoved = selectedDriver
    ? moved.filter((s) => [s.actual_driver, s.engine_driver].some((d) => d && (d === selectedDriver.key || d === selectedDriver.name)))
    : moved;
  const driverColor = useMemo(() => {
    const keys = [...new Set((plan?.stops || []).flatMap((s) => [s.actual_driver, s.engine_driver]).filter(Boolean))].sort();
    const m = new Map();
    keys.forEach((k, i) => m.set(k, ROUTE_PALETTE[i % ROUTE_PALETTE.length]));
    return m;
  }, [plan]);

  // map
  const mapDiv = useRef(null); const mapRef = useRef(null); const [mapReady, setMapReady] = useState(0);
  const markersRef = useRef([]); const linesRef = useRef([]);
  const lastBoundsRef = useRef(null); // last fitted bounds, so a resize can refit
  useEffect(() => {
    if (!google || !mapDiv.current || mapRef.current) return;
    mapRef.current = new google.maps.Map(mapDiv.current, { center: ROUTING_DEPOT, zoom: 9, mapTypeControl: false, streetViewControl: false, fullscreenControl: false, gestureHandling: 'greedy', ...(MAP_ID ? { mapId: MAP_ID } : {}) });
    setMapReady((n) => n + 1);
  }, [google]);
  useEffect(() => {
    if (!google || !mapRef.current) return;
    markersRef.current.forEach((m) => m.setMap(null)); linesRef.current.forEach((l) => l.setMap(null));
    markersRef.current = []; linesRef.current = [];
    if (!plan) return;
    const stops = (plan.stops || []).filter((s) => s.lat != null && s.lng != null);
    if (!stops.length) return;
    const depotPt = { lat: ROUTING_DEPOT.lat, lng: ROUTING_DEPOT.lng };
    const engineTrips = plan.engine_trips || [];
    const byId = new Map(stops.map((s) => [s.id, s]));
    // driver focus: a clicked row isolates one driver (matched on key OR name,
    // since stop/trip driver ids can be either). No selection ⇒ everything shows.
    const isSel = (id) => !selectedDriver || id === selectedDriver.key || id === selectedDriver.name;
    const stopInSel = (s) => !selectedDriver || isSel(s.actual_driver) || isSel(s.engine_driver);

    // Engine visiting order per stop (index within its trip), derived on the client
    // so pin numbers work on EVERY plan — even ones built before actual_pos existed.
    const enginePos = new Map();
    for (const t of engineTrips) (t.stop_ids || []).forEach((id, i) => enginePos.set(id, i + 1));
    const DISPATCH_LINE = '#64748b';   // neutral grey — a driverless route in Dispatch mode
                                       // (Diff's ORIGINAL line styles itself — diff-route-style.js)
    const MOVED_COLOR = '#d97706';     // amber — engine moved this stop to a different driver
    const focused = !!selectedDriver;  // number the pins only when ONE driver is isolated

    // engine polylines: one per trip, colored by driver, trip1 solid / trip2+ dashed
    const drawEngine = () => {
      for (const t of engineTrips) {
        if (movedOnly && !movedDrivers.has(t.driver_key)) continue;
        if (!isSel(t.driver_key)) continue;
        const path = [depotPt];
        for (const id of t.stop_ids) { const s = byId.get(id); if (s) path.push({ lat: s.lat, lng: s.lng }); }
        if (path.length < 2) continue;
        const color = driverColor.get(t.driver_key) || BRAND;
        const dashed = t.seq > 1;
        // In Diff this is the NEW route — narrower than the original's casing and on top of it,
        // so the two are legible whether they agree or diverge (see lib/diff-route-style.js).
        const st = mapMode === 'diff'
          ? diffRouteStyle('new', { color })
          : { strokeColor: color, strokeOpacity: 0.95, strokeWeight: 3, zIndex: 6 };
        const pl = new google.maps.Polyline({ path, ...st, strokeOpacity: dashed ? 0 : st.strokeOpacity,
          icons: dashed ? [{ icon: { path: 'M 0,-1 0,1', strokeOpacity: 0.95, scale: 3 }, offset: '0', repeat: '12px' }] : undefined });
        pl.setMap(mapRef.current); linesRef.current.push(pl);
      }
    };
    // dispatch polylines: ONE PER ACTUAL TRIP, drawn in true delivery order — the same shape
    // the engine side draws (see groupDispatchTrips for why per-driver was wrong). In Diff,
    // dispatch is a neutral grey casing so it can never be mistaken for an engine route.
    const drawDispatch = (mode) => {
      for (const { drv, stops: ordered } of groupDispatchTrips(stops)) {
        if (movedOnly && !movedDrivers.has(drv)) continue;
        if (!isSel(drv)) continue;
        const path = [depotPt, ...ordered.map((s) => ({ lat: s.lat, lng: s.lng }))];
        if (path.length < 2) continue;
        // In Diff this is the ORIGINAL route, drawn as a WIDE casing under the engine's line.
        // It used to be thinner and fainter than the line drawn on top of it, which meant it
        // vanished completely wherever the two plans agreed — most of a real route.
        const st = mode === 'diff'
          ? diffRouteStyle('original')
          : { strokeColor: driverColor.get(drv) || DISPATCH_LINE, strokeOpacity: 0.9, strokeWeight: 3, zIndex: 5 };
        const pl = new google.maps.Polyline({ path, ...st });
        pl.setMap(mapRef.current); linesRef.current.push(pl);
      }
    };
    if (mapMode === 'dispatch') drawDispatch('dispatch');
    else if (mapMode === 'engine') drawEngine();
    else { drawDispatch('diff'); drawEngine(); }

    const movedSet = new Set(moved.map((s) => s.id));
    for (const s of stops) {
      if (movedOnly && !movedSet.has(s.id)) continue;
      if (!stopInSel(s)) continue;
      const drv = mapMode === 'dispatch' ? s.actual_driver : s.engine_driver;
      const isMoved = mapMode === 'diff' && movedSet.has(s.id);
      const color = isMoved ? MOVED_COLOR : (driverColor.get(drv) || '#64748b');
      // Pin number tracks the mode's primary line: delivery order in Dispatch,
      // engine visiting order in Engine/Diff. Only when a single driver is focused —
      // numbering the whole day would be a wall of digits.
      let label = null;
      if (focused && !isMoved) {
        const seq = mapMode === 'dispatch' ? s.actual_pos : enginePos.get(s.id);
        if (seq != null) label = String(seq);
      }
      const hollow = !isMoved && mapMode === 'diff' && label == null;
      const sz = label ? 26 : 24;
      const mk = new google.maps.Marker({ position: { lat: s.lat, lng: s.lng }, map: mapRef.current,
        icon: { url: circleMarkerSvg(color, { hollow, label }), scaledSize: new google.maps.Size(sz, sz), anchor: new google.maps.Point(sz / 2, sz / 2) },
        title: `${s.businessName || s.id} — dispatch ${s.actual_driver || '?'}${s.actual_pos ? ` #${s.actual_pos}` : ''}${s.engine_driver ? `, engine ${s.engine_driver}${enginePos.get(s.id) ? ` #${enginePos.get(s.id)}` : ''}` : ''}`, zIndex: isMoved ? 30 : 15 });
      markersRef.current.push(mk);
    }
    const bounds = new google.maps.LatLngBounds(); bounds.extend(depotPt);
    for (const s of stops) { if (movedOnly && !movedSet.has(s.id)) continue; if (!stopInSel(s)) continue; bounds.extend({ lat: s.lat, lng: s.lng }); }
    if (bounds.isEmpty()) bounds.extend(depotPt);
    lastBoundsRef.current = bounds;
    mapRef.current.fitBounds(bounds, 40);
  }, [google, mapReady, plan, mapMode, moved, movedOnly, movedDrivers, driverColor, selectedDriver]);

  // Google Maps paints solid gray until it's told its container has a real size.
  // A ResizeObserver fires a resize + refit the moment the container gets a
  // non-zero size and on every later change (expand map, collapse chart, tab
  // settle) — this is what keeps the tiles from staying blank.
  useEffect(() => {
    if (!google || !mapDiv.current) return undefined;
    const el = mapDiv.current;
    const kick = () => {
      if (!mapRef.current || !el.offsetWidth || !el.offsetHeight) return;
      google.maps.event.trigger(mapRef.current, 'resize');
      const b = lastBoundsRef.current;
      if (b && !b.isEmpty()) mapRef.current.fitBounds(b, 40);
    };
    const ro = new ResizeObserver(kick);
    ro.observe(el);
    return () => ro.disconnect();
  }, [google, mapReady]);

  const modeBtn = (id, label) => (
    <button key={id} onClick={() => setMapMode(id)}
      className={`px-2 py-1 text-[11px] font-semibold rounded ${mapMode === id ? 'text-white' : 'text-slate-600 bg-white border border-slate-200 hover:bg-slate-50'}`}
      style={mapMode === id ? { background: BRAND } : {}}>{label}</button>
  );

  return (
    <div className="space-y-3">
      <div className="flex items-center gap-2 flex-wrap">
        <input type="date" value={date} onChange={(e) => { if (e.target.value) setDate(e.target.value); }}
          className="text-xs border border-slate-300 rounded px-1.5 py-1 focus:outline-none focus:ring-2 focus:ring-blue-200 focus:border-blue-400" aria-label="Select plan date" />
        {date !== latestDate && latestDate && (
          <button onClick={() => setDate(latestDate)} className="text-[10px] font-semibold py-1 px-2 rounded border border-blue-300 text-blue-700 bg-white hover:bg-blue-50 whitespace-nowrap">Latest</button>
        )}
        {date && <span className="text-[11px] text-slate-500">{formatDateLong(date)}</span>}
      </div>

      {dailyErr && <div className="text-xs text-red-600 border border-red-200 bg-red-50 rounded p-2">⚠ {dailyErr}</div>}
      {!daily && !dailyErr && <div className="text-xs text-slate-500">Loading assignment history…</div>}
      {daily && !days.length && (
        <div className="text-xs text-slate-600 border rounded bg-white p-3">
          No scored plans yet. Run the observation backfill (routing-observations-backfill-background), then the plan replay (routing-engine-plan-replay-background) — the trend fills in from there and the nightly shadow keeps it current.
        </div>
      )}

      {rollup && (
        <div className="flex gap-2 flex-wrap">
          <EngineStatTile label="Stop agreement" value={rollup.stop_agreement_pct == null ? '—' : `${rollup.stop_agreement_pct}%`} hint="Share of stops the engine gave the SAME driver dispatch did (driver choice)" />
          <EngineStatTile label="Agreement · known drivers" value={rollup.stop_agreement_known_pct == null ? '—' : `${rollup.stop_agreement_known_pct}%`} hint="Stops belonging to drivers the engine knows (envelope from their OWN history) — the headline segment" />
          <EngineStatTile label="Agreement · fallback" value={rollup.stop_agreement_fallback_pct == null ? '—' : `${rollup.stop_agreement_fallback_pct}%`} hint="Stops of drivers scored on a class-level fallback envelope — the engine was guessing; read separately" />
          <EngineStatTile label="Co-load agreement" value={rollup.coload_agreement_pct == null ? '—' : `${rollup.coload_agreement_pct}%`} hint="Of the stop pairs dispatch co-loaded, the share the engine also co-loaded (load shape; label-symmetric)" />
          <EngineStatTile label="Co-load precision" value={rollup.coload_precision_pct == null ? '—' : `${rollup.coload_precision_pct}%`} hint="Of the engine's co-loads, the share dispatch also co-loaded" />
          <EngineStatTile label="Trips engine / actual" value={`${rollup.trips_engine ?? '—'} / ${rollup.trips_actual ?? '—'}`} />
          <EngineStatTile label="Travel Δ (engine − dispatch)" value={rollup.est_travel_engine_min == null ? '—' : engineDeltaFmt((rollup.est_travel_engine_min || 0) - (rollup.est_travel_actual_min || 0))} hint="Estimated total driving minutes, same haversine model both sides" />
          <EngineStatTile label="Matched-load seq" value={engineScoreFmt(rollup.matched_load_sequence_score)} hint="Phase-1 sequence score over engine trips that overlap an actual load ≥60%" />
        </div>
      )}

      <EngineVersionProgress versions={versions} current={daily?.engine_version} />

      <EngineHowToRead />

      <div className="border rounded-lg bg-white p-2">
        <button onClick={() => setChartOpen((v) => !v)} title={chartOpen ? 'Hide chart' : 'Show chart'}
          className="w-full flex items-center justify-between text-[11px] font-semibold text-slate-600 px-1 pb-1">
          <span>Daily agreement — stop (driver) vs co-load (shape), higher is closer to dispatch</span>
          <span className="text-slate-400 ml-2 shrink-0">{chartOpen ? '▾ hide' : '▸ show'}</span>
        </button>
        {chartOpen && <EngineAgreementChart days={days} />}
      </div>

      <div className="flex flex-col xl:flex-row gap-3 items-stretch">
        <div className={`${mapExpanded ? 'hidden' : 'xl:w-[38%]'} border rounded-lg bg-white overflow-hidden flex flex-col`}>
          <div className="flex items-center justify-between gap-2 px-3 pt-2 pb-1">
            <div className="text-[11px] font-semibold text-slate-600 truncate">Drivers{movedOnly ? ` · moved only (${movedDrivers.size})` : ''}{dayLoading ? ' · loading…' : ''}{dayErr ? ` · ⚠ ${dayErr}` : ''}<span className="font-normal text-slate-400"> · tap a row to focus the map</span></div>
            <button onClick={() => setMovedOnly((v) => !v)} title="Show only the drivers/routes the engine moved a stop to or from — on the table AND the map"
              className={`text-[10px] font-semibold px-2 py-0.5 rounded border shrink-0 ${movedOnly ? 'text-white' : 'text-slate-600 bg-white border-slate-200 hover:bg-slate-50'}`}
              style={movedOnly ? { background: BRAND, borderColor: BRAND } : {}}>Only moved</button>
          </div>
          <div className="overflow-x-auto overflow-y-auto max-h-[560px]">
            <table className="w-full text-xs">
              <thead className="bg-slate-50 sticky top-0"><tr>
                <SortableTh label="Driver" k="driver" sortKey={sortKey} sortDir={sortDir} onToggle={toggle} />
                <SortableTh label="Class" k="class" sortKey={sortKey} sortDir={sortDir} onToggle={toggle} />
                {/* "E/A" was too short to be read correctly: Chad read a 11/20 as the engine
                    putting 20 stops on a driver, when 20 is what DISPATCH ran and 11 is the
                    engine's proposal. Spell both sides out — this column is a comparison, and
                    which number is which is the whole point of it. */}
                <SortableTh label="Trips eng/disp" k="trips_actual" sortKey={sortKey} sortDir={sortDir} onToggle={toggle} />
                <SortableTh label="Stops eng/disp" k="stops_actual" sortKey={sortKey} sortDir={sortDir} onToggle={toggle} />
                <SortableTh label="Lbs eng/disp" k="lbs_actual" sortKey={sortKey} sortDir={sortDir} onToggle={toggle} />
                {/* WHICH TRUCKS TAKE 17-18 vs 12-15. The engine used to load every box
                    driver to the fleet p95 (22) when the median box trip is 14. This is the
                    per-trip skid cap the solver actually used for this driver, learned from
                    their own history; a hollow value means no skid history yet, so they are
                    still on the class number. */}
                <SortableTh label="Skid cap" k="skid_cap" sortKey={sortKey} sortDir={sortDir} onToggle={toggle} />
                <SortableTh label="Agree %" k="agreement_pct" sortKey={sortKey} sortDir={sortDir} onToggle={toggle} />
              </tr></thead>
              <tbody>
                {shownRows.map((r) => (
                  <tr key={r.driver_key}
                    onClick={() => setSelectedDriver((cur) => (cur && cur.key === r.driver_key ? null : { key: r.driver_key, name: r.driver }))}
                    className={`border-t cursor-pointer ${selectedDriver && selectedDriver.key === r.driver_key ? 'bg-blue-50' : 'hover:bg-slate-50'}`}>
                    <td className="px-2 py-1 font-semibold text-slate-800">
                      <span className="inline-block w-2 h-2 rounded-full mr-1.5 align-middle" style={{ background: driverColor.get(r.driver_key) || '#94a3b8' }} />{r.driver}
                    </td>
                    <td className="px-2 py-1">{r.class}</td>
                    <td className="px-2 py-1 tabular-nums">{r.trips_engine}/{r.trips_actual}</td>
                    <td className="px-2 py-1 tabular-nums">{r.stops_engine}/{r.stops_actual}</td>
                    <td className="px-2 py-1 tabular-nums">{r.lbs_engine.toLocaleString()}/{r.lbs_actual.toLocaleString()}</td>
                    <td className="px-2 py-1 tabular-nums" title={r.skid_cap_learned ? 'Learned from this driver\u2019s own trips' : 'No skid history yet \u2014 using the truck-class cap'}>
                      {r.skid_cap < 0 ? '\u2014' : <span className={r.skid_cap_learned ? 'font-semibold text-slate-800' : 'text-slate-400'}>{r.skid_cap}</span>}
                    </td>
                    <td className="px-2 py-1 tabular-nums font-semibold">{r.agreement_pct < 0 ? '—' : `${r.agreement_pct}%`}</td>
                  </tr>
                ))}
                {!shownRows.length && !dayLoading && <tr><td colSpan="7" className="px-3 py-4 text-center text-slate-400">{movedOnly ? 'No moved routes on this date — the engine matched dispatch on every driver.' : 'No plan for this date.'}</td></tr>}
              </tbody>
            </table>
          </div>
        </div>

        <div className={`${mapExpanded ? 'xl:w-full' : 'xl:w-[62%]'} border rounded-lg bg-white overflow-hidden flex flex-col`}>
          <div className="flex items-center justify-between gap-2 px-3 pt-2 pb-1">
            <div className="text-[11px] font-semibold text-slate-600 truncate">
              {selectedDriver
                ? <>Focused · <span style={{ color: BRAND }}>{selectedDriver.name}</span> — dispatch vs engine</>
                : <>Day plan · trip 1 solid, later trips dashed{movedOnly ? ' · moved only' : ''}</>}
            </div>
            <div className="flex gap-1 shrink-0">
              {selectedDriver && (
                <button onClick={() => setSelectedDriver(null)} title="Show every driver again"
                  className="px-2 py-1 text-[11px] font-semibold rounded text-slate-600 bg-white border border-slate-200 hover:bg-slate-50">✕ Clear</button>
              )}
              {modeBtn('dispatch', 'Dispatch')}{modeBtn('engine', 'Engine')}{modeBtn('diff', 'Diff')}
              <button onClick={() => setMapExpanded((v) => !v)} title={mapExpanded ? 'Collapse map (show the drivers table)' : 'Expand map full width'}
                className="px-2 py-1 text-[11px] font-semibold rounded text-slate-600 bg-white border border-slate-200 hover:bg-slate-50">{mapExpanded ? '⤡ Collapse' : '⤢ Expand'}</button>
            </div>
          </div>
          {/* Legend — spells out the diff's visual language (grey = dispatch, driver
              color = engine, amber = moved) so the map reads without guessing. */}
          <div className="flex items-center gap-x-3 gap-y-0.5 flex-wrap px-3 pb-1.5 text-[10px] leading-tight text-slate-500 border-b border-slate-100">
            {mapMode === 'diff' && <>
              {/* Swatches mirror the map: the ORIGINAL is the wide grey sleeve, the NEW is the
                  narrow coloured line that runs inside it where the two plans agree. */}
              <span className="inline-flex items-center gap-1"><span className="inline-block w-4 h-[7px] rounded" style={{ background: DIFF_ORIGINAL_COLOR, opacity: 0.45 }} />ORIGINAL · what dispatch ran</span>
              <span className="inline-flex items-center gap-1"><span className="inline-block w-4 h-[3px] rounded" style={{ background: BRAND }} />NEW · engine, trip 1 (driver color)</span>
              <span className="inline-flex items-center gap-1"><span className="inline-block w-4 border-t-2 border-dotted" style={{ borderColor: BRAND }} />trip 2+</span>
              <span className="inline-flex items-center gap-1"><span className="inline-block w-2.5 h-2.5 rounded-full" style={{ background: '#d97706' }} />moved to another driver</span>
            </>}
            {mapMode === 'dispatch' && <span>Actual routes — <b className="text-slate-600">one color per driver</b>, drawn in delivery order</span>}
            {mapMode === 'engine' && <>
              <span className="inline-flex items-center gap-1"><span className="inline-block w-4 h-[3px] rounded" style={{ background: BRAND }} />trip 1</span>
              <span className="inline-flex items-center gap-1"><span className="inline-block w-4 border-t-2 border-dotted" style={{ borderColor: BRAND }} />trip 2+</span>
              <span>· <b className="text-slate-600">one color per driver</b></span>
            </>}
            <span className="text-slate-400">{selectedDriver ? `· pins numbered in ${mapMode === 'dispatch' ? 'delivery' : 'engine'} order` : '· tap a driver row to number the stops'}</span>
          </div>
          <div ref={mapDiv} className={`w-full ${mapExpanded ? 'h-[720px]' : 'h-[560px]'} bg-slate-100`} />
          {mapsError && <div className="text-[11px] text-red-600 px-3 py-1">⚠ map failed to load: {String(mapsError)}</div>}
          {mapMode === 'diff' && plan && (
            <div className="px-3 py-2 border-t max-h-[130px] overflow-y-auto">
              <div className="text-[10px] uppercase tracking-wide text-slate-500 pb-1">Engine moved to a different driver ({focusMoved.length}{selectedDriver ? ` · ${selectedDriver.name}` : ''})</div>
              {focusMoved.length ? focusMoved.slice(0, 50).map((s) => (
                <div key={s.id} className="text-[11px] text-slate-700 py-0.5">
                  <span className="inline-block w-2 h-2 rounded-full mr-1.5 align-middle" style={{ background: '#d97706' }} />
                  <span className="font-semibold">{s.businessName || s.id}</span>: {s.actual_driver} → {s.engine_driver}
                </div>
              )) : <div className="text-[11px] text-slate-400">{selectedDriver ? 'No stop moved to or from this driver — the engine kept their board.' : 'Every stop went to the same driver dispatch used.'}</div>}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

// Cross-version progress — one row per engine version (stop-weighted over the
// whole window). This is the "is it actually getting better?" readout: the daily
// chart can't show it because a rescoring pass overwrites every day doc in place,
// so all its points always share ONE version. Each version snapshot is preserved
// in its own doc; here we line them up oldest→newest with the change in agreement
// and the trips/travel over-split gap called out.
function EngineVersionProgress({ versions, current }) {
  if (versions == null) return null; // still loading — stay quiet
  if (!versions.length) {
    return (
      <div className="border rounded-lg bg-white px-3 py-2 text-[11px] text-slate-500">
        <span className="font-semibold text-slate-600">Progress across engine versions</span> — appears here once the next replay or nightly writes the first snapshot. Each engine version keeps its own scorecard, so you can see whether a change actually moved the needle.
      </div>
    );
  }
  const fmtPct = (v) => (v == null ? '—' : `${v}%`);
  const fmtDelta = (v) => (v == null ? '—' : `${v > 0 ? '+' : ''}${v}%`);
  return (
    <div className="border rounded-lg bg-white p-2">
      <div className="text-[11px] font-semibold text-slate-600 px-1 pb-1.5">
        Progress across engine versions <span className="font-normal text-slate-400">— stop agreement is stop-weighted over the whole window; trips/travel Δ are engine vs dispatch (lower is better)</span>
      </div>
      <div className="flex gap-2 overflow-x-auto pb-1">
        {versions.map((v, i) => {
          const prev = i > 0 ? versions[i - 1] : null;
          const agree = v.stop_agreement_wmean;
          const chg = prev && prev.stop_agreement_wmean != null && agree != null ? Math.round((agree - prev.stop_agreement_wmean) * 10) / 10 : null;
          const isCur = v.engine_version === current;
          return (
            <div key={v.engine_version} className={`shrink-0 rounded-lg border px-2.5 py-1.5 min-w-[132px] ${isCur ? 'border-blue-300 bg-blue-50' : 'border-slate-200 bg-slate-50'}`}>
              <div className="flex items-center justify-between gap-1.5">
                <span className="text-[11px] font-bold text-slate-800">v{v.engine_version}</span>
                {isCur && <span className="text-[8px] uppercase tracking-wide bg-blue-600 text-white px-1 py-0.5 rounded">current</span>}
              </div>
              <div className="mt-0.5 flex items-baseline gap-1">
                <span className="text-lg font-bold tabular-nums" style={{ color: BRAND }}>{fmtPct(agree)}</span>
                {chg != null && chg !== 0 && (
                  <span className={`text-[10px] font-semibold ${chg > 0 ? 'text-emerald-600' : 'text-red-500'}`}>{chg > 0 ? '▲' : '▼'} {Math.abs(chg)}</span>
                )}
              </div>
              <div className="text-[9px] text-slate-500 leading-tight">stop agreement</div>
              <div className="mt-1 text-[9.5px] text-slate-500 tabular-nums leading-snug">
                trips Δ <span className="font-semibold text-slate-700">{fmtDelta(v.trips_delta_pct)}</span> · travel Δ <span className="font-semibold text-slate-700">{fmtDelta(v.travel_delta_pct)}</span>
              </div>
              <div className="text-[9px] text-slate-400 tabular-nums">{v.days_scored} days{v.window_from ? ` · ${String(v.window_from).slice(5)}–${String(v.window_to).slice(5)}` : ''}</div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// Daily agreement trend — stop % (solid) + co-load % (dashed). Higher = closer.
function EngineAgreementChart({ days }) {
  // Deliberately short aspect (760×86, vs the sequencing trend's 640×170): this
  // sits directly above the map, which Chad wants bigger — so the chart gives
  // back vertical room instead of eating it.
  const W = 760, H = 86, PAD_L = 30, PAD_R = 8, PAD_T = 10, PAD_B = 20;
  const pts = (days || []).filter((d) => d.stop_agreement_pct != null);
  if (pts.length < 2) return <div className="h-[86px] flex items-center justify-center text-xs text-slate-400">Not enough scored days yet — the trend appears after the plan replay runs.</div>;
  const x = (i) => PAD_L + (i * (W - PAD_L - PAD_R)) / (pts.length - 1);
  // Y-AXIS SCALES TO THE DATA. A fixed 0-100 axis put the whole realistic
  // operating range (agreement runs ~20-30%) into the bottom quarter of a 56px
  // band, so a genuine +2pt version gain moved the line about ONE pixel and the
  // trend read as dead flat no matter what the engine did. Keep 0 as the floor
  // (agreement is a proportion — a zero baseline is honest) and bring the TOP
  // down to the next round step above the data, so real movement is visible.
  const peak = Math.max(...pts.map((d) => Math.max(d.stop_agreement_pct ?? 0, d.coload_agreement_pct ?? 0)), 0);
  const step = peak <= 20 ? 5 : peak <= 50 ? 10 : 25;
  const top = Math.min(100, Math.max(step * 2, Math.ceil((peak + step * 0.35) / step) * step));
  const y = (v) => PAD_T + (H - PAD_T - PAD_B) * (1 - Math.min(v, top) / top);
  const line = (key) => pts.map((d, i) => `${x(i).toFixed(1)},${y(d[key] ?? 0).toFixed(1)}`).join(' ');
  // month labels for a multi-month span, else evenly spaced day labels so a
  // single-month plan window still shows real dates on the axis.
  const monthTicks = engineAxisTicks(pts);
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="w-full h-auto" role="img" aria-label="Daily plan agreement trend">
      {[0, top / 2, top].map((v, k) => (<g key={k}><line x1={PAD_L} y1={y(v)} x2={W - PAD_R} y2={y(v)} stroke="#e2e8f0" strokeWidth="1" /><text x={PAD_L - 4} y={y(v) + 3} fontSize="9" fill="#94a3b8" textAnchor="end">{Math.round(v)}</text></g>))}
      {monthTicks.map((t) => (<text key={t.i} x={x(t.i)} y={H - 6} fontSize="9" fill="#64748b" textAnchor={t.i === 0 ? 'start' : x(t.i) > W - 30 ? 'end' : 'middle'}>{t.label}</text>))}
      <polyline points={line('coload_agreement_pct')} fill="none" stroke="#94a3b8" strokeWidth="1.5" strokeDasharray="4 3" />
      <polyline points={line('stop_agreement_pct')} fill="none" stroke={BRAND} strokeWidth="2" />
      {pts.map((d, i) => (<circle key={d.date} cx={x(i)} cy={y(d.stop_agreement_pct ?? 0)} r="2.4" fill={BRAND}><title>{`${d.date} — stop ${d.stop_agreement_pct ?? '—'}%, co-load ${d.coload_agreement_pct ?? '—'}%`}</title></circle>))}
      <g fontSize="9"><line x1={W - 170} y1={12} x2={W - 152} y2={12} stroke={BRAND} strokeWidth="2" /><text x={W - 148} y={15} fill="#475569">stop</text><line x1={W - 108} y1={12} x2={W - 90} y2={12} stroke="#94a3b8" strokeWidth="1.5" strokeDasharray="4 3" /><text x={W - 86} y={15} fill="#475569">co-load</text></g>
    </svg>
  );
}

// Build ⇄ Engine toggle. A segmented control (the app's standard two-way sub-mode pattern).
// Rendered at the far RIGHT of the top nav row on desktop (only while on Routing), and inside
// the Routing screen on mobile (whose app bar is a chip menu with no persistent tab row).
function RoutingSubTabs({ tab, onChange }) {
  const btn = (id, label) => (
    <button
      key={id}
      onClick={() => onChange(id)}
      className={`px-3 py-1 text-[12px] font-semibold ${tab === id ? 'text-white' : 'bg-white text-slate-600 hover:bg-slate-50'} ${id === 'engine' ? 'border-l border-slate-300' : ''}`}
      style={tab === id ? { background: BRAND } : undefined}
    >{label}</button>
  );
  return (
    <div className="flex rounded-md border border-slate-300 overflow-hidden shrink-0">
      {btn('build', 'Build')}
      {btn('engine', 'Engine')}
    </div>
  );
}

// Routing section = the beta Build screen + the Engine (shadow) tab. `routingTab`/`setRoutingTab`
// are LIFTED to the shell so the Build/Engine toggle can live in the top nav row on desktop; the
// in-screen sub-tab bar renders only on mobile (`showSubTabs`).
function RoutingSection({ debugCaptureRef, routingTab, setRoutingTab, showSubTabs, presence }) {
  return (
    <div className="flex-1 flex flex-col min-h-0">
      {showSubTabs && (
        <div className="flex items-center border-b bg-white px-2 py-1.5 shrink-0">
          <RoutingSubTabs tab={routingTab} onChange={setRoutingTab} />
        </div>
      )}
      {routingTab === 'build'
        ? <RoutingScreen debugCaptureRef={debugCaptureRef} presence={presence} />
        : <EngineScreen />}
    </div>
  );
}

// ---------- shell ----------

// ── Multi-dispatcher presence (v0.51.0) ──
// Two people in the dispatch map at once used to be invisible to each other: all
// in-progress work (Compare cards, staged stops, selections) is per-device state,
// so both could grab the same unplanned stop onto different loads and the later
// Save silently won. This hook publishes a tiny heartbeat doc for THIS device to
// Firestore (`dispatch_presence/{deviceId}` — who's on, which screen, which stops
// its Compare cards are staging, when it last saved) and subscribes to everyone
// else's. Pure logic (staleness, claims, labels) lives in lib/presence.js.
// ENTIRELY fail-soft: no Firestore (or a denied rule) just means the feature is
// off — the app behaves exactly as before, nothing throws.
const PRESENCE_COLL = 'dispatch_presence';
function useDispatchPresence(screen) {
  const [identity] = useState(() => loadDeviceIdentity(typeof localStorage !== 'undefined' ? localStorage : null));
  const [name, setName] = useState(identity.name);
  const [peers, setPeers] = useState([]);
  const docsRef = useRef([]);        // latest raw snapshot docs (staleness re-evaluated on a timer)
  const peersJsonRef = useRef('[]'); // ref-stability: identical peer sets keep the SAME state array
  // What this device publishes. A ref (not state) so the stable publish callback
  // always reads current values without re-subscribing anything.
  const selfRef = useRef({ name: identity.name, screen, staged: [], stagedDate: null, saveAt: 0 });
  selfRef.current.screen = screen;

  const publish = useCallback(() => {
    if (!db) return;
    const s = selfRef.current;
    try {
      setDoc(doc(db, PRESENCE_COLL, identity.id), {
        deviceId: identity.id,
        name: s.name,
        screen: s.screen,
        // Cap the staged list — presence is a signal, not a datastore; 400 stops
        // is far past any real Compare board and keeps the doc tiny.
        staged: s.staged.slice(0, 400).map(String),
        stagedDate: s.stagedDate || null,
        saveAt: s.saveAt || 0,
        updatedAt: Date.now(),
        appVersion: APP_VERSION,
      }, { merge: true }).catch(() => { /* best-effort */ });
    } catch { /* presence must never break the app */ }
  }, [identity.id]);

  // Debounced publish for chatty updates (staged-set edits while building).
  const pushTimer = useRef(null);
  const publishSoon = useCallback(() => {
    if (pushTimer.current) clearTimeout(pushTimer.current);
    pushTimer.current = setTimeout(publish, 600);
  }, [publish]);

  // Heartbeat + screen changes; delete the doc on the way out (best-effort — the
  // staleness window covers a killed tab that never got to say goodbye).
  useEffect(() => { publish(); }, [screen, publish]);
  useEffect(() => {
    const t = setInterval(publish, PRESENCE_HEARTBEAT_MS);
    const bye = () => { try { if (db) deleteDoc(doc(db, PRESENCE_COLL, identity.id)); } catch { /* ignore */ } };
    window.addEventListener('beforeunload', bye);
    return () => { clearInterval(t); if (pushTimer.current) clearTimeout(pushTimer.current); window.removeEventListener('beforeunload', bye); };
  }, [publish, identity.id]);

  // Subscribe to everyone's presence; re-evaluate staleness every 30s so a peer
  // whose heartbeat stopped (without a doc change) still ages out of the chip.
  useEffect(() => {
    if (!db) return;
    const recompute = () => {
      // Strip the volatile heartbeat stamp before the equality check: consumers
      // only read the fields below, and keeping updatedAt in the state would
      // re-render every screen on each peer heartbeat (~25s) for no visible change.
      const next = activePeers(docsRef.current, identity.id, Date.now())
        .map(({ deviceId, name: n, screen: sc, staged, stagedDate, saveAt }) => ({ deviceId, name: n, screen: sc, staged, stagedDate, saveAt }));
      const json = JSON.stringify(next);
      if (json !== peersJsonRef.current) { peersJsonRef.current = json; setPeers(next); }
    };
    let unsub = null;
    try {
      unsub = onSnapshot(collection(db, PRESENCE_COLL),
        (snap) => { docsRef.current = snap.docs.map((d) => d.data()); recompute(); },
        () => { /* rules denied / offline — feature silently off */ });
    } catch { /* ignore */ }
    const t = setInterval(recompute, 30000);
    return () => { if (unsub) try { unsub(); } catch { /* ignore */ } clearInterval(t); };
  }, [identity.id]);

  // The Routing screen reports what its Compare cards are staging (stopNbrs + board date).
  const publishStaged = useCallback((stopNbrs, date) => {
    const s = selfRef.current;
    const next = (stopNbrs || []).map(String);
    if (s.stagedDate === date && s.staged.length === next.length && s.staged.every((v, i) => v === next[i])) return;
    s.staged = next; s.stagedDate = date || null;
    publishSoon();
  }, [publishSoon]);

  // Stamped on every CONFIRMED save — peers watching latestPeerSaveAt re-read the
  // board within seconds instead of waiting out the 2-minute poll.
  const bumpSave = useCallback(() => { selfRef.current.saveAt = Date.now(); publish(); }, [publish]);

  const rename = useCallback((n) => {
    const clean = String(n || '').trim().slice(0, 24);
    if (!clean) return;
    selfRef.current.name = clean;
    setName(clean);
    saveDeviceName(typeof localStorage !== 'undefined' ? localStorage : null, clean);
    publish();
  }, [publish]);

  // Memoized so consumers can depend on the stable member callbacks without the
  // whole object churning every render (it still updates when peers/name change).
  return useMemo(() => ({ deviceId: identity.id, name, rename, peers, publishStaged, bumpSave }),
    [identity.id, name, rename, peers, publishStaged, bumpSave]);
}

// Header chip: green + who else is on when someone is; quiet gray "you" chip when
// alone. Click either to set the name other dispatchers see for this device.
function PresenceChip({ presence, compact = false }) {
  if (!presence) return null;
  const label = peerChipLabel(presence.peers);
  const rename = () => {
    const n = window.prompt('Your dispatcher name (what the other dispatcher sees):', presence.name);
    if (n && n.trim()) presence.rename(n);
  };
  if (!label) {
    if (compact) return null;   // mobile: no chrome when alone
    return (
      <button onClick={rename} title={`Only you are on right now. Shown to other dispatchers when someone else opens the app. Click to change your name (now "${presence.name}").`}
        className="text-[11px] px-2 py-1 rounded border border-slate-200 text-slate-400 hover:text-slate-600 hover:bg-slate-50 inline-flex items-center gap-1.5 max-w-[160px]">
        <span className="w-1.5 h-1.5 rounded-full bg-slate-300 shrink-0" />
        <span className="truncate">{presence.name}</span>
      </button>
    );
  }
  return (
    <button onClick={rename} title={`${label}. Stops they're staging are locked on your selection tools. Click to change YOUR name (now "${presence.name}").`}
      className={`text-[11px] px-2 py-1 rounded inline-flex items-center gap-1.5 ${compact ? 'bg-white/15 text-white max-w-[150px]' : 'border border-emerald-300 bg-emerald-50 text-emerald-800 hover:bg-emerald-100 max-w-[260px]'}`}>
      <span className={`w-1.5 h-1.5 rounded-full shrink-0 ${compact ? 'bg-emerald-300' : 'bg-emerald-500'} animate-pulse`} />
      <span className="truncate">{label}</span>
    </button>
  );
}

function Shell() {
  const [tab, setTab] = useState('map');
  // Shared "Debug this view" capture: the active screen registers its bundle
  // builder here; the chip menu / nav entry opens the sheet, which posts it.
  const debugCaptureRef = useRef(null);
  const [debugOpen, setDebugOpen] = useState(false);
  const viewportWidth = useViewportWidth();
  const { h: viewportHeight, w: visibleWidth, x: viewportLeft, y: viewportTop } = useViewportSize();
  const isMobile = viewportWidth < MOBILE_BREAKPOINT;
  const updateAvailable = useBuildUpdate();
  const [chipMenuOpen, setChipMenuOpen] = useState(false);

  // The manifest-check flag. Read from the last stored run so a problem found
  // yesterday is still on the nav after a reload — the whole point is that you
  // should not have to remember to go and look at a tab to learn something is
  // wrong. Refreshed when the tab stores a new run, and when another tab in this
  // browser does (the `storage` event).
  const [moreBadge, setMoreBadge] = useState(() => manifestIssues(loadStored()).badge);
  useEffect(() => {
    const sync = () => setMoreBadge(manifestIssues(loadStored()).badge);
    window.addEventListener('dd-manifest-check-updated', sync);
    window.addEventListener('storage', sync);
    return () => {
      window.removeEventListener('dd-manifest-check-updated', sync);
      window.removeEventListener('storage', sync);
    };
  }, []);

  // Routing Build ⇄ Engine sub-tab, lifted here so the toggle can render in the top nav row
  // (far right) on desktop while the Routing screen consumes the same state.
  const [routingTab, setRoutingTab] = useState(() => {
    try { return localStorage.getItem('routing.tab') === 'engine' ? 'engine' : 'build'; } catch { return 'build'; }
  });
  useEffect(() => { try { localStorage.setItem('routing.tab', routingTab); } catch {} }, [routingTab]);
  // Opening the Routing screen defaults to the BUILD tab (Chad's preference). Switching to
  // Engine while you're on the screen stays put; navigating back to Routing lands on Build again.
  useEffect(() => { if (tab === 'routing') setRoutingTab('build'); }, [tab]);

  // Multi-dispatcher presence — published for every tab so "who's on" is honest
  // even from New Order / Quote; the Routing screen adds its staged-stop claims.
  const presence = useDispatchPresence(tab);

  // SMS messages + unread badge. Messages is a WINDOW over the current screen
  // (it doesn't navigate away), so it's a toggle, not a tab.
  const inbound = useSmsMessages();
  const { notes } = useCustomerNotes();
  const [messagesOpen, setMessagesOpen] = useState(false);
  const [smsSeenAt, setSmsSeenAt] = useState(() => Number(safeReadJSON(LS_SMS_SEEN, 0)) || 0);
  const smsUnread = inbound.filter((m) => m.direction === 'in' && new Date(m.at || 0).getTime() > smsSeenAt).length;
  const openMessages = () => { setMessagesOpen(true); };
  const closeMessages = () => { setMessagesOpen(false); const now = Date.now(); setSmsSeenAt(now); safeWriteJSON(LS_SMS_SEEN, now); };

  // Customer contacts (phone → name) from saved notes, for the Messages contact
  // picker. Employees (drivers/contractors) come from the roster endpoint inside
  // the panel; customers are the names we already know locally.
  const customerContacts = useMemo(() => {
    const seen = new Set(); const out = [];
    for (const n of notes.values()) for (const c of (n.contacts || [])) {
      const k = normPhone(c?.phone); if (k.length !== 10 || seen.has(k)) continue;
      seen.add(k); out.push({ phone: k, name: n.raw_name || c?.name || '' });
    }
    return out;
  }, [notes]);

  // Close chip menu on any tab change or click outside the bar.
  useEffect(() => { setChipMenuOpen(false); }, [tab]);

  const onSelectMenu = (next) => {
    setChipMenuOpen(false);
    if (next === 'debug') { setDebugOpen(true); return; }
    if (next === 'messages') { openMessages(); return; }
    // NOTE the default: anything unrecognised lands on 'map'. A new screen must be
    // named here or the phone menu silently opens the map instead — which is what
    // happened to Manifest check in v0.54.48: the desktop nav had it, the chip
    // menu did not, and there was no way to reach it from a phone at all.
    const KNOWN = ['routing', 'neworder', 'quote', 'manifest'];
    setTab(next === 'diagnostics' ? 'diag' : KNOWN.includes(next) ? next : 'map');
  };

  return (
    // h-screen is the SSR/first-paint fallback; once mounted we pin the shell to
    // the live visible viewport height (pixels) so iOS Safari toolbars can't hide
    // the bottom Save bar. Pixel height keeps the map container non-zero.
    <div
      className="h-screen flex flex-col overflow-hidden"
      style={{
        ...(viewportHeight ? { height: viewportHeight } : {}),
        // Pin to the visible width so iOS's slightly-wider layout viewport can't
        // push right-edge controls off-screen.
        ...(visibleWidth ? { width: visibleWidth, maxWidth: visibleWidth } : {}),
        // On mobile, anchor the shell to the visible (visual) viewport's actual
        // position. When iOS focuses an input it can scroll the visual viewport
        // sideways/up inside the wider layout viewport; without this the shell
        // stays at the layout-left and slides partly off the visible screen
        // (the "screen is shifting" / content hanging off the left edge bug).
        ...(isMobile
          ? { position: 'fixed', left: viewportLeft || 0, top: viewportTop || 0 }
          : {}),
      }}
    >
      {/* Above BOTH headers and outside the tab switch, so it can't be scrolled past or
          lost by changing screens — a stale tab is a whole-app condition, not a per-tab one. */}
      {updateAvailable && <UpdateBanner />}
      {isMobile ? (
        <MobileAppBar
          version={APP_VERSION}
          chipMenuOpen={chipMenuOpen}
          onChipMenu={() => setChipMenuOpen((v) => !v)}
          onSelectMenu={onSelectMenu}
          smsUnread={smsUnread}
          presence={presence}
          manifestBadge={moreBadge}
        />
      ) : (
        <header className="shrink-0 relative z-30 flex items-center justify-between px-4 py-2 border-b bg-white" style={{ paddingTop: 'env(safe-area-inset-top)' }}>
          <div className="flex items-center gap-3">
            <img src="/davis-logo.jpg" alt="Davis Delivery Service" className="h-9 w-auto" />
            <div className="font-bold leading-tight text-slate-800 border-l border-slate-200 pl-3">Dispatch Map</div>
          </div>
          <nav className="flex items-center gap-1 text-sm">
            <TabBtn label="Map" icon={<MapPin size={14} />} active={tab === 'map'} onClick={() => setTab('map')} />
            {ROUTING_FLAG && <TabBtn label="Routing (beta)" icon={<MapPinned size={14} />} active={tab === 'routing'} onClick={() => setTab('routing')} />}
            <TabBtn label="New Order" icon={<Package size={14} />} active={tab === 'neworder'} onClick={() => setTab('neworder')} />
            <TabBtn label="Quote" icon={<Calculator size={14} />} active={tab === 'quote'} onClick={() => setTab('quote')} />
            <TabBtn label="Messages" icon={<MessageSquare size={14} />} active={messagesOpen} onClick={openMessages} badge={smsUnread} />
            <TabBtn label="Diagnostics" icon={<Activity size={14} />} active={tab === 'diag'} onClick={() => setTab('diag')} />
            {/* Overflow tabs. Screens you visit deliberately rather than live in go here
                instead of shrinking the whole nav row; the badge surfaces a problem from
                a screen you are NOT on, which is the entire point of the manifest check. */}
            <MoreMenu
              activeId={tab}
              onPick={setTab}
              badge={moreBadge}
              items={[{ id: 'manifest', label: 'Manifest check', hint: 'Uline nightly vs the scan', icon: <FileCheck size={14} />, badge: moreBadge }]}
            />
            <TabBtn label="Debug" icon={<Bug size={14} />} active={debugOpen} onClick={() => setDebugOpen(true)} />
          </nav>
          {/* Far right of the nav row: the presence chip (who else is on) plus the Routing
              Build/Engine toggle — the toggle shows ONLY on the Routing screen. */}
          <div className="flex items-center gap-2">
            <PresenceChip presence={presence} />
            {tab === 'routing' && ROUTING_FLAG && <RoutingSubTabs tab={routingTab} onChange={setRoutingTab} />}
          </div>
        </header>
      )}

      {tab === 'map' ? <MapScreen onOpenMessages={openMessages} smsUnread={smsUnread} debugCaptureRef={debugCaptureRef} presence={presence} /> : (tab === 'routing' && ROUTING_FLAG) ? <RoutingSection debugCaptureRef={debugCaptureRef} routingTab={routingTab} setRoutingTab={setRoutingTab} showSubTabs={isMobile} presence={presence} /> : tab === 'neworder' ? <NewOrderScreen /> : tab === 'quote' ? <QuoteScreen /> : tab === 'manifest' ? <ManifestCheckScreen /> : <DiagnosticsRoute />}

      {/* Messages floats OVER the current screen (you never leave the map). */}
      {messagesOpen && <MessagesPanel messages={inbound} seenAt={smsSeenAt} onClose={closeMessages} customerContacts={customerContacts} />}

      {/* "Debug this view" — reachable from any tab; captures the active screen. */}
      <DebugCaptureSheet open={debugOpen} onClose={() => setDebugOpen(false)} captureRef={debugCaptureRef} />

      {/* Footer is desktop/tablet only on mobile; the in-map version chip
          and the top-bar chip cover the same info on small screens. */}
      {!isMobile && (
        <footer className="border-t bg-white px-4 py-1 text-[10px] text-slate-400 flex items-center justify-between">
          <div>Dispatch Map v{APP_VERSION} · {BUILD_COMMIT}{BUILD_TIME ? ` · built ${BUILD_TIME.slice(5, 16).replace('T', ' ')}Z` : ''}</div>
          <div className="hidden sm:block">© Davis Delivery Service</div>
        </footer>
      )}
    </div>
  );
}

// Tiny diagnostics wrapper so the screen has its own data fetch
// (rather than threading the map's state through props).
function DiagnosticsRoute() {
  const { stops, ops, lastLoadScanAt, lastUnplannedScanAt, loading, refresh } = useStops();
  const { notes } = useCustomerNotes();
  return (
    <DiagnosticsScreen
      stops={stops}
      notes={notes}
      ops={ops}
      lastLoadScanAt={lastLoadScanAt}
      lastUnplannedScanAt={lastUnplannedScanAt}
      refreshing={loading}
      onRefresh={() => refresh()}
    />
  );
}

// Normalize a phone to 10 digits (drops a leading US country-code 1). Used by the
// shell to derive customer contacts handed to the Messages panel.
const normPhone = (p) => { const d = String(p || '').replace(/\D/g, ''); return d.length === 11 && d.startsWith('1') ? d.slice(1) : d; };
// Progressive phone mask → xxx-xxx-xxxx as the user types (keeps only digits, US 10-digit; a leading
// "1" on an 11-digit entry is trimmed by normPhone). Every order-entry phone field runs through this.
// Mask a phone to xxx-xxx-xxxx. Delegates to the pure normalizePhone in bulk-orders.js so the
// interactive typed path (set/setCell/setIntakeCell) and the spreadsheet-import path share ONE
// implementation and can't drift — an extension / "+" intl / >11-digit number passes through
// verbatim, and NuVizz gets the digits stripped later at write time.
const fmtPhone = (v) => normalizePhone(v);

// ── New Order — create a delivery stop (order) in NuVizz from a standalone tab. Fill the
// delivery address + optional order details and Create. The origin ("from") + service date
// default (origin is saved ONCE to localStorage, since ROUTING_DEPOT has no street address).
// Gated by a Beta/Live toggle AND the server write flag: in ○ Beta a Create only previews
// (nothing sent). New orders land UNPLANNED — plan them onto a load later in Routing.
const NEWORDER_ORIGIN_KEY = 'dd_neworder_origin';    // the DEFAULT / last-used origin (also read by Routing's import header fallback)
const NEWORDER_ORIGINS_KEY = 'dd_neworder_origins';  // the saved LIST of pickup origins (multiple pickup locations)
// The company's own terminal — a COMPLETE address, so it's usable as-is: it seeds the pickup
// dropdown on every device (no manual save needed) and is the selection when nothing else is saved.
const NEWORDER_ORIGIN_DEFAULT = { name: 'Davis Delivery Service', addr1: '943 Gainesville Hwy 200-4000', city: 'Buford', state: 'GA', zip: '30518' };
// A blank origin for the "＋ New pickup location…" reset (state pre-filled; NOT the Davis address).
const NEWORDER_ORIGIN_BLANK = { name: '', addr1: '', city: '', state: 'GA', zip: '' };
const EMPTY_ORDER_ROW = { name: '', addr1: '', addr2: '', city: '', state: '', zip: '', stopNbr: '', pro: '', itemDesc: '', pallets: '', loose: '', weight: '', price: '', phone: '', email: '', dispatchNotes: '' };

// Coerce every field of a saved origin to a STRING — a hand-edited/corrupt entry (e.g. a numeric
// zip) would otherwise pass the completeness gate and then throw on .trim() mid-submit.
function coerceOrigin(s) {
  const o = { ...NEWORDER_ORIGIN_DEFAULT };
  if (s && typeof s === 'object') for (const k of Object.keys(o)) o[k] = String(s[k] ?? o[k] ?? '');
  return o;
}
const originIsComplete = (o) => !!(String(o?.name).trim() && String(o?.addr1).trim() && String(o?.city).trim() && String(o?.state).trim() && String(o?.zip).trim());
const originKey = (o) => `${String(o?.name).trim().toLowerCase()}|${String(o?.addr1).trim().toLowerCase()}`;
// Load the saved pickup-origin LIST, seeding it from the legacy single default if the list is empty.
function loadSavedOrigins() {
  let list = [];
  try { const a = JSON.parse(localStorage.getItem(NEWORDER_ORIGINS_KEY) || 'null'); if (Array.isArray(a)) list = a.map(coerceOrigin).filter(originIsComplete); } catch { /* ignore */ }
  if (!list.length) {
    try { const d = JSON.parse(localStorage.getItem(NEWORDER_ORIGIN_KEY) || 'null'); const o = coerceOrigin(d); if (originIsComplete(o)) list = [o]; } catch { /* ignore */ }
  }
  // De-dupe by name|addr1 (keep first).
  const seen = new Set(); const out = [];
  for (const o of list) { const k = originKey(o); if (!seen.has(k)) { seen.add(k); out.push(o); } }
  // Always seed the Davis terminal so the pickup dropdown exists (and is pre-selected) on a fresh
  // device with nothing saved. User-saved locations stay first (they win the default pick).
  if (!seen.has(originKey(NEWORDER_ORIGIN_DEFAULT))) out.push({ ...NEWORDER_ORIGIN_DEFAULT });
  return out;
}

// Local calendar day (YYYY-MM-DD) — the default service date for a new order.
function todayLocalYMD() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

// Module-level (NOT defined inside the screen) so typing never remounts the input and loses focus.
function OrderField({ label, req, value, onChange, placeholder, type = 'text', className = '', disabled = false }) {
  return (
    <label className={`block ${className}`}>
      <span className="text-[11px] font-medium text-slate-500">{label}{req && <span className="text-red-500"> *</span>}</span>
      <input
        type={type} value={value} onChange={onChange} placeholder={placeholder} disabled={disabled}
        className={`mt-0.5 w-full border border-slate-300 rounded px-2 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-300 ${disabled ? 'bg-slate-50 text-slate-500' : ''}`}
      />
    </label>
  );
}

// New Order opens on a Single / Bulk toggle so both ways to create an order live under one
// tab (per the "put the bulk add tab under new order" debug request — it previously had its
// own top-level nav tab). Neither inner screen's logic is touched; this is a thin shell that
// picks which one renders. The choice is remembered per device.
const NEWORDER_MODE_KEY = 'dd_neworder_mode';
function NewOrderScreen() {
  const [mode, setMode] = useState(() => {
    try { return localStorage.getItem(NEWORDER_MODE_KEY) === 'bulk' ? 'bulk' : 'single'; } catch { return 'single'; }
  });
  const setModeAndSave = (m) => { setMode(m); try { localStorage.setItem(NEWORDER_MODE_KEY, m); } catch { /* ignore */ } };
  return (
    <div className="flex-1 min-h-0 flex flex-col overflow-hidden bg-slate-50">
      <div className="shrink-0 bg-white border-b border-slate-200 px-4 py-2 flex items-center gap-2">
        <span className="text-[11px] font-medium text-slate-500 mr-1">Create:</span>
        <div className="inline-flex rounded-lg border border-slate-300 overflow-hidden">
          <button
            onClick={() => setModeAndSave('single')}
            title="One order at a time"
            className={`px-3 py-1.5 text-[12px] font-semibold inline-flex items-center gap-1.5 ${mode === 'single' ? 'text-white' : 'text-slate-600 bg-white hover:bg-slate-50'}`}
            style={mode === 'single' ? { background: BRAND } : {}}
          >
            <Package size={13} /> Single order
          </button>
          <button
            onClick={() => setModeAndSave('bulk')}
            title="Many orders at once — grid entry or spreadsheet import"
            className={`px-3 py-1.5 text-[12px] font-semibold inline-flex items-center gap-1.5 border-l border-slate-300 ${mode === 'bulk' ? 'text-white' : 'text-slate-600 bg-white hover:bg-slate-50'}`}
            style={mode === 'bulk' ? { background: BRAND } : {}}
          >
            <LayoutList size={13} /> Bulk add
          </button>
        </div>
      </div>
      {/* MUST be a flex column: the inner screens' roots are `flex-1 min-h-0 overflow-auto`,
          which only constrains height on a flex ITEM. As a plain block this wrapper let the
          screen grow to content height and clipped it (`overflow-hidden`) — and the app shell
          permanently locks body scroll (index.css), so everything below the fold was simply
          unreachable ("Bulk Add won't let me scroll" the moment the manifest panel mounted). */}
      <div className="flex-1 min-h-0 flex flex-col overflow-hidden">
        {mode === 'single' ? <NewOrderSingleScreen /> : <BulkOrderScreen />}
      </div>
    </div>
  );
}

function NewOrderSingleScreen() {
  // Saved pickup origins (multiple locations) + the currently-selected/edited one.
  const [origins, setOrigins] = useState(() => loadSavedOrigins());
  const [origin, setOrigin] = useState(() => {
    const list = loadSavedOrigins();
    try { const d = coerceOrigin(JSON.parse(localStorage.getItem(NEWORDER_ORIGIN_KEY) || 'null')); if (originIsComplete(d)) return d; } catch { /* ignore */ }
    return list[0] || NEWORDER_ORIGIN_DEFAULT;
  });
  // Trimmed like the delivery gate — a whitespace-only origin field must not enable Create.
  const originComplete = originIsComplete(origin);
  const [showOrigin, setShowOrigin] = useState(!originComplete);
  const [originSaved, setOriginSaved] = useState(false);   // transient "✓ Saved" confirmation
  const [row, setRow] = useState(EMPTY_ORDER_ROW);
  const [serviceDate, setServiceDate] = useState(todayLocalYMD());
  const [live, setLive] = useState(false);
  const [busy, setBusy] = useState(false);
  const [result, setResult] = useState(null); // { ok, beta?, msg }

  const set = (k) => (e) => setRow((r) => ({ ...r, [k]: k === 'phone' ? fmtPhone(e.target.value) : e.target.value }));
  const setOrig = (k) => (e) => { setOriginSaved(false); setOrigin((o) => ({ ...o, [k]: e.target.value })); };

  const deliveryComplete = !!(row.name.trim() && row.addr1.trim() && row.city.trim() && row.state.trim() && row.zip.trim());
  const canSubmit = deliveryComplete && originComplete && !!serviceDate && !busy;

  // Selecting a saved pickup location from the dropdown ('' = keep editing / new location).
  const pickOrigin = (e) => {
    setOriginSaved(false);
    const k = e.target.value;
    if (!k) { setOrigin(coerceOrigin({ ...NEWORDER_ORIGIN_BLANK })); return; }
    const found = origins.find((o) => originKey(o) === k);
    if (found) setOrigin(coerceOrigin(found));
  };

  // Save the current origin: upsert into the saved LIST (by name|addr1) AND set it as the default
  // (NEWORDER_ORIGIN_KEY, which Routing's import-header fallback reads). Disabled until complete —
  // the reported "save did nothing" was a silent save of an INCOMPLETE origin with no feedback.
  const persistOrigin = () => {
    if (!originComplete) return;
    const o = coerceOrigin(origin);
    const next = [...origins.filter((x) => originKey(x) !== originKey(o)), o];
    setOrigins(next);
    try {
      localStorage.setItem(NEWORDER_ORIGINS_KEY, JSON.stringify(next));
      localStorage.setItem(NEWORDER_ORIGIN_KEY, JSON.stringify(o));
    } catch { /* ignore */ }
    setOriginSaved(true);
  };

  // Remove the selected saved pickup location from the list (keeps the fields editable for this order).
  const deleteOrigin = () => {
    const o = coerceOrigin(origin);
    const next = origins.filter((x) => originKey(x) !== originKey(o));
    setOrigins(next);
    try {
      localStorage.setItem(NEWORDER_ORIGINS_KEY, JSON.stringify(next));
      const def = coerceOrigin(JSON.parse(localStorage.getItem(NEWORDER_ORIGIN_KEY) || 'null'));
      if (originKey(def) === originKey(o)) { if (next[0]) localStorage.setItem(NEWORDER_ORIGIN_KEY, JSON.stringify(next[0])); else localStorage.removeItem(NEWORDER_ORIGIN_KEY); }
    } catch { /* ignore */ }
    setOriginSaved(false);
  };

  const originIsSaved = origins.some((o) => originKey(o) === originKey(origin));

  // The clientOpId is minted ONCE per ORDER (not per click): a retry after a lost response
  // replays the same id, so the server's idempotency ledger returns the prior success instead
  // of creating a DUPLICATE order. Regenerated only after a confirmed success.
  const opIdRef = useRef(newClientOpId());

  const submit = async () => {
    if (!canSubmit) return;
    persistOrigin();
    setBusy(true); setResult(null);
    try {
      const payloadRow = {
        name: row.name.trim(), addr1: row.addr1.trim(), addr2: row.addr2.trim() || null,
        city: row.city.trim(), state: row.state.trim(), zip: row.zip.trim(),
        stopNbr: row.stopNbr.trim() || null, pro: row.pro.trim() || null,
        itemDesc: row.itemDesc.trim() || null,
        pallets: row.pallets === '' ? null : Number(row.pallets),
        loose: row.loose === '' ? null : Number(row.loose),
        weight: row.weight === '' ? null : Number(row.weight),
        price: row.price.trim() || null,                             // → NuVizz Seal # (sealNbr)
        phone: (row.phone || '').trim() || null,                     // → to.contact.phone
        email: (row.email || '').trim() || null,                     // → to.contact.email
        dispatchNotes: (row.dispatchNotes || '').trim() || null,     // → comments[] ORD_IN (driver instructions)
      };
      const settings = {
        origin: { name: origin.name.trim(), addr1: origin.addr1.trim(), city: origin.city.trim(), state: origin.state.trim(), zip: origin.zip.trim() },
        serviceDate, timeZone: 'America/New_York',
      };
      if (!live) {
        setResult({ ok: true, beta: true, msg: `○ Beta — would create an order for ${payloadRow.name} (nothing sent). Flip to ● LIVE to create it in NuVizz.` });
        return;
      }
      let res;
      try { res = await callWrite('createStop', { row: payloadRow, settings }, { dryRun: false, clientOpId: opIdRef.current, createdBy: 'dispatcher' }); }
      catch (e) { res = { ok: false, error: e?.message || 'network error' }; }
      if (res.ok && res.result?.ok) {
        const nbr = res.result.entityNbr || payloadRow.stopNbr || '(number assigned by NuVizz)';
        opIdRef.current = newClientOpId();   // next order = new idempotency key
        if (res.result.updated) {
          // stop/sync/update is an UPSERT: the typed Order # already existed, and NuVizz
          // REPLACED that order's details. Say so loudly; keep the form so it's reviewable.
          setResult({ ok: true, updated: true, msg: `⚠ Order ${nbr} ALREADY EXISTED — NuVizz UPDATED it (its address/details were replaced with what you entered). Verify in the portal if that wasn't intended.` });
        } else {
          setResult({ ok: true, msg: `✓ Order created — ${nbr}. It's now UNPLANNED; plan it onto a load in Routing.` });
          setRow(EMPTY_ORDER_ROW);   // ready for the next order; keep origin + date
        }
      } else {
        setResult({ ok: false, msg: `✗ Create failed: ${res.error || res.result?.error || 'write error'}` });
      }
    } finally { setBusy(false); }   // a throw anywhere above can never wedge the form in "Creating…"
  };

  return (
    <div className="flex-1 min-h-0 overflow-auto bg-slate-50">
      <div className="max-w-2xl mx-auto p-4 space-y-4">
        {/* Header + Beta/Live */}
        <div className="flex items-center justify-between gap-3">
          <div>
            <h1 className="text-lg font-bold text-slate-800 flex items-center gap-2"><Package size={18} /> New Order</h1>
            <p className="text-[12px] text-slate-500">Create a delivery order in NuVizz. It lands <b>unplanned</b> — plan it onto a load in Routing.</p>
          </div>
          <button
            onClick={() => setLive((v) => !v)}
            title={live ? 'LIVE — Create sends the order to NuVizz. Click for Beta (preview only).' : 'BETA — Create only previews (nothing sent). Click to go Live.'}
            className={`inline-flex items-center gap-1 text-[12px] font-bold px-2.5 py-1.5 rounded border shrink-0 ${live ? 'border-red-600 bg-red-600 text-white' : 'border-slate-300 bg-white text-slate-600 hover:bg-slate-50'}`}
          >
            {live ? '● LIVE' : '○ Beta'}
          </button>
        </div>

        {/* Origin (from) — pick a saved pickup location or edit for this order */}
        <div className="bg-white border border-slate-200 rounded-lg p-3">
          <button onClick={() => setShowOrigin((v) => !v)} className="w-full flex items-center justify-between text-left">
            <span className="text-[13px] font-semibold text-slate-700">Pickup (ship from){!originComplete && <span className="ml-2 text-[11px] font-normal text-amber-600">— required</span>}</span>
            <span className="text-[12px] text-slate-500 inline-flex items-center gap-1">
              {originComplete && !showOrigin ? `${origin.name} · ${origin.city}, ${origin.state}` : ''}
              {showOrigin ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
            </span>
          </button>
          {showOrigin && (
            <div className="mt-3 space-y-2">
              {/* Saved-location picker — only when there's more than one, or one that's saved */}
              {origins.length > 0 && (
                <label className="block">
                  <span className="text-[11px] font-medium text-slate-500">Pickup location</span>
                  <select
                    value={originIsSaved ? originKey(origin) : ''}
                    onChange={pickOrigin}
                    className="mt-0.5 w-full border border-slate-300 rounded px-2 py-1.5 text-sm bg-white focus:outline-none focus:ring-2 focus:ring-blue-300"
                  >
                    {origins.map((o) => <option key={originKey(o)} value={originKey(o)}>{o.name} — {o.city}, {o.state}</option>)}
                    <option value="">＋ New pickup location…</option>
                  </select>
                </label>
              )}
              <OrderField label="Pickup name" req value={origin.name} onChange={setOrig('name')} placeholder="Buford Terminal" />
              <OrderField label="Address" req value={origin.addr1} onChange={setOrig('addr1')} placeholder="123 Depot Rd" />
              <div className="grid grid-cols-6 gap-2">
                <OrderField className="col-span-3" label="City" req value={origin.city} onChange={setOrig('city')} placeholder="Buford" />
                <OrderField className="col-span-1" label="State" req value={origin.state} onChange={setOrig('state')} placeholder="GA" />
                <OrderField className="col-span-2" label="ZIP" req value={origin.zip} onChange={setOrig('zip')} placeholder="30518" />
              </div>
              <div className="flex items-center gap-2 flex-wrap">
                <button
                  onClick={persistOrigin} disabled={!originComplete}
                  title={originComplete ? 'Save this pickup location for reuse' : 'Fill all pickup fields to save'}
                  className={`text-[12px] font-medium inline-flex items-center gap-1 px-2.5 py-1 rounded border ${originComplete ? 'border-slate-300 bg-white text-slate-700 hover:bg-slate-50' : 'border-slate-200 bg-slate-50 text-slate-400 cursor-not-allowed'}`}
                >
                  <Save size={13} /> {originIsSaved ? 'Update pickup location' : 'Save pickup location'}
                </button>
                {originIsSaved && origins.length > 0 && (
                  <button onClick={deleteOrigin} className="text-[12px] font-medium inline-flex items-center gap-1 px-2.5 py-1 rounded border border-slate-300 bg-white text-slate-600 hover:bg-red-50 hover:text-red-700 hover:border-red-200"><Trash2 size={13} /> Remove</button>
                )}
                {originSaved && <span className="text-[12px] font-medium text-green-700 inline-flex items-center gap-1"><FileCheck size={13} /> Saved</span>}
                {!originComplete && <span className="text-[11px] text-amber-600">Fill all pickup fields to save.</span>}
              </div>
            </div>
          )}
        </div>

        {/* Delivery (to) */}
        <div className="bg-white border border-slate-200 rounded-lg p-3 space-y-2">
          <div className="text-[13px] font-semibold text-slate-700">Deliver to</div>
          <OrderField label="Business / consignee name" req value={row.name} onChange={set('name')} placeholder="Acme Distribution" />
          <OrderField label="Address" req value={row.addr1} onChange={set('addr1')} placeholder="500 Main St" />
          <OrderField label="Suite / unit (optional)" value={row.addr2} onChange={set('addr2')} placeholder="Ste 200" />
          <div className="grid grid-cols-6 gap-2">
            <OrderField className="col-span-3" label="City" req value={row.city} onChange={set('city')} placeholder="Lawrenceville" />
            <OrderField className="col-span-1" label="State" req value={row.state} onChange={set('state')} placeholder="GA" />
            <OrderField className="col-span-2" label="ZIP" req value={row.zip} onChange={set('zip')} placeholder="30046" />
          </div>
        </div>

        {/* Order details */}
        <div className="bg-white border border-slate-200 rounded-lg p-3 space-y-2">
          <div className="text-[13px] font-semibold text-slate-700">Order details</div>
          <OrderField label="Item description (optional)" value={row.itemDesc} onChange={set('itemDesc')} placeholder="e.g. 2 pallets appliances" />
          <div className="grid grid-cols-2 gap-2">
            <OrderField label="Order # (optional)" value={row.stopNbr} onChange={set('stopNbr')} placeholder="auto if blank" />
            <OrderField label="PRO / shipment # (optional)" value={row.pro} onChange={set('pro')} placeholder="e.g. 12345" />
          </div>
          <div className="grid grid-cols-3 gap-2">
            <OrderField label="Pallets" type="number" value={row.pallets} onChange={set('pallets')} placeholder="1" />
            <OrderField label="Loose" type="number" value={row.loose} onChange={set('loose')} placeholder="" />
            <OrderField label="Weight (lbs)" type="number" value={row.weight} onChange={set('weight')} placeholder="" />
          </div>
          <OrderField label="Price ($ → Seal #)" type="number" value={row.price} onChange={set('price')} placeholder="e.g. 185.00" className="max-w-[200px]" />
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <OrderField label="Consignee phone (optional)" value={row.phone} onChange={set('phone')} placeholder="770-555-0123" />
            <OrderField label="Consignee email (optional)" type="email" value={row.email} onChange={set('email')} placeholder="name@company.com" />
          </div>
          <OrderField label="Dispatch notes for the driver (optional)" value={row.dispatchNotes} onChange={set('dispatchNotes')} placeholder="e.g. dock 4, call on arrival" />
          <OrderField label="Service date" req type="date" value={serviceDate} onChange={(e) => setServiceDate(e.target.value)} className="max-w-[200px]" />
        </div>

        {/* Result + submit */}
        {result && (
          <div className={`rounded-lg px-3 py-2 text-[13px] ${result.ok ? (result.beta ? 'bg-slate-100 text-slate-700 border border-slate-200' : result.updated ? 'bg-amber-50 text-amber-800 border border-amber-200' : 'bg-green-50 text-green-800 border border-green-200') : 'bg-red-50 text-red-800 border border-red-200'}`}>
            {result.msg}
          </div>
        )}
        <div className="flex items-center justify-between gap-3 pb-6">
          <span className="text-[12px] text-slate-500">{!originComplete ? 'Set the origin address first.' : !deliveryComplete ? 'Fill the required (*) delivery fields.' : live ? 'Ready — this WILL create the order in NuVizz.' : 'Beta — Create previews only.'}</span>
          <button
            onClick={submit} disabled={!canSubmit}
            className={`inline-flex items-center gap-1.5 px-4 py-2 rounded font-semibold text-white text-sm shrink-0 ${canSubmit ? '' : 'opacity-40 cursor-not-allowed'}`}
            style={{ background: live ? '#dc2626' : BRAND }}
          >
            <Plus size={16} /> {busy ? 'Creating…' : live ? 'Create order (LIVE)' : 'Preview (Beta)'}
          </button>
        </div>
      </div>
    </div>
  );
}

// ── Bulk Add — create MANY delivery orders at once: an editable grid of rows plus a
// paste/drop importer (Excel/Sheets paste, .csv, .xlsx). Pickup + service date are set ONCE
// for the whole batch (each order can still override its own delivery fields). Like New Order
// it's gated by a Beta/Live toggle + the server write flag; each row creates an UNPLANNED order.
const BULK_MAX_ROWS = 300;   // soft cap per batch (keeps one Save from hammering NuVizz)
function bulkEmptyRow() { const o = {}; for (const f of BULK_FIELDS) o[f.key] = ''; return o; }
const BULK_COLMAP_KEY = 'dd_bulk_colmap';
const BULK_DRAFT_KEY = 'dd_bulk_draft';   // the grid autosaves here — unchecked rows queue across days
const MANIFEST_DRAFT_KEY = 'dd_manifest_intake';   // the Manifest Intake panel autosaves here — held rows survive reloads

function BulkOrderScreen() {
  // Shared pickup for the batch (same saved-origins model as New Order).
  const [origins, setOrigins] = useState(() => loadSavedOrigins());
  const [origin, setOrigin] = useState(() => {
    const list = loadSavedOrigins();
    try { const d = coerceOrigin(JSON.parse(localStorage.getItem(NEWORDER_ORIGIN_KEY) || 'null')); if (originIsComplete(d)) return d; } catch { /* ignore */ }
    return list[0] || NEWORDER_ORIGIN_DEFAULT;
  });
  const originComplete = originIsComplete(origin);
  const originIsSaved = origins.some((o) => originKey(o) === originKey(origin));
  const [showOrigin, setShowOrigin] = useState(!originComplete);
  const [originSaved, setOriginSaved] = useState(false);
  const [serviceDate, setServiceDate] = useState(todayLocalYMD());
  const [live, setLive] = useState(false);
  // The grid is a PERSISTED DRAFT (Chad: push some rows now, leave the rest queued for a
  // later day's push). Rows autosave to this device; a row's _push flag (default true)
  // marks whether Create sends it — unchecked rows stay in the grid, surviving reloads,
  // until they're pushed or removed. _push is UI state, not an order field (never sent).
  const [rows, setRows] = useState(() => {
    try {
      const saved = JSON.parse(localStorage.getItem(BULK_DRAFT_KEY) || 'null');
      if (Array.isArray(saved) && saved.length) {
        // Normalize the phone as the draft rehydrates too — not just at import/typing — so rows
        // saved by an OLDER build (raw digit runs like "4048148100") show as xxx-xxx-xxxx the
        // moment the grid reloads, without the dispatcher having to re-import.
        return saved.slice(0, BULK_MAX_ROWS + 1).map((r) => ({ ...bulkEmptyRow(), ...r, phone: normalizePhone(r?.phone), _push: r?._push !== false }));
      }
    } catch { /* corrupt draft — start fresh */ }
    return [bulkEmptyRow(), bulkEmptyRow(), bulkEmptyRow()];
  });
  useEffect(() => { try { localStorage.setItem(BULK_DRAFT_KEY, JSON.stringify(rows)); } catch { /* ignore */ } }, [rows]);
  const [pasteText, setPasteText] = useState('');
  const [importer, setImporter] = useState(null);   // { columns, dataRows, mapping, sig }
  const [importErr, setImportErr] = useState('');
  const [importBusy, setImportBusy] = useState('');  // OCR in flight — the drop zone shows this instead of the hint
  const [importInfo, setImportInfo] = useState('');  // manifest read summary + integrity warnings (review nudge)
  // Set by a confident-header AUTO import: {prevRows, stash} — "Undo & map manually" restores the
  // grid to prevRows and reopens the mapper with the same parse, so auto never traps a bad mapping.
  const [autoImportUndo, setAutoImportUndo] = useState(null);
  const [dragOver, setDragOver] = useState(false);
  const [busy, setBusy] = useState(false);
  const [progress, setProgress] = useState(null);    // { done, total }
  const [results, setResults] = useState(null);      // { beta?, created, updated, failed, rows:[…] } | { loadMode, ok, msg, detail? }
  // "Create as a NEW load" mode (item A): ONE async import creates the load AND every order
  // inline — no per-stop pre-creates. Rows top-to-bottom = the driver's visit order.
  const [asLoad, setAsLoad] = useState(false);
  const [loadNbr, setLoadNbr] = useState('');
  const [routeName, setRouteName] = useState('');
  // Bulk Add screen view: the order-building grid, or the durable "Pushed to NuVizz" history
  // (same cloud log the manifest flow writes — a receipt of what a spreadsheet push sent).
  const [bulkView, setBulkView] = useState('orders');   // 'orders' | 'pushed'
  const [verifyMsg, setVerifyMsg] = useState(null);   // live status while the import converges
  const fileRef = useRef(null);

  // ── Manifest Intake (Chad's mockup): a dedicated review panel for OCR'd manifests ──
  // { manifest: {...data.manifest, fileName}, warnings: [], rows: [intakeRow] } | null.
  // Persisted so HELD rows survive reloads / next-day sessions until pushed or discarded.
  // Its own busy/progress/results cluster — the grid's footer keys off busy/progress, and
  // the two flows must never cross.
  const [intake, setIntake] = useState(() => safeReadJSON(MANIFEST_DRAFT_KEY, null));
  useEffect(() => { safeWriteJSON(MANIFEST_DRAFT_KEY, intake); }, [intake]);
  const [intakeTab, setIntakeTab] = useState('held');
  const [intakeOpen, setIntakeOpen] = useState(null);        // expanded row id (address/details editor)
  const [intakeBusy, setIntakeBusy] = useState(false);
  const [intakeProgress, setIntakeProgress] = useState(null);
  const [intakeResults, setIntakeResults] = useState(null);
  // Pushed-to-NuVizz history: the Pushed tab shows the DURABLE cloud log for a chosen day
  // (default today), so you can look back at what was pushed yesterday from any device.
  const etTodayStr = () => new Intl.DateTimeFormat('en-CA', { timeZone: 'America/New_York' }).format(new Date());
  const [pushedDate, setPushedDate] = useState(etTodayStr);
  const [pushedLog, setPushedLog] = useState({ loading: false, records: [], error: null, date: null });
  const pushedReqRef = useRef(null);   // latest requested date — stale responses must not render under a newer label
  const fetchPushedLog = useCallback(async (date) => {
    if (!date) return;
    pushedReqRef.current = date;
    setPushedLog((s) => ({ ...s, loading: true, error: null }));
    try {
      const r = await fetch(`/.netlify/functions/manifest-push-log?date=${encodeURIComponent(date)}`);
      const d = await r.json();
      if (pushedReqRef.current !== date) return;   // a newer day was requested — drop this response
      setPushedLog({ loading: false, records: Array.isArray(d.records) ? d.records : [], error: d.ok ? null : (d.reason || 'load failed'), date });
    } catch (e) { if (pushedReqRef.current === date) setPushedLog({ loading: false, records: [], error: e.message, date }); }
  }, []);
  useEffect(() => { if (intakeTab === 'pushed' || bulkView === 'pushed') fetchPushedLog(pushedDate); }, [intakeTab, bulkView, pushedDate, fetchPushedLog]);

  const setOrig = (k) => (e) => { setOriginSaved(false); setOrigin((o) => ({ ...o, [k]: e.target.value })); };
  const pickOrigin = (e) => {
    setOriginSaved(false);
    const k = e.target.value;
    if (!k) { setOrigin(coerceOrigin({ ...NEWORDER_ORIGIN_BLANK })); return; }
    const found = origins.find((o) => originKey(o) === k);
    if (found) setOrigin(coerceOrigin(found));
  };
  const persistOrigin = () => {
    if (!originComplete) return;
    const o = coerceOrigin(origin);
    const next = [...origins.filter((x) => originKey(x) !== originKey(o)), o];
    setOrigins(next);
    try { localStorage.setItem(NEWORDER_ORIGINS_KEY, JSON.stringify(next)); localStorage.setItem(NEWORDER_ORIGIN_KEY, JSON.stringify(o)); } catch { /* ignore */ }
    setOriginSaved(true);
  };

  const setCell = (i, key) => (e) => { const v = key === 'phone' ? fmtPhone(e.target.value) : e.target.value; setRows((rs) => rs.map((r, idx) => (idx === i ? { ...r, [key]: v } : r))); };
  // Structural mutations are FROZEN while a push is in flight: createAll deletes finished
  // rows by click-time index, so adding/removing/importing mid-push shifted indexes and
  // could destroy a queued row that was never sent (or keep a sent one for a double-push).
  const addRow = () => { if (busy) return; setAutoImportUndo(null); setRows((rs) => (rs.length >= BULK_MAX_ROWS ? rs : [...rs, bulkEmptyRow()])); };
  const removeRow = (i) => { if (busy) return; setAutoImportUndo(null); setRows((rs) => (rs.length > 1 ? rs.filter((_, idx) => idx !== i) : [bulkEmptyRow()])); };
  const clearRows = () => { if (busy) return; setAutoImportUndo(null); setRows([bulkEmptyRow(), bulkEmptyRow(), bulkEmptyRow()]); setResults(null); };

  // In load mode every row ALSO needs its Order # (stopNbr) — it is the convergence key the
  // import path verifies the seated order against; NuVizz cannot generate it for an inline create.
  const missingFor = (r) => {
    const m = bulkRowMissing(r);
    // Load mode references its stops by NuVizz Stop Number, which after the v0.50.54 ref
    // cross is the grid's PRO column (bulkRowNuvizzRefs) — requiring Order # here let a
    // PRO-less row pass the gate and then silently VANISH from the created load (the
    // server filters the empty stopNbr out of orderedStopNbrs).
    if (asLoad && !bulkRowNuvizzRefs(r).stopNbr) m.push('pro');
    return m;
  };
  const activeRows = rows.filter((r) => !bulkRowIsBlank(r));
  // Selection: only _push rows count toward Create; unchecked rows are QUEUED (they stay
  // in the autosaved grid for a later push and never gate or join this batch).
  const isPush = (r) => r._push !== false;
  const pushRows = activeRows.filter(isPush);
  const queuedCount = activeRows.length - pushRows.length;
  const togglePush = (i) => { if (busy) return; setRows((rs) => rs.map((r, idx) => (idx === i ? { ...r, _push: !isPush(r) } : r))); };
  const allPushed = activeRows.length > 0 && activeRows.every(isPush);
  const toggleAllPush = () => { if (busy) return; setRows((rs) => rs.map((r) => (bulkRowIsBlank(r) ? r : { ...r, _push: !allPushed }))); };
  const readyCount = pushRows.filter((r) => missingFor(r).length === 0).length;
  const incompleteCount = pushRows.length - readyCount;
  const canCreate = originComplete && !!serviceDate && readyCount > 0 && !busy
    // Load mode: ONE declarative import = the load's COMPLETE stop list — a half-ready grid
    // must never fire (the incomplete rows would simply be missing from the created load).
    && (!asLoad || (incompleteCount === 0 && !!loadNbr.trim()));

  // ── Importer (paste / file) ──
  const recallMapping = (sig) => { if (!sig) return null; try { return (JSON.parse(localStorage.getItem(BULK_COLMAP_KEY) || '{}'))[sig] || null; } catch { return null; } };
  const rememberMapping = (sig, mapping) => { if (!sig) return; try { const all = JSON.parse(localStorage.getItem(BULK_COLMAP_KEY) || '{}'); all[sig] = mapping; localStorage.setItem(BULK_COLMAP_KEY, JSON.stringify(all)); } catch { /* ignore */ } };

  const finishIngest = (parsed) => {
    setImportErr('');
    if (!parsed || !parsed.length) { setImportErr('Nothing to import — the paste/file was empty.'); return; }
    // Column count = the WIDEST row, not just the first. A short/merged title first row (or a
    // header with trailing blanks) must not collapse the mapping to "Column 1" and hide the rest.
    const width = parsed.reduce((m, r) => Math.max(m, Array.isArray(r) ? r.length : 0), 0);
    const hasHeader = looksLikeHeader(parsed[0]);
    const header = parsed[0] || [];
    const columns = Array.from({ length: Math.max(width, 1) }, (_, i) => ({
      idx: i,
      label: hasHeader ? String(header[i] || `Column ${i + 1}`) : `Column ${i + 1}`,
    }));
    const dataRows = hasHeader ? parsed.slice(1) : parsed;
    if (!dataRows.length) { setImportErr('Found a header but no data rows.'); return; }
    const sig = hasHeader ? headerSignature(parsed[0]) : null;
    const mapping = recallMapping(sig) || autoMapColumns(hasHeader ? parsed[0] : []);
    const stash = { columns, dataRows, mapping, sig, hasHeader };
    // CONFIDENT header — every required field auto-mapped → apply it straight away: drop → orders
    // in the grid, no 30-dropdown mapping screen. "Undo & map manually" on the info line reopens
    // the mapper with this same parse. Anything less confident still opens the mapper.
    if (hasHeader && mappingCoversRequired(mapping) && commitImport(dataRows, mapping, sig, { auto: true, stash })) return;
    setImporter(stash);
  };
  const ingestText = (text) => finishIngest(parseDelimited(text));
  const ingestAoa = (aoa) => {
    const parsed = (aoa || []).map((r) => (Array.isArray(r) ? r.map((c) => (c == null ? '' : String(c))) : [String(r ?? '')]));
    while (parsed.length && parsed[parsed.length - 1].every((x) => String(x).trim() === '')) parsed.pop();
    finishIngest(parsed);
  };
  // One file. Multi-file drops come through onFiles below, which processes them
  // sequentially — seq/total only label the progress + error lines ("file 1 of 2").
  const onFile = async (file, { seq = 1, total = 1 } = {}) => {
    if (!file) return;
    const busyTag = total > 1 ? ` (file ${seq} of ${total})` : '';
    // Errors APPEND (with the file named) instead of replacing, so on a 2-PDF drop
    // file 1's failure isn't wiped the moment file 2 starts.
    const fail = (msg) => setImportErr((p) => {
      const m = total > 1 && !String(msg).includes(file.name) ? `"${file.name}": ${msg}` : msg;
      return p ? `${p} · ${m}` : m;
    });
    const name = (file.name || '').toLowerCase();
    try {
      if (name.endsWith('.xlsx') || name.endsWith('.xls')) {
        const mod = await import('xlsx');   // lazy — the parser only loads when a spreadsheet is dropped
        const XLSX = mod?.read ? mod : (mod?.default || mod);   // xlsx is CJS: named exports may sit on .default under Vite
        const wb = XLSX.read(await file.arrayBuffer(), { type: 'array' });
        const ws = wb.Sheets[wb.SheetNames[0]];
        ingestAoa(XLSX.utils.sheet_to_json(ws, { header: 1, blankrows: false, defval: '' }));
      } else if (name.endsWith('.pdf')) {
        // Scanned carrier manifest (Estes-style). These PDFs are pure fax IMAGES — zero
        // embedded text — so no parser can read them; the AI reader runs as a BACKGROUND
        // function (vision over a multi-page scan takes 20-40s, past the 26s request cap
        // that timed out the first version) and we poll for the result. One AI call per
        // drop (a few cents); ZERO NuVizz calls.
        // GUARD (review blocker): a new drop REPLACES the intake — never silently destroy
        // HELD orders ("saved on this device" is the feature's promise). Confirm BEFORE the
        // OCR runs, so a Cancel also costs nothing.
        // A new manifest ADDS to the current intake — held orders are kept and the new orders
        // are appended below them, so you can stack several manifests before pushing (no more
        // "replace and drop held"). Only a push in flight blocks a read.
        if (intakeBusy) { fail('A push is in progress — wait for it to finish before reading a new manifest.'); return; }
        setImportBusy(`Reading "${file.name}"${busyTag} — a scanned manifest takes ~20–40s…`);
        try {
          // NOTE: an earlier fix auto-SPLIT a big PDF into page groups client-side (pdf-lib)
          // and OCR'd each under the 240 KB inline cap. A high-resolution fax scan defeats
          // it: Manifest_04753105 is 3.9 MB over FIVE pages (~1.05 MB/page), so even a
          // single page exceeded the cap and the splitter bailed to the same "too large"
          // error. The chunked UPLOAD below replaces it: the base64 rides to Firestore in
          // ~700 KB parts through manifest-upload (a regular function without the
          // background-function body cap), and the reader reassembles it — ONE OCR pass,
          // one AI call, any realistic scan size.
          const buf = new Uint8Array(await file.arrayBuffer());
          let bin = '';
          for (let i = 0; i < buf.length; i += 0x8000) bin += String.fromCharCode.apply(null, buf.subarray(i, i + 0x8000));
          const b64 = btoa(bin);
          const jobId = (crypto?.randomUUID?.() || `j${Date.now()}${Math.random().toString(36).slice(2, 10)}`).toLowerCase();
          // Netlify BACKGROUND functions cap the request body ~256 KB, so only a small PDF can
          // ride inline. A big one (a high-resolution fax scan easily hits several MB) is
          // uploaded in ~700 KB parts to manifest-upload (a regular function, no such cap) and
          // the reader reassembles it — no more "split it and drop the halves".
          const INLINE_MAX = 240000, CHUNK = 700000, TOTAL_MAX = 21000000; // chars of base64 (~16 MB PDF)
          if (b64.length > TOTAL_MAX) { fail('That PDF is over ~16 MB — even the chunked reader won\'t take it. Print-to-PDF a smaller page range and drop that.'); return; }
          let kickBody;
          if (b64.length <= INLINE_MAX) {
            kickBody = { jobId, pdfBase64: b64, filename: file.name };
          } else {
            const total = Math.ceil(b64.length / CHUNK);
            for (let i = 0; i < total; i++) {
              setImportBusy(`Uploading "${file.name}"${busyTag} — part ${i + 1} of ${total}…`);
              let up = null;
              try {
                up = await fetch('/.netlify/functions/manifest-upload', {
                  method: 'POST', headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({ jobId, seq: i, total, data: b64.slice(i * CHUNK, (i + 1) * CHUNK) }),
                });
              } catch { /* fall through to the retry below */ }
              if (!up || !up.ok) {
                // One retry per part — a single blip shouldn't scrap a multi-MB upload.
                await new Promise((r) => setTimeout(r, 1500));
                try {
                  up = await fetch('/.netlify/functions/manifest-upload', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ jobId, seq: i, total, data: b64.slice(i * CHUNK, (i + 1) * CHUNK) }),
                  });
                } catch { up = null; }
              }
              if (!up || !up.ok) { fail(`Upload failed on part ${i + 1} of ${total}${up ? ` (HTTP ${up.status})` : ''} — drop the file again.`); return; }
            }
            kickBody = { jobId, chunks: total, filename: file.name };
          }
          setImportBusy(`Reading "${file.name}"${busyTag} — a scanned manifest takes ~20–40s (a heavy scan can take a few minutes)…`);
          const kick = await fetch('/.netlify/functions/manifest-ocr-background', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(kickBody),
          });
          if (!kick.ok && kick.status !== 202) { fail(`manifest reader unavailable (HTTP ${kick.status})`); return; }
          const t0 = Date.now();
          let data = null;
          while (Date.now() - t0 < 360000) {   // poll up to 6 min; the reader itself caps at 5
            await new Promise((r) => setTimeout(r, 3000));
            setImportBusy(`Reading "${file.name}"${busyTag} — ${Math.round((Date.now() - t0) / 1000)}s (a scanned manifest takes ~20–40s; a heavy scan can take a few minutes)…`);
            try {
              const pr = await fetch(`/.netlify/functions/manifest-ocr-result?job=${jobId}`);
              const pd = await pr.json();
              if (pd.status === 'done') { data = pd; break; }
              if (pd.status === 'error') { fail(pd.error || 'manifest read failed'); return; }
            } catch { /* transient poll failure — keep waiting */ }
          }
          if (!data) { fail('The manifest reader did not answer in time — drop the file again.'); return; }
          // Carrier → the Order # prefix (matches the board's existing ESTES-<digits> convention).
          const carrierWord = String(data.manifest?.carrier || 'ESTES').trim().split(/\s+/)[0].toUpperCase().replace(/[^A-Z0-9]/g, '') || 'ESTES';
          // Manifest rows open the dedicated INTAKE panel (review → check → Push to NuVizz),
          // not the generic spreadsheet column-mapper.
          const incoming = manifestRowsToIntake(data.rows, { prefix: `${carrierWord}-` });
          const manifestMeta = { ...(data.manifest || {}), fileName: file.name };
          // The manifest's own "Total Pros" vs what was actually read. A SHORTFALL means
          // orders are missing off this file — a different class of problem from a misread
          // ZIP, so it rides separately and gets its own red banner instead of being joined
          // into the amber warning line where it read as one nag among twenty.
          const shortfall = data.integrity && data.integrity.shortBy > 0
            ? [{ fileName: file.name, expected: data.integrity.expectedPros, read: data.integrity.readPros, shortBy: data.integrity.shortBy }]
            : [];
          setIntake((prev) => {
            if (!prev || !(prev.rows || []).length) {
              return { manifest: manifestMeta, mergedManifests: [manifestMeta], warnings: data.warnings || [], shortfalls: shortfall, rows: incoming };
            }
            // APPEND: keep existing held + pushed rows, add the new manifest's orders below them,
            // deduped by order ref (re-dropping the same manifest won't double it) with fresh,
            // collision-free ids.
            const existingRefs = new Set(prev.rows.map((r) => String(r.stopNbr || '').toUpperCase()).filter(Boolean));
            const existingIds = new Set(prev.rows.map((r) => r.id));
            const added = [];
            for (const r of incoming) {
              const ref = String(r.stopNbr || '').toUpperCase();
              if (ref && existingRefs.has(ref)) continue;
              let id = r.id; while (existingIds.has(id)) id = `${id}_x`;
              existingIds.add(id); if (ref) existingRefs.add(ref);
              added.push({ ...r, id });
            }
            return {
              ...prev,
              mergedManifests: [...(prev.mergedManifests || [prev.manifest]), manifestMeta],
              warnings: [...(prev.warnings || []), ...(data.warnings || [])],
              shortfalls: [...(prev.shortfalls || []), ...shortfall],
              rows: [...prev.rows, ...added],
            };
          });
          setIntakeTab('held'); setIntakeResults(null); setIntakeOpen(null); setBulkView('orders');
        } finally { setImportBusy(''); }
      } else {
        ingestText(await file.text());   // .csv / .tsv / .txt
      }
    } catch (err) { fail(`Could not read "${file.name}": ${err?.message || 'unreadable file'}`); setImportBusy(''); }
  };
  // Multi-file drop/pick (Chad: "drop 2 PDFs at the same time"). PDFs process
  // SEQUENTIALLY — each OCR pass appends its orders to the same Manifest Intake
  // (deduped by order ref, as always), so several manifests stack in one drop.
  // Spreadsheets stay one-per-drop: the column-mapper handles a single parse at a
  // time, so extra non-PDFs are skipped with a note rather than silently eaten.
  // The lone spreadsheet runs FIRST — finishIngest clears the error line when it
  // starts, so running it after a failed PDF would wipe that PDF's error.
  const onFiles = async (fileList) => {
    const files = Array.from(fileList || []).filter(Boolean);
    if (!files.length) return;
    setImportErr(''); setImportInfo('');
    const isPdf = (f) => (f.name || '').toLowerCase().endsWith('.pdf');
    const pdfs = files.filter(isPdf);
    const others = files.filter((f) => !isPdf(f));
    if (others.length > 1) setImportErr(`One spreadsheet per drop — reading "${others[0].name}", skipped ${others.length - 1} other non-PDF file(s). (Several PDF manifests at once is fine.)`);
    if (others.length) await onFile(others[0]);
    for (let i = 0; i < pdfs.length; i++) await onFile(pdfs[i], { seq: i + 1, total: pdfs.length });
  };
  // Shared by the mapper's Import button and the confident-header AUTO path: land the mapped
  // orders in the grid (ghost residue dropped), remember the header mapping, report what happened.
  const commitImport = (dataRows, mapping, sig, { auto = false, stash = null } = {}) => {
    const mapped = mappedRowsToOrders(dataRows, mapping).filter((o) => !bulkRowIsBlank(o));
    // Drop GHOST rows — template residue with no consignee/address/order#/PRO (a column dragged
    // down past the last real order). They'd land as junk rows demanding 5 fields each.
    const orders = mapped.filter((o) => !bulkRowIsGhost(o));
    const ghosts = mapped.length - orders.length;
    if (!orders.length) { setImportErr(ghosts ? `All ${ghosts} row(s) were residue — no consignee/address/order # anywhere. Check the column mapping.` : 'No rows to import with the current column mapping.'); return false; }
    // Normalize the imported phone to xxx-xxx-xxxx (same mask as typing) so a dropped/pasted
    // spreadsheet lands formatted — NuVizz gets the digits stripped later at write time.
    if (busy) { setImportErr('A push is running — import again when it finishes.'); return false; }
    // Cap against REMAINING capacity: slicing to BULK_MAX_ROWS alone let existing rows push
    // imported orders past the grid cap — they silently vanished while the banner still
    // claimed the full count. Count what actually lands and say what was dropped.
    const keepCount = rows.filter((r) => !bulkRowIsBlank(r)).length;
    const capacity = Math.max(0, BULK_MAX_ROWS - keepCount);
    const overCap = Math.max(0, orders.length - capacity);
    const filled = orders.slice(0, capacity).map((o) => ({ ...bulkEmptyRow(), ...o, phone: normalizePhone(o.phone) }));
    if (!filled.length) { setImportErr(`The grid is full (${BULK_MAX_ROWS} rows) — push or clear rows, then import again.`); return false; }
    setAutoImportUndo(auto && stash ? { prevRows: rows, stash } : null);
    setBulkView('orders');   // a fresh import always lands you back on the grid, not the Pushed tab
    setRows((rs) => { const keep = rs.filter((r) => !bulkRowIsBlank(r)); return [...keep, ...filled, bulkEmptyRow()].slice(0, BULK_MAX_ROWS + 1); });
    rememberMapping(sig, mapping);
    setImporter(null); setPasteText(''); setResults(null);
    setImportInfo(`${auto ? 'Read the columns automatically and imported' : 'Imported'} ${filled.length} order(s)${ghosts ? ` — skipped ${ghosts} residue row(s) that had no consignee, address, or order # (template leftovers)` : ''}${overCap ? ` — ⚠ ${overCap} row(s) did NOT fit (grid cap ${BULK_MAX_ROWS}); push or clear rows and re-import for the rest` : ''}.`);
    return true;
  };
  const applyImport = () => { if (importer) commitImport(importer.dataRows, importer.mapping, importer.sig); };
  const undoAutoImport = () => {
    setAutoImportUndo((u) => {
      if (!u) return null;
      setRows(u.prevRows && u.prevRows.length ? u.prevRows : [bulkEmptyRow(), bulkEmptyRow(), bulkEmptyRow()]);
      setImportInfo('');
      setImporter(u.stash);   // reopen the mapper on the same parse for manual mapping
      return null;
    });
  };

  // ── Create all ready rows ──
  const createAll = async () => {
    if (!canCreate) return;
    const targets = rows.map((r, idx) => ({ r, idx })).filter(({ r }) => !bulkRowIsBlank(r) && isPush(r) && bulkRowMissing(r).length === 0);
    if (!targets.length) return;
    if (!live) { setResults({ beta: true, created: 0, updated: 0, failed: 0, rows: [], msg: `○ Beta — would create ${targets.length} order(s) (nothing sent). Flip to ● LIVE to create them in NuVizz.` }); return; }
    persistOrigin();
    const settings = { origin: { name: origin.name.trim(), addr1: origin.addr1.trim(), city: origin.city.trim(), state: origin.state.trim(), zip: origin.zip.trim() }, serviceDate, timeZone: 'America/New_York' };
    setBusy(true); setResults(null); setProgress({ done: 0, total: targets.length });
    const out = [];
    const pushedLogRecords = [];   // durable cloud push-history — feeds the "Pushed to NuVizz" tab
    // Sequential — one create at a time, each with its own idempotency key, to respect the
    // NuVizz daily-call ceiling/breaker and never fire a duplicate on a mid-batch retry.
    for (let k = 0; k < targets.length; k++) {
      const { r, idx } = targets[k];
      const refs = bulkRowNuvizzRefs(r);   // PRO (SHP) → NuVizz Stop Number; Order # (SO) → NuVizz Shipment Number
      const payloadRow = {
        name: r.name.trim(), addr1: r.addr1.trim(), addr2: r.addr2.trim() || null,
        city: r.city.trim(), state: r.state.trim(), zip: r.zip.trim(),
        stopNbr: refs.stopNbr, pro: refs.pro, itemDesc: r.itemDesc.trim() || null,
        pallets: r.pallets.trim() || null, loose: r.loose.trim() || null, weight: r.weight.trim() || null,
        price: (r.price || '').trim() || null,                    // → NuVizz Seal # (sealNbr)
        phone: (r.phone || '').trim() || null,                    // → to.contact.phone
        email: (r.email || '').trim() || null,                    // → to.contact.email
        dispatchNotes: (r.dispatchNotes || '').trim() || null,    // → comments[] ORD_IN (driver instructions)
      };
      // STABLE per-row op id: a fresh id per attempt made the server's idempotency ledger
      // useless — a lost response + a retry click double-created the order. The id lives on
      // the row (UI-only field like _push, autosaved with the draft) and is only minted once.
      const opId = r._opId || newClientOpId();
      let res;
      try { res = await callWrite('createStop', { row: payloadRow, settings }, { dryRun: false, clientOpId: opId, createdBy: 'dispatcher-bulk' }); }
      catch (e) { res = { ok: false, error: e?.message || 'network error' }; }
      const ok = !!(res.ok && res.result?.ok);
      if (!ok && !r._opId) setRows((rs) => rs.map((x) => (x === r ? { ...x, _opId: opId } : x)));
      out.push({ idx, name: payloadRow.name, ok, updated: !!res.result?.updated, nbr: res.result?.entityNbr || payloadRow.stopNbr || '', error: ok ? null : (res.error || res.result?.error || 'write error') });
      if (ok) {
        pushedLogRecords.push({
          // Log the PRO (SHP) as the order ref — that's what NuVizz now shows as this order's Stop Number.
          orderRef: refs.stopNbr, nuvizzNbr: res.result?.entityNbr || refs.stopNbr,
          name: r.name || '', addr1: r.addr1 || '', addr2: r.addr2 || '', city: r.city || '', state: r.state || '', zip: r.zip || '',
          itemDesc: r.itemDesc || '', pallets: r.pallets || '', loose: r.loose || '', weight: r.weight || '', price: r.price || '',
          phone: r.phone || '', dispatchNotes: r.dispatchNotes || '', updated: !!res.result?.updated,
          manifestNumber: null, serviceDate, pushedAt: new Date().toISOString(),
        });
      }
      setProgress({ done: k + 1, total: targets.length });
    }
    setBusy(false); setProgress(null);
    const okIdx = new Set(out.filter((o) => o.ok).map((o) => o.idx));
    // Keep failed + incomplete rows for a retry; drop the ones that succeeded.
    setRows((rs) => { const kept = rs.filter((r, idx) => !bulkRowIsBlank(r) && !okIdx.has(idx)); return kept.length ? kept : [bulkEmptyRow()]; });
    setResults({ created: out.filter((o) => o.ok && !o.updated).length, updated: out.filter((o) => o.ok && o.updated).length, failed: out.filter((o) => !o.ok).length, rows: out });
    // Durably log what was pushed so the Pushed tab shows it by date, from any device (best-effort,
    // our own Firestore log — a hiccup never fails the create). On a clean run, jump to the receipt.
    if (pushedLogRecords.length) {
      try {
        await fetch('/.netlify/functions/manifest-push-log', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ records: pushedLogRecords }),
        });
      } catch { /* history is best-effort */ }
      const today = etTodayStr();
      if (pushedDate !== today) setPushedDate(today); else fetchPushedLog(today);
      if (!out.some((o) => !o.ok)) setBulkView('pushed');
    }
  };

  // ── Create as a NEW load (item A): ONE async import creates the load + every order inline ──
  // vs the per-row path's N stop/sync/update pre-creates (+ the Save's per-add stop/info echo
  // reads). Target anatomy: 1 load/update + 1-2 load/info — any N. The import is ASYNC, so the
  // same client-side convergence discipline as the Routing Save applies: backoff polls
  // (6/10/15/25/25s), then ONE same-payload re-send, then report honestly. ok ONLY from the
  // read-back; a 404 while NuVizz creates the brand-new load just reads as not-yet-converged.
  const bulkNormNbr = (v) => { const s = String(v ?? '').trim().toUpperCase(); const t = s.replace(/^0+(?=.)/, ''); return t || s; };
  const verifyLoadCreate = async (nbr, wantNbrs, resendBody) => {
    const POLLS_MS = [6000, 10000, 15000, 25000, 25000];
    let reads = 0, resent = false;
    for (let pass = 0; pass < 2; pass++) {
      for (const [i, ms] of POLLS_MS.entries()) {
        setVerifyMsg(`Verifying load ${nbr} in NuVizz — ${resent ? 're-sent, ' : ''}read-back ${pass * POLLS_MS.length + i + 1}/${POLLS_MS.length * 2}…`);
        await new Promise((r) => setTimeout(r, ms));
        try {
          const res = await callWrite('getLoad', { loadNbr: nbr }, { dryRun: false });
          reads++;
          const stops = (res.result?.load?.stops || []).filter((s) => String(s.stopType || 'DO').toUpperCase() !== 'PU');
          const seqsOk = stops.length > 0 && stops.every((s) => s.stopSeq != null && Number.isFinite(Number(s.stopSeq)));
          const seen = stops.slice().sort((a, b) => Number(a.stopSeq ?? 1e9) - Number(b.stopSeq ?? 1e9)).map((s) => String(s.stopNbr));
          // eslint-disable-next-line no-console
          console.log(`[bulk-load-verify] poll ${pass}/${i} ${nbr}`, { requested: wantNbrs, readBack: seen, seqsOk });
          if (seqsOk && seen.length === wantNbrs.length && seen.every((n, k) => bulkNormNbr(n) === bulkNormNbr(wantNbrs[k]))) return { ok: true, reads, resent };
        } catch { /* transient read failure / not created yet — keep polling */ }
      }
      if (pass === 0) {
        // ONE re-send (a lost async import is rare but real). Fresh idempotency key so the
        // ledger can never swallow it — and WITHOUT createNew: if the first import landed
        // partially, the collision guard would refuse a "create" at an existing load, while a
        // plain declarative rebuild echoes what landed and inlines what didn't (self-healing).
        // A brand-new load has no membership history, so the Routing unstick ladder's
        // stuck-append state does not apply here.
        resent = true;
        const rebuild = { ...resendBody, loads: resendBody.loads.map(({ createNew, ...L }) => L) };
        try { await callWrite('commitBoard', rebuild, { dryRun: false, clientOpId: newClientOpId(), createdBy: 'dispatcher-bulk' }); } catch { /* the next polls decide */ }
      }
    }
    return { ok: false, reads, resent };
  };
  const createAsLoad = async () => {
    if (!canCreate) return;
    const targets = rows.filter((r) => !bulkRowIsBlank(r) && isPush(r));   // queued (unchecked) rows never join the load
    const nbr = loadNbr.trim();
    if (!live) { setResults({ loadMode: true, beta: true, msg: `○ Beta — would create load "${nbr}"${routeName.trim() ? ` (${routeName.trim()})` : ''} with ${targets.length} stop(s) in grid order via ONE async import (nothing sent). Flip to ● LIVE to create it.` }); return; }
    persistOrigin();
    const settings = { origin: { name: origin.name.trim(), addr1: origin.addr1.trim(), city: origin.city.trim(), state: origin.state.trim(), zip: origin.zip.trim() }, serviceDate, timeZone: 'America/New_York' };
    const payloadRows = targets.map((r) => ({
      name: r.name.trim(), addr1: r.addr1.trim(), addr2: r.addr2.trim() || null,
      city: r.city.trim(), state: r.state.trim(), zip: r.zip.trim(),
      // PRO (SHP) → NuVizz Stop Number; Order # (SO) → NuVizz Shipment Number. The load then
      // references its stops by that Stop Number (orderedStopNbrs = the PRO series), so it stays consistent.
      stopNbr: bulkRowNuvizzRefs(r).stopNbr || '', pro: bulkRowNuvizzRefs(r).pro, itemDesc: r.itemDesc.trim() || null,
      email: (r.email || '').trim() || null,                    // → to.contact.email (was silently dropped in load mode)
      pallets: r.pallets.trim() || null, loose: r.loose.trim() || null, weight: r.weight.trim() || null,
      price: (r.price || '').trim() || null,                    // → NuVizz Seal # (sealNbr) via buildStopPayload on the server
      phone: (r.phone || '').trim() || null,                    // → to.contact.phone
      dispatchNotes: (r.dispatchNotes || '').trim() || null,    // → comments[] ORD_IN (driver instructions)
    }));
    const body = {
      loads: [{ loadNbr: nbr, routeName: routeName.trim() || undefined, createNew: true, orderedStopNbrs: payloadRows.map((r) => r.stopNbr), newStops: payloadRows }],
      settings, origin: settings.origin, useImport: true,
    };
    setBusy(true); setResults(null); setVerifyMsg(`Sending ONE import for load ${nbr} (${payloadRows.length} stops)…`);
    let res;
    try { res = await callWrite('commitBoard', body, { dryRun: false, clientOpId: newClientOpId(), createdBy: 'dispatcher-bulk' }); }
    catch (e) { res = { ok: false, error: e?.message || 'network error' }; }
    const L0 = res?.result?.loads?.[0];
    // On success, only the PUSHED rows leave the grid — queued (unchecked) rows stay for a later push.
    const finish = (ok, msg, detail) => {
      setVerifyMsg(null); setBusy(false); setResults({ loadMode: true, ok, msg, detail });
      if (ok) setRows((rs) => { const kept = rs.filter((r) => !bulkRowIsBlank(r) && !isPush(r)); return kept.length ? [...kept, bulkEmptyRow()] : [bulkEmptyRow(), bulkEmptyRow(), bulkEmptyRow()]; });
    };
    if (res?.ok && L0?.ok) {
      const c = L0?.steps?.filter?.((s) => s.op === 'converge').reduce?.((n, s) => n + (s.reads || 0), 0) ?? 0;
      finish(true, `✓ Load "${nbr}" created with ${payloadRows.length} stop(s) in your grid order — confirmed by read-back.`, `Anatomy: 1 import + ${c || 1} read-back(s); zero per-stop pre-creates.`);
    } else if (L0?.pending) {
      const v = await verifyLoadCreate(nbr, L0.requestedOrder || body.loads[0].orderedStopNbrs, body);
      if (v.ok) finish(true, `✓ Load "${nbr}" created with ${payloadRows.length} stop(s) in your grid order — confirmed by read-back.`, `Anatomy: ${v.resent ? 2 : 1} import(s) + ${v.reads + 1} read-back(s); zero per-stop pre-creates.`);
      else finish(false, `✗ Load "${nbr}": NuVizz hasn't shown the created load in the sent order yet (after ${v.reads} read-backs${v.resent ? ' + one re-send' : ''}). Check the load in the portal — your rows are still in the grid; creating again with the SAME load number is safe (the import is declarative).`);
    } else {
      finish(false, `✗ Load "${nbr}" was not created: ${res?.error || L0?.error || res?.result?.error || 'write error'}. Your rows are still in the grid.`);
    }
  };

  // ── Manifest Intake helpers ──
  const intakeRows = intake?.rows || [];
  const heldRows = intakeRows.filter((r) => r._status !== 'pushed');
  const pushedRows = intakeRows.filter((r) => r._status === 'pushed');
  // The Pushed tab renders the cloud push-log for the selected day, mapped onto the row shape
  // the table already knows. (Today's log includes this session's pushes once they're written.)
  const cloudPushedRows = (pushedLog.records || []).map((r, i) => ({
    id: `log_${i}_${r.orderRef || r.nuvizzNbr || i}`,
    _status: 'pushed', _pushedNbr: r.nuvizzNbr || r.orderRef, _updated: !!r.updated,
    stopNbr: r.orderRef || '', name: r.name || '', addr1: r.addr1 || '', addr2: r.addr2 || '',
    city: r.city || '', state: r.state || '', zip: r.zip || '', itemDesc: r.itemDesc || '',
    pallets: r.pallets || '', loose: r.loose || '', weight: r.weight || '', phone: r.phone || '',
    dispatchNotes: r.dispatchNotes || '', price: r.price || '',
  }));
  const checkedHeld = heldRows.filter((r) => r._checked === true);
  const intakeTally = checkedHeld.reduce((a, r) => ({
    plt: a.plt + (Number(r.pallets) || 0), loose: a.loose + (Number(r.loose) || 0),
    lb: a.lb + (Number(r.weight) || 0), usd: a.usd + (Number(r.price) || 0),
  }), { plt: 0, loose: 0, lb: 0, usd: 0 });
  // ALL intake mutations no-op while a push is in flight (review finding): pushChecked works
  // from its click-time snapshot, so a mid-push edit/uncheck/remove would silently diverge from
  // what's actually being sent to NuVizz — and a mid-push discard nulled the state under the
  // in-flight loop. The row inputs/buttons are also disabled while intakeBusy (belt).
  const setIntakeCell = (id, key) => (e) => {
    const v = key === 'phone' ? fmtPhone(e.target.value) : e.target.value;
    if (intakeBusy) return;
    setIntake((it) => (it ? { ...it, rows: it.rows.map((r) => (r.id === id ? { ...r, [key]: v } : r)) } : it));
  };
  const toggleIntakeRow = (id) => { if (intakeBusy) return; setIntake((it) => (it ? { ...it, rows: it.rows.map((r) => (r.id === id ? { ...r, _checked: r._checked !== true } : r)) } : it)); };
  const allHeldChecked = heldRows.length > 0 && heldRows.every((r) => r._checked === true);
  const toggleIntakeAll = () => { if (intakeBusy) return; setIntake((it) => (it ? { ...it, rows: it.rows.map((r) => (r._status === 'pushed' ? r : { ...r, _checked: !allHeldChecked })) } : it)); };
  const removeIntakeRow = (id) => {
    if (intakeBusy) return;
    setIntake((it) => {
      if (!it) return it;
      const rows = it.rows.filter((r) => r.id !== id);
      return rows.length ? { ...it, rows } : null;   // last row gone → close the panel
    });
  };
  const discardIntake = () => {
    if (intakeBusy) return;   // never yank the state from under an in-flight push
    const held = heldRows.length;
    if (held && !window.confirm(`Discard this manifest? ${held} held order(s) will be dropped (they have NOT been sent to NuVizz).`)) return;
    setIntake(null); setIntakeResults(null); setIntakeOpen(null);
  };
  // Push the CHECKED held rows — a structural clone of createAll: same live/beta gate, same
  // settings shape, sequential createStop writes each under its own idempotency key. On green
  // the row moves to the Pushed tab (keeping NuVizz's number); on failure it stays Held with
  // the error inline. Queued (unchecked) rows are untouched.
  const pushChecked = async () => {
    const targets = checkedHeld.filter((r) => bulkRowMissing(r).length === 0);
    if (!targets.length || intakeBusy) return;
    if (!live) { setIntakeResults({ beta: true, msg: `○ Beta — would push ${targets.length} order(s) to NuVizz (nothing sent). Flip to ● LIVE to push.` }); return; }
    persistOrigin();
    const settings = { origin: { name: origin.name.trim(), addr1: origin.addr1.trim(), city: origin.city.trim(), state: origin.state.trim(), zip: origin.zip.trim() }, serviceDate, timeZone: 'America/New_York' };
    setIntakeBusy(true); setIntakeResults(null); setIntakeProgress({ done: 0, total: targets.length });
    let sent = 0, updated = 0, failed = 0;
    const pushedLogRecords = [];   // durable cloud push-history (written after the loop)
    for (let k = 0; k < targets.length; k++) {
      const r = targets[k];
      const payloadRow = {
        name: r.name.trim(), addr1: r.addr1.trim(), addr2: (r.addr2 || '').trim() || null,
        city: r.city.trim(), state: r.state.trim(), zip: r.zip.trim(),
        stopNbr: (r.stopNbr || '').trim() || null, pro: (r.pro || '').trim() || null, itemDesc: (r.itemDesc || '').trim() || null,
        pallets: (r.pallets || '').trim() || null, loose: (r.loose || '').trim() || null, weight: (r.weight || '').trim() || null,
        price: (r.price || '').trim() || null,                    // → NuVizz Seal # (sealNbr)
        phone: (r.phone || '').trim() || null,                    // → to.contact.phone
        email: (r.email || '').trim() || null,                    // → to.contact.email
        dispatchNotes: (r.dispatchNotes || '').trim() || null,    // → comments[] ORD_IN (driver instructions)
      };
      const opId = r._opId || newClientOpId();
      let res;
      try { res = await callWrite('createStop', { row: payloadRow, settings }, { dryRun: false, clientOpId: opId, createdBy: 'dispatcher-manifest' }); }
      catch (e) { res = { ok: false, error: e?.message || 'network error' }; }
      if (!(res.ok && res.result?.ok) && !r._opId) setIntake((it) => (it ? { ...it, rows: it.rows.map((x) => (x.id === r.id ? { ...x, _opId: opId } : x)) } : it));
      const ok = !!(res.ok && res.result?.ok);
      if (ok) {
        sent++; if (res.result?.updated) updated++;
        pushedLogRecords.push({
          orderRef: (r.stopNbr || '').trim() || null, nuvizzNbr: res.result?.entityNbr || (r.stopNbr || '').trim() || null,
          name: r.name || '', addr1: r.addr1 || '', addr2: r.addr2 || '', city: r.city || '', state: r.state || '', zip: r.zip || '',
          itemDesc: r.itemDesc || '', pallets: r.pallets || '', loose: r.loose || '', weight: r.weight || '', price: r.price || '',
          phone: r.phone || '', dispatchNotes: r.dispatchNotes || '', updated: !!res.result?.updated,
          manifestNumber: intake?.manifest?.manifestNumber || null, serviceDate, pushedAt: new Date().toISOString(),
        });
      } else failed++;
      // Null-guarded: mutations are frozen during a push, but never trust that with LIVE
      // writes in flight — a missing intake must degrade to a no-op, not a render crash.
      setIntake((it) => (it ? { ...it, rows: it.rows.map((x) => (x.id !== r.id ? x
        : ok ? { ...x, _status: 'pushed', _checked: false, _pushedNbr: res.result?.entityNbr || x.stopNbr, _updated: !!res.result?.updated, _error: null }
        : { ...x, _error: res.error || res.result?.error || 'write error' })) } : it));
      setIntakeProgress({ done: k + 1, total: targets.length });
    }
    // Durably log what was pushed so the Pushed tab can show it by date, from any device
    // (best-effort, Firestore only — a log hiccup never fails the push).
    if (pushedLogRecords.length) {
      try {
        await fetch('/.netlify/functions/manifest-push-log', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ records: pushedLogRecords }),
        });
      } catch { /* history is best-effort */ }
      const today = etTodayStr();
      if (pushedDate !== today) setPushedDate(today); else fetchPushedLog(today);
    }
    setIntakeBusy(false); setIntakeProgress(null);
    setIntakeResults({ ok: failed === 0, msg: failed
      ? `⚠ Pushed ${sent} of ${targets.length} — ${failed} failed (kept in Held with the reason).`
      : `✓ Pushed ${sent} order(s) to NuVizz${updated ? ` (${updated} updated existing)` : ''} — they land UNPLANNED; plan them in Routing.` });
    if (failed === 0) setIntakeTab('pushed');
  };
  const canPushIntake = originComplete && !!serviceDate && !intakeBusy
    && checkedHeld.length > 0 && checkedHeld.every((r) => bulkRowMissing(r).length === 0);

  const gridInput = 'w-full border border-slate-300 rounded px-1.5 py-1 text-[12px] focus:outline-none focus:ring-1 focus:ring-blue-300';
  // Same as gridInput but WITHOUT w-full, so a fixed width (w-12 / w-16 …) actually applies. Tailwind
  // lets w-full win over a w-12 when both are on the element, which stretched the number/phone columns.
  const numInput = 'border border-slate-300 rounded px-1.5 py-1 text-[12px] focus:outline-none focus:ring-1 focus:ring-blue-300';

  return (
    <div className="flex-1 min-h-0 overflow-auto bg-slate-50">
      <div className="w-full p-4 space-y-4">
        {/* Header + Beta/Live */}
        <div className="flex items-center justify-between gap-3">
          <div>
            <h1 className="text-lg font-bold text-slate-800 flex items-center gap-2"><LayoutList size={18} /> Bulk Add</h1>
            <p className="text-[12px] text-slate-500">Create many orders at once — fill the grid or paste/drop a spreadsheet. Each lands <b>unplanned</b>.</p>
          </div>
          <button
            onClick={() => setLive((v) => !v)}
            title={live ? 'LIVE — Create sends the orders to NuVizz. Click for Beta (preview only).' : 'BETA — Create only previews (nothing sent). Click to go Live.'}
            className={`inline-flex items-center gap-1 text-[12px] font-bold px-2.5 py-1.5 rounded border shrink-0 ${live ? 'border-red-600 bg-red-600 text-white' : 'border-slate-300 bg-white text-slate-600 hover:bg-slate-50'}`}
          >
            {live ? '● LIVE' : '○ Beta'}
          </button>
        </div>

        {/* Orders grid vs the durable Pushed-to-NuVizz receipt (same cloud log the manifest flow writes) */}
        <div className="flex items-center gap-2 border-b border-slate-200 pb-1">
          <TabBtn label="Orders" active={bulkView === 'orders'} onClick={() => setBulkView('orders')} icon={<LayoutList size={13} />} />
          <TabBtn label="Pushed to NuVizz" active={bulkView === 'pushed'} onClick={() => { setBulkView('pushed'); fetchPushedLog(pushedDate); }} icon={<FileCheck size={13} />} />
        </div>

        {bulkView === 'orders' && (<>
        {/* Shared pickup + service date (applies to the whole batch) */}
        <div className="bg-white border border-slate-200 rounded-lg p-3">
          <button onClick={() => setShowOrigin((v) => !v)} className="w-full flex items-center justify-between text-left">
            <span className="text-[13px] font-semibold text-slate-700">Pickup + date <span className="font-normal text-slate-400">(applies to all rows)</span>{!originComplete && <span className="ml-2 text-[11px] font-normal text-amber-600">— required</span>}</span>
            <span className="text-[12px] text-slate-500 inline-flex items-center gap-1">
              {originComplete && !showOrigin ? `${origin.name} · ${origin.city}, ${origin.state} · ${serviceDate}` : ''}
              {showOrigin ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
            </span>
          </button>
          {showOrigin && (
            <div className="mt-3 space-y-2">
              {origins.length > 0 && (
                <label className="block">
                  <span className="text-[11px] font-medium text-slate-500">Pickup location</span>
                  <select value={originIsSaved ? originKey(origin) : ''} onChange={pickOrigin} className="mt-0.5 w-full border border-slate-300 rounded px-2 py-1.5 text-sm bg-white focus:outline-none focus:ring-2 focus:ring-blue-300">
                    {origins.map((o) => <option key={originKey(o)} value={originKey(o)}>{o.name} — {o.city}, {o.state}</option>)}
                    <option value="">＋ New pickup location…</option>
                  </select>
                </label>
              )}
              <OrderField label="Pickup name" req value={origin.name} onChange={setOrig('name')} placeholder="Buford Terminal" />
              <OrderField label="Address" req value={origin.addr1} onChange={setOrig('addr1')} placeholder="123 Depot Rd" />
              <div className="grid grid-cols-6 gap-2">
                <OrderField className="col-span-3" label="City" req value={origin.city} onChange={setOrig('city')} placeholder="Buford" />
                <OrderField className="col-span-1" label="State" req value={origin.state} onChange={setOrig('state')} placeholder="GA" />
                <OrderField className="col-span-2" label="ZIP" req value={origin.zip} onChange={setOrig('zip')} placeholder="30518" />
              </div>
              <div className="flex items-end gap-3 flex-wrap">
                <OrderField label="Service date" req type="date" value={serviceDate} onChange={(e) => setServiceDate(e.target.value)} className="max-w-[200px]" />
                <button onClick={persistOrigin} disabled={!originComplete} title={originComplete ? 'Save this pickup location for reuse' : 'Fill all pickup fields to save'} className={`text-[12px] font-medium inline-flex items-center gap-1 px-2.5 py-1 rounded border ${originComplete ? 'border-slate-300 bg-white text-slate-700 hover:bg-slate-50' : 'border-slate-200 bg-slate-50 text-slate-400 cursor-not-allowed'}`}><Save size={13} /> {originIsSaved ? 'Update pickup location' : 'Save pickup location'}</button>
                {originSaved && <span className="text-[12px] font-medium text-green-700 inline-flex items-center gap-1"><FileCheck size={13} /> Saved</span>}
              </div>
            </div>
          )}
        </div>

        {/* Destination: unplanned orders vs ONE new load (item A — inline import creation) */}
        <div className="bg-white border border-slate-200 rounded-lg p-3 space-y-2">
          <div className="text-[13px] font-semibold text-slate-700">Create as</div>
          <div className="flex flex-col sm:flex-row gap-2">
            <label className={`flex-1 border rounded-lg px-3 py-2 cursor-pointer ${!asLoad ? 'border-blue-400 bg-blue-50/60' : 'border-slate-200 hover:bg-slate-50'}`}>
              <input type="radio" name="bulk-dest" checked={!asLoad} onChange={() => setAsLoad(false)} className="mr-1.5 align-middle" />
              <span className="text-[12px] font-semibold text-slate-700 align-middle">Unplanned orders</span>
              <div className="text-[11px] text-slate-500 mt-0.5">One create per row — plan them onto loads in Routing afterwards.</div>
            </label>
            <label className={`flex-1 border rounded-lg px-3 py-2 cursor-pointer ${asLoad ? 'border-blue-400 bg-blue-50/60' : 'border-slate-200 hover:bg-slate-50'}`}>
              <input type="radio" name="bulk-dest" checked={asLoad} onChange={() => setAsLoad(true)} className="mr-1.5 align-middle" />
              <span className="text-[12px] font-semibold text-slate-700 align-middle">⚡ A NEW load (one import)</span>
              <div className="text-[11px] text-slate-500 mt-0.5">Rows top-to-bottom become the driver&apos;s stop order. ONE async import creates the load + every order — no per-row creates. Every row needs its Order&nbsp;#.</div>
            </label>
          </div>
          {asLoad && (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 pt-1">
              <OrderField label="Load number" req value={loadNbr} onChange={(e) => setLoadNbr(e.target.value)} placeholder="e.g. an EMPTY Draft load's number, or a new one" />
              <OrderField label="Route name (shown on the board)" value={routeName} onChange={(e) => setRouteName(e.target.value)} placeholder="e.g. SUW 3" />
              <div className="sm:col-span-2 text-[11px] text-slate-500">
                Point this at an <b>empty Draft load&apos;s number</b> to build onto it, or type a <b>new number</b> to create the load outright. If the load number already carries stops, the create is refused (edit that load from the board instead) — and every Order&nbsp;# is first checked against NuVizz: a number that already exists is refused, never duplicated.
              </div>
            </div>
          )}
        </div>

        {/* Import: drop / choose / paste */}
        <div className="bg-white border border-slate-200 rounded-lg p-3 space-y-2">
          <div className="text-[13px] font-semibold text-slate-700">Import a spreadsheet <span className="font-normal text-slate-400">(optional)</span></div>
          <div
            onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
            onDragLeave={() => setDragOver(false)}
            onDrop={(e) => { e.preventDefault(); setDragOver(false); onFiles(e.dataTransfer?.files); }}
            className={`rounded-lg border-2 border-dashed px-3 py-4 text-center text-[12px] ${dragOver ? 'border-blue-400 bg-blue-50 text-blue-700' : 'border-slate-300 text-slate-500'}`}
          >
            <FileText size={18} className="inline mb-1" /><br />
            {importBusy
              ? <span className="text-blue-700 font-medium inline-flex items-center gap-1.5"><RefreshCw size={13} className="animate-spin" /> {importBusy}</span>
              : <>Drop a <b>.xlsx</b>, <b>.csv</b>, or scanned <b>manifest .pdf</b>(s) here — several PDFs at once is fine, each is read in turn — or <button onClick={() => fileRef.current?.click()} className="text-blue-600 underline font-medium">choose files</button>.</>}
            <input ref={fileRef} type="file" multiple accept=".csv,.tsv,.txt,.xlsx,.xls,.pdf" className="hidden" onChange={(e) => { onFiles(e.target.files); e.target.value = ''; }} />
          </div>
          <div className="text-[11px] text-slate-500">…or paste rows copied from Excel / Google Sheets:</div>
          <textarea
            value={pasteText} onChange={(e) => setPasteText(e.target.value)}
            placeholder={'Consignee\tAddress\tCity\tState\tZip\tItem\nACME\t500 Main St\tLawrenceville\tGA\t30046\tappliances'}
            className="w-full h-20 border border-slate-300 rounded px-2 py-1.5 text-[12px] font-mono focus:outline-none focus:ring-2 focus:ring-blue-300"
          />
          <div className="flex items-center gap-2">
            <button onClick={() => ingestText(pasteText)} disabled={!pasteText.trim()} className={`text-[12px] font-medium inline-flex items-center gap-1 px-2.5 py-1 rounded border ${pasteText.trim() ? 'border-slate-300 bg-white text-slate-700 hover:bg-slate-50' : 'border-slate-200 bg-slate-50 text-slate-400 cursor-not-allowed'}`}>Load pasted rows</button>
            {importErr && <span className="text-[12px] text-red-600 inline-flex items-center gap-1"><AlertTriangle size={13} /> {importErr}</span>}
          </div>
          {importInfo && (
            <div className="text-[12px] text-emerald-800 bg-emerald-50 border border-emerald-200 rounded px-2 py-1">
              {importInfo}
              {autoImportUndo && <button onClick={undoAutoImport} className="ml-2 underline font-medium hover:text-emerald-950">Wrong columns? Undo &amp; map manually</button>}
            </div>
          )}

          {/* Column mapping confirm */}
          {importer && (
            <div className="mt-2 border border-blue-200 bg-blue-50/50 rounded-lg p-3 space-y-2">
              <div className="text-[12px] font-semibold text-slate-700">Map columns <span className="font-normal text-slate-500">({importer.dataRows.length} row{importer.dataRows.length === 1 ? '' : 's'}{importer.hasHeader ? '' : ' — no header detected, map by position'})</span></div>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                {importer.columns.map((c) => (
                  <label key={c.idx} className="block">
                    <span className="text-[11px] text-slate-500 truncate block" title={c.label}>{c.label}</span>
                    <select
                      value={importer.mapping[c.idx] || ''}
                      onChange={(e) => setImporter((im) => ({ ...im, mapping: { ...im.mapping, [c.idx]: e.target.value } }))}
                      className="mt-0.5 w-full border border-slate-300 rounded px-1.5 py-1 text-[12px] bg-white"
                    >
                      <option value="">— skip —</option>
                      {BULK_FIELDS.map((f) => <option key={f.key} value={f.key}>{f.label}{f.required ? ' *' : ''}</option>)}
                    </select>
                  </label>
                ))}
              </div>
              <div className="flex items-center gap-2">
                {(() => {
                  // Honest count: what WILL land (blank + residue rows excluded), not the raw row count.
                  const mapped = mappedRowsToOrders(importer.dataRows, importer.mapping).filter((o) => !bulkRowIsBlank(o));
                  const n = mapped.filter((o) => !bulkRowIsGhost(o)).length;
                  const skip = importer.dataRows.length - n;
                  return (
                    <button onClick={applyImport} disabled={!n} className={`text-[12px] font-semibold inline-flex items-center gap-1 px-3 py-1 rounded text-white ${n ? '' : 'opacity-40 cursor-not-allowed'}`} style={{ background: BRAND }}>
                      <Plus size={13} /> Import {n} order{n === 1 ? '' : 's'}{skip > 0 ? ` (${skip} skipped)` : ''}
                    </button>
                  );
                })()}
                <button onClick={() => setImporter(null)} className="text-[12px] font-medium px-2.5 py-1 rounded border border-slate-300 bg-white text-slate-600 hover:bg-slate-50">Cancel</button>
              </div>
            </div>
          )}
        </div>

        {/* ── Manifest Intake — the dedicated review panel for OCR'd manifests (Chad's mockup):
            stat tiles, Held/Pushed tabs, check-to-push with a live tally, per-order phone/notes/
            price, expandable address editor, and Push to NuVizz through the same guarded path. ── */}
        {intake && (() => {
          const m = intake.manifest || {};
          const carrierWord = String(m.carrier || 'Estes').trim().split(/\s+/)[0];
          const merged = intake.mergedManifests || [m];
          const multiManifest = merged.length > 1;
          const rowsShown = intakeTab === 'held' ? heldRows : cloudPushedRows;
          const intakeCols = intakeTab === 'held' ? 12 : 11;   // the checkbox column exists only on Held
          const unitSum = intakeRows.reduce((a, r) => a + (Number(r.pallets) || 0), 0);
          const wgtSum = intakeRows.reduce((a, r) => a + (Number(r.weight) || 0), 0);
          // Merged manifests: sum the declared header totals across all of them (fall back to the
          // per-row sums). A single manifest keeps its own header value exactly as before.
          const mnfUnits = multiManifest ? merged.reduce((a, mm) => a + (Number(mm?.totalUnits) || 0), 0) || unitSum : (m.totalUnits ?? unitSum);
          const mnfWeight = multiManifest ? merged.reduce((a, mm) => a + (Number(mm?.totalWeight) || 0), 0) || wgtSum : (m.totalWeight ?? wgtSum);
          return (
            <div className="bg-white border border-slate-200 rounded-lg p-3 space-y-3">
              <div className="flex items-start justify-between gap-3">
                <div>
                  <div className="text-[14px] font-bold text-slate-800">{carrierWord} Manifest {m.manifestNumber ? `#${m.manifestNumber}` : (m.fileName || '')}{multiManifest ? ` + ${merged.length - 1} more` : ''} — Bulk Add</div>
                  <div className="text-[11px] text-slate-500 mt-0.5">
                    Pickup: {origin.name || '—'} · Source: {m.carrier || 'manifest'} {m.manifestDate || ''}{m.manifestTime ? ` ${m.manifestTime}` : ''}{m.trailer ? ` · Trailer ${m.trailer}` : ''}{multiManifest ? ` · ${merged.length} manifests merged` : ''}
                  </div>
                </div>
                <div className="flex items-center gap-2 shrink-0">
                  {!live && <span className="text-[10px] font-bold uppercase tracking-wide bg-slate-800 text-white rounded-full px-2.5 py-1">● Preview mode — nothing sent</span>}
                  <button onClick={discardIntake} disabled={intakeBusy} title={intakeBusy ? 'Wait for the push to finish' : 'Discard this manifest (held rows are dropped)'} className={`text-slate-400 ${intakeBusy ? 'opacity-40 cursor-not-allowed' : 'hover:text-red-600'}`}><X size={16} /></button>
                </div>
              </div>
              <div className="flex gap-2 flex-wrap">
                <EngineStatTile label="Orders" value={intakeRows.length} hint={!multiManifest && m.totalPros != null ? `Manifest header says ${m.totalPros} PROs` : (multiManifest ? `${merged.length} manifests` : '')} />
                <EngineStatTile label="Mnf units" value={mnfUnits} hint="Manifest handling units (→ Pallets)" />
                <EngineStatTile label="Weight" value={`${Number(mnfWeight || 0).toLocaleString()} lb`} />
                <EngineStatTile label="Pickup" value={origin.name || '—'} hint="Set in the Pickup + date card above" />
              </div>
              <div className="text-[12px] text-blue-900 bg-blue-50 border border-blue-200 rounded-lg px-3 py-2">
                Enter <b>Pallets</b>, <b>Loose pcs</b>, <b>Phone</b>, <b>Dispatch notes</b> and <b>Price</b> per order (Price → NuVizz Seal #), then <b>check the rows to push</b> and hit <b>Push to NuVizz</b>. Unchecked orders stay in the <b>Held</b> queue (saved on this device). Pickup = <b>{origin.name || 'your pickup'}</b> for every order — set it in the Pickup + date card above. Expand a row (▸) to edit its address.
              </div>
              {/* MISSING ORDERS — the manifest's own header count vs what was read. Red and on
                  its own, above the amber line: "this file is short 6 orders" is not the same
                  kind of news as "row 12's ZIP looks short", and it was invisible when the two
                  were joined into one ' · ' string. */}
              {(intake.shortfalls || []).length > 0 && (
                <div className="text-[12px] text-red-900 bg-red-50 border border-red-300 rounded-lg px-3 py-2">
                  <div className="font-semibold">⚠ Orders are missing — do not push until you have checked the paper.</div>
                  {intake.shortfalls.map((s, i) => (
                    <div key={i} className="mt-0.5">
                      <b>{s.fileName}</b>: the manifest header says <b>{s.expected}</b> PROs but only <b>{s.read}</b> were read — <b>{s.shortBy} order{s.shortBy === 1 ? '' : 's'} short</b>.
                    </div>
                  ))}
                </div>
              )}
              {(intake.warnings || []).length > 0 && (
                <div className="text-[12px] text-amber-800 bg-amber-50 border border-amber-200 rounded-lg px-3 py-2">
                  ⚠ {intake.warnings.join(' · ')}
                </div>
              )}
              <div className="flex items-center gap-2">
                <TabBtn label="Bulk Add — Held" badge={heldRows.length} active={intakeTab === 'held'} onClick={() => setIntakeTab('held')} icon={<Clock size={13} />} />
                <TabBtn label="Pushed to NuVizz" badge={pushedRows.length} active={intakeTab === 'pushed'} onClick={() => setIntakeTab('pushed')} icon={<FileCheck size={13} />} />
              </div>
              {intakeTab === 'held' && (
                <div className="flex items-center justify-between text-[12px] text-slate-600 border-b border-slate-100 pb-2">
                  <label className="inline-flex items-center gap-2">
                    <input type="checkbox" checked={allHeldChecked} onChange={toggleIntakeAll} disabled={!heldRows.length || intakeBusy} className="align-middle accent-blue-600" />
                    <span className="font-medium">Select all</span> <span className="text-slate-400">check rows to push</span>
                  </label>
                  <span className="tabular-nums font-medium">{checkedHeld.length} checked · {intakeTally.plt} plt · {intakeTally.loose} loose · {intakeTally.lb.toLocaleString()} lb · ${intakeTally.usd.toFixed(2)}</span>
                </div>
              )}
              {intakeTab === 'pushed' && (
                <div className="flex items-center flex-wrap gap-2 text-[12px] text-slate-600 border-b border-slate-100 pb-2">
                  <span className="font-medium">Pushed on</span>
                  <input
                    type="date"
                    value={pushedDate}
                    max={etTodayStr()}
                    onChange={(e) => setPushedDate(e.target.value || etTodayStr())}
                    className="border border-slate-300 rounded px-2 py-1 text-[12px]"
                  />
                  {pushedDate !== etTodayStr() && (
                    <button onClick={() => setPushedDate(etTodayStr())} className="text-[11px] text-blue-700 hover:underline">Today</button>
                  )}
                  <button onClick={() => fetchPushedLog(pushedDate)} title="Refresh" className="text-slate-400 hover:text-slate-700"><RefreshCw size={13} className={pushedLog.loading ? 'animate-spin' : ''} /></button>
                  <span className="ml-auto tabular-nums font-medium">
                    {pushedLog.loading ? 'loading…' : `${cloudPushedRows.length} pushed`}
                    {pushedDate === etTodayStr() ? ' today' : ''}
                  </span>
                  {pushedLog.error && <span className="text-[11px] text-amber-700 w-full">History unavailable: {pushedLog.error}</span>}
                </div>
              )}
              <div className="overflow-x-auto">
                <table className="text-[12px] border-collapse w-full">
                  <thead>
                    <tr className="text-left text-[10px] uppercase tracking-wide text-slate-500">
                      {intakeTab === 'held' && <th className="pr-1 pb-1 w-7"></th>}
                      <th className="pr-2 pb-1 w-6">#</th>
                      <th className="px-1 pb-1">Order ref</th>
                      <th className="px-1 pb-1">Consignee (delivery)</th>
                      <th className="px-1 pb-1">Items</th>
                      <th className="px-1 pb-1">Pallets</th>
                      <th className="px-1 pb-1">Loose</th>
                      <th className="px-1 pb-1">Weight</th>
                      <th className="px-1 pb-1">Phone</th>
                      <th className="px-1 pb-1">Dispatch notes</th>
                      <th className="px-1 pb-1">Price</th>
                      <th className="pb-1"></th>
                    </tr>
                  </thead>
                  <tbody>
                    {rowsShown.length === 0 && (
                      <tr><td colSpan={intakeCols} className="py-3 text-center text-slate-400">{intakeTab === 'held' ? 'Nothing held — every order has been pushed.' : (pushedLog.loading ? 'Loading…' : `Nothing pushed on ${pushedDate}.`)}</td></tr>
                    )}
                    {rowsShown.map((r, i) => {
                      const missing = bulkRowMissing(r);
                      const open = intakeOpen === r.id;
                      const pushed = r._status === 'pushed';
                      return (
                        <React.Fragment key={r.id}>
                          <tr className="align-middle border-t border-slate-100">
                            {intakeTab === 'held' && (
                              <td className="pr-1 py-1"><input type="checkbox" checked={r._checked === true} onChange={() => toggleIntakeRow(r.id)} disabled={intakeBusy} className="align-middle accent-blue-600" /></td>
                            )}
                            <td className="pr-2 py-1 text-slate-400 tabular-nums">{i + 1}</td>
                            <td className="px-1 py-1">
                              <button onClick={() => setIntakeOpen(open ? null : r.id)} title={open ? 'Collapse' : 'Expand — edit address / details'} className="inline-flex items-center gap-1">
                                <ChevronRight size={12} className={`text-slate-400 transition-transform ${open ? 'rotate-90' : ''}`} />
                                <span className="font-mono text-[10px] text-slate-600 bg-slate-100 border border-slate-200 rounded px-1.5 py-0.5">{pushed ? (r._pushedNbr || r.stopNbr) : (r.stopNbr || '—')}</span>
                              </button>
                            </td>
                            <td className="px-1 py-1 min-w-[170px]">
                              <div className="font-semibold text-slate-800 leading-tight">{r.name || <span className="text-amber-600">name missing</span>}{pushed && r._updated && <span className="ml-1 text-[9px] font-bold text-amber-600 uppercase">updated</span>}</div>
                              {(r.addr1 || r.addr2) && <div className="text-[10px] text-slate-600 leading-tight">{[r.addr1, r.addr2].filter(Boolean).join(', ')}</div>}
                              <div className="text-[10px] text-slate-500">{[r.city, r.state].filter(Boolean).join(', ')} {r.zip}</div>
                              {r._error && <div className="text-[10px] text-red-600 mt-0.5"><AlertTriangle size={10} className="inline -mt-0.5" /> {r._error}</div>}
                              {!pushed && !r._error && missing.length > 0 && <div className="text-[10px] text-amber-600 mt-0.5">need {missing.length} field(s) — expand ▸</div>}
                            </td>
                            {pushed ? (
                              <>
                                <td className="px-1 py-1 max-w-[240px] truncate text-slate-600" title={r.itemDesc}>{r.itemDesc || '—'}</td>
                                <td className="px-1 py-1 tabular-nums">{r.pallets || '—'}</td>
                                <td className="px-1 py-1 tabular-nums">{r.loose || '—'}</td>
                                <td className="px-1 py-1 tabular-nums">{r.weight || '—'}</td>
                                <td className="px-1 py-1">{r.phone || '—'}</td>
                                <td className="px-1 py-1 max-w-[240px] truncate" title={r.dispatchNotes}>{r.dispatchNotes || '—'}</td>
                                <td className="px-1 py-1 tabular-nums">{r.price ? `$${r.price}` : '—'}</td>
                                <td className="py-1 text-green-600"><FileCheck size={14} /></td>
                              </>
                            ) : (
                              <>
                                <td className="px-1 py-1"><input value={r.itemDesc} onChange={setIntakeCell(r.id, 'itemDesc')} disabled={intakeBusy} placeholder="what's shipping" className={`${gridInput} min-w-[200px]`} /></td>
                                <td className="px-1 py-1"><input value={r.pallets} onChange={setIntakeCell(r.id, 'pallets')} disabled={intakeBusy} className={`${numInput} w-12 text-right`} /></td>
                                <td className="px-1 py-1"><input value={r.loose} onChange={setIntakeCell(r.id, 'loose')} disabled={intakeBusy} className={`${numInput} w-12 text-right`} /></td>
                                <td className="px-1 py-1"><input value={r.weight} onChange={setIntakeCell(r.id, 'weight')} disabled={intakeBusy} className={`${numInput} w-16 text-right`} /></td>
                                <td className="px-1 py-1"><input value={r.phone} onChange={setIntakeCell(r.id, 'phone')} disabled={intakeBusy} placeholder="add phone" className={`${numInput} w-32`} /></td>
                                <td className="px-1 py-1"><input value={r.dispatchNotes} onChange={setIntakeCell(r.id, 'dispatchNotes')} disabled={intakeBusy} placeholder="dispatch notes" className={`${gridInput} min-w-[220px]`} /></td>
                                <td className="px-1 py-1"><input value={r.price} onChange={setIntakeCell(r.id, 'price')} disabled={intakeBusy} placeholder="$" className={`${numInput} w-16 text-right`} /></td>
                                <td className="py-1"><button onClick={() => removeIntakeRow(r.id)} disabled={intakeBusy} title="Remove this order from the manifest intake" className={`text-slate-400 ${intakeBusy ? 'opacity-40 cursor-not-allowed' : 'hover:text-red-600'}`}><X size={13} /></button></td>
                              </>
                            )}
                          </tr>
                          {open && (
                            <tr className="border-t border-slate-50">
                              <td colSpan={intakeCols} className="px-6 py-2 bg-slate-50/70">
                                <div className="grid grid-cols-2 sm:grid-cols-3 gap-2 max-w-[900px]">
                                  <OrderField label="Consignee / business" value={r.name} onChange={setIntakeCell(r.id, 'name')} disabled={pushed || intakeBusy} />
                                  <OrderField label="Address" value={r.addr1} onChange={setIntakeCell(r.id, 'addr1')} disabled={pushed || intakeBusy} />
                                  <OrderField label="Suite / unit" value={r.addr2} onChange={setIntakeCell(r.id, 'addr2')} disabled={pushed || intakeBusy} />
                                  <OrderField label="City" value={r.city} onChange={setIntakeCell(r.id, 'city')} disabled={pushed || intakeBusy} />
                                  <OrderField label="State" value={r.state} onChange={setIntakeCell(r.id, 'state')} disabled={pushed || intakeBusy} />
                                  <OrderField label="ZIP" value={r.zip} onChange={setIntakeCell(r.id, 'zip')} disabled={pushed || intakeBusy} />
                                  <OrderField label="Item description" value={r.itemDesc} onChange={setIntakeCell(r.id, 'itemDesc')} disabled={pushed || intakeBusy} />
                                  <OrderField label="Order # (ref)" value={r.stopNbr} onChange={setIntakeCell(r.id, 'stopNbr')} disabled={pushed || intakeBusy} />
                                  <OrderField label="PRO (barcode digits)" value={r.pro} onChange={setIntakeCell(r.id, 'pro')} disabled={pushed || intakeBusy} />
                                </div>
                              </td>
                            </tr>
                          )}
                        </React.Fragment>
                      );
                    })}
                  </tbody>
                </table>
              </div>
              {intakeProgress && (
                <div className="rounded-lg px-3 py-2 text-[13px] bg-blue-50 text-blue-800 border border-blue-200">⏳ Pushing {intakeProgress.done}/{intakeProgress.total}…</div>
              )}
              {intakeResults && (
                <div className={`rounded-lg px-3 py-2 text-[13px] ${intakeResults.beta ? 'bg-slate-100 text-slate-700 border border-slate-200' : intakeResults.ok ? 'bg-green-50 text-green-800 border border-green-200' : 'bg-amber-50 text-amber-800 border border-amber-200'}`}>{intakeResults.msg}</div>
              )}
              {intakeTab === 'held' && (
                <div className="flex items-center justify-between gap-3">
                  <span className="text-[12px] text-slate-500">
                    {!originComplete ? 'Set the pickup + service date first.'
                      : checkedHeld.length === 0 ? 'Check ☑ the rows to push — unchecked rows stay Held for a later push.'
                      : !canPushIntake ? 'A checked row is missing required fields — expand it (▸) and fill them.'
                      : live ? `Ready — this WILL create ${checkedHeld.length} order(s) in NuVizz. ${heldRows.length - checkedHeld.length} stay held.`
                      : `Beta — previews the push (${checkedHeld.length} checked).`}
                  </span>
                  <button onClick={pushChecked} disabled={!canPushIntake} className={`inline-flex items-center gap-1.5 px-4 py-2 rounded font-semibold text-white text-sm shrink-0 ${canPushIntake ? '' : 'opacity-40 cursor-not-allowed'}`} style={{ background: live ? '#dc2626' : BRAND }}>
                    <Send size={14} /> {intakeBusy ? 'Pushing…' : live ? `Push ${checkedHeld.length || ''} to NuVizz (LIVE)` : 'Preview push (Beta)'}
                  </button>
                </div>
              )}
            </div>
          );
        })()}

        {/* The grid */}
        <div className="bg-white border border-slate-200 rounded-lg p-3 space-y-2">
          <div className="flex items-center justify-between">
            <div className="text-[13px] font-semibold text-slate-700">Orders <span className="font-normal text-slate-400">({activeRows.length} filled{incompleteCount ? ` · ${incompleteCount} incomplete` : ''}{queuedCount ? ` · ${queuedCount} queued for later` : ''})</span></div>
            <div className="flex items-center gap-2">
              <button onClick={addRow} className="text-[12px] font-medium inline-flex items-center gap-1 px-2.5 py-1 rounded border border-slate-300 bg-white text-slate-700 hover:bg-slate-50"><Plus size={13} /> Add row</button>
              <button onClick={clearRows} className="text-[12px] font-medium inline-flex items-center gap-1 px-2.5 py-1 rounded border border-slate-300 bg-white text-slate-600 hover:bg-red-50 hover:text-red-700 hover:border-red-200"><Trash2 size={13} /> Clear</button>
            </div>
          </div>
          <div className="overflow-x-auto">
            <table className="text-[12px] border-collapse">
              <thead>
                <tr className="text-left text-[11px] text-slate-500">
                  <th className="pr-1 pb-1 w-7" title="Push to NuVizz on Create — unchecked rows stay QUEUED in the grid (saved on this device) for a later push">
                    <input type="checkbox" checked={allPushed} onChange={toggleAllPush} disabled={!activeRows.length} className="align-middle accent-blue-600" title="Check/uncheck all filled rows" />
                  </th>
                  <th className="pr-2 pb-1 font-medium w-6">#</th>
                  {BULK_FIELDS.map((f) => <th key={f.key} className={`px-1 pb-1 font-medium whitespace-nowrap ${f.key === 'name' ? 'sticky left-0 z-20 bg-white border-r border-slate-200' : ''}`}>{f.label}{(f.required || (asLoad && f.key === 'pro')) && <span className="text-red-500"> *</span>}</th>)}
                  <th className="px-1 pb-1 font-medium">Status</th>
                  <th className="pb-1"></th>
                </tr>
              </thead>
              <tbody>
                {rows.map((r, i) => {
                  const blank = bulkRowIsBlank(r);
                  const missing = blank ? [] : missingFor(r);
                  const queued = !blank && !isPush(r);
                  return (
                    <tr key={i} className={`align-top ${queued ? 'opacity-60' : ''}`}>
                      <td className="pr-1 py-0.5">
                        {!blank && <input type="checkbox" checked={isPush(r)} onChange={() => togglePush(i)} className="align-middle accent-blue-600" title={queued ? 'Queued — will NOT be pushed; stays in the grid for later' : 'Will be pushed on Create'} />}
                      </td>
                      <td className="pr-2 py-0.5 text-slate-400 tabular-nums">{i + 1}</td>
                      {BULK_FIELDS.map((f) => (
                        // Consignee is STICKY-LEFT: sliding the grid out to Phone/Notes/Status
                        // (phones especially) kept the values but lost WHICH ORDER each row was —
                        // the identity column now stays pinned while the rest scrolls under it.
                        <td key={f.key} className={`px-1 py-0.5 ${f.key === 'name' ? 'sticky left-0 z-10 bg-white border-r border-slate-200' : ''}`}>
                          <input value={r[f.key]} onChange={setCell(i, f.key)} className={`${gridInput} ${f.key === 'name' || f.key === 'addr1' ? 'min-w-[150px]' : f.key === 'dispatchNotes' || f.key === 'email' ? 'min-w-[180px]' : f.key === 'itemDesc' ? 'min-w-[140px]' : f.key === 'phone' ? 'min-w-[130px]' : f.key === 'city' ? 'min-w-[110px]' : f.key === 'stopNbr' || f.key === 'pro' ? 'min-w-[96px]' : f.key === 'state' ? 'w-12' : f.key === 'zip' ? 'w-20' : 'w-16'} ${!blank && !queued && missing.includes(f.key) ? 'border-amber-400 bg-amber-50' : ''}`} />
                        </td>
                      ))}
                      <td className="px-1 py-0.5 whitespace-nowrap">
                        {blank ? <span className="text-slate-300">—</span> : queued ? <span className="text-slate-500 inline-flex items-center gap-1"><Clock size={12} /> queued</span> : missing.length ? <span className="text-amber-600 inline-flex items-center gap-1"><AlertTriangle size={12} /> need {missing.length}</span> : <span className="text-green-600 inline-flex items-center gap-1"><FileCheck size={12} /> ready</span>}
                      </td>
                      <td className="py-0.5"><button onClick={() => removeRow(i)} title="Remove row" className="text-slate-400 hover:text-red-600"><X size={14} /></button></td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>

        {/* Live convergence status (load mode) */}
        {verifyMsg && (
          <div className="rounded-lg px-3 py-2 text-[13px] bg-blue-50 text-blue-800 border border-blue-200">⏳ {verifyMsg}</div>
        )}

        {/* Results */}
        {results?.loadMode && (
          <div className={`rounded-lg px-3 py-2 text-[13px] ${results.beta ? 'bg-slate-100 text-slate-700 border border-slate-200' : results.ok ? 'bg-green-50 text-green-800 border border-green-200' : 'bg-amber-50 text-amber-800 border border-amber-200'}`}>
            <div className="font-medium">{results.msg}</div>
            {results.detail && <div className="text-[12px] mt-0.5 opacity-80">{results.detail}</div>}
          </div>
        )}
        {results && !results.loadMode && (
          <div className={`rounded-lg px-3 py-2 text-[13px] ${results.beta ? 'bg-slate-100 text-slate-700 border border-slate-200' : results.failed ? 'bg-amber-50 text-amber-800 border border-amber-200' : 'bg-green-50 text-green-800 border border-green-200'}`}>
            {results.beta ? results.msg : (
              <div className="space-y-1">
                <div className="font-medium">{results.failed ? `⚠ ${results.created + results.updated} of ${results.created + results.updated + results.failed} created` : `✓ Created ${results.created}${results.updated ? ` (+${results.updated} updated existing)` : ''} order(s) — now UNPLANNED; plan them onto loads in Routing.`}</div>
                {results.failed > 0 && (
                  <ul className="list-disc ml-5 text-[12px]">
                    {results.rows.filter((o) => !o.ok).slice(0, 12).map((o, k) => <li key={k}><b>{o.name || `Row ${o.idx + 1}`}</b>: {o.error}</li>)}
                    {results.failed > 12 && <li>…and {results.failed - 12} more (still in the grid to retry).</li>}
                  </ul>
                )}
              </div>
            )}
          </div>
        )}

        {/* Create */}
        <div className="flex items-center justify-between gap-3 pb-6">
          <span className="text-[12px] text-slate-500">
            {!originComplete ? 'Set the pickup + service date first.'
              : readyCount === 0 && activeRows.length > 0 && pushRows.length === 0 ? `All ${activeRows.length} row(s) are queued — check ☑ at least one row to push it.`
              : readyCount === 0 ? `Fill at least one row (required * fields${asLoad ? ' — PRO / shipment # too in load mode' : ''}).`
              : asLoad && incompleteCount > 0 ? `Load mode sends the load's COMPLETE stop list — finish or remove the ${incompleteCount} incomplete row(s) first.`
              : asLoad && !loadNbr.trim() ? 'Enter the load number (an empty Draft load, or a new one).'
              : busy && progress ? `Creating ${progress.done}/${progress.total}…`
              : busy ? 'Working…'
              : asLoad ? (live ? `Ready — ONE import WILL create load "${loadNbr.trim()}" with ${readyCount} stop(s) in grid order.${queuedCount ? ` ${queuedCount} queued row(s) stay in the grid.` : ''}` : `Beta — previews the one-import load create (${readyCount} stops).`)
              : live ? `Ready — this WILL create ${readyCount} order(s) in NuVizz${incompleteCount ? ` (${incompleteCount} incomplete row(s) skipped)` : ''}${queuedCount ? ` · ${queuedCount} queued row(s) stay in the grid for a later push` : ''}.` : `Beta — Create previews only (${readyCount} ready${queuedCount ? ` · ${queuedCount} queued` : ''}).`}
          </span>
          <button onClick={asLoad ? createAsLoad : createAll} disabled={!canCreate} className={`inline-flex items-center gap-1.5 px-4 py-2 rounded font-semibold text-white text-sm shrink-0 ${canCreate ? '' : 'opacity-40 cursor-not-allowed'}`} style={{ background: live ? '#dc2626' : BRAND }}>
            <Plus size={16} /> {busy ? (asLoad ? 'Importing…' : 'Creating…')
              : asLoad ? (live ? `Create load + ${readyCount} stop(s) (LIVE · 1 import)` : `Preview load (Beta)`)
              : live ? `Create ${readyCount} order(s) (LIVE)` : `Preview ${readyCount} (Beta)`}
          </button>
        </div>
        </>)}

        {/* ── Pushed to NuVizz — the durable receipt of what Bulk Add sent, by day, from any
            device. Same cloud log the manifest flow writes; reads our own store only (0 NuVizz). ── */}
        {bulkView === 'pushed' && (() => {
          const recs = pushedLog.records || [];
          const isToday = pushedDate === etTodayStr();
          const fmtTime = (iso) => { try { return new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', hour: 'numeric', minute: '2-digit' }).format(new Date(iso)); } catch { return ''; } };
          return (
            <div className="bg-white border border-slate-200 rounded-lg p-3 space-y-3">
              <div className="flex items-center flex-wrap gap-2">
                <div className="text-[13px] font-semibold text-slate-700 inline-flex items-center gap-1.5"><FileCheck size={14} /> Pushed to NuVizz</div>
                <span className="text-slate-300">·</span>
                <input type="date" value={pushedDate} max={etTodayStr()} onChange={(e) => setPushedDate(e.target.value)} className="border border-slate-300 rounded px-2 py-1 text-[12px] bg-white focus:outline-none focus:ring-1 focus:ring-blue-300" />
                {!isToday && <button onClick={() => setPushedDate(etTodayStr())} className="text-[11px] text-blue-600 hover:underline">Today</button>}
                <button onClick={() => fetchPushedLog(pushedDate)} title="Refresh" className="text-slate-400 hover:text-slate-700"><RefreshCw size={13} className={pushedLog.loading ? 'animate-spin' : ''} /></button>
                <span className="text-[12px] text-slate-500">{pushedLog.loading ? 'loading…' : `${recs.length} pushed`}{isToday ? ' today' : ''}</span>
                {pushedLog.error && <span className="text-[11px] text-amber-700">History unavailable: {pushedLog.error}</span>}
                <span className="text-[11px] text-slate-400 w-full">Every order you push from Bulk Add is logged here — pick a day to see exactly what was sent. Reads our own log only (zero NuVizz calls).</span>
              </div>
              <div className="overflow-x-auto">
                <table className="text-[12px] border-collapse w-full">
                  <thead>
                    <tr className="text-left text-[11px] text-slate-500 border-b border-slate-200">
                      <th className="px-2 pb-1 font-medium">Consignee</th>
                      <th className="px-2 pb-1 font-medium">Order #</th>
                      <th className="px-2 pb-1 font-medium">NuVizz #</th>
                      <th className="px-2 pb-1 font-medium text-right">Plt</th>
                      <th className="px-2 pb-1 font-medium text-right">Loose</th>
                      <th className="px-2 pb-1 font-medium text-right">Wt</th>
                      <th className="px-2 pb-1 font-medium text-right">Price</th>
                      <th className="px-2 pb-1 font-medium whitespace-nowrap">Pushed</th>
                    </tr>
                  </thead>
                  <tbody>
                    {recs.length === 0 ? (
                      <tr><td colSpan={8} className="py-4 text-center text-slate-400">{pushedLog.loading ? 'Loading…' : `Nothing pushed on ${pushedDate}.`}</td></tr>
                    ) : recs.map((r, i) => (
                      <tr key={`${r.orderRef || r.nuvizzNbr || i}_${i}`} className="border-b border-slate-100 align-top">
                        <td className="px-2 py-1"><div className="font-medium text-slate-700">{r.name || '—'}</div>{(r.addr1 || r.addr2) && <div className="text-[11px] text-slate-500">{[r.addr1, r.addr2].filter(Boolean).join(', ')}</div>}{(r.city || r.state) && <div className="text-[11px] text-slate-400">{[r.city, r.state].filter(Boolean).join(', ')}</div>}</td>
                        <td className="px-2 py-1 text-slate-600 tabular-nums">{r.orderRef || '—'}</td>
                        <td className="px-2 py-1 tabular-nums">{r.nuvizzNbr || '—'}{r.updated && <span className="ml-1 text-[10px] px-1 py-0.5 rounded bg-amber-100 text-amber-700 align-middle">updated</span>}</td>
                        <td className="px-2 py-1 text-right tabular-nums">{r.pallets || ''}</td>
                        <td className="px-2 py-1 text-right tabular-nums">{r.loose || ''}</td>
                        <td className="px-2 py-1 text-right tabular-nums">{r.weight || ''}</td>
                        <td className="px-2 py-1 text-right tabular-nums">{r.price ? `$${r.price}` : ''}</td>
                        <td className="px-2 py-1 text-slate-500 whitespace-nowrap">{fmtTime(r.pushedAt)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          );
        })()}
      </div>
    </div>
  );
}


// ── "More" — the overflow tab menu ───────────────────────────────────────────
// The nav row is full, and screens like the manifest check are ones you visit
// deliberately rather than live in. Rather than shrink every tab to fit them,
// they live here. `badge` surfaces a problem from a screen you are NOT on — the
// whole point of the manifest check is that you should not have to remember to
// go and look.
function MoreMenu({ items, activeId, onPick, badge = 0 }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    if (!open) return undefined;
    const away = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    const esc = (e) => { if (e.key === 'Escape') setOpen(false); };
    document.addEventListener('mousedown', away);
    document.addEventListener('keydown', esc);
    return () => { document.removeEventListener('mousedown', away); document.removeEventListener('keydown', esc); };
  }, [open]);
  const active = items.some((i) => i.id === activeId);
  return (
    <div className="relative" ref={ref}>
      <button
        onClick={() => setOpen((v) => !v)}
        aria-haspopup="menu"
        aria-expanded={open}
        className={`relative px-3 py-1.5 rounded inline-flex items-center gap-1.5 font-medium ${active ? 'text-white' : 'text-slate-600 hover:bg-slate-100'}`}
        style={active ? { background: BRAND } : {}}
      >
        <MoreHorizontal size={14} />More
        <ChevronDown size={12} className={open ? 'rotate-180 transition-transform' : 'transition-transform'} />
        {badge > 0 && (
          <span className="ml-0.5 min-w-[16px] h-4 px-1 rounded-full bg-red-600 text-white text-[10px] font-bold inline-flex items-center justify-center">{badge > 99 ? '99+' : badge}</span>
        )}
      </button>
      {open && (
        <div role="menu" className="absolute right-0 mt-1 w-64 bg-white border rounded-lg shadow-lg py-1 z-50">
          {items.map((it) => (
            <button
              key={it.id}
              role="menuitem"
              onClick={() => { setOpen(false); onPick(it.id); }}
              className={`w-full text-left px-3 py-2 text-sm flex items-center gap-2 ${activeId === it.id ? 'bg-blue-50 text-blue-800 font-semibold' : 'text-slate-700 hover:bg-slate-50'}`}
            >
              {it.icon}
              <span className="flex-1 min-w-0">
                <span className="block truncate">{it.label}</span>
                {it.hint && <span className="block text-[10px] text-slate-400 truncate">{it.hint}</span>}
              </span>
              {it.badge > 0 && (
                <span className="min-w-[16px] h-4 px-1 rounded-full bg-red-600 text-white text-[10px] font-bold inline-flex items-center justify-center">{it.badge > 99 ? '99+' : it.badge}</span>
              )}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

// ── Manifest check ───────────────────────────────────────────────────────────
// Drop the nightly Uline freight report; every PRO on it is checked against what
// the scan actually put in Firestore. ZERO NuVizz calls — the report is a
// text-layer PDF so reading it needs no AI either, and the board side is a
// Firestore read. The endpoint CAN go on to ask NuVizz about each unmatched
// order, but that is not wired to any button here: nothing on this screen spends
// a NuVizz call, so it can never surprise you with one.
function ManifestCheckScreen() {
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState(null);
  const [result, setResult] = useState(() => loadStored());
  const [fileName, setFileName] = useState(() => loadStored()?.fileName || null);
  const [drag, setDrag] = useState(false);

  const run = async (file) => {
    if (!file || busy) return;
    setBusy(true); setErr(null);
    try {
      const buf = await file.arrayBuffer();
      let bin = '';
      const bytes = new Uint8Array(buf);
      for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
      const pdfBase64 = btoa(bin);
      const r = await fetch('/.netlify/functions/manifest-check', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ pdfBase64 }),
      });
      const d = await r.json();
      if (!d?.ok) { setErr(d?.error || `check failed (HTTP ${r.status})`); setResult(null); }
      else {
        setResult(d); setFileName(file.name);
        saveStored(toStored(d, file.name));
        window.dispatchEvent(new Event('dd-manifest-check-updated'));
      }
    } catch (e) { setErr(String(e?.message || e)); }
    setBusy(false);
  };

  const clear = () => { setResult(null); setFileName(null); setErr(null); saveStored(null); window.dispatchEvent(new Event('dd-manifest-check-updated')); };
  const { issues, level } = manifestIssues(result);
  const suspects = result?.suspects || [];
  const m = result?.manifest;

  return (
    <div className="flex-1 overflow-auto bg-slate-50">
      <div className="max-w-5xl mx-auto p-4 space-y-3">
        <div>
          <h1 className="text-lg font-bold text-slate-800">Manifest check</h1>
          <p className="text-xs text-slate-500 mt-0.5">
            Drop the nightly Uline freight report. Every order on it is checked against what the scan
            put in Firestore — so an order the shipper handed us that never reached NuVizz shows up here.
            <span className="font-semibold text-slate-600"> Zero NuVizz calls.</span>
          </p>
        </div>

        <label
          onDragOver={(e) => { e.preventDefault(); setDrag(true); }}
          onDragLeave={() => setDrag(false)}
          onDrop={(e) => { e.preventDefault(); setDrag(false); run(e.dataTransfer?.files?.[0]); }}
          className={`block border-2 border-dashed rounded-lg p-6 text-center cursor-pointer ${drag ? 'border-blue-400 bg-blue-50' : 'border-slate-300 bg-white hover:bg-slate-50'}`}
        >
          <input type="file" accept=".pdf" className="hidden" onChange={(e) => run(e.target.files?.[0])} disabled={busy} />
          <FileCheck size={20} className="mx-auto text-slate-400" />
          <div className="text-sm font-semibold text-slate-700 mt-1">
            {busy ? 'Checking…' : 'Drop the Uline freight report PDF, or click to choose'}
          </div>
          {fileName && !busy && <div className="text-[11px] text-slate-400 mt-0.5">{fileName}</div>}
        </label>

        {err && <div className="text-xs text-red-700 bg-red-50 border border-red-200 rounded p-2">{err}</div>}

        {result && (
          <>
            <div className={`rounded-lg border p-3 ${level === 'alert' ? 'border-red-300 bg-red-50' : level === 'warn' ? 'border-amber-300 bg-amber-50' : 'border-emerald-300 bg-emerald-50'}`}>
              <div className={`text-sm font-bold ${level === 'alert' ? 'text-red-800' : level === 'warn' ? 'text-amber-800' : 'text-emerald-800'}`}>
                {manifestHeadline(result)}
              </div>
              {issues.length > 0 && (
                <ul className="mt-1 space-y-0.5">
                  {issues.map((i) => (
                    <li key={i.kind} className={`text-xs ${i.level === 'alert' ? 'text-red-700' : 'text-amber-700'}`}>• {i.text}</li>
                  ))}
                </ul>
              )}
              <div className="text-[11px] text-slate-500 mt-1.5">
                Checked against {(result.checkedAgainst || []).map((d) => `${d.date} (${d.stops})`).join(' · ') || '—'}
                {' · '}{result.boardOnly} scanned order(s) not on this manifest (other shippers — normal)
              </div>
            </div>

            {m && (
              <div className="grid grid-cols-2 sm:grid-cols-5 gap-2">
                {[['Orders', m.orders], ['Pounds', m.totals?.lbs], ['Skids', m.totals?.skids], ['Loose', m.totals?.pieces], ['In the scan', result.onBoard]].map(([k, v]) => (
                  <div key={k} className="bg-white border rounded p-2">
                    <div className="text-[10px] uppercase font-semibold text-slate-400">{k}</div>
                    <div className="text-base font-bold text-slate-800 tabular-nums">{v == null ? '—' : Number(v).toLocaleString()}</div>
                  </div>
                ))}
              </div>
            )}
            {m && (
              <div className="text-[11px] text-slate-500">
                {m.verified
                  ? <span className="text-emerald-700 font-semibold">✓ These totals match the ones printed on the manifest.</span>
                  : <span className="text-amber-700 font-semibold">⚠ These numbers could NOT be reconciled against the manifest’s printed totals — treat them as unconfirmed.</span>}
                {(m.warnings || []).map((w, i) => <div key={i} className="text-amber-700">• {w}</div>)}
              </div>
            )}

            {suspects.length > 0 && (
              <div className="bg-white border rounded-lg overflow-hidden">
                <div className="px-3 py-2 border-b bg-red-50 text-xs font-bold text-red-800">
                  On the manifest, not in the scan ({result.suspectsTotal ?? suspects.length})
                </div>
                <div className="overflow-x-auto">
                  <table className="min-w-full text-xs">
                    <thead className="bg-slate-50 text-slate-500">
                      <tr>
                        {['PRO', 'Customer', 'City', 'ZIP', 'Lbs', 'Skids', 'Loose', 'Shipped'].map((h) => (
                          <th key={h} className="px-2 py-1 text-left font-semibold whitespace-nowrap">{h}</th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {suspects.map((r) => (
                        <tr key={r.pro} className="border-t">
                          <td className="px-2 py-1 font-mono font-semibold text-slate-800 whitespace-nowrap">{r.pro}</td>
                          <td className="px-2 py-1 text-slate-700">{r.custName || '—'}</td>
                          <td className="px-2 py-1 text-slate-600">{r.city || '—'}</td>
                          <td className="px-2 py-1 text-slate-600">{r.zip || '—'}</td>
                          <td className="px-2 py-1 tabular-nums">{r.lbs ?? '—'}</td>
                          <td className="px-2 py-1 tabular-nums">{r.skids ?? '—'}</td>
                          <td className="px-2 py-1 tabular-nums">{r.pieces ?? '—'}</td>
                          <td className="px-2 py-1 text-slate-500 whitespace-nowrap">{r.shipDate || '—'}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                <div className="px-3 py-2 border-t text-[11px] text-slate-500">
                  These are on Uline’s manifest but not in the scan for the day(s) above. That is not by itself proof
                  the order is missing from NuVizz — it could be dated to another day. Search the PRO to check.
                </div>
              </div>
            )}

            <div className="flex items-center gap-2">
              <button onClick={clear} className="px-2 py-1 text-xs font-semibold text-slate-600 border rounded hover:bg-slate-50">Clear</button>
              {result.at && <span className="text-[11px] text-slate-400">checked {String(result.at).slice(0, 16).replace('T', ' ')}</span>}
            </div>
          </>
        )}
      </div>
    </div>
  );
}

function TabBtn({ label, icon, active, onClick, badge = 0 }) {
  return (
    <button
      onClick={onClick}
      className={`relative px-3 py-1.5 rounded inline-flex items-center gap-1.5 font-medium ${active ? 'text-white' : 'text-slate-600 hover:bg-slate-100'}`}
      style={active ? { background: BRAND } : {}}
    >
      {icon}{label}
      {badge > 0 && (
        <span className="ml-0.5 min-w-[16px] h-4 px-1 rounded-full bg-red-600 text-white text-[10px] font-bold inline-flex items-center justify-center">{badge > 99 ? '99+' : badge}</span>
      )}
    </button>
  );
}

export default function App() {
  return <Shell />;
}
